/**
 * Pure hashing/provenance helpers (no OPFS access) so they are testable
 * under Node. The OPFS store lives in opfs.ts and uses these helpers.
 */
export async function hashBuffer(buffer: ArrayBuffer): Promise<string> {
  const digest = await crypto.subtle.digest("SHA-256", buffer);
  return Array.from(new Uint8Array(digest), (b) => b.toString(16).padStart(2, "0")).join("");
}

export async function hashBlob(data: ArrayBuffer | Blob): Promise<string> {
  const buffer = data instanceof Blob ? await data.arrayBuffer() : data;
  return hashBuffer(buffer);
}

export function makeProvenance(
  origin: string,
  contentHash?: string,
): { origin: string; contentHash?: string; recordedAt: number; recordedBy: string } {
  return {
    origin,
    contentHash,
    recordedAt: Date.now(),
    recordedBy: "local-user",
  };
}
