/**
 * Build identity + development diagnostics (TPI-V2-WEB-009C §20).
 *
 * Purpose: make it impossible to confuse "the code is wrong" with "the browser
 * is running an old build". Nonintrusive — the production dashboard shows only
 * the same small version line it always did; full diagnostics live in the
 * dashboard Menu and the browser console, and only in development.
 */

declare const __TPI_BUILD_INFO__: { version: string; commit: string } | undefined;

/** Compile-time identity injected by the Vite plugin (falls back honestly). */
export const BUILD_INFO: { version: string; commit: string } =
  typeof __TPI_BUILD_INFO__ !== "undefined" ? __TPI_BUILD_INFO__ : { version: "0.0.0", commit: "unknown" };

export interface DevDiagnostics {
  app: string;
  version: string;
  commit: string;
  mode: "development" | "production";
  /** Service-worker cache name currently controlling the page. */
  serviceWorkerCache: string;
  serviceWorkerState: string;
  /** True when the worker's own version differs from the app build. */
  staleServiceWorker: boolean;
  serverReportedCommit: string | null;
  /** True when the dev server is serving a different commit than this bundle. */
  serverMismatch: boolean;
  serverStartedAt: string | null;
  origin: string;
  userAgent: string;
  /** Stored investigation data counts — presence only, never content. */
  dataPresent: { databases: string[]; opfsSupported: boolean };
}

async function swInfo(): Promise<{ cache: string; state: string }> {
  if (!("serviceWorker" in navigator)) return { cache: "unavailable", state: "unsupported" };
  // Cache Storage is authoritative and instant — read it first.
  let shellCaches: string[] = [];
  try {
    shellCaches = (await caches.keys()).filter((n) => n.startsWith("tpi-shell-")).sort();
  } catch {
    shellCaches = [];
  }
  const registration = await navigator.serviceWorker.getRegistration();
  const state = registration?.active?.state ?? (registration ? "installing" : "notRegistered");
  if (shellCaches.length > 0) return { cache: shellCaches[shellCaches.length - 1]!, state };
  if (!registration) return { cache: "none", state: "notRegistered" };
  // No shell cache yet: ask the worker directly, briefly.
  const worker = navigator.serviceWorker.controller ?? registration.active;
  const fromMessage = await new Promise<string>((resolve) => {
    if (!worker) return resolve("unknown");
    const channel = new MessageChannel();
    const timer = setTimeout(() => resolve("unknown"), 800);
    channel.port1.onmessage = (event) => {
      clearTimeout(timer);
      resolve((event.data as { cache?: string })?.cache ?? "unknown");
    };
    try {
      worker.postMessage({ type: "TPI_SW_VERSION" }, [channel.port2]);
    } catch {
      clearTimeout(timer);
      resolve("unknown");
    }
  });
  return { cache: fromMessage, state };
}

async function dataPresence(): Promise<{ databases: string[]; opfsSupported: boolean }> {
  let databases: string[] = [];
  try {
    const list = await indexedDB.databases?.();
    databases = (list ?? []).map((d) => d.name ?? "").filter(Boolean);
  } catch {
    databases = [];
  }
  return { databases, opfsSupported: typeof navigator.storage?.getDirectory === "function" };
}

/** Collect diagnostics. Never throws; unknown values are reported as unknown. */
export async function collectDiagnostics(): Promise<DevDiagnostics> {
  const isDev = import.meta.env?.DEV === true;
  const sw = await swInfo();
  let serverCommit: string | null = null;
  let serverStartedAt: string | null = null;
  if (isDev) {
    try {
      const res = await fetch("/__tpi_dev_info", { cache: "no-store" });
      if (res.ok) {
        const info = (await res.json()) as { commit?: string; serverStartedAt?: string };
        serverCommit = info.commit ?? null;
        serverStartedAt = info.serverStartedAt ?? null;
      }
    } catch {
      serverCommit = null;
    }
  }
  return {
    app: "TPI Research & Investigation Studio",
    version: BUILD_INFO.version,
    commit: BUILD_INFO.commit,
    mode: isDev ? "development" : "production",
    serviceWorkerCache: sw.cache,
    serviceWorkerState: sw.state,
    // "v1" shells are the pre-009C worker that could serve stale modules.
    staleServiceWorker: sw.cache === "tpi-shell-v1",
    serverReportedCommit: serverCommit,
    serverMismatch: Boolean(serverCommit && BUILD_INFO.commit !== "unknown" && serverCommit !== BUILD_INFO.commit),
    serverStartedAt,
    origin: location.origin,
    userAgent: navigator.userAgent,
    dataPresent: await dataPresence(),
  };
}

/** Log the identity once at boot so any console shows which build is running. */
export function logBuildIdentity(): void {
  const line = `TPI build ${BUILD_INFO.version} · commit ${BUILD_INFO.commit} · ${import.meta.env?.DEV ? "development" : "production"}`;
  console.info(line);
}
