/**
 * History-based router. Routes mirror the iOS dashboard navigation graph
 * (HomeDashboardView) — the five canonical destinations first (WP-0) —
 * plus the case-scoped Case Hub route (TPI-V2-WEB-014B).
 *
 * Case Hub route format: `#/casehub?case=<caseId>`
 * The selected case lives in the URL, not in module state, so refresh,
 * Back/Forward and shareable links all resolve to the same case.
 */
export type RouteName =
  | "dashboard"
  | "command-center"
  | "casehub"
  | "equipment"
  | "forensic"
  | "weather"
  | "mystic";

export type RouteHandler = (container: HTMLElement) => void | Promise<void>;

const ROUTES: readonly RouteName[] = [
  "dashboard",
  "command-center",
  "casehub",
  "equipment",
  "forensic",
  "weather",
  "mystic",
];

/** Raw query string of the current hash route ("" when absent). */
export function routeQuery(): URLSearchParams {
  const raw = location.hash.replace(/^#\/?/, "");
  const index = raw.indexOf("?");
  return new URLSearchParams(index === -1 ? "" : raw.slice(index + 1));
}

export function routeFromPath(): RouteName {
  const name = location.hash.replace(/^#\/?/, "").split("?")[0] as RouteName;
  return ROUTES.includes(name) ? name : "dashboard";
}

/**
 * Navigate to a route, optionally carrying query parameters.
 * Values are omitted when undefined so URLs stay clean and stable.
 */
export function navigate(route: RouteName, params?: Record<string, string | undefined>): void {
  const query = new URLSearchParams();
  for (const [key, value] of Object.entries(params ?? {})) {
    if (value !== undefined && value !== "") query.set(key, value);
  }
  const suffix = query.toString();
  location.hash = suffix ? `/${route}?${suffix}` : `/${route}`;
}

/** Case id from the current route, or null when the route carries none. */
export function caseIdFromRoute(): string | null {
  const value = routeQuery().get("case");
  return value && value.trim() ? value.trim() : null;
}

export function onRouteChange(handler: (route: RouteName) => void): void {
  const run = () => handler(routeFromPath());
  window.addEventListener("hashchange", run);
  run();
}

export function isRoute(value: string): value is RouteName {
  return (ROUTES as readonly string[]).includes(value);
}
