/**
 * Environmental Baseline view (TPI-V2-WEB-008 §7/§12/§13/§16).
 *
 * Room-by-room baseline windows, the iOS global lock and drift checks, and the
 * environmental history interface. Readiness comes from the authoritative
 * BaselineService / workflow engine — never from UI-computed truth.
 */
import "./casehub.css";
import { getDb } from "../../core/db";
import { CaseRepository } from "../../core/repositories/caseRepository";
import { PropertyService } from "../../core/property/propertyService";
import { WalkthroughService } from "../../core/property/walkthroughService";
import { SessionService } from "../../core/session/sessionService";
import { BaselineService, isBaselineComplete } from "../../core/environment/baselineService";
import { MEASUREMENT_TYPE_LABELS, MeasurementService } from "../../core/environment/measurementService";
import type { AcquisitionMethod, MeasurementType } from "../../core/types";
import { esc, viewShell, wireBackButton } from "../dashboard/shell";
import { mountView, onDelegate, invalidateView, clearDrafts } from "../../shared/uidom";
import { renderCaseHub } from "./CaseHub";

const db = () => getDb();
const sessions = () => new SessionService(db());
const property = () => new PropertyService(db());
const baseline = () =>
  new BaselineService(db(), property(), new WalkthroughService(db(), property()), sessions());
const measurements = () => new MeasurementService(db(), sessions());

interface BaselineFilter {
  roomId: string;
  sessionId: string;
  measurementType: string;
  acquisition: string;
}

const filters = new WeakMap<HTMLElement, BaselineFilter>();

function ft(container: HTMLElement): BaselineFilter {
  let f = filters.get(container);
  if (!f) {
    f = { roomId: "", sessionId: "", measurementType: "", acquisition: "" };
    filters.set(container, f);
  }
  return f;
}

function fmtTime(ms: number | null): string {
  return ms ? new Date(ms).toLocaleString() : "—";
}

export async function renderBaselineView(container: HTMLElement, caseId: string): Promise<void> {
  const record = await new CaseRepository(db()).getCase(caseId);
  if (!record) {
    invalidateView(container);
    mountView(container, viewShell("Environmental Baseline", `<div class="cc-empty">Case not found.</div>`));
    wireBackButton(container);
    return;
  }
  const svc = baseline();
  const gate = await svc.canStartBaseline(caseId);
  const progress = await svc.progress(caseId);
  const blockers = await svc.evaluateCaseBaseline(caseId);
  const records = await svc.listForCase(caseId);
  const structure = await property().getStructureForCase(caseId);
  const rooms = structure
    ? (await db().structureRooms.where("structureId").equals(structure.id).toArray()).filter((r) => !r.archived)
    : [];
  const sessionList = await sessions().listSessions(caseId);
  const f = ft(container);
  const history = await measurements().query(caseId, {
    roomId: f.roomId || undefined,
    sessionId: f.sessionId || undefined,
    measurementType: (f.measurementType || undefined) as MeasurementType | undefined,
    acquisition: (f.acquisition || undefined) as AcquisitionMethod | undefined,
  });
  const byRoom = new Map(records.map((r) => [r.roomId, r]));

  invalidateView(container);
  mountView(
    container,
    viewShell(
      `Environmental Baseline — ${record.caseNumber}`,
      `
      <div class="case-form" data-root="baseline-view" data-case-id="${esc(caseId)}" data-epoch="${Date.now()}-${Math.random()}">
        ${
          gate.allowed
            ? `<p class="cc-count">Baseline coverage: <strong>${progress.completeRooms} of ${progress.flaggedRooms}</strong> rooms complete •
               drift checks: ${progress.driftCheckedRooms}/${progress.flaggedRooms} •
               global lock: ${progress.globalLockRecorded ? "recorded" : "not recorded"}${progress.unresolvedDrift ? " • <strong>unresolved drift</strong>" : ""}</p>`
            : `<p class="cc-count" role="alert">${esc(gate.reason)}</p>`
        }
        <p class="cc-meta">A baseline is a documented reference condition for later comparison. It is not evidence that a location is — or is not — paranormal, and measurements are never invented to satisfy a requirement.</p>

        <h3 class="cc-section-title">Blockers</h3>
        ${blockers.length === 0
          ? '<div class="cc-empty">No baseline blockers.</div>'
          : blockers
              .map(
                (b) => `
          <div class="case-row" role="alert">
            <div>
              <div class="case-title">${esc(b.reason)}</div>
              <div class="case-meta">required action: ${esc(b.requiredAction)} • ${b.nonOverridable ? "<strong>not overridable</strong>" : "override permitted with documented exception"}</div>
            </div>
            <span class="status-badge error">error</span>
          </div>`,
              )
              .join("")}

        <h3 class="cc-section-title">Room Baselines</h3>
        ${rooms.length === 0
          ? '<div class="cc-empty">No rooms defined. Add rooms in the Property Structure module.</div>'
          : rooms
              .map((room) => {
                const rec = byRoom.get(room.id);
                const complete = rec ? isBaselineComplete(rec) : false;
                return `
            <div class="baseline-room-block" data-baseline-room="${room.id}" data-room-id="${room.id}">
              <div class="case-row">
                <div>
                  <div class="case-title">${esc(room.name)} ${complete ? "✓" : ""}</div>
                  ${
                    rec
                      ? `<div class="case-meta">
                          window ${fmtTime(rec.baselineStart)} → ${fmtTime(rec.baselineEnd)} •
                          summary ${rec.baselineSummary ? "recorded" : "<strong>missing</strong>"} •
                          complete ${rec.baselineMarkedComplete ? "yes" : "<strong>no</strong>"} •
                          drift ${rec.driftChecked ? (rec.driftDetected ? "<strong>unstable</strong>" : "stable") : "<strong>not checked</strong>"}
                          ${rec.roomNameAtRecord !== room.name ? ` • recorded as "${esc(rec.roomNameAtRecord)}"` : ""}
                        </div>`
                      : '<div class="case-meta">No baseline record yet.</div>'
                  }
                </div>
                <span class="status-badge ${complete ? "implemented" : ""}">${complete ? "complete" : "incomplete"}</span>
              </div>
              ${
                !rec
                  ? `<div class="form-actions"><button class="button-primary" data-bl-start data-room-id="${room.id}" type="button" ${gate.allowed ? "" : "disabled"}>Start Baseline Window</button></div>`
                  : `<div class="case-form" data-baseline-editor="${rec.id}" data-room-id="${room.id}">
                       <div class="detail-grid">
                         <div class="detail-field"><label for="bl-summary-${rec.id}">Baseline summary (required for completion)</label>
                           <textarea id="bl-summary-${rec.id}" data-bl-summary rows="2">${esc(rec.baselineSummary)}</textarea></div>
                         <div class="detail-field"><label for="bl-notes-${rec.id}">Additional notes</label>
                           <textarea id="bl-notes-${rec.id}" data-bl-notes rows="2">${esc(rec.notes)}</textarea></div>
                       </div>
                       <div class="form-actions">
                         ${rec.baselineStart === null ? `<button class="button-primary" data-bl-start="${rec.id}" type="button" ${gate.allowed ? "" : "disabled"}>Start Baseline Window</button>` : ""}
                         ${rec.baselineStart !== null && rec.baselineEnd === null ? `<button class="button-primary" data-bl-end="${rec.id}" type="button">End Window &amp; Save Summary</button>` : ""}
                         ${rec.baselineEnd !== null && !rec.baselineMarkedComplete ? `<button class="button-primary" data-bl-complete="${rec.id}" type="button">Confirm Baseline Complete</button>` : ""}
                       </div>
                       <fieldset class="baseline-fieldset" data-bl-global-form="${rec.id}">
                         <legend>Global baseline lock (property-wide)</legend>
                         <div class="case-meta">iOS global lock: phones logged/away ${rec.globalPhonesLogged ? "✓" : "—"} • HVAC state logged ${rec.globalHvacLogged ? "✓" : "—"} • stable equipment placement ${rec.globalStablePlacement ? "✓" : "—"}</div>
                         <label><input type="checkbox" data-bl-flag="phones" ${rec.globalPhonesLogged ? "checked" : ""}> Mobile phones are off/away from the baseline area</label>
                         <label><input type="checkbox" data-bl-flag="hvac" ${rec.globalHvacLogged ? "checked" : ""}> HVAC state has been logged</label>
                         <label><input type="checkbox" data-bl-flag="placement" ${rec.globalStablePlacement ? "checked" : ""}> Equipment placement is stable</label>
                         <div class="form-actions"><button class="button-secondary" data-bl-global="${rec.id}" type="button">Record Global Lock</button></div>
                       </fieldset>
                       <fieldset class="baseline-fieldset" data-bl-drift-form="${rec.id}">
                         <legend>Drift verification</legend>
                         <div class="case-meta">Current: ${rec.driftChecked ? (rec.driftDetected ? "<strong>unstable drift recorded</strong>" : "stable") : "not yet checked"}</div>
                         <label for="bl-drift-state-${rec.id}">Drift result</label>
                         <select id="bl-drift-state-${rec.id}" data-bl-drift-state>
                           <option value="stable"${!rec.driftDetected ? " selected" : ""}>Stable — conditions consistent</option>
                           <option value="unstable"${rec.driftDetected ? " selected" : ""}>Unstable — drift detected</option>
                         </select>
                         <label for="bl-drift-notes-${rec.id}">Drift notes (required when unstable)</label>
                         <input id="bl-drift-notes-${rec.id}" data-bl-drift-notes type="text" placeholder="e.g. adjacent HVAC cycled repeatedly">
                         <div class="form-actions"><button class="button-secondary" data-bl-drift="${rec.id}" type="button">Record Drift Check</button></div>
                       </fieldset>
                     </div>`
              }
            </div>`;
              })
              .join("")}

        <h3 class="cc-section-title">Environmental History (${history.length})</h3>
        <div class="case-form">
          <div class="detail-grid">
            <div class="detail-field"><label for="h-room">Filter by room</label>
              <select id="h-room">
                <option value="">All rooms</option>
                ${rooms.map((r) => `<option value="${r.id}"${f.roomId === r.id ? " selected" : ""}>${esc(r.name)}</option>`).join("")}
              </select></div>
            <div class="detail-field"><label for="h-session">Filter by session</label>
              <select id="h-session">
                <option value="">All sessions</option>
                ${sessionList.map((s) => `<option value="${s.id}"${f.sessionId === s.id ? " selected" : ""}>${esc(s.status)} — ${fmtTime(s.startedAt)}</option>`).join("")}
              </select></div>
            <div class="detail-field"><label for="h-type">Filter by type</label>
              <select id="h-type">
                <option value="">All types</option>
                ${(Object.keys(MEASUREMENT_TYPE_LABELS) as MeasurementType[]).map((t) => `<option value="${t}"${f.measurementType === t ? " selected" : ""}>${esc(MEASUREMENT_TYPE_LABELS[t])}</option>`).join("")}
              </select></div>
            <div class="detail-field"><label for="h-acq">Filter by acquisition</label>
              <select id="h-acq">
                <option value="">All methods</option>
                ${(["automatic", "manualInstrument", "observation", "imported"] as const).map((a) => `<option value="${a}"${f.acquisition === a ? " selected" : ""}>${a}</option>`).join("")}
              </select></div>
          </div>
          <div class="form-actions"><button class="button-secondary" id="apply-history-filter" type="button">Apply Filters</button></div>
        </div>
        ${history.length === 0
          ? '<div class="cc-empty">No measurements recorded.</div>'
          : `<div class="table-wrap"><table class="data-table">
              <thead><tr><th>Time</th><th>Type</th><th>Value</th><th>Acquisition</th><th>Instrument</th><th>Room</th><th>Calibration</th></tr></thead>
              <tbody>
                ${history
                  .slice()
                  .reverse()
                  .map(
                    (m) => `<tr>
                      <td>${fmtTime(m.at)}</td>
                      <td>${esc(MEASUREMENT_TYPE_LABELS[m.measurementType])}</td>
                      <td>${m.value === null ? esc(m.text || "—") : `${m.value} ${esc(m.unit)}`}</td>
                      <td><strong>${esc(m.acquisition)}</strong></td>
                      <td>${esc(m.instrument || "—")}</td>
                      <td>${esc(rooms.find((r) => r.id === m.roomId)?.name ?? "—")}</td>
                      <td>${esc(m.calibration)}</td>
                    </tr>`,
                  )
                  .join("")}
              </tbody>
            </table></div>`}
        <p class="cc-meta">Readings shown in chronological order. Proximity in time is not correlation — this view makes no causal or statistical claim.</p>

        <div class="form-actions">
          <button class="back-button" id="baseline-back" type="button">← Back to Case Hub</button>
        </div>
      </div>
    `,
  ));

  wireHandlers(container, caseId);
  wireBackButton(container);
}

function wireHandlers(container: HTMLElement, caseId: string): void {
  const reload = () => renderBaselineView(container, caseId);

  onDelegate(container, "click", "#baseline-back", () => {
    void renderCaseHub(container, caseId);
  });

  onDelegate(container, "click", "[data-bl-start]", async (el) => {
    // Start is also offered for rooms without a record yet — the button then
    // carries the room id directly.
    const roomId = el.dataset.roomId ?? roomIdFromEditor(container, el.dataset.blStart ?? "");
    if (!roomId) {
      alert("Select a room before starting a baseline window.");
      return;
    }
    try {
      const session = await sessions().activeSession(caseId);
      await baseline().startBaseline(caseId, roomId, session?.id ?? null);
      await reload();
    } catch (err) {
      alert((err as Error).message);
    }
  });

  onDelegate(container, "click", "[data-bl-end]", async (el) => {
    clearDrafts(container); // summary committed to the record
    const id = el.dataset.blEnd ?? "";
    const editor = container.querySelector<HTMLElement>(`[data-baseline-editor="${id}"]`);
    const summary = editor?.querySelector<HTMLTextAreaElement>("[data-bl-summary]")?.value ?? "";
    const notes = editor?.querySelector<HTMLTextAreaElement>("[data-bl-notes]")?.value ?? "";
    try {
      await baseline().endBaseline(id, { summary, notes });
      await reload();
    } catch (err) {
      alert((err as Error).message);
    }
  });

  onDelegate(container, "click", "[data-bl-complete]", async (el) => {
    clearDrafts(container);
    const id = el.dataset.blComplete ?? "";
    const editor = container.querySelector<HTMLElement>(`[data-baseline-editor="${id}"]`);
    const summary = editor?.querySelector<HTMLTextAreaElement>("[data-bl-summary]")?.value ?? "";
    const notes = editor?.querySelector<HTMLTextAreaElement>("[data-bl-notes]")?.value ?? "";
    try {
      await baseline().endBaseline(id, { summary, notes, markComplete: true });
      await reload();
    } catch (err) {
      alert((err as Error).message);
    }
  });

  onDelegate(container, "click", "[data-bl-global]", async (el) => {
    const id = el.dataset.blGlobal ?? "";
    const form = container.querySelector<HTMLElement>(`[data-bl-global-form="${id}"]`);
    const flag = (name: string) => form?.querySelector<HTMLInputElement>(`[data-bl-flag="${name}"]`)?.checked ?? false;
    await baseline().recordGlobalLock(id, {
      phonesLogged: flag("phones"),
      hvacLogged: flag("hvac"),
      stablePlacement: flag("placement"),
    });
    await reload();
  });

  onDelegate(container, "click", "[data-bl-drift]", async (el) => {
    const id = el.dataset.blDrift ?? "";
    const form = container.querySelector<HTMLElement>(`[data-bl-drift-form="${id}"]`);
    const unstable = (form?.querySelector<HTMLSelectElement>("[data-bl-drift-state]")?.value ?? "stable") === "unstable";
    const notes = form?.querySelector<HTMLInputElement>("[data-bl-drift-notes]")?.value ?? "";
    if (unstable && !notes.trim()) {
      alert("Recording unstable drift requires notes explaining what was observed.");
      return;
    }
    try {
      await baseline().recordDriftCheck(id, { checked: true, detected: unstable, notes, sessionId: null });
      await reload();
    } catch (err) {
      alert((err as Error).message);
    }
  });

  onDelegate(container, "click", "#apply-history-filter", async () => {
    const f = ft(container);
    f.roomId = container.querySelector<HTMLSelectElement>("#h-room")?.value ?? "";
    f.sessionId = container.querySelector<HTMLSelectElement>("#h-session")?.value ?? "";
    f.measurementType = container.querySelector<HTMLSelectElement>("#h-type")?.value ?? "";
    f.acquisition = container.querySelector<HTMLSelectElement>("#h-acq")?.value ?? "";
    await reload();
  });
}

/** Resolve the room that owns a baseline editor via its stable room id. */
function roomIdFromEditor(container: HTMLElement, baselineId: string): string {
  const editor = container.querySelector<HTMLElement>(`[data-baseline-editor="${baselineId}"]`);
  return editor?.dataset.roomId ?? "";
}
