/**
 * Room layout element service (TPI-V2-WEB-010G §6/§8, Phase 010G-A).
 *
 * Port of the element operations found in
 * `Cases/CaseWalkthroughRoomWorkspaceView.swift`:
 *   place at 0.5/0.5 · drag-move (clamped 0…1) · size change (supported sizes
 *   only) · conditional property change (Outlet anchor, Vent style, Light style)
 *   · rotate (+90° mod 360) · delete.
 *
 * Persistence uses the existing reserved `roomLayoutElements` table. No schema
 * migration was required: the additional original fields are optional and
 * default on read (see docs/ROOM_LAYOUT_ELEMENTS.md).
 *
 * Every mutation writes an audit event. Room geometry is never touched here —
 * elements are positioned *inside* a room's footprint.
 */
import type { TPIDatabase } from "../db";
import { SCHEMA_VERSION } from "../db";
import { v4 as uuidv4 } from "../../shared/uuid";
import type { RoomLayoutElementRecord } from "../types";
import { ValidationError } from "../validation";
import { AuditService } from "../audit";
import {
  LAYOUT_ELEMENT_KINDS,
  elementFootprint,
  rotatedFootprint,
  type AnchorRelation,
  type LayoutElementKind,
  type LayoutElementSize,
  type LightStyle,
  type VentStyle,
} from "./layoutCatalog";

export interface LayoutElement extends RoomLayoutElementRecord {
  kind: LayoutElementKind;
  size: LayoutElementSize;
  anchorRelation: AnchorRelation;
  ventStyle: VentStyle;
  lightStyle: LightStyle;
  archived: boolean;
  revision: number;
}

function normalise(record: RoomLayoutElementRecord): LayoutElement {
  const kind = (record.kind in LAYOUT_ELEMENT_KINDS ? record.kind : "table") as LayoutElementKind;
  const spec = LAYOUT_ELEMENT_KINDS[kind];
  const size = spec.supportedSizes.includes(record.size as LayoutElementSize)
    ? (record.size as LayoutElementSize)
    : spec.defaultSize;
  const round = (v: number) => Math.round(v * 1000) / 1000;
  return {
    ...record,
    kind,
    size,
    posX: round(Math.max(0, Math.min(1, record.posX))),
    posY: round(Math.max(0, Math.min(1, record.posY))),
    anchorRelation: record.anchorRelation ?? "none",
    ventStyle: record.ventStyle ?? "wall",
    lightStyle: record.lightStyle ?? "ceiling",
    archived: record.archived ?? false,
    revision: record.revision ?? 1,
  };
}

export class LayoutElementService {
  private readonly audit: AuditService;

  constructor(private readonly db: TPIDatabase) {
    this.audit = new AuditService(db);
  }

  async listForRoom(roomId: string, includeArchived = false): Promise<LayoutElement[]> {
    const rows = await this.db.roomLayoutElements.where("roomId").equals(roomId).toArray();
    return rows
      .map(normalise)
      .filter((e) => includeArchived || !e.archived)
      .sort((a, b) => a.createdAt - b.createdAt || a.id.localeCompare(b.id));
  }

  async listForCase(caseId: string): Promise<LayoutElement[]> {
    const rows = await this.db.roomLayoutElements.where("caseId").equals(caseId).toArray();
    return rows.map(normalise).sort((a, b) => a.createdAt - b.createdAt);
  }

  async get(id: string): Promise<LayoutElement | undefined> {
    const row = await this.db.roomLayoutElements.get(id);
    return row ? normalise(row) : undefined;
  }

  /** Place a new element at the canvas centre, exactly as the original does. */
  async placeElement(
    caseId: string,
    roomId: string,
    kind: LayoutElementKind,
    options: { size?: LayoutElementSize; posX?: number; posY?: number; notes?: string } = {},
  ): Promise<LayoutElement> {
    const room = await this.db.structureRooms.get(roomId);
    if (!room) throw new ValidationError(`Room not found: ${roomId}`, "roomId");
    if (room.caseId !== caseId) throw new ValidationError("Room belongs to a different case.", "roomId");
    const spec = LAYOUT_ELEMENT_KINDS[kind];
    if (!spec) throw new ValidationError(`Unknown layout element kind: ${kind}`, "kind");
    const size = options.size && spec.supportedSizes.includes(options.size) ? options.size : spec.defaultSize;
    const ts = Date.now();
    const record: RoomLayoutElementRecord = {
      id: uuidv4(),
      schemaVersion: SCHEMA_VERSION,
      createdAt: ts,
      updatedAt: ts,
      caseId,
      roomId,
      kind,
      size,
      posX: options.posX ?? 0.5, // original default placement
      posY: options.posY ?? 0.5,
      rotationDegrees: 0,
      revision: 1,
      notes: options.notes ?? "",
      roomName: room.name,
      anchorRelation: "none",
      ventStyle: "wall",
      lightStyle: "ceiling",
      archived: false,
    };
    await this.db.roomLayoutElements.put(record);
    await this.audit.record("roomUpdated", `Layout element placed (${spec.name}).`, {
      caseId,
      affectedRecordId: record.id,
      metadata: { elementKind: kind, roomId, size },
    });
    return normalise(record);
  }

  /** Copy the selected item with a stable new ID and the original +6% offset. */
  async duplicateElement(id: string): Promise<LayoutElement> {
    const source = await this.get(id);
    if (!source) throw new ValidationError(`Layout element not found: ${id}`, "id");
    const ts = Date.now();
    const copy: RoomLayoutElementRecord = {
      ...source,
      id: uuidv4(),
      createdAt: ts,
      updatedAt: ts,
      posX: Math.min(0.97, source.posX + 0.06),
      posY: Math.min(0.97, source.posY + 0.06),
      revision: 1,
      archived: false,
    };
    await this.db.roomLayoutElements.put(copy);
    await this.audit.record("roomUpdated", `Layout element duplicated (${LAYOUT_ELEMENT_KINDS[source.kind].name}).`, {
      caseId: source.caseId,
      affectedRecordId: copy.id,
      metadata: { elementKind: source.kind, roomId: source.roomId, sourceElementId: source.id, revision: copy.revision ?? 1 },
    });
    return normalise(copy);
  }

  /** Drag-move with the original clamp to the canvas. */
  async moveElement(id: string, posX: number, posY: number): Promise<LayoutElement> {
    return this.mutate(id, (el) => ({
      ...el,
      posX: Math.max(0, Math.min(1, posX)),
      posY: Math.max(0, Math.min(1, posY)),
    }), "moved");
  }

  /** Size change — restricted to the kind's supported sizes (original menu). */
  async resizeElement(id: string, size: LayoutElementSize): Promise<LayoutElement> {
    const element = await this.get(id);
    if (!element) throw new ValidationError(`Layout element not found: ${id}`, "id");
    const spec = LAYOUT_ELEMENT_KINDS[element.kind];
    if (!spec.supportedSizes.includes(size)) {
      throw new ValidationError(
        `${spec.name} supports: ${spec.supportedSizes.join(", ")}.`,
        "size",
      );
    }
    return this.mutate(id, (el) => ({ ...el, size }), `resized to ${size}`);
  }

  /** Rotate — original: `(rotation + 90) mod 360`. */
  async rotateElement(id: string): Promise<LayoutElement> {
    return this.mutate(
      id,
      (el) => ({ ...el, rotationDegrees: (el.rotationDegrees + 90) % 360 }),
      "rotated 90°",
    );
  }

  /** Conditional properties (only valid for their specific kinds). */
  async setAnchorRelation(id: string, relation: AnchorRelation): Promise<LayoutElement> {
    const element = await this.requireKind(id, "outlet");
    return this.mutate(element.id, (el) => ({ ...el, anchorRelation: relation }), `outlet relation ${relation}`);
  }

  async setVentStyle(id: string, style: VentStyle): Promise<LayoutElement> {
    const element = await this.requireKind(id, "ventHVAC");
    return this.mutate(element.id, (el) => ({ ...el, ventStyle: style }), `vent style ${style}`);
  }

  async setLightStyle(id: string, style: LightStyle): Promise<LayoutElement> {
    const element = await this.requireKind(id, "lightFixture");
    return this.mutate(element.id, (el) => ({ ...el, lightStyle: style }), `light style ${style}`);
  }

  private async requireKind(id: string, kind: LayoutElementKind): Promise<LayoutElement> {
    const element = await this.get(id);
    if (!element) throw new ValidationError(`Layout element not found: ${id}`, "id");
    if (element.kind !== kind) {
      throw new ValidationError(
        `This property applies only to ${LAYOUT_ELEMENT_KINDS[kind].name} elements (this is ${LAYOUT_ELEMENT_KINDS[element.kind].name}).`,
        "kind",
      );
    }
    return element;
  }

  /** Change the element type (size is re-validated against the new kind). */
  async changeKind(id: string, kind: LayoutElementKind): Promise<LayoutElement> {
    const spec = LAYOUT_ELEMENT_KINDS[kind];
    if (!spec) throw new ValidationError(`Unknown layout element kind: ${kind}`, "kind");
    return this.mutate(
      id,
      (el) => ({
        ...el,
        kind,
        size: spec.supportedSizes.includes(el.size) ? el.size : spec.defaultSize,
        anchorRelation: kind === "outlet" ? el.anchorRelation : "none",
        ventStyle: kind === "ventHVAC" ? el.ventStyle : "wall",
        lightStyle: kind === "lightFixture" ? el.lightStyle : "ceiling",
      }),
      `changed to ${spec.name}`,
    );
  }

  async setNotes(id: string, notes: string): Promise<LayoutElement> {
    return this.mutate(id, (el) => ({ ...el, notes }), "notes updated");
  }

  /**
   * Remove an element — the original behaviour (`modelContext.delete`). The audit
   * event preserves kind, room and position so the removal is traceable.
   */
  async removeElement(id: string): Promise<void> {
    const element = await this.get(id);
    if (!element) throw new ValidationError(`Layout element not found: ${id}`, "id");
    await this.db.roomLayoutElements.delete(id);
    await this.audit.record("roomUpdated", `Layout element removed (${LAYOUT_ELEMENT_KINDS[element.kind].name}).`, {
      caseId: element.caseId,
      affectedRecordId: id,
      metadata: {
        elementKind: element.kind,
        roomId: element.roomId,
        posX: element.posX,
        posY: element.posY,
        rotationDegrees: element.rotationDegrees,
        revision: (element.revision ?? 1) + 1,
      },
    });
  }

  /** Browser addition: keep the record but hide it from the layout. */
  async archiveElement(id: string): Promise<LayoutElement> {
    return this.mutate(id, (el) => ({ ...el, archived: true }), "archived");
  }

  async restoreElement(id: string): Promise<LayoutElement> {
    return this.mutate(id, (el) => ({ ...el, archived: false }), "restored");
  }

  /** Footprint of an element as fractions of the room canvas (original maths). */
  footprintOf(element: LayoutElement): { width: number; height: number } {
    return elementFootprint(element.kind, element.size);
  }

  /** Footprint after rotation (the original rotated bounds). */
  rotatedFootprintOf(element: LayoutElement): { width: number; height: number } {
    return rotatedFootprint(this.footprintOf(element), element.rotationDegrees);
  }

  private async mutate(
    id: string,
    change: (element: LayoutElement) => LayoutElement,
    description: string,
  ): Promise<LayoutElement> {
    const element = await this.get(id);
    if (!element) throw new ValidationError(`Layout element not found: ${id}`, "id");
    const next = change(element);
    const record: RoomLayoutElementRecord = {
      id: next.id,
      schemaVersion: next.schemaVersion,
      createdAt: next.createdAt,
      updatedAt: Date.now(),
      caseId: next.caseId,
      roomId: next.roomId,
      kind: next.kind,
      size: next.size,
      posX: next.posX,
      posY: next.posY,
      rotationDegrees: next.rotationDegrees,
      revision: next.revision + 1,
      notes: next.notes,
      roomName: next.roomName,
      anchorRelation: next.anchorRelation,
      ventStyle: next.ventStyle,
      lightStyle: next.lightStyle,
      archived: next.archived,
    };
    await this.db.roomLayoutElements.put(record);
    await this.audit.record("roomUpdated", `Layout element ${description} (${LAYOUT_ELEMENT_KINDS[next.kind].name}).`, {
      caseId: next.caseId,
      affectedRecordId: id,
      metadata: { elementKind: next.kind, roomId: next.roomId, revision: record.revision ?? 1 },
    });
    return normalise(record);
  }
}
