/**
 * Property Structure view (TPI-V2-WEB-007 §7/§8/§9).
 *
 * Structure hierarchy (floors/zones/rooms), interactive SVG floor-plan room
 * builder with normalized-geometry persistence, and investigation markers.
 * Built with delegated handlers + idempotent mounting (KI-WEB-006-1 fix).
 * Accessibility: every drag interaction has a form-based equivalent
 * (numeric x/y/width/height inputs).
 */
import "./casehub.css";
import { getDb } from "../../core/db";
import { CaseRepository } from "../../core/repositories/caseRepository";
import { ClaimRepository } from "../../core/repositories/claimsRepository";
import {
  ELECTRONICS_OPTIONS,
  HVAC_OPTIONS,
  LIGHTING_OPTIONS,
  MARKER_SOURCES,
  MARKER_TYPES,
  PropertyService,
  ROOM_SHAPES,
  WINDOW_OPTIONS,
} from "../../core/property/propertyService";
import { LayoutElementService, type LayoutElement } from "../../core/property/layoutElementService";
import {
  CATEGORY_NAMES,
  KINDS_BY_CATEGORY,
  LAYOUT_ELEMENT_KINDS,
  SIZE_NAMES,
  ANCHOR_NAMES,
  VENT_NAMES,
  LIGHT_NAMES,
  conditionalProperties,
  elementFootprint,
  type LayoutElementCategory,
  type LayoutElementKind,
} from "../../core/property/layoutCatalog";
import type { RoomRecord, RoomShape } from "../../core/types";
import { esc, viewShell, wireBackButton } from "../dashboard/shell";
import { mountView, onDelegate, invalidateView, clearDrafts } from "../../shared/uidom";
import { renderCaseHub } from "./CaseHub";
import { claimsManagerHtml, wireClaimsManager } from "./ClaimsManager";
import { wireReferenceClaimImport, type ReferenceImportData } from "./ReferenceClaimImport";

const db = () => getDb();
const service = () => new PropertyService(db());

interface BuilderState {
  structureId: string;
  selectedFloorId: string | null;
  selectedRoomId: string | null;
  /** SVG viewBox for zoom/pan: [x, y, w, h] in normalized ×100 units. */
  view: [number, number, number, number];
  markerMode: boolean;
  /** Live rooms for the current render (drag handlers read geometry here). */
  rooms: RoomRecord[];
  /** Live layout elements for the selected room (010G-A). */
  elements: LayoutElement[];
  selectedElementId: string | null;
  layoutCategory: LayoutElementCategory;
  layoutKind: LayoutElementKind;
  layoutPlaceMode: boolean;
}

const state = new WeakMap<HTMLElement, BuilderState>();
/** Live position while dragging a layout element (committed on pointerup). */
let pendingElementPosition: { posX: number; posY: number } | null = null;

function st(container: HTMLElement): BuilderState {
  let s = state.get(container);
  if (!s) {
    s = {
      structureId: "",
      selectedFloorId: null,
      selectedRoomId: null,
      view: [0, 0, 100, 100],
      markerMode: false,
      rooms: [],
      elements: [],
      selectedElementId: null,
      layoutCategory: "doors",
      layoutKind: "singleDoor",
      layoutPlaceMode: false,
    };
    state.set(container, s);
  }
  return s;
}

export async function renderPropertyStructure(container: HTMLElement, caseId: string): Promise<void> {
  const record = await new CaseRepository(db()).getCase(caseId);
  if (!record) {
    invalidateView(container);
    mountView(container, viewShell("Property Structure", `<div class="cc-empty">Case not found.</div>`));
    wireBackButton(container);
    return;
  }
  const svc = service();
  const structure = await svc.ensureStructureForCase(caseId);
  const hierarchy = await svc.loadHierarchy(structure.id);
  const markers = await svc.listMarkers(caseId);
  const claims = await new ClaimRepository(db()).listForCase(caseId);
  // Include archived rooms: historical claim links must remain resolvable and
  // editable even after a room is removed from the active layout.
  const allRooms = await db().structureRooms.where("caseId").equals(caseId).toArray();
  const s = st(container);
  s.rooms = [...hierarchy.floors.flatMap((f) => f.rooms), ...hierarchy.zones.flatMap((z) => z.rooms), ...hierarchy.unassignedRooms];
  if (!s.selectedFloorId && hierarchy.floors.length > 0) s.selectedFloorId = hierarchy.floors[0]!.id;
  if (s.structureId !== structure.id) {
    s.structureId = structure.id;
    s.selectedRoomId = null;
    s.view = [0, 0, 100, 100];
    s.markerMode = false;
  }

  const roomsOf = (floorId: string): RoomRecord[] => hierarchy.floors.find((f) => f.id === floorId)?.rooms ?? [];
  const floorRooms = s.selectedFloorId ? roomsOf(s.selectedFloorId) : [];
  // Layout elements belong to the selected room (010G-A). They are decorative
  // context inside the room footprint and never alter room geometry.
  s.elements = s.selectedRoomId ? await new LayoutElementService(db()).listForRoom(s.selectedRoomId, true) : [];
  if (s.selectedElementId && !s.elements.some((e) => e.id === s.selectedElementId)) s.selectedElementId = null;
  const zoneRooms = hierarchy.zones.flatMap((z) => z.rooms);
  const selectedRoom = [...floorRooms, ...zoneRooms, ...hierarchy.unassignedRooms].find((r) => r.id === s.selectedRoomId);

  invalidateView(container); // different view — reset idempotence cache
  mountView(
    container,
    viewShell(
      `Property Structure — ${record.caseNumber}`,
      `
      <div class="case-form" data-root="property-structure" data-case-id="${esc(caseId)}" data-epoch="${Date.now()}-${Math.random()}">
        <p class="cc-count"><strong>${esc(hierarchy.structure.name)}</strong> • ${esc(hierarchy.structure.kind)} •
        revision ${hierarchy.structure.revision} • ${hierarchy.floors.length} floor(s) • ${hierarchy.zones.length} zone(s) •
        ${hierarchy.floors.reduce((n, f) => n + f.rooms.length, 0) + hierarchy.zones.reduce((n, z) => n + z.rooms.length, 0)} active room(s)/area(s)</p>

        <h3 class="cc-section-title">Floors & Levels</h3>
        <div class="form-actions">
          <input id="floor-name" type="text" placeholder="Floor name (e.g. Main Floor, Basement, Attic)" aria-label="New floor name">
          <button class="button-secondary" id="add-floor" type="button">Add Floor</button>
        </div>
        <div>${hierarchy.floors
          .map(
            (f) => `
          <div class="case-row" data-floor="${f.id}">
            <div><div class="case-title">${esc(f.displayName)}</div>
            <div class="case-meta">${f.rooms.length} room(s) • order ${f.orderIndex}</div></div>
            <button class="back-button" data-rename-floor="${f.id}" type="button">Rename</button>
          </div>`,
          )
          .join("") || '<div class="cc-empty">No floors yet — add one below.</div>'}</div>

        <h3 class="cc-section-title">Zones / Sectors (outdoor & non-room areas)</h3>
        <div class="form-actions">
          <input id="zone-name" type="text" placeholder="Zone name (e.g. North Grounds, Sector A)" aria-label="New zone name">
          <button class="button-secondary" id="add-zone" type="button">Add Zone</button>
        </div>
        <div>${hierarchy.zones
          .map(
            (z) => `
          <div class="case-row" data-zone="${z.id}">
            <div><div class="case-title">${esc(z.displayName)}</div>
            <div class="case-meta">${z.rooms.length} area(s) • order ${z.orderIndex}</div></div>
          </div>`,
          )
          .join("") || '<div class="cc-empty">No zones yet.</div>'}</div>

        <h3 class="cc-section-title">Rooms & Areas</h3>
        <div class="form-actions">
          <select id="room-parent" aria-label="Room location">
            ${hierarchy.floors.map((f) => `<option value="${f.id}" data-kind="floor">${esc(`Floor: ${f.displayName}`)}</option>`).join("")}
            ${hierarchy.zones.map((z) => `<option value="${z.id}" data-kind="zone">${esc(`Zone: ${z.displayName}`)}</option>`).join("")}
          </select>
          <select id="room-shape" aria-label="Room shape">
            ${ROOM_SHAPES.map((r) => `<option value="${r.id}">${esc(r.label)}</option>`).join("")}
          </select>
          <input id="room-name" type="text" placeholder="Room / area name" aria-label="New room name">
          <button class="button-primary" id="add-room" type="button">Add Room</button>
        </div>
        <div id="room-list">
          ${[...hierarchy.floors.flatMap((f) => f.rooms.map((r) => ({ r, parent: f.displayName }))),
             ...hierarchy.zones.flatMap((z) => z.rooms.map((r) => ({ r, parent: z.displayName }))),
             ...hierarchy.unassignedRooms.map((r) => ({ r, parent: "Unassigned" }))]
            .map(
              ({ r, parent }) => `
            <div class="case-row" data-room-row="${r.id}">
              <div>
                <div class="case-title">${esc(r.name)}${r.assessmentStatus === "reviewed" ? " ✓" : r.assessmentStatus === "notApplicable" ? " (N/A)" : ""}</div>
                <div class="case-meta">${esc(parent)} • ${esc(r.builderShape)} • assessment: ${esc(r.assessmentStatus)}</div>
              </div>
              <div style="display:flex;gap:6px;">
                <button class="back-button" data-select-room="${r.id}" type="button">Select</button>
                <button class="back-button" data-rename-room="${r.id}" type="button">Rename</button>
                <button class="back-button" data-archive-room="${r.id}" type="button">Archive…</button>
              </div>
            </div>`,
            )
            .join("") || '<div class="cc-empty">No rooms yet.</div>'}
        </div>

        <h3 class="cc-section-title">Floor Plan — ${esc(hierarchy.floors.find((f) => f.id === s.selectedFloorId)?.displayName ?? "no floor selected")}</h3>
        <div class="form-actions">
          <button class="back-button" id="zoom-in" type="button">Zoom +</button>
          <button class="back-button" id="zoom-out" type="button">Zoom −</button>
          <button class="back-button" id="pan-reset" type="button">Reset View</button>
          <button class="back-button" id="toggle-markers" type="button">${s.markerMode ? "Marker Mode: ON (click canvas)" : "Marker Mode: OFF"}</button>
        </div>
        <svg id="floor-canvas" viewBox="${s.view.join(" ")}" width="100%" height="360"
             style="background:#0B0E12;border:1px solid #2A3441;border-radius:8px;touch-action:none;"
             role="img" aria-label="Floor plan canvas for the selected floor">
          <rect x="0" y="0" width="100" height="100" fill="none" stroke="#2A3441" stroke-width="0.4"/>
          ${floorRooms
            .map(
              (r) => `
            <g class="plan-room" data-plan-room="${r.id}" style="cursor:pointer;">
              <rect x="${(r.posX * 100).toFixed(2)}" y="${(r.posY * 100).toFixed(2)}"
                    width="${(r.width * 100).toFixed(2)}" height="${(r.height * 100).toFixed(2)}"
                    rx="${r.builderShape === "openArea" ? 2 : 0.6}"
                    fill="${s.selectedRoomId === r.id ? "rgba(0,194,255,0.12)" : "rgba(0,194,255,0.04)"}"
                    stroke="${s.selectedRoomId === r.id ? "#00C2FF" : "#3A4656"}"
                    stroke-width="${s.selectedRoomId === r.id ? 0.5 : 0.3}"
                    ${r.builderShape === "openArea" ? 'stroke-dasharray="2 1"' : ""}/>
              <text x="${((r.posX + 0.01) * 100).toFixed(2)}" y="${((r.posY + 0.05) * 100).toFixed(2)}"
                    font-size="2.4" fill="#9FB3C8">${esc(r.name)}</text>
              ${r.assessmentStatus === "reviewed" ? `<circle cx="${((r.posX + r.width - 0.03) * 100).toFixed(2)}" cy="${((r.posY + 0.04) * 100).toFixed(2)}" r="1" fill="#37C871"/>` : ""}
              ${r.id === s.selectedRoomId ? layoutElementsSvg(r, s.elements) : ""}
            </g>`,
            )
            .join("")}
          ${markers
            .filter((m) => m.floorId === s.selectedFloorId)
            .map(
              (m) => `
            <g class="plan-marker" data-plan-marker="${m.id}">
              <circle cx="${(m.posX * 100).toFixed(2)}" cy="${(m.posY * 100).toFixed(2)}" r="1.2"
                      fill="${markerColor(m.markerType)}" stroke="#0B0E12" stroke-width="0.2"/>
              <title>${esc(m.label)} (${esc(m.markerType)} — ${esc(m.source)})</title>
            </g>`,
            )
            .join("")}
        </svg>
        <p class="cc-meta">Drag rooms to move them; drag the bottom-right corner handle to resize. Keyboard alternative: select a room and edit the numeric fields below. Scroll wheel zooms; drag empty canvas to pan.</p>

        ${selectedRoom ? roomEditorHtml(selectedRoom) : '<div class="cc-empty">Select a room to edit its properties.</div>'}
        ${selectedRoom ? layoutElementPanelHtml(selectedRoom, s) : ""}

        <h3 class="cc-section-title">Markers (${markers.length})</h3>
        ${markers.length === 0 ? '<div class="cc-empty">No markers placed.</div>' : markers
          .map(
            (m) => `
          <div class="case-row" data-marker-row="${m.id}">
            <div>
              <div class="case-title">${esc(m.label)}</div>
              <div class="case-meta">${esc(m.markerType)} • source: ${esc(m.source)} • ${m.roomId ? "room-linked" : "floor-level"}${m.evidenceId ? " • evidence-linked" : ""}</div>
            </div>
            <button class="back-button" data-edit-marker="${m.id}" type="button">Edit…</button>
          </div>`,
          )
          .join("")}

        ${claimsManagerHtml(container, {
          caseId,
          claims,
          rooms: allRooms,
          floors: hierarchy.floors,
          zones: hierarchy.zones,
          referenceImportEligible: record.investigationType === "hauntedLocation",
        })}

        <div class="form-actions">
          <button class="back-button" id="ps-back" type="button">← Back to Case Hub</button>
        </div>
      </div>
    `,
  ));

  wireHandlers(container, caseId);
  const rerender = () => renderPropertyStructure(container, caseId);
  wireClaimsManager(container, caseId, rerender);
  const referenceImportData: ReferenceImportData = {
    caseId,
    rooms: allRooms,
    floors: hierarchy.floors,
    zones: hierarchy.zones,
    eligible: record.investigationType === "hauntedLocation",
  };
  wireReferenceClaimImport(container, referenceImportData, rerender);
  wireBackButton(container);
}

function markerColor(type: string): string {
  switch (type) {
    case "reportedActivity": return "#E0A83C";
    case "investigatorObservation": return "#00C2FF";
    case "environmentalPoint": return "#7BC49A";
    case "equipmentPosition": return "#8E7CC3";
    case "evidenceLocation": return "#C97BA0";
    case "followUp": return "#C9C07B";
    default: return "#9FB3C8";
  }
}

function roomEditorHtml(room: RoomRecord): string {
  return `
    <div class="case-form" id="room-editor" data-room-id="${room.id}">
      <h3 class="cc-section-title">Room Editor — ${esc(room.name)}</h3>
      <div class="detail-grid">
        <div class="detail-field"><label for="room-edit-name">Room name</label>
          <input id="room-edit-name" data-room-field="name" type="text" value="${esc(room.name)}"></div>
        <div class="detail-field"><label for="room-edit-shape">Shape</label>
          <select id="room-edit-shape" data-room-field="shape">
            ${ROOM_SHAPES.map((r) => `<option value="${r.id}" ${r.id === room.builderShape ? "selected" : ""}>${esc(r.label)}</option>`).join("")}
          </select></div>
        <div class="detail-field"><label for="room-edit-x">X position (0–100)</label>
          <input id="room-edit-x" data-room-geom="posX" type="number" step="0.5" min="0" max="100" value="${(room.posX * 100).toFixed(1)}"></div>
        <div class="detail-field"><label for="room-edit-y">Y position (0–100)</label>
          <input id="room-edit-y" data-room-geom="posY" type="number" step="0.5" min="0" max="100" value="${(room.posY * 100).toFixed(1)}"></div>
        <div class="detail-field"><label for="room-edit-w">Width (0–100)</label>
          <input id="room-edit-w" data-room-geom="width" type="number" step="0.5" min="1" max="100" value="${(room.width * 100).toFixed(1)}"></div>
        <div class="detail-field"><label for="room-edit-h">Height (0–100)</label>
          <input id="room-edit-h" data-room-geom="height" type="number" step="0.5" min="1" max="100" value="${(room.height * 100).toFixed(1)}"></div>
      </div>
      <div class="detail-field"><label for="room-edit-notes">Room notes (map / physical context)</label>
        <textarea id="room-edit-notes" data-room-field="notes" rows="2">${esc(room.notes)}</textarea></div>
      <div class="form-actions"><button class="button-primary" id="apply-room-edit" type="button">Apply Room Changes</button></div>

      <h3 class="cc-section-title">Room Assessment</h3>
      <div class="detail-grid">
        <div class="detail-field"><label for="assess-lighting">Lighting conditions</label>
          <select id="assess-lighting" data-assess="lightingConditions">
            <option value="">— select —</option>
            ${LIGHTING_OPTIONS.map((o) => `<option ${room.lightingConditions === o ? "selected" : ""}>${esc(o)}</option>`).join("")}
          </select></div>
        <div class="detail-field"><label for="assess-windows">Windows</label>
          <select id="assess-windows" data-assess="windowsState">
            <option value="">— select —</option>
            ${WINDOW_OPTIONS.map((o) => `<option ${room.windowsState === o ? "selected" : ""}>${esc(o)}</option>`).join("")}
          </select></div>
        <div class="detail-field"><label for="assess-hvac">HVAC</label>
          <select id="assess-hvac" data-assess="hvacState">
            <option value="">— select —</option>
            ${HVAC_OPTIONS.map((o) => `<option ${room.hvacState === o ? "selected" : ""}>${esc(o)}</option>`).join("")}
          </select></div>
        <div class="detail-field"><label for="assess-electronics">Electronics</label>
          <select id="assess-electronics" data-assess="electronicsState">
            <option value="">— select —</option>
            ${ELECTRONICS_OPTIONS.map((o) => `<option ${room.electronicsState === o ? "selected" : ""}>${esc(o)}</option>`).join("")}
          </select></div>
      </div>
      <div class="detail-field"><label for="assess-modifications">Recent modifications</label>
        <textarea id="assess-modifications" data-assess="recentModifications" rows="2">${esc(room.recentModifications)}</textarea></div>
      <div class="detail-field"><label for="assess-repairs">Repairs notes</label>
        <textarea id="assess-repairs" data-assess="repairsNotes" rows="2">${esc(room.repairsNotes)}</textarea></div>
      <div class="detail-field"><label for="assess-environmental">Environmental observations (manual observations — not sensor readings)</label>
        <textarea id="assess-environmental" data-assess="environmentalObservations" rows="2">${esc(room.environmentalObservations)}</textarea></div>
      <div class="form-actions">
        <button class="button-primary" id="save-assessment" type="button">Save Assessment</button>
        <button class="button-primary" id="mark-reviewed" type="button">Mark Reviewed</button>
        <button class="back-button" id="mark-na" type="button">Not Applicable…</button>
      </div>
      <p class="cc-meta">A room is "reviewed" (iOS minimum) only when lighting, window, HVAC, and electronics conditions are recorded. This is a walkthrough assessment — it does not create baseline measurements.</p>
    </div>`;
}

