function glyphFor(kind: LayoutElementKind): string {
  return ELEMENT_GLYPHS[kind] ?? '<path d="M4 6h16v12H4z"/>';
}

/** Draw the room's layout elements inside its SVG group. */
function layoutElementsSvg(room: RoomRecord, elements: LayoutElement[]): string {
  return elements
    .filter((e) => !e.archived)
    .map((e) => {
      const footprint = elementFootprint(e.kind, e.size);
      const cx = (room.posX + e.posX * room.width) * 100;
      const cy = (room.posY + e.posY * room.height) * 100;
      const w = footprint.width * room.width * 100;
      const h = footprint.height * room.height * 100;
      const spec = LAYOUT_ELEMENT_KINDS[e.kind];
      const stroke = e.id === (undefined as unknown as string) ? "#00C2FF" : "#8AA0B6";
      void stroke;
      const subLabel =
        e.kind === "outlet" ? ANCHOR_NAMES[e.anchorRelation]
          : e.kind === "ventHVAC" ? VENT_NAMES[e.ventStyle]
            : e.kind === "lightFixture" ? LIGHT_NAMES[e.lightStyle]
              : "";
      return `
        <g class="plan-element" data-plan-element="${e.id}" style="cursor:pointer;">
          <g transform="translate(${cx.toFixed(2)} ${cy.toFixed(2)}) rotate(${e.rotationDegrees})">
            <rect x="${(-w / 2).toFixed(2)}" y="${(-h / 2).toFixed(2)}" width="${w.toFixed(2)}" height="${h.toFixed(2)}"
                  fill="rgba(0,194,255,0.10)" stroke="#00C2FF" stroke-width="0.25" rx="0.4"/>
            <svg x="${(-w / 2 + 0.2).toFixed(2)}" y="${(-h / 2 + 0.2).toFixed(2)}" width="${Math.max(0.4, w - 0.4).toFixed(2)}" height="${Math.max(0.4, h - 0.4).toFixed(2)}"
                 viewBox="0 0 24 24" fill="none" stroke="#00C2FF" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round">
              ${glyphFor(e.kind)}
            </svg>
          </g>
          <title>${esc(spec.name)}${subLabel ? ` — ${esc(subLabel)}` : ""}</title>
        </g>`;
    })
    .join("");
}

/** Original palette + selected-element operations (010G-A). */
function layoutElementPanelHtml(room: RoomRecord, s: BuilderState): string {
  const selected = s.elements.find((e) => e.id === s.selectedElementId) ?? null;
  const spec = selected ? LAYOUT_ELEMENT_KINDS[selected.kind] : null;
  const cond = selected ? conditionalProperties(selected.kind) : { anchor: false, vent: false, light: false };
  const active = s.elements.filter((e) => !e.archived);
  const archived = s.elements.filter((e) => e.archived);

  return `
    <h3 class="cc-section-title">${active.length === 0 ? "Build Room Layout" : "Edit Room Layout"} — ${esc(room.name)}</h3>
    <div class="case-form" data-layout-panel="${room.id}" tabindex="0" role="group" aria-label="Room layout elements for ${esc(room.name)}">
      <p class="cc-meta">${active.length} layout item(s) in this room. Elements are placed inside the room footprint and never change room geometry or evidence.</p>

      <div class="detail-field"><label class="cc-count"><input type="checkbox" id="layout-place-mode" ${s.layoutPlaceMode ? "checked" : ""}> Place mode — click the room to position the next element</label></div>

      <div class="detail-grid">
        <div class="detail-field"><label for="layout-category">Category</label>
          <select id="layout-category">
            ${KINDS_BY_CATEGORY.map((g) => `<option value="${g.category}"${s.layoutCategory === g.category ? " selected" : ""}>${esc(CATEGORY_NAMES[g.category])}</option>`).join("")}
          </select></div>
        <div class="detail-field"><label for="layout-kind">Element</label>
          <select id="layout-kind">
            ${(KINDS_BY_CATEGORY.find((g) => g.category === s.layoutCategory)?.kinds ?? [])
              .map((k) => `<option value="${k}"${s.layoutKind === k ? " selected" : ""}>${esc(LAYOUT_ELEMENT_KINDS[k].name)}</option>`)
              .join("")}
          </select></div>
      </div>
      <div class="form-actions">
        <button class="button-primary" id="layout-add" type="button">Add Element at Centre</button>
      </div>

      ${
        selected && spec
          ? `
      <h3 class="cc-section-title">Selected Layout Item: ${esc(spec.name)}</h3>
      <div class="detail-grid">
        <div class="detail-field"><label for="layout-size">Size: ${esc(SIZE_NAMES[selected.size])}</label>
          <select id="layout-size">
            ${spec.supportedSizes.map((z) => `<option value="${z}"${z === selected.size ? " selected" : ""}>${esc(SIZE_NAMES[z])}</option>`).join("")}
          </select></div>
        ${cond.anchor ? `<div class="detail-field"><label for="layout-anchor">Outlet: ${esc(ANCHOR_NAMES[selected.anchorRelation])}</label>
          <select id="layout-anchor">${(Object.keys(ANCHOR_NAMES) as Array<keyof typeof ANCHOR_NAMES>).map((a) => `<option value="${a}"${a === selected.anchorRelation ? " selected" : ""}>${esc(ANCHOR_NAMES[a])}</option>`).join("")}</select></div>` : ""}
        ${cond.vent ? `<div class="detail-field"><label for="layout-vent">Vent: ${esc(VENT_NAMES[selected.ventStyle])}</label>
          <select id="layout-vent">${(Object.keys(VENT_NAMES) as Array<keyof typeof VENT_NAMES>).map((v) => `<option value="${v}"${v === selected.ventStyle ? " selected" : ""}>${esc(VENT_NAMES[v])}</option>`).join("")}</select></div>` : ""}
        ${cond.light ? `<div class="detail-field"><label for="layout-light">Light: ${esc(LIGHT_NAMES[selected.lightStyle])}</label>
          <select id="layout-light">${(Object.keys(LIGHT_NAMES) as Array<keyof typeof LIGHT_NAMES>).map((l) => `<option value="${l}"${l === selected.lightStyle ? " selected" : ""}>${esc(LIGHT_NAMES[l])}</option>`).join("")}</select></div>` : ""}
        <div class="detail-field"><label for="layout-kind-change">Change element type</label>
          <select id="layout-kind-change">
            ${KINDS_BY_CATEGORY.flatMap((g) => g.kinds)
              .map((k) => `<option value="${k}"${k === selected.kind ? " selected" : ""}>${esc(CATEGORY_NAMES[LAYOUT_ELEMENT_KINDS[k].category])} — ${esc(LAYOUT_ELEMENT_KINDS[k].name)}</option>`)
              .join("")}
          </select></div>
      </div>
      <div class="detail-field"><label for="layout-notes">Element notes</label>
        <input id="layout-notes" type="text" value="${esc(selected.notes)}" placeholder="e.g. outlet directly behind the client's chair"></div>
      <p class="cc-meta" id="layout-position">Position: ${(selected.posX * 100).toFixed(0)}% , ${(selected.posY * 100).toFixed(0)}% • rotation ${selected.rotationDegrees}°</p>
      <div class="form-actions">
        <button class="button-secondary" id="layout-apply" type="button">Apply Changes</button>
        <button class="button-secondary" id="layout-rotate" type="button">Rotate</button>
        <button class="button-secondary" id="layout-duplicate" type="button">Duplicate</button>
        <button class="back-button" id="layout-archive" type="button">Archive Item</button>
        <button class="back-button" id="layout-delete" type="button">Delete Item</button>
      </div>
      <p class="cc-meta">Arrow keys nudge the selected item; Shift+Arrow nudges further. Rotation is 90° per press, as in the original.</p>`
          : '<div class="cc-empty">Select a layout item in the room, or add one from the palette above.</div>'
      }

      ${active.length > 0 ? `<h3 class="cc-section-title">Items (${active.length})</h3>${active
        .map((e) => `<div class="case-row"><div><div class="case-title">${esc(LAYOUT_ELEMENT_KINDS[e.kind].name)}${e.id === s.selectedElementId ? " ▸" : ""}</div><div class="case-meta">${esc(SIZE_NAMES[e.size])} • ${(e.posX * 100).toFixed(0)}%,${(e.posY * 100).toFixed(0)}% • ${e.rotationDegrees}°${e.notes ? ` • ${esc(e.notes)}` : ""}</div></div><button class="back-button" data-select-element="${e.id}" type="button">Select</button></div>`)
        .join("")}` : ""}
      ${archived.length > 0 ? `<h3 class="cc-section-title">Archived items (${archived.length})</h3>${archived
        .map((e) => `<div class="case-row"><div><div class="case-title">${esc(LAYOUT_ELEMENT_KINDS[e.kind].name)}</div><div class="case-meta">archived</div></div><button class="back-button" data-restore-element="${e.id}" type="button">Restore</button></div>`)
        .join("")}` : ""}
    </div>`;
}

function wireHandlers(container: HTMLElement, caseId: string): void {
  try {
  onDelegate(container, "click", "[data-root='property-structure'] #ps-back", () => {
    void renderCaseHub(container, caseId);
  });
  onDelegate(container, "click", "#add-floor", async () => {
    // A successful add intentionally resets the add-form.
    clearDrafts(container);
    const input = container.querySelector<HTMLInputElement>("#floor-name");
    if (!input?.value.trim()) return;
    await service().createFloor(st(container).structureId, input.value);
    await renderPropertyStructure(container, caseId);
  });
  onDelegate(container, "click", "[data-rename-floor]", async (el) => {
    const floorId = el.dataset.renameFloor ?? "";
    const current = container.querySelector(`[data-floor="${floorId}"] .case-title`)?.textContent ?? "";
    const name = window.prompt("Rename floor:", current);
    if (!name?.trim()) return;
    await service().renameFloor(floorId, name);
    await renderPropertyStructure(container, caseId);
  });
  onDelegate(container, "click", "#add-zone", async () => {
    // A successful add intentionally resets the add-form.
    clearDrafts(container);
    const input = container.querySelector<HTMLInputElement>("#zone-name");
    if (!input?.value.trim()) return;
    await service().createZone(st(container).structureId, input.value);
    await renderPropertyStructure(container, caseId);
  });
  onDelegate(container, "click", "#add-room", async () => {
    // A successful add intentionally resets the add-form.
    clearDrafts(container);
    const s = st(container);
    const parentSel = container.querySelector<HTMLSelectElement>("#room-parent");
    const nameInput = container.querySelector<HTMLInputElement>("#room-name");
    const shapeSel = container.querySelector<HTMLSelectElement>("#room-shape");
    if (!parentSel || !shapeSel) return;
    if (!nameInput?.value.trim()) {
      alert("A room/area name is required.");
      return;
    }
    const parentOption = parentSel.selectedOptions[0];
    const isZone = parentOption?.dataset.kind === "zone";
    const parentValue = parentSel.value;
    await service().createRoom(s.structureId, {
      name: nameInput.value,
      shape: shapeSel.value as RoomShape,
      floorId: isZone ? null : parentValue,
      zoneId: isZone ? parentValue : null,
    });
    await renderPropertyStructure(container, caseId);
  });
  onDelegate(container, "click", "[data-select-room]", (el) => {
    const s = st(container);
    s.selectedRoomId = el.dataset.selectRoom ?? null;
    void renderPropertyStructure(container, caseId);
  });
  onDelegate(container, "click", "[data-rename-room]", async (el) => {
    const roomId = el.dataset.renameRoom ?? "";
    const current = container.querySelector(`[data-room-row="${roomId}"] .case-title`)?.textContent ?? "";
    const name = window.prompt("Rename room:", current);
    if (!name?.trim()) return;
    await service().updateRoomDetails(roomId, { name, reason: "Renamed" });
    await renderPropertyStructure(container, caseId);
  });
  onDelegate(container, "click", "[data-archive-room]", async (el) => {
    const roomId = el.dataset.archiveRoom ?? "";
    const reason = window.prompt("Document why this room is being archived (it is preserved, not deleted):", "");
    if (!reason?.trim()) return;
    await service().archiveRoom(roomId, reason);
    if (st(container).selectedRoomId === roomId) st(container).selectedRoomId = null;
    await renderPropertyStructure(container, caseId);
  });
  onDelegate(container, "click", "#zoom-in", () => {
    const s = st(container);
    s.view = zoomView(s.view, 0.8);
    void renderPropertyStructure(container, caseId);
  });
  onDelegate(container, "click", "#zoom-out", () => {
    const s = st(container);
    s.view = zoomView(s.view, 1.25);
    void renderPropertyStructure(container, caseId);
  });
  onDelegate(container, "click", "#pan-reset", () => {
    const s = st(container);
    s.view = [0, 0, 100, 100];
    void renderPropertyStructure(container, caseId);
  });
  onDelegate(container, "click", "#toggle-markers", () => {
    const s = st(container);
    s.markerMode = !s.markerMode;
    void renderPropertyStructure(container, caseId);
  });

  // Canvas interactions: select / move / resize rooms, place markers, pan.
  const canvasState: {
    mode: "idle" | "move" | "resize" | "pan";
    startX: number;
    startY: number;
    origin?: { x: number; y: number; w: number; h: number };
    view?: [number, number, number, number];
    live?: { posX: number; posY: number; width: number; height: number };
  } = { mode: "idle", startX: 0, startY: 0 };
  const toCanvas = (canvas: SVGSVGElement, e: PointerEvent): { x: number; y: number } => {
    const rect = canvas.getBoundingClientRect();
    const view = st(container).view;
    return {
      x: view[0] + ((e.clientX - rect.left) / rect.width) * view[2],
      y: view[1] + ((e.clientY - rect.top) / rect.height) * view[3],
    };
  };
  const canvas = () => container.querySelector<SVGSVGElement>("#floor-canvas");

  onDelegate(container, "click", "#floor-canvas .plan-room", (el) => {
    console.log("PLAN-ROOM-CLICK", st(container).markerMode);
    if (st(container).markerMode) return;
    st(container).selectedRoomId = el.dataset.planRoom ?? null;
    void renderPropertyStructure(container, caseId);
  });
  onDelegate(container, "click", "#floor-canvas", async (el, e) => {
    console.log("CANVAS-CLICK", st(container).markerMode);
    const s = st(container);
    if (!s.markerMode) return;
    const svg = el as unknown as SVGSVGElement;
    const pt = toCanvas(svg, e as PointerEvent);
    const label = window.prompt("Marker label:", "");
    if (!label?.trim()) return;
    const type = window.prompt(`Marker type (${MARKER_TYPES.join(", ")}):`, "reportedActivity") ?? "";
    if (!MARKER_TYPES.includes(type as never)) return;
    const source = window.prompt(`Source classification (${MARKER_SOURCES.join(", ")}):`, "clientReported") ?? "";
    if (!MARKER_SOURCES.includes(source as never)) return;
    const details = window.prompt("Details:", "") ?? "";
    const roomId = s.selectedRoomId ?? null;
    await service().createMarker(caseId, {
      roomId,
      floorId: s.selectedFloorId,
      posX: pt.x / 100,
      posY: pt.y / 100,
      markerType: type as never,
      label,
      details,
      source: source as never,
    });
    s.markerMode = false;
    await renderPropertyStructure(container, caseId);
  });

  // Drag handling for rooms (move/resize) and panning.
  onDelegate(container, "pointerdown", "#floor-canvas .plan-room", (el, e) => {
    if (st(container).markerMode) return;
    const roomId = el.dataset.planRoom ?? "";
    const s = st(container);
    const svg = canvas();
    if (!svg) return;
    const pt = toCanvas(svg, e as PointerEvent);
    const target = s.selectedRoomId === roomId ? (s.rooms.find((r) => r.id === roomId) ?? null) : null;
    if (!target) {
      s.selectedRoomId = roomId;
      void renderPropertyStructure(container, caseId);
      return;
    }
    const nearCorner = Math.abs(pt.x - (target.posX + target.width) * 100) < 4 && Math.abs(pt.y - (target.posY + target.height) * 100) < 4;
    canvasState.mode = nearCorner ? "resize" : "move";
    canvasState.startX = pt.x;
    canvasState.startY = pt.y;
    canvasState.origin = { x: target.posX * 100, y: target.posY * 100, w: target.width * 100, h: target.height * 100 };
    (e.target as Element).setPointerCapture?.((e as PointerEvent).pointerId);
  });
  onDelegate(container, "pointermove", "#floor-canvas", (_el, e) => {
    if (canvasState.mode === "idle") return;
    const svg = canvas();
    if (!svg) return;
    const s = st(container);
    const pt = toCanvas(svg, e as PointerEvent);
    if (canvasState.mode === "pan" && canvasState.view) {
      s.view = [
        Math.max(0, Math.min(100 - canvasState.view[2], canvasState.view[0] - (pt.x - canvasState.startX))),
        Math.max(0, Math.min(100 - canvasState.view[3], canvasState.view[1] - (pt.y - canvasState.startY))),
        canvasState.view[2],
        canvasState.view[3],
      ];
      svg.setAttribute("viewBox", s.view.join(" "));
      return;
    }
    if (!canvasState.origin || !s.selectedRoomId) return;
    const o = canvasState.origin;
    const dx = pt.x - canvasState.startX;
    const dy = pt.y - canvasState.startY;
    const g: { posX: number; posY: number; width: number; height: number } =
      canvasState.mode === "move"
        ? { posX: o.x + dx, posY: o.y + dy, width: o.w, height: o.h }
        : { posX: o.x, posY: o.y, width: Math.max(2, o.w + dx), height: Math.max(2, o.h + dy) };
    const rect = container.querySelector(`#floor-canvas [data-plan-room="${s.selectedRoomId}"] rect`);
    if (rect) {
      rect.setAttribute("x", String(Math.max(0, Math.min(100 - g.width, g.posX))));
      rect.setAttribute("y", String(Math.max(0, Math.min(100 - g.height, g.posY))));
      rect.setAttribute("width", String(Math.min(g.width, 100)));
      rect.setAttribute("height", String(Math.min(g.height, 100)));
    }
    canvasState.live = g;
  });
  onDelegate(container, "pointerup", "#floor-canvas", async () => {
    const s = st(container);
    const g = canvasState.live;
    if (canvasState.mode !== "idle" && canvasState.mode !== "pan" && g && s.selectedRoomId) {
      try {
        await service().updateRoomGeometry(s.selectedRoomId, {
          posX: Math.max(0, Math.min(100 - g.width, g.posX)) / 100,
          posY: Math.max(0, Math.min(100 - g.height, g.posY)) / 100,
          width: g.width / 100,
          height: g.height / 100,
        });
      } catch (err) {
        alert((err as Error).message);
      }
      canvasState.live = undefined;
      await renderPropertyStructure(container, caseId);
    }
    canvasState.mode = "idle";
  });
  // Pan: drag empty canvas background.
  onDelegate(container, "pointerdown", "#floor-canvas rect", (el, e) => {
    const s = st(container);
    if (s.markerMode) return;
    // Only the background border rect (no parent plan-room group).
    if (el.closest(".plan-room")) return;
    const svg = canvas();
    if (!svg) return;
    const pt = toCanvas(svg, e as PointerEvent);
    canvasState.mode = "pan";
    canvasState.startX = pt.x;
    canvasState.startY = pt.y;
    canvasState.view = [...s.view];
  });

  // Wheel zoom.
  onDelegate(container, "wheel", "#floor-canvas", (el, e) => {
    e.preventDefault();
    const s = st(container);
    s.view = zoomView(s.view, e.deltaY > 0 ? 1.1 : 0.9);
    (el as unknown as SVGSVGElement).setAttribute("viewBox", s.view.join(" "));
  });

  // ---- Layout elements (010G-A) ----
  const layoutService = () => new LayoutElementService(db());
  const selectedElement = () => {
    const s = st(container);
    return s.elements.find((e) => e.id === s.selectedElementId) ?? null;
  };

  onDelegate(container, "change", "#layout-category", (el) => {
    const s = st(container);
    s.layoutCategory = (el as HTMLSelectElement).value as LayoutElementCategory;
    const kinds = KINDS_BY_CATEGORY.find((g) => g.category === s.layoutCategory)?.kinds ?? [];
    s.layoutKind = kinds[0] ?? "singleDoor";
    void renderPropertyStructure(container, caseId);
  });
  onDelegate(container, "change", "#layout-kind", (el) => {
    st(container).layoutKind = (el as HTMLSelectElement).value as LayoutElementKind;
  });
  onDelegate(container, "change", "#layout-place-mode", (el) => {
    st(container).layoutPlaceMode = (el as HTMLInputElement).checked;
  });

  onDelegate(container, "click", "#layout-add", async () => {
    const s = st(container);
    if (!s.selectedRoomId) {
      alert("Select a room first — layout elements belong to a room.");
      return;
    }
    const element = await layoutService().placeElement(caseId, s.selectedRoomId, s.layoutKind);
    s.selectedElementId = element.id;
    await renderPropertyStructure(container, caseId);
  });

  // Place mode: click inside the room to drop the next element at that point.
  onDelegate(container, "click", "#floor-canvas .plan-room", async (el, event) => {
    const s = st(container);
    if (!s.layoutPlaceMode || !s.selectedRoomId) return;
    const room = s.rooms.find((r) => r.id === el.dataset.planRoom);
    if (!room) return;
    const svg = container.querySelector<SVGSVGElement>("#floor-canvas");
    if (!svg) return;
    const rect = svg.getBoundingClientRect();
    const view = s.view;
    const nx = (view[0] + ((event as PointerEvent).clientX - rect.left) / rect.width * view[2]) / 100;
    const ny = (view[1] + ((event as PointerEvent).clientY - rect.top) / rect.height * view[3]) / 100;
    const posX = Math.max(0, Math.min(1, (nx - room.posX) / Math.max(room.width, 0.001)));
    const posY = Math.max(0, Math.min(1, (ny - room.posY) / Math.max(room.height, 0.001)));
    const element = await layoutService().placeElement(caseId, room.id, s.layoutKind, { posX, posY });
    s.selectedElementId = element.id;
    s.layoutPlaceMode = false;
    await renderPropertyStructure(container, caseId);
  });

  onDelegate(container, "click", "[data-select-element]", (el) => {
    const s = st(container);
    s.selectedElementId = el.dataset.selectElement ?? null;
    void renderPropertyStructure(container, caseId);
  });
  onDelegate(container, "click", "[data-restore-element]", async (el) => {
    await layoutService().restoreElement(el.dataset.restoreElement ?? "");
    await renderPropertyStructure(container, caseId);
  });

  onDelegate(container, "click", "#layout-apply", async () => {
    const element = selectedElement();
    if (!element) return;
    try {
      const size = container.querySelector<HTMLSelectElement>("#layout-size")?.value;
      if (size && size !== element.size) await layoutService().resizeElement(element.id, size as never);
      const kind = container.querySelector<HTMLSelectElement>("#layout-kind-change")?.value;
      if (kind && kind !== element.kind) await layoutService().changeKind(element.id, kind as LayoutElementKind);
      const fresh = await layoutService().get(element.id);
      if (!fresh) return;
      if (fresh.kind === "outlet") {
        const anchor = container.querySelector<HTMLSelectElement>("#layout-anchor")?.value;
        if (anchor && anchor !== fresh.anchorRelation) await layoutService().setAnchorRelation(element.id, anchor as never);
      }
      if (fresh.kind === "ventHVAC") {
        const vent = container.querySelector<HTMLSelectElement>("#layout-vent")?.value;
        if (vent && vent !== fresh.ventStyle) await layoutService().setVentStyle(element.id, vent as never);
      }
      if (fresh.kind === "lightFixture") {
        const light = container.querySelector<HTMLSelectElement>("#layout-light")?.value;
        if (light && light !== fresh.lightStyle) await layoutService().setLightStyle(element.id, light as never);
      }
      const notes = container.querySelector<HTMLInputElement>("#layout-notes")?.value ?? "";
      if (notes !== fresh.notes) await layoutService().setNotes(element.id, notes);
      await renderPropertyStructure(container, caseId);
    } catch (err) {
      alert((err as Error).message);
    }
  });

  onDelegate(container, "click", "#layout-rotate", async () => {
    const element = selectedElement();
    if (!element) return;
    await layoutService().rotateElement(element.id);
    await renderPropertyStructure(container, caseId);
  });
  onDelegate(container, "click", "#layout-duplicate", async () => {
    const element = selectedElement();
    if (!element) return;
    const duplicate = await layoutService().duplicateElement(element.id);
    st(container).selectedElementId = duplicate.id;
    await renderPropertyStructure(container, caseId);
  });
  onDelegate(container, "click", "#layout-archive", async () => {
    const element = selectedElement();
    if (!element) return;
    await layoutService().archiveElement(element.id);
    await renderPropertyStructure(container, caseId);
  });
  onDelegate(container, "click", "#layout-delete", async () => {
    const element = selectedElement();
    if (!element) return;
    if (!window.confirm("Delete this layout item? The removal is recorded in the audit trail.")) return;
    await layoutService().removeElement(element.id);
    await renderPropertyStructure(container, caseId);
  });

  // Clicking a placed element selects it.
  onDelegate(container, "click", "#floor-canvas .plan-element", (el) => {
    const s = st(container);
    if (s.layoutPlaceMode) return;
    s.selectedElementId = el.dataset.planElement ?? null;
    void renderPropertyStructure(container, caseId);
  });

  // Drag a placed element to move it (clamped inside the room, as the original).
  const elementDrag: { active: boolean; id: string | null; room: RoomRecord | null } = { active: false, id: null, room: null };
  onDelegate(container, "pointerdown", "#floor-canvas .plan-element", (el, event) => {
    const s = st(container);
    if (s.layoutPlaceMode) return;
    const id = el.dataset.planElement ?? null;
    const room = s.rooms.find((r) => r.id === s.selectedRoomId) ?? null;
    if (!id || !room) return;
    s.selectedElementId = id;
    elementDrag.active = true;
    elementDrag.id = id;
    elementDrag.room = room;
    (event as PointerEvent).preventDefault();
  });
  onDelegate(container, "pointermove", "#floor-canvas", (_el, event) => {
    if (!elementDrag.active || !elementDrag.id || !elementDrag.room) return;
    const s = st(container);
    const svg = container.querySelector<SVGSVGElement>("#floor-canvas");
    if (!svg) return;
    const rect = svg.getBoundingClientRect();
    const view = s.view;
    const nx = (view[0] + ((event as PointerEvent).clientX - rect.left) / rect.width * view[2]) / 100;
    const ny = (view[1] + ((event as PointerEvent).clientY - rect.top) / rect.height * view[3]) / 100;
    const room = elementDrag.room;
    const posX = Math.max(0, Math.min(1, (nx - room.posX) / Math.max(room.width, 0.001)));
    const posY = Math.max(0, Math.min(1, (ny - room.posY) / Math.max(room.height, 0.001)));
    const node = container.querySelector(`#floor-canvas [data-plan-element="${elementDrag.id}"] g`);
    if (node) {
      const footprint = elementFootprint(
        (s.elements.find((e) => e.id === elementDrag.id)?.kind ?? "table") as LayoutElementKind,
        (s.elements.find((e) => e.id === elementDrag.id)?.size ?? "medium") as never,
      );
      const cx = (room.posX + posX * room.width) * 100;
      const cy = (room.posY + posY * room.height) * 100;
      const rotation = s.elements.find((e) => e.id === elementDrag.id)?.rotationDegrees ?? 0;
      void footprint;
      node.setAttribute("transform", `translate(${cx.toFixed(2)} ${cy.toFixed(2)}) rotate(${rotation})`);
    }
    pendingElementPosition = { posX, posY };
  });
  onDelegate(container, "pointerup", "#floor-canvas", async () => {
    if (!elementDrag.active || !elementDrag.id) return;
    const id = elementDrag.id;
    elementDrag.active = false;
    elementDrag.id = null;
    elementDrag.room = null;
    if (pendingElementPosition) {
      const { posX, posY } = pendingElementPosition;
      pendingElementPosition = null;
      await layoutService().moveElement(id, posX, posY);
      await renderPropertyStructure(container, caseId);
    }
  });

  // Keyboard alternative for moving the selected item (accessibility, §7).
  onDelegate(container, "keydown", "[data-layout-panel]", async (_el, event) => {
    const element = selectedElement();
    if (!element) return;
    const key = (event as KeyboardEvent).key;
    const step = (event as KeyboardEvent).shiftKey ? 0.05 : 0.01;
    let dx = 0;
    let dy = 0;
    if (key === "ArrowLeft") dx = -step;
    else if (key === "ArrowRight") dx = step;
    else if (key === "ArrowUp") dy = -step;
    else if (key === "ArrowDown") dy = step;
    else return;
    (event as KeyboardEvent).preventDefault();
    await layoutService().moveElement(element.id, element.posX + dx, element.posY + dy);
    await renderPropertyStructure(container, caseId);
  });

  // Room editor form actions.
  onDelegate(container, "click", "#apply-room-edit", async () => {
    const roomId = container.querySelector<HTMLElement>("#room-editor")?.dataset.roomId ?? "";
    const name = container.querySelector<HTMLInputElement>("[data-room-field='name']")?.value ?? "";
    const shape = (container.querySelector<HTMLSelectElement>("[data-room-field='shape']")?.value ?? "rectangle") as RoomShape;
    const notes = container.querySelector<HTMLTextAreaElement>("[data-room-field='notes']")?.value ?? "";
    await service().updateRoomDetails(roomId, { name, builderShape: shape, notes, reason: "Edited via room editor" });
    await applyGeometryInputs(container, caseId);
  });
  onDelegate(container, "click", "#save-assessment", async () => {
    const roomId = container.querySelector<HTMLElement>("#room-editor")?.dataset.roomId ?? "";
    await service().saveRoomAssessment(roomId, readAssessment(container));
    await renderPropertyStructure(container, caseId);
  });
  onDelegate(container, "click", "#mark-reviewed", async () => {
    const roomId = container.querySelector<HTMLElement>("#room-editor")?.dataset.roomId ?? "";
    try {
      await service().saveRoomAssessment(roomId, readAssessment(container), { markReviewed: true });
      await renderPropertyStructure(container, caseId);
    } catch (err) {
      alert((err as Error).message);
    }
  });
  onDelegate(container, "click", "#mark-na", async () => {
    const roomId = container.querySelector<HTMLElement>("#room-editor")?.dataset.roomId ?? "";
    const reason = window.prompt("Document why this room/area does not apply:", "");
    if (!reason?.trim()) return;
    await service().markRoomNotApplicable(roomId, reason);
    await renderPropertyStructure(container, caseId);
  });
  onDelegate(container, "click", "[data-edit-marker]", async (el) => {
    const markerId = el.dataset.editMarker ?? "";
    const details = window.prompt("Update marker details:", "") ?? "";
    const source = window.prompt(`Source classification (${MARKER_SOURCES.join(", ")}):`, "investigatorObservation") ?? "";
    if (!MARKER_SOURCES.includes(source as never)) return;
    await service().updateMarker(markerId, { details, source: source as never });
    await renderPropertyStructure(container, caseId);
  });
  } catch (err) { console.log("WIRE-ERR", (err as Error).message, (err as Error).stack?.split("\n")[1]); }
}


async function applyGeometryInputs(container: HTMLElement, caseId: string): Promise<void> {
  const roomId = container.querySelector<HTMLElement>("#room-editor")?.dataset.roomId ?? "";
  const num = (sel: string) => Number(container.querySelector<HTMLInputElement>(sel)?.value ?? "0") / 100;
  try {
    await service().updateRoomGeometry(roomId, {
      posX: num("[data-room-geom='posX']"),
      posY: num("[data-room-geom='posY']"),
      width: num("[data-room-geom='width']"),
      height: num("[data-room-geom='height']"),
    });
  } catch (err) {
    alert((err as Error).message);
  }
  await renderPropertyStructure(container, caseId);
}

function readAssessment(container: HTMLElement): Record<string, string> {
  const out: Record<string, string> = {};
  container.querySelectorAll<HTMLSelectElement | HTMLTextAreaElement>("[data-assess]").forEach((el) => {
    out[el.dataset.assess ?? ""] = el.value;
  });
  return out;
}

function zoomView(view: [number, number, number, number], factor: number): [number, number, number, number] {
  const w = Math.max(10, Math.min(100, view[2] * factor));
  const h = Math.max(10, Math.min(100, view[3] * factor));
  const x = Math.max(0, Math.min(100 - w, view[0] + (view[2] - w) / 2));
  const y = Math.max(0, Math.min(100 - h, view[1] + (view[3] - h) / 2));
  return [x, y, w, h];
}
