/**
 * Case Hub equipment readings — TPI-V2-WEB-013.
 *
 * Original references:
 *   Cases/CaseDetailView.swift — CaseEMFReadingsView, CaseMotionReadingsView,
 *   CaseNoiseReadingsView, CaseAudioReadingsView.
 *
 * The original screens are case-scoped, read-only feeds. This browser view
 * preserves that hierarchy: case header, session/room context controls, and
 * one card per existing record. It reuses the authoritative schema-v11 stores:
 * environmentMeasurements for EMF/motion/noise and original audio evidence for
 * Audio Readings.
 *
 * This module never creates a measurement or evidence record. Opening a screen,
 * changing a filter, previewing audio, or verifying a hash is a read operation.
 * It never advances a phase, changes a checklist, unlocks review, or produces a
 * paranormal conclusion.
 */
import "./casehub.css";
import { getDb } from "../../core/db";
import { CaseRepository } from "../../core/repositories/caseRepository";
import { EvidenceRepository } from "../../core/repositories/evidenceRepository";
import { MeasurementService, MEASUREMENT_TYPE_LABELS } from "../../core/environment/measurementService";
import type {
  AcquisitionMethod,
  EnvironmentMeasurementRecord,
  EvidenceRecord,
  InvestigationSessionRecord,
  MeasurementType,
  RoomRecord,
} from "../../core/types";
import { esc, viewShell, wireBackButton } from "../dashboard/shell";
import { invalidateView, mountView, onDelegate } from "../../shared/uidom";
import { renderCaseHub } from "./CaseHub";

const db = () => getDb();

export type EquipmentReadingKind = "emf" | "motion" | "noise" | "audio";

interface ReadingDefinition {
  kind: EquipmentReadingKind;
  title: string;
  subtitle: string;
  measurementType?: MeasurementType;
  emptyTitle: string;
  emptyDetail: string;
  technicalNote: string;
}

