/**
 * Read-only Claims Viewer (TPI-V2-WEB-C6B).
 *
 * ORIGINAL SOURCES:
 *   Cases/HauntedClaimsListView.swift — case-scoped list, reference badge,
 *   room labels, no-claims state and createdAt-ascending order.
 *   Cases/CaseInvestigationSummaryView.swift — compact claims presentation and
 *   reference/investigator counts inside the Investigation Summary.
 *
 * This browser surface is deliberately read-only. It reads ClaimRepository
 * data through the caller, never writes a claim, and never creates evidence,
 * observations, reviews, checklist changes, phase changes or completion state.
 * A claim is reported information; its classification is the stored claim mark,
 * not a scientific finding or an observation record.
 */
import type { ClaimRecord, RoomRecord } from "../../core/types";
import { esc } from "../dashboard/shell";
import { onDelegate } from "../../shared/uidom";

export interface ClaimsViewerData {
  claims: ClaimRecord[];
  rooms: RoomRecord[];
  locationNames: ReadonlyMap<string, string>;
  caseLocationName: string | null;
}

const CLASSIFICATION_FILTERS: ReadonlyArray<{ value: string; label: string }> = [
  { value: "all", label: "All classifications" },
  { value: "Client Reported", label: "Client Reported" },
  { value: "Witness Reported", label: "Witness Reported" },
  { value: "Investigator Observed", label: "Investigator Observed" },
];

const IMPORT_SOURCE_LABEL: Record<string, string> = {
  referenceLocation: "Reference location",
  manual: "Manual source",
  external: "External source",
};

function missing(text = "Not recorded"): string {
  return `<span class="claims-missing">${esc(text)}</span>`;
}

function valueOr(value: string | null | undefined, fallback = "Not recorded"): string {
  return value && value.trim().length > 0 ? esc(value) : missing(fallback);
}

function timeOr(ms: number | null | undefined, fallback = "Not recorded"): string {
  return ms !== null && ms !== undefined && Number.isFinite(ms) ? esc(new Date(ms).toLocaleString()) : missing(fallback);
}

function fact(label: string, value: string): string {
  return `<div class="claims-fact"><dt>${esc(label)}</dt><dd>${value}</dd></div>`;
}

function textBlock(label: string, value: string | null | undefined, missingText: string): string {
  return `<div class="claims-text-block">
    <h5>${esc(label)}</h5>
    ${value && value.trim().length > 0
      ? `<p class="claims-original-text">${esc(value)}</p>`
      : `<p class="cc-meta">${esc(missingText)}</p>`}
  </div>`;
}

function isImported(claim: ClaimRecord): boolean {
  return (
    claim.importedFromReference ||
    claim.importSourceType !== null ||
    claim.importIdentity !== null ||
    claim.importedAt !== null
  );
}

function importLabel(claim: ClaimRecord): string {
  if (claim.importedFromReference) return "Reference-imported";
  if (isImported(claim)) return "Imported";
  return "Locally recorded";
}

function roomIds(claim: ClaimRecord): string[] {
  return [...new Set([claim.roomID, ...claim.linkedRoomIds].filter((id): id is string => Boolean(id)))];
}

function roomLabels(claim: ClaimRecord, roomById: ReadonlyMap<string, RoomRecord>): string[] {
  const labels = roomIds(claim).map(
    (id) => roomById.get(id)?.name ?? `Unresolved room reference (${id})`,
  );
  if (labels.length > 0) return labels;
  if (claim.roomTBD) return ["Room assignment marked TBD"];
  if (claim.roomName.trim().length > 0) return [claim.roomName];
  return ["No room association recorded"];
}

function locationLabel(claim: ClaimRecord, data: ClaimsViewerData): string {
  if (claim.locationId) {
    return data.locationNames.get(claim.locationId) ?? `Unresolved location reference (${claim.locationId})`;
  }
  if (data.caseLocationName) {
    return `No claim-specific location; case location: ${data.caseLocationName}`;
  }
  return "No location recorded";
}

function witnessSummary(claim: ClaimRecord): string {
  if (claim.witnessesText.trim().length > 0) return claim.witnessesText;
  if (claim.witnessCount > 0) return `${claim.witnessCount} witness(es) recorded`;
  return "Witness not recorded";
}

function occurrenceSummary(claim: ClaimRecord): string {
  if (claim.sourceOccurrenceAt !== null) return `Source occurrence: ${new Date(claim.sourceOccurrenceAt).toLocaleString()}`;
  if (claim.firstOccurrenceText.trim().length > 0) return claim.firstOccurrenceText;
  if (claim.mostRecentOccurrenceText.trim().length > 0) return claim.mostRecentOccurrenceText;
  return "Occurrence date/time not recorded";
}

function classificationRole(claim: ClaimRecord): string {
  return claim.classification === "Investigator Observed"
    ? "Stored claim classification: Investigator Observed. This is a claim mark, not an observation record, evidence record or scientific finding."
    : "Stored claim classification: a client- or witness-reported statement. It is not verified and is not an investigator observation.";
}

function detailHtml(claim: ClaimRecord, data: ClaimsViewerData, roomById: ReadonlyMap<string, RoomRecord>): string {
  const rooms = roomLabels(claim, roomById);
  const imported = isImported(claim);
  const sourceType = claim.importSourceType
    ? IMPORT_SOURCE_LABEL[claim.importSourceType] ?? claim.importSourceType
    : "Not recorded";
  const weather = claim.weatherCorrelation
    ? `Marked weather correlation${claim.weatherPattern.trim() ? `: ${claim.weatherPattern}` : ""}`
    : "No weather correlation marked in the record";
  const mostRecentKnown =
    claim.mostRecentOccurrenceKnown === null
      ? "Not recorded"
      : claim.mostRecentOccurrenceKnown
        ? "Marked known"
        : "Marked not known";
  const emotionalImpact =
    claim.emotionalImpact > 0 ? `${claim.emotionalImpact} (recorded scale value)` : "Not recorded";
  const witnessMembers = claim.witnessMemberIds.length
    ? `${claim.witnessMemberIds.length} linked member reference(s); member directory is not available in this browser`
    : "None recorded";

  return `<article class="claims-detail" id="claim-detail-${esc(claim.id)}" data-claim-detail="${esc(claim.id)}" aria-labelledby="claim-title-${esc(claim.id)}">
    <div class="claims-detail-head">
      <div>
        <span class="claims-eyebrow">Claim detail</span>
        <h4 id="claim-title-${esc(claim.id)}">${valueOr(claim.title, "Untitled claim")}</h4>
      </div>
      <span class="claims-badge claims-badge-classification">${esc(claim.classification)}</span>
    </div>
    <p class="claims-classification-role">${esc(classificationRole(claim))}</p>

    <h5 class="claims-group-title">Claim identity</h5>
    <dl class="claims-facts">
      ${fact("Claim identifier", valueOr(claim.claimID))}
      ${fact("Classification", esc(claim.classification))}
      ${fact("Classification marked resolved", claim.classificationResolved ? "Yes" : "No")}
      ${fact("Created", timeOr(claim.createdAt))}
      ${fact("Last updated", timeOr(claim.updatedAt))}
    </dl>

    <h5 class="claims-group-title">Reported occurrence</h5>
    <dl class="claims-facts">
      ${fact("Claim type", valueOr(claim.claimTypeOtherText || claim.claimType))}
      ${fact("Occurrence level", valueOr(claim.occurrenceLevel))}
      ${fact("Reported frequency", valueOr(claim.frequency))}
      ${fact("Time pattern", valueOr(claim.timePattern))}
      ${fact("Weather context", esc(weather))}
      ${fact("Most recent occurrence", esc(mostRecentKnown))}
    </dl>
    ${textBlock("Original reported statement", claim.sourceText, "No separate source statement recorded.")}
    ${textBlock("Source occurrence text", claim.sourceOccurrenceText, "No source occurrence text recorded.")}
    ${textBlock("First occurrence text", claim.firstOccurrenceText, "No first-occurrence text recorded.")}
    ${textBlock("Most recent occurrence text", claim.mostRecentOccurrenceText, "No most-recent-occurrence text recorded.")}
    <dl class="claims-facts">
      ${fact("Source occurrence timestamp", timeOr(claim.sourceOccurrenceAt, "No occurrence timestamp recorded"))}
    </dl>

    <h5 class="claims-group-title">Witness information</h5>
    <dl class="claims-facts">
      ${fact("Witness count", claim.witnessCount > 0 ? `${claim.witnessCount}${claim.witnessCountResolved ? " (marked resolved)" : " (not marked resolved)"}` : "Not recorded")}
      ${fact("Witness member references", esc(witnessMembers))}
      ${fact("Emotional impact", esc(emotionalImpact))}
      ${fact("Emotional impact marked resolved", claim.emotionalImpactResolved ? "Yes" : "No")}
    </dl>
    ${textBlock("Witness name or source text", claim.witnessesText, "No witness attribution or statement recorded.")}
    ${textBlock("Recorded feeling", claim.feelingText, "No feeling text recorded.")}
    ${textBlock("Feeling notes", claim.feelingNotes, "No feeling notes recorded.")}

    <h5 class="claims-group-title">Investigation context</h5>
    <dl class="claims-facts">
      ${fact("Location", esc(locationLabel(claim, data)))}
      ${fact("Room / area", rooms.map((room) => esc(room)).join("<br>"))}
      ${fact("Room marked TBD", claim.roomTBD ? "Yes" : "No")}
      ${fact("Walkthrough status", esc(claim.walkthroughStatus))}
      ${fact("Linked pin identifier", claim.linkedPinID ? `${esc(claim.linkedPinID)} <span class="cc-meta">(reference not validated in this viewer)</span>` : missing())}
      ${fact("Guided draft", claim.isGuidedDraft ? "Yes" : "No")}
    </dl>
    ${textBlock("Investigator notes", claim.notes, "No investigator notes recorded.")}
    <p class="cc-meta claims-note-label">Investigator notes are shown as stored. They are not rewritten, promoted to evidence or presented as a conclusion.</p>

    <h5 class="claims-group-title">Import provenance</h5>
    <dl class="claims-facts">
      ${fact("Record origin", esc(imported ? importLabel(claim) : "Locally recorded"))}
      ${fact("Imported from reference", claim.importedFromReference ? "Yes" : "No")}
      ${fact("Source type", esc(sourceType))}
      ${fact("Source reference", valueOr(claim.importSourceRef))}
      ${fact("Original source claim identifier", valueOr(claim.importSourceClaimId))}
      ${fact("Import timestamp", timeOr(claim.importedAt, "No import timestamp recorded"))}
      ${fact("Source text hash", valueOr(claim.sourceTextHash))}
    </dl>
    ${textBlock("Original source text", claim.sourceText, "No original source text recorded.")}
    ${textBlock("Source occurrence text", claim.sourceOccurrenceText, "No source occurrence text recorded.")}
    <dl class="claims-facts">
      ${fact("Source occurrence timestamp", timeOr(claim.sourceOccurrenceAt, "No source occurrence timestamp recorded"))}
    </dl>
    ${imported
      ? `<p class="cc-meta" data-claim-provenance-note>Imported provenance is displayed as stored. The viewer does not import, merge, repair or reclassify this claim.</p>`
      : `<p class="cc-meta" data-claim-provenance-note>This claim has no import provenance. It is a locally recorded claim.</p>`}
  </article>`;
}

function listItemHtml(
  claim: ClaimRecord,
  data: ClaimsViewerData,
  roomById: ReadonlyMap<string, RoomRecord>,
  selected: boolean,
): string {
  const rooms = roomLabels(claim, roomById);
  return `<li class="claims-list-item" data-claim-item data-claim-id="${esc(claim.id)}"
      data-claim-classification="${esc(claim.classification)}"
      data-claim-room-ids="${esc(roomIds(claim).join(" "))}"
      data-claim-created-at="${claim.createdAt}"
      data-claim-title-key="${esc(claim.title.toLocaleLowerCase())}">
    <button class="claims-list-button" type="button" data-claim-select="${esc(claim.id)}"
      aria-pressed="${selected ? "true" : "false"}" aria-controls="claim-detail-${esc(claim.id)}">
      <span class="claims-list-head">
        <strong>${valueOr(claim.title, "Untitled claim")}</strong>
        <span class="claims-badge claims-badge-classification">${esc(claim.classification)}</span>
        <span class="claims-badge claims-badge-origin">${esc(importLabel(claim))}</span>
      </span>
      <span class="claims-list-meta">Witness: ${esc(witnessSummary(claim))}</span>
      <span class="claims-list-meta">Location: ${esc(locationLabel(claim, data))}</span>
      <span class="claims-list-meta">Room: ${rooms.map((room) => esc(room)).join(" · ")}</span>
      <span class="claims-list-meta">Occurrence: ${esc(occurrenceSummary(claim))}</span>
      <span class="claims-list-meta">Created: ${timeOr(claim.createdAt)} · Walkthrough: ${esc(claim.walkthroughStatus)}</span>
    </button>
  </li>`;
}

export function claimsViewerHtml(data: ClaimsViewerData): string {
  const claims = [...data.claims].sort(
    (a, b) => a.createdAt - b.createdAt || a.claimID.localeCompare(b.claimID),
  );
  const roomById = new Map(data.rooms.map((room) => [room.id, room]));
  const importedCount = claims.filter(isImported).length;
  const investigatorCount = claims.filter((claim) => claim.classification === "Investigator Observed").length;
  const reportedCount = claims.length - investigatorCount;

  if (claims.length === 0) {
    return `<div class="claims-viewer" data-claims-viewer data-claims-total="${claims.length}">
      <p class="claims-safeguard" data-claims-safeguard><strong>Reported information only.</strong>
        Claims are statements recorded by clients, witnesses or investigators. A claim is not evidence,
        not an observation record and not a paranormal conclusion.</p>
      <p class="cc-count" data-claims-total-count>0 claims recorded for this case.</p>
      <p class="cc-empty" data-claims-empty="true">No claims have been recorded for this case.</p>
    </div>`;
  }

  const roomFilterLabels = new Map<string, string>();
  for (const claim of claims) {
    for (const id of roomIds(claim)) {
      const label = roomById.get(id)?.name ?? `Unresolved room reference (${id})`;
      roomFilterLabels.set(id, label);
    }
  }
  const roomFilters = [...roomFilterLabels.entries()].sort((a, b) => a[1].localeCompare(b[1]));

  return `<div class="claims-viewer" data-claims-viewer data-claims-total="${claims.length}">
    <p class="claims-safeguard" data-claims-safeguard><strong>Reported information only.</strong>
      Claims are statements recorded by clients, witnesses or investigators. A claim is not evidence,
      not an observation record and not a paranormal conclusion. The classification shown is the stored
      claim mark; it does not verify the statement. <strong>Investigator Observed</strong> is a claim
      classification, not an observation record.</p>

    <p class="cc-count" data-claims-total-count>${claims.length} claim(s) recorded · ${reportedCount} client/witness-reported ·
      ${investigatorCount} investigator-marked · ${importedCount} imported</p>

    <div class="claims-controls" data-claims-controls>
      <div class="claims-control-group" role="group" aria-label="Filter claims by classification">
        <span class="claims-control-label">Classification</span>
        ${CLASSIFICATION_FILTERS.map(
          (filter) => `<button class="claims-filter${filter.value === "all" ? " is-active" : ""}" type="button"
            data-claim-filter-classification="${esc(filter.value)}"
            aria-pressed="${filter.value === "all" ? "true" : "false"}">${esc(filter.label)}</button>`,
        ).join("")}
      </div>
      <div class="claims-control-group" role="group" aria-label="Filter claims by room or area">
        <span class="claims-control-label">Room / area</span>
        <button class="claims-filter is-active" type="button" data-claim-filter-room="all" aria-pressed="true">All rooms</button>
        ${roomFilters.map(
          ([id, label]) => `<button class="claims-filter" type="button" data-claim-filter-room="${esc(id)}"
            aria-pressed="false">${esc(label)}</button>`,
        ).join("")}
      </div>
      <div class="claims-control-group" role="group" aria-label="Sort claims">
        <span class="claims-control-label">Sort</span>
        ${[
          ["oldest", "Oldest first"],
          ["newest", "Newest first"],
          ["title", "Title A–Z"],
        ].map(
          ([value, label]) => `<button class="claims-filter${value === "oldest" ? " is-active" : ""}" type="button"
            data-claim-sort="${value}" aria-pressed="${value === "oldest" ? "true" : "false"}">${label}</button>`,
        ).join("")}
      </div>
    </div>

    <p class="cc-meta claims-visible-count" data-claims-visible-count aria-live="polite">Showing ${claims.length} of ${claims.length} claims.</p>
    <p class="cc-empty" data-claims-no-match hidden>No claims match the selected filters.</p>

    <div class="claims-layout">
      <div class="claims-list-pane">
        <h4 class="claims-pane-title">Claims</h4>
        <ul class="claims-list" data-claims-list>
          ${claims.map((claim, index) => listItemHtml(claim, data, roomById, index === 0)).join("")}
        </ul>
      </div>
      <div class="claims-detail-pane" data-claims-detail-region>
        <h4 class="claims-pane-title">Claim detail</h4>
        ${claims.map((claim, index) => detailHtml(claim, data, roomById).replace(
          'class="claims-detail"',
          `class="claims-detail"${index === 0 ? "" : " hidden"}`,
        )).join("")}
      </div>
    </div>
  </div>`;
}

function pressedValue(container: HTMLElement, attribute: string, fallback: string): string {
  const active = container.querySelector<HTMLElement>(`[${attribute}][aria-pressed="true"]`);
  return active?.getAttribute(attribute) ?? fallback;
}

function selectClaim(container: HTMLElement, id: string): void {
  container.querySelectorAll<HTMLElement>("[data-claim-select]").forEach((button) => {
    const selected = button.dataset.claimSelect === id;
    button.setAttribute("aria-pressed", String(selected));
    button.classList.toggle("is-selected", selected);
  });
  container.querySelectorAll<HTMLElement>("[data-claim-detail]").forEach((detail) => {
    detail.hidden = detail.dataset.claimDetail !== id;
  });
}

function applyClaimsView(container: HTMLElement): void {
  const root = container.querySelector<HTMLElement>("[data-claims-viewer]");
  if (!root) return;
  const classification = pressedValue(root, "data-claim-filter-classification", "all");
  const room = pressedValue(root, "data-claim-filter-room", "all");
  const sort = pressedValue(root, "data-claim-sort", "oldest");
  const items = [...root.querySelectorAll<HTMLElement>("[data-claim-item]")];
  let visible = 0;
  let firstVisible: HTMLElement | null = null;
  for (const item of items) {
    const ids = (item.dataset.claimRoomIds ?? "").split(/\s+/).filter(Boolean);
    const matches =
      (classification === "all" || item.dataset.claimClassification === classification) &&
      (room === "all" || ids.includes(room));
    item.hidden = !matches;
    if (matches) {
      visible += 1;
      if (!firstVisible) firstVisible = item;
    }
  }

  const list = root.querySelector<HTMLElement>("[data-claims-list]");
  if (list) {
    const sorted = [...items].sort((a, b) => {
      if (sort === "title") {
        return (a.dataset.claimTitleKey ?? "").localeCompare(b.dataset.claimTitleKey ?? "");
      }
      const aTime = Number(a.dataset.claimCreatedAt ?? 0);
      const bTime = Number(b.dataset.claimCreatedAt ?? 0);
      return sort === "newest" ? bTime - aTime : aTime - bTime;
    });
    for (const item of sorted) list.append(item);
  }

  const selected = root.querySelector<HTMLElement>('[data-claim-select][aria-pressed="true"]');
  const selectedId = selected?.dataset.claimSelect;
  const selectedVisible = selectedId
    ? items.some((item) => item.dataset.claimId === selectedId && !item.hidden)
    : false;
  if (!selectedVisible) {
    if (firstVisible?.dataset.claimId) selectClaim(container, firstVisible.dataset.claimId);
    else {
      root.querySelectorAll<HTMLElement>("[data-claim-detail]").forEach((detail) => {
        detail.hidden = true;
      });
    }
  }

  const count = root.querySelector<HTMLElement>("[data-claims-visible-count]");
  if (count) count.textContent = `Showing ${visible} of ${items.length} claims.`;
  const noMatch = root.querySelector<HTMLElement>("[data-claims-no-match]");
  if (noMatch) noMatch.hidden = visible !== 0;
}

function setPressed(container: HTMLElement, selector: string, active: HTMLElement): void {
  container.querySelectorAll<HTMLElement>(selector).forEach((button) => {
    const on = button === active;
    button.setAttribute("aria-pressed", String(on));
    button.classList.toggle("is-active", on);
  });
}

/** Bind once per container through the C1H delegated-handler contract. */
export function wireClaimsViewer(container: HTMLElement): void {
  onDelegate(container, "click", "[data-claim-select]", (button) => {
    const id = button.dataset.claimSelect;
    if (id && !button.closest("[hidden]")) selectClaim(container, id);
  });
  onDelegate(container, "click", "[data-claim-filter-classification]", (button) => {
    setPressed(container, "[data-claim-filter-classification]", button);
    applyClaimsView(container);
  });
  onDelegate(container, "click", "[data-claim-filter-room]", (button) => {
    setPressed(container, "[data-claim-filter-room]", button);
    applyClaimsView(container);
  });
  onDelegate(container, "click", "[data-claim-sort]", (button) => {
    setPressed(container, "[data-claim-sort]", button);
    applyClaimsView(container);
  });
}
