/**
 * Connectivity status service (TPI-V2-WEB-008 §15).
 *
 * Honest distinction between:
 *  - `browserReported`: what `navigator.onLine` claims (a hint, not proof of
 *    reachability);
 *  - `verified`: an explicit, on-demand reachability probe — only reported when
 *    the investigator or a feature actually ran one;
 *  - `offline`: the browser reports no connection.
 *
 * No background network requests are made: verification only runs when
 * explicitly requested.
 */
export type ConnectivityState = "online" | "offline" | "unknown";
export type ReachabilityState = "notTested" | "reachable" | "unreachable";

export interface ConnectivityStatus {
  browserReported: ConnectivityState;
  reachability: ReachabilityState;
  /** Timestamp of the last explicit verification, if any. */
  verifiedAt: number | null;
  /** Detail for the last verification attempt (no URLs beyond the origin). */
  detail: string;
}

export class ConnectivityService {
  private reachability: ReachabilityState = "notTested";
  private verifiedAt: number | null = null;
  private detail = "";
  private listeners = new Set<(status: ConnectivityStatus) => void>();
  private bound = false;

  getStatus(): ConnectivityStatus {
    return {
      browserReported: typeof navigator === "undefined" ? "unknown" : navigator.onLine ? "online" : "offline",
      reachability: this.reachability,
      verifiedAt: this.verifiedAt,
      detail: this.detail,
    };
  }

  /** Attach browser online/offline listeners once. */
  watch(): void {
    if (this.bound || typeof window === "undefined") return;
    this.bound = true;
    window.addEventListener("online", () => this.emit());
    window.addEventListener("offline", () => {
      // A browser-reported offline event invalidates any previous verification.
      this.reachability = "unreachable";
      this.detail = "The browser reported that the connection was lost.";
      this.emit();
    });
  }

  subscribe(fn: (status: ConnectivityStatus) => void): () => void {
    this.listeners.add(fn);
    fn(this.getStatus());
    return () => this.listeners.delete(fn);
  }

  private emit(): void {
    const status = this.getStatus();
    for (const fn of this.listeners) fn(status);
  }

  /**
   * Explicit reachability verification. Never runs automatically — a network
   * request is only issued when a caller asks for it (WP-6 §15).
   */
  async verify(timeoutMs = 4000): Promise<ConnectivityStatus> {
    if (typeof fetch === "undefined" || typeof navigator === "undefined" || !navigator.onLine) {
      this.reachability = "unreachable";
      this.verifiedAt = Date.now();
      this.detail = "Not verified: the browser reports no connection.";
      this.emit();
      return this.getStatus();
    }
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeoutMs);
    try {
      // Same-origin HEAD of the app shell only — no third-party endpoints.
      const res = await fetch("/", { method: "HEAD", cache: "no-store", signal: controller.signal });
      this.reachability = res.ok ? "reachable" : "unreachable";
      this.detail = res.ok ? "The application shell was reachable." : `Reachability probe returned HTTP ${res.status}.`;
    } catch {
      this.reachability = "unreachable";
      this.detail = "Reachability probe failed (no response within the timeout).";
    } finally {
      clearTimeout(timer);
    }
    this.verifiedAt = Date.now();
    this.emit();
    return this.getStatus();
  }
}

let instance: ConnectivityService | undefined;
export function getConnectivity(): ConnectivityService {
  instance ??= new ConnectivityService();
  instance.watch();
  return instance;
}
export function setConnectivityForTesting(svc: ConnectivityService | undefined): void {
  instance = svc;
}
