/**
 * Versioned local database (Dexie over IndexedDB).
 *
 * TPI-V2-WEB-003 — SCHEMA VERSION 2.
 * Database name: tpi-core.
 *
 * Migration safety: the runtime migration framework (core/data/migrations.ts)
 * exports a verified snapshot to OPFS *before* any upgrade is applied, then
 * validates the result afterwards. See docs/DATA_MIGRATION_STRATEGY.md.
 *
 * All access to investigation records must go through the repository/service
 * modules in src/core — UI components must not implement their own DB logic.
 */
import Dexie, { type Table } from "dexie";
import { v4 as uuidv4 } from "../shared/uuid";
import type {
  AuditEventRecord,
  CaseClosureRecord,
  CaseRecord,
  CaseReportRecord,
  CaseReportRevisionRecord,
  ChecklistItemRecord,
  ClaimRecord,
  ClientRecord,
  EvidenceRecord,
  InvestigationNoteRecord,
  InvestigationSessionRecord,
  LocationRecord,
  RoomSummaryRecord,
  EnvironmentalReadingRecord,
  ObservationRecord,
} from "./types";

export const DATABASE_NAME = "tpi-core";

/** The schema version implemented by THIS build of the application. */
export const SCHEMA_VERSION = 14;
export const WORKFLOW_PHASE_COUNT = 9;

export interface AppMetaRecord {
  key: "schemaVersion" | "lastBackupAt";
  value: string;
}

export class TPIDatabase extends Dexie {
  cases!: Table<CaseRecord, string>;
  clients!: Table<ClientRecord, string>;
  locations!: Table<LocationRecord, string>;
  sessions!: Table<InvestigationSessionRecord, string>;
  evidence!: Table<EvidenceRecord, string>;
  environmentReadings!: Table<EnvironmentalReadingRecord, string>;
  observations!: Table<ObservationRecord, string>;
  checklistItems!: Table<ChecklistItemRecord, string>;
  documentInstances!: Table<import("./types").DocumentInstanceRecord, string>;
  documentVersions!: Table<import("./types").DocumentVersionRecord, string>;
  documentSignatures!: Table<import("./types").SignatureRecord, string>;
  intakeDossiers!: Table<import("./types").IntakeDossierRecord, string>;
  intakeResponses!: Table<import("./types").IntakeResponseRecord, string>;
  propertyStructures!: Table<import("./types").PropertyStructureRecord, string>;
  structureFloors!: Table<import("./types").FloorRecord, string>;
  structureZones!: Table<import("./types").ZoneRecord, string>;
  structureRooms!: Table<import("./types").RoomRecord, string>;
  roomLayoutElements!: Table<import("./types").RoomLayoutElementRecord, string>;
  structureMarkers!: Table<import("./types").StructureMarkerRecord, string>;
  walkthroughSessions!: Table<import("./types").WalkthroughSessionRecord, string>;
  walkthroughObservations!: Table<import("./types").WalkthroughObservationRecord, string>;
  sessionEvents!: Table<import("./types").SessionEventRecord, string>;
  baselineRecords!: Table<import("./types").BaselineRecord, string>;
  environmentMeasurements!: Table<import("./types").EnvironmentMeasurementRecord, string>;
  evidenceAnnotations!: Table<import("./types").EvidenceAnnotationRecord, string>;
  evidenceReviews!: Table<import("./types").EvidenceReviewRecord, string>;
  evidenceImports!: Table<import("./types").EvidenceImportRecord, string>;
  intakeAttachments!: Table<import("./types").IntakeAttachmentRecord, string>;
  claims!: Table<ClaimRecord, string>;
  investigationNotes!: Table<InvestigationNoteRecord, string>;
  roomSummaries!: Table<RoomSummaryRecord, string>;
  caseReports!: Table<CaseReportRecord, string>;
  caseReportRevisions!: Table<CaseReportRevisionRecord, string>;
  caseClosures!: Table<CaseClosureRecord, string>;
  auditEvents!: Table<AuditEventRecord, string>;
  appMeta!: Table<AppMetaRecord, string>;

  constructor() {
    super(DATABASE_NAME);
    this.version(1).stores({
      cases: "id, caseNumber, status, currentPhase, investigationType, updatedAt",
      auditEvents: "id, caseId, type, createdAt",
    });
    this.version(2)
      .upgrade((tx) => upgradeV1ToV2(tx))
      .stores({
        cases: "id, caseNumber, status, currentPhase, investigationType, updatedAt, clientId, locationId, isClosed",
        clients: "id, caseId, fullName, createdAt",
        locations: "id, caseId, name, createdAt",
        sessions: "id, caseId, startedAt, status",
        evidence: "id, caseId, sessionId, kind, acquisition, parentId, createdAt",
        environmentReadings: "id, caseId, sessionId, createdAt",
        observations: "id, caseId, sessionId, roomName, createdAt",
        auditEvents: "id, caseId, type, createdAt, affectedRecordId",
        appMeta: "key",
      });
    this.version(3)
      .upgrade((tx) => upgradeV2ToV3(tx))
      .stores({
        // v3: locations are reusable across cases — association is held by
        // cases.locationId; the location's own caseId is an optional origin.
        locations: "id, name, createdAt",
      });
    this.version(4)
      .upgrade(() => undefined) // index-only change
      .stores({
        cases: "id, caseNumber, status, currentPhase, investigationType, updatedAt, clientId, locationId, isClosed, title",
      });
    this.version(5)
      .upgrade((tx) => upgradeV4ToV5(tx))
      .stores({
        cases: "id, caseNumber, status, currentPhase, investigationType, updatedAt, clientId, locationId, isClosed, title",
        checklistItems: "id, caseId, phase, definitionId, status, required",
      });
    this.version(6)
      .upgrade((tx) => upgradeV5ToV6(tx))
      .stores({
        // v6 (TPI-V2-WEB-006): Documents Center, signatures, guided intake.
        documentInstances: "id, caseId, templateId, status, updatedAt",
        documentVersions: "id, documentId, caseId, versionNumber",
        documentSignatures: "id, documentId, caseId, signedAt",
        intakeDossiers: "id, caseId, status, updatedAt",
        intakeResponses: "id, caseId, questionId, updatedAt",
      });
    this.version(7)
      .upgrade((tx) => upgradeV6ToV7(tx))
      .stores({
        // v7 (TPI-V2-WEB-007): property structure, room builder, walkthrough.
        propertyStructures: "id, caseId, locationId, updatedAt",
        structureFloors: "id, structureId, caseId, orderIndex",
        structureZones: "id, structureId, caseId, orderIndex",
        structureRooms: "id, structureId, floorId, zoneId, caseId, assessmentStatus, updatedAt",
        roomLayoutElements: "id, roomId, caseId",
        structureMarkers: "id, caseId, roomId, floorId, markerType",
        walkthroughSessions: "id, caseId, status, startedAt",
        walkthroughObservations: "id, caseId, sessionId, roomId, createdAt",
      });
    this.version(8)
      .upgrade((tx) => upgradeV7ToV8(tx))
      .stores({
        // v8 (TPI-V2-WEB-008): session events, baselines, measurements.
        sessions: "id, caseId, startedAt, status",
        sessionEvents: "id, caseId, sessionId, at, type",
        baselineRecords: "id, caseId, roomId, sessionId, structureId, updatedAt",
        environmentMeasurements: "id, caseId, sessionId, roomId, measurementType, acquisition, at",
      });
    this.version(9)
      .upgrade((tx) => upgradeV8ToV9(tx))
      .stores({
        // v9 (TPI-V2-WEB-009): evidence annotations, reviews, import journal.
        evidence: "id, caseId, sessionId, kind, acquisition, parentId, createdAt, verificationStatus, roomId",
        evidenceAnnotations: "id, caseId, evidenceId, annotationType, createdAt",
        evidenceReviews: "id, caseId, evidenceId, status, at",
        evidenceImports: "id, caseId, stage, createdAt",
      });
    this.version(10)
      .upgrade((tx) => upgradeV9ToV10(tx))
      .stores({
        // v10 (TPI-V2-WEB-010G): intake research attachments (original model).
        intakeAttachments: "id, caseId, questionId, evidenceId, createdAt",
      });
    this.version(11)
      .upgrade((tx) => upgradeV10ToV11(tx))
      .stores({
        // v11 (TPI-V2-WEB-C6A): persistent reported claims (PPClaim port).
        // No existing store or index is changed. Claim ids are unique; import
        // identity is deterministic per case/source and unique when present.
        claims:
          "id, caseId, &claimID, locationId, roomID, classification, &importIdentity, importedFromReference, createdAt, updatedAt, *linkedRoomIds",
      });
    this.version(12)
      .upgrade((tx) => upgradeV11ToV12(tx))
      .stores({
        // v12 (TPI-V2-WEB-016): investigator-authored notes and per-room
        // summaries. Additive only — no existing store or index is changed.
        // The unique compound index is what makes a room summary deterministically
        // single-valued for one case/session/room combination.
        investigationNotes: "id, caseId, roomId, sessionId, kind, createdAt, updatedAt",
        roomSummaries:
          "id, caseId, sessionId, roomId, updatedAt, &[caseId+sessionId+roomId]",
      });
    this.version(13)
      .upgrade((tx) => upgradeV12ToV13(tx))
      .stores({
        // v13 (TPI-V2-WEB-019): persistent report drafts and immutable
        // revision snapshots. Additive only — no existing store or index is
        // changed. Unique compound indexes enforce one report per case/type
        // and one sequential revision number per report.
        caseReports:
          "id, caseId, reportType, status, updatedAt, &[caseId+reportType]",
        caseReportRevisions:
          "id, reportId, caseId, revisionNumber, finalizedAt, &[reportId+revisionNumber]",
      });
    this.version(14)
      .upgrade((tx) => upgradeV13ToV14(tx))
      .stores({
        // v14 (TPI-V2-WEB-020): historical closure events. Additive only —
        // caseReports and caseReportRevisions keep their exact v13 schema.
        // Reopening stamps the existing closure row; re-closing creates a new
        // row, so earlier closure records are never replaced.
        caseClosures: "id, caseId, closedAt, reopenedAt",
      });
  }
}

/**
 * v2 → v3 data upgrade: stamp record schemaVersion to 3. Locations gain
 * cross-case reuse (their caseId becomes an optional originating-case ref).
 */
export async function upgradeV2ToV3(tx: {
  table: (name: string) => Table<Record<string, unknown>, string>;
}): Promise<void> {
  for (const name of ["cases", "clients", "locations", "sessions", "evidence", "environmentReadings", "observations", "auditEvents"]) {
    await tx
      .table(name)
      .toCollection()
      .modify((record: Record<string, unknown>) => {
        record.schemaVersion = 3;
      });
  }
}

/**
 * v4 → v5 workflow upgrade:
 * - maps legacy 7-phase chains onto the canonical 9-phase chain
 *   (documents + investigationReady inserted per the iOS FrontHalf audit);
 * - seeds the canonical checklist for every existing case.
 * Legacy phases keep their meaning: intake→intake, walkthrough→walkthrough,
 * baseline→baseline, investigation→investigation, review→review, summary→summary.
 */
export async function upgradeV4ToV5(tx: {
  table: (name: string) => Table<Record<string, unknown>, string>;
}): Promise<void> {
  const LEGACY_PHASE_MAP: Record<string, string> = {
    caseCreation: "caseCreation",
    intake: "intake",
    walkthrough: "walkthrough",
    baseline: "baseline",
    investigation: "investigation",
    review: "review",
    summary: "summary",
  };
  const cases = tx.table("cases");
  const caseRows = await cases.toArray();
  const checklist = tx.table("checklistItems");
  for (const c of caseRows) {
    const legacyPhase = String(c["currentPhase"] ?? "caseCreation");
    const canonical = LEGACY_PHASE_MAP[legacyPhase] ?? "caseCreation";
    await cases.put({ ...c, currentPhase: canonical, schemaVersion: 5 });
    for (const item of seedChecklistForPhase(String(c["id"]), canonical)) {
      await checklist.add(item as unknown as Record<string, unknown>);
    }
  }
}

