/**
 * v7 → v8 session/baseline upgrade (TPI-V2-WEB-008):
 * - adds `sessionEvents`, `baselineRecords`, `environmentMeasurements`;
 * - stamps records to schemaVersion 8;
 * - backfills new session lifecycle fields with explicit defaults. Sessions
 *   that were left `active` by an earlier browser session are flagged
 *   `interrupted` so the runtime surfaces them for recovery instead of
 *   silently treating them as still running.
 */
export async function upgradeV7ToV8(tx: {
  table: (name: string) => Table<Record<string, unknown>, string>;
}): Promise<void> {
  // Tolerate legacy databases that predate some tables: an upgrade must never
  // fail merely because an unrelated table was never created.
  const modifyIfPresent = async (name: string, fn: (record: Record<string, unknown>) => void) => {
    try {
      await tx.table(name).toCollection().modify(fn);
    } catch {
      /* table absent in this legacy database — nothing to stamp */
    }
  };
  for (const name of [
    "cases",
    "clients",
    "locations",
    "evidence",
    "environmentReadings",
    "observations",
    "checklistItems",
    "auditEvents",
    "documentInstances",
    "documentVersions",
    "documentSignatures",
    "intakeDossiers",
    "intakeResponses",
    "propertyStructures",
    "structureFloors",
    "structureZones",
    "structureRooms",
    "roomLayoutElements",
    "structureMarkers",
    "walkthroughSessions",
    "walkthroughObservations",
    "sessionEvents",
    "baselineRecords",
    "environmentMeasurements",
  ]) {
    await modifyIfPresent(name, (record) => {
      record.schemaVersion = 8;
    });
  }
  await modifyIfPresent("sessions", (s) => {
    s.schemaVersion = 8;
    if (s.status === "active") {
      // Legacy active row from a closed browser — needs explicit recovery.
      s.interrupted = true;
    }
    if (s.pausedAt === undefined) s.pausedAt = null;
    if (s.resumedAt === undefined) s.resumedAt = null;
    if (s.pausedMs === undefined) s.pausedMs = 0;
    if (s.pauseReason === undefined) s.pauseReason = "";
    if (s.deviceLabel === undefined) s.deviceLabel = "";
    if (s.locationId === undefined) s.locationId = null;
    if (s.structureId === undefined) s.structureId = null;
    if (s.currentRoomId === undefined) s.currentRoomId = null;
    if (s.reviewedAt === undefined) s.reviewedAt = null;
    if (s.recoveredAt === undefined) s.recoveredAt = null;
  });
}

/**
 * v8 → v9 evidence upgrade (TPI-V2-WEB-009):
 * - adds `evidenceAnnotations`, `evidenceReviews`, `evidenceImports`;
 * - stamps records to schemaVersion 9;
 * - backfills evidence provenance/verification defaults. Existing evidence is
 *   marked `unverified` (never assumed verified) and receives its original
 *   filename/import timestamp from the values we can derive honestly.
 */
export async function upgradeV8ToV9(tx: {
  table: (name: string) => Table<Record<string, unknown>, string>;
}): Promise<void> {
  const modifyIfPresent = async (name: string, fn: (record: Record<string, unknown>) => void) => {
    try {
      await tx.table(name).toCollection().modify(fn);
    } catch {
      /* table absent in this legacy database */
    }
  };
  for (const name of [
    "cases",
    "clients",
    "locations",
    "sessions",
    "environmentReadings",
    "observations",
    "checklistItems",
    "auditEvents",
    "documentInstances",
    "documentVersions",
    "documentSignatures",
    "intakeDossiers",
    "intakeResponses",
    "propertyStructures",
    "structureFloors",
    "structureZones",
    "structureRooms",
    "roomLayoutElements",
    "structureMarkers",
    "walkthroughSessions",
    "walkthroughObservations",
    "sessionEvents",
    "baselineRecords",
    "environmentMeasurements",
  ]) {
    await modifyIfPresent(name, (record) => {
      record.schemaVersion = 9;
    });
  }
  await modifyIfPresent("evidence", (e) => {
    e.schemaVersion = 9;
    if (e.verificationStatus === undefined) e.verificationStatus = "unverified";
    if (e.verifiedAt === undefined) e.verifiedAt = null;
    if (e.importedAt === undefined) e.importedAt = e.createdAt ?? null;
    if (e.originalFileName === undefined) e.originalFileName = typeof e.fileName === "string" ? e.fileName : "";
    if (e.sourceDescription === undefined) e.sourceDescription = "";
    if (e.captureTimestamp === undefined) e.captureTimestamp = e.acquiredAt ?? null;
    if (e.captureTimestampSource === undefined) e.captureTimestampSource = "capture";
    if (e.captureTimezoneOffsetMinutes === undefined) e.captureTimezoneOffsetMinutes = null;
    if (e.roomId === undefined) e.roomId = null;
    if (e.locationId === undefined) e.locationId = null;
    if (e.observationId === undefined) e.observationId = null;
    if (e.markerId === undefined) e.markerId = null;
    if (e.measurementId === undefined) e.measurementId = null;
  });
}

