/**
 * v11 → v12 investigation-note / room-summary upgrade (TPI-V2-WEB-016):
 * - adds `investigationNotes` and `roomSummaries` (declared above);
 * - stamps every pre-existing record to schemaVersion 12;
 * - creates no note or summary, rewrites no evidence/claim/session record, and
 *   does not touch OPFS media. Existing v11 data is preserved byte-for-byte in
 *   its own fields; only the additive schemaVersion stamp changes.
 */
export async function upgradeV11ToV12(tx: {
  table: (name: string) => Table<Record<string, unknown>, string>;
}): Promise<void> {
  const modifyIfPresent = async (name: string, fn: (record: Record<string, unknown>) => void) => {
    try {
      await tx.table(name).toCollection().modify(fn);
    } catch {
      /* table absent in this legacy database */
    }
  };
  for (const name of [
    "cases", "clients", "locations", "sessions", "evidence", "environmentReadings",
    "observations", "checklistItems", "auditEvents", "documentInstances", "documentVersions",
    "documentSignatures", "intakeDossiers", "intakeResponses", "propertyStructures",
    "structureFloors", "structureZones", "structureRooms", "roomLayoutElements",
    "structureMarkers", "walkthroughSessions", "walkthroughObservations", "sessionEvents",
    "baselineRecords", "environmentMeasurements", "evidenceAnnotations", "evidenceReviews",
    "evidenceImports", "intakeAttachments", "claims",
  ]) {
    await modifyIfPresent(name, (record) => {
      record.schemaVersion = 12;
    });
  }
  // App-level version bookkeeping is part of the migration, not a data rewrite.
  try {
    await tx.table("appMeta").put({ key: "schemaVersion", value: "12" });
  } catch {
    /* appMeta absent in this legacy database */
  }
}

/**
 * v12 → v13 persisted-report upgrade (TPI-V2-WEB-019):
 * - adds `caseReports` and `caseReportRevisions` (declared above);
 * - stamps every pre-existing record to schemaVersion 13;
 * - creates no report, draft or revision and does not backfill any
 *   report-preview text into a finalized record;
 * - does not rewrite evidence, claims, notes, reviews, sessions, completion
 *   state or OPFS references beyond the additive version stamp.
 */
export async function upgradeV12ToV13(tx: {
  table: (name: string) => Table<Record<string, unknown>, string>;
}): Promise<void> {
  const modifyIfPresent = async (name: string, fn: (record: Record<string, unknown>) => void) => {
    try {
      await tx.table(name).toCollection().modify(fn);
    } catch (error) {
      // Ignore only a genuinely absent legacy table. Any write failure must
      // abort the upgrade so Dexie rolls back the migration transaction.
      if ((error as { name?: string }).name !== "NotFoundError") throw error;
    }
  };
  for (const name of [
    "cases", "clients", "locations", "sessions", "evidence", "environmentReadings",
    "observations", "checklistItems", "auditEvents", "documentInstances", "documentVersions",
    "documentSignatures", "intakeDossiers", "intakeResponses", "propertyStructures",
    "structureFloors", "structureZones", "structureRooms", "roomLayoutElements",
    "structureMarkers", "walkthroughSessions", "walkthroughObservations", "sessionEvents",
    "baselineRecords", "environmentMeasurements", "evidenceAnnotations", "evidenceReviews",
    "evidenceImports", "intakeAttachments", "claims", "investigationNotes", "roomSummaries",
  ]) {
    await modifyIfPresent(name, (record) => {
      record.schemaVersion = 13;
    });
  }
  try {
    await tx.table("appMeta").put({ key: "schemaVersion", value: "13" });
  } catch (error) {
    if ((error as { name?: string }).name !== "NotFoundError") throw error;
  }
}

/**
 * v13 → v14 closure-history upgrade (TPI-V2-WEB-020):
 * - adds only `caseClosures` (declared above);
 * - stamps every pre-existing record to schemaVersion 14;
 * - creates no closure row, report revision or evidence change;
 * - leaves existing `isClosed`/`closedAt` values untouched. Legacy closures
 *   without a historical row are recovered transparently only if reopened.
 */
export async function upgradeV13ToV14(tx: {
  table: (name: string) => Table<Record<string, unknown>, string>;
}): Promise<void> {
  const modifyIfPresent = async (name: string, fn: (record: Record<string, unknown>) => void) => {
    try {
      await tx.table(name).toCollection().modify(fn);
    } catch (error) {
      if ((error as { name?: string }).name !== "NotFoundError") throw error;
    }
  };
  for (const name of [
    "cases", "clients", "locations", "sessions", "evidence", "environmentReadings",
    "observations", "checklistItems", "auditEvents", "documentInstances", "documentVersions",
    "documentSignatures", "intakeDossiers", "intakeResponses", "propertyStructures",
    "structureFloors", "structureZones", "structureRooms", "roomLayoutElements",
    "structureMarkers", "walkthroughSessions", "walkthroughObservations", "sessionEvents",
    "baselineRecords", "environmentMeasurements", "evidenceAnnotations", "evidenceReviews",
    "evidenceImports", "intakeAttachments", "claims", "investigationNotes", "roomSummaries",
    "caseReports", "caseReportRevisions",
  ]) {
    await modifyIfPresent(name, (record) => {
      record.schemaVersion = 14;
    });
  }
  try {
    await tx.table("appMeta").put({ key: "schemaVersion", value: "14" });
  } catch (error) {
    if ((error as { name?: string }).name !== "NotFoundError") throw error;
  }
}

/** Canonical checklist rows seeded for a case at a given phase. */
function seedChecklistForPhase(
  caseId: string,
  currentPhase: string,
): Array<Record<string, unknown>> {
  return CANONICAL_CHECKLIST_ITEMS.filter(
    (d) => d.definitionId !== "caseCreated" || currentPhase !== "caseCreation",
  ).map((d) => ({
    id: globalThis.crypto.randomUUID(),
    schemaVersion: 5,
    createdAt: Date.now(),
    updatedAt: Date.now(),
    caseId,
    phase: d.phase,
    definitionId: d.definitionId,
    title: d.title,
    guidance: d.guidance,
    required: d.required,
    status: d.definitionId === "caseCreated" ? "complete" : "pending",
    completedAt: d.definitionId === "caseCreated" ? Date.now() : null,
    completedBy: d.definitionId === "caseCreated" ? "system" : null,
    notes: "",
  }));
}

/** Canonical checklist template (ported from iOS PPFrontHalfWorkflowChecklistItemID). */
const CANONICAL_CHECKLIST_ITEMS = [
  { definitionId: "caseCreated", phase: "caseCreation", title: "Case Created", guidance: "Create and activate a case file first.", required: true },
  { definitionId: "requiredDocumentsSigned", phase: "documents", title: "Required Documents Signed", guidance: "Required documents and signatures are complete.", required: true },
  { definitionId: "intakeComplete", phase: "intake", title: "Intake", guidance: "Intake cards are complete.", required: true },
  { definitionId: "walkthroughComplete", phase: "walkthrough", title: "Walkthrough", guidance: "Walkthrough is complete.", required: true },
  { definitionId: "baselineComplete", phase: "baseline", title: "Baseline Complete", guidance: "Baseline is complete.", required: true },
  { definitionId: "investigationReady", phase: "investigationReady", title: "Investigation Ready", guidance: "Front-half preparation is complete.", required: true },
  { definitionId: "evidenceReviewed", phase: "review", title: "Evidence Reviewed", guidance: "Imported evidence has been reviewed.", required: true },
] as const;

/**
 * v1 → v2 data upgrade: stamps existing case records with the new fields
 * (defaults) and bumps appMeta. Dexie runs this inside an upgrade transaction.
 */
export async function upgradeV1ToV2(tx: {
  table: (name: string) => Table<Record<string, unknown>, string>;
}): Promise<void> {
  const cases = tx.table("cases");
  await cases.toCollection().modify((caseRecord: Record<string, unknown>) => {
    caseRecord.schemaVersion = 2;
    if (caseRecord.isClosed === undefined) caseRecord.isClosed = false;
    if (caseRecord.closedAt === undefined) caseRecord.closedAt = null;
    if (caseRecord.archivedAt === undefined) caseRecord.archivedAt = null;
    if (caseRecord.archiveNote === undefined) caseRecord.archiveNote = "";
    if (caseRecord.clientId === undefined) caseRecord.clientId = null;
    if (caseRecord.locationId === undefined) caseRecord.locationId = null;
  });
}

let instance: TPIDatabase | undefined;

export function getDb(): TPIDatabase {
  instance ??= new TPIDatabase();
  return instance;
}

/** Test seam: inject/replace the singleton. */
export function setDbForTesting(db: TPIDatabase | undefined): void {
  instance = db;
}

export function now(): number {
  return Date.now();
}

export function nextCaseNumber(existing: number): string {
  const year = new Date().getFullYear();
  const serial = String(existing + 1).padStart(4, "0");
  return `TPI-${year}-${serial}`;
}

