/**
 * Case repository — the single write path for case records.
 * Enforces validation, controlled status transitions, timestamps, and audit.
 */
import type { TPIDatabase } from "../db";
import { now, nextCaseNumber, SCHEMA_VERSION } from "../db";
import { v4 as uuidv4 } from "../../shared/uuid";
import type {
  AuditEventType,
  CaseRecord,
  CaseStatus,
  InvestigationType,
  WorkflowPhase,
} from "../types";
import {
  ValidationError,
  assertCaseStatusTransition,
  assertReferenceExists,
  assertTimestampsMonotonic,
} from "../validation";
import { AuditService } from "../audit";
import { ChecklistService } from "../workflow/checklistService";

export type CasePatch = Partial<
  Pick<
    CaseRecord,
    | "title"
    | "clientName"
    | "phone"
    | "email"
    | "street"
    | "city"
    | "state"
    | "zip"
    | "notes"
    | "investigationType"
    | "currentPhase"
  >
>;

export class CaseRepository {
  private readonly audit: AuditService;

  constructor(private readonly db: TPIDatabase) {
    this.audit = new AuditService(db);
  }

  async createCase(
    input: Pick<CaseRecord, "title" | "investigationType"> & {
      clientName?: string;
      notes?: string;
    },
  ): Promise<CaseRecord> {
    if (!input.title?.trim()) {
      throw new ValidationError("Case title is required", "title");
    }
    const count = await this.db.cases.count();
    const record: CaseRecord = {
      id: uuidv4(),
      schemaVersion: SCHEMA_VERSION as CaseRecord["schemaVersion"],
      createdAt: now(),
      updatedAt: now(),
      caseNumber: nextCaseNumber(count),
      title: input.title.trim(),
      status: "active",
      investigationType: input.investigationType,
      currentPhase: "caseCreation",
      isClosed: false,
      closedAt: null,
      archivedAt: null,
      archiveNote: "",
      clientId: null,
      locationId: null,
      clientName: input.clientName,
      notes: input.notes,
    };
    await this.db.transaction(
      "rw",
      this.db.cases,
      this.db.checklistItems,
      this.db.auditEvents,
      async () => {
        await this.db.cases.add(record);
        // Seed the canonical investigation checklist (TPI-V2-WEB-005 §7)
        await new ChecklistService(this.db).ensureCanonicalChecklist(record.id);
        await this.audit.record("caseCreated", `Case ${record.caseNumber} created`, {
          caseId: record.id,
          affectedRecordId: record.id,
          metadata: { investigationType: record.investigationType },
        });
      },
    );
    return record;
  }

  async getCase(id: string): Promise<CaseRecord | undefined> {
    return this.db.cases.get(id);
  }

  /**
   * Search / filter / sort over cases (TPI-V2-WEB-004 §13).
   * Uses indexed where clauses where possible; free-text terms filter the
   * matched set without loading unbounded results.
   */
  async searchCases(options: {
    query?: string;
    status?: CaseStatus;
    clientId?: string;
    locationId?: string;
    sortBy?: "updatedAt" | "createdAt" | "caseNumber" | "title";
    sortDir?: "asc" | "desc";
    limit?: number;
    offset?: number;
  }): Promise<{ items: CaseRecord[]; total: number }> {
    const { query, status, clientId, locationId, sortBy = "updatedAt", sortDir = "desc", limit = 50, offset = 0 } = options;
    let collection = this.db.cases.orderBy(sortBy);
    if (sortDir === "desc") collection = collection.reverse();
    if (status !== undefined) {
      collection = collection.filter((c) => c.status === status);
    }
    if (clientId !== undefined) {
      collection = collection.filter((c) => c.clientId === clientId);
    }
    if (locationId !== undefined) {
      collection = collection.filter((c) => c.locationId === locationId);
    }
    const q = query?.trim().toLowerCase() ?? "";
    if (q.length > 0) {
      collection = collection.filter(
        (c) => c.title.toLowerCase().includes(q) || c.caseNumber.toLowerCase().includes(q),
      );
    }
    const total = await collection.count();
    const items = await collection.offset(offset).limit(limit).toArray();
    return { items, total };
  }

  /** Paginated list — avoids loading entire histories into memory (Directive §14). */
  async listCases(limit = 50, offset = 0): Promise<CaseRecord[]> {
    return this.db.cases.orderBy("updatedAt").reverse().offset(offset).limit(limit).toArray();
  }

  async countCases(): Promise<number> {
    return this.db.cases.count();
  }

  async updateCase(id: string, patch: CasePatch): Promise<CaseRecord | undefined> {
    const updated = await this.db.transaction(
      "rw",
      this.db.cases,
      this.db.auditEvents,
      async () => {
        const existing = await this.db.cases.get(id);
        if (!existing) return undefined;
        const next: CaseRecord = { ...existing, ...patch, updatedAt: now() };
        assertTimestampsMonotonic(next.createdAt, next.updatedAt);
        if (existing.status !== next.status) {
          assertCaseStatusTransition(existing.status, next.status);
        }
        await this.db.cases.put(next);
        const changedFields = Object.keys(patch);
        await this.audit.record(
          "caseUpdated",
          `Case ${next.caseNumber} updated (${changedFields.join(", ")})`,
          {
            caseId: id,
            affectedRecordId: id,
            metadata: { fields: changedFields.join(",") },
          },
        );
        return next;
      },
    );
    return updated;
  }

  async setCaseStatus(id: string, status: CaseStatus, archiveNote?: string): Promise<CaseRecord | undefined> {
    const updated = await this.db.transaction(
      "rw",
      this.db.cases,
      this.db.auditEvents,
      async () => {
        const existing = await this.db.cases.get(id);
        if (!existing) return undefined;
        assertCaseStatusTransition(existing.status, status);
        const next: CaseRecord = {
          ...existing,
          status,
          updatedAt: now(),
          archivedAt: status === "archived" ? now() : null,
          archiveNote: status === "archived" ? (archiveNote ?? existing.archiveNote) : existing.archiveNote,
          // Archiving/restoring is deliberately independent of formal closure.
          // Only CaseClosureService may reopen a closed investigation; silently
          // clearing isClosed here would bypass closure history.
          isClosed: existing.isClosed,
        };
        await this.db.cases.put(next);
        const type: AuditEventType =
          status === "archived"
            ? "caseArchived"
            : status === "active"
              ? "caseReopened"
              : "statusChanged";
        await this.audit.record(type, `Case ${next.caseNumber} → ${status}`, {
          caseId: id,
          affectedRecordId: id,
        });
        return next;
      },
    );
    return updated;
  }

  /**
   * Associate (or change) the location of record references with audit.
   * A non-null location must exist: cases may never point at a missing record
   * (C5B). Removing the association (null) remains permitted.
   */
  async setLocation(id: string, locationId: string | null): Promise<CaseRecord | undefined> {
    return this.db.transaction("rw", this.db.cases, this.db.locations, this.db.auditEvents, async () => {
      const existing = await this.db.cases.get(id);
      if (!existing) return undefined;
      if (locationId !== null) {
        const locationExists = (await this.db.locations.get(locationId)) !== undefined;
        assertReferenceExists(locationId, locationExists, "locationId");
      }
      const next: CaseRecord = { ...existing, locationId, updatedAt: now() };
      await this.db.cases.put(next);
      await this.audit.record("locationChanged", `Case ${next.caseNumber} location reference changed`, {
        caseId: id,
        affectedRecordId: locationId ?? undefined,
      });
      return next;
    });
  }

  /** Controlled phase move — will be replaced by core/workflow engine (WP-3). */
  async setPhase(id: string, phase: WorkflowPhase): Promise<CaseRecord | undefined> {
    return this.updateCase(id, { currentPhase: phase });
  }
}

export type { InvestigationType };
