const locationById = new Map(
  REFERENCE_LOCATION_CATALOG.map((location) => [location.id, location]),
);

export function referenceLocationById(
  id: string,
): ReferenceLocationRecord | undefined {
  return locationById.get(id);
}

export function referenceStateSection(
  code: string,
): ReferenceStateSection | undefined {
  return REFERENCE_STATE_SECTIONS.find((section) => section.code === code);
}

/** Stable DOM key for one source activity; not an import identity. */
export function referenceActivityKey(
  locationId: string,
  activityIndex: number,
): string {
  if (!Number.isInteger(activityIndex) || activityIndex < 0) {
    throw new Error("Activity index must be a non-negative integer");
  }
  return `${locationId}#${activityIndex}`;
}
