/**
 * TPI-V2-WEB-020 — explicit report finalization.
 *
 * Finalization is investigator-directed. Readiness, checklist state, evidence
 * count and claims count are ADVISORY: none is a prerequisite. The only blocking
 * conditions are case/report identity, editable state, sign-off, client privacy
 * approval, and structural source-reference integrity.
 *
 * The immutable revision is written through WEB-019's appendRevision primitive
 * with an expected-current-revision guard. Repeated clicks or a stale review
 * cannot create a duplicate revision.
 */
import type { TPIDatabase } from "../db";
import { ValidationError } from "../validation";
import type {
  CaseReportRecord,
  CaseReportRevisionRecord,
  ReportEligibilitySnapshot,
  ReportPrivacyReview,
  ReportSignoff,
  ReportSourceRef,
  ReportType,
} from "../types";
import { WorkflowReadinessService } from "../workflow/workflowService";
import { InvestigationCompletionService } from "../workflow/investigationCompletionService";
import {
  CLIENT_ALLOWED_SOURCE_TABLES,
  INTERNAL_SOURCE_TABLES,
  REPORT_TYPE_LABELS,
} from "./reportDraft";
import { CaseReportRepository } from "./reportRepository";
import { buildCaseReport } from "./caseReport";
import {
  CLIENT_PRIVACY_ATTESTATION,
  FINALIZATION_ATTESTATION,
  privacyReviewIsComplete,
  scanClientReportPrivacy,
  type PrivacyFlag,
} from "./reportPrivacy";
import type { CaseReportModel } from "./caseReport";

export interface FinalizationAssessment {
  report: CaseReportRecord;
  blockers: string[];
  warnings: string[];
  investigationCompleted: boolean;
  evidenceReviewComplete: boolean;
  reviewStatus: string;
  privacyFlags: PrivacyFlag[];
}

export interface FinalizeReportInput {
  caseId: string;
  reportId: string;
  signoff: ReportSignoff;
  /** Required for client reports; ignored for internal reports. */
  privacyReview?: ReportPrivacyReview | null;
  /** The UI's deliberate finalization confirmation. */
  confirmed: boolean;
}

export interface FinalizeReportResult {
  report: CaseReportRecord;
  revision: CaseReportRevisionRecord;
}

function validateSourceRefs(
  reportType: ReportType,
  caseId: string,
  refs: readonly ReportSourceRef[],
): string[] {
  const blockers: string[] = [];
  const allowed: readonly string[] =
    reportType === "client" ? CLIENT_ALLOWED_SOURCE_TABLES : INTERNAL_SOURCE_TABLES;
  const seen = new Set<string>();
  for (const ref of refs) {
    if (!ref.table || !allowed.includes(ref.table)) {
      blockers.push(`A source reference uses a source family that is not allowed for a ${reportType} report.`);
      continue;
    }
    if (!ref.recordId?.trim()) {
      blockers.push("A source reference is missing its stable record identity.");
    }
    if (ref.caseId !== caseId) {
      blockers.push("A source reference belongs to another case.");
    }
    if (ref.table === "evidence" && ref.contentHash && !/^[0-9a-f]{64}$/i.test(ref.contentHash)) {
      blockers.push("An evidence source reference has an invalid SHA-256 value.");
    }
    const key = `${ref.table}\u0000${ref.recordId}`;
    if (seen.has(key)) blockers.push("The source-reference snapshot contains a duplicate identity.");
    seen.add(key);
  }
  return [...new Set(blockers)];
}

export class ReportFinalizationService {
  private readonly reports: CaseReportRepository;
  private readonly completion: InvestigationCompletionService;
  private readonly readiness: WorkflowReadinessService;

  constructor(private readonly db: TPIDatabase) {
    this.reports = new CaseReportRepository(db);
    this.completion = new InvestigationCompletionService(db);
    this.readiness = new WorkflowReadinessService(db);
  }

  private requireReport(caseId: string, reportId: string): Promise<CaseReportRecord> {
    return this.reports.getById(caseId, reportId).then((report) => {
      if (!report) throw new ValidationError("Report not found for this case.", "reportId");
      return report;
    });
  }

  async assess(
    caseId: string,
    reportId: string,
    model?: CaseReportModel | null,
  ): Promise<FinalizationAssessment> {
    const report = await this.requireReport(caseId, reportId);
    const blockers: string[] = [];
    const warnings: string[] = [];

    if (!report.title.trim() || !report.draft.title.trim()) {
      blockers.push("A report title is required before finalization.");
    }
    if (report.status === "final") {
      blockers.push("This report is already finalized. Create an amendment draft to change it.");
    }
    blockers.push(...validateSourceRefs(report.reportType, caseId, report.sourceRefs));

    const [completion, evaluation] = await Promise.all([
      this.completion.getCompletion(caseId),
      this.readiness.evaluate(caseId),
    ]);
    const resolvedModel = model ?? (await buildCaseReport(this.db, caseId));
    const investigationCompleted = Boolean(completion);
    if (!investigationCompleted) {
      warnings.push(
        "No explicit investigation-completion event is recorded. This is advisory; a report may be finalized without it.",
      );
    }

    const counts = resolvedModel?.counts;
    if (counts?.evidence === 0) {
      warnings.push("No evidence records are referenced. Finalizing an investigation with no evidence is permitted.");
    }
    if (counts?.claims === 0) {
      warnings.push("No claims are recorded. A report with no claims is valid.");
    }
    if (counts?.measurements === 0) {
      warnings.push("No equipment measurements are recorded. No finding is required.");
    }
    if (counts?.sessions === 0) {
      warnings.push("No investigation sessions are recorded. Confirm this reflects the actual investigation.");
    }
    if (evaluation && evaluation.state !== "ready" && evaluation.state !== "overridden") {
      warnings.push(
        `Workflow readiness is "${evaluation.state}" with ${evaluation.blockers.length} advisory condition(s). Readiness does not block report finalization.`,
      );
    }

    const originals = resolvedModel?.evidence.filter((item) => item.kind === "original") ?? [];
    const evidenceReviewComplete =
      originals.length === 0 ||
      originals.every((item) => item.reviewStatus === "reviewed" || item.reviewStatus === "notRequired");
    if (!evidenceReviewComplete) {
      warnings.push("Some evidence review is incomplete. This is advisory and does not prevent finalization.");
    }

    const privacyFlags =
      report.reportType === "client" && resolvedModel
        ? scanClientReportPrivacy(report.draft, resolvedModel)
        : [];

    return {
      report,
      blockers: [...new Set(blockers)],
      warnings: [...new Set(warnings)],
      investigationCompleted,
      evidenceReviewComplete,
      reviewStatus: originals.length === 0 ? "not applicable (no evidence)" : evidenceReviewComplete ? "complete" : "incomplete",
      privacyFlags,
    };
  }

  async finalize(input: FinalizeReportInput, model?: CaseReportModel | null): Promise<FinalizeReportResult> {
    if (!input.confirmed) {
      throw new ValidationError("Finalization requires an explicit investigator confirmation.", "confirmed");
    }
    const report = await this.requireReport(input.caseId, input.reportId);
    if (report.status === "final") {
      throw new ValidationError("This report is already finalized. Create an amendment to propose changes.", "status");
    }

    const signoff = input.signoff;
    if (!signoff.finalizedBy?.trim()) {
      throw new ValidationError("A typed investigator name is required for sign-off.", "signoff.finalizedBy");
    }
    if (!["leadInvestigator", "investigator", "reviewer"].includes(signoff.role)) {
      throw new ValidationError("A valid sign-off role is required.", "signoff.role");
    }
    if (signoff.attestation.trim() !== FINALIZATION_ATTESTATION) {
      throw new ValidationError(
        "The investigator must acknowledge the finalization statement.",
        "signoff.attestation",
      );
    }

    const assessment = await this.assess(input.caseId, input.reportId, model);
    if (assessment.blockers.length > 0) {
      throw new ValidationError(assessment.blockers[0] ?? "Finalization blocked.", "report");
    }

    let privacyReview: ReportPrivacyReview | null = null;
    if (report.reportType === "client") {
      const flags = assessment.privacyFlags;
      if (!privacyReviewIsComplete(input.privacyReview, flags)) {
        throw new ValidationError(
          "A deliberate client privacy review is required before finalizing a client report.",
          "privacyReview",
        );
      }
      privacyReview = {
        reviewedBy: input.privacyReview!.reviewedBy.trim(),
        reviewedAt: Date.now(),
        confirmed: true,
        attestation: CLIENT_PRIVACY_ATTESTATION,
        flagsAcknowledged: flags.map((flag) => flag.id),
      };
    }

    const finalizedAt = Date.now();
    const eligibility: ReportEligibilitySnapshot = {
      investigationCompleted: assessment.investigationCompleted,
      evidenceReviewComplete: assessment.evidenceReviewComplete,
      reviewStatus: assessment.reviewStatus,
      blockers: [],
      warnings: assessment.warnings,
      capturedAt: finalizedAt,
    };
    const revision = await this.reports.appendRevision({
      caseId: input.caseId,
      reportId: input.reportId,
      content: report.draft,
      sourceRefs: report.sourceRefs,
      eligibility,
      signoff: {
        ...signoff,
        finalizedBy: signoff.finalizedBy.trim(),
        attestation: signoff.attestation.trim(),
        signedAt: finalizedAt,
      },
      privacyReview,
      expectedCurrentRevisionId: report.currentRevisionId,
      finalizedAt,
    });
    const updated = await this.reports.getById(input.caseId, input.reportId);
    if (!updated) throw new ValidationError("Finalized report could not be reloaded.", "reportId");
    return { report: updated, revision };
  }
}

export function finalizedReportLabel(report: CaseReportRecord): string {
  return `${REPORT_TYPE_LABELS[report.reportType]} — ${report.title}`;
}
