const LIMITATIONS: readonly string[] = [
  "This report reproduces persisted records. It does not create a conclusion, anomaly classification, confidence score or paranormal determination.",
  "Client and witness statements remain statements. They are not verified facts and are not evidence records.",
  "Equipment measurements are recorded readings with their stated acquisition and calibration. They are not findings.",
  "Evidence hashes are the stored SHA-256 values. They demonstrate byte integrity, not authenticity, causation or paranormal activity.",
  "Missing or unavailable information is labelled. It is never inferred, back-filled or replaced with another case's data.",
];

const WALKTHROUGH_CLASSIFICATION: Record<string, string> = {
  reported: "Reported by client/witness",
  observed: "Investigator observed",
  measured: "Instrument measurement",
  interpreted: "Investigator interpretation",
};

function clean(value: string | null | undefined): string | null {
  const trimmed = (value ?? "").trim();
  return trimmed ? trimmed : null;
}

function dateLabel(ms: number): string {
  return new Date(ms).toLocaleString();
}

function sessionLabel(
  sessionId: string | null,
  sessions: Map<string, InvestigationSessionRecord>,
  addMissingRef: (kind: "room" | "session") => void,
): string {
  if (!sessionId) return "No session association";
  const session = sessions.get(sessionId);
  if (!session) {
    addMissingRef("session");
    return "Session record missing";
  }
  return `${session.status} — ${dateLabel(session.startedAt)}`;
}

export async function buildCaseReport(
  db: TPIDatabase,
  caseId: string,
): Promise<CaseReportModel | null> {
  const record: CaseRecord | undefined = await db.cases.get(caseId);
  if (!record) return null;

  const [
    linkedClient,
    location,
    structure,
    rooms,
    sessions,
    notes,
    summaries,
    claims,
    evidence,
    measurements,
    walkthroughObservations,
    observations,
  ] = await Promise.all([
    record.clientId ? db.clients.get(record.clientId) : Promise.resolve(undefined),
    record.locationId ? db.locations.get(record.locationId) : Promise.resolve(undefined),
    db.propertyStructures.where("caseId").equals(caseId).first(),
    db.structureRooms.where("caseId").equals(caseId).toArray(),
    db.sessions.where("caseId").equals(caseId).toArray(),
    db.investigationNotes.where("caseId").equals(caseId).toArray(),
    db.roomSummaries.where("caseId").equals(caseId).toArray(),
    db.claims.where("caseId").equals(caseId).toArray(),
    db.evidence.where("caseId").equals(caseId).toArray(),
    db.environmentMeasurements.where("caseId").equals(caseId).toArray(),
    db.walkthroughObservations.where("caseId").equals(caseId).toArray(),
    db.observations.where("caseId").equals(caseId).toArray(),
  ]);

  const warnings: string[] = [];
  const missingReferences = new Set<"room" | "session">();
  const addWarning = (warning: string): void => {
    if (!warnings.includes(warning)) warnings.push(warning);
  };
  const addMissingRef = (kind: "room" | "session"): void => {
    missingReferences.add(kind);
  };

  // Client: reject a linked record from another case. A case-level legacy
  // contact field may be used, but it is labelled as such and never merged
  // with a foreign client's data.
  let clientRow: ClientRecord | undefined = linkedClient;
  if (clientRow && clientRow.caseId !== record.id) {
    clientRow = undefined;
    addWarning("The linked client record belongs to another case and was not included.");
  } else if (record.clientId && !clientRow) {
    addWarning("The linked client record is missing. Case-level contact fields are used only if present.");
  } else if (!clientRow && clean(record.clientName)) {
    addWarning("No client record is linked. Legacy case-level contact fields are labelled as such.");
  }

  const clientSource = clientRow ? "clients" : clean(record.clientName) || clean(record.phone) || clean(record.email)
    ? "cases (legacy contact fields)"
    : "not recorded";
  const client: ReportClient = {
    recordId: clientRow?.id ?? null,
    name: clean(clientRow?.fullName) ?? clean(record.clientName),
    phone: clean(clientRow?.phone) ?? clean(record.phone),
    email: clean(clientRow?.email) ?? clean(record.email),
    notes: clean(clientRow?.notes),
    source: clientSource,
  };

  const locationAddress = [
    location?.street ?? record.street,
    location?.city ?? record.city,
    location?.state ?? record.state,
    location?.zip ?? record.zip,
  ]
    .map((part) => clean(part))
    .filter((part): part is string => Boolean(part))
    .join(", ");
  const locationName = clean(location?.name) ?? clean(structure?.name);
  const locationSource = location
    ? "locations"
    : locationName || locationAddress
      ? "cases / propertyStructures"
      : "not recorded";
  if (record.locationId && !location) {
    addWarning("The linked location record is missing. Case-level address fields are used only if present.");
  }
  const reportLocation: ReportLocation = {
    recordId: location?.id ?? null,
    name: locationName,
    address: locationAddress || null,
    propertyDetails: clean(location?.propertyDetails),
    source: locationSource,
  };

  if (!structure) addWarning("No property structure is recorded.");
  if (!rooms.length) addWarning("No rooms are recorded; room references cannot be resolved.");
  if (!sessions.length) addWarning("No investigation sessions are recorded.");
  if (!notes.length) addWarning("No investigator notes are recorded.");
  if (!summaries.length) addWarning("No per-room summaries are recorded.");
  if (!claims.length) addWarning("No client or witness claims are recorded.");
  if (!evidence.length) addWarning("No evidence records are recorded.");
  if (!measurements.length) addWarning("No equipment measurements are recorded.");

  const roomById = new Map(rooms.map((room) => [room.id, room]));
  const sessionById = new Map(sessions.map((session) => [session.id, session]));

  const roomLabel = (roomId: string | null): string | null => {
    if (!roomId) return null;
    const room = roomById.get(roomId);
    if (!room) {
      addMissingRef("room");
      return "Room record missing";
    }
    return room.name;
  };

  const sortedSessions = [...sessions].sort((a, b) => b.startedAt - a.startedAt);
  const reportSessions: ReportSession[] = sortedSessions.map((session) => ({
    id: session.id,
    status: session.status,
    startedAt: session.startedAt,
    endedAt: session.endedAt ?? null,
    durationMinutes: session.endedAt && session.endedAt >= session.startedAt
      ? Math.round((session.endedAt - session.startedAt) / 60_000)
      : null,
    investigators: session.investigators,
    notes: clean(session.notes),
    roomName: roomLabel(session.currentRoomId ?? null),
    source: "sessions" as const,
  }));

  const reportNotes: ReportNote[] = [...notes]
    .sort((a, b) => b.updatedAt - a.updatedAt)
    .map((note: InvestigationNoteRecord) => ({
      id: note.id,
      kind: note.kind,
      kindLabel: NOTE_KIND_LABELS[note.kind] ?? note.kind,
      title: clean(note.title),
      body: note.body,
      author: clean(note.author),
      roomName: note.roomId ? (roomLabel(note.roomId) ?? "Room record missing") : "General investigator notes",
      sessionLabel: sessionLabel(note.sessionId, sessionById, addMissingRef),
      createdAt: note.createdAt,
      updatedAt: note.updatedAt,
      source: "investigationNotes" as const,
    }));

  const reportSummaries: ReportSummary[] = [...summaries]
    .sort((a, b) => b.updatedAt - a.updatedAt)
    .map((summary: RoomSummaryRecord) => ({
      id: summary.id,
      body: summary.body,
      author: clean(summary.author),
      roomName: roomLabel(summary.roomId) ?? "Room record missing",
      sessionLabel: sessionLabel(summary.sessionId, sessionById, addMissingRef),
      createdAt: summary.createdAt,
      updatedAt: summary.updatedAt,
      source: "roomSummaries" as const,
    }));

  const reportClaims: ReportClaim[] = [...claims]
    .sort((a, b) => b.createdAt - a.createdAt)
    .map((claim: ClaimRecord) => ({
      id: claim.id,
      title: claim.title,
      classification: claim.classification,
      roomName: claim.roomID ? (roomLabel(claim.roomID) ?? "Room record missing") : clean(claim.roomName),
      firstOccurrence: clean(claim.firstOccurrenceText),
      mostRecentOccurrence: clean(claim.mostRecentOccurrenceText),
      frequency: clean(claim.frequency),
      timePattern: clean(claim.timePattern),
      witnesses: clean(claim.witnessesText) ?? (claim.witnessCount > 0 ? `${claim.witnessCount} witness(es)` : null),
      notes: clean(claim.notes),
      source: "claims" as const,
    }));

  const reportEvidence: ReportEvidence[] = [...evidence]
    .sort((a, b) => (b.captureTimestamp ?? b.acquiredAt) - (a.captureTimestamp ?? a.acquiredAt))
    .map((item: EvidenceRecord) => ({
      id: item.id,
      title: item.title,
      mediaType: item.mediaType,
      kind: item.kind,
      fileName: item.fileName,
      fileSizeBytes: item.fileSizeBytes,
      contentHash: item.contentHash,
      acquiredAt: item.captureTimestamp ?? item.acquiredAt,
      timestampSource: item.captureTimestampSource ?? "unknown",
      reviewStatus: item.reviewStatus,
      integrity: item.verificationStatus ?? "unverified",
      recordedBy: clean(item.provenance?.recordedBy),
      provenanceOrigin: clean(item.provenance?.origin),
      recordedAt: item.provenance?.recordedAt ?? null,
      verifiedAt: item.verifiedAt ?? null,
      roomName: item.roomId ? roomLabel(item.roomId) : null,
      sessionLabel: item.sessionId ? sessionLabel(item.sessionId, sessionById, addMissingRef) : null,
      parentId: item.parentId ?? null,
      source: "evidence" as const,
    }));

  const reportMeasurements: ReportMeasurement[] = [...measurements]
    .sort((a, b) => b.at - a.at)
    .map((item: EnvironmentMeasurementRecord) => ({
      id: item.id,
      measurementType: item.measurementType,
      value: item.value,
      unit: clean(item.unit),
      text: clean(item.text),
      at: item.at,
      acquisition: item.acquisition,
      instrument: clean(item.instrument),
      calibration: item.calibration,
      roomName: item.roomId ? roomLabel(item.roomId) : null,
      sessionLabel: item.sessionId ? sessionLabel(item.sessionId, sessionById, addMissingRef) : null,
      notes: clean(item.notes),
      source: "environmentMeasurements" as const,
    }));

  const reportFindings: ReportFinding[] = [
    ...walkthroughObservations.map((item: WalkthroughObservationRecord) => ({
      id: item.id,
      classification: WALKTHROUGH_CLASSIFICATION[item.kind] ?? item.kind,
      title: clean(item.areaLabel) ?? (item.roomId ? (roomLabel(item.roomId) ?? "Area record missing") : "Walkthrough observation"),
      body: item.description,
      roomName: item.roomId ? roomLabel(item.roomId) : clean(item.areaLabel),
      sessionLabel: sessionLabel(item.sessionId, sessionById, addMissingRef),
      at: item.createdAt,
      amended: item.amended,
      evidenceId: item.evidenceId,
      source: "walkthroughObservations" as const,
    })),
    ...observations.map((item: ObservationRecord) => ({
      id: item.id,
      classification: item.entryType === "interpretation" ? "Investigator interpretation" : "Investigator observation",
      title: clean(item.title) ?? clean(item.roomName) ?? "Observation",
      body: item.body,
      roomName: clean(item.roomName),
      sessionLabel: sessionLabel(item.sessionId ?? null, sessionById, addMissingRef),
      at: item.createdAt,
      amended: false,
      evidenceId: null,
      source: "observations" as const,
    })),
  ].sort((a, b) => b.at - a.at);

  if (!reportFindings.length) addWarning("No investigator-authored findings or observations are recorded; none were generated.");
  if (missingReferences.size) {
    addWarning("Some records reference a room or session that is not part of this case. Those references are labelled missing and no foreign data is shown.");
  }

  const evidenceProblems = reportEvidence.filter((item) =>
    item.integrity === "missing" || item.integrity === "corrupted" || item.integrity === "verificationFailed",
  ).length;
  if (evidenceProblems) {
    addWarning(`${evidenceProblems} evidence record(s) have a recorded integrity problem; the report preserves that state.`);
  }
  const unverified = reportEvidence.filter((item) => item.integrity === "unverified").length;
  if (unverified) {
    addWarning(`${unverified} of ${reportEvidence.length} evidence reference(s) are not marked verified.`);
  }

  const sources: ReportSource[] = [
    { label: "Case record", table: "cases", records: 1, included: "Identification, status, phase, dates, case notes" },
    { label: "Client record", table: "clients", records: clientRow ? 1 : 0, included: "Name, contact fields, client notes" },
    { label: "Location record", table: "locations", records: location ? 1 : 0, included: "Name, address, property details" },
    { label: "Property structure / rooms", table: "propertyStructures / structureRooms", records: (structure ? 1 : 0) + rooms.length, included: "Structure identity and room names" },
    { label: "Investigation sessions", table: "sessions", records: reportSessions.length, included: "Status, window, investigators, session notes" },
    { label: "Investigator notes", table: "investigationNotes", records: reportNotes.length, included: "Kind, title, body, attribution, room/session references" },
    { label: "Per-room summaries", table: "roomSummaries", records: reportSummaries.length, included: "Room/session text and attribution" },
    { label: "Reported claims", table: "claims", records: reportClaims.length, included: "Client/witness statements and classifications" },
    { label: "Evidence references", table: "evidence", records: reportEvidence.length, included: "References, type, timestamps, review, integrity and SHA-256" },
    { label: "Equipment measurements", table: "environmentMeasurements", records: reportMeasurements.length, included: "Type, value, acquisition, instrument, calibration" },
    { label: "Investigator findings/observations", table: "walkthroughObservations / observations", records: reportFindings.length, included: "Existing investigator-authored entries and their classification" },
  ];

  return {
    reportVersion: CASE_REPORT_MODEL_VERSION,
    databaseSchemaVersion: SCHEMA_VERSION,
    generatedAt: Date.now(),
    caseId: record.id,
    caseNumber: clean(record.caseNumber),
    title: clean(record.title),
    status: record.status,
    investigationType: record.investigationType,
    currentPhase: record.currentPhase,
    createdAt: record.createdAt,
    updatedAt: record.updatedAt,
    closedAt: record.closedAt ?? null,
    archivedAt: record.archivedAt ?? null,
    client,
    location: reportLocation,
    structure: structure
      ? { name: structure.name, kind: structure.kind, notes: clean(structure.notes), revision: structure.revision }
      : null,
    rooms: [...rooms]
      .sort((a, b) => a.orderIndex - b.orderIndex || a.name.localeCompare(b.name))
      .map((room: RoomRecord) => ({ id: room.id, name: room.name, roomType: room.roomType, archived: room.archived })),
    sessions: reportSessions,
    notes: reportNotes,
    summaries: reportSummaries,
    claims: reportClaims,
    evidence: reportEvidence,
    measurements: reportMeasurements,
    findings: reportFindings,
    warnings,
    limitations: [...LIMITATIONS],
    sources,
    counts: {
      rooms: rooms.length,
      sessions: reportSessions.length,
      notes: reportNotes.length,
      summaries: reportSummaries.length,
      claims: reportClaims.length,
      evidence: reportEvidence.length,
      measurements: reportMeasurements.length,
      findings: reportFindings.length,
      warnings: warnings.length,
    },
  };
}

export function reportFileToken(report: Pick<CaseReportModel, "caseNumber" | "caseId">): string {
  const seed = report.caseNumber || report.caseId;
  return seed.replace(/[^A-Za-z0-9_-]+/g, "_").replace(/^_+|_+$/g, "") || report.caseId;
}

export function buildEvidenceManifest(report: CaseReportModel): EvidenceManifest {
  return {
    format: EVIDENCE_MANIFEST_FORMAT,
    version: EVIDENCE_MANIFEST_VERSION,
    reportModelVersion: report.reportVersion,
    databaseSchemaVersion: report.databaseSchemaVersion,
    generatedAt: new Date(report.generatedAt).toISOString(),
    case: {
      id: report.caseId,
      caseNumber: report.caseNumber,
      title: report.title,
    },
    evidenceCount: report.evidence.length,
    evidence: report.evidence.map((item) => ({
      id: item.id,
      title: item.title,
      kind: item.kind,
      mediaType: item.mediaType,
      fileName: item.fileName,
      fileSizeBytes: item.fileSizeBytes,
      contentHash: item.contentHash,
      hashAlgorithm: "SHA-256",
      acquiredAt: new Date(item.acquiredAt).toISOString(),
      timestampSource: item.timestampSource,
      reviewStatus: item.reviewStatus,
      verificationStatus: item.integrity,
      verifiedAt: item.verifiedAt ? new Date(item.verifiedAt).toISOString() : null,
      provenance: item.provenanceOrigin || item.recordedBy || item.recordedAt
        ? {
            origin: item.provenanceOrigin,
            recordedBy: item.recordedBy,
            recordedAt: item.recordedAt ? new Date(item.recordedAt).toISOString() : null,
          }
        : null,
      parentId: item.parentId,
    })),
    warnings: [...report.warnings],
    limitations: [...report.limitations],
    note: EVIDENCE_MANIFEST_NOTE,
  };
}

export function evidenceManifestJson(report: CaseReportModel): string {
  return JSON.stringify(buildEvidenceManifest(report), null, 2);
}
