/**
 * Guided Intake view (TPI-V2-WEB-006 §13). Structured forms using the
 * original iOS question text; partial save + resume; conditional questions;
 * completion derived from real responses via IntakeService.
 */
import "./casehub.css";
import { getDb } from "../../core/db";
import { CaseRepository } from "../../core/repositories/caseRepository";
import { IntakeService } from "../../core/intake/intakeService";
import {
  INTAKE_SECTIONS,
  questionById,
  type IntakeQuestion,
} from "../../core/intake/questions";
import type { IntakeResponseRecord } from "../../core/types";
import {
  ATTACHMENT_STATUSES,
  DEFAULT_ATTACHMENT_STATUS,
  DEFAULT_DOCUMENT_TYPE,
  DOCUMENT_TYPES,
  IntakeAttachmentService,
  type AttachmentClassification,
  type IntakeAttachment,
} from "../../core/intake/intakeAttachmentService";
import { EvidenceRepository } from "../../core/repositories/evidenceRepository";
import { esc, viewShell, wireBackButton } from "../dashboard/shell";
import { mountView, onDelegate, invalidateView, clearDrafts } from "../../shared/uidom";
import { renderCaseHub } from "./CaseHub";

const db = () => getDb();

export async function renderIntakeView(container: HTMLElement, caseId: string, sectionId?: string): Promise<void> {
  const record = await new CaseRepository(db()).getCase(caseId);
  if (!record) {
    container.innerHTML = viewShell("Guided Intake", `<div class="cc-empty">Case not found.</div>`);
    wireBackButton(container);
    return;
  }
  const service = new IntakeService(db());
  const dossier = await service.ensureDossier(caseId);
  const answers = await service.answerMap(caseId);
  const evaluation = await service.evaluate(caseId);
  const claimCount = service.claimCount(answers);
  const section = INTAKE_SECTIONS.find((s) => s.id === sectionId) ?? INTAKE_SECTIONS[0]!;

  const questions = service.applicableQuestions(claimCount, answers).filter((q) => q.section === section.id);
  const sectionDone = (id: string): "complete" | "partial" | "empty" => {
    const qs = service.applicableQuestions(claimCount, answers).filter((q) => q.section === id);
    if (qs.length === 0) return "empty";
    const done = qs.filter((q) => {
      const r = answers.get(q.id);
      return r?.status === "answered" || (r?.status === "skipped" && !q.required);
    }).length;
    return done === qs.length ? "complete" : done > 0 ? "partial" : "empty";
  };

  const nav = INTAKE_SECTIONS.map(
    (s) => `
    <button class="back-button intake-section-tab" data-section="${s.id}" aria-current="${s.id === section.id}">
      ${esc(s.label)} ${sectionDone(s.id) === "complete" ? "✓" : sectionDone(s.id) === "partial" ? "•" : ""}
    </button>`,
  ).join("");

  const body = questions
    .map((q) => questionHtml(q, answers.get(q.id), section.id === "claims" ? claimSuffix(q) : ""))
    .join("");

  // Research Archive also carries the original research-attachment form
  // (TPI-V2-WEB-010G Phase 010G-B). Attachments are the original metadata model
  // plus an optional link to a real imported file.
  const attachmentService = new IntakeAttachmentService(db());
  const attachments = section.id === "researchArchive" ? await attachmentService.listForCase(caseId) : [];
  const attachableEvidence =
    section.id === "researchArchive"
      ? (await db().evidence.where("caseId").equals(caseId).toArray())
          .filter((e) => e.kind === "original")
          .sort((a, b) => b.createdAt - a.createdAt)
      : [];
  const attachmentHtml =
    section.id === "researchArchive"
      ? attachmentsHtml(attachments, attachableEvidence)
      : "";

  invalidateView(container); // different view — reset idempotence cache
  container.dataset.intakeSection = section.id;
  mountView(container, viewShell(
    `Guided Intake — ${record.caseNumber}`,
    `
    <div class="case-form" data-root="intake" data-epoch="${Date.now()}-${Math.random()}">
      <p class="cc-count" id="intake-status-line">
        ${dossier.status === "finalized"
          ? `Intake finalized. Corrections reopen the dossier without destroying audit history.`
          : `Intake in progress — responses save as you go; you can leave and resume any time.`}
        Progress: <strong>${evaluation.percent}%</strong> (${evaluation.answeredCount}/${evaluation.applicableCount} applicable questions).
        Client statements are recorded as statements — not verified facts.
        <span id="intake-save-status">Answers auto-save.</span>
      </p>
      <div class="intake-nav" role="tablist" aria-label="Intake sections">${nav}</div>
      <div class="meter" role="meter" aria-valuenow="${evaluation.percent}" aria-valuemin="0" aria-valuemax="100" aria-label="Intake progress"><div class="fill" style="width:${evaluation.percent}%"></div></div>
      <div id="intake-questions">${body}</div>
      ${attachmentHtml}
      ${section.id === "claims" ? `<div class="form-actions"><button class="back-button" id="claims-add" type="button" ${answers.has(`additionalClaimDecision#${claimCount - 1}`) ? "" : "disabled"}>+ Start another claim set (answer the additional-claim question above first)</button></div>` : ""}
      <div class="form-actions">
        ${dossier.status === "finalized"
          ? `<button class="button-secondary" id="intake-reopen" type="button">Reopen for Correction…</button>`
          : `<button class="button-primary" id="intake-review" type="button">Review & Finalize Intake</button>`}
        <button class="back-button" id="intake-back" type="button">← Back to Case Hub</button>
      </div>
      <div id="intake-review"></div>
    </div>
    `,
  ));

  const rerender = () => void renderIntakeView(container, caseId, section.id);

  // TPI-V2-WEB-007 §4: delegated handlers — current section on the container.
  onDelegate(container, "click", ".intake-section-tab", (el) => {
    void renderIntakeView(container, caseId, el.dataset.section);
  });
  onDelegate(container, "click", "#intake-back", () => {
    void renderCaseHub(container, caseId);
  });
  onDelegate(container, "click", "#claims-add", rerender);
  onDelegate(container, "click", "[data-question] [data-save]", (el) => {
    const row = el.closest<HTMLElement>("[data-question]");
    if (!row) return;
    const qid = row.dataset.question ?? "";
    const q = questionById(qid);
    if (!q) return;
    const value = readAnswer(row, q);
    void service
      .saveResponse(caseId, qid, { value, status: "answered", repeatIndex: repeatIndexOf(qid) })
      .then(() => {
        clearDrafts(container); // the answer is committed and rendered from the record
        return renderIntakeView(container, caseId, container.dataset.intakeSection);
      })
      .catch((err) => alert((err as Error).message));
  });
  onDelegate(container, "click", "[data-question] [data-skip]", (el) => {
    const row = el.closest<HTMLElement>("[data-question]");
    if (!row) return;
    const qid = row.dataset.question ?? "";
    void service
      .saveResponse(caseId, qid, { value: "", status: "skipped", repeatIndex: repeatIndexOf(qid) })
      .then(() => {
        clearDrafts(container); // the answer is committed and rendered from the record
        return renderIntakeView(container, caseId, container.dataset.intakeSection);
      })
      .catch((err) => alert((err as Error).message));
  });
  // Auto-save: every change is persisted shortly after it is made (debounced
  // per question) so responses survive interruptions and re-renders.
  const autosaveTimers = new Map<string, number>();
  const scheduleAutosave = (qid: string, status: "answered" | "skipped", value: string) => {
    const existing = autosaveTimers.get(qid);
    if (existing) window.clearTimeout(existing);
    const handle = window.setTimeout(() => {
      autosaveTimers.delete(qid);
      void service
        .saveResponse(caseId, qid, { value, status, repeatIndex: repeatIndexOf(qid) })
        .catch((err) => console.warn("intake autosave failed:", (err as Error).message));
    }, 500);
    autosaveTimers.set(qid, handle);
  };

  // Auto-save wiring (per render — inputs are replaced with the view).
  container.querySelectorAll<HTMLElement>("[data-question]").forEach((row) => {
    const qid = row.dataset.question ?? "";
    const q = questionById(qid);
    if (!q) return;
    row.querySelectorAll<HTMLElement>("[data-q-input]").forEach((el) => {
      const handler = () => scheduleAutosave(qid, "answered", readAnswer(row, q));
      el.addEventListener("input", handler);
      el.addEventListener("change", handler);
    });
  });
  onDelegate(container, "click", "#intake-review", async () => {
    const review = container.querySelector<HTMLDivElement>("#intake-review");
    if (!review) return;
    // Re-evaluate at click time — the closure's evaluation predates any
    // auto-saved answers (stale-state guard, KI-WEB-006-1 class).
    const evaluation = await service.evaluate(caseId);
    review.innerHTML = `
      <h3 class="cc-section-title">Review before finalizing</h3>
      ${evaluation.missing.length === 0
        ? `<p class="cc-count">All required responses are recorded. Finalizing records completion in the workflow engine.</p>
           <div class="form-actions"><button class="button-primary" id="intake-finalize" type="button">Confirm Finalize</button></div>`
        : `<p class="cc-count"><strong>${evaluation.missing.length}</strong> required question(s) outstanding:</p>` +
          evaluation.missing
            .slice(0, 12)
            .map(
              (m) => `<div class="case-row" role="alert"><div><div class="case-title">${esc(m.prompt)}</div><div class="case-meta">${esc(m.section)} • ${esc(m.reason)}</div></div></div>`,
            )
            .join("")}`;
  });
  onDelegate(container, "click", "#intake-finalize", async () => {
    try {
      await service.finalize(caseId);
      await renderIntakeView(container, caseId, container.dataset.intakeSection);
    } catch (err) {
      alert((err as Error).message);
    }
  });
  onDelegate(container, "click", "#intake-reopen", async () => {
    const reason = window.prompt("Document why intake is being reopened for correction:", "");
    if (!reason?.trim()) return;
    await service.reopen(caseId, reason);
    await renderIntakeView(container, caseId, container.dataset.intakeSection);
  });

  if (section.id === "researchArchive") wireAttachmentHandlers(container, caseId, section.id);
  wireBackButton(container);
}

/**
 * Research-attachment panel — the original "Add Attachment" form
 * (section "Research Attachment") with its exact prompts, plus an optional link
 * to a real imported file or a new import.
 */
function attachmentsHtml(
  attachments: IntakeAttachment[],
  evidence: Array<{ id: string; title: string; mediaType: string; originalFileName?: string }>,
): string {
  return `
    <h3 class="cc-section-title">Research Attachment</h3>
    <div class="case-form" data-attachment-panel>
      <p class="cc-meta">Research attachments are documents and media connected to this case's intake (deeds, records, historical photographs, clippings, and similar). ${attachments.length} attached.
      A client's document is recorded as <strong>client-supplied</strong> material — it is never presented as an investigator observation.
      ${attachments.some((a) => a.evidenceId) ? "" : "The original application stored attachment metadata only; linking an actual file is a browser addition that keeps the original file unchanged and hashed."}</p>

      <div class="detail-grid">
        <div class="detail-field"><label for="att-title">What is the title of this document?</label>
          <input id="att-title" type="text" placeholder="What is the title of this document?"></div>
        <div class="detail-field"><label for="att-source">Where did this document come from?</label>
          <input id="att-source" type="text" placeholder="Where did this document come from?"></div>
        <div class="detail-field"><label for="att-date">What is the date of this document?</label>
          <input id="att-date" type="date"></div>
        <div class="detail-field"><label for="att-uploaded-by">Uploaded by</label>
          <input id="att-uploaded-by" type="text" placeholder="Uploaded by"></div>
        <div class="detail-field"><label for="att-status">What is the verification status?</label>
          <select id="att-status">
            ${ATTACHMENT_STATUSES.map((x) => `<option value="${esc(x)}"${x === DEFAULT_ATTACHMENT_STATUS ? " selected" : ""}>${esc(x)}</option>`).join("")}
          </select></div>
        <div class="detail-field"><label for="att-type">Document type</label>
          <select id="att-type">
            ${DOCUMENT_TYPES.map((x) => `<option value="${esc(x)}"${x === DEFAULT_DOCUMENT_TYPE ? " selected" : ""}>${esc(x)}</option>`).join("")}
          </select></div>
        <div class="detail-field"><label for="att-classification">Source classification</label>
          <select id="att-classification">
            <option value="notRecorded" selected>Not recorded</option>
            <option value="clientSupplied">Client-supplied material</option>
            <option value="investigatorCaptured">Investigator-recorded material</option>
            <option value="importedExternal">Imported external material</option>
          </select></div>
        <div class="detail-field"><label for="att-question">Intake question / claim</label>
          <select id="att-question">
            <option value="researchArchiveNotes" selected>Research Archive (general)</option>
            <option value="clientName">Client &amp; Household</option>
            <option value="claimDescription">Claim (current claim)</option>
            <option value="healthWellnessNotes">Health &amp; Wellness notes</option>
            <option value="landHistoricalNotes">Land &amp; Historical</option>
          </select></div>
        <div class="detail-field"><label for="att-evidence">Attach existing evidence (optional)</label>
          <select id="att-evidence">
            <option value="">— metadata only —</option>
            ${evidence.map((e) => `<option value="${e.id}">${esc(e.title)} (${esc(e.mediaType)})</option>`).join("")}
          </select></div>
      </div>
      <div class="detail-field"><label for="att-notes">Are there any notes related to this document?</label>
        <textarea id="att-notes" rows="2" placeholder="Are there any notes related to this document?"></textarea></div>
      <div class="detail-field"><label for="att-file">Import a new file for this attachment (optional)</label>
        <input id="att-file" type="file"></div>
      <div class="form-actions">
        <button class="button-primary" id="att-add" type="button">Add</button>
        <button class="back-button" id="att-cancel" type="button">Cancel</button>
      </div>
      <p class="cc-meta" id="att-status-line" role="status"></p>
    </div>

    <div id="attachment-list">
      ${attachments.length === 0
        ? '<div class="cc-empty">No research attachments recorded.</div>'
        : attachments
            .map(
              (a) => `
        <div class="case-row" data-attachment="${a.id}">
          <div>
            <div class="case-title">${esc(a.documentTitle)}</div>
            <div class="case-meta">
              ${esc(a.documentType)} • ${esc(a.verificationStatus)} • ${esc(a.classification === "clientSupplied" ? "client-supplied material" : a.classification === "investigatorCaptured" ? "investigator-recorded material" : a.classification === "importedExternal" ? "imported external material" : "source not recorded")}
              ${a.dateText ? ` • ${esc(a.dateText)}` : ""}${a.uploadedBy ? ` • uploaded by ${esc(a.uploadedBy)}` : ""}${a.source ? ` • from ${esc(a.source)}` : ""}
              ${a.evidenceId ? " • file linked (hashed original)" : " • metadata only"}
              ${a.questionId ? ` • ${esc(a.questionId)}` : ""}
              ${a.notes ? `<br>${esc(a.notes)}` : ""}
            </div>
          </div>
          <div style="display:flex;gap:6px;">
            <button class="back-button" data-att-edit="${a.id}" type="button">Edit…</button>
            <button class="back-button" data-att-remove="${a.id}" type="button">Remove Association…</button>
          </div>
        </div>`,
            )
            .join("")}
    </div>`;
}

/** Research attachments (TPI-V2-WEB-010G Phase 010G-B). */
function wireAttachmentHandlers(container: HTMLElement, caseId: string, sectionId: string): void {
  const attService = new IntakeAttachmentService(db());
  const attStatus = (text: string) => {
    const el = container.querySelector<HTMLElement>("#att-status-line");
    if (el) el.textContent = text;
  };

  onDelegate(container, "click", "#att-cancel", () => {
    container.querySelectorAll<HTMLInputElement | HTMLTextAreaElement>("#att-title, #att-source, #att-date, #att-uploaded-by, #att-notes").forEach((el) => {
      el.value = "";
    });
    const evidenceSel = container.querySelector<HTMLSelectElement>("#att-evidence");
    if (evidenceSel) evidenceSel.value = "";
    const fileInput = container.querySelector<HTMLInputElement>("#att-file");
    if (fileInput) fileInput.value = "";
    attStatus("Cleared.");
  });

  onDelegate(container, "click", "#att-add", async () => {
    const read = (sel: string) => container.querySelector<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>(sel)?.value.trim() ?? "";
    try {
      let evidenceId: string | null = read("#att-evidence") || null;
      const classification = (read("#att-classification") || "notRecorded") as AttachmentClassification;
      const file = container.querySelector<HTMLInputElement>("#att-file")?.files?.[0];
      if (file) {
        const mediaType = file.type.startsWith("image/") ? "photo" : file.type.startsWith("video/") ? "video" : file.type.startsWith("audio/") ? "audio" : "document";
        const repo = new EvidenceRepository(db());
        const record = await repo.storeOriginal({
          caseId,
          mediaType,
          title: read("#att-title") || file.name,
          fileName: file.name,
          data: file,
          origin: classification === "clientSupplied" ? "clientSupplied"
            : classification === "investigatorCaptured" ? "investigatorCaptured"
              : classification === "importedExternal" ? "import" : "unknown",
          recordedBy: read("#att-uploaded-by") || (classification === "clientSupplied" ? "client-supplied" : "not recorded"),
        });
        await db().evidence.put({
          ...record,
          originalFileName: file.name,
          sourceDescription: `Intake attachment — ${read("#att-source") || "source not recorded"}`,
          importedAt: Date.now(),
          verificationStatus: "verified",
          verifiedAt: Date.now(),
          verificationDetail: "Stored unchanged on import and hashed.",
        });
        evidenceId = record.id;
      }
      await attService.create(caseId, {
        documentTitle: read("#att-title"),
        documentType: read("#att-type") || DEFAULT_DOCUMENT_TYPE,
        source: read("#att-source"),
        dateText: read("#att-date"),
        uploadedBy: read("#att-uploaded-by"),
        verificationStatus: read("#att-status") || DEFAULT_ATTACHMENT_STATUS,
        notes: read("#att-notes"),
        evidenceId,
        questionId: read("#att-question") || "researchArchiveNotes",
        classification,
      });
      await renderIntakeView(container, caseId, sectionId);
    } catch (err) {
      attStatus((err as Error).message);
    }
  });

  onDelegate(container, "click", "[data-att-edit]", async (el) => {
    const id = el.dataset.attEdit ?? "";
    const existing = await attService.get(id);
    if (!existing) return;
    const title = window.prompt("What is the title of this document?", existing.documentTitle);
    if (title === null) return;
    const source = window.prompt("Where did this document come from?", existing.source);
    if (source === null) return;
    const dateText = window.prompt("What is the date of this document?", existing.dateText);
    if (dateText === null) return;
    const uploadedBy = window.prompt("Uploaded by", existing.uploadedBy);
    if (uploadedBy === null) return;
    const status = window.prompt(`What is the verification status? (${ATTACHMENT_STATUSES.join(" / ")})`, existing.verificationStatus);
    if (status === null) return;
    const notes = window.prompt("Are there any notes related to this document?", existing.notes);
    if (notes === null) return;
    try {
      await attService.update(id, {
        documentTitle: title,
        source,
        dateText,
        uploadedBy,
        verificationStatus: status,
        notes,
      });
      await renderIntakeView(container, caseId, sectionId);
    } catch (err) {
      alert((err as Error).message);
    }
  });

  onDelegate(container, "click", "[data-att-remove]", async (el) => {
    const id = el.dataset.attRemove ?? "";
    const existing = await attService.get(id);
    if (!existing) return;
    const message = existing.evidenceId
      ? "Remove this attachment association? The linked evidence file is preserved in the case; only the association is removed."
      : "Remove this attachment record?";
    if (!window.confirm(message)) return;
    const result = await attService.removeAssociation(id);
    await renderIntakeView(container, caseId, sectionId);
    attStatus(result.evidencePreserved ? "Attachment removed; the linked evidence was preserved." : "Attachment removed.");
  });
}

function readAnswer(row: HTMLElement, q: IntakeQuestion): string {
  const input = row.querySelector<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>("[data-q-input]");
  if (!input) return "";
  if (q.type === "multi") {
    const boxes = Array.from(row.querySelectorAll<HTMLInputElement>("input[type=checkbox]:checked"));
    return JSON.stringify(boxes.map((b) => b.value));
  }
  return input.value;
}

function repeatIndexOf(questionId: string): number {
  const hash = questionId.indexOf("#");
  return hash === -1 ? 0 : Number(questionId.slice(hash + 1)) || 0;
}

function claimSuffix(q: IntakeQuestion): string {
  const idx = repeatIndexOf(q.id);
  return idx === 0 ? "" : ` (claim ${idx + 1})`;
}

function questionHtml(q: IntakeQuestion, response: IntakeResponseRecord | undefined, suffix: string): string {
  const answered = response?.status === "answered";
  const skipped = response?.status === "skipped";
  let value = "";
  if (answered) {
    try {
      const parsed = JSON.parse(response!.value) as unknown;
      value = Array.isArray(parsed) ? parsed.join(", ") : String(parsed);
    } catch {
      value = response!.value;
    }
  }
  let control: string;
  switch (q.type) {
    case "longText":
      control = `<textarea data-q-input rows="3" aria-label="${esc(q.prompt)}">${esc(value)}</textarea>`;
      break;
    case "select":
      control = `<select data-q-input aria-label="${esc(q.prompt)}">
        <option value="">— select —</option>
        ${(q.options ?? []).map((o) => `<option ${value === o ? "selected" : ""}>${esc(o)}</option>`).join("")}
      </select>`;
      break;
    case "multi":
      control = (q.options ?? [])
        .map((o) => {
          const selected = value.split(", ").includes(o);
          return `<label style="display:block"><input type="checkbox" data-q-input value="${esc(o)}" ${selected ? "checked" : ""}> ${esc(o)}</label>`;
        })
        .join("");
      break;
    case "date":
      control = `<input data-q-input type="date" value="${esc(value)}" aria-label="${esc(q.prompt)}">`;
      break;
    case "number":
      control = `<input data-q-input type="number" value="${esc(value)}" aria-label="${esc(q.prompt)}">`;
      break;
    default:
      control = `<input data-q-input type="text" value="${esc(value)}" aria-label="${esc(q.prompt)}">`;
  }
  return `
    <div class="case-row checklist-item" data-question="${esc(q.id)}">
      <div style="flex:1">
        <div class="case-title">${answered ? "✓" : skipped ? "→" : "□"} ${esc(q.prompt)}${suffix ? ` <span class="status-badge pending">${esc(suffix)}</span>` : ""}${q.required ? ' <span class="status-badge">required</span>' : ' <span class="status-badge pending">optional</span>'}</div>
        <div class="case-meta">source: ${esc(q.source)}${q.help ? ` • ${esc(q.help)}` : ""}${skipped ? " • skipped" : ""}</div>
        <div style="margin-top:6px;display:flex;gap:8px;flex-wrap:wrap;align-items:center;">
          ${control}
          <button class="back-button" data-save type="button">Save</button>
          ${!q.required ? `<button class="back-button" data-skip type="button">Skip</button>` : `<button class="back-button" data-skip type="button" title="Required questions may be skipped during the session but must be answered before finalization.">Skip (must revisit)</button>`}
        </div>
      </div>
    </div>`;
}
