/**
 * Multimedia capture hub for a case (TPI-V2-WEB-010 §17/§18/§19/§20, Phase 010E).
 *
 * One place to capture or import every media type for the current case, with
 * room association and intake/statement source classification, all routed
 * through the existing evidence pipeline (OPFS + SHA-256 + audit).
 *
 * Source classification follows the original models:
 *  - `PPRoomMedia.source`: capturedInApp / importedCameraRoll / importedBasecamp
 *  - `PPIntakeAttachment`: client-supplied material with a verification status
 *  - investigator recordings are distinguished from client-supplied material
 * Never presents client material as investigator observation, or vice versa.
 */
import "../dashboard/dashboard.css";
import { getDb } from "../../core/db";
import { CaseRepository } from "../../core/repositories/caseRepository";
import { EvidenceRepository } from "../../core/repositories/evidenceRepository";
import { AuditService } from "../../core/audit";
import { getManagedFileStore } from "../../core/files/storeRegistry";
import type { CaseRecord, EvidenceRecord } from "../../core/types";
import { esc, viewShell, wireBackButton } from "../dashboard/shell";
import { mountView, onDelegate, invalidateView } from "../../shared/uidom";
import { renderCaseHub } from "./CaseHub";

const db = () => getDb();

/** Original `PPRoomMediaSource` values (browser-adapted labels). */
export type MediaSource =
  | "investigatorCaptured"
  | "clientSupplied"
  | "importedExternal";

export const SOURCE_LABELS: Record<MediaSource, string> = {
  investigatorCaptured: "Investigator-recorded (in app)",
  clientSupplied: "Client-supplied (statement attachment)",
  importedExternal: "Imported from external source",
};

/** Original `PPMediaPhase`. */
export type MediaPhase = "walkthrough" | "investigation";

interface MultimediaUiState {
  caseId: string;
  roomId: string;
  source: MediaSource;
  phase: MediaPhase;
  status: string;
  objectUrls: string[];
}

const ui = new WeakMap<HTMLElement, MultimediaUiState>();

function st(container: HTMLElement, caseId: string): MultimediaUiState {
  let s = ui.get(container);
  if (!s || s.caseId !== caseId) {
    s = { caseId, roomId: "", source: "investigatorCaptured", phase: "investigation", status: "", objectUrls: [] };
    ui.set(container, s);
  }
  return s;
}

function releaseUrls(s: MultimediaUiState): void {
  for (const url of s.objectUrls) URL.revokeObjectURL(url);
  s.objectUrls = [];
}

export async function renderMultimedia(container: HTMLElement, caseId: string): Promise<void> {
  const record = await new CaseRepository(db()).getCase(caseId);
  if (!record) {
    invalidateView(container);
    mountView(container, viewShell("Multimedia Capture", `<div class="cc-empty">Case not found.</div>`));
    wireBackButton(container);
    return;
  }
  const s = st(container, caseId);
  const structure = await db().propertyStructures.where("caseId").equals(caseId).first();
  const rooms = structure
    ? (await db().structureRooms.where("structureId").equals(structure.id).toArray()).filter((r) => !r.archived)
    : [];
  const media = (await db().evidence.where("caseId").equals(caseId).toArray())
    .filter((e) => e.mediaType === "audio" || e.mediaType === "photo" || e.mediaType === "video")
    .sort((a, b) => b.createdAt - a.createdAt);
  const originals = media.filter((m) => m.kind === "original");
  const derived = media.filter((m) => m.kind === "derived");

  releaseUrls(s);
  const thumbs = new Map<string, string>();
  for (const item of media.filter((m) => m.mediaType === "photo").slice(0, 24)) {
    try {
      const bytes = await getManagedFileStore().read(item.opfsPath);
      if (!bytes) continue;
      const url = URL.createObjectURL(new Blob([bytes], { type: item.mimeType ?? "image/*" }));
      s.objectUrls.push(url);
      thumbs.set(item.id, url);
    } catch {
      /* thumbnail unavailable */
    }
  }

  const sessions = await db().sessions.where("caseId").equals(caseId).toArray();

  invalidateView(container);
  mountView(
    container,
    viewShell(
      `Multimedia Capture — ${record.caseNumber}`,
      `
      <div class="case-form" data-root="multimedia" data-case-id="${esc(caseId)}" data-epoch="${Date.now()}-${Math.random()}">
        <p class="cc-count">Original media: <strong>${originals.length}</strong> • derived: ${derived.length} • total stored ${Math.round(media.reduce((n, m) => n + m.fileSizeBytes, 0) / 1024)} KB</p>

        <h3 class="cc-section-title">Capture &amp; Import Context</h3>
        <div class="detail-grid">
          <div class="detail-field"><label for="mm-room">Room / area</label>
            <select id="mm-room">
              <option value="">Unassigned</option>
              ${rooms.map((r) => `<option value="${r.id}"${s.roomId === r.id ? " selected" : ""}>${esc(r.name)}</option>`).join("")}
            </select></div>
          <div class="detail-field"><label for="mm-source">Material source (classification)</label>
            <select id="mm-source">
              ${(Object.keys(SOURCE_LABELS) as MediaSource[]).map((k) => `<option value="${k}"${s.source === k ? " selected" : ""}>${esc(SOURCE_LABELS[k])}</option>`).join("")}
            </select></div>
          <div class="detail-field"><label for="mm-phase">Investigation phase</label>
            <select id="mm-phase">
              <option value="walkthrough"${s.phase === "walkthrough" ? " selected" : ""}>Walkthrough</option>
              <option value="investigation"${s.phase === "investigation" ? " selected" : ""}>Investigation</option>
            </select></div>
          <div class="detail-field"><label for="mm-session">Session (optional)</label>
            <select id="mm-session">
              <option value="">— none —</option>
              ${sessions.map((x) => `<option value="${x.id}">${esc(x.status)} — ${new Date(x.startedAt).toLocaleString()}</option>`).join("")}
            </select></div>
        </div>
        <p class="cc-meta">Client-supplied material is recorded as a client statement attachment — it is never presented as investigator observation. Originals are stored unchanged with a SHA-256 digest.</p>

        <h3 class="cc-section-title">Import Media</h3>
        <div class="detail-field"><label for="mm-files">Files (audio, images, video)</label>
          <input id="mm-files" type="file" accept="audio/*,image/*,video/*" multiple></div>
        <div class="detail-field"><label for="mm-note">Source description / statement context</label>
          <input id="mm-note" type="text" placeholder="e.g. Client emailed this phone recording from the night of the 12th"></div>
        <div class="form-actions">
          <button class="button-primary" id="mm-import" type="button">Import to Case</button>
          <button class="button-secondary" id="mm-camera" type="button">Capture Photo…</button>
        </div>
        <p class="cc-meta" id="mm-status" role="status">${esc(s.status)}</p>

        <h3 class="cc-section-title">Dedicated Tools</h3>
        <div class="form-actions">
          <button class="button-secondary" id="mm-evp" type="button">EVP Recorder</button>
          <button class="button-secondary" id="mm-analysis" type="button">Audio Analysis</button>
          <button class="button-secondary" id="mm-darkroom" type="button">Dark Room</button>
          <button class="button-secondary" id="mm-video" type="button">Video Analysis</button>
        </div>

        <h3 class="cc-section-title">Case Media (${media.length})</h3>
        ${
          media.length === 0
            ? '<div class="cc-empty">No media captured or imported for this case yet.</div>'
            : media
                .map((m) => {
                  const thumb = thumbs.get(m.id);
                  const params = m.derivationParameters
                    ? Object.entries(m.derivationParameters)
                        .map(([k, v]) => `${k}: ${String(v)}`)
                        .join(" • ")
                    : "";
                  return `
          <div class="case-row" data-media="${m.id}">
            <div style="display:flex;gap:12px;align-items:flex-start;">
              ${
                thumb
                  ? `<img src="${thumb}" alt="" width="56" height="56" style="object-fit:cover;border-radius:8px;border:1px solid var(--border);">`
                  : `<div aria-hidden="true" style="width:56px;height:56px;border-radius:8px;border:1px solid var(--border);background:var(--background-deep);display:grid;place-items:center;color:var(--text-tertiary);font-size:10px;">${esc(m.mediaType)}</div>`
              }
              <div>
                <div class="case-title">${esc(m.title)} ${m.kind === "derived" ? '<span class="status-badge pending">DERIVED</span>' : '<span class="status-badge implemented">ORIGINAL</span>'}</div>
                <div class="case-meta">
                  ${esc(m.mediaType)} • ${Math.round(m.fileSizeBytes / 1024)} KB • ${new Date(m.captureTimestamp ?? m.acquiredAt).toLocaleString()} • ${esc(m.captureTimestampSource ?? "unknown")}<br>
                  ${m.roomId ? `room: ${esc(rooms.find((r) => r.id === m.roomId)?.name ?? "(archived room)")} • ` : ""}
                  ${m.parentId ? "derived from an original • " : ""}
                  integrity: ${esc(m.verificationStatus ?? "unverified")}
                  ${params ? `<br>${esc(params)}` : ""}
                  ${m.sourceDescription ? `<br>${esc(m.sourceDescription)}` : ""}
                </div>
              </div>
            </div>
          </div>`;
                })
                .join("")
        }

        <div class="form-actions"><button class="back-button" id="mm-back" type="button">← Back to Case Hub</button></div>
      </div>
    `,
  ));

  wireHandlers(container, caseId, rooms);
  wireBackButton(container);
}

function wireHandlers(container: HTMLElement, caseId: string, rooms: Array<{ id: string; name: string }>): void {
  const s = st(container, caseId);
  const reload = () => renderMultimedia(container, caseId);
  const roomId = () => container.querySelector<HTMLSelectElement>("#mm-room")?.value || null;
  const sessionId = () => container.querySelector<HTMLSelectElement>("#mm-session")?.value || null;
  const source = () => (container.querySelector<HTMLSelectElement>("#mm-source")?.value ?? "investigatorCaptured") as MediaSource;
  const phase = () => (container.querySelector<HTMLSelectElement>("#mm-phase")?.value ?? "investigation") as MediaPhase;
  const note = () => container.querySelector<HTMLInputElement>("#mm-note")?.value ?? "";

  onDelegate(container, "click", "#mm-back", () => void renderCaseHub(container, caseId));
  onDelegate(container, "change", "#mm-room", (el) => {
    s.roomId = (el as HTMLSelectElement).value;
  });
  onDelegate(container, "change", "#mm-source", (el) => {
    s.source = (el as HTMLSelectElement).value as MediaSource;
  });
  onDelegate(container, "change", "#mm-phase", (el) => {
    s.phase = (el as HTMLSelectElement).value as MediaPhase;
  });

  const importMedia = async (files: File[]): Promise<void> => {
    const repo = new EvidenceRepository(db());
    let count = 0;
    for (const file of files) {
      const mediaType = file.type.startsWith("image/") ? "photo" : file.type.startsWith("video/") ? "video" : file.type.startsWith("audio/") ? "audio" : "document";
      const record = await repo.storeOriginal({
        caseId,
        sessionId: sessionId() ?? undefined,
        mediaType,
        title: file.name.replace(/\.[^.]+$/, "") || file.name,
        fileName: file.name,
        data: file,
        origin: source(),
        recordedBy: source() === "clientSupplied" ? "client-supplied" : "local-user",
      });
      await db().evidence.put({
        ...record,
        originalFileName: file.name,
        sourceDescription: `${SOURCE_LABELS[source()]}${note() ? ` — ${note()}` : ""}`,
        importedAt: Date.now(),
        verificationStatus: "verified",
        verifiedAt: Date.now(),
        verificationDetail: "Stored unchanged on import and hashed.",
        roomId: roomId(),
        markerId: null,
        measurementId: null,
        captureTimestamp: file.lastModified || null,
        captureTimestampSource: file.lastModified ? "fileMetadata" : "unknown",
        notes: `Phase: ${phase()}`,
      });
      count += 1;
    }
    await new AuditService(db()).record("evidenceImported", `Multimedia imported (${SOURCE_LABELS[source()]}).`, {
      caseId,
      affectedRecordId: undefined,
      metadata: { files: count, source: source(), phase: phase() },
    });
    s.status = `${count} file(s) imported as ${SOURCE_LABELS[source()]}.`;
    await reload();
  };

  onDelegate(container, "click", "#mm-import", async () => {
    const files = Array.from(container.querySelector<HTMLInputElement>("#mm-files")?.files ?? []);
    if (files.length === 0) {
      s.status = "Select at least one file to import.";
      await reload();
      return;
    }
    await importMedia(files);
  });

  onDelegate(container, "click", "#mm-camera", async () => {
    if (!navigator.mediaDevices?.getUserMedia) {
      s.status = "This browser cannot access a camera. Use Import to add photos instead.";
      await reload();
      return;
    }
    let stream: MediaStream | null = null;
    try {
      stream = await navigator.mediaDevices.getUserMedia({ video: true });
      const video = document.createElement("video");
      video.srcObject = stream;
      await video.play();
      await new Promise((resolve) => setTimeout(resolve, 350));
      const canvas = document.createElement("canvas");
      canvas.width = video.videoWidth || 1280;
      canvas.height = video.videoHeight || 720;
      canvas.getContext("2d")?.drawImage(video, 0, 0, canvas.width, canvas.height);
      const blob = await new Promise<Blob | null>((resolve) => canvas.toBlob((b) => resolve(b), "image/png"));
      if (!blob) throw new Error("frame could not be encoded");
      await importMedia([new File([blob], `photo_${Date.now()}.png`, { type: "image/png" })]);
    } catch (err) {
      s.status =
        (err as { name?: string }).name === "NotAllowedError"
          ? "Camera permission was denied. Use Import to add photos instead."
          : `Camera capture failed: ${(err as Error).message}`;
      await reload();
    } finally {
      if (stream) for (const track of stream.getTracks()) track.stop();
    }
  });

  onDelegate(container, "click", "#mm-evp", async () => {
    const { renderEvpRecorder } = await import("../equipment/EvpRecorder");
    await renderEvpRecorder(container, caseId);
  });
  onDelegate(container, "click", "#mm-analysis", async () => {
    const { renderAudioAnalysis } = await import("../forensic/AudioAnalysis");
    await renderAudioAnalysis(container);
  });
  onDelegate(container, "click", "#mm-darkroom", async () => {
    const { renderDarkRoom } = await import("../forensic/DarkRoom");
    await renderDarkRoom(container);
  });
  onDelegate(container, "click", "#mm-video", async () => {
    const { renderVideoAnalysis } = await import("../forensic/VideoAnalysis");
    await renderVideoAnalysis(container);
  });
  void rooms;
}

/** Evidence rows for a case that belong to a given room (used by tests/tools). */
export async function mediaForRoom(caseId: string, roomId: string): Promise<EvidenceRecord[]> {
  return (await db().evidence.where("caseId").equals(caseId).toArray()).filter((e) => e.roomId === roomId);
}

export type { CaseRecord };
