/**
 * OPFS storage helpers (Directive §8). Evidence bytes are stored under
 * deterministic case-scoped paths: cases/{caseId}/evidence/{evidenceId}-...
 * storage.estimate() is used for quota checks where supported.
 */
import type { Provenance } from "../types";

export type { Provenance };

async function getRoot(): Promise<FileSystemDirectoryHandle> {
  return navigator.storage.getDirectory();
}

async function ensureDirectory(
  parent: FileSystemDirectoryHandle,
  name: string,
): Promise<FileSystemDirectoryHandle> {
  return parent.getDirectoryHandle(name, { create: true });
}

/** Resolve a relative opfsPath such as "cases/{caseId}/evidence/xyz". */
async function resolvePath(path: string): Promise<FileSystemFileHandle> {
  const parts = path.split("/").filter((p) => p.length > 0);
  const fileName = parts[parts.length - 1] as string;
  let dir = await getRoot();
  for (const segment of parts.slice(0, -1)) {
    dir = await dir.getDirectoryHandle(segment);
  }
  return dir.getFileHandle(fileName);
}

/** Storage quota estimate (usage + quota in bytes) where supported. */
export async function storageEstimate(): Promise<{
  usage: number;
  quota: number;
} | undefined> {
  if (!navigator.storage?.estimate) return undefined;
  const { usage = 0, quota = 0 } = await navigator.storage.estimate();
  return { usage, quota };
}

/**
 * Request persistent storage. Browsers may still deny or later evict data;
 * users must be told browser settings, device cleanup, and profile deletion
 * can remove stored investigation data.
 */
export async function requestPersistentStorage(): Promise<boolean> {
  if (!navigator.storage?.persisted || !navigator.storage?.persist) return false;
  if (await navigator.storage.persisted()) return true;
  return navigator.storage.persist();
}

export async function storeCaseFile(
  caseId: string,
  fileName: string,
  data: ArrayBuffer | Blob,
): Promise<{ path: string; contentHash: string }> {
  const root = await getRoot();
  const casesDir = await ensureDirectory(root, "cases");
  const caseDir = await ensureDirectory(casesDir, caseId);
  const segments = fileName.split("/");
  let dir = caseDir;
  for (const segment of segments.slice(0, -1)) {
    dir = await ensureDirectory(dir, segment);
  }
  const fileHandle = await dir.getFileHandle(segments[segments.length - 1] as string, {
    create: true,
  });
  const writable = await fileHandle.createWritable();
  await writable.write(data);
  await writable.close();

  const { hashBlob } = await import("./opfs.hash");
  const contentHash = await hashBlob(data);
  return { path: `cases/${caseId}/${fileName}`, contentHash };
}

export async function readCasePath(path: string): Promise<ArrayBuffer | undefined> {
  try {
    const handle = await resolvePath(path);
    const file = await handle.getFile();
    return await file.arrayBuffer();
  } catch {
    return undefined;
  }
}

/** Legacy read helper by case id + file name (pre-v2 paths). */
export async function readCaseFile(
  caseId: string,
  fileName: string,
): Promise<ArrayBuffer | undefined> {
  try {
    const root = await getRoot();
    const caseDir = await root.getDirectoryHandle("cases");
    const dir = await caseDir.getDirectoryHandle(caseId);
    const handle = await dir.getFileHandle(fileName);
    const file = await handle.getFile();
    return await file.arrayBuffer();
  } catch {
    return undefined;
  }
}

/** Verify a stored file still matches its recorded integrity hash. */
export async function verifyCaseFile(
  caseId: string,
  fileName: string,
  expectedHash: string,
): Promise<boolean> {
  const data = await readCaseFile(caseId, fileName);
  if (!data) return false;
  const { hashBlob } = await import("./opfs.hash");
  return (await hashBlob(data)) === expectedHash;
}
