/**
 * Mystic floating chatbot (TPI-V2-WEB-009B §11–§14).
 *
 * Faithful restoration of the original iPad interface:
 *  - expands by default (`PPAssistantPanelState.presentationState = .expanded`);
 *  - minimizes to the original "Wake Mystic / Tap to reopen" pill;
 *  - avatar, MYSTIC / Paranormal Assistant chrome, MANUAL badge, gear,
 *    minimize, recent-history area, active-response row, "Type a reply" input,
 *    mic, clear, send, drag handle — per UI/AI/PPAssistantPanelChrome.swift and
 *    the owner's reference screenshots.
 *
 * Structural note: the chatbot is mounted ONCE on its own root element outside
 * the routed view container, so view re-renders can never destroy it or a
 * typed draft (WP-9 §23 / directive §14).
 *
 * Honesty (§12): no AI engine is operating. Messages are acknowledged locally
 * with an explicit notice — the interface is restored, the intelligence is not
 * fabricated.
 */
import "./mystic.css";

export type MysticState = "expanded" | "minimized";

const STATE_KEY = "tpi.mystic.state";
const HISTORY_KEY = "tpi.mystic.history";
const DRAFT_KEY = "tpi.mystic.draft";
const SIZE_KEY = "tpi.mystic.height";

interface HistoryEntry {
  who: "You" | "Mystic";
  text: string;
  notice?: boolean;
}

const GHOST = "/assets/mystic/PPGhostBrand.png";

const ICONS = {
  gear:
    '<path d="M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8zm8.9 4c0-.6-.1-1.2-.2-1.8l2-1.6-2-3.4-2.4 1a7.7 7.7 0 0 0-3-1.8L15 2h-4l-.3 2.4a7.7 7.7 0 0 0-3 1.8l-2.4-1-2 3.4 2 1.6a7.9 7.9 0 0 0 0 3.6l-2 1.6 2 3.4 2.4-1a7.7 7.7 0 0 0 3 1.8L11 22h4l.3-2.4a7.7 7.7 0 0 0 3-1.8l2.4 1 2-3.4-2-1.6c.1-.6.2-1.2.2-1.8z"/>',
  minus: '<rect x="5" y="11" width="14" height="2" rx="1"/>',
  mic: '<path d="M12 15a3 3 0 0 0 3-3V6a3 3 0 1 0-6 0v6a3 3 0 0 0 3 3zm5-3a5 5 0 0 1-10 0H5a7 7 0 0 0 6 6.9V21h2v-2.1A7 7 0 0 0 19 12h-2z"/>',
  trash:
    '<path d="M6 7h12l-1 13a2 2 0 0 1-2 2H9a2 2 0 0 1-2-2L6 7zm3-3h6l1 1h4v2H4V5h4l1-1zM9 9v9h1.5V9H9zm4.5 0v9H15V9h-1.5z"/>',
  send: '<path d="M12 4l7 7h-4v7h-6v-7H5l7-7z"/>',
  pencil:
    '<path d="M4 20h4L19 9l-4-4L4 16v4zm13.7-12.3l2.6-2.6 1.9 1.9-2.6 2.6-1.9-1.9z"/>',
};

let root: HTMLElement | null = null;
let state: MysticState = "expanded";
let history: HistoryEntry[] = [];
let draft = "";

function load(): void {
  try {
    const stored = localStorage.getItem(STATE_KEY);
    state = stored === "minimized" ? "minimized" : "expanded"; // default: expanded
    const storedHistory = localStorage.getItem(HISTORY_KEY);
    history = storedHistory ? (JSON.parse(storedHistory) as HistoryEntry[]) : [];
    draft = localStorage.getItem(DRAFT_KEY) ?? "";
  } catch {
    state = "expanded";
    history = [];
    draft = "";
  }
}

function persist(): void {
  try {
    localStorage.setItem(STATE_KEY, state);
    localStorage.setItem(HISTORY_KEY, JSON.stringify(history.slice(-100)));
    localStorage.setItem(DRAFT_KEY, draft);
  } catch {
    /* storage unavailable — the UI still works for this session */
  }
}

function saveDraftFromInput(): void {
  const input = root?.querySelector<HTMLInputElement>("#mystic-input");
  if (input) draft = input.value;
  persist();
}

export function getMysticState(): MysticState {
  return state;
}

function historyHtml(): string {
  if (history.length === 0) {
    return `<div class="history-label">Recent history</div>
      <div class="entry notice">No messages yet. Mystic is in manual mode.</div>`;
  }
  return (
    `<div class="history-label">Recent history</div>` +
    history
      .slice(-40)
      .map(
        (e) =>
          `<div class="entry${e.who === "Mystic" ? " mystic" : ""}${e.notice ? " notice" : ""}"><span class="who">${e.who}</span>${escapeText(e.text)}</div>`,
      )
      .join("")
  );
}

function escapeText(text: string): string {
  return text.replace(/[&<>"']/g, (c) => {
    switch (c) {
      case "&": return "&amp;";
      case "<": return "&lt;";
      case ">": return "&gt;";
      case '"': return "&quot;";
      default: return "&#39;";
    }
  });
}

function render(): void {
  // The minimized pill is fixed over routed content. The report workspace uses
  // this state to reserve clearance on narrow screens; expanded/desktop layout
  // is unchanged.
  document.body.classList.toggle("mystic-minimized", state === "minimized");
  if (!root) return;
  const savedHeight = (() => {
    try {
      return localStorage.getItem(SIZE_KEY);
    } catch {
      return null;
    }
  })();
  const heightStyle = savedHeight ? `height:${savedHeight};` : "";

  if (state === "expanded") {
    root.innerHTML = `
      <section class="mystic-chat" style="${heightStyle}" aria-label="Mystic paranormal assistant" data-mystic="chat">
        <header class="mystic-head">
          <div class="mystic-avatar" aria-hidden="true">
            <span class="avatar-ring"></span>
            <span class="avatar-ping"></span>
            <img src="${GHOST}" alt="" />
          </div>
          <div class="mystic-titles">
            <span class="mystic-eyebrow">Mystic</span>
            <span class="mystic-name">Paranormal Assistant</span>
          </div>
          <span class="mystic-spacer"></span>
          <span class="mystic-mode" title="Manual mode — no AI engine is operating">MANUAL</span>
          <button class="mystic-icon-btn" id="mystic-settings" type="button" aria-label="Mystic settings">
            <svg viewBox="0 0 24 24" aria-hidden="true">${ICONS.gear}</svg>
          </button>
          <button class="mystic-icon-btn" id="mystic-minimize" type="button" aria-label="Minimize Mystic">
            <svg viewBox="0 0 24 24" aria-hidden="true">${ICONS.minus}</svg>
          </button>
        </header>
        <div class="mystic-history" id="mystic-history" aria-live="polite">${historyHtml()}</div>
        <div class="mystic-active" aria-label="Active response source">
          <svg viewBox="0 0 24 24" aria-hidden="true">${ICONS.pencil}</svg>
          <div>
            <div class="label">Active response</div>
            <div class="value">Paranormal Assistant</div>
          </div>
        </div>
        <div class="mystic-inputbar">
          <input id="mystic-input" type="text" placeholder="Type a reply" aria-label="Message Mystic" value="${escapeText(draft)}" autocomplete="off" />
          <button class="mystic-mic" id="mystic-mic" type="button" aria-label="Voice input (not available yet)">
            <svg viewBox="0 0 24 24" aria-hidden="true">${ICONS.mic}</svg>
          </button>
        </div>
        <div class="mystic-actions">
          <button class="mystic-btn trash" id="mystic-clear" type="button" aria-label="Clear conversation">
            <svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">${ICONS.trash}</svg>
          </button>
          <button class="mystic-btn send" id="mystic-send" type="button" aria-label="Send message">
            <svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">${ICONS.send}</svg>
          </button>
        </div>
        <div class="mystic-drag-handle" aria-hidden="true"></div>
        <div id="mystic-resize" title="Drag to resize" aria-hidden="true" style="position:absolute;right:6px;bottom:6px;width:14px;height:14px;cursor:ns-resize;color:var(--text-tertiary);">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 20L20 4M14 4h6v6M10 20H4v-6"/></svg>
        </div>
      </section>`;
  } else {
    root.innerHTML = `
      <button class="mystic-pill" id="mystic-wake" type="button" aria-label="Wake Mystic — tap to reopen the assistant">
        <img src="${GHOST}" alt="" />
        <span class="pill-titles">
          <span class="pill-title">Wake Mystic</span>
          <span class="pill-sub">Tap to reopen</span>
        </span>
        <svg class="pill-chevron" viewBox="0 0 24 24" aria-hidden="true"><path d="M6 15l6-6 6 6"/></svg>
      </button>`;
  }
  wire();
}

function pushEntry(entry: HistoryEntry): void {
  history.push(entry);
  if (history.length > 100) history = history.slice(-100);
  persist();
}

function appendToHistory(): void {
  const el = root?.querySelector<HTMLElement>("#mystic-history");
  if (!el) return;
  el.innerHTML = historyHtml();
  el.scrollTop = el.scrollHeight;
}

function sendMessage(): void {
  const input = root?.querySelector<HTMLInputElement>("#mystic-input");
  const text = input?.value.trim() ?? "";
  if (!text) return;
  pushEntry({ who: "You", text });
  pushEntry({
    who: "Mystic",
    text: "Recorded locally. The Mystic decision engine is not operating in this build — no AI response is generated, and nothing leaves this device.",
    notice: true,
  });
  if (input) input.value = "";
  draft = "";
  persist();
  appendToHistory();
  const active = root?.querySelector<HTMLElement>(".mystic-active .value");
  if (active) active.textContent = "Paranormal Assistant (notice only)";
}

function wire(): void {
  const chat = root?.querySelector<HTMLElement>("[data-mystic='chat']");
  const pill = root?.querySelector<HTMLElement>("#mystic-wake");

  pill?.addEventListener("click", () => {
    state = "expanded";
    persist();
    render();
    root?.querySelector<HTMLInputElement>("#mystic-input")?.focus();
  });

  if (!chat) return;

  root?.querySelector("#mystic-minimize")?.addEventListener("click", () => {
    saveDraftFromInput();
    state = "minimized";
    persist();
    render();
  });

  root?.querySelector("#mystic-settings")?.addEventListener("click", () => {
    pushEntry({
      who: "Mystic",
      text: "Settings arrive with a future build. The interface is restored; no settings are faked here.",
      notice: true,
    });
    appendToHistory();
  });

  root?.querySelector("#mystic-clear")?.addEventListener("click", () => {
    history = [];
    persist();
    appendToHistory();
    const active = root?.querySelector<HTMLElement>(".mystic-active .value");
    if (active) active.textContent = "Paranormal Assistant";
  });

  root?.querySelector("#mystic-mic")?.addEventListener("click", () => {
    pushEntry({
      who: "Mystic",
      text: "Voice input arrives with a future build.",
      notice: true,
    });
    appendToHistory();
  });

  root?.querySelector("#mystic-send")?.addEventListener("click", sendMessage);

  const input = root?.querySelector<HTMLInputElement>("#mystic-input");
  input?.addEventListener("keydown", (e) => {
    if (e.key === "Enter") {
      e.preventDefault();
      sendMessage();
    }
  });
  // Preserve drafts across any unrelated UI activity (directive §14).
  input?.addEventListener("input", () => {
    draft = input.value;
    try {
      localStorage.setItem(DRAFT_KEY, draft);
    } catch {
      /* storage unavailable */
    }
  });
  input?.addEventListener("blur", saveDraftFromInput);

  // Resize (original has a resize control) — vertical drag adjusts height.
  const handle = root?.querySelector<HTMLElement>("#mystic-resize");
  handle?.addEventListener("pointerdown", (e) => {
    e.preventDefault();
    const startY = e.clientY;
    const startHeight = chat.getBoundingClientRect().height;
    const onMove = (ev: PointerEvent) => {
      const next = Math.max(420, Math.min(window.innerHeight - 80, startHeight + (startY - ev.clientY)));
      chat.style.height = `${next}px`;
    };
    const onUp = () => {
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp);
      try {
        localStorage.setItem(SIZE_KEY, `${Math.round(chat.getBoundingClientRect().height)}px`);
      } catch {
        /* storage unavailable */
      }
    };
    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);
  });
}

/** Open the chatbot from the dashboard "Wake Mystic" control. */
export function expandMystic(): void {
  mountMystic();
  state = "expanded";
  persist();
  render();
  root?.querySelector<HTMLInputElement>("#mystic-input")?.focus();
}

/** Mount once, outside the routed view container. Safe to call repeatedly. */
export function mountMystic(): void {
  if (root) return;
  root = document.createElement("div");
  root.id = "mystic-root";
  root.dataset.testid = "mystic-root";
  document.body.appendChild(root);
  load();
  render();
}

/** Exposed for tests. */
export function mysticSnapshot(): { state: MysticState; historyLength: number; draft: string } {
  return { state, historyLength: history.length, draft };
}

/** Test/session seam: reset to defaults (expanded, empty). */
export function resetMysticForTesting(): void {
  state = "expanded";
  history = [];
  draft = "";
  try {
    localStorage.removeItem(STATE_KEY);
    localStorage.removeItem(HISTORY_KEY);
    localStorage.removeItem(DRAFT_KEY);
  } catch {
    /* ignore */
  }
  if (root) render();
}