/**
 * Room layout element catalog (TPI-V2-WEB-010G §5–§8, Phase 010G-A).
 *
 * Verbatim port of the catalog in `Core/PPRoomLayoutElement.swift`:
 * 6 categories, 44 element kinds, 4 size presets, per-kind supported/default
 * sizes, and the exact `canvasSize(for:size:canvas:)` fractions.
 *
 * Symbol glyphs: the original used SF Symbols by name (`symbolName`); those are
 * not redistributable files, so equivalent stroke glyphs are drawn here at the
 * original sizes — the catalog data (categories, names, sizes, fractions) is
 * unchanged. See docs/ROOM_LAYOUT_ELEMENTS.md.
 */

export type LayoutElementCategory =
  | "doors"
  | "windows"
  | "environmental"
  | "structure"
  | "fixtures"
  | "objects";

/** Original category display names (PPRoomLayoutElementCategory). */
export const CATEGORY_NAMES: Record<LayoutElementCategory, string> = {
  doors: "Doors",
  windows: "Windows",
  environmental: "Environmental Sources",
  structure: "Structural Features",
  fixtures: "Bath & Kitchen",
  objects: "Objects",
};

export type LayoutElementSize = "small" | "medium" | "large" | "wide";

/** Original size display names (PPRoomLayoutElementSize). */
export const SIZE_NAMES: Record<LayoutElementSize, string> = {
  small: "Small",
  medium: "Medium",
  large: "Large",
  wide: "Wide",
};

/** Original anchor relations (PPRoomLayoutAnchorRelation). */
export type AnchorRelation = "none" | "above" | "under";
export const ANCHOR_NAMES: Record<AnchorRelation, string> = {
  none: "None",
  above: "Above",
  under: "Under",
};

/** Original vent styles (PPRoomLayoutVentStyle). */
export type VentStyle = "wall" | "floor";
export const VENT_NAMES: Record<VentStyle, string> = { wall: "Wall Vent", floor: "Floor Vent" };

/** Original light styles (PPRoomLayoutLightStyle). */
export type LightStyle = "ceiling" | "wall";
export const LIGHT_NAMES: Record<LightStyle, string> = { ceiling: "Ceiling Light", wall: "Wall Light" };

export type LayoutElementKind =
  | "singleDoor" | "doubleDoor" | "closetDoor"
  | "windowSmall" | "windowLarge"
  | "wallSegment" | "archway" | "closet" | "staircase" | "staircaseLanding"
  | "outlet" | "breakerPanel" | "electricalBox" | "servicePanel" | "emergencyBackupLight"
  | "wallSwitch" | "wallSwitchAlt" | "ventHVAC" | "returnVent" | "heater"
  | "radiatorOldStyle" | "wallAC" | "baseboardHeat" | "lightFixture" | "ceilingFan"
  | "recessedLight" | "wallLight" | "fireplace" | "woodStove"
  | "shower" | "vanity" | "bathroomSink" | "counter" | "kitchenSink" | "cabinetRun"
  | "stovePosition" | "refrigeratorPosition"
  | "bed" | "couch" | "table" | "chair" | "dresser" | "shelf";

/** Original `dims(sw, mw, lw, sh, mh, lh)` helper. */
type Dims = readonly [number, number, number, number, number, number];

interface KindSpec {
  /** Original display name. */
  name: string;
  category: LayoutElementCategory;
  /** Original `symbolName` (kept for provenance; browser draws its own glyph). */
  symbolName: string;
  supportedSizes: readonly LayoutElementSize[];
  defaultSize: LayoutElementSize;
  /** Size fractions; `wide` derived as max(largeW, 0.22) × medH (original rule). */
  dims: Dims;
}

