/** Kinds grouped by category, in the original order. */
export const KINDS_BY_CATEGORY: Array<{ category: LayoutElementCategory; kinds: LayoutElementKind[] }> = (
  Object.keys(CATEGORY_NAMES) as LayoutElementCategory[]
).map((category) => ({
  category,
  kinds: (Object.keys(LAYOUT_ELEMENT_KINDS) as LayoutElementKind[]).filter(
    (k) => LAYOUT_ELEMENT_KINDS[k].category === category,
  ),
}));

/**
 * Original `canvasSize(for:size:canvas:)` — returns width/height as fractions of
 * the room canvas (the browser stores room geometry as fractions, so no pixel
 * canvas is needed).
 */
export function elementFootprint(kind: LayoutElementKind, size: LayoutElementSize): { width: number; height: number } {
  const [sw, mw, lw, sh, mh, lh] = LAYOUT_ELEMENT_KINDS[kind].dims;
  const clampSize = (s: LayoutElementSize): LayoutElementSize =>
    LAYOUT_ELEMENT_KINDS[kind].supportedSizes.includes(s) ? s : LAYOUT_ELEMENT_KINDS[kind].defaultSize;
  switch (clampSize(size)) {
    case "small":
      return { width: sw, height: sh };
    case "large":
      return { width: lw, height: lh };
    case "wide":
      return { width: Math.max(lw, 0.22), height: mh };
    case "medium":
    default:
      return { width: mw, height: mh };
  }
}

/** Portrait or landscape footprint after rotation (the original rotated bounds). */
export function rotatedFootprint(
  footprint: { width: number; height: number },
  rotationDegrees: number,
): { width: number; height: number } {
  const quarterTurns = Math.round(((rotationDegrees % 360) + 360) % 360 / 90) % 2;
  return quarterTurns === 1
    ? { width: footprint.height, height: footprint.width }
    : { width: footprint.width, height: footprint.height };
}

/** Which conditional properties apply to a kind (original conditionals). */
export function conditionalProperties(kind: LayoutElementKind): {
  anchor: boolean;
  vent: boolean;
  light: boolean;
} {
  return {
    anchor: kind === "outlet",
    vent: kind === "ventHVAC",
    light: kind === "lightFixture",
  };
}

/** Total catalog size, asserted by tests so the count can never drift silently. */
export const CATALOG_KIND_COUNT = Object.keys(LAYOUT_ELEMENT_KINDS).length;
export const CATEGORY_COUNT = Object.keys(CATEGORY_NAMES).length;
