/**
 * Walkthrough service (TPI-V2-WEB-007).
 *
 * iOS origins: CaseWalkthroughView / CaseWalkthroughRoomWorkspaceView,
 * PPInvestigationNote kinds, PPWalkthroughEditLog, InvestigationSessionManager
 * walkthrough completion. Multiple sessions per case are supported; previous
 * sessions are never overwritten.
 *
 * Observation discipline (directive §12): every observation carries a source
 * classification — reported (client/witness), observed (investigator),
 * measured (identified instrument), interpreted (assessment). Reported items
 * are never transformed into verified observations.
 */
import type { TPIDatabase } from "../db";
import { SCHEMA_VERSION } from "../db";
import { v4 as uuidv4 } from "../../shared/uuid";
import type { ObservationKind, RoomRecord, WalkthroughObservationRecord, WalkthroughSessionRecord } from "../types";
import { ValidationError } from "../validation";
import { AuditService } from "../audit";
import type { PropertyService } from "./propertyService";

export interface WalkthroughBlocker {
  sessionId: string | null;
  roomId: string | null;
  roomName: string;
  reason: string;
  requiredAction: string;
  nonOverridable: boolean;
}

export class WalkthroughService {
  private readonly audit: AuditService;

  constructor(
    private readonly db: TPIDatabase,
    private readonly property: PropertyService,
  ) {
    this.audit = new AuditService(db);
  }

  async startSession(caseId: string, investigator: string, locationId?: string | null): Promise<WalkthroughSessionRecord> {
    const caseRecord = await this.db.cases.get(caseId);
    if (!caseRecord) throw new ValidationError(`Case not found: ${caseId}`, "caseId");
    const structure = await this.property.ensureStructureForCase(caseId);
    const ts = Date.now();
    const session: WalkthroughSessionRecord = {
      id: uuidv4(),
      schemaVersion: SCHEMA_VERSION,
      createdAt: ts,
      updatedAt: ts,
      caseId,
      locationId: locationId ?? caseRecord.locationId ?? null,
      structureId: structure.id,
      startedAt: ts,
      completedAt: null,
      status: "active",
      investigator: investigator.trim() || "Investigator",
      notes: "",
      structureRevision: structure.revision,
    };
    await this.db.walkthroughSessions.put(session);
    await this.audit.record("walkthroughStarted", "Walkthrough session started.", {
      caseId,
      affectedRecordId: session.id,
      metadata: { structureRevision: session.structureRevision },
    });
    return session;
  }

  async listSessions(caseId: string): Promise<WalkthroughSessionRecord[]> {
    const rows = await this.db.walkthroughSessions.where("caseId").equals(caseId).toArray();
    return rows.sort((a, b) => b.startedAt - a.startedAt);
  }

  async getSession(sessionId: string): Promise<WalkthroughSessionRecord | undefined> {
    return this.db.walkthroughSessions.get(sessionId);
  }

  async activeSession(caseId: string): Promise<WalkthroughSessionRecord | undefined> {
    const sessions = await this.listSessions(caseId);
    return sessions.find((s) => s.status === "active");
  }

  /**
   * Completion rule (iOS `isWalkthroughMinimumComplete` + roomsVisitedCheck):
   * every live room/area must be `reviewed` (with the four context conditions
   * recorded — enforced by PropertyService) or carry a justified
   * not-applicable determination. An empty or partially assessed session can
   * never be completed.
   */
  async completeSession(sessionId: string): Promise<WalkthroughSessionRecord> {
    const session = await this.db.walkthroughSessions.get(sessionId);
    if (!session) throw new ValidationError(`Session not found: ${sessionId}`, "sessionId");
    if (session.status === "completed") return session;
    const blockers = await this.assessSessionRooms(session);
    if (blockers.length > 0) {
      const first = blockers[0]!;
      throw new ValidationError(
        `Walkthrough cannot be completed: ${blockers.length} room(s)/area(s) outstanding — next: ${first.roomName} (${first.reason})`,
        "walkthrough",
      );
    }
    const next: WalkthroughSessionRecord = {
      ...session,
      status: "completed",
      completedAt: Date.now(),
      updatedAt: Date.now(),
    };
    await this.db.walkthroughSessions.put(next);
    await this.audit.record("walkthroughCompleted", "Walkthrough session completed.", {
      caseId: session.caseId,
      affectedRecordId: session.id,
    });
    await this.reconcileChecklist(session.caseId);
    return next;
  }

  private async assessSessionRooms(session: WalkthroughSessionRecord): Promise<WalkthroughBlocker[]> {
    if (!session.structureId) return [{ sessionId: session.id, roomId: null, roomName: "Property structure", reason: "No property structure is associated with this session.", requiredAction: "Create the property structure first.", nonOverridable: true }];
    const hierarchy = await this.property.loadHierarchy(session.structureId);
    const areas: RoomRecord[] = [
      ...hierarchy.floors.flatMap((f) => f.rooms ?? []),
      ...hierarchy.zones.flatMap((z) => z.rooms ?? []),
      ...hierarchy.unassignedRooms,
    ];
    const blockers: WalkthroughBlocker[] = [];
    for (const room of areas) {
      if (room.assessmentStatus === "reviewed") continue;
      if (room.assessmentStatus === "notApplicable" && room.notApplicableReason.trim()) continue;
      blockers.push({
        sessionId: session.id,
        roomId: room.id,
        roomName: room.name,
        reason:
          room.assessmentStatus === "notApplicable"
            ? "Marked not applicable without a documented reason."
            : room.assessmentStatus === "notStarted"
              ? "Not yet assessed."
              : "Assessment incomplete — room not marked reviewed.",
        requiredAction: "Complete the room assessment in the walkthrough, or document a justified not-applicable determination.",
        nonOverridable: true,
      });
    }
    return blockers;
  }

  /* ------------------------------ observations ------------------------------ */

  async addObservation(
    sessionId: string,
    input: {
      roomId?: string | null;
      areaLabel?: string;
      kind: ObservationKind;
      description: string;
      instrument?: string;
      evidenceId?: string | null;
    },
  ): Promise<WalkthroughObservationRecord> {
    const session = await this.db.walkthroughSessions.get(sessionId);
    if (!session) throw new ValidationError(`Session not found: ${sessionId}`, "sessionId");
    if (!input.description.trim()) throw new ValidationError("Observation description is required.", "description");
    if (input.kind === "measured" && !input.instrument?.trim()) {
      throw new ValidationError("Measured observations require the identifying instrument.", "instrument");
    }
    if (input.roomId && !(await this.db.structureRooms.get(input.roomId))) {
      throw new ValidationError("Room does not exist.", "roomId");
    }
    const ts = Date.now();
    const observation: WalkthroughObservationRecord = {
      id: uuidv4(),
      schemaVersion: SCHEMA_VERSION,
      createdAt: ts,
      updatedAt: ts,
      caseId: session.caseId,
      sessionId,
      roomId: input.roomId ?? null,
      areaLabel: input.areaLabel ?? "",
      kind: input.kind,
      description: input.description.trim(),
      instrument: input.instrument ?? "",
      evidenceId: input.evidenceId ?? null,
      amendedFromId: null,
      amended: false,
    };
    await this.db.walkthroughObservations.put(observation);
    await this.audit.record("observationCreated", `Walkthrough observation recorded (${input.kind}).`, {
      caseId: session.caseId,
      affectedRecordId: observation.id,
      metadata: { kind: input.kind, sessionId },
      // Description content is intentionally not logged (may contain PII).
    });
    return observation;
  }

  /** Amendment: the previous value is preserved (never overwritten/erased). */
  async amendObservation(
    observationId: string,
    update: { description?: string; instrument?: string; kind?: ObservationKind; reason: string },
  ): Promise<WalkthroughObservationRecord> {
    if (!update.reason.trim()) throw new ValidationError("An amendment requires a documented reason.", "reason");
    const prior = await this.db.walkthroughObservations.get(observationId);
    if (!prior) throw new ValidationError(`Observation not found: ${observationId}`, "observationId");
    const ts = Date.now();
    const revised: WalkthroughObservationRecord = {
      ...prior,
      id: uuidv4(),
      createdAt: ts,
      updatedAt: ts,
      description: update.description?.trim() ?? prior.description,
      instrument: update.instrument ?? prior.instrument,
      kind: update.kind ?? prior.kind,
      amendedFromId: prior.id,
      amended: false,
    };
    await this.db.walkthroughObservations.put(revised);
    await this.db.walkthroughObservations.put({ ...prior, amended: true, updatedAt: ts });
    await this.audit.record("observationAmended", `Observation amended: ${update.reason.slice(0, 160)}`, {
      caseId: prior.caseId,
      affectedRecordId: revised.id,
      metadata: { priorId: prior.id, kind: revised.kind },
    });
    return revised;
  }

  async listObservations(caseId: string, sessionId?: string): Promise<WalkthroughObservationRecord[]> {
    const rows = sessionId
      ? await this.db.walkthroughObservations.where("sessionId").equals(sessionId).toArray()
      : await this.db.walkthroughObservations.where("caseId").equals(caseId).toArray();
    return rows.sort((a, b) => a.createdAt - b.createdAt);
  }

  /* --------------------------- workflow integration -------------------------- */

  /**
   * Walkthrough phase readiness from REAL persisted records (directive §14):
   * at least one completed walkthrough session whose rooms are all assessed
   * (reviewed or justified not-applicable).
   */
  async evaluateCaseWalkthrough(caseId: string): Promise<WalkthroughBlocker[]> {
    const structure = await this.property.getStructureForCase(caseId);
    if (!structure) {
      return [{
        sessionId: null,
        roomId: null,
        roomName: "Property structure",
        reason: "No property structure exists for this case.",
        requiredAction: "Create the property structure and rooms in the Property Structure module.",
        nonOverridable: true,
      }];
    }
    const sessions = await this.listSessions(caseId);
    const completed = sessions.find((s) => s.status === "completed");
    if (!completed) {
      return [{
        sessionId: null,
        roomId: null,
        roomName: "Walkthrough session",
        reason: "No completed walkthrough session exists.",
        requiredAction: "Start and complete a walkthrough session in the Walkthrough module.",
        nonOverridable: true,
      }];
    }
    return this.assessSessionRooms(completed);
  }

  /**
   * Checklist reconciliation for `walkthroughComplete` — mirrors the documents
   * and intake strategy (real records only, both directions, audited).
   */
  async reconcileChecklist(caseId: string): Promise<void> {
    const items = await this.db.checklistItems.where("caseId").equals(caseId).toArray();
    const item = items.find((i) => i.definitionId === "walkthroughComplete");
    if (!item) return;
    const blockers = await this.evaluateCaseWalkthrough(caseId);
    const satisfied = blockers.length === 0;
    if (satisfied && item.status !== "complete") {
      await this.db.checklistItems.put({
        ...item,
        status: "complete",
        completedAt: Date.now(),
        completedBy: "walkthrough-service",
        updatedAt: Date.now(),
      });
      await this.audit.record("checklistChanged", "Walkthrough checklist satisfied by completed walkthrough records.", {
        caseId,
        affectedRecordId: item.id,
      });
    } else if (!satisfied && (item.status === "complete" || item.status === "exception")) {
      await this.db.checklistItems.put({
        ...item,
        status: "pending",
        completedAt: null,
        completedBy: null,
        notes: "Reconciled under TPI-V2-WEB-007: the previous completion was not backed by walkthrough records.",
        updatedAt: Date.now(),
      });
      await this.audit.record("checklistChanged", "Walkthrough checklist item reset — no completed walkthrough records existed.", {
        caseId,
        affectedRecordId: item.id,
      });
    }
  }
}
