/**
 * Investigation session runtime (TPI-V2-WEB-008 §5/§6).
 *
 * iOS origin: InvestigationSessionManager (sessionID, startedAt, endedAt,
 * investigatorName, deviceLabel, currentRoomName, startBreak/endBreak pause
 * semantics, per-room records, investigation gate).
 *
 * Lifecycle is persisted explicitly and never inferred from a page being open.
 * Elapsed time excludes paused time and never accrues while the browser is
 * suspended (the runtime records what it can prove from timestamps).
 */
import type { TPIDatabase } from "../db";
import { SCHEMA_VERSION } from "../db";
import { v4 as uuidv4 } from "../../shared/uuid";
import type {
  InvestigationSessionRecord,
  SessionEventRecord,
  SessionEventSource,
  SessionEventType,
  SessionStatus,
} from "../types";
import { ValidationError } from "../validation";
import { AuditService } from "../audit";

/**
 * Legal lifecycle transitions (WP-6 §5), expressed per operation so that
 * `resume` can never be applied to a session that never started and `start`
 * can never re-start a running or finished session.
 */
const ALLOWED_FROM = {
  start: ["planned"] as SessionStatus[],
  pause: ["active"] as SessionStatus[],
  resume: ["paused"] as SessionStatus[],
  end: ["active", "paused"] as SessionStatus[],
};

export interface SessionSummary {
  session: InvestigationSessionRecord;
  /** Elapsed ms excluding paused intervals. */
  elapsedMs: number;
  /** True when the session was left running by a previous browser session. */
  needsRecovery: boolean;
  eventCount: number;
  measurementCount: number;
}

export class SessionService {
  private readonly audit: AuditService;
  /** Guarantees strictly increasing event timestamps within the same ms. */
  private lastEventAt = 0;

  constructor(private readonly db: TPIDatabase) {
    this.audit = new AuditService(db);
  }

  private monotonicAt(): number {
    const nowMs = Date.now();
    this.lastEventAt = nowMs > this.lastEventAt ? nowMs : this.lastEventAt + 1;
    return this.lastEventAt;
  }

  /* --------------------------------- events -------------------------------- */

  /** Append a session event (chronological, PII-free). */
  async recordEvent(
    sessionId: string,
    type: SessionEventType,
    detail: string,
    options: { source?: SessionEventSource; metadata?: Record<string, string | number | boolean | null> } = {},
  ): Promise<SessionEventRecord> {
    const session = await this.db.sessions.get(sessionId);
    if (!session) throw new ValidationError(`Session not found: ${sessionId}`, "sessionId");
    const event: SessionEventRecord = {
      id: uuidv4(),
      schemaVersion: SCHEMA_VERSION,
      caseId: session.caseId,
      sessionId,
      at: this.monotonicAt(),
      type,
      source: options.source ?? "investigator",
      detail: detail.slice(0, 300),
      metadata: options.metadata,
    };
    await this.db.sessionEvents.put(event);
    return event;
  }

  async listEvents(sessionId: string): Promise<SessionEventRecord[]> {
    const rows = await this.db.sessionEvents.where("sessionId").equals(sessionId).toArray();
    return rows.sort((a, b) => a.at - b.at);
  }

  async listCaseEvents(caseId: string, limit = 200): Promise<SessionEventRecord[]> {
    const rows = await this.db.sessionEvents.where("caseId").equals(caseId).toArray();
    return rows.sort((a, b) => b.at - a.at).slice(0, limit);
  }

  /* -------------------------------- lifecycle ------------------------------ */

  /** Create a session in `planned` state (explicitly not yet running). */
  async createSession(
    caseId: string,
    input: { investigators?: string[]; deviceLabel?: string; roomId?: string | null; startNow?: boolean } = {},
  ): Promise<InvestigationSessionRecord> {
    const caseRecord = await this.db.cases.get(caseId);
    if (!caseRecord) throw new ValidationError(`Case not found: ${caseId}`, "caseId");
    const structure = await this.db.propertyStructures.where("caseId").equals(caseId).first();
    const ts = Date.now();
    const session: InvestigationSessionRecord = {
      id: uuidv4(),
      schemaVersion: SCHEMA_VERSION,
      createdAt: ts,
      updatedAt: ts,
      caseId,
      startedAt: ts,
      status: input.startNow ? "active" : "planned",
      investigators: input.investigators ?? [],
      notes: "",
      deviceLabel: input.deviceLabel ?? "",
      locationId: caseRecord.locationId ?? null,
      structureId: structure?.id ?? null,
      currentRoomId: input.roomId ?? null,
      pausedAt: null,
      pauseReason: "",
      pausedMs: 0,
      resumedAt: null,
      reviewedAt: null,
      interrupted: false,
      recoveredAt: null,
    };
    await this.db.sessions.put(session);
    await this.recordEvent(session.id, "sessionCreated", "Session created.", {
      source: "investigator",
      metadata: { started: session.status === "active" },
    });
    await this.audit.record("sessionStarted", `Investigation session created (${session.status}).`, {
      caseId,
      affectedRecordId: session.id,
      metadata: { status: session.status },
    });
    return session;
  }

  private assertTransition(from: SessionStatus, to: SessionStatus, operation?: keyof typeof ALLOWED_FROM): void {
    if (operation) {
      if (!ALLOWED_FROM[operation].includes(from)) {
        throw new ValidationError(`Invalid session transition: ${from} → ${to} (${operation})`, "status");
      }
      return;
    }
    const permitted = Object.values(ALLOWED_FROM).some((set) => set.includes(from));
    if (!permitted) throw new ValidationError(`Invalid session transition: ${from} → ${to}`, "status");
  }

  async startSession(sessionId: string): Promise<InvestigationSessionRecord> {
    const session = await this.requireSession(sessionId);
    this.assertTransition(session.status, "active", "start");
    const next: InvestigationSessionRecord = {
      ...session,
      status: "active",
      startedAt: session.status === "planned" ? Date.now() : session.startedAt,
      interrupted: false,
      updatedAt: Date.now(),
    };
    await this.db.sessions.put(next);
    await this.recordEvent(sessionId, "sessionStarted", "Session started.");
    await this.audit.record("sessionStarted", "Investigation session started.", {
      caseId: session.caseId,
      affectedRecordId: sessionId,
    });
    return next;
  }

  /** Pause (iOS `startBreak`) — elapsed time stops accruing. */
  async pauseSession(sessionId: string, reason = ""): Promise<InvestigationSessionRecord> {
    const session = await this.requireSession(sessionId);
    this.assertTransition(session.status, "paused", "pause");
    const next: InvestigationSessionRecord = {
      ...session,
      status: "paused",
      pausedAt: Date.now(),
      pauseReason: reason,
      updatedAt: Date.now(),
    };
    await this.db.sessions.put(next);
    await this.recordEvent(sessionId, "sessionPaused", reason ? `Session paused: ${reason.slice(0, 120)}` : "Session paused.");
    await this.audit.record("sessionPaused", "Investigation session paused.", {
      caseId: session.caseId,
      affectedRecordId: sessionId,
      metadata: { resumed: false },
    });
    return next;
  }

  /** Resume (iOS `endBreak`) — paused duration is accumulated, not lost. */
  async resumeSession(sessionId: string): Promise<InvestigationSessionRecord> {
    const session = await this.requireSession(sessionId);
    this.assertTransition(session.status, "active", "resume");
    const pausedDelta = session.pausedAt ? Date.now() - session.pausedAt : 0;
    const next: InvestigationSessionRecord = {
      ...session,
      status: "active",
      pausedAt: null,
      resumedAt: Date.now(),
      pausedMs: (session.pausedMs ?? 0) + pausedDelta,
      updatedAt: Date.now(),
    };
    await this.db.sessions.put(next);
    await this.recordEvent(sessionId, "sessionResumed", "Session resumed.");
    await this.audit.record("sessionResumed", "Investigation session resumed.", {
      caseId: session.caseId,
      affectedRecordId: sessionId,
    });
    return next;
  }

  async endSession(sessionId: string, status: "completed" | "aborted" = "completed"): Promise<InvestigationSessionRecord> {
    const session = await this.requireSession(sessionId);
    this.assertTransition(session.status, status, "end");
    const pausedDelta = session.pausedAt ? Date.now() - session.pausedAt : 0;
    const next: InvestigationSessionRecord = {
      ...session,
      status,
      endedAt: Date.now(),
      pausedAt: null,
      pausedMs: (session.pausedMs ?? 0) + pausedDelta,
      interrupted: false,
      updatedAt: Date.now(),
    };
    await this.db.sessions.put(next);
    await this.recordEvent(sessionId, "sessionEnded", `Session ${status}.`);
    await this.audit.record("sessionEnded", `Investigation session ${status}.`, {
      caseId: session.caseId,
      affectedRecordId: sessionId,
      metadata: { status },
    });
    return next;
  }

  async reviewSession(sessionId: string): Promise<InvestigationSessionRecord> {
    const session = await this.requireSession(sessionId);
    const next: InvestigationSessionRecord = { ...session, reviewedAt: Date.now(), updatedAt: Date.now() };
    await this.db.sessions.put(next);
    await this.recordEvent(sessionId, "sessionReviewed", "Session records reviewed.");
    return next;
  }

  /** Documented correction: reopen a finished session (history preserved). */
  async reopenSession(sessionId: string, reason: string): Promise<InvestigationSessionRecord> {
    if (!reason.trim()) throw new ValidationError("Reopening a session requires a documented reason.", "reason");
    const session = await this.requireSession(sessionId);
    if (session.status !== "completed" && session.status !== "aborted") {
      throw new ValidationError("Only a completed or aborted session can be reopened.", "status");
    }
    const next: InvestigationSessionRecord = {
      ...session,
      status: "active",
      endedAt: undefined,
      interrupted: false,
      updatedAt: Date.now(),
    };
    await this.db.sessions.put(next);
    await this.recordEvent(sessionId, "sessionReopened", `Session reopened: ${reason.slice(0, 160)}`);
    await this.audit.record("sessionReopened", `Investigation session reopened: ${reason.slice(0, 160)}`, {
      caseId: session.caseId,
      affectedRecordId: sessionId,
    });
    return next;
  }

  /**
   * Recovery (WP-6 §5): a session persisted as `active` by a browser session
   * that is no longer running must not silently appear to be recording.
   * Called on case load; flags such sessions and records an audit event once.
   */
  async recoverInterruptedSessions(caseId: string): Promise<InvestigationSessionRecord[]> {
    const sessions = await this.db.sessions.where("caseId").equals(caseId).toArray();
    const recovered: InvestigationSessionRecord[] = [];
    for (const session of sessions) {
      if (session.status !== "active") continue;
      const next: InvestigationSessionRecord = {
        ...session,
        interrupted: true,
        recoveredAt: Date.now(),
        updatedAt: Date.now(),
      };
      await this.db.sessions.put(next);
      await this.recordEvent(session.id, "sessionRecovered", "Session was left running when the browser closed; marked interrupted for review.", {
        source: "system",
      });
      await this.audit.record("sessionRecovered", "Interrupted investigation session detected on load and marked for review.", {
        caseId,
        affectedRecordId: session.id,
      });
      recovered.push(next);
    }
    return recovered;
  }

  /** Mark the current runtime as owning the active session (per browser load). */
  async claimActiveSession(sessionId: string): Promise<InvestigationSessionRecord> {
    const session = await this.requireSession(sessionId);
    const next: InvestigationSessionRecord = { ...session, interrupted: false, updatedAt: Date.now() };
    await this.db.sessions.put(next);
    return next;
  }

  /* --------------------------------- queries ------------------------------- */

  async getSession(sessionId: string): Promise<InvestigationSessionRecord | undefined> {
    return this.db.sessions.get(sessionId);
  }

  async listSessions(caseId: string): Promise<InvestigationSessionRecord[]> {
    const rows = await this.db.sessions.where("caseId").equals(caseId).toArray();
    return rows.sort((a, b) => b.startedAt - a.startedAt);
  }

  async activeSession(caseId: string): Promise<InvestigationSessionRecord | undefined> {
    const sessions = await this.listSessions(caseId);
    return sessions.find((s) => s.status === "active" || s.status === "paused");
  }

  /** Elapsed time excluding paused intervals (never counts suspended time twice). */
  elapsedMs(session: InvestigationSessionRecord, at = Date.now()): number {
    const end = session.endedAt ?? (session.status === "paused" ? session.pausedAt ?? at : at);
    const pausedNow = session.status === "paused" && session.pausedAt ? Math.max(0, end - session.pausedAt) : 0;
    return Math.max(0, end - session.startedAt - (session.pausedMs ?? 0) - pausedNow);
  }

  async summarize(sessionId: string): Promise<SessionSummary | undefined> {
    const session = await this.db.sessions.get(sessionId);
    if (!session) return undefined;
    const [events, measurements] = await Promise.all([
      this.db.sessionEvents.where("sessionId").equals(sessionId).count(),
      this.db.environmentMeasurements.where("sessionId").equals(sessionId).count(),
    ]);
    return {
      session,
      elapsedMs: this.elapsedMs(session),
      needsRecovery: session.interrupted === true && session.status === "active",
      eventCount: events,
      measurementCount: measurements,
    };
  }

  private async requireSession(sessionId: string): Promise<InvestigationSessionRecord> {
    const session = await this.db.sessions.get(sessionId);
    if (!session) throw new ValidationError(`Session not found: ${sessionId}`, "sessionId");
    return session;
  }
}
