/**
 * Command Center — case files, clients, locations, activity, workflow.
 * Visual identity: iOS CasesListView / HomeDashboardView (dark + cyan).
 * All data access goes through the approved repository layer.
 */
import "./commandcenter.css";
import { CaseRepository } from "../../core/repositories/caseRepository";
import {
  ClientRepository,
  LocationRepository,
} from "../../core/repositories/investigationRepositories";
import { AuditService } from "../../core/audit";
import { WorkflowService, WORKFLOW_PHASE_ORDER, type LifecycleStage } from "../../core/workflow/workflowService";
import { getDb } from "../../core/db";
import type { CaseRecord, CaseStatus, ClientRecord, LocationRecord } from "../../core/types";
import { ValidationError } from "../../core/validation";
import {
  INVESTIGATION_CLASSIFICATION_NOTE,
  INVESTIGATION_TYPE_OPTIONS,
  investigationTypeSelectOptions,
} from "../../core/investigationClassification";
import { esc, viewShell, wireBackButton } from "../dashboard/shell";
import { caseIdFromRoute, navigate } from "../../app/router";
import { renderCaseHub } from "../casehub/CaseHub";

type Tab = "cases" | "hub" | "clients" | "locations" | "activity" | "workflow" | "intake";

const db = () => getDb();
const cases = () => new CaseRepository(db());
const clients = () => new ClientRepository(db());
const locations = () => new LocationRepository(db());
const audit = () => new AuditService(db());
const workflow = () => new WorkflowService(db());

let activeTab: Tab = "cases";
let searchQuery = "";
let statusFilter: CaseStatus | undefined;

function toast(message: string, isError = false): void {
  const el = document.createElement("div");
  el.className = `toast${isError ? " error" : ""}`;
  el.setAttribute("role", "status");
  el.textContent = message;
  document.body.appendChild(el);
  setTimeout(() => el.remove(), 3500);
}

function fmtTime(ms: number): string {
  return new Date(ms).toLocaleString();
}

const TABS: Array<{ id: Tab; label: string }> = [
  { id: "cases", label: "CASE FILES" },
  { id: "hub", label: "CASE HUB" },
  { id: "clients", label: "CLIENTS" },
  { id: "locations", label: "LOCATIONS" },
  { id: "activity", label: "CASE ACTIVITY" },
  { id: "workflow", label: "WORKFLOW" },
  { id: "intake", label: "INTAKE" },
];

export function renderCommandCenterV2(container: HTMLElement): void {
  container.innerHTML = `
    <div class="view cc-view">
      <header class="cc-page-header">
        <button class="cc-header-icon" id="cc-sidebar-control" type="button" aria-label="Open Command Center navigation" aria-expanded="false">☰</button>
        <button class="cc-header-icon cc-back-icon" id="cc-back" type="button" aria-label="Back to Dashboard">‹</button>
        <h2 id="cc-page-title">${activeTab === "cases" ? "Case Files" : "Command Center"}</h2>
        ${activeTab === "cases" ? `
          <button class="cc-header-icon" id="export-backup" type="button" aria-label="Export case data" title="Export case data">↥</button>
          <button class="cc-add-case" id="open-create-case" type="button" aria-label="Add case">＋</button>` : ""}
      </header>
      <nav class="cc-tabs" role="tablist" aria-label="Command Center sections" hidden>
        ${TABS.map((t) => `<button class="cc-tab" role="tab" type="button" data-tab="${t.id}" aria-selected="${t.id === activeTab}">${t.label}</button>`).join("")}
      </nav>
      <section id="cc-content" role="tabpanel"></section>
    </div>`;

  container.querySelector<HTMLButtonElement>("#cc-sidebar-control")?.addEventListener("click", (event) => {
    const button = event.currentTarget as HTMLButtonElement;
    const nav = container.querySelector<HTMLElement>(".cc-tabs");
    const expanded = button.getAttribute("aria-expanded") === "true";
    button.setAttribute("aria-expanded", String(!expanded));
    nav?.toggleAttribute("hidden", expanded);
  });
  container.querySelector<HTMLButtonElement>("#cc-back")?.addEventListener("click", () => navigate("dashboard"));
  container.querySelectorAll<HTMLButtonElement>(".cc-tab").forEach((btn) => {
    btn.addEventListener("click", () => {
      activeTab = btn.dataset.tab as Tab;
      renderCommandCenterV2(container);
    });
  });

  const content = container.querySelector<HTMLElement>("#cc-content");
  if (!content) return;
  switch (activeTab) {
    case "cases": void renderCasesTab(content); break;
    case "hub": void renderHubTab(content); break;
    case "clients": void renderClientsTab(content); break;
    case "locations": void renderLocationsTab(content); break;
    case "activity": void renderActivityTab(content); break;
    case "workflow": void renderWorkflowTab(content); break;
    case "intake": void renderIntakeTab(content); break;
  }
  wireBackButton(container);
}

/* ---------------- Case Files ---------------- */
async function renderCasesTab(container: HTMLElement): Promise<void> {
  container.innerHTML = `
    <div class="case-files-screen">
      <div class="case-status-segment" role="group" aria-label="Case status">
        <button type="button" data-status-view="active" aria-pressed="${statusFilter !== "archived"}">Active</button>
        <button type="button" data-status-view="archived" aria-pressed="${statusFilter === "archived"}">Archived</button>
      </div>
      <details class="case-search-tools" ${searchQuery ? "open" : ""}>
        <summary>Search and filter cases</summary>
        <div class="cc-toolbar">
          <input type="search" id="case-search" placeholder="Search case number or title…" value="${esc(searchQuery)}" aria-label="Search cases" />
          <select id="case-status-filter" aria-label="Filter by status">
            <option value="">All statuses</option>
            <option value="active"${statusFilter === "active" ? " selected" : ""}>Active</option>
            <option value="inactive"${statusFilter === "inactive" ? " selected" : ""}>Inactive</option>
          </select>
        </div>
      </details>
      <div id="case-list" aria-live="polite"></div>
      <dialog id="case-create-dialog" class="case-create-dialog" aria-labelledby="case-create-title">
        <form method="dialog" class="case-form" id="case-create-form">
          <h3 id="case-create-title">Create Case File</h3>
          <label for="new-case-title">CASE TITLE</label>
          <input id="new-case-title" type="text" placeholder="e.g. Miller Residence Investigation" required />
          <label for="new-case-type">INVESTIGATION TYPE</label>
          <select id="new-case-type">
            ${INVESTIGATION_TYPE_OPTIONS.map((option) => `<option value="${option.value}">${esc(option.label)}</option>`).join("")}
          </select>
          <p class="cc-meta">${esc(INVESTIGATION_CLASSIFICATION_NOTE)}</p>
          <div class="form-actions">
            <button class="button-secondary" id="cancel-create-case" type="button">Cancel</button>
            <button class="button-primary" id="create-case" type="button">Create Case</button>
          </div>
          <p id="form-error" class="hidden" role="alert"></p>
        </form>
      </dialog>
    </div>`;

  const root = container.closest<HTMLElement>(".cc-view") ?? container;
  const list = container.querySelector<HTMLElement>("#case-list");
  const dialog = container.querySelector<HTMLDialogElement>("#case-create-dialog");
  root.querySelector<HTMLButtonElement>("#open-create-case")?.addEventListener("click", () => {
    dialog?.showModal();
    container.querySelector<HTMLInputElement>("#new-case-title")?.focus();
  });
  container.querySelector<HTMLButtonElement>("#cancel-create-case")?.addEventListener("click", () => dialog?.close());
  const runSearch = async (): Promise<void> => {
    const { items } = await cases().searchCases({
      query: searchQuery,
      sortBy: "updatedAt",
      sortDir: "desc",
      limit: 1000,
    });
    if (!list) return;
    const retainedScroll = list.scrollTop;
    const isArchived = statusFilter === "archived";
    const visible = items.filter((c) => (c.status === "archived") === isArchived && (!statusFilter || statusFilter === "archived" || c.status === statusFilter));
    list.innerHTML = visible.length === 0
      ? `<div class="cc-empty">${isArchived ? "No archived cases." : "No active cases."}</div>`
      : `<div class="cc-count">${visible.length} case${visible.length === 1 ? "" : "s"}</div>` + visible.map(caseRowHtml).join("");
    list.scrollTop = retainedScroll;
    list.querySelectorAll<HTMLElement>(".case-row").forEach((row) => {
      const open = (target: HTMLElement): void => {
        // Only real controls opt out; clicking the card body (including the
        // collapsed actions strip) must open the case.
        if (target.closest("button, .case-file-action-menu, summary")) return;
        const selected = row.dataset.id;
        if (!selected) return;
        activeTab = "cases";
        // Case context lives in the route (TPI-V2-WEB-014B §2).
        navigate("casehub", { case: selected });
      };
      row.addEventListener("click", (event) => open(event.target as HTMLElement));
      row.addEventListener("keydown", (event) => {
        if (event.key === "Enter" || event.key === " ") {
          event.preventDefault();
          open(event.target as HTMLElement);
        }
      });
    });
    list.querySelectorAll<HTMLButtonElement>("[data-archive]").forEach((b) => b.addEventListener("click", async () => {
      const id = b.dataset.archive;
      if (!id || !window.confirm("Archive this case? Its records are preserved and it can be reopened later.")) return;
      try { await cases().setCaseStatus(id, "archived"); toast("Case archived"); await runSearch(); }
      catch (err) { toast((err as Error).message, true); }
    }));
    list.querySelectorAll<HTMLButtonElement>("[data-edit]").forEach((b) => b.addEventListener("click", async () => {
      const id = b.dataset.edit;
      if (!id) return;
      const current = (await cases().getCase(id))?.title ?? "";
      const title = window.prompt("Edit case title:", current);
      if (title === null) return;
      if (!title.trim()) { toast("Case title cannot be empty", true); return; }
      try { await cases().updateCase(id, { title: title.trim() }); toast("Case updated"); await runSearch(); }
      catch (err) { toast((err as Error).message, true); }
    }));
    list.querySelectorAll<HTMLButtonElement>("[data-reopen]").forEach((b) => b.addEventListener("click", async () => {
      const id = b.dataset.reopen;
      if (!id) return;
      try { await cases().setCaseStatus(id, "active"); toast("Case reopened"); await runSearch(); }
      catch (err) { toast((err as Error).message, true); }
    }));
  };

  container.querySelectorAll<HTMLButtonElement>("[data-status-view]").forEach((button) => button.addEventListener("click", () => {
    statusFilter = button.dataset.statusView === "archived" ? "archived" : undefined;
    container.querySelectorAll("[data-status-view]").forEach((item) => item.setAttribute("aria-pressed", String(item === button)));
    void runSearch();
  }));
  container.querySelector<HTMLInputElement>("#case-search")?.addEventListener("input", (event) => {
    searchQuery = (event.currentTarget as HTMLInputElement).value;
    void runSearch();
  });
  container.querySelector<HTMLSelectElement>("#case-status-filter")?.addEventListener("change", (event) => {
    const value = (event.currentTarget as HTMLSelectElement).value;
    statusFilter = value ? value as CaseStatus : undefined;
    void runSearch();
  });

  container.querySelector<HTMLButtonElement>("#create-case")?.addEventListener("click", async () => {
    const titleEl = container.querySelector<HTMLInputElement>("#new-case-title");
    const typeEl = container.querySelector<HTMLSelectElement>("#new-case-type");
    const errEl = container.querySelector<HTMLElement>("#form-error");
    const title = titleEl?.value.trim() ?? "";
    if (!title) { titleEl?.focus(); errEl?.classList.remove("hidden"); if (errEl) errEl.textContent = "Case title is required."; return; }
    try {
      const record = await cases().createCase({ title, investigationType: (typeEl?.value as CaseRecord["investigationType"]) ?? "residential" });
      if (titleEl) titleEl.value = "";
      errEl?.classList.add("hidden");
      dialog?.close();
      statusFilter = undefined;
      toast(`Case ${record.caseNumber} created`);
      await runSearch();
      const caseCard = list?.querySelector<HTMLElement>(`[data-id="${record.id}"]`);
      caseCard?.scrollIntoView({ block: "nearest" });
      const mysticMinimize = document.querySelector<HTMLButtonElement>("#mystic-minimize");
      if (mysticMinimize && mysticMinimize.offsetParent !== null) mysticMinimize.click();
    } catch (err) { errEl?.classList.remove("hidden"); if (errEl) errEl.textContent = `Save failed: ${(err as Error).message}`; }
  });
  root.querySelector<HTMLButtonElement>("#export-backup")?.addEventListener("click", exportBackup);
  await runSearch();
}

function caseRowHtml(c: CaseRecord): string {
  const address = [c.street, c.city, c.state, c.zip].filter(Boolean).join(", ");
  return `
    <article class="case-row case-file-card" data-id="${c.id}" tabindex="0" role="button" aria-label="Open case ${esc(c.title)}">
      <div class="case-file-org">The Paranormal Initiative</div>
      <div class="case-file-title-row">
        <div class="case-title">${esc(c.title)}</div>
        ${c.status === "active" ? `<span class="case-active-badge">ACTIVE</span>` : `<span class="status-badge">${esc(c.status)}</span>`}
      </div>
      <div class="case-meta case-file-address">${esc(address || "Address not recorded")}</div>
      <details class="case-file-actions">
        <summary aria-label="Case actions" title="Case actions">•••</summary>
        <div class="case-file-action-menu">
          <button class="back-button" data-edit="${c.id}" type="button">Edit</button>
          ${c.status === "archived" ? `<button class="back-button" data-reopen="${c.id}" type="button">Restore</button>` : `<button class="back-button" data-archive="${c.id}" type="button">Archive</button>`}
        </div>
      </details>
    </article>`;
}

/* ---------------- Case detail ---------------- */
/**
 * Case details editor — the unique editing surface retained from the legacy
 * case-detail view (TPI-V2-WEB-014B §5). It is reached from the Case Hub and is
 * no longer a competing case-detail entry point.
 */
export async function renderCaseDetail(container: HTMLElement, caseId: string, onBack?: () => void): Promise<void> {
  if (!caseId) return;
  const record = await cases().getCase(caseId);
  if (!record) {
    toast("Case not found", true);
    if (onBack) onBack();
    else navigate("command-center");
    return;
  }
  const stage = workflow().lifecycleStage(record);
  const client = record.clientId ? await clients().get(record.clientId) : undefined;
  const location = record.locationId ? await locations().get(record.locationId) : undefined;
  const allLocations = await locations().search("", 50);
  const caseClients = await clients().listForCase(record.id);
  const events = await audit().listForCase(record.id, 50);

  container.innerHTML = viewShell(
    `Case — ${record.caseNumber}`,
    `
    <div class="case-form">
      <div class="phase-timeline" aria-label="Workflow phase timeline">
        ${WORKFLOW_PHASE_ORDER.map((p) => {
          const idx = WORKFLOW_PHASE_ORDER.indexOf(record.currentPhase);
          const myIdx = WORKFLOW_PHASE_ORDER.indexOf(p);
          return `<span class="phase-step ${myIdx === idx ? "current" : myIdx < idx ? "done" : ""}">${p}</span>`;
        }).join("")}
      </div>
      <p class="cc-count">Lifecycle stage: <strong>${stage}</strong> • Status: ${esc(record.status)} • Created ${fmtTime(record.createdAt)}</p>
      <div class="detail-grid">
        <div class="detail-field"><label for="d-title">Title</label><input id="d-title" value="${esc(record.title)}" /></div>
        <div class="detail-field"><label for="d-type">Investigation type</label>
          <select id="d-type">
            ${investigationTypeSelectOptions(record.investigationType).map((option) => `<option value="${option.value}"${option.value === record.investigationType ? " selected" : ""}>${esc(option.label)}</option>`).join("")}
          </select>
          <p class="cc-meta" data-classification-note>${esc(INVESTIGATION_CLASSIFICATION_NOTE)}</p></div>
        <div class="detail-field"><label for="d-client-name">Client name</label><input id="d-client-name" value="${esc(record.clientName ?? "")}" /></div>
        <div class="detail-field"><label for="d-phone">Client phone</label><input id="d-phone" value="${esc(record.phone ?? "")}" /></div>
        <div class="detail-field"><label for="d-email">Client email</label><input id="d-email" value="${esc(record.email ?? "")}" /></div>
        <div class="detail-field"><label for="d-street">Street</label><input id="d-street" value="${esc(record.street ?? "")}" /></div>
        <div class="detail-field"><label for="d-city">City</label><input id="d-city" value="${esc(record.city ?? "")}" /></div>
        <div class="detail-field"><label for="d-state">State</label><input id="d-state" value="${esc(record.state ?? "")}" /></div>
      </div>
      <p class="cc-count">Linked client record: ${client ? esc(client.fullName) : "none"} • Linked location: ${location ? esc(location.name) : "none"}</p>

      <h3 class="cc-section-title">Client Record</h3>
      <div class="case-form">
        <p class="cc-count" data-linked-client>Current client record: <strong>${client ? esc(client.fullName) : "none"}</strong></p>
        <div class="form-actions">
          <select id="case-client-select" aria-label="Clients associated with this case">
            <option value="">— select a client record for this case —</option>
            ${caseClients.map((candidate) => `<option value="${candidate.id}"${candidate.id === record.clientId ? " selected" : ""}>${esc(candidate.fullName)}</option>`).join("")}
          </select>
          <button class="button-secondary" id="associate-client" type="button">Associate Client</button>
          ${record.clientId ? `<button class="back-button" id="clear-client" type="button">Remove Association</button>` : ""}
        </div>
        <p class="cc-meta">Client records are case-scoped: only clients created for this case can be linked. The free-text contact fields above remain available for cases without a client record. Removing a link never deletes the client record.</p>
      </div>

      <h3 class="cc-section-title">Investigation Location</h3>
      <div class="case-form">
        ${
          record.locationId
            ? `<p class="cc-count">Current location: <strong>${esc(location?.name ?? "(record missing)")}</strong>${location?.street ? ` — ${esc([location.street, location.city, location.state].filter(Boolean).join(", "))}` : ""}</p>`
            : `<p class="cc-count">No location is associated with this case. The walkthrough phase will report a location warning until one is set.</p>`
        }
        <div class="form-actions">
          <select id="case-location-select" aria-label="Existing locations">
            <option value="">— select an existing location —</option>
            ${allLocations.map((l) => `<option value="${l.id}"${l.id === record.locationId ? " selected" : ""}>${esc(l.name)}</option>`).join("")}
          </select>
          <button class="button-secondary" id="associate-location" type="button">Associate Location</button>
          ${record.locationId ? `<button class="back-button" id="clear-location" type="button">Remove Association</button>` : ""}
        </div>
        <div class="detail-grid">
          <div class="detail-field"><label for="new-loc-name">New location name</label><input id="new-loc-name" type="text" placeholder="e.g. Miller Residence" /></div>
          <div class="detail-field"><label for="new-loc-street">Street</label><input id="new-loc-street" type="text" /></div>
          <div class="detail-field"><label for="new-loc-city">City</label><input id="new-loc-city" type="text" /></div>
          <div class="detail-field"><label for="new-loc-state">State</label><input id="new-loc-state" type="text" /></div>
        </div>
        <div class="form-actions"><button class="button-primary" id="create-location-for-case" type="button">Create &amp; Associate Location</button></div>
        <p class="cc-meta">Changing the case location never rewrites existing observations, markers, or walkthrough records — those keep the physical property they were recorded at. Confirm the change only when the investigation genuinely moves to a different property.</p>
      </div>

      <div class="form-actions">
        <button class="button-primary" id="save-case" type="button">Save Changes</button>
        ${record.status !== "archived" ? `<button class="button-secondary" id="archive-case" type="button">Archive Case</button>` : `<button class="button-secondary" id="reopen-case" type="button">Reopen Case</button>`}
        <button class="button-secondary" id="advance-phase" type="button">Advance Workflow</button>
      </div>
      <p id="detail-error" class="hidden" style="color:#ffb3c2;font-size:12px;" role="alert"></p>
    </div>
    <h3 class="cc-section-title">Case activity</h3>
    ${events.length === 0
      ? `<div class="cc-empty">No activity recorded.</div>`
      : `<ul class="activity-list">${events
          .map(
            (e) =>
              `<li><span class="when">${fmtTime(e.createdAt)}</span><div class="what">${esc(e.detail)}</div></li>`,
          )
          .join("")}</ul>`}
    `,
  );

  const showErr = (msg: string): void => {
    const el = container.querySelector<HTMLElement>("#detail-error");
    el?.classList.remove("hidden");
    if (el) el.textContent = msg;
  };

  container.querySelector<HTMLButtonElement>("#save-case")?.addEventListener("click", async () => {
    const read = (id: string): string =>
      container.querySelector<HTMLInputElement>(`#${id}`)?.value.trim() ?? "";
    try {
      await cases().updateCase(record.id, {
        title: read("d-title") || record.title,
        investigationType: container.querySelector<HTMLSelectElement>("#d-type")?.value as CaseRecord["investigationType"],
        clientName: read("d-client-name") || undefined,
        phone: read("d-phone") || undefined,
        email: read("d-email") || undefined,
        street: read("d-street") || undefined,
        city: read("d-city") || undefined,
        state: read("d-state") || undefined,
      });
      toast("Case saved");
      await renderCaseDetail(container, caseId, onBack);
    } catch (err) {
      showErr(`Save failed: ${(err as Error).message}`);
    }
  });

  container.querySelector<HTMLButtonElement>("#archive-case")?.addEventListener("click", async () => {
    if (!window.confirm("Archive this case? It can be reopened later.")) return;
    try {
      await cases().setCaseStatus(record.id, "archived");
      toast("Case archived");
      await renderCaseDetail(container, caseId, onBack);
    } catch (err) { showErr((err as Error).message); }
  });
  container.querySelector<HTMLButtonElement>("#reopen-case")?.addEventListener("click", async () => {
    try {
      await cases().setCaseStatus(record.id, "active");
      toast("Case reopened");
      await renderCaseDetail(container, caseId, onBack);
    } catch (err) { showErr((err as Error).message); }
  });
  container.querySelector<HTMLButtonElement>("#advance-phase")?.addEventListener("click", async () => {
    try {
      const next = await workflow().advancePhase(record.id);
      if (next) toast(`Workflow advanced to ${next.currentPhase}`);
      await renderCaseDetail(container, caseId, onBack);
    } catch (err) { showErr((err as Error).message); }
  });

  // ---- WP-6 §17: case ↔ location association ----
  const setCaseLocation = async (locationId: string | null, label: string) => {
    try {
      const previous = record.locationId;
      if (previous && previous !== locationId && locationId !== null) {
        const ok = window.confirm(
          "This case is being moved to a different property. Existing observations, markers, and walkthrough records keep the property they were recorded at and are not rewritten.\n\nContinue?",
        );
        if (!ok) return;
      }
      await cases().setLocation(record.id, locationId);
      await audit().record(
        previous ? "locationChanged" : "locationAssociated",
        locationId ? `Case location ${previous ? "changed" : "associated"}: ${label}` : "Case location association removed",
        { caseId: record.id, affectedRecordId: locationId ?? previous ?? record.id, metadata: { hadPrevious: Boolean(previous) } },
      );
      toast(locationId ? "Location associated" : "Location association removed");
      await renderCaseDetail(container, caseId, onBack);
    } catch (err) {
      showErr((err as Error).message);
    }
  };

  container.querySelector<HTMLButtonElement>("#associate-location")?.addEventListener("click", async () => {
    const select = container.querySelector<HTMLSelectElement>("#case-location-select");
    const locationId = select?.value ?? "";
    if (!locationId) {
      showErr("Select an existing location, or create a new one below.");
      return;
    }
    const label = select?.selectedOptions[0]?.textContent ?? locationId;
    await setCaseLocation(locationId, label);
  });
  container.querySelector<HTMLButtonElement>("#clear-location")?.addEventListener("click", async () => {
    if (!window.confirm("Remove the location association from this case?")) return;
    await setCaseLocation(null, "");
  });
  container.querySelector<HTMLButtonElement>("#create-location-for-case")?.addEventListener("click", async () => {
    const readEl = (sel: string) => container.querySelector<HTMLInputElement>(sel)?.value.trim() ?? "";
    const name = readEl("#new-loc-name");
    try {
      if (!name) throw new ValidationError("Location name is required", "name");
      const previous = record.locationId;
      if (previous) {
        // Same safeguard as re-association: moving a case to a different
        // property never rewrites historical observations or walkthrough records.
        const ok = window.confirm(
          "This case is being moved to a different property. Existing observations, markers, and walkthrough records keep the property they were recorded at and are not rewritten.\n\nContinue?",
        );
        if (!ok) return;
      }
      const created = await locations().create({
        name,
        street: readEl("#new-loc-street") || undefined,
        city: readEl("#new-loc-city") || undefined,
        state: readEl("#new-loc-state") || undefined,
      });
      await cases().setLocation(record.id, created.id);
      await audit().record(previous ? "locationChanged" : "locationAssociated", `Case location ${previous ? "changed" : "associated"}: ${name}`, {
        caseId: record.id,
        affectedRecordId: created.id,
        metadata: { created: true },
      });
      toast("Location created and associated");
      await renderCaseDetail(container, caseId, onBack);
    } catch (err) {
      showErr((err as Error).message);
    }
  });

  // ---- C5A: explicit client-record association (case-scoped, no duplicates) ----
  container.querySelector<HTMLButtonElement>("#associate-client")?.addEventListener("click", async () => {
    const select = container.querySelector<HTMLSelectElement>("#case-client-select");
    const clientId = select?.value ?? "";
    if (!clientId) {
      showErr("Select an existing client record for this case.");
      return;
    }
    try {
      await clients().associateWithCase(clientId, record.id);
      toast("Client record associated");
      await renderCaseDetail(container, caseId, onBack);
    } catch (err) { showErr((err as Error).message); }
  });
  container.querySelector<HTMLButtonElement>("#clear-client")?.addEventListener("click", async () => {
    if (!window.confirm("Remove the client association from this case? The client record is preserved.")) return;
    try {
      await clients().clearCaseAssociation(record.id);
      toast("Client association removed");
      await renderCaseDetail(container, caseId, onBack);
    } catch (err) { showErr((err as Error).message); }
  });

  // Back from detail returns to Case Files; the original navigation does not jump to dashboard.
  container.querySelector<HTMLButtonElement>("[data-action='back']")?.addEventListener("click", () => {
    if (onBack) onBack();
    else navigate("command-center");
  });
}

/** Stable alias: the canonical case detail editor. */
export const renderCaseDetails = renderCaseDetail;

/* ---------------- Case Hub ---------------- */
async function renderHubTab(container: HTMLElement): Promise<void> {
  const appRoot = container.closest<HTMLElement>(".cc-view")?.parentElement ?? container;
  const openHub = (caseId: string): Promise<void> =>
    renderCaseHub(appRoot, caseId, () => {
      activeTab = "cases";
      navigate("command-center");
    });

  const routedCase = caseIdFromRoute();
  if (routedCase) {
    await openHub(routedCase);
    return;
  }
  // Tab fallback: the most recently updated case is rendered in place. Case
  // context is never stored in module state; opening a case row produces the
  // canonical `#/casehub?case=…` route.
  const { items } = await cases().searchCases({ limit: 1, sortBy: "updatedAt", sortDir: "desc" });
  const recent = items[0]?.id;
  if (!recent) {
    container.innerHTML = `<div class="cc-empty">Create a case first — the Case Hub opens from a case.</div>`;
    return;
  }
  await openHub(recent);
}

/* ---------------- Clients ---------------- */
async function renderClientsTab(container: HTMLElement): Promise<void> {
  const list = await clients().search(searchQuery, 50);
  container.innerHTML = `
    <div class="case-form">
      <label for="client-name">CLIENT FULL NAME</label>
      <input id="client-name" type="text" placeholder="Full name" />
      <label for="client-phone">PHONE (OPTIONAL)</label>
      <input id="client-phone" type="tel" />
      <label for="client-email">EMAIL (OPTIONAL)</label>
      <input id="client-email" type="email" />
      <label for="client-case">ASSOCIATE WITH CASE</label>
      <select id="client-case" aria-label="Associate with case"></select>
      <div class="form-actions"><button class="button-primary" id="create-client" type="button">Create Client</button></div>
      <p id="client-error" class="hidden" style="color:#ffb3c2;font-size:12px;" role="alert"></p>
    </div>
    <div id="client-list" aria-live="polite">${clientListHtml(list)}</div>`;

  const caseSelect = container.querySelector<HTMLSelectElement>("#client-case");
  const { items } = await cases().searchCases({ status: "active", limit: 100 });
  if (caseSelect) {
    caseSelect.innerHTML =
      `<option value="">— select a case —</option>` +
      items.map((c) => `<option value="${c.id}">${esc(c.caseNumber)} — ${esc(c.title)}</option>`).join("");
  }

  container.querySelector<HTMLButtonElement>("#create-client")?.addEventListener("click", async () => {
    const nameEl = container.querySelector<HTMLInputElement>("#client-name");
    const errEl = container.querySelector<HTMLElement>("#client-error");
    const name = nameEl?.value.trim() ?? "";
    const caseId = caseSelect?.value;
    try {
      if (!caseId) throw new ValidationError("Select a case to associate the client with", "caseId");
      await clients().create({
        caseId,
        fullName: name,
        phone: container.querySelector<HTMLInputElement>("#client-phone")?.value.trim() || undefined,
        email: container.querySelector<HTMLInputElement>("#client-email")?.value.trim() || undefined,
      });
      errEl?.classList.add("hidden");
      if (nameEl) nameEl.value = "";
      toast("Client created and associated");
      await renderClientsTab(container);
    } catch (err) {
      errEl?.classList.remove("hidden");
      if (errEl) errEl.textContent = (err as Error).message;
    }
  });

  container.querySelector<HTMLInputElement>("#client-name")?.closest(".case-form");
  await bindSearchRefresh(container, "#client-list", () =>
    clients().search(searchQuery, 50).then((l) => clientListHtml(l as ClientRecord[])),
  );
}

function clientListHtml(list: ClientRecord[]): string {
  return list.length === 0
    ? `<div class="cc-empty">No clients match.</div>`
    : list
        .map(
          (cl) => `
      <div class="case-row" tabindex="0">
        <div>
          <div class="case-title">${esc(cl.fullName)}</div>
          <div class="case-meta">${cl.phone ? "phone on file • " : ""}${cl.email ? "email on file • " : ""}case ${esc(cl.caseId.slice(0, 8))}…</div>
        </div>
        <span class="status-badge">${cl.consentRecordIds.length} consent</span>
      </div>`,
        )
        .join("");
}

