/* ---------------- Workflow ---------------- */
async function renderWorkflowTab(container: HTMLElement): Promise<void> {
  const { items } = await cases().searchCases({ status: "active", limit: 50 });
  container.innerHTML = `
    <h3 class="cc-section-title">Investigation workflow</h3>
    <div class="case-form">
      <p class="primary-line">One authoritative workflow service governs case phases. Advance a case step by step; manual corrections require a reason and are audited.</p>
    </div>
    ${items.length === 0
      ? `<div class="cc-empty">No active cases.</div>`
      : items
          .map(
            (c) => `
      <div class="case-row">
        <div>
          <div class="case-title">${esc(c.title)}</div>
          <div class="phase-timeline" style="margin:8px 0 0;">
            ${WORKFLOW_PHASE_ORDER.map((p) => {
              const cur = WORKFLOW_PHASE_ORDER.indexOf(c.currentPhase);
              const idx = WORKFLOW_PHASE_ORDER.indexOf(p);
              return `<span class="phase-step ${idx === cur ? "current" : idx < cur ? "done" : ""}">${p}</span>`;
            }).join("")}
          </div>
        </div>
        <button class="back-button" data-advance="${c.id}" type="button">Advance</button>
      </div>`,
          )
          .join("")}`;

  container.querySelectorAll<HTMLButtonElement>("[data-advance]").forEach((b) =>
    b.addEventListener("click", async () => {
      const id = b.dataset.advance;
      if (!id) return;
      try {
        const next = await workflow().advancePhase(id);
        if (next) toast(`Advanced to ${next.currentPhase}`);
        await renderWorkflowTab(container);
      } catch (err) { toast((err as Error).message, true); }
    }),
  );
}

