/* ---------------- Shared helpers ---------------- */
async function bindSearchRefresh(
  container: HTMLElement,
  selector: string,
  render: () => Promise<string>,
): Promise<void> {
  const searchEl = container.querySelector<HTMLInputElement>("#case-search");
  void searchEl;
  const target = container.querySelector<HTMLElement>(selector);
  void target;
  // searchQuery is updated by the shared toolbar in the cases tab; client and
  // location tabs re-render through their own flows.
  await render();
}

async function exportBackup(): Promise<void> {
  const { exportAll, serializeExport } = await import("../../core/backup");
  const manifest = await exportAll(db());
  const { json } = await serializeExport(manifest);
  const blob = new Blob([json], { type: "application/json" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `tpi-backup-${new Date().toISOString().slice(0, 10)}.json`;
  a.click();
  URL.revokeObjectURL(url);
}

