/**
 * Document service (TPI-V2-WEB-006) — the authoritative document lifecycle.
 *
 * iOS origins: PPCaseDocumentEngine, PPDocumentCompletionEngine. Browser
 * additions required by directive §7/§8: content-hash signature binding,
 * signature invalidation on content change, immutable finalized versions,
 * superseding, and documented inapplicability.
 *
 * Document events are recorded through the existing append-only AuditService
 * (no competing event store). All storage is local; nothing is uploaded.
 */
import type { TPIDatabase } from "../db";
import { v4 as uuidv4 } from "../../shared/uuid";
import type {
  DocumentInstanceRecord,
  DocumentVersionRecord,
  SignatureRecord,
  SignatureMethod,
  SignatureRole,
} from "../types";
import { ValidationError } from "../validation";
import { AuditService } from "../audit";
import { hashBuffer } from "../files/opfs.hash";
import { DOCUMENT_TEMPLATES, REQUIRED_DOCUMENT_ORDER, templateFor, TEMPLATE_VERSION, type DocumentTemplate } from "./templates";
import { renderDocument, renderContextForCase } from "./renderer";

export interface DocumentsBlocker {
  documentId: string | null;
  templateId: string;
  title: string;
  reason: string;
  requiredAction: string;
  nonOverridable: boolean;
}

async function sha256Text(text: string): Promise<string> {
  return hashBuffer(new TextEncoder().encode(text).buffer as ArrayBuffer);
}

/** Canonical content used for signature binding and integrity checks. */
export async function computeContentHash(
  instance: Pick<DocumentInstanceRecord, "templateId" | "templateVersion" | "fieldValues">,
  renderedBody: string,
): Promise<string> {
  const canonical = JSON.stringify({
    templateVersion: instance.templateVersion,
    templateId: instance.templateId,
    fieldValues: sortedValues(instance.fieldValues),
    body: renderedBody,
  });
  return sha256Text(canonical);
}

function sortedValues(values: Record<string, string>): Record<string, string> {
  const out: Record<string, string> = {};
  for (const key of Object.keys(values).sort()) out[key] = values[key] ?? "";
  return out;
}

export class DocumentService {
  private readonly audit: AuditService;

  constructor(private readonly db: TPIDatabase) {
    this.audit = new AuditService(db);
  }

  /* ------------------------- template / instance setup ------------------------ */

  /** Idempotently create `notStarted` instances for every required template. */
  async ensureDocumentsForCase(caseId: string): Promise<DocumentInstanceRecord[]> {
    const existing = await this.listForCase(caseId);
    const have = new Set(existing.map((d) => d.templateId));
    for (const template of DOCUMENT_TEMPLATES.filter((t) => t.isRequired)) {
      if (have.has(template.id)) continue;
      const instance = this.newInstance(caseId, template);
      await this.db.documentInstances.put(instance);
      await this.audit.record("documentCreated", `Document created: ${template.title}`, {
        caseId,
        affectedRecordId: instance.id,
        metadata: { templateId: template.id, required: true },
      });
    }
    return this.listForCase(caseId);
  }

  /** Create an instance for an optional/custom template. */
  async createOptionalDocument(caseId: string, templateId: DocumentFormTypeFromTemplate): Promise<DocumentInstanceRecord> {
    const template = templateFor(templateId);
    const instance = this.newInstance(caseId, template);
    await this.db.documentInstances.put(instance);
    await this.audit.record("documentCreated", `Document created: ${template.title}`, {
      caseId,
      affectedRecordId: instance.id,
      metadata: { templateId: template.id, required: template.isRequired },
    });
    return instance;
  }

  private newInstance(caseId: string, template: DocumentTemplate): DocumentInstanceRecord {
    const ts = Date.now();
    return {
      id: uuidv4(),
      schemaVersion: 6,
      createdAt: ts,
      updatedAt: ts,
      caseId,
      templateId: template.id,
      templateVersion: TEMPLATE_VERSION,
      status: "notStarted",
      isRequired: template.isRequired,
      sortIndex: template.sortIndex,
      clientId: null,
      fieldValues: {},
      contentHash: null,
      openedAt: null,
      finalizedAt: null,
      finalizedVersionId: null,
      supersedesId: null,
      supersededById: null,
      voidReason: "",
      notes: "",
      applicability: { applicable: true, determinedBy: null, justification: "", determinedAt: null },
    };
  }

  async listForCase(caseId: string): Promise<DocumentInstanceRecord[]> {
    const rows = await this.db.documentInstances.where("caseId").equals(caseId).toArray();
    rows.sort((a, b) => a.sortIndex - b.sortIndex || a.createdAt - b.createdAt);
    return rows;
  }

  async get(documentId: string): Promise<DocumentInstanceRecord | undefined> {
    return this.db.documentInstances.get(documentId);
  }

  async signaturesFor(documentId: string): Promise<SignatureRecord[]> {
    const rows = await this.db.documentSignatures.where("documentId").equals(documentId).toArray();
    return rows.sort((a, b) => a.createdAt - b.createdAt);
  }

  async versionsFor(documentId: string): Promise<DocumentVersionRecord[]> {
    const rows = await this.db.documentVersions.where("documentId").equals(documentId).toArray();
    return rows.sort((a, b) => a.versionNumber - b.versionNumber);
  }

  /* ------------------------------- draft editing ------------------------------ */

  /** Validate field values against the template's fillable fields. */
  validateFields(templateId: DocumentFormTypeFromTemplate, fieldValues: Record<string, string>): string[] {
    const template = templateFor(templateId);
    const errors: string[] = [];
    for (const field of template.fields) {
      const value = (fieldValues[field.id] ?? "").trim();
      if (field.required && value.length === 0) {
        errors.push(`${field.label} is required.`);
      }
      if (field.type === "select" && value.length > 0 && field.options && !field.options.includes(value)) {
        errors.push(`${field.label} must be one of the listed options.`);
      }
    }
    return errors;
  }

  /**
   * Save a draft. If the signed content changes, previously active signatures
   * are invalidated (directive §8 — a signature binds to the exact content
   * presented to the signer; signed documents are never silently modified).
   */
  async saveDraft(
    documentId: string,
    fieldValues: Record<string, string>,
    options: { notes?: string; actor?: string } = {},
  ): Promise<DocumentInstanceRecord> {
    // Pre-compute content outside the transaction — crypto.subtle awaits are
    // not tracked by Dexie's transaction zone and would commit it prematurely.
    const pre = await this.db.documentInstances.get(documentId);
    if (!pre) throw new ValidationError(`Document not found: ${documentId}`, "documentId");
    const preCase = await this.db.cases.get(pre.caseId);
    if (!preCase) throw new ValidationError(`Case not found: ${pre.caseId}`, "caseId");
    const preBody = renderDocument(pre.templateId, { fieldValues }, renderContextForCase(preCase));
    const newHash = await computeContentHash({ ...pre, fieldValues }, preBody);
    const contentChanged = pre.contentHash !== null && pre.contentHash !== newHash;

    const result = await this.db.transaction(
      "rw",
      this.db.documentInstances,
      this.db.documentSignatures,
      this.db.cases,
      this.db.auditEvents,
      async () => {
      const instance = await this.db.documentInstances.get(documentId);
      if (!instance) throw new ValidationError(`Document not found: ${documentId}`, "documentId");
      if (instance.status === "finalized") {
        throw new ValidationError("Finalized documents are immutable — create an amendment instead.", "status");
      }
      if (instance.status === "voided" || instance.status === "superseded") {
        throw new ValidationError(`A ${instance.status} document cannot be edited.`, "status");
      }
      const errors = this.validateFields(instance.templateId, fieldValues);
      if (errors.length > 0) {
        throw new ValidationError(`Invalid document fields: ${errors.join(" ")}`, "fieldValues");
      }
      const invalidated: string[] = [];
      if (contentChanged) {
        const sigs = await this.db.documentSignatures.where("documentId").equals(documentId).toArray();
        for (const sig of sigs) {
          if (sig.active) {
            const updatedSig: SignatureRecord = {
              ...sig,
              active: false,
              invalidatedAt: Date.now(),
              invalidatedReason: "Document content changed after signing; the prior signature no longer authorizes this version.",
            };
            await this.db.documentSignatures.put(updatedSig);
            invalidated.push(`${sig.signerRole} (${sig.id})`);
          }
        }
      }

      const next: DocumentInstanceRecord = {
        ...instance,
        fieldValues: { ...fieldValues },
        notes: options.notes ?? instance.notes,
        contentHash: newHash,
        status: "awaitingSignature",
        updatedAt: Date.now(),
      };
      await this.db.documentInstances.put(next);
      await this.audit.record(
        "documentUpdated",
        contentChanged
          ? `Draft saved; ${invalidated.length} prior signature(s) invalidated by content change.`
          : "Draft saved.",
        {
          caseId: instance.caseId,
          affectedRecordId: documentId,
          metadata: { contentHash: newHash, invalidatedSignatures: invalidated.length },
        },
      );
      if (invalidated.length > 0) {
        await this.audit.record("signatureInvalidated", "Signatures invalidated because the signed document content changed.", {
          caseId: instance.caseId,
          affectedRecordId: documentId,
          metadata: { roles: invalidated.join(",") },
        });
      }
      return next;
      },
    );
    return result;
  }

  async markOpened(documentId: string): Promise<void> {
    const instance = await this.db.documentInstances.get(documentId);
    if (instance && instance.openedAt === null) {
      await this.db.documentInstances.put({ ...instance, openedAt: Date.now(), updatedAt: Date.now() });
    }
  }

  /* -------------------------------- signatures -------------------------------- */

  /**
   * Capture a signature bound to the exact current content hash. Requires an
   * explicit intent acknowledgment. No identity verification is performed or
   * claimed (docs/SIGNATURE_AND_CONSENT.md).
   */
  async captureSignature(
    documentId: string,
    input: {
      signerName: string;
      signerRole: SignatureRole;
      method: SignatureMethod;
      imageDataUrl?: string | null;
      intentAcknowledged: boolean;
      actor?: string;
    },
  ): Promise<SignatureRecord> {
    const result = await this.db.transaction(
      "rw",
      this.db.documentInstances,
      this.db.documentSignatures,
      this.db.auditEvents,
      async () => {
      const instance = await this.db.documentInstances.get(documentId);
      if (!instance) throw new ValidationError(`Document not found: ${documentId}`, "documentId");
      if (!["draft", "awaitingSignature", "signed"].includes(instance.status)) {
        throw new ValidationError(`Signature cannot be captured on a ${instance.status} document.`, "status");
      }
      if (!input.intentAcknowledged) {
        throw new ValidationError("Explicit signing intent acknowledgment is required.", "intentAcknowledged");
      }
      if (!input.signerName.trim()) {
        throw new ValidationError("Signer name is required.", "signerName");
      }
      if (input.method === "drawn" && !input.imageDataUrl) {
        throw new ValidationError("A drawn signature requires signature image data.", "imageDataUrl");
      }
      if (instance.contentHash === null) {
        throw new ValidationError("Save the completed document draft before signing.", "contentHash");
      }
      // Replace any prior signature by the same role for this document.
      const prior = await this.db.documentSignatures.where("documentId").equals(documentId).toArray();
      for (const sig of prior) {
        if (sig.signerRole === input.signerRole && sig.active) {
          await this.db.documentSignatures.put({
            ...sig,
            active: false,
            invalidatedAt: Date.now(),
            invalidatedReason: `Replaced by a new ${input.signerRole} signature.`,
          });
        }
      }
      const sig: SignatureRecord = {
        id: uuidv4(),
        schemaVersion: 6,
        createdAt: Date.now(),
        documentId,
        caseId: instance.caseId,
        versionId: instance.finalizedVersionId,
        signerName: input.signerName.trim(),
        signerRole: input.signerRole,
        method: input.method,
        imageDataUrl: input.imageDataUrl ?? null,
        intentAcknowledged: true,
        contentHash: instance.contentHash,
        signedAt: Date.now(),
        active: true,
        invalidatedAt: null,
        invalidatedReason: "",
      };
      await this.db.documentSignatures.put(sig);
      const next = await this.recomputeStatus(instance);
      if (next.status !== instance.status) {
        await this.db.documentInstances.put(next);
      }
      await this.audit.record("signatureCaptured", `Signature captured (${input.signerRole}, ${input.method}).`, {
        caseId: instance.caseId,
        affectedRecordId: documentId,
        metadata: { role: input.signerRole, method: input.method, signatureId: sig.id, contentHash: sig.contentHash },
      });
      if (next.status !== instance.status) {
        await this.audit.record("documentUpdated", `Document status: ${instance.status} → ${next.status}.`, {
          caseId: instance.caseId,
          affectedRecordId: documentId,
          metadata: { status: next.status },
        });
      }
      return sig;
      },
    );
    return result;
  }

  async clearSignature(documentId: string, role: SignatureRole): Promise<void> {
    await this.db.transaction("rw", this.db.documentInstances, this.db.documentSignatures, async () => {
      const instance = await this.db.documentInstances.get(documentId);
      if (!instance) throw new ValidationError(`Document not found: ${documentId}`, "documentId");
      const sigs = await this.db.documentSignatures.where("documentId").equals(documentId).toArray();
      for (const sig of sigs) {
        if (sig.signerRole === role && sig.active) {
          await this.db.documentSignatures.put({
            ...sig,
            active: false,
            invalidatedAt: Date.now(),
            invalidatedReason: `Cleared by user (${role}).`,
          });
        }
      }
      const next = await this.recomputeStatus(instance);
      if (next.status !== instance.status) {
        await this.db.documentInstances.put(next);
      }
    });
  }

  /** Recompute status from field validity + active signature coverage. */
  private async recomputeStatus(instance: DocumentInstanceRecord): Promise<DocumentInstanceRecord> {
    const next = { ...instance, updatedAt: Date.now() };
    if (["finalized", "voided", "superseded"].includes(instance.status)) return next;
    const sigs = await this.db.documentSignatures.where("documentId").equals(instance.id).toArray();
    const active = sigs.filter((s) => s.active && s.contentHash === instance.contentHash);
    const roles = new Set(active.map((s) => s.signerRole));
    const complete = roles.has("client") && roles.has("investigator");
    next.status = complete ? "signed" : "awaitingSignature";
    return next;
  }

  /* ------------------------- finalization / versions -------------------------- */

  /** Finalize: immutable version snapshot (application-level immutability). */
  async finalize(documentId: string, actor = "local-user"): Promise<DocumentVersionRecord> {
    const pre = await this.db.documentInstances.get(documentId);
    if (!pre) throw new ValidationError(`Document not found: ${documentId}`, "documentId");
    if (pre.status !== "signed") {
      throw new ValidationError(
        "A document can only be finalized when all required signatures are captured against its current content.",
        "status",
      );
    }
    const preCase = await this.db.cases.get(pre.caseId);
    if (!preCase) throw new ValidationError(`Case not found: ${pre.caseId}`, "caseId");
    const body = renderDocument(pre.templateId, pre, renderContextForCase(preCase));
    const contentHash = await computeContentHash(pre, body);

    const version = await this.db.transaction(
      "rw",
      this.db.documentInstances,
      this.db.documentVersions,
      this.db.documentSignatures,
      this.db.cases,
      this.db.auditEvents,
      async () => {
      const instance = await this.db.documentInstances.get(documentId);
      if (!instance) throw new ValidationError(`Document not found: ${documentId}`, "documentId");
      if (instance.status !== "signed") {
        throw new ValidationError(
          "A document can only be finalized when all required signatures are captured against its current content.",
          "status",
        );
      }
      const versions = await this.db.documentVersions.where("documentId").equals(documentId).toArray();
      const version: DocumentVersionRecord = {
        id: uuidv4(),
        schemaVersion: 6,
        createdAt: Date.now(),
        documentId,
        caseId: instance.caseId,
        versionNumber: versions.length + 1,
        label: "final",
        templateId: instance.templateId,
        templateVersion: instance.templateVersion,
        content: body,
        contentHash,
        fieldValues: { ...instance.fieldValues },
        signatureIds: (await this.signaturesFor(documentId)).filter((s) => s.active && s.contentHash === contentHash).map((s) => s.id),
        createdBy: actor,
      };
      await this.db.documentVersions.put(version);
      const finalizedInstance: DocumentInstanceRecord = {
        ...instance,
        status: "finalized",
        finalizedAt: Date.now(),
        finalizedVersionId: version.id,
        updatedAt: Date.now(),
      };
      await this.db.documentInstances.put(finalizedInstance);
      await this.audit.record("documentFinalized", `Document finalized (version ${version.versionNumber}).`, {
        caseId: instance.caseId,
        affectedRecordId: documentId,
        metadata: { versionId: version.id, contentHash, signatures: version.signatureIds.length },
      });
      return version;
      },
    );
    await this.reconcileChecklist(version.caseId);
    return version;
  }

  /** Version history — finalized snapshots plus the current draft hash. */
  async versionHistory(documentId: string): Promise<DocumentVersionRecord[]> {
    return this.versionsFor(documentId);
  }

  /** Explicit amendment: new draft instance superseding the finalized one. */
  async createAmendment(documentId: string, reason: string): Promise<DocumentInstanceRecord> {
    if (!reason.trim()) throw new ValidationError("An amendment requires a documented reason.", "reason");
    const amendment = await this.db.transaction("rw", this.db.documentInstances, this.db.auditEvents, async () => {
      const instance = await this.db.documentInstances.get(documentId);
      if (!instance) throw new ValidationError(`Document not found: ${documentId}`, "documentId");
      if (instance.status !== "finalized") {
        throw new ValidationError("Only a finalized document can be superseded by an amendment.", "status");
      }
      const template = templateFor(instance.templateId);
      const amendment = this.newInstance(instance.caseId, template);
      amendment.supersedesId = instance.id;
      amendment.fieldValues = { ...instance.fieldValues };
      amendment.status = "draft";
      amendment.contentHash = instance.contentHash; // carried over; invalidated on first save
      await this.db.documentInstances.put(amendment);
      await this.db.documentInstances.put({
        ...instance,
        status: "superseded",
        supersededById: amendment.id,
        updatedAt: Date.now(),
      });
      await this.audit.record("documentSuperseded", `Amendment created, superseding prior finalized document. Reason: ${reason.slice(0, 200)}`, {
        caseId: instance.caseId,
        affectedRecordId: amendment.id,
        metadata: { supersedesId: instance.id },
      });
      return amendment;
    });
    await this.reconcileChecklist(amendment.caseId);
    return amendment;
  }

  async voidDocument(documentId: string, reason: string): Promise<DocumentInstanceRecord> {
    if (!reason.trim()) throw new ValidationError("Voiding a document requires a documented reason.", "reason");
    const next = await this.db.transaction("rw", this.db.documentInstances, this.db.auditEvents, async () => {
      const instance = await this.db.documentInstances.get(documentId);
      if (!instance) throw new ValidationError(`Document not found: ${documentId}`, "documentId");
      const next: DocumentInstanceRecord = { ...instance, status: "voided", voidReason: reason, updatedAt: Date.now() };
      await this.db.documentInstances.put(next);
      await this.audit.record("documentVoided", `Document voided. Reason: ${reason.slice(0, 200)}`, {
        caseId: instance.caseId,
        affectedRecordId: documentId,
      });
      return next;
    });
    await this.reconcileChecklist(next.caseId);
    return next;
  }

  /** Explicit, justified determination that a document does not apply. */
  async determineApplicability(
    documentId: string,
    applicable: boolean,
    justification: string,
    determinedBy = "investigator",
  ): Promise<DocumentInstanceRecord> {
    if (!applicable && !justification.trim()) {
      throw new ValidationError("Declaring a document inapplicable requires a documented justification.", "justification");
    }
    const updated = await this.db.transaction("rw", this.db.documentInstances, this.db.auditEvents, async () => {
      const instance = await this.db.documentInstances.get(documentId);
      if (!instance) throw new ValidationError(`Document not found: ${documentId}`, "documentId");
      if (instance.status === "finalized") {
        throw new ValidationError("Amend a finalized document instead of changing applicability.", "status");
      }
      const next: DocumentInstanceRecord = {
        ...instance,
        applicability: {
          applicable,
          determinedBy: determinedBy,
          justification: applicable ? "" : justification,
          determinedAt: Date.now(),
        },
        updatedAt: Date.now(),
      };
      await this.db.documentInstances.put(next);
      await this.audit.record(
        "documentApplicabilityDetermined",
        applicable ? "Document marked applicable." : `Document determined inapplicable: ${justification.slice(0, 200)}`,
        { caseId: instance.caseId, affectedRecordId: documentId, metadata: { applicable } },
      );
      return next;
    });
    await this.reconcileChecklist(updated.caseId);
    return updated;
  }

  /* ---------------------------- readiness / blockers --------------------------- */

  /**
   * Evaluate the documents phase from REAL persisted records (directive §10).
   * A checklist checkbox never satisfies these requirements.
   */
  async evaluateCaseDocuments(caseId: string): Promise<DocumentsBlocker[]> {
    await this.ensureDocumentsForCase(caseId);
    const docs = await this.listForCase(caseId);
    const blockers: DocumentsBlocker[] = [];
    for (const doc of docs) {
      if (!doc.isRequired) continue;
      const template = templateFor(doc.templateId);
      if (!doc.applicability.applicable && doc.applicability.determinedBy && doc.applicability.justification.trim()) {
        continue; // documented inapplicability — no false "signed" claim
      }
      if (doc.status === "voided") {
        blockers.push({
          documentId: doc.id,
          templateId: doc.templateId,
          title: template.title,
          reason: `${template.title} was voided and must be redone.`,
          requiredAction: "Create an amendment or a replacement document.",
          nonOverridable: true,
        });
        continue;
      }
      if (doc.status === "superseded") {
        blockers.push({
          documentId: doc.supersededById ?? doc.id,
          templateId: doc.templateId,
          title: template.title,
          reason: `${template.title} was superseded by an amendment that is not finalized.`,
          requiredAction: "Complete and finalize the amendment document.",
          nonOverridable: true,
        });
        continue;
      }
      if (doc.status === "finalized") {
        const ok = await this.finalizedIntegrityOk(doc);
        if (!ok) {
          blockers.push({
            documentId: doc.id,
            templateId: doc.templateId,
            title: template.title,
            reason: `${template.title} finalized content does not match its recorded signatures.`,
            requiredAction: "Create an amendment and re-capture signatures.",
            nonOverridable: true,
          });
        }
        continue;
      }
      // notStarted / draft / awaitingSignature / signed
      const fieldErrors = this.validateFields(doc.templateId, doc.fieldValues);
      const sigs = (await this.signaturesFor(doc.id)).filter((s) => s.active);
      const roles = new Set(sigs.map((s) => s.signerRole));
      if (doc.status === "notStarted" || fieldErrors.length > 0) {
        blockers.push({
          documentId: doc.id,
          templateId: doc.templateId,
          title: template.title,
          reason: `${template.title} has not been completed (${doc.status === "notStarted" ? "not started" : "required fields missing"}).`,
          requiredAction: "Complete the required fields in the Documents Center.",
          nonOverridable: true,
        });
      } else if (!roles.has("client") || !roles.has("investigator")) {
        blockers.push({
          documentId: doc.id,
          templateId: doc.templateId,
          title: template.title,
          reason: `${template.title} is missing ${roles.has("client") ? "the investigator" : "the client"} signature.`,
          requiredAction: "Capture the missing signature in the Documents Center.",
          nonOverridable: true,
        });
      } else {
        blockers.push({
          documentId: doc.id,
          templateId: doc.templateId,
          title: template.title,
          reason: `${template.title} is signed but not finalized.`,
          requiredAction: "Review and finalize the document.",
          nonOverridable: true,
        });
      }
    }
    return blockers;
  }

  /** Integrity check: the finalized version's hash matches the bound signatures. */
  private async finalizedIntegrityOk(doc: DocumentInstanceRecord): Promise<boolean> {
    if (!doc.finalizedVersionId) return false;
    const version = await this.db.documentVersions.get(doc.finalizedVersionId);
    if (!version) return false;
    if (version.contentHash !== doc.contentHash) return false;
    const sigs = await this.signaturesFor(doc.id);
    const bound = sigs.filter((s) => s.active && s.contentHash === version.contentHash);
    const roles = new Set(bound.map((s) => s.signerRole));
    return roles.has("client") && roles.has("investigator");
  }

  /**
   * Safe checklist reconciliation (directive §10 migration consideration):
   * `requiredDocumentsSigned` may only read "complete" when real signed +
   * finalized document records exist. A previously checked item without
   * backing records is reset to pending with an explanatory note.
   */
  async reconcileChecklist(caseId: string): Promise<void> {
    const blockers = await this.evaluateCaseDocuments(caseId);
    await this.reconcileChecklistFromBlockers(caseId, blockers);
  }

  /** Checklist sync from pre-computed blockers (used by the workflow engine). */
  async reconcileChecklistFromBlockers(caseId: string, blockers: DocumentsBlocker[]): Promise<void> {
    const items = await this.db.checklistItems.where("caseId").equals(caseId).toArray();
    const item = items.find((i) => i.definitionId === "requiredDocumentsSigned");
    if (!item) return;
    const requiredBlockers = blockers.filter((b) => b.nonOverridable);
    const satisfied = requiredBlockers.length === 0;
    if (satisfied && item.status !== "complete") {
      await this.db.checklistItems.put({
        ...item,
        status: "complete",
        completedAt: Date.now(),
        completedBy: "document-service",
        updatedAt: Date.now(),
      });
      await this.audit.record("checklistChanged", "Required documents checklist satisfied by finalized document records.", {
        caseId,
        affectedRecordId: item.id,
      });
    } else if (!satisfied && (item.status === "complete" || item.status === "exception")) {
      await this.db.checklistItems.put({
        ...item,
        status: "pending",
        completedAt: null,
        completedBy: null,
        notes:
          "Reconciled under TPI-V2-WEB-006: the previous checklist completion was not backed by signed, finalized document records.",
        updatedAt: Date.now(),
      });
      await this.audit.record("checklistChanged", "Required-documents checklist item reset — no signed/finalized backing records existed.", {
        caseId,
        affectedRecordId: item.id,
      });
    }
  }
}

/** Helper type so callers can pass any registered template id. */
export type DocumentFormTypeFromTemplate = (typeof DOCUMENT_TEMPLATES)[number]["id"] | "other";
export { REQUIRED_DOCUMENT_ORDER };
