/**
 * Claim import service (C6A).
 *
 * Imports source-backed reported claims without a UI. It preserves source
 * identity, source text and source classification; never converts a reported
 * claim into an observation or evidence record; never changes case phase,
 * checklist/readiness state or investigation completion.
 *
 * Import identity is deterministic and case-scoped:
 *   caseId | sourceType | sourceReference | sourceClaimId
 * Statement text is NEVER part of the identity, so identical reports from
 * different witnesses remain separate claims.
 */
import type { TPIDatabase } from "../db";
import { now } from "../db";
import { ValidationError, assertNonEmpty, assertReferenceExists } from "../validation";
import { ClaimRepository, type ClaimCreateInput } from "../repositories/claimsRepository";
import type {
  ClaimClassification,
  ClaimImportSourceType,
  ClaimRecord,
  ClaimWalkthroughStatus,
} from "../types";

export interface ClaimImportItem {
  /** Stable source identifier. Required; never derived from statement text. */
  sourceClaimId: string;
  title: string;
  /** Verbatim source statement. Preserved unchanged. */
  sourceText?: string | null;
  classification?: ClaimClassification;
  classificationResolved?: boolean;
  locationId?: string | null;
  roomID?: string | null;
  roomTBD?: boolean;
  roomName?: string;
  subLocation?: string;
  linkedRoomIds?: string[];
  occurrenceLevel?: string;
  claimType?: string;
  claimTypeOtherText?: string;
  firstOccurrenceText?: string;
  mostRecentOccurrenceText?: string;
  frequency?: string;
  timePattern?: string;
  weatherCorrelation?: boolean;
  weatherPattern?: string;
  witnessCount?: number;
  witnessesText?: string;
  witnessCountResolved?: boolean;
  witnessMemberIds?: string[];
  emotionalImpact?: number;
  emotionalImpactResolved?: boolean;
  feelingText?: string;
  feelingNotes?: string;
  notes?: string;
  linkedPinID?: string | null;
  walkthroughStatus?: ClaimWalkthroughStatus;
  mostRecentOccurrenceKnown?: boolean | null;
  isGuidedDraft?: boolean;
  sourceOccurrenceText?: string | null;
  sourceOccurrenceAt?: number | null;
}

export interface ClaimImportRequest {
  caseId: string;
  sourceType: ClaimImportSourceType;
  /** Source container identity, e.g. a reference-location id. */
  sourceReference: string;
  importedAt?: number;
  items: ClaimImportItem[];
}

export interface ClaimImportConflict {
  sourceClaimId: string;
  existingClaimId: string;
  reason: "content-differs";
}

export interface ClaimImportRejection {
  index: number;
  sourceClaimId: string | null;
  reason: string;
}

export interface ClaimImportResult {
  imported: number;
  skipped: number;
  conflicts: ClaimImportConflict[];
  rejected: ClaimImportRejection[];
  claimIds: string[];
}

export type ClaimImportInspectionStatus =
  | "new"
  | "duplicate"
  | "conflict"
  | "rejected";

export interface ClaimImportInspectionEntry {
  index: number;
  sourceClaimId: string | null;
  status: ClaimImportInspectionStatus;
  existingClaimId?: string;
  reason?: string;
}

export interface ClaimImportInspection {
  entries: ClaimImportInspectionEntry[];
  newCount: number;
  duplicateCount: number;
  conflictCount: number;
  rejectedCount: number;
}

/** Deterministic, case-scoped import identity. Never uses statement text. */
export function claimImportIdentity(
  caseId: string,
  sourceType: ClaimImportSourceType,
  sourceReference: string,
  sourceClaimId: string,
): string {
  return [caseId, sourceType, sourceReference, sourceClaimId]
    .map((part) => part.trim())
    .join("|");
}

async function sha256Hex(value: string): Promise<string> {
  const bytes = new TextEncoder().encode(value);
  const digest = await crypto.subtle.digest("SHA-256", bytes);
  return Array.from(new Uint8Array(digest), (b) =>
    b.toString(16).padStart(2, "0"),
  ).join("");
}

/** Material fields compared when the same import identity is seen again. */
function contentFingerprint(claim: {
  title: string;
  sourceText: string | null;
  sourceOccurrenceText: string | null;
  sourceOccurrenceAt: number | null;
  classification: ClaimClassification;
  claimType: string;
  occurrenceLevel: string;
  firstOccurrenceText: string;
  mostRecentOccurrenceText: string;
  witnessesText: string;
  witnessCount: number;
  witnessMemberIds: string[];
  emotionalImpact: number;
  feelingText: string;
  notes: string;
  locationId: string | null;
  roomID: string | null;
  linkedRoomIds: string[];
}): string {
  return JSON.stringify({
    title: claim.title,
    sourceText: claim.sourceText,
    sourceOccurrenceText: claim.sourceOccurrenceText,
    sourceOccurrenceAt: claim.sourceOccurrenceAt,
    classification: claim.classification,
    claimType: claim.claimType,
    occurrenceLevel: claim.occurrenceLevel,
    firstOccurrenceText: claim.firstOccurrenceText,
    mostRecentOccurrenceText: claim.mostRecentOccurrenceText,
    witnessesText: claim.witnessesText,
    witnessCount: claim.witnessCount,
    witnessMemberIds: [...claim.witnessMemberIds].sort(),
    emotionalImpact: claim.emotionalImpact,
    feelingText: claim.feelingText,
    notes: claim.notes,
    locationId: claim.locationId,
    roomID: claim.roomID,
    linkedRoomIds: [...claim.linkedRoomIds].sort(),
  });
}

function existingFingerprint(claim: ClaimRecord): string {
  return contentFingerprint(claim);
}

function incomingFingerprint(
  item: ClaimImportItem,
  sourceOccurrenceAt: number | null,
): string {
  return contentFingerprint({
    title: item.title.trim(),
    sourceText: item.sourceText ?? null,
    sourceOccurrenceText: item.sourceOccurrenceText ?? null,
    sourceOccurrenceAt,
    classification: item.classification ?? "Client Reported",
    claimType: item.claimType ?? "Other",
    occurrenceLevel: item.occurrenceLevel ?? "",
    firstOccurrenceText: item.firstOccurrenceText ?? "",
    mostRecentOccurrenceText: item.mostRecentOccurrenceText ?? "",
    witnessesText: item.witnessesText ?? "",
    witnessCount: item.witnessCount ?? 0,
    witnessMemberIds: item.witnessMemberIds ?? [],
    emotionalImpact: item.emotionalImpact ?? 0,
    feelingText: item.feelingText ?? "",
    notes: item.notes ?? "",
    locationId: item.locationId ?? null,
    roomID: item.roomID ?? null,
    linkedRoomIds: item.linkedRoomIds ?? [],
  });
}

export class ClaimImportService {
  private readonly claims: ClaimRepository;

  constructor(private readonly db: TPIDatabase) {
    this.claims = new ClaimRepository(db);
  }

  /**
   * Read-only preflight for a caller that needs to review duplicate/conflict
   * status before writing. It performs no create, update, audit or clock write.
   */
  async inspectClaims(request: ClaimImportRequest): Promise<ClaimImportInspection> {
    assertNonEmpty(request.caseId, "caseId");
    assertNonEmpty(request.sourceReference, "sourceReference");
    const caseRecord = await this.db.cases.get(request.caseId);
    assertReferenceExists(request.caseId, caseRecord !== undefined, "caseId");
    if (!caseRecord) throw new ValidationError("Referenced case not found", "caseId");

    const plan: ClaimImportInspection = {
      entries: [],
      newCount: 0,
      duplicateCount: 0,
      conflictCount: 0,
      rejectedCount: 0,
    };

    for (const [index, item] of request.items.entries()) {
      const sourceClaimId = item.sourceClaimId?.trim() ?? "";
      if (!sourceClaimId) {
        plan.entries.push({
          index,
          sourceClaimId: null,
          status: "rejected",
          reason: "Missing source identity",
        });
        plan.rejectedCount += 1;
        continue;
      }

      const identity = claimImportIdentity(
        request.caseId,
        request.sourceType,
        request.sourceReference,
        sourceClaimId,
      );
      const existing = await this.claims.findByImportIdentity(
        request.caseId,
        identity,
      );
      if (!existing) {
        plan.entries.push({ index, sourceClaimId, status: "new" });
        plan.newCount += 1;
        continue;
      }

      if (
        existingFingerprint(existing) ===
        incomingFingerprint(item, item.sourceOccurrenceAt ?? null)
      ) {
        plan.entries.push({
          index,
          sourceClaimId,
          status: "duplicate",
          existingClaimId: existing.id,
        });
        plan.duplicateCount += 1;
      } else {
        plan.entries.push({
          index,
          sourceClaimId,
          status: "conflict",
          existingClaimId: existing.id,
          reason: "content-differs",
        });
        plan.conflictCount += 1;
      }
    }

    return plan;
  }

  async importClaims(request: ClaimImportRequest): Promise<ClaimImportResult> {
    assertNonEmpty(request.caseId, "caseId");
    assertNonEmpty(request.sourceReference, "sourceReference");
    const caseRecord = await this.db.cases.get(request.caseId);
    assertReferenceExists(request.caseId, caseRecord !== undefined, "caseId");
    if (!caseRecord) throw new ValidationError("Referenced case not found", "caseId");

    const importedAt = request.importedAt ?? now();
    const result: ClaimImportResult = {
      imported: 0,
      skipped: 0,
      conflicts: [],
      rejected: [],
      claimIds: [],
    };

    for (const [index, item] of request.items.entries()) {
      const sourceClaimId = item.sourceClaimId?.trim() ?? "";
      if (!sourceClaimId) {
        result.rejected.push({
          index,
          sourceClaimId: null,
          reason: "Missing source identity",
        });
        continue;
      }

      const sourceOccurrenceAt = item.sourceOccurrenceAt ?? null;
      const identity = claimImportIdentity(
        request.caseId,
        request.sourceType,
        request.sourceReference,
        sourceClaimId,
      );
      const existing = await this.claims.findByImportIdentity(
        request.caseId,
        identity,
      );
      if (existing) {
        if (existingFingerprint(existing) === incomingFingerprint(item, sourceOccurrenceAt)) {
          result.skipped += 1;
          result.claimIds.push(existing.id);
        } else {
          result.conflicts.push({
            sourceClaimId,
            existingClaimId: existing.id,
            reason: "content-differs",
          });
        }
        continue;
      }

      const sourceText = item.sourceText ?? null;
      const input: ClaimCreateInput = {
        caseId: request.caseId,
        claimID: undefined,
        title: item.title,
        locationId: item.locationId ?? null,
        roomID: item.roomID ?? null,
        roomTBD: item.roomTBD ?? false,
        roomName: item.roomName ?? "",
        subLocation: item.subLocation ?? "",
        linkedRoomIds: item.linkedRoomIds ?? [],
        occurrenceLevel: item.occurrenceLevel ?? "",
        claimType: item.claimType ?? "Other",
        claimTypeOtherText: item.claimTypeOtherText ?? "",
        firstOccurrenceText: item.firstOccurrenceText ?? "",
        mostRecentOccurrenceText: item.mostRecentOccurrenceText ?? "",
        frequency: item.frequency ?? "",
        timePattern: item.timePattern ?? "",
        weatherCorrelation: item.weatherCorrelation ?? false,
        weatherPattern: item.weatherPattern ?? "",
        witnessCount: item.witnessCount ?? 0,
        witnessesText: item.witnessesText ?? "",
        witnessCountResolved: item.witnessCountResolved ?? false,
        witnessMemberIds: item.witnessMemberIds ?? [],
        emotionalImpact: item.emotionalImpact ?? 0,
        emotionalImpactResolved: item.emotionalImpactResolved ?? false,
        feelingText: item.feelingText ?? "",
        feelingNotes: item.feelingNotes ?? "",
        classification: item.classification ?? "Client Reported",
        classificationResolved: item.classificationResolved ?? false,
        notes: item.notes ?? "",
        linkedPinID: item.linkedPinID ?? null,
        walkthroughStatus: item.walkthroughStatus ?? "Not Located",
        mostRecentOccurrenceKnown: item.mostRecentOccurrenceKnown ?? null,
        isGuidedDraft: item.isGuidedDraft ?? false,
        importedFromReference: request.sourceType === "referenceLocation",
        importSourceType: request.sourceType,
        importSourceRef: request.sourceReference,
        importSourceClaimId: sourceClaimId,
        importIdentity: identity,
        importedAt,
        sourceText,
        sourceTextHash: sourceText === null ? null : await sha256Hex(sourceText),
        sourceOccurrenceText: item.sourceOccurrenceText ?? null,
        sourceOccurrenceAt,
      };

      try {
        const created = await this.claims.create(input);
        result.imported += 1;
        result.claimIds.push(created.id);
      } catch (error) {
        // A concurrent import may have won the unique identity/claim race.
        const raced = await this.claims.findByImportIdentity(
          request.caseId,
          identity,
        );
        if (raced) {
          if (existingFingerprint(raced) === incomingFingerprint(item, sourceOccurrenceAt)) {
            result.skipped += 1;
            result.claimIds.push(raced.id);
          } else {
            result.conflicts.push({
              sourceClaimId,
              existingClaimId: raced.id,
              reason: "content-differs",
            });
          }
        } else if (error instanceof ValidationError) {
          result.rejected.push({
            index,
            sourceClaimId,
            reason: error.message,
          });
        } else {
          throw error;
        }
      }
    }

    return result;
  }
}
