/**
 * Reference-claim import mapping (TPI-V2-WEB-C6D).
 *
 * Source statements are copied verbatim into `sourceText`. The source identity
 * is the stable reference-location id plus the zero-based activity position;
 * statement text is never used as an identifier. No witness, occurrence date,
 * destination room or classification evidence is inferred from the source.
 */
import type { ClaimImportItem, ClaimImportRequest } from "./claimImportService";
import type { ReferenceLocationRecord } from "../reference/referenceLocationCatalog";

export const REFERENCE_IMPORT_SOURCE_TYPE = "referenceLocation" as const;

export interface ReferenceDestinationReview {
  /** Zero-based position in `location.claims`. */
  activityIndex: number;
  /** Explicit case room choice, or null for explicit unassigned. */
  roomId: string | null;
  roomName: string;
}

/**
 * Stable source id for one activity. The original directory has no per-claim
 * ids, so position is the only stable source-local identity available. It is
 * deterministic across reloads, independent of statement text and never
 * derived from mutable statement content.
 */
export function referenceActivitySourceId(
  locationId: string,
  activityIndex: number,
): string {
  if (!Number.isInteger(activityIndex) || activityIndex < 0) {
    throw new Error("Activity index must be a non-negative integer");
  }
  return `${locationId}:activity-${String(activityIndex + 1).padStart(3, "0")}`;
}

export function referenceActivityText(
  location: ReferenceLocationRecord,
  activityIndex: number,
): string {
  const text = location.claims[activityIndex];
  if (text === undefined) {
    throw new Error(
      `Reference location ${location.id} has no activity at index ${activityIndex}`,
    );
  }
  return text;
}

/**
 * Build one import item. A destination room is copied only from the explicit
 * review supplied by the caller. With no room, the item remains unassigned and
 * no source room label is mapped by name.
 */
export function buildReferenceClaimImportItem(
  location: ReferenceLocationRecord,
  activityIndex: number,
  destination: ReferenceDestinationReview | null = null,
): ClaimImportItem {
  const sourceText = referenceActivityText(location, activityIndex);
  const roomId = destination?.roomId ?? null;
  const roomName = roomId === null ? "" : destination?.roomName ?? "";
  return {
    sourceClaimId: referenceActivitySourceId(location.id, activityIndex),
    title: sourceText.trim(),
    sourceText,
    classification: "Client Reported",
    classificationResolved: false,
    claimType: "Other",
    occurrenceLevel: "",
    roomID: roomId,
    roomTBD: false,
    roomName,
    linkedRoomIds: roomId === null ? [] : [roomId],
    witnessCount: 0,
    witnessCountResolved: false,
    witnessesText: "",
    emotionalImpact: 0,
    emotionalImpactResolved: false,
    feelingText: "",
    feelingNotes: "",
    notes: "",
    walkthroughStatus: "Not Located",
    mostRecentOccurrenceKnown: null,
    isGuidedDraft: false,
    sourceOccurrenceText: null,
    sourceOccurrenceAt: null,
  };
}

/**
 * Build the C6A import request from explicit per-activity destination reviews.
 * SourceReference is the stable resource location id, not a case location id.
 */
export function buildReferenceClaimImportRequest(
  caseId: string,
  location: ReferenceLocationRecord,
  reviews: readonly ReferenceDestinationReview[],
): ClaimImportRequest {
  if (reviews.length === 0) {
    throw new Error("Select at least one reference activity to import");
  }
  const seen = new Set<number>();
  const items = reviews.map((review) => {
    if (seen.has(review.activityIndex)) {
      throw new Error("A reference activity was selected more than once");
    }
    seen.add(review.activityIndex);
    return buildReferenceClaimImportItem(location, review.activityIndex, review);
  });
  return {
    caseId,
    sourceType: REFERENCE_IMPORT_SOURCE_TYPE,
    sourceReference: location.id,
    items,
  };
}
