/**
 * Client + Location + Session + Observation + Environmental reading
 * repositories. All writes are validated, referenced-checked, and audited.
 */
import type { TPIDatabase } from "../db";
import { now, uuidv4, SCHEMA_VERSION } from "../db";
import type {
  CaseRecord,
  ClientRecord,
  EnvironmentalReadingRecord,
  LocationRecord,
  ObservationRecord,
  SessionStatus,
  InvestigationSessionRecord,
} from "../types";
import {
  ValidationError,
  assertNonEmpty,
  assertReferenceExists,
  assertTimestampsMonotonic,
} from "../validation";
import { AuditService } from "../audit";

export class ClientRepository {
  private readonly audit: AuditService;
  constructor(private readonly db: TPIDatabase) {
    this.audit = new AuditService(db);
  }

  async create(input: {
    caseId: string;
    fullName: string;
    phone?: string;
    email?: string;
    notes?: string;
    consentRecordIds?: string[];
  }): Promise<ClientRecord> {
    assertNonEmpty(input.fullName, "fullName");
    const exists = (await this.db.cases.get(input.caseId)) !== undefined;
    assertReferenceExists(input.caseId, exists, "caseId");
    // Prevent accidental duplicate associations: one client record per
    // case per identical full name.
    const duplicates = await this.db.clients
      .where("caseId")
      .equals(input.caseId)
      .filter((c) => c.fullName.trim().toLowerCase() === input.fullName.trim().toLowerCase())
      .count();
    if (duplicates > 0) {
      throw new ValidationError(
        "A client with this name is already associated with the case",
        "fullName",
      );
    }
    const record: ClientRecord = {
      id: uuidv4(),
      schemaVersion: SCHEMA_VERSION as ClientRecord["schemaVersion"],
      createdAt: now(),
      updatedAt: now(),
      caseId: input.caseId,
      fullName: input.fullName.trim(),
      phone: input.phone,
      email: input.email,
      consentRecordIds: input.consentRecordIds ?? [],
      notes: input.notes,
    };
    await this.db.transaction("rw", this.db.clients, this.db.cases, this.db.auditEvents, async () => {
      await this.db.clients.add(record);
      await this.db.cases.update(input.caseId, { clientId: record.id, updatedAt: now() });
      await this.audit.record("clientAssociated", "Client associated with case", {
        caseId: input.caseId,
        affectedRecordId: record.id,
      });
    });
    return record;
  }

  async update(id: string, patch: Partial<Pick<ClientRecord, "fullName" | "phone" | "email" | "notes" | "consentRecordIds">>): Promise<ClientRecord | undefined> {
    return this.db.transaction("rw", this.db.clients, this.db.auditEvents, async () => {
      const existing = await this.db.clients.get(id);
      if (!existing) return undefined;
      const next: ClientRecord = { ...existing, ...patch, updatedAt: now() };
      assertTimestampsMonotonic(next.createdAt, next.updatedAt);
      await this.db.clients.put(next);
      await this.audit.record("clientAssociated", "Client record updated", {
        caseId: next.caseId,
        affectedRecordId: id,
      });
      return next;
    });
  }

  /**
   * Link an EXISTING client record to its case (C5A).
   *
   * Client records are case-scoped in the browser model, matching the original
   * CaseFile's embedded client fields. Associating a client owned by another
   * case is rejected rather than silently leaking one case's client data into
   * another. The client id is preserved; no second record is created.
   */
  async associateWithCase(clientId: string, caseId: string): Promise<CaseRecord> {
    const client = await this.db.clients.get(clientId);
    assertReferenceExists(clientId, client !== undefined, "clientId");
    const caseRecord = await this.db.cases.get(caseId);
    assertReferenceExists(caseId, caseRecord !== undefined, "caseId");
    if (!client || !caseRecord) throw new ValidationError("Referenced record not found", "clientId");
    if (client.caseId !== caseId) {
      throw new ValidationError(
        "This client record belongs to a different case and cannot be associated here",
        "clientId",
      );
    }
    if (caseRecord.clientId === clientId) return caseRecord;
    return this.db.transaction("rw", this.db.cases, this.db.auditEvents, async () => {
      const next: CaseRecord = { ...caseRecord, clientId, updatedAt: now() };
      await this.db.cases.put(next);
      await this.audit.record("clientAssociated", "Existing client record associated with case", {
        caseId,
        affectedRecordId: clientId,
        metadata: { reused: true },
      });
      return next;
    });
  }

  /** Remove the case's client link. The client record itself is preserved. */
  async clearCaseAssociation(caseId: string): Promise<CaseRecord | undefined> {
    return this.db.transaction("rw", this.db.cases, this.db.auditEvents, async () => {
      const existing = await this.db.cases.get(caseId);
      if (!existing) return undefined;
      if (!existing.clientId) return existing;
      const previous = existing.clientId;
      const next: CaseRecord = { ...existing, clientId: null, updatedAt: now() };
      await this.db.cases.put(next);
      await this.audit.record("clientAssociated", "Client association removed from case", {
        caseId,
        affectedRecordId: previous,
        metadata: { removed: true },
      });
      return next;
    });
  }

  async get(id: string): Promise<ClientRecord | undefined> {
    return this.db.clients.get(id);
  }

  async listForCase(caseId: string): Promise<ClientRecord[]> {
    return this.db.clients.where("caseId").equals(caseId).toArray();
  }

  /** Case-insensitive contains search over names (indexed on caseId, filtered in query). */
  async search(query: string, limit = 50): Promise<ClientRecord[]> {
    const q = query.trim().toLowerCase();
    return this.db.clients
      .orderBy("fullName")
      .filter((c) => q.length === 0 || c.fullName.toLowerCase().includes(q))
      .limit(limit)
      .toArray();
  }
}

export class LocationRepository {
  private readonly audit: AuditService;
  constructor(private readonly db: TPIDatabase) {
    this.audit = new AuditService(db);
  }

  async create(
    input: Omit<LocationRecord, "id" | "schemaVersion" | "createdAt" | "updatedAt"> & { caseId?: string },
  ): Promise<LocationRecord> {
    assertNonEmpty(input.name, "name");
    if (input.caseId !== undefined) {
      const exists = (await this.db.cases.get(input.caseId)) !== undefined;
      assertReferenceExists(input.caseId, exists, "caseId");
    }
    // Avoid accidental duplicate locations (C5B). Identity is the same
    // normalized name plus address fields — the original reference directory
    // deduplicates on the equivalent state/city/name key. A same-named
    // location at a genuinely different address remains allowed.
    const key = locationIdentityKey(input);
    const duplicate = (await this.db.locations.toArray()).find(
      (candidate) => locationIdentityKey(candidate) === key,
    );
    if (duplicate) {
      throw new ValidationError(
        `An identical location already exists (${duplicate.name}); reuse the existing record instead`,
        "name",
      );
    }
    const record: LocationRecord = {
      id: uuidv4(),
      schemaVersion: SCHEMA_VERSION as LocationRecord["schemaVersion"],
      createdAt: now(),
      updatedAt: now(),
      ...input,
    };
    await this.db.transaction("rw", this.db.locations, this.db.auditEvents, async () => {
      await this.db.locations.add(record);
      await this.audit.record("locationChanged", "Investigation location recorded", {
        caseId: input.caseId,
        affectedRecordId: record.id,
      });
    });
    return record;
  }

  async get(id: string): Promise<LocationRecord | undefined> {
    return this.db.locations.get(id);
  }

  /** Case-insensitive contains search over location names (reusable records). */
  async search(query: string, limit = 50): Promise<LocationRecord[]> {
    const q = query.trim().toLowerCase();
    return this.db.locations
      .orderBy("name")
      .filter((l) => q.length === 0 || l.name.toLowerCase().includes(q))
      .limit(limit)
      .toArray();
  }

  async update(id: string, patch: Partial<LocationRecord>): Promise<LocationRecord | undefined> {
    return this.db.transaction("rw", this.db.locations, this.db.auditEvents, async () => {
      const existing = await this.db.locations.get(id);
      if (!existing) return undefined;
      const next: LocationRecord = { ...existing, ...patch, updatedAt: now() };
      assertTimestampsMonotonic(next.createdAt, next.updatedAt);
      await this.db.locations.put(next);
      await this.audit.record("locationChanged", "Investigation location updated", {
        caseId: next.caseId,
        affectedRecordId: id,
      });
      return next;
    });
  }
}

/** Normalized identity used to prevent accidental duplicate location records. */
export function locationIdentityKey(location: {
  name: string;
  street?: string;
  city?: string;
  state?: string;
  zip?: string;
}): string {
  const part = (value: string | undefined): string =>
    (value ?? "")
      .trim()
      .replace(/\s+/g, " ")
      .toLowerCase();
  return [part(location.name), part(location.street), part(location.city), part(location.state), part(location.zip)].join("|");
}

export class SessionRepository {
  private readonly audit: AuditService;
  constructor(private readonly db: TPIDatabase) {
    this.audit = new AuditService(db);
  }

  async start(caseId: string, investigators: string[] = []): Promise<InvestigationSessionRecord> {
    const exists = (await this.db.cases.get(caseId)) !== undefined;
    assertReferenceExists(caseId, exists, "caseId");
    const ts = now();
    const record: InvestigationSessionRecord = {
      id: uuidv4(),
      schemaVersion: SCHEMA_VERSION as InvestigationSessionRecord["schemaVersion"],
      createdAt: ts,
      updatedAt: ts,
      caseId,
      startedAt: ts,
      status: "active",
      investigators,
    };
    await this.db.sessions.add(record);
    await this.audit.record("statusChanged", "Investigation session started", {
      caseId,
      affectedRecordId: record.id,
      metadata: { sessionStatus: "active" },
    });
    return record;
  }

  async end(id: string, status: SessionStatus = "completed"): Promise<InvestigationSessionRecord | undefined> {
    return this.db.transaction("rw", this.db.sessions, this.db.auditEvents, async () => {
      const existing = await this.db.sessions.get(id);
      if (!existing) return undefined;
      const next: InvestigationSessionRecord = {
        ...existing,
        status,
        endedAt: status === "active" ? existing.endedAt : now(),
        updatedAt: now(),
      };
      await this.db.sessions.put(next);
      await this.audit.record("statusChanged", `Investigation session ${status}`, {
        caseId: existing.caseId,
        affectedRecordId: id,
        metadata: { sessionStatus: status },
      });
      return next;
    });
  }

  async get(id: string): Promise<InvestigationSessionRecord | undefined> {
    return this.db.sessions.get(id);
  }

  async listForCase(caseId: string): Promise<InvestigationSessionRecord[]> {
    return this.db.sessions.where("caseId").equals(caseId).toArray();
  }
}

export class ObservationRepository {
  private readonly audit: AuditService;
  constructor(private readonly db: TPIDatabase) {
    this.audit = new AuditService(db);
  }

  async create(input: {
    caseId: string;
    sessionId?: string;
    roomName?: string;
    title?: string;
    body: string;
    entryType?: "observation" | "interpretation";
  }): Promise<ObservationRecord> {
    assertNonEmpty(input.body, "body");
    const exists = (await this.db.cases.get(input.caseId)) !== undefined;
    assertReferenceExists(input.caseId, exists, "caseId");
    if (input.sessionId !== undefined) {
      const session = await this.db.sessions.get(input.sessionId);
      assertReferenceExists(input.sessionId, session !== undefined, "sessionId");
      if (session && session.caseId !== input.caseId) {
        throw new ValidationError("Session does not belong to the given case", "sessionId");
      }
    }
    const record: ObservationRecord = {
      id: uuidv4(),
      schemaVersion: SCHEMA_VERSION as ObservationRecord["schemaVersion"],
      createdAt: now(),
      caseId: input.caseId,
      sessionId: input.sessionId,
      roomName: input.roomName ?? "General",
      title: input.title,
      body: input.body.trim(),
      entryType: input.entryType ?? "observation",
    };
    await this.db.observations.add(record);
    await this.audit.record("caseUpdated", "Observation recorded", {
      caseId: input.caseId,
      affectedRecordId: record.id,
      metadata: { entryType: record.entryType },
    });
    return record;
  }

  async listForCase(caseId: string, limit = 100, offset = 0): Promise<ObservationRecord[]> {
    return this.db.observations
      .where("caseId")
      .equals(caseId)
      .reverse()
      .sortBy("createdAt")
      .then((all) => all.slice(offset, offset + limit));
  }
}

export class EnvironmentalReadingRepository {
  private readonly audit: AuditService;
  constructor(private readonly db: TPIDatabase) {
    this.audit = new AuditService(db);
  }

  async create(input: Omit<EnvironmentalReadingRecord, "id" | "schemaVersion" | "createdAt"> & { createdAt?: number }): Promise<EnvironmentalReadingRecord> {
    const exists = (await this.db.cases.get(input.caseId)) !== undefined;
    assertReferenceExists(input.caseId, exists, "caseId");
    const record: EnvironmentalReadingRecord = {
      id: uuidv4(),
      schemaVersion: SCHEMA_VERSION as EnvironmentalReadingRecord["schemaVersion"],
      createdAt: input.createdAt ?? now(),
      ...input,
    };
    await this.db.environmentReadings.add(record);
    await this.audit.record("caseUpdated", "Environmental reading recorded", {
      caseId: input.caseId,
      affectedRecordId: record.id,
      metadata: { source: record.source },
    });
    return record;
  }

  async listForCase(caseId: string, limit = 200, offset = 0): Promise<EnvironmentalReadingRecord[]> {
    return this.db.environmentReadings
      .where("caseId")
      .equals(caseId)
      .reverse()
      .sortBy("createdAt")
      .then((all) => all.slice(offset, offset + limit));
  }
}
