/**
 * Investigation Inbox — TPI-V2-WEB-015.
 *
 * ORIGINAL SOURCE
 *   `Cases/CaseDetailView.swift` → `CaseInvestigationInboxView` (lines 3180–3728)
 *
 * The original is a case-scoped staging view for investigation-phase field
 * media, with Global Feed / By Room modes, a room filter and a review-state
 * filter, newest first.
 *
 * PRESENTATION FIDELITY
 *   Both original view modes, the room filter, the review-state summary and the
 *   per-item Room / Type / State facts are reproduced. Original actions that
 *   MUTATE media (review-state buttons, reassign room, bulk Basecamp import,
 *   room/case export) are not reproduced: WEB-015 is read-only by directive, so
 *   those actions remain on the screens that already own them.
 *
 * INTEGRITY
 *   Every row keeps its source identity; timestamps are shown with provenance;
 *   missing references are labelled, never invented; no conclusion is drawn and
 *   nothing is classified as paranormal. This view never writes.
 */
import "./casehub.css";
import { getDb } from "../../core/db";
import {
  MEDIA_LABELS,
  REVIEW_LABELS,
  UNASSIGNED,
  filterInboxRows,
  groupInboxRowsByRoom,
  loadInboxData,
  type InboxRow,
} from "../../core/evidence/inboxService";
import { esc, viewShell, wireBackButton } from "../dashboard/shell";
import { mountView, onDelegate, invalidateView } from "../../shared/uidom";
import { renderCaseHub } from "./CaseHub";
import { renderEvidenceLibrary } from "./EvidenceLibrary";
import { renderEvidenceReview } from "./EvidenceViews";

const db = () => getDb();

type InboxMode = "global" | "byRoom";

interface InboxUiState {
  mode: InboxMode;
  room: string;
  review: string;
}

const ui = new WeakMap<HTMLElement, InboxUiState>();

function st(container: HTMLElement): InboxUiState {
  let s = ui.get(container);
  if (!s) {
    s = { mode: "global", room: "", review: "" };
    ui.set(container, s);
  }
  return s;
}

function fmtTime(ms: number | null | undefined): string {
  return ms ? new Date(ms).toLocaleString() : "—";
}

function fmtBytes(n: number): string {
  if (n < 1024) return `${n} B`;
  if (n < 1024 * 1024) return `${(n / 1024).toFixed(1)} KB`;
  return `${(n / (1024 * 1024)).toFixed(1)} MB`;
}

function fact(label: string, value: string): string {
  return `<div class="cc-native-fact"><strong>${esc(label)}</strong>${esc(value)}</div>`;
}

function rowHtml(row: InboxRow): string {
  const reviewLabel = REVIEW_LABELS[row.reviewStatus] ?? row.reviewStatus;
  return `
    <section class="cc-native-card" data-inbox-record="${esc(row.evidenceId)}"
      data-inbox-review="${esc(row.reviewStatus)}" data-inbox-room="${esc(row.roomId ?? "")}"
      data-inbox-kind="${esc(row.kind)}">
      <h3>${esc(row.title)} <span class="status-badge">${esc(reviewLabel)}</span></h3>
      <p class="cc-meta">${esc(MEDIA_LABELS[row.mediaType] ?? row.mediaType)} • ${esc(fmtTime(row.at))} (${esc(row.atSource)})</p>
      <div class="cc-native-facts">
        ${fact("Room", row.roomLabel)}
        ${fact("Session", row.sessionLabel)}
        ${fact("Type", `${row.kind === "derived" ? "Derived record" : "Original record"} — ${MEDIA_LABELS[row.mediaType] ?? row.mediaType}`)}
        ${fact("Source", `${row.origin} — recorded by ${row.recordedBy}`)}
        ${fact("Review state", reviewLabel)}
        ${fact("Integrity", row.verificationStatus)}
      </div>
      ${row.roomMissing ? `<p><span class="status-badge error" data-inbox-missing="room">reference missing</span> <span class="cc-meta">This record points at a room that is not in the case structure. The stored association is shown unchanged.</span></p>` : ""}
      ${row.sessionMissing ? `<p><span class="status-badge error" data-inbox-missing="session">reference missing</span> <span class="cc-meta">This record points at a session that is not in the case. The stored association is shown unchanged.</span></p>` : ""}
      ${row.notes ? `<p class="cc-meta">${esc(row.notes)}</p>` : ""}
      <details class="inbox-record-details">
        <summary>Record details</summary>
        <div class="cc-native-facts">
          ${fact("Evidence id", row.evidenceId)}
          ${fact("Captured / acquired", `${fmtTime(row.at)} — ${row.atSource}`)}
          ${fact("Imported", row.importedAt ? fmtTime(row.importedAt) : "not recorded")}
          ${fact("File size", fmtBytes(row.fileSizeBytes))}
          ${fact("SHA-256", row.contentHash || "not recorded")}
          ${fact("Room id", row.roomId ?? "none")}
          ${fact("Session id", row.sessionId ?? "none")}
          ${fact(
            "Latest structured review",
            row.latestReview
              ? `${row.latestReview.status} — ${row.latestReview.reviewer || "reviewer not recorded"}, ${fmtTime(row.latestReview.at)}`
              : "no structured review recorded",
          )}
        </div>
      </details>
      <div class="form-actions">
        <button class="button-secondary" type="button" data-inbox-nav="library">Open Evidence Library</button>
        <button class="button-secondary" type="button" data-inbox-nav="review">Open Evidence Review</button>
      </div>
    </section>`;
}

export async function renderInvestigationInbox(container: HTMLElement, caseId: string): Promise<void> {
  const data = await loadInboxData(db(), caseId);
  if (!data) {
    invalidateView(container);
    mountView(container, viewShell("Investigation Inbox", `<div class="cc-empty">Case not found.</div>`));
    wireBackButton(container);
    return;
  }

  const s = st(container);
  const filtered = filterInboxRows(data.rows, { room: s.room, review: s.review });
  const hasFilters = Boolean(s.room || s.review);
  const filteredOut = data.rows.length > 0 && filtered.length === 0;

  const reviewOptions = (Object.keys(REVIEW_LABELS) as Array<keyof typeof REVIEW_LABELS>)
    .map((key) => `<option value="${esc(key)}"${s.review === key ? " selected" : ""}>${esc(REVIEW_LABELS[key])}</option>`)
    .join("");
  const roomOptions = data.filterRooms
    .map((room) => `<option value="${esc(room.id)}"${s.room === room.id ? " selected" : ""}>${esc(room.name)}</option>`)
    .join("");

  const listHtml = filteredOut
    ? `<div class="cc-empty" data-inbox-empty="filtered">No investigation records match these filters. Nothing has been hidden or removed.</div>`
    : data.rows.length === 0
      ? `<div class="cc-empty" data-inbox-empty="none">
           <strong>No investigation records found</strong>
           <p class="cc-meta">Capture evidence during an investigation, or import field files in the Evidence Library. Records appear here with their source, room and session context, and review state exactly as stored.</p>
         </div>`
      : s.mode === "byRoom"
        ? groupInboxRowsByRoom(filtered)
            .map(
              (group) => `
            <section class="inbox-room-group" data-inbox-room-group="${esc(group.roomLabel)}">
              <h3 class="cc-section-title">${esc(group.roomLabel)}</h3>
              ${group.rows.map(rowHtml).join("")}
            </section>`,
            )
            .join("")
        : filtered.map(rowHtml).join("");

  invalidateView(container);
  mountView(
    container,
    viewShell(
      `Investigation Inbox — ${data.caseNumber}`,
      `
      <div class="case-form" data-root="investigation-inbox" data-case-id="${esc(caseId)}" data-epoch="${Date.now()}-${Math.random()}">
        <p class="cc-count">Records: <strong>${data.counts.total}</strong> • awaiting review ${data.counts.awaitingReview} • flagged ${data.counts.flagged} • excluded ${data.counts.excluded} • derived ${data.counts.derived}${data.counts.integrityProblems ? ` • <strong>integrity problems ${data.counts.integrityProblems}</strong>` : ""}</p>
        <p class="cc-meta">This inbox is read-only. It lists records that already exist and never changes evidence, review state, or timestamps. Classification and review actions stay in Evidence Library and Evidence Review.</p>
        ${data.unresolved.rooms || data.unresolved.sessions
          ? `<p class="cc-meta" data-inbox-unresolved>Unresolved references: ${data.unresolved.rooms} room, ${data.unresolved.sessions} session. Missing references are labelled below; stored associations are not rewritten.</p>`
          : ""}

        <div class="case-form" id="inbox-controls">
          <div class="form-actions">
            <button class="${s.mode === "global" ? "button-primary" : "button-secondary"}" type="button"
              data-inbox-mode="global" aria-pressed="${s.mode === "global"}">Global Feed</button>
            <button class="${s.mode === "byRoom" ? "button-primary" : "button-secondary"}" type="button"
              data-inbox-mode="byRoom" aria-pressed="${s.mode === "byRoom"}">By Room</button>
          </div>
          <div class="detail-grid">
            <div class="detail-field"><label for="inbox-room">Room</label>
              <select id="inbox-room"><option value="">All rooms</option>${roomOptions}<option value="${UNASSIGNED}"${s.room === UNASSIGNED ? " selected" : ""}>Unassigned</option></select></div>
            <div class="detail-field"><label for="inbox-review">Review state</label>
              <select id="inbox-review"><option value="">All review states</option>${reviewOptions}</select></div>
          </div>
          ${hasFilters ? `<div class="form-actions"><button class="button-secondary" type="button" id="inbox-clear">Clear filters</button></div>` : ""}
        </div>

        <div id="inbox-list">${listHtml}</div>

        <div class="form-actions"><button class="back-button" id="inbox-back" type="button">← Back to Case Hub</button></div>
      </div>
    `,
    ),
  );

  const root = container.closest<HTMLElement>(".cc-view")?.parentElement ?? container;

  onDelegate(container, "click", "[data-inbox-mode]", async (el) => {
    const mode = el.dataset.inboxMode;
    if (mode !== "global" && mode !== "byRoom") return;
    st(container).mode = mode;
    await renderInvestigationInbox(container, caseId);
  });
  onDelegate(container, "change", "#inbox-room", async () => {
    st(container).room = container.querySelector<HTMLSelectElement>("#inbox-room")?.value ?? "";
    await renderInvestigationInbox(container, caseId);
  });
  onDelegate(container, "change", "#inbox-review", async () => {
    st(container).review = container.querySelector<HTMLSelectElement>("#inbox-review")?.value ?? "";
    await renderInvestigationInbox(container, caseId);
  });
  onDelegate(container, "click", "#inbox-clear", async () => {
    const state = st(container);
    state.room = "";
    state.review = "";
    await renderInvestigationInbox(container, caseId);
  });
  onDelegate(container, "click", "[data-inbox-nav]", (el) => {
    if (el.dataset.inboxNav === "library") void renderEvidenceLibrary(root, caseId);
    else if (el.dataset.inboxNav === "review") void renderEvidenceReview(root, caseId);
  });
  onDelegate(container, "click", "#inbox-back", () => void renderCaseHub(root, caseId));
  wireBackButton(container);
}
