/**
 * Property structure service (TPI-V2-WEB-007).
 *
 * iOS origins: InvestigationFloor, InvestigationRoom, InvestigationZone,
 * PPRoom (room-context questions + walkthrough status), PPRoomPin,
 * PPRoomLayoutElement (categories/kinds), RoomBuilderShape.
 *
 * Integrity rules (directive §6):
 * - structures belong to a case and may reference a reusable location;
 * - rooms are never destructively deleted — they are archived (soft);
 * - geometry is structured data (normalized 0–1), never a flattened image;
 * - room ids are stable, so observations/markers survive layout changes;
 * - structural changes bump the structure revision (sessions record the
 *   revision they were performed against).
 */
import type { TPIDatabase } from "../db";
import { SCHEMA_VERSION } from "../db";
import { v4 as uuidv4 } from "../../shared/uuid";
import type {
  FloorRecord,
  MarkerSource,
  PropertyKind,
  PropertyStructureRecord,
  RoomRecord,
  RoomShape,
  StructureMarkerRecord,
  ZoneRecord,
} from "../types";
import { ValidationError } from "../validation";
import { AuditService } from "../audit";

export const ROOM_SHAPES: ReadonlyArray<{ id: RoomShape; label: string; aspect: number }> = [
  { id: "rectangle", label: "Rectangle", aspect: 1.55 },
  { id: "square", label: "Square", aspect: 1.0 },
  { id: "narrowRectangle", label: "Narrow Rectangle", aspect: 0.65 },
  { id: "hallway", label: "Hallway", aspect: 3.2 },
  { id: "stairwell", label: "Stairwell", aspect: 0.55 },
  { id: "closet", label: "Closet / Utility", aspect: 0.75 },
  { id: "openArea", label: "Open Area", aspect: 1.4 },
];

/** iOS room-context option sets (CaseWalkthroughRoomWorkspaceView). */
export const LIGHTING_OPTIONS = [
  "Lights Off",
  "Natural Light Only",
  "Dim Lighting",
  "Overhead Lights On",
  "Lamp Lighting",
  "Mixed Lighting",
  "Flickering / Unstable Lighting",
];
export const WINDOW_OPTIONS = [
  "Windows Closed - No Air Movement",
  "Windows Closed - Slight Air Movement",
  "Windows Closed - Noticeable Draft",
  "One Window Cracked",
  "Windows Partially Open",
  "Windows Open",
  "Windows Sealed / Covered",
];
export const HVAC_OPTIONS = [
  "HVAC Off",
  "HVAC On - Heat",
  "HVAC On - AC",
  "HVAC On - Fan / Air Circulation",
  "Vent Active - Light Airflow",
  "Vent Active - Strong Airflow",
  "Unknown",
];
export const ELECTRONICS_OPTIONS = [
  "No Electronics Operating Nearby",
  "Minimal Electronics Active",
  "Television / Monitor Active",
  "Appliances Running Nearby",
  "Multiple Devices Powered On",
  "Breaker / Electrical Equipment Nearby",
  "Unknown",
];

export const MARKER_TYPES = [
  "reportedActivity",
  "investigatorObservation",
  "environmentalPoint",
  "equipmentPosition",
  "evidenceLocation",
  "followUp",
] as const;

export const MARKER_SOURCES = [
  "clientReported",
  "investigatorObservation",
  "instrumentMeasurement",
  "interpretation",
] as const;

export interface PropertyHierarchy {
  structure: PropertyStructureRecord;
  floors: Array<FloorRecord & { rooms: RoomRecord[] }>;
  zones: Array<ZoneRecord & { rooms: RoomRecord[] }>;
  unassignedRooms: RoomRecord[];
}

export class PropertyService {
  private readonly audit: AuditService;

  constructor(private readonly db: TPIDatabase) {
    this.audit = new AuditService(db);
  }

  /** Idempotently ensure a structure exists for the case. */
  async ensureStructureForCase(caseId: string): Promise<PropertyStructureRecord> {
    const existing = await this.db.propertyStructures.where("caseId").equals(caseId).first();
    if (existing) return existing as PropertyStructureRecord;
    const caseRecord = await this.db.cases.get(caseId);
    if (!caseRecord) throw new ValidationError(`Case not found: ${caseId}`, "caseId");
    const kind: PropertyKind =
      caseRecord.investigationType === "residential" ? "residential"
      : caseRecord.investigationType === "historical" ? "historical"
      : caseRecord.investigationType === "business" ? "commercial"
      : "mixed";
    const ts = Date.now();
    const structure: PropertyStructureRecord = {
      id: uuidv4(),
      schemaVersion: SCHEMA_VERSION,
      createdAt: ts,
      updatedAt: ts,
      caseId,
      locationId: caseRecord.locationId,
      name: caseRecord.title,
      kind,
      notes: "",
      revision: 1,
      archived: false,
    };
    await this.db.propertyStructures.put(structure);
    await this.audit.record("structureCreated", `Property structure created (${kind}).`, {
      caseId,
      affectedRecordId: structure.id,
    });
    return structure;
  }

  async getStructureForCase(caseId: string): Promise<PropertyStructureRecord | undefined> {
    return this.db.propertyStructures.where("caseId").equals(caseId).first();
  }

  async loadHierarchy(structureId: string): Promise<PropertyHierarchy> {
    const structure = await this.db.propertyStructures.get(structureId);
    if (!structure) throw new ValidationError(`Structure not found: ${structureId}`, "structureId");
    const [floors, zones, rooms] = await Promise.all([
      this.db.structureFloors.where("structureId").equals(structureId).sortBy("orderIndex"),
      this.db.structureZones.where("structureId").equals(structureId).sortBy("orderIndex"),
      this.db.structureRooms.where("structureId").equals(structureId).sortBy("orderIndex"),
    ]);
    const live = rooms.filter((r) => !r.archived) as RoomRecord[];
    return {
      structure,
      floors: (floors as FloorRecord[]).map((f) => ({ ...f, rooms: live.filter((r) => r.floorId === f.id) })),
      zones: (zones as ZoneRecord[]).map((z) => ({ ...z, rooms: live.filter((r) => r.zoneId === z.id) })),
      unassignedRooms: live.filter((r) => !r.floorId && !r.zoneId),
    };
  }

  async createFloor(structureId: string, displayName: string): Promise<FloorRecord> {
    if (!displayName.trim()) throw new ValidationError("Floor name is required.", "displayName");
    const structure = await this.db.propertyStructures.get(structureId);
    if (!structure) throw new ValidationError(`Structure not found: ${structureId}`, "structureId");
    const count = await this.db.structureFloors.where("structureId").equals(structureId).count();
    const ts = Date.now();
    const floor: FloorRecord = {
      id: uuidv4(),
      schemaVersion: SCHEMA_VERSION,
      createdAt: ts,
      updatedAt: ts,
      structureId,
      caseId: structure.caseId,
      displayName: displayName.trim(),
      orderIndex: count,
      notes: "",
    };
    await this.db.structureFloors.put(floor);
    await this.bumpRevision(structure, "Floor added");
    return floor;
  }

  async renameFloor(floorId: string, displayName: string): Promise<FloorRecord> {
    if (!displayName.trim()) throw new ValidationError("Floor name is required.", "displayName");
    const floor = await this.db.structureFloors.get(floorId);
    if (!floor) throw new ValidationError(`Floor not found: ${floorId}`, "floorId");
    const next = { ...floor, displayName: displayName.trim(), updatedAt: Date.now() };
    await this.db.structureFloors.put(next);
    await this.audit.record("floorUpdated", `Floor renamed.`, {
      caseId: floor.caseId,
      affectedRecordId: floorId,
    });
    return next;
  }

  async createZone(structureId: string, displayName: string, notes = ""): Promise<ZoneRecord> {
    if (!displayName.trim()) throw new ValidationError("Zone name is required.", "displayName");
    const structure = await this.db.propertyStructures.get(structureId);
    if (!structure) throw new ValidationError(`Structure not found: ${structureId}`, "structureId");
    const count = await this.db.structureZones.where("structureId").equals(structureId).count();
    const ts = Date.now();
    const zone: ZoneRecord = {
      id: uuidv4(),
      schemaVersion: SCHEMA_VERSION,
      createdAt: ts,
      updatedAt: ts,
      structureId,
      caseId: structure.caseId,
      displayName: displayName.trim(),
      orderIndex: count,
      notes,
    };
    await this.db.structureZones.put(zone);
    await this.bumpRevision(structure, "Zone added");
    return zone;
  }

  /** Create a room with an initial shape-derived footprint. */
  async createRoom(
    structureId: string,
    input: { name: string; floorId?: string | null; zoneId?: string | null; shape?: RoomShape; roomType?: string },
  ): Promise<RoomRecord> {
    if (!input.name.trim()) throw new ValidationError("Room name is required.", "name");
    // Normalize empty-string parent ids to "no parent" so a blank form value can
    // never create a room that belongs to no floor and no zone.
    const floorId = input.floorId ? input.floorId : null;
    const zoneId = input.zoneId ? input.zoneId : null;
    const structure = await this.db.propertyStructures.get(structureId);
    if (!structure) throw new ValidationError(`Structure not found: ${structureId}`, "structureId");
    if (floorId && !(await this.db.structureFloors.get(floorId))) {
      throw new ValidationError("Floor does not exist.", "floorId");
    }
    if (floorId && zoneId) {
      throw new ValidationError("A room belongs to either a floor or a zone, not both.", "floorId");
    }
    if (zoneId && !(await this.db.structureZones.get(zoneId))) {
      throw new ValidationError("Zone does not exist.", "zoneId");
    }
    const shape = input.shape ?? "rectangle";
    const preset = ROOM_SHAPES.find((s) => s.id === shape) ?? ROOM_SHAPES[0]!;
    const siblings = (await this.db.structureRooms.where("structureId").equals(structureId).toArray())
      .filter((r) => !r.archived && (floorId ? r.floorId === floorId : zoneId ? r.zoneId === zoneId : !r.floorId && !r.zoneId));
    const orderIndex = siblings.length;
    // Simple auto-placement: flow left-to-right, wrapping rows.
    const col = orderIndex % 3;
    const row = Math.floor(orderIndex / 3);
    const w = Math.min(0.3 * preset.aspect, 0.45);
    const h = Math.min(0.22 / (preset.aspect > 1 ? 1 : preset.aspect), 0.3);
    const ts = Date.now();
    const room: RoomRecord = {
      id: uuidv4(),
      schemaVersion: SCHEMA_VERSION,
      createdAt: ts,
      updatedAt: ts,
      structureId,
      caseId: structure.caseId,
      floorId,
      zoneId,
      name: input.name.trim(),
      roomType: input.roomType?.trim() || input.name.trim(),
      builderShape: shape,
      posX: Math.min(0.02 + col * 0.33, 0.98 - w),
      posY: Math.min(0.02 + row * 0.26, 0.98 - h),
      width: w,
      height: h,
      orderIndex,
      notes: "",
      lightingConditions: "",
      windowsState: "",
      hvacState: "",
      electronicsState: "",
      recentModifications: "",
      repairsNotes: "",
      environmentalObservations: "",
      assessmentStatus: "notStarted",
      notApplicableReason: "",
      archived: false,
    };
    await this.db.structureRooms.put(room);
    await this.bumpRevision(structure, "");
    await this.audit.record("roomUpdated", `Room "${room.name}" added to the property structure.`, {
      caseId: structure.caseId,
      affectedRecordId: room.id,
    });
    return room;
  }

  async updateRoomGeometry(roomId: string, geometry: { posX: number; posY: number; width: number; height: number }): Promise<RoomRecord> {
    const room = await this.db.structureRooms.get(roomId);
    if (!room) throw new ValidationError(`Room not found: ${roomId}`, "roomId");
    const clamp = (v: number) => Math.max(0, Math.min(1, v));
    const posX = clamp(geometry.posX);
    const posY = clamp(geometry.posY);
    const width = clamp(geometry.width);
    const height = clamp(geometry.height);
    if (posX + width > 1.001 || posY + height > 1.001) {
      throw new ValidationError("Room geometry must stay within the floor canvas.", "posX");
    }
    const next: RoomRecord = { ...room, posX, posY, width, height, updatedAt: Date.now() };
    await this.db.structureRooms.put(next);
    const structure = await this.db.propertyStructures.get(room.structureId);
    if (structure) await this.bumpRevision(structure, "");
    await this.audit.record("roomUpdated", `Room layout geometry updated.`, {
      caseId: room.caseId,
      affectedRecordId: roomId,
      metadata: { geometry: true },
    });
    return next;
  }

  async updateRoomDetails(
    roomId: string,
    patch: Partial<Pick<RoomRecord, "name" | "notes" | "builderShape" | "floorId" | "zoneId">> & { reason?: string },
  ): Promise<RoomRecord> {
    const room = await this.db.structureRooms.get(roomId);
    if (!room) throw new ValidationError(`Room not found: ${roomId}`, "roomId");
    if (patch.name !== undefined && !patch.name.trim()) throw new ValidationError("Room name is required.", "name");
    if (patch.floorId !== undefined && patch.floorId && !(await this.db.structureFloors.get(patch.floorId))) {
      throw new ValidationError("Floor does not exist.", "floorId");
    }
    if (patch.zoneId !== undefined && patch.zoneId && !(await this.db.structureZones.get(patch.zoneId))) {
      throw new ValidationError("Zone does not exist.", "zoneId");
    }
    const next: RoomRecord = { ...room, ...patch, name: patch.name?.trim() ?? room.name, updatedAt: Date.now() };
    await this.db.structureRooms.put(next);
    const structure = await this.db.propertyStructures.get(room.structureId);
    if (structure) await this.bumpRevision(structure, "");
    await this.audit.record("roomUpdated", `Room "${next.name}" details updated${patch.reason ? `: ${patch.reason.slice(0, 120)}` : ""}.`, {
      caseId: room.caseId,
      affectedRecordId: roomId,
    });
    return next;
  }

  /**
   * Room assessment (iOS PPRoom semantics): marking a room `reviewed` requires
   * the four context fields to be recorded (iOS `isWalkthroughMinimumComplete`).
   * A documented not-applicable determination is the justified exception.
   */
  async saveRoomAssessment(
    roomId: string,
    assessment: Partial<Pick<RoomRecord, "lightingConditions" | "windowsState" | "hvacState" | "electronicsState" | "recentModifications" | "repairsNotes" | "environmentalObservations" | "notes">>,
    options: { markReviewed?: boolean } = {},
  ): Promise<RoomRecord> {
    const room = await this.db.structureRooms.get(roomId);
    if (!room) throw new ValidationError(`Room not found: ${roomId}`, "roomId");
    const merged = { ...room, ...assessment, updatedAt: Date.now() };
    if (options.markReviewed) {
      const required = [merged.lightingConditions, merged.windowsState, merged.hvacState, merged.electronicsState]
        .map((v) => v.trim());
      if (required.some((v) => v.length === 0)) {
        throw new ValidationError(
          "Marking a room reviewed requires lighting, window, HVAC, and electronics conditions to be recorded first.",
          "assessmentStatus",
        );
      }
      merged.assessmentStatus = "reviewed";
    }
    await this.db.structureRooms.put(merged);
    await this.audit.record("roomUpdated", `Room assessment updated (${merged.assessmentStatus}).`, {
      caseId: room.caseId,
      affectedRecordId: roomId,
      // Assessment option selections are safe to summarize; free text is not logged.
      metadata: { status: merged.assessmentStatus },
    });
    return merged;
  }

  async markRoomNotApplicable(roomId: string, reason: string): Promise<RoomRecord> {
    if (!reason.trim()) throw new ValidationError("A documented reason is required to mark a room not applicable.", "reason");
    const room = await this.db.structureRooms.get(roomId);
    if (!room) throw new ValidationError(`Room not found: ${roomId}`, "roomId");
    const next: RoomRecord = { ...room, assessmentStatus: "notApplicable", notApplicableReason: reason, updatedAt: Date.now() };
    await this.db.structureRooms.put(next);
    await this.audit.record("roomUpdated", `Room determined not applicable: ${reason.slice(0, 160)}`, {
      caseId: room.caseId,
      affectedRecordId: roomId,
    });
    return next;
  }

  /** Soft-archival — rooms are never destructively deleted (directive §6). */
  async archiveRoom(roomId: string, reason: string): Promise<RoomRecord> {
    if (!reason.trim()) throw new ValidationError("Archiving a room requires a documented reason.", "reason");
    const room = await this.db.structureRooms.get(roomId);
    if (!room) throw new ValidationError(`Room not found: ${roomId}`, "roomId");
    const next: RoomRecord = { ...room, archived: true, updatedAt: Date.now() };
    await this.db.structureRooms.put(next);
    await this.bumpRevision(await this.getStructure(room.structureId), "");
    await this.audit.record("roomUpdated", `Room archived (removed from active layout): ${reason.slice(0, 160)}`, {
      caseId: room.caseId,
      affectedRecordId: roomId,
    });
    return next;
  }

  private async getStructure(structureId: string): Promise<PropertyStructureRecord> {
    const s = await this.db.propertyStructures.get(structureId);
    if (!s) throw new ValidationError(`Structure not found: ${structureId}`, "structureId");
    return s;
  }

  private async bumpRevision(structure: PropertyStructureRecord, _label: string): Promise<void> {
    await this.db.propertyStructures.put({ ...structure, revision: structure.revision + 1, updatedAt: Date.now() });
  }

  /* ------------------------------- markers -------------------------------- */

  async createMarker(
    caseId: string,
    input: {
      roomId?: string | null;
      floorId?: string | null;
      posX: number;
      posY: number;
      markerType: (typeof MARKER_TYPES)[number];
      label: string;
      details: string;
      source: MarkerSource;
      evidenceId?: string | null;
      createdBy?: string;
    },
  ): Promise<StructureMarkerRecord> {
    if (!input.label.trim()) throw new ValidationError("Marker label is required.", "label");
    if (input.roomId && !(await this.db.structureRooms.get(input.roomId))) {
      throw new ValidationError("Room does not exist.", "roomId");
    }
    const clamp = (v: number) => Math.max(0, Math.min(1, v));
    const ts = Date.now();
    const marker: StructureMarkerRecord = {
      id: uuidv4(),
      schemaVersion: SCHEMA_VERSION,
      createdAt: ts,
      updatedAt: ts,
      caseId,
      roomId: input.roomId ?? null,
      floorId: input.floorId ?? null,
      posX: clamp(input.posX),
      posY: clamp(input.posY),
      markerType: input.markerType,
      label: input.label.trim(),
      details: input.details,
      source: input.source,
      evidenceId: input.evidenceId ?? null,
      createdBy: input.createdBy ?? "local-user",
    };
    await this.db.structureMarkers.put(marker);
    await this.audit.record("markerCreated", `Marker added (${input.markerType}, source: ${input.source}).`, {
      caseId,
      affectedRecordId: marker.id,
      metadata: { markerType: input.markerType, source: input.source },
    });
    return marker;
  }

  async updateMarker(markerId: string, patch: Partial<Pick<StructureMarkerRecord, "label" | "details" | "source" | "markerType" | "posX" | "posY" | "evidenceId">>): Promise<StructureMarkerRecord> {
    const marker = await this.db.structureMarkers.get(markerId);
    if (!marker) throw new ValidationError(`Marker not found: ${markerId}`, "markerId");
    const next: StructureMarkerRecord = { ...marker, ...patch, updatedAt: Date.now() };
    await this.db.structureMarkers.put(next);
    await this.audit.record("markerUpdated", `Marker updated (${next.markerType}).`, {
      caseId: marker.caseId,
      affectedRecordId: markerId,
      metadata: { markerType: next.markerType },
    });
    return next;
  }

  async listMarkers(caseId: string): Promise<StructureMarkerRecord[]> {
    return this.db.structureMarkers.where("caseId").equals(caseId).toArray();
  }
}
