import type { DocumentFormType } from "../types";

export const TEMPLATE_VERSION = "ios-migrate-1";

export interface DocumentTemplate {
  id: DocumentFormType;
  title: string;
  fileNameStem: string;
  isRequired: boolean;
  /** iOS sort order for required documents (others sort last). */
  sortIndex: number;
  body: string;
  /** Fillable browser fields beyond the signature block (validated). */
  fields: DocumentField[];
}

export interface DocumentField {
  id: string;
  label: string;
  type: "text" | "textarea" | "select";
  required: boolean;
  options?: string[];
  /** Help text shown under the field. */
  help?: string;
}

/** iOS PPDocumentTemplateStore.requiredDocumentOrder — exact order preserved. */
