export function templateFor(id: DocumentFormType): DocumentTemplate {
  return (
    DOCUMENT_TEMPLATES.find((t) => t.id === id) ?? {
      id: "other",
      title: "Custom Document",
      fileNameStem: "CustomDocument",
      isRequired: false,
      sortIndex: Number.MAX_SAFE_INTEGER,
      fields: [{ id: "documentText", label: "Document text", type: "textarea", required: true }],
      body: "[DOCUMENT_TITLE]\nCustom Document\n\n[STANDARD_SIGNATURE_BLOCK]",
    }
  );
}
