/**
 * Evidence import service (TPI-V2-WEB-009 §11/§12).
 *
 * Import is journalled and verified before success is reported:
 *   hashing → storing → verifying → metadata → complete
 * A failure at any stage leaves a `failed` journal row (never a silent
 * half-import). `recoverIncompleteImports` runs at startup: verified staged
 * files are promoted to evidence records, unverifiable ones are retained for
 * inspection rather than discarded.
 *
 * Originals are never modified, compressed, transcoded, or normalized.
 */
import type { TPIDatabase } from "../db";
import { SCHEMA_VERSION } from "../db";
import { v4 as uuidv4 } from "../../shared/uuid";
import type {
  EvidenceImportRecord,
  EvidenceMediaType,
  EvidenceRecord,
  TimestampSource,
} from "../types";
import { ValidationError } from "../validation";
import { AuditService } from "../audit";
import { hashBlob } from "../files/opfs.hash";
import { getManagedFileStore } from "../files/storeRegistry";
import { EvidenceRepository } from "../repositories/evidenceRepository";

export interface ImportCandidate {
  file: File;
  mediaType: EvidenceMediaType;
}

export interface ImportOptions {
  caseId: string;
  sessionId?: string | null;
  roomId?: string | null;
  locationId?: string | null;
  sourceDescription?: string;
  notes?: string;
  /** Investigator-entered capture time (ms) when known. */
  captureTimestamp?: number | null;
  captureTimestampSource?: TimestampSource;
  title?: string;
}

export interface ImportResult {
  evidence: EvidenceRecord;
  duplicateOf?: EvidenceRecord;
}

export interface ImportFailure {
  fileName: string;
  error: string;
  stage: EvidenceImportRecord["stage"];
}

export interface ImportReport {
  imported: ImportResult[];
  duplicates: ImportResult[];
  failed: ImportFailure[];
}

/** Media type inferred from the browser-provided MIME type / extension. */
export function inferMediaType(file: File): EvidenceMediaType | "unsupported" {
  const type = (file.type || "").toLowerCase();
  if (type.startsWith("audio/")) return "audio";
  if (type.startsWith("video/")) return "video";
  if (type.startsWith("image/")) return "photo";
  if (type === "application/pdf" || type.startsWith("text/") || type.includes("document") || type.includes("word") || type.includes("sheet")) return "document";
  const ext = file.name.toLowerCase().split(".").pop() ?? "";
  if (["wav", "mp3", "m4a", "aac", "flac", "ogg", "opus"].includes(ext)) return "audio";
  if (["mp4", "mov", "mkv", "webm", "avi"].includes(ext)) return "video";
  if (["jpg", "jpeg", "png", "gif", "webp", "heic", "tif", "tiff", "bmp"].includes(ext)) return "photo";
  if (["pdf", "txt", "md", "csv", "json", "doc", "docx", "rtf"].includes(ext)) return "document";
  if (["log", "dat", "bin", "sensor"].includes(ext)) return "sensor-log";
  return "unsupported";
}

export class EvidenceImportService {
  private readonly audit: AuditService;
  private readonly evidence: EvidenceRepository;

  constructor(private readonly db: TPIDatabase) {
    this.audit = new AuditService(db);
    this.evidence = new EvidenceRepository(db);
  }

  /** Import a batch of files. One failure never aborts the rest. */
  async importFiles(files: File[], options: ImportOptions): Promise<ImportReport> {
    const report: ImportReport = { imported: [], duplicates: [], failed: [] };
    for (const file of files) {
      try {
        const result = await this.importOne(file, options);
        if (result.duplicateOf) report.duplicates.push(result);
        else report.imported.push(result);
      } catch (err) {
        report.failed.push({
          fileName: file.name,
          error: (err as Error).message,
          stage: ((err as { importStage?: EvidenceImportRecord["stage"] }).importStage ?? "failed"),
        });
      }
    }
    return report;
  }

  /** Import a single file through the journalled pipeline. */
  async importOne(file: File, options: ImportOptions): Promise<ImportResult> {
    const { caseId } = options;
    const caseRecord = await this.db.cases.get(caseId);
    if (!caseRecord) throw new ValidationError(`Case not found: ${caseId}`, "caseId");
    if (options.sessionId) {
      const session = await this.db.sessions.get(options.sessionId);
      if (!session) throw new ValidationError("Session does not exist.", "sessionId");
      if (session.caseId !== caseId) throw new ValidationError("Session belongs to a different case.", "sessionId");
    }
    if (options.roomId) {
      const room = await this.db.structureRooms.get(options.roomId);
      if (!room) throw new ValidationError("Room does not exist.", "roomId");
      if (room.caseId !== caseId) throw new ValidationError("Room belongs to a different case.", "roomId");
    }
    if (options.locationId) {
      const location = await this.db.locations.get(options.locationId);
      if (!location) throw new ValidationError("Location does not exist.", "locationId");
    }
    if (file.size === 0) throw stageError(new ValidationError("File is empty (0 bytes).", "file"), "hashing");

    const mediaType = inferMediaType(file);
    if (mediaType === "unsupported") {
      throw stageError(
        new ValidationError(
          `Unsupported file type for "${file.name}" (${file.type || "unknown MIME type"}).`,
          "file",
        ),
        "hashing",
      );
    }

    const journalId = uuidv4();
    const storedName = `${journalId}-original-${file.name.replace(/[/\\]/g, "_")}`;
    const journal: EvidenceImportRecord = {
      id: journalId,
      schemaVersion: SCHEMA_VERSION,
      caseId,
      sessionId: options.sessionId ?? null,
      fileName: file.name,
      fileSizeBytes: file.size,
      mediaType,
      stage: "hashing",
      storedName,
      contentHash: "",
      evidenceId: null,
      createdAt: Date.now(),
      updatedAt: Date.now(),
      completedAt: null,
      error: "",
    };
    await this.db.evidenceImports.put(journal);

    const setStage = async (stage: EvidenceImportRecord["stage"], error = "") => {
      const current = (await this.db.evidenceImports.get(journalId)) ?? journal;
      await this.db.evidenceImports.put({ ...current, stage, error, updatedAt: Date.now() });
    };

    try {
      // 1) Hash the source bytes BEFORE storing (duplicate detection + reference).
      let contentHash: string;
      try {
        contentHash = await hashBlob(file);
      } catch (err) {
        await setStage("failed", `hashing failed: ${(err as Error).message}`);
        throw stageError(new ValidationError(`Could not hash "${file.name}": ${(err as Error).message}`, "file"), "hashing");
      }
      await setStage("hashing");
      const existing = (await this.db.evidence.where("caseId").equals(caseId).toArray()).find(
        (e) => e.contentHash === contentHash && e.kind === "original",
      );
      if (existing) {
        await setStage("complete");
        await this.db.evidenceImports.put({
          ...journal,
          contentHash,
          stage: "complete",
          completedAt: Date.now(),
          updatedAt: Date.now(),
          evidenceId: existing.id,
          error: "duplicate of an existing original",
        });
        await this.audit.record("evidenceImported", "Duplicate evidence import detected; original preserved and reused.", {
          caseId,
          affectedRecordId: existing.id,
          metadata: { duplicate: true },
        });
        return { evidence: existing, duplicateOf: existing };
      }

      // 2) Store the bytes in managed OPFS.
      let stored: { path: string; contentHash: string };
      try {
        stored = await getManagedFileStore().store(caseId, storedName, file);
      } catch (err) {
        await setStage("failed", `storage failed: ${(err as Error).message}`);
        throw stageError(new ValidationError(`Evidence storage failed: ${(err as Error).message}`, "storage"), "storing");
      }
      await setStage("storing");

      // 3) Verify the stored copy by reading it back and re-hashing.
      const readBack = await getManagedFileStore().read(stored.path);
      if (!readBack) {
        await setStage("failed", "stored copy could not be read back");
        throw stageError(new ValidationError("Stored copy could not be read back for verification.", "storage"), "verifying");
      }
      const storedHash = await hashBlob(readBack);
      if (storedHash !== contentHash || stored.contentHash !== contentHash) {
        await setStage("failed", "hash mismatch after write");
        throw stageError(
          new ValidationError("Integrity mismatch: the stored copy does not match the source file.", "contentHash"),
          "verifying",
        );
      }
      await setStage("verifying");

      // 4) Commit metadata through the authoritative evidence repository.
      const record = await this.evidence.storeOriginal({
        caseId,
        sessionId: options.sessionId ?? undefined,
        mediaType,
        title: options.title?.trim() || file.name,
        fileName: storedName,
        data: file,
        origin: "import",
        recordedBy: "local-user",
      });
      const enriched: EvidenceRecord = {
        ...record,
        originalFileName: file.name,
        sourceDescription: options.sourceDescription ?? "",
        importedAt: Date.now(),
        verificationStatus: "verified",
        verifiedAt: Date.now(),
        verificationDetail: "Verified at import by reading the stored copy back and re-hashing.",
        locationId: options.locationId ?? null,
        roomId: options.roomId ?? null,
        observationId: null,
        markerId: null,
        measurementId: null,
        captureTimestamp: options.captureTimestamp ?? file.lastModified ?? null,
        captureTimestampSource: options.captureTimestamp
          ? options.captureTimestampSource ?? "investigator"
          : file.lastModified
            ? "fileMetadata"
            : "unknown",
        captureTimezoneOffsetMinutes: -new Date().getTimezoneOffset(),
        notes: options.notes ?? "",
      };
      await this.db.evidence.put(enriched);
      await setStage("metadata");

      const finalJournal = (await this.db.evidenceImports.get(journalId)) ?? journal;
      await this.db.evidenceImports.put({
        ...finalJournal,
        stage: "complete",
        contentHash,
        evidenceId: enriched.id,
        completedAt: Date.now(),
        updatedAt: Date.now(),
        error: "",
      });

      await this.audit.record("evidenceImported", `Evidence imported (${mediaType}).`, {
        caseId,
        affectedRecordId: enriched.id,
        metadata: { mediaType, bytes: enriched.fileSizeBytes, verified: true },
      });
      return { evidence: enriched };
    } catch (err) {
      const journalRow = (await this.db.evidenceImports.get(journalId)) ?? journal;
      if (journalRow.stage !== "failed") {
        await this.db.evidenceImports.put({
          ...journalRow,
          stage: "failed",
          error: (err as Error).message,
          updatedAt: Date.now(),
        });
      }
      throw err;
    }
  }

  /* ------------------------------- recovery -------------------------------- */

  /**
   * Recover imports interrupted by a browser close (WP-9 §12). Called at
   * startup. Staged files that verify are promoted to evidence records;
   * anything that cannot be verified is reported and retained, never deleted.
   */
  async recoverIncompleteImports(): Promise<{
    promoted: EvidenceRecord[];
    unresolved: EvidenceImportRecord[];
  }> {
    const all = await this.db.evidenceImports.toArray();
    const incomplete = all.filter((row) => row.stage !== "complete" && row.stage !== "failed");
    const promoted: EvidenceRecord[] = [];
    const unresolved: EvidenceImportRecord[] = [];

    for (const row of incomplete) {
      const path = `cases/${row.caseId}/evidence/${row.storedName}`;
      const bytes = await getManagedFileStore().read(path);
      if (!bytes) {
        // Nothing verifiable was staged — mark failed so it is visible to the
        // investigator rather than lingering invisibly.
        await this.db.evidenceImports.put({
          ...row,
          stage: "failed",
          error: "Import was interrupted before a verifiable copy existed.",
          updatedAt: Date.now(),
        });
        unresolved.push(row);
        continue;
      }
      const storedHash = await hashBlob(bytes);
      if (row.contentHash && storedHash !== row.contentHash) {
        await this.db.evidenceImports.put({
          ...row,
          stage: "failed",
          error: "Interrupted import failed verification (stored copy does not match).",
          updatedAt: Date.now(),
        });
        unresolved.push(row);
        continue;
      }
      // Verified staged copy → promote to a real evidence record.
      const record = await this.evidence.storeOriginal({
        caseId: row.caseId,
        sessionId: row.sessionId ?? undefined,
        mediaType: row.mediaType,
        title: row.fileName,
        fileName: row.storedName,
        data: new Blob([bytes], { type: "" }),
        origin: "import-recovered",
        recordedBy: "local-user",
      });
      const enriched: EvidenceRecord = {
        ...record,
        originalFileName: row.fileName,
        importedAt: Date.now(),
        verificationStatus: "verified",
        verifiedAt: Date.now(),
        verificationDetail: "Recovered from an interrupted import and verified by re-hashing.",
        locationId: null,
        roomId: null,
        observationId: null,
        markerId: null,
        measurementId: null,
        captureTimestamp: record.acquiredAt,
        captureTimestampSource: "import",
        captureTimezoneOffsetMinutes: null,
      };
      await this.db.evidence.put(enriched);
      await this.db.evidenceImports.put({
        ...row,
        stage: "complete",
        contentHash: storedHash,
        evidenceId: enriched.id,
        completedAt: Date.now(),
        updatedAt: Date.now(),
        error: "recovered",
      });
      await this.audit.record("importRecovered", "Interrupted evidence import recovered and verified.", {
        caseId: row.caseId,
        affectedRecordId: enriched.id,
        metadata: { bytes: enriched.fileSizeBytes },
      });
      promoted.push(enriched);
    }
    return { promoted, unresolved };
  }

  async listImports(caseId: string): Promise<EvidenceImportRecord[]> {
    const rows = await this.db.evidenceImports.where("caseId").equals(caseId).toArray();
    return rows.sort((a, b) => b.createdAt - a.createdAt);
  }
}

/** Attach the failing stage so the report can say exactly where it stopped. */
function stageError(err: Error, stage: EvidenceImportRecord["stage"]): Error {
  (err as { importStage?: EvidenceImportRecord["stage"] }).importStage = stage;
  return err;
}
