/**
 * Sensor capability service (TPI-V2-WEB-008 §14).
 *
 * Centralizes sensor availability so the UI never claims equipment is
 * operational when it is not. Availability is NOT inferred from the mere
 * presence of a browser API — every capability starts `unknown`/`unsupported`
 * and only becomes `active` after a real, successful acquisition.
 */
export type SensorState =
  | "unsupported"
  | "permissionRequired"
  | "permissionDenied"
  | "deviceUnavailable"
  | "active"
  | "interrupted"
  | "stopped";

export interface SensorCapability {
  id: "microphone" | "magnetometer" | "motion" | "light" | "geolocation" | "ambientTemperature";
  label: string;
  state: SensorState;
  /** Human-readable explanation of the current state. */
  detail: string;
  /** Whether the browser exposes any API for this capability. */
  apiPresent: boolean;
  /** Recorded at last state change. */
  changedAt: number;
}

/**
 * Honest static assessment of what a browser can and cannot provide.
 * Hardware-dependent capabilities are explicitly marked unsupported for
 * measurement purposes even where an API nominally exists:
 *  - magnetometer: the Magnetometer/DeviceOrientation API is not widely
 *    available and its values are not a calibrated EMF instrument reading;
 *  - light/temperature/motion: same reasoning.
 * Manual instrument entry is the supported path for these quantities.
 */
export function initialCapabilities(): SensorCapability[] {
  const now = Date.now();
  const has = (fn: () => boolean): boolean => {
    try {
      return fn();
    } catch {
      return false;
    }
  };
  const micApi = has(() => typeof navigator !== "undefined" && !!navigator.mediaDevices?.getUserMedia);
  return [
    {
      id: "microphone",
      label: "Microphone (ambient audio level)",
      state: micApi ? "permissionRequired" : "unsupported",
      detail: micApi
        ? "Signal level only — dBFS, not a calibrated sound-pressure level. Requires a secure context and explicit user permission."
        : "This browser does not expose getUserMedia; audio level monitoring is unavailable.",
      apiPresent: micApi,
      changedAt: now,
    },
    {
      id: "magnetometer",
      label: "Magnetometer (EMF)",
      state: "unsupported",
      detail:
        "No calibrated magnetometer interface is available in this browser. EMF must be recorded from an external meter using manual instrument entry.",
      apiPresent: false,
      changedAt: now,
    },
    {
      id: "ambientTemperature",
      label: "Ambient temperature sensor",
      state: "unsupported",
      detail: "Browsers do not expose ambient temperature sensors. Use manual instrument entry.",
      apiPresent: false,
      changedAt: now,
    },
    {
      id: "light",
      label: "Ambient light sensor",
      state: "unsupported",
      detail: "The AmbientLightSensor API is not broadly available. Use manual observation entry.",
      apiPresent: false,
      changedAt: now,
    },
    {
      id: "motion",
      label: "Motion / vibration sensor",
      state: "unsupported",
      detail: "Motion sensors are not available for calibrated measurement in this browser.",
      apiPresent: false,
      changedAt: now,
    },
    {
      id: "geolocation",
      label: "Geolocation",
      state: "permissionRequired",
      detail: "Used only for optional property coordinates when the investigator grants permission.",
      apiPresent: has(() => typeof navigator !== "undefined" && !!navigator.geolocation),
      changedAt: now,
    },
  ];
}

/** Live capability registry — the single source of truth for sensor state. */
export class SensorCapabilityService {
  private capabilities = new Map<string, SensorCapability>();
  private listeners = new Set<(caps: SensorCapability[]) => void>();

  constructor() {
    for (const cap of initialCapabilities()) this.capabilities.set(cap.id, cap);
  }

  list(): SensorCapability[] {
    return [...this.capabilities.values()];
  }

  get(id: SensorCapability["id"]): SensorCapability | undefined {
    return this.capabilities.get(id);
  }

  /** Update a capability state; emits to subscribers. */
  setState(id: SensorCapability["id"], state: SensorState, detail?: string): SensorCapability | undefined {
    const existing = this.capabilities.get(id);
    if (!existing) return undefined;
    const next: SensorCapability = {
      ...existing,
      state,
      detail: detail ?? existing.detail,
      changedAt: Date.now(),
    };
    this.capabilities.set(id, next);
    for (const fn of this.listeners) fn(this.list());
    return next;
  }

  subscribe(fn: (caps: SensorCapability[]) => void): () => void {
    this.listeners.add(fn);
    fn(this.list());
    return () => this.listeners.delete(fn);
  }
}

let instance: SensorCapabilityService | undefined;
export function getSensorCapabilities(): SensorCapabilityService {
  instance ??= new SensorCapabilityService();
  return instance;
}
export function setSensorCapabilitiesForTesting(svc: SensorCapabilityService | undefined): void {
  instance = svc;
}
