/**
 * Evidence repository — original vs derived evidence, integrity, provenance
 * (Directive §8). All media bytes live in OPFS; metadata lives in Dexie.
 *
 * CRITICAL RULE: original evidence is never overwritten during analysis.
 * Processed/enhanced/converted media is stored as a separate DERIVED record
 * linked to its parent via parentId.
 *
 * A hash provides INTEGRITY DETECTION (detecting accidental change or
 * corruption), not tamper-proofing. See docs/EVIDENCE_INTEGRITY.md.
 */
import type { TPIDatabase } from "../db";
import { now, uuidv4 as uuidV4, SCHEMA_VERSION } from "../db";
import { getManagedFileStore } from "../files/storeRegistry";
import { hashBlob } from "../files/opfs.hash";
import type {
  EvidenceMediaType,
  EvidenceRecord,
  InvestigationSessionRecord,
} from "../types";
import {
  ValidationError,
  assertEvidenceRecordShape,
  assertReferenceExists,
  assertSessionBelongsToCase,
} from "../validation";
import { AuditService } from "../audit";

/** Injectable storage seam (tests use fake OPFS). */
export type EvidenceStore = (
  caseId: string,
  fileName: string,
  data: Blob,
) => Promise<{ path: string; contentHash: string }>;

export class EvidenceRepository {
  private readonly audit: AuditService;
  private readonly storeFile: EvidenceStore;

  constructor(
    private readonly db: TPIDatabase,
    // Routed through the managed-file store seam so tests can inject an
    // in-memory filesystem (Node has no OPFS). Production uses OPFS.
    storeFile: EvidenceStore = (caseId, fileName, data) => getManagedFileStore().store(caseId, fileName, data),
  ) {
    this.audit = new AuditService(db);
    this.storeFile = storeFile;
  }

  private async caseExists(caseId: string): Promise<boolean> {
    return (await this.db.cases.get(caseId)) !== undefined;
  }

  /** Store a newly acquired ORIGINAL evidence file. */
  async storeOriginal(input: {
    caseId: string;
    sessionId?: string;
    mediaType: EvidenceMediaType;
    title: string;
    fileName: string;
    data: Blob;
    origin?: string;
    recordedBy?: string;
  }): Promise<EvidenceRecord> {
    const { caseId } = input;
    if (!(await this.caseExists(caseId))) {
      throw new ValidationError(`Case not found: ${caseId}`, "caseId");
    }
    let session: InvestigationSessionRecord | undefined;
    if (input.sessionId !== undefined) {
      session = await this.db.sessions.get(input.sessionId);
      assertReferenceExists(input.sessionId, session !== undefined, "sessionId");
      assertSessionBelongsToCase(session, caseId);
    }

    let contentHash: string;
    try {
      contentHash = await hashBlob(input.data);
    } catch (err) {
      throw new ValidationError(
        `Failed to hash evidence data: ${(err as Error).message}`,
        "data",
      );
    }

    const evidenceId = uuidV4();
    const safeName = input.fileName.replace(/[/\\]/g, "_");
    const fileName = `${evidenceId}-original-${safeName}`;
    let stored: { path: string; contentHash: string };
    try {
      stored = await this.storeFile(caseId, fileName, input.data);
    } catch (err) {
      throw new ValidationError(
        `Evidence storage failed (quota or OPFS error): ${(err as Error).message}`,
        "storage",
      );
    }
    if (stored.contentHash !== contentHash) {
      throw new ValidationError("Integrity mismatch immediately after write", "contentHash");
    }

    const record: EvidenceRecord = {
      id: evidenceId,
      schemaVersion: SCHEMA_VERSION as EvidenceRecord["schemaVersion"],
      createdAt: now(),
      updatedAt: now(),
      caseId,
      sessionId: input.sessionId,
      kind: "original",
      mediaType: input.mediaType,
      title: input.title,
      fileName,
      opfsPath: stored.path,
      fileSizeBytes: input.data.size,
      mimeType: input.data.type || undefined,
      contentHash,
      acquiredAt: now(),
      reviewStatus: "raw",
      provenance: {
        origin: input.origin ?? "local-capture",
        contentHash,
        recordedAt: now(),
        recordedBy: input.recordedBy ?? "local-user",
      },
    };
    assertEvidenceRecordShape(record);

    await this.db.transaction("rw", this.db.evidence, this.db.auditEvents, async () => {
      await this.db.evidence.add(record);
      await this.audit.record("evidenceAdded", `Evidence added to case (${input.mediaType})`, {
        caseId,
        affectedRecordId: evidenceId,
        metadata: { kind: "original", sizeBytes: record.fileSizeBytes },
      });
    });
    return record;
  }

  /** Create a DERIVED asset (processed/enhanced/converted) from a source record. */
  async createDerived(input: {
    sourceId: string;
    mediaType: EvidenceMediaType;
    title: string;
    fileName: string;
    data: Blob;
    processedBy?: string;
  }): Promise<EvidenceRecord> {
    const source = await this.db.evidence.get(input.sourceId);
    if (!source) {
      throw new ValidationError(`Source evidence not found: ${input.sourceId}`, "sourceId");
    }
    const evidenceId = uuidV4();
    const safeName = input.fileName.replace(/[/\\]/g, "_");
    const fileName = `${evidenceId}-derived-${safeName}`;
    let stored: { path: string; contentHash: string };
    try {
      stored = await this.storeFile(source.caseId, fileName, input.data);
    } catch (err) {
      throw new ValidationError(
        `Derived evidence storage failed: ${(err as Error).message}`,
        "storage",
      );
    }
    const record: EvidenceRecord = {
      id: evidenceId,
      schemaVersion: SCHEMA_VERSION as EvidenceRecord["schemaVersion"],
      createdAt: now(),
      updatedAt: now(),
      caseId: source.caseId,
      sessionId: source.sessionId,
      kind: "derived",
      parentId: source.id,
      mediaType: input.mediaType,
      title: input.title,
      fileName,
      opfsPath: stored.path,
      fileSizeBytes: input.data.size,
      mimeType: input.data.type || undefined,
      contentHash: stored.contentHash,
      acquiredAt: now(),
      reviewStatus: "raw",
      provenance: {
        origin: "derived",
        contentHash: stored.contentHash,
        recordedAt: now(),
        recordedBy: input.processedBy ?? "local-user",
      },
    };
    assertEvidenceRecordShape(record);

    await this.db.transaction("rw", this.db.evidence, this.db.auditEvents, async () => {
      await this.db.evidence.add(record);
      await this.audit.record("evidenceProcessed", `Derived evidence created from source`, {
        caseId: source.caseId,
        affectedRecordId: evidenceId,
        metadata: { parentId: source.id, sizeBytes: record.fileSizeBytes },
      });
    });
    return record;
  }

  async getEvidence(id: string): Promise<EvidenceRecord | undefined> {
    return this.db.evidence.get(id);
  }

  async listForCase(caseId: string, limit = 100, offset = 0): Promise<EvidenceRecord[]> {
    return this.db.evidence
      .where("caseId")
      .equals(caseId)
      .reverse()
      .sortBy("createdAt")
      .then((all) => all.slice(offset, offset + limit));
  }

  /**
   * Verify integrity: re-read the stored file from OPFS and recompute its hash.
   * Returns "verified" | "missing" | "corrupted".
   */
  async verifyIntegrity(
    id: string,
    readFile: (opfsPath: string) => Promise<ArrayBuffer | undefined> = defaultRead,
  ): Promise<"verified" | "missing" | "corrupted"> {
    const record = await this.db.evidence.get(id);
    if (!record) throw new ValidationError(`Evidence not found: ${id}`, "id");
    let data: ArrayBuffer | undefined;
    try {
      data = await readFile(record.opfsPath);
    } catch {
      data = undefined;
    }
    if (!data) {
      await this.audit.record("evidenceVerified", "Evidence file missing from storage", {
        caseId: record.caseId,
        affectedRecordId: id,
        metadata: { result: "missing" },
      });
      return "missing";
    }
    const hash = await hashBlob(data);
    const ok = hash === record.contentHash;
    await this.audit.record(
      "evidenceVerified",
      ok ? "Evidence integrity verified" : "Evidence integrity check FAILED",
      {
        caseId: record.caseId,
        affectedRecordId: id,
        metadata: { result: ok ? "verified" : "corrupted" },
      },
    );
    return ok ? "verified" : "corrupted";
  }

  async deleteEvidenceMetadata(id: string): Promise<void> {
    // Metadata deletion is allowed only for records without a derived chain
    // and is audited. OPFS bytes are intentionally left in place (recovery
    // guidance), but orphaned-file cleanup is a future maintenance flow.
    const record = await this.db.evidence.get(id);
    if (!record) return;
    const children = await this.db.evidence.where("parentId").equals(id).count();
    if (children > 0) {
      throw new ValidationError(
        "Cannot delete evidence that has derived assets",
        "parentId",
      );
    }
    await this.db.transaction("rw", this.db.evidence, this.db.auditEvents, async () => {
      await this.db.evidence.delete(id);
      await this.audit.record("evidenceVerified", "Evidence metadata removed (bytes retained)", {
        caseId: record.caseId,
        affectedRecordId: id,
      });
    });
  }
}

/** Default OPFS reader — accepts the full opfsPath recorded on the record. */
async function defaultRead(opfsPath: string): Promise<ArrayBuffer | undefined> {
  const { readCasePath } = await import("../files/opfs");
  return readCasePath(opfsPath);
}
