/**
 * Investigation notes and per-room summaries — schema v12 data layer
 * (TPI-V2-WEB-016).
 *
 * ORIGINAL SEMANTICS
 *   `PPInvestigationNote` is investigator-authored text, scoped to a case and
 *   optionally a room, with three kinds: Note / Observation / Photo Flag.
 *   `InvestigationRoomRecord.investigationSummary` is one text field per room
 *   inside one investigation session.
 *
 * INTEGRITY RULES ENFORCED HERE
 *   - a note/summary can only reference a case that exists;
 *   - a room or session reference must belong to that same case (cross-case
 *     references are rejected, never silently repaired);
 *   - editing preserves `createdAt`; ordering uses `updatedAt`;
 *   - author attribution is stored only when the investigator entered it — an
 *     empty string means "not recorded", never a fabricated identity;
 *   - notes never create evidence, observations, reviews or checklist state;
 *   - a room summary is unique per case + session + room (DB unique index).
 */
import { SCHEMA_VERSION, now, uuidv4, type TPIDatabase } from "../db";
import { AuditService } from "../audit";
import { ValidationError } from "../validation";
import type {
  InvestigationNoteKind,
  InvestigationNoteRecord,
  RoomSummaryRecord,
} from "../types";

export const NOTE_KINDS: readonly InvestigationNoteKind[] = [
  "note",
  "observation",
  "photoFlag",
];

/** Original `PPInvestigationNoteKind` display labels. */
export const NOTE_KIND_LABELS: Record<InvestigationNoteKind, string> = {
  note: "Note",
  observation: "Observation",
  photoFlag: "Photo Flag",
};

export interface CreateInvestigationNoteInput {
  caseId: string;
  roomId?: string | null;
  sessionId?: string | null;
  kind: InvestigationNoteKind;
  title?: string;
  body?: string;
  author?: string;
}

export interface UpdateInvestigationNoteInput {
  roomId?: string | null;
  sessionId?: string | null;
  kind?: InvestigationNoteKind;
  title?: string;
  body?: string;
  author?: string;
}

export interface SaveRoomSummaryInput {
  caseId: string;
  sessionId: string;
  roomId: string;
  body: string;
  author?: string;
}

function assertKind(value: string): asserts value is InvestigationNoteKind {
  if (!NOTE_KINDS.includes(value as InvestigationNoteKind)) {
    throw new ValidationError(
      `Unknown investigation note kind: ${value}`,
      "kind",
    );
  }
}

async function assertCaseExists(db: TPIDatabase, caseId: string): Promise<void> {
  if (!caseId || !(await db.cases.get(caseId))) {
    throw new ValidationError(`Case not found: ${caseId}`, "caseId");
  }
}

async function assertRoomBelongsToCase(
  db: TPIDatabase,
  caseId: string,
  roomId: string,
): Promise<void> {
  const room = await db.structureRooms.get(roomId);
  if (!room) throw new ValidationError("Room not found.", "roomId");
  if (room.caseId !== caseId) {
    throw new ValidationError("Room belongs to a different case.", "roomId");
  }
}

async function assertSessionBelongsToCase(
  db: TPIDatabase,
  caseId: string,
  sessionId: string,
): Promise<void> {
  const session = await db.sessions.get(sessionId);
  if (!session) throw new ValidationError("Investigation session not found.", "sessionId");
  if (session.caseId !== caseId) {
    throw new ValidationError(
      "Investigation session belongs to a different case.",
      "sessionId",
    );
  }
}

function normalizeOptionalId(value: string | null | undefined): string | null {
  return value && value.trim() ? value : null;
}

/** Creation time is never rewritten by an edit; updatedAt always advances. */
function nextUpdatedAt(previous: number): number {
  return Math.max(now(), previous + 1);
}

export class InvestigationNoteRepository {
  private readonly audit: AuditService;

  constructor(private readonly db: TPIDatabase) {
    this.audit = new AuditService(db);
  }

  async create(input: CreateInvestigationNoteInput): Promise<InvestigationNoteRecord> {
    assertKind(input.kind);
    const title = input.title?.trim() ?? "";
    const body = input.body ?? "";
    if (!title && !body.trim()) {
      throw new ValidationError("A note needs a title or body text.", "body");
    }
    const roomId = normalizeOptionalId(input.roomId);
    const sessionId = normalizeOptionalId(input.sessionId);
    const author = input.author?.trim() ?? "";

    return this.db.transaction(
      "rw",
      [
        this.db.investigationNotes,
        this.db.cases,
        this.db.structureRooms,
        this.db.sessions,
        this.db.auditEvents,
      ],
      async () => {
        await assertCaseExists(this.db, input.caseId);
        if (roomId) await assertRoomBelongsToCase(this.db, input.caseId, roomId);
        if (sessionId) await assertSessionBelongsToCase(this.db, input.caseId, sessionId);

        const ts = now();
        const record: InvestigationNoteRecord = {
          id: uuidv4(),
          schemaVersion: SCHEMA_VERSION as InvestigationNoteRecord["schemaVersion"],
          createdAt: ts,
          updatedAt: ts,
          caseId: input.caseId,
          roomId,
          sessionId,
          kind: input.kind,
          title,
          body,
          author,
        };
        await this.db.investigationNotes.add(record);
        await this.audit.record(
          "noteCreated",
          `Investigation note created (${NOTE_KIND_LABELS[input.kind]}).`,
          {
            caseId: input.caseId,
            affectedRecordId: record.id,
            metadata: {
              kind: input.kind,
              hasRoom: Boolean(roomId),
              hasSession: Boolean(sessionId),
            },
          },
        );
        return record;
      },
    );
  }

  async update(
    caseId: string,
    id: string,
    patch: UpdateInvestigationNoteInput,
  ): Promise<InvestigationNoteRecord> {
    return this.db.transaction(
      "rw",
      [
        this.db.investigationNotes,
        this.db.cases,
        this.db.structureRooms,
        this.db.sessions,
        this.db.auditEvents,
      ],
      async () => {
        const existing = await this.db.investigationNotes.get(id);
        // Cross-case reads/writes are indistinguishable from "not found".
        if (!existing || existing.caseId !== caseId) {
          throw new ValidationError("Note not found for this case.", "id");
        }
        const kind = patch.kind ?? existing.kind;
        assertKind(kind);
        const roomId =
          patch.roomId === undefined ? existing.roomId : normalizeOptionalId(patch.roomId);
        const sessionId =
          patch.sessionId === undefined
            ? existing.sessionId
            : normalizeOptionalId(patch.sessionId);
        if (roomId) await assertRoomBelongsToCase(this.db, caseId, roomId);
        if (sessionId) await assertSessionBelongsToCase(this.db, caseId, sessionId);

        const title = patch.title === undefined ? existing.title : patch.title.trim();
        const body = patch.body === undefined ? existing.body : patch.body;
        if (!title && !body.trim()) {
          throw new ValidationError("A note needs a title or body text.", "body");
        }
        const author = patch.author === undefined ? existing.author : patch.author.trim();

        const next: InvestigationNoteRecord = {
          ...existing,
          kind,
          roomId,
          sessionId,
          title,
          body,
          author,
          updatedAt: nextUpdatedAt(existing.updatedAt),
        };
        await this.db.investigationNotes.put(next);
        await this.audit.record(
          "noteUpdated",
          `Investigation note updated (${NOTE_KIND_LABELS[kind]}).`,
          {
            caseId,
            affectedRecordId: id,
            metadata: { kind, hasRoom: Boolean(roomId), hasSession: Boolean(sessionId) },
          },
        );
        return next;
      },
    );
  }

  async get(caseId: string, id: string): Promise<InvestigationNoteRecord | undefined> {
    const row = await this.db.investigationNotes.get(id);
    return row && row.caseId === caseId ? row : undefined;
  }

  async listForCase(caseId: string): Promise<InvestigationNoteRecord[]> {
    const rows = await this.db.investigationNotes.where("caseId").equals(caseId).toArray();
    return rows.sort((a, b) => b.updatedAt - a.updatedAt);
  }

  async countForCase(caseId: string): Promise<number> {
    return this.db.investigationNotes.where("caseId").equals(caseId).count();
  }
}

export class RoomSummaryRepository {
  private readonly audit: AuditService;

  constructor(private readonly db: TPIDatabase) {
    this.audit = new AuditService(db);
  }

  /**
   * Deterministic upsert keyed by case + session + room. Re-saving edits the
   * existing summary (same id, preserved createdAt) instead of creating a
   * duplicate. The compound unique index is the second line of defence.
   */
  async save(input: SaveRoomSummaryInput): Promise<RoomSummaryRecord> {
    if (!input.body.trim()) {
      throw new ValidationError("Room summary text is required.", "body");
    }
    const author = input.author?.trim() ?? "";

    return this.db.transaction(
      "rw",
      [
        this.db.roomSummaries,
        this.db.cases,
        this.db.structureRooms,
        this.db.sessions,
        this.db.auditEvents,
      ],
      async () => {
        await assertCaseExists(this.db, input.caseId);
        await assertSessionBelongsToCase(this.db, input.caseId, input.sessionId);
        await assertRoomBelongsToCase(this.db, input.caseId, input.roomId);

        const existing = await this.db.roomSummaries
          .where("[caseId+sessionId+roomId]")
          .equals([input.caseId, input.sessionId, input.roomId])
          .first();
        const ts = now();
        if (existing) {
          const next: RoomSummaryRecord = {
            ...existing,
            body: input.body,
            author,
            updatedAt: nextUpdatedAt(existing.updatedAt),
          };
          await this.db.roomSummaries.put(next);
          await this.audit.record(
            "roomSummarySaved",
            "Per-room investigation summary updated.",
            {
              caseId: input.caseId,
              affectedRecordId: next.id,
              metadata: { created: false, roomId: input.roomId, sessionId: input.sessionId },
            },
          );
          return next;
        }

        const record: RoomSummaryRecord = {
          id: uuidv4(),
          schemaVersion: SCHEMA_VERSION as RoomSummaryRecord["schemaVersion"],
          createdAt: ts,
          updatedAt: ts,
          caseId: input.caseId,
          sessionId: input.sessionId,
          roomId: input.roomId,
          body: input.body,
          author,
        };
        await this.db.roomSummaries.add(record);
        await this.audit.record("roomSummarySaved", "Per-room investigation summary created.", {
          caseId: input.caseId,
          affectedRecordId: record.id,
          metadata: { created: true, roomId: input.roomId, sessionId: input.sessionId },
        });
        return record;
      },
    );
  }

  async getForRoom(
    caseId: string,
    sessionId: string,
    roomId: string,
  ): Promise<RoomSummaryRecord | undefined> {
    return this.db.roomSummaries
      .where("[caseId+sessionId+roomId]")
      .equals([caseId, sessionId, roomId])
      .first();
  }

  async listForSession(sessionId: string): Promise<RoomSummaryRecord[]> {
    const rows = await this.db.roomSummaries.where("sessionId").equals(sessionId).toArray();
    return rows.sort((a, b) => b.updatedAt - a.updatedAt);
  }

  async listForCase(caseId: string): Promise<RoomSummaryRecord[]> {
    const rows = await this.db.roomSummaries.where("caseId").equals(caseId).toArray();
    return rows.sort((a, b) => b.updatedAt - a.updatedAt);
  }
}
