/**
 * Investigation Summary — TPI-V2-WEB-C2A.
 *
 * ORIGINAL SOURCE: `Cases/CaseInvestigationSummaryView.swift` (1,204 lines).
 * The original screen is room/area-scoped: it shows the active room and phase,
 * investigation start/end/status, per-room summary text, a review/claims gate,
 * structured evidence assessments, AI interaction notes, and PDF export. For
 * haunted locations it shows location identity, documented coverage, claims,
 * evidence counts, and a capsule export.
 *
 * THIS BUILD IS READ-ONLY (C2A directive, Phase 5; WEB-017 report preview). It
 * reconstructs the informational half from records that actually exist in the
 * browser: case identity · workflow status/milestones · intake · claims ·
 * sessions · baselines and environmental measurements · evidence references ·
 * notes · per-room summaries · a print-ready report preview.
 *
 * Claims are shown through the C6B read-only Claims Viewer (original
 * HauntedClaimsListView / CaseInvestigationSummaryView claim presentation).
 * The viewer never writes a claim or promotes one to evidence, an observation
 * or a conclusion. The WEB-017 preview only reproduces existing records; it
 * generates no finding, confidence score or paranormal conclusion.
 */
import "./casehub.css";
import { getDb } from "../../core/db";
import { CaseRepository } from "../../core/repositories/caseRepository";
import { ClientRepository, LocationRepository } from "../../core/repositories/investigationRepositories";
import { EvidenceRepository } from "../../core/repositories/evidenceRepository";
import { ClaimRepository } from "../../core/repositories/claimsRepository";
import {
  WorkflowService,
  WorkflowReadinessService,
  ChecklistService,
} from "../../core/workflow/workflowService";
import { SessionService } from "../../core/session/sessionService";
import { INTAKE_SECTIONS, questionById } from "../../core/intake/questions";
import type {
  BaselineRecord,
  EnvironmentMeasurementRecord,
  EvidenceRecord,
  ObservationRecord,
  WalkthroughObservationRecord,
} from "../../core/types";
import { esc, viewShell } from "../dashboard/shell";
import { invalidateView, mountView, onDelegate } from "../../shared/uidom";
import { renderCaseHub } from "./CaseHub";
import { claimsViewerHtml, wireClaimsViewer } from "./ClaimsViewer";
import { buildCaseReport } from "../../core/reporting/caseReport";
import { CaseReportRepository } from "../../core/reporting/reportRepository";
import { ReportFinalizationService } from "../../core/reporting/reportFinalizationService";
import { CaseClosureService } from "../../core/reporting/caseClosureService";
import {
  reportDraftWorkspaceHtml,
  selectedTypeFor,
  wireReportDraftWorkspace,
} from "./ReportDraft";
import { caseReportHtml, wireCaseReport } from "./CaseReport";
import { caseClosureHtml, wireCaseClosure } from "./CaseClosure";

const db = () => getDb();

function fmtTime(ms: number | null | undefined): string {
  return ms ? new Date(ms).toLocaleString() : "—";
}

function fmtDuration(start: number, end: number | null | undefined): string {
  if (!end || end < start) return "—";
  const minutes = Math.round((end - start) / 60_000);
  if (minutes < 60) return `${minutes} min`;
  return `${Math.floor(minutes / 60)} h ${minutes % 60} min`;
}

function fmtAnswer(raw: string): string {
  try {
    const value: unknown = JSON.parse(raw);
    if (Array.isArray(value)) return value.map((v) => String(v)).join(", ");
    if (typeof value === "boolean") return value ? "Yes" : "No";
    if (value && typeof value === "object") return JSON.stringify(value);
    return String(value ?? "");
  } catch {
    return raw;
  }
}

const SOURCE_LABEL: Record<string, string> = {
  "client-statement": "Client statement",
  "investigator-observation": "Investigator observation",
  interpretation: "Interpretation",
};

function facts(rows: Array<[string, string]>): string {
  return `<div class="cc-native-facts">${rows
    .map(([label, value]) => `<div class="cc-native-fact"><strong>${esc(label)}</strong>${value}</div>`)
    .join("")}</div>`;
}

function card(id: string, title: string, body: string): string {
  return `<section class="cc-native-card" data-summary-section="${esc(id)}"><h3>${esc(title)}</h3>${body}</section>`;
}

function empty(id: string, text: string): string {
  return `<p class="cc-meta" data-summary-empty="${esc(id)}">${esc(text)}</p>`;
}

function baselineState(record: BaselineRecord): "complete" | "inProgress" | "notStarted" {
  if (
    record.baselineStart &&
    record.baselineEnd &&
    record.baselineSummary.trim() &&
    record.baselineMarkedComplete &&
    record.driftChecked &&
    !record.driftDetected
  ) {
    return "complete";
  }
  if (record.baselineStart || record.baselineEnd || record.baselineSummary.trim()) return "inProgress";
  return "notStarted";
}

const BASELINE_LABEL = {
  complete: "Complete",
  inProgress: "In progress",
  notStarted: "Not started",
} as const;

/** Original features with no browser data model/engine — stated, never faked. */
const UNAVAILABLE: ReadonlyArray<[string, string]> = [
  [
    "Summary Readiness Gate (claims / AI script)",
    "The original claims-and-AI readiness gate is not ported. Workflow readiness and the real checklist are shown instead.",
  ],
  [
    "Native report-file generation (PDF/DOCX/TXT/Markdown)",
    "The browser provides a read-only report preview, browser print/save-as-PDF and a case-scoped evidence manifest. Direct native file generation is not implemented; no placeholder file is produced.",
  ],
  [
    "Evidence Intelligence Summary",
    "The iOS evidence-intelligence engine is not ported. Evidence counts and review statuses are shown without a classification.",
  ],
  [
    "AI Interaction Notes",
    "No AI interaction records are stored in this browser build.",
  ],
  [
    "Case package (.ppcase) export",
    "The original capsule requires a persisted report/closure model and a versioned package writer. The design is documented, but no incompatible package is generated in this build.",
  ],
];

export async function renderInvestigationSummary(container: HTMLElement, caseId: string): Promise<void> {
  if (!caseId) {
    renderMissing(container);
    return;
  }
  const record = await new CaseRepository(db()).getCase(caseId);
  if (!record) {
    // Never substitute another case (Stage C1 §2 contract).
    renderMissing(container);
    return;
  }

  const structure = await db().propertyStructures.where("caseId").equals(record.id).first();
  const [
    client,
    location,
    evaluation,
    items,
    rooms,
    floors,
    baselines,
    measurements,
    sessions,
    evidence,
    dossier,
    responses,
    walkthroughSessions,
    walkthroughObservations,
    observations,
    claims,
  ] = await Promise.all([
    record.clientId ? new ClientRepository(db()).get(record.clientId) : Promise.resolve(undefined),
    record.locationId ? new LocationRepository(db()).get(record.locationId) : Promise.resolve(undefined),
    new WorkflowReadinessService(db()).evaluate(record.id),
    new ChecklistService(db()).listForCase(record.id),
    db().structureRooms.where("caseId").equals(record.id).toArray(),
    structure ? db().structureFloors.where("structureId").equals(structure.id).toArray() : Promise.resolve([]),
    db().baselineRecords.where("caseId").equals(record.id).toArray(),
    db().environmentMeasurements.where("caseId").equals(record.id).toArray(),
    new SessionService(db()).listSessions(record.id),
    new EvidenceRepository(db()).listForCase(record.id, 250),
    db().intakeDossiers.where("caseId").equals(record.id).first(),
    db().intakeResponses.where("caseId").equals(record.id).toArray(),
    db().walkthroughSessions.where("caseId").equals(record.id).toArray(),
    db().walkthroughObservations.where("caseId").equals(record.id).toArray(),
    db().observations.where("caseId").equals(record.id).toArray(),
    new ClaimRepository(db()).listForCase(record.id),
  ]);

  const reportRepository = new CaseReportRepository(db());
  const finalizationService = new ReportFinalizationService(db());
  const closureService = new CaseClosureService(db());
  const [caseReport, reportRows, closureState] = await Promise.all([
    buildCaseReport(db(), record.id),
    reportRepository.listForCaseWithRevisions(record.id),
    closureService.state(record.id),
  ]);
  const reports = reportRows.map((row) => row.report);
  const revisionsByReport = Object.fromEntries(
    reportRows.map((row) => [row.report.id, row.revisions]),
  );
  const selectedReportType = selectedTypeFor(container, record.id);

  // Resolve only the locations actually referenced by this case's claims. A
  // missing record stays unresolved; it is never replaced with another case's
  // location or with the case location.
  const claimLocationNames = new Map<string, string>();
  const claimLocationRepo = new LocationRepository(db());
  await Promise.all(
    [...new Set(claims.map((claim) => claim.locationId).filter((id): id is string => id !== null))].map(
      async (id) => {
        const claimLocation = await claimLocationRepo.get(id);
        if (claimLocation) claimLocationNames.set(id, claimLocation.name);
      },
    ),
  );

  if (!evaluation) {
    renderMissing(container);
    return;
  }
  const stage = new WorkflowService(db()).lifecycleStage(record);
  const activeRooms = rooms.filter((room) => !room.archived).sort((a, b) => a.orderIndex - b.orderIndex);
  const completed = items.filter((item) => item.status === "complete" || item.status === "notApplicable");
  const pending = items.filter((item) => item.status === "pending");
  const exceptions = items.filter((item) => item.status === "exception");
  const baselineComplete = activeRooms.filter((room) => {
    const baseline = baselines.find((item) => item.roomId === room.id);
    return baseline ? baselineState(baseline) === "complete" : false;
  }).length;
  const latestSession = [...sessions].sort((a, b) => b.startedAt - a.startedAt)[0];
  const activeSession = sessions.find((session) => session.status === "active" || session.status === "paused");
  const completedWalkthroughs = walkthroughSessions.filter((session) => session.status === "completed").length;
  const answered = responses.filter((response) => response.status === "answered");
  const originals = evidence.filter((item) => item.kind === "original");
  const verified = originals.filter((item) => item.verificationStatus === "verified").length;
  const flagged = evidence.filter((item) => item.reviewStatus === "flagged").length;
  const problemEvidence = originals.filter(
    (item) => item.verificationStatus === "missing" || item.verificationStatus === "corrupted" || item.verificationStatus === "verificationFailed",
  ).length;

  const address = [record.street || location?.street, record.city || location?.city, record.state || location?.state, record.zip]
    .filter((part) => part?.trim())
    .join(", ");
  const roomName = (roomId: string | null | undefined): string =>
    activeRooms.find((room) => room.id === roomId)?.name ?? rooms.find((room) => room.id === roomId)?.name ?? "Room record missing";

  const identity = card(
    "identity",
    "Case Identity",
    facts([
      ["Case number", esc(record.caseNumber)],
      ["Title", esc(record.title)],
      ["Status", esc(record.status)],
      ["Investigation type", esc(record.investigationType)],
      ["Current phase", esc(record.currentPhase)],
      ["Created", esc(fmtTime(record.createdAt))],
      ["Last updated", esc(fmtTime(record.updatedAt))],
      ["Client", esc(client?.fullName ?? record.clientName ?? "Not recorded")],
      ["Location", esc(location?.name ?? "Not recorded")],
      ["Address", esc(address || "Not recorded")],
      ["Structure", esc(structure ? `${structure.name} (${structure.kind})` : "Not recorded")],
      ["Floors / rooms", `${floors.length} / ${activeRooms.length}`],
    ]) +
      (record.notes?.trim()
        ? `<p class="cc-meta summary-copy" data-summary-case-notes>${esc(record.notes.trim())}</p>`
        : empty("case-notes", "No case notes recorded.")),
  );

  const status = card(
    "status",
    "Investigation Status",
    facts([
      ["Lifecycle stage", esc(stage)],
      ["Workflow readiness", esc(evaluation.state)],
      ["Required checklist", `${evaluation.progress.checklistPercent}% complete · ${evaluation.progress.outstandingRequiredCount} outstanding`],
      ["Blockers", String(evaluation.progress.blockerCount)],
      ["Baseline", activeRooms.length ? `${baselineComplete} of ${activeRooms.length} rooms complete` : "No rooms defined"],
      ["Walkthroughs", `${completedWalkthroughs} completed`],
      ["Current session", activeSession ? esc(`${activeSession.status} since ${fmtTime(activeSession.startedAt)}`) : "No active session"],
      ["Latest session", latestSession ? esc(`${latestSession.status} — ${fmtTime(latestSession.startedAt)}`) : "Not recorded"],
      ["Sessions recorded", String(sessions.length)],
      ["Evidence references", String(evidence.length)],
    ]) +
      `<div class="meter" role="meter" aria-valuenow="${evaluation.progress.checklistPercent}" aria-valuemin="0" aria-valuemax="100" aria-label="Required checklist completion"><div class="fill" style="width:${evaluation.progress.checklistPercent}%"></div></div>
       <p class="cc-meta">Readiness and progress come from the authoritative workflow service. This summary does not advance, complete or finalize anything.</p>`,
  );

  const milestones = card(
    "milestones",
    "Workflow Milestones",
    `<p class="cc-count" data-summary-milestones-count>${completed.length} record(s) complete · ${pending.length} pending · ${exceptions.length} documented exception(s)</p>
     ${completed.length
       ? `<ul class="summary-list" data-summary-completed>${completed
           .map(
             (item) =>
               `<li data-summary-completed-item><span class="summary-head"><span class="status-badge">complete</span><strong>${esc(item.title)}</strong></span>
                 <p class="cc-meta">${esc(item.phase)} · ${item.required ? "required" : "optional"}${item.completedAt ? ` · ${esc(fmtTime(item.completedAt))}` : ""}${item.notes.trim() ? ` · ${esc(item.notes)}` : ""}</p></li>`,
           )
           .join("")}</ul>`
       : empty("milestones-complete", "No checklist milestones are recorded complete.")}
     ${pending.length
       ? `<details class="cc-readiness-details"><summary>Pending work (${pending.length})</summary><ul class="summary-list" data-summary-pending>${pending
           .map(
             (item) =>
               `<li data-summary-pending-item><span class="summary-head"><span class="status-badge pending">pending</span><strong>${esc(item.title)}</strong></span>
                 <p class="cc-meta">${esc(item.phase)} · ${item.required ? "required" : "optional"}</p></li>`,
           )
           .join("")}</ul></details>`
       : `<p class="cc-meta">No pending checklist work.</p>`}
     ${exceptions.length
       ? `<details class="cc-readiness-details"><summary>Documented exceptions (${exceptions.length})</summary><ul class="summary-list" data-summary-exceptions>${exceptions
           .map((item) => `<li><strong>${esc(item.title)}</strong><p class="cc-meta">${esc(item.notes || "Exception recorded without notes.")}</p></li>`)
           .join("")}</ul></details>`
       : ""}`,
  );

  const intake = card(
    "intake",
    "Intake",
    dossier
      ? `${facts([
          ["Dossier status", esc(dossier.status)],
          ["Finalized", dossier.finalizedAt ? esc(fmtTime(dossier.finalizedAt)) : "Not recorded"],
          ["Answered questions", `${answered.length} recorded`],
          ["Walkthrough preparation", ""],
        ])}`
        + `<ul class="summary-flags" data-summary-intake-flags>${[
          ["Rooms visited", dossier.walkthrough?.roomsVisited],
          ["Sub-locations pinned", dossier.walkthrough?.subLocationsPinned],
          ["Witness statements", dossier.walkthrough?.witnessStatementsCaptured],
          ["Environmental notes", dossier.walkthrough?.environmentalNotesEntered],
          ["Additional claims checked", dossier.walkthrough?.additionalClaimsChecked],
        ]
          .map(([label, value]) => `<li>${value ? "✓" : "—"} ${esc(String(label))}</li>`)
          .join("")}</ul>`
        + (dossier.investigatorNotes.trim()
          ? `<p class="cc-meta summary-copy" data-summary-intake-notes>${esc(dossier.investigatorNotes.trim())}</p>`
          : empty("intake-notes", "No intake investigator notes recorded."))
        + (answered.length
          ? `<details class="cc-readiness-details"><summary>Recorded intake answers (${answered.length})</summary>
               <p class="cc-meta">Client statements are reproduced as statements, not verified facts.</p>
               <ul class="summary-list" data-summary-intake-answers>${answered
                 .slice(0, 25)
                 .map((response) => {
                   const question = questionById(response.questionId.split("#")[0] ?? response.questionId);
                   const section = INTAKE_SECTIONS.find((entry) => entry.id === question?.section);
                   return `<li data-summary-intake-answer><strong>${esc(question?.prompt ?? response.questionId)}</strong>
                     <p class="cc-meta">${esc(fmtAnswer(response.value))}</p>
                     <p class="cc-meta">${esc(section?.label ?? "Intake")} · ${esc(SOURCE_LABEL[response.source] ?? response.source)}</p></li>`;
                 })
                 .join("")}</ul>
               ${answered.length > 25 ? `<p class="cc-meta">Only the first 25 answers are shown; all ${answered.length} remain in Guided Intake.</p>` : ""}
             </details>`
          : empty("intake-answers", "No intake answers are recorded."))
      : empty("intake", "No intake record has been started for this case."),
  );

  const sessionBody = sessions.length
    ? `<ul class="summary-list" data-summary-sessions>${[...sessions]
        .sort((a, b) => b.startedAt - a.startedAt)
        .map(
          (session) =>
            `<li data-summary-session="${esc(session.id)}">
               <span class="summary-head"><span class="status-badge">${esc(session.status)}</span><strong>${esc(fmtTime(session.startedAt))}</strong></span>
               <p class="cc-meta">Ended: ${esc(fmtTime(session.endedAt))} · Duration: ${esc(fmtDuration(session.startedAt, session.endedAt))}${session.interrupted ? " · interrupted (recovered)" : ""}</p>
               <p class="cc-meta">Investigators: ${esc(session.investigators.length ? session.investigators.join(", ") : "Not recorded")} · Room: ${esc(session.currentRoomId ? roomName(session.currentRoomId) : "Not recorded")}</p>
               ${session.notes?.trim() ? `<p class="cc-meta summary-copy">${esc(session.notes.trim())}</p>` : ""}
             </li>`,
        )
        .join("")}</ul>`
    : empty("sessions", "No investigation sessions recorded. Session controls remain in the Case Hub.");

  const baselineRows = activeRooms.length
    ? activeRooms
        .map((room) => {
          const baseline = baselines.find((item) => item.roomId === room.id);
          const state = baseline ? baselineState(baseline) : "notStarted";
          return `<li data-summary-baseline="${esc(room.id)}" data-baseline-state="${state}">
            <span class="summary-head"><span class="status-badge${state === "complete" ? "" : " pending"}">${esc(BASELINE_LABEL[state])}</span><strong>${esc(room.name)}</strong></span>
            <p class="cc-meta">Start: ${esc(fmtTime(baseline?.baselineStart))} · End: ${esc(fmtTime(baseline?.baselineEnd))} · Drift: ${baseline ? (baseline.driftChecked ? (baseline.driftDetected ? "detected" : "checked, stable") : "not checked") : "Not recorded"}</p>
            <p class="cc-meta">Baseline summary: ${baseline?.baselineSummary.trim() ? "Saved" : "Missing"}${baseline?.notes.trim() ? ` · Notes: ${esc(baseline.notes.trim())}` : ""}</p>
            ${baseline?.baselineSummary.trim() ? `<p class="cc-meta summary-copy">${esc(baseline.baselineSummary.trim())}</p>` : ""}
          </li>`;
        })
        .join("")
    : empty("baselines", "No property structure or rooms defined; baseline status cannot be determined.");

  const measurementGroups = new Map<string, EnvironmentMeasurementRecord[]>();
  for (const measurement of measurements) {
    const group = measurementGroups.get(measurement.measurementType) ?? [];
    group.push(measurement);
    measurementGroups.set(measurement.measurementType, group);
  }
  const measurementBody = measurements.length
    ? `<ul class="summary-list" data-summary-measurements>${[...measurementGroups.entries()]
        .sort(([a], [b]) => a.localeCompare(b))
        .map(([type, group]) => {
          const latest = [...group].sort((a, b) => b.at - a.at)[0]!;
          return `<li data-summary-measurement="${esc(type)}">
            <span class="summary-head"><strong>${esc(type)}</strong><span class="status-badge">${group.length} reading(s)</span></span>
            <p class="cc-meta">Latest: ${esc(latest.value !== null ? `${latest.value}${latest.unit ? ` ${latest.unit}` : ""}` : latest.text || "No value recorded")} · ${esc(fmtTime(latest.at))}</p>
            <p class="cc-meta">${esc(latest.acquisition)}${latest.instrument ? ` · ${esc(latest.instrument)}` : ""}${latest.calibration !== "unknown" ? ` · calibration ${esc(latest.calibration)}` : ""}</p>
          </li>`;
        })
        .join("")}</ul>`
    : empty("measurements", "No environmental readings recorded.");

  const environment = card(
    "environment",
    "Environmental Readings",
    `<p class="cc-count">${baselineComplete} of ${activeRooms.length} room baseline(s) complete · ${measurements.length} measurement(s) recorded</p>
     ${baselineRows}
     <h4 class="cc-section-title" style="margin-top:14px">Recorded measurements</h4>
     ${measurementBody}`,
  );

  const evidenceBody = evidence.length
    ? `<p class="cc-count">${evidence.length} reference(s) · ${originals.length} original · ${verified} verified · ${flagged} flagged review · ${problemEvidence} integrity problem(s)</p>
       <ul class="summary-list" data-summary-evidence>${evidence
         .slice(0, 12)
         .map(
           (item: EvidenceRecord) =>
             `<li data-summary-evidence-item="${esc(item.id)}">
                <span class="summary-head"><strong>${esc(item.title)}</strong><span class="status-badge">${esc(item.mediaType)}</span></span>
                <p class="cc-meta">${esc(item.kind)} · review: ${esc(item.reviewStatus)} · integrity: ${esc(item.verificationStatus ?? "unverified")}</p>
                <p class="cc-meta">Acquired: ${esc(fmtTime(item.acquiredAt))}${item.notes?.trim() ? ` · ${esc(item.notes.trim())}` : ""}</p>
              </li>`,
         )
         .join("")}</ul>
       ${evidence.length > 12 ? `<p class="cc-meta">Only 12 of ${evidence.length} references are listed; the complete set remains in the Evidence Library.</p>` : ""}
       <p class="cc-meta">These are references to persisted evidence records only. Files, hashes and review actions are handled in the Evidence Library.</p>`
    : empty("evidence", "No evidence imported for this case.");

  const notes: Array<{ id: string; source: string; title: string; body: string; meta: string }> = [];
  for (const observation of walkthroughObservations as WalkthroughObservationRecord[]) {
    notes.push({
      id: observation.id,
      source: "Walkthrough",
      title: observation.areaLabel || (observation.roomId ? roomName(observation.roomId) : "Area not recorded"),
      body: observation.description,
      meta: `${observation.kind}${observation.instrument ? ` · ${observation.instrument}` : ""} · ${fmtTime(observation.createdAt)}${observation.amended ? " · amended" : ""}`,
    });
  }
  for (const observation of observations as ObservationRecord[]) {
    notes.push({
      id: observation.id,
      source: observation.entryType === "interpretation" ? "Interpretation" : "Observation",
      title: observation.title?.trim() || observation.roomName,
      body: observation.body,
      meta: `${observation.roomName} · ${fmtTime(observation.createdAt)}`,
    });
  }
  const notesBody = notes.length
    ? `<ul class="summary-list" data-summary-notes>${notes
        .sort((a, b) => a.source.localeCompare(b.source))
        .slice(0, 16)
        .map(
          (note) =>
            `<li data-summary-note="${esc(note.id)}">
               <span class="summary-head"><span class="status-badge">${esc(note.source)}</span><strong>${esc(note.title)}</strong></span>
               <p class="cc-meta summary-copy">${esc(note.body)}</p>
               <p class="cc-meta">${esc(note.meta)}</p>
             </li>`,
        )
        .join("")}</ul>
       ${notes.length > 16 ? `<p class="cc-meta">Only 16 of ${notes.length} notes are shown.</p>` : ""}
       <p class="cc-meta">Reported, observed, measured and interpreted entries keep their original classification. No interpretation is added here.</p>`
    : empty("notes", "No investigation notes recorded in walkthrough or session records.");

  const unavailable = card(
    "unavailable",
    "Original Features Not Available in This Build",
    `<p class="cc-meta">The following original Investigation Summary capabilities have no browser implementation. They are listed so missing work is explicit; nothing below is simulated.</p>
     <ul class="summary-list" data-summary-unavailable>${UNAVAILABLE.map(
       ([title, reason]) => `<li><strong>${esc(title)}</strong><p class="cc-meta">${esc(reason)}</p></li>`,
     ).join("")}</ul>`,
  );

  invalidateView(container);
  mountView(
    container,
    viewShell(
      `Investigation Summary — ${record.caseNumber}`,
      `<div class="case-form" data-root="investigation-summary" data-case-id="${esc(record.id)}" data-epoch="${Date.now()}-${Math.random()}">
        <div class="form-actions">
          <button class="back-button" id="summary-back" type="button">← Back to Case Hub</button>
        </div>
        <p class="cc-count" data-summary-readonly="true">Read-only summary and report preview. The persisted report workspace below supports explicit draft saves, investigator-controlled finalization, amendments and case closure. No conclusion about paranormal activity is generated; missing or unavailable information is labelled as such.</p>
        ${identity}
        ${status}
        ${milestones}
        ${intake}
        ${card("claims", "Claims", claimsViewerHtml({
          claims,
          rooms,
          locationNames: claimLocationNames,
          caseLocationName: location?.name ?? null,
        }))}
        ${card("sessions", "Investigation Sessions", sessionBody)}
        ${environment}
        ${card("evidence", "Evidence References", evidenceBody)}
        ${card("notes", "Investigation Notes", notesBody)}
        ${caseReport
          ? reportDraftWorkspaceHtml(reports, caseReport, selectedReportType, revisionsByReport, {
              readinessState: evaluation.state,
              readinessBlockers: evaluation.blockers.length,
            })
          : ""}
        ${caseReport ? caseClosureHtml(closureState, reports, revisionsByReport) : ""}
        ${caseReport ? caseReportHtml(caseReport) : card("report", "Case Report", empty("report", "The case report could not be assembled from persisted records."))}
        ${unavailable}
      </div>`,
    ),
  );

  onDelegate(container, "click", "#summary-back", () => {
    void renderCaseHub(container, caseId);
  });
  wireClaimsViewer(container);
  if (caseReport) {
    wireCaseReport(container, caseReport);
    wireReportDraftWorkspace(container, {
      caseId: record.id,
      model: caseReport,
      repository: reportRepository,
      finalization: finalizationService,
      rerender: () => renderInvestigationSummary(container, record.id),
    });
    wireCaseClosure(container, {
      caseId: record.id,
      service: closureService,
      rerender: () => renderInvestigationSummary(container, record.id),
    });
  }
}

function renderMissing(container: HTMLElement): void {
  invalidateView(container);
  mountView(
    container,
    viewShell(
      "Investigation Summary",
      `<div class="cc-empty" data-summary-missing="true">
        <p><strong>Case not found.</strong> This case does not exist or is no longer available.</p>
        <p class="cc-meta">No other case was opened. Choose a case from Case Files to continue.</p>
        <button class="button-primary" id="summary-missing-back" type="button">Back to Case Files</button>
      </div>`,
    ),
  );
  onDelegate(container, "click", "#summary-missing-back", () => {
    window.location.hash = "/command-center";
  });
}
