/**
 * Evidence Timeline, Evidence Review, and Environmental Comparison views
 * (TPI-V2-WEB-009 §15/§16/§17/§19).
 */
import "./casehub.css";
import { getDb } from "../../core/db";
import { CaseRepository } from "../../core/repositories/caseRepository";
import { EvidenceTimelineService, EnvironmentalComparisonService, type TimelineEntry, type TimelineEntryKind } from "../../core/evidence/timelineAndComparison";
import {
  ANNOTATION_TYPE_LABELS,
  EvidenceAnnotationService,
  EvidenceReviewService,
  REVIEW_STATUS_LABELS,
} from "../../core/evidence/evidenceReviewService";
import type { AnnotationType, EvidenceReviewStatus } from "../../core/types";
import { esc, viewShell, wireBackButton } from "../dashboard/shell";
import { mountView, onDelegate, invalidateView, clearDrafts, setViewNote, viewNote } from "../../shared/uidom";
import { InvestigationCompletionService } from "../../core/workflow/investigationCompletionService";
import { renderCaseHub } from "./CaseHub";

const db = () => getDb();

function fmtTime(ms: number | null | undefined): string {
  return ms ? new Date(ms).toLocaleString() : "—";
}

interface ViewState {
  from: string;
  to: string;
  kinds: TimelineEntryKind[];
  roomId: string;
  sessionId: string;
  selectedEvidenceId: string;
  windowMinutes: number;
}

const states = new Map<string, ViewState>();

function stateOf(container: HTMLElement): ViewState {
  const id = (container.dataset.viewId ??= Math.random().toString(36).slice(2));
  let s = states.get(id);
  if (!s) {
    s = { from: "", to: "", kinds: [], roomId: "", sessionId: "", selectedEvidenceId: "", windowMinutes: 15 };
    states.set(id, s);
  }
  return s;
}

/* ================================ timeline ================================ */

export async function renderEvidenceTimeline(container: HTMLElement, caseId: string): Promise<void> {
  const record = await new CaseRepository(db()).getCase(caseId);
  if (!record) {
    invalidateView(container);
    mountView(container, viewShell("Evidence Timeline", `<div class="cc-empty">Case not found.</div>`));
    wireBackButton(container);
    return;
  }
  const st = stateOf(container);
  const structure = await db().propertyStructures.where("caseId").equals(caseId).first();
  const rooms = structure ? (await db().structureRooms.where("structureId").equals(structure.id).toArray()).filter((r) => !r.archived) : [];
  const sessions = await db().sessions.where("caseId").equals(caseId).toArray();

  const entries = await new EvidenceTimelineService(db()).build(caseId, {
    from: st.from ? new Date(st.from).getTime() : undefined,
    to: st.to ? new Date(st.to).getTime() + 86_399_000 : undefined,
    kinds: st.kinds.length ? st.kinds : undefined,
    roomId: st.roomId || undefined,
    sessionId: st.sessionId || undefined,
  });

  const kinds: TimelineEntryKind[] = ["evidenceCapture", "evidenceImport", "sessionEvent", "measurement", "observation", "review", "annotation"];

  invalidateView(container);
  mountView(
    container,
    viewShell(
      `Evidence Timeline — ${record.caseNumber}`,
      `
      <div class="case-form" data-root="evidence-timeline" data-case-id="${esc(caseId)}" data-epoch="${Date.now()}-${Math.random()}">
        <p class="cc-count">${entries.length} timeline entr${entries.length === 1 ? "y" : "ies"} in chronological order.</p>
        <div class="case-form">
          <div class="detail-grid">
            <div class="detail-field"><label for="tl-from">From date</label><input id="tl-from" type="date" value="${esc(st.from)}"></div>
            <div class="detail-field"><label for="tl-to">To date</label><input id="tl-to" type="date" value="${esc(st.to)}"></div>
            <div class="detail-field"><label for="tl-room">Room</label>
              <select id="tl-room"><option value="">All rooms</option>${rooms.map((r) => `<option value="${r.id}"${st.roomId === r.id ? " selected" : ""}>${esc(r.name)}</option>`).join("")}</select></div>
            <div class="detail-field"><label for="tl-session">Session</label>
              <select id="tl-session"><option value="">All sessions</option>${sessions.map((s) => `<option value="${s.id}"${st.sessionId === s.id ? " selected" : ""}>${esc(s.status)} — ${fmtTime(s.startedAt)}</option>`).join("")}</select></div>
          </div>
          <fieldset class="baseline-fieldset"><legend>Entry types</legend>
            ${kinds.map((k) => `<label><input type="checkbox" data-tl-kind="${k}" ${st.kinds.includes(k) ? "checked" : ""}> ${esc(k)}</label>`).join("")}
          </fieldset>
          <div class="form-actions"><button class="button-secondary" id="tl-apply" type="button">Apply Filters</button></div>
        </div>

        ${
          entries.length === 0
            ? '<div class="cc-empty">No timeline entries match these filters.</div>'
            : `<ul class="activity-list">${entries
                .map(
                  (e: TimelineEntry) => `
          <li>
            <span class="when">${fmtTime(e.at)} • ${esc(e.kind)} • timestamp: ${esc(e.timestampSource)}</span>
            <div class="what"><strong>${esc(e.title)}</strong></div>
            <div class="case-meta">${esc(e.detail)}</div>
          </li>`,
                )
                .join("")}</ul>`
        }
        <p class="cc-meta">Timestamps are shown with their source (capture, import, investigator-entered, or file metadata). Unknown times are never invented; where a capture time is unknown the acquisition time is used and labelled accordingly.</p>

        <div class="form-actions"><button class="back-button" id="tl-back" type="button">← Back to Case Hub</button></div>
      </div>
    `,
  ));

  onDelegate(container, "click", "#tl-back", () => void renderCaseHub(container.closest<HTMLElement>(".cc-view")?.parentElement ?? container, caseId));
  onDelegate(container, "click", "#tl-apply", async () => {
    const s = stateOf(container);
    s.from = container.querySelector<HTMLInputElement>("#tl-from")?.value ?? "";
    s.to = container.querySelector<HTMLInputElement>("#tl-to")?.value ?? "";
    s.roomId = container.querySelector<HTMLSelectElement>("#tl-room")?.value ?? "";
    s.sessionId = container.querySelector<HTMLSelectElement>("#tl-session")?.value ?? "";
    s.kinds = Array.from(container.querySelectorAll<HTMLInputElement>("[data-tl-kind]:checked")).map(
      (el) => el.dataset.tlKind as TimelineEntryKind,
    );
    await renderEvidenceTimeline(container, caseId);
  });
  wireBackButton(container);
}

/* ================================= review ================================= */

export async function renderEvidenceReview(container: HTMLElement, caseId: string): Promise<void> {
  const record = await new CaseRepository(db()).getCase(caseId);
  if (!record) {
    invalidateView(container);
    mountView(container, viewShell("Evidence Review", `<div class="cc-empty">Case not found.</div>`));
    wireBackButton(container);
    return;
  }
  const investigationCompletion = await new InvestigationCompletionService(db()).getCompletion(caseId);
  if (!investigationCompletion) {
    invalidateView(container);
    mountView(
      container,
      viewShell(
        `Evidence Review — ${record.caseNumber}`,
        `
        <div class="case-form" data-root="evidence-review-locked" data-case-id="${esc(caseId)}" data-investigation-completed="false">
          <h3 class="cc-section-title">Evidence Review Locked</h3>
          <p class="cc-count">Investigation completion has not been recorded for this case.</p>
          <p class="cc-meta">Evidence Review unlocks after an explicit <strong>Complete Investigation</strong> action. Ending a session alone does not complete the investigation.</p>
          <p class="cc-meta">Use the Case Hub Session Controls or the Investigation Session screen to end any active session and record completion. Existing evidence and review records are preserved by this lock.</p>
          <div class="form-actions"><button class="back-button" id="rv-locked-back" type="button">← Back to Case Hub</button></div>
        </div>
      `,
      ),
    );
    onDelegate(container, "click", "#rv-locked-back", () => void renderCaseHub(container.closest<HTMLElement>(".cc-view")?.parentElement ?? container, caseId));
    wireBackButton(container);
    return;
  }
  const reviewService = new EvidenceReviewService(db());
  const annotationService = new EvidenceAnnotationService(db());
  const evidence = (await db().evidence.where("caseId").equals(caseId).toArray()).filter((e) => e.kind === "original");
  const st = stateOf(container);
  if (!st.selectedEvidenceId && evidence.length > 0) st.selectedEvidenceId = evidence[0]!.id;
  const selected = evidence.find((e) => e.id === st.selectedEvidenceId);
  const blockers = await reviewService.evaluateCaseEvidence(caseId);
  const reviews = selected ? await reviewService.listForEvidence(selected.id) : [];
  const annotations = selected ? await annotationService.listForEvidence(selected.id, true) : [];

  invalidateView(container);
  mountView(
    container,
    viewShell(
      `Evidence Review — ${record.caseNumber}`,
      `
      <div class="case-form" data-root="evidence-review" data-case-id="${esc(caseId)}" data-epoch="${Date.now()}-${Math.random()}">
        <p class="cc-count">${evidence.length} original item(s) • ${blockers.length === 0 ? "review requirements satisfied" : `${blockers.length} outstanding review item(s)`}</p>
        <p class="cc-meta">Review records an investigator assessment. It never forces a paranormal or non-paranormal conclusion, and an unexplained recording is not proof of paranormal activity.</p>

        <h3 class="cc-section-title">Evidence Items</h3>
        ${evidence.length === 0
          ? '<div class="cc-empty">No evidence imported. A case may legitimately have no evidence — import is not required to be truthful.</div>'
          : evidence
              .map((e) => {
                const latest = reviewsFileStatus(e.reviewStatus);
                return `
          <div class="case-row" data-review-item="${e.id}">
            <div>
              <div class="case-title">${e.id === st.selectedEvidenceId ? "▸ " : ""}${esc(e.title)}</div>
              <div class="case-meta">${esc(e.mediaType)} • review: ${esc(latest)} • integrity: ${esc(e.verificationStatus ?? "unverified")}</div>
            </div>
            <button class="back-button" data-select-evidence="${e.id}" type="button">Open</button>
          </div>`;
              })
              .join("")}

        ${
          selected
            ? `
        <h3 class="cc-section-title">Review — ${esc(selected.title)}</h3>
        <div class="case-form" data-review-form="${selected.id}">
          <div class="detail-grid">
            <div class="detail-field"><label for="rv-status">Review status</label>
              <select id="rv-status">
                ${(Object.keys(REVIEW_STATUS_LABELS) as EvidenceReviewStatus[]).map((s) => `<option value="${s}">${esc(REVIEW_STATUS_LABELS[s])}</option>`).join("")}
              </select></div>
            <div class="detail-field"><label for="rv-reviewer">Reviewer</label><input id="rv-reviewer" type="text" placeholder="Investigator name"></div>
          </div>
          <div class="detail-field"><label for="rv-notes">Assessment notes (required to mark Reviewed)</label>
            <textarea id="rv-notes" rows="2" placeholder="What was examined and what did you conclude about the recording itself"></textarea></div>
          <div class="detail-field"><label for="rv-observations">Observations (what is directly present in the recording)</label>
            <textarea id="rv-observations" rows="2"></textarea></div>
          <div class="detail-field"><label for="rv-natural">Possible natural explanations considered</label>
            <textarea id="rv-natural" rows="2" placeholder="e.g. building settling, HVAC cycling, traffic, plumbing"></textarea></div>
          <div class="detail-field"><label for="rv-followup">Follow-up recommendation (required for Needs Follow-Up)</label>
            <textarea id="rv-followup" rows="2"></textarea></div>
          <div class="form-actions"><button class="button-primary" id="save-review" type="button">Save Review</button></div>
          <p class="cc-meta" id="review-status" role="status">${esc(viewNote(container, "review"))}</p>
        </div>

        <h3 class="cc-section-title">Annotations (${annotations.length})</h3>
        <div class="case-form" id="annotation-form">
          <div class="detail-grid">
            <div class="detail-field"><label for="an-type">Annotation type</label>
              <select id="an-type">${(Object.keys(ANNOTATION_TYPE_LABELS) as AnnotationType[]).map((t) => `<option value="${t}">${esc(ANNOTATION_TYPE_LABELS[t])}</option>`).join("")}</select></div>
            <div class="detail-field"><label for="an-author">Author</label><input id="an-author" type="text" placeholder="Investigator name"></div>
            <div class="detail-field"><label for="an-start">Start (seconds, A/V)</label><input id="an-start" type="number" step="0.1" min="0"></div>
            <div class="detail-field"><label for="an-end">End (seconds, A/V)</label><input id="an-end" type="number" step="0.1" min="0"></div>
            <div class="detail-field"><label for="an-section">Document section reference</label><input id="an-section" type="text" placeholder="e.g. page 2, paragraph 3"></div>
          </div>
          <fieldset class="baseline-fieldset"><legend>Image region (normalized 0–1)</legend>
            <label>X <input id="an-x" type="number" step="0.01" min="0" max="1"></label>
            <label>Y <input id="an-y" type="number" step="0.01" min="0" max="1"></label>
            <label>Width <input id="an-w" type="number" step="0.01" min="0" max="1"></label>
            <label>Height <input id="an-h" type="number" step="0.01" min="0" max="1"></label>
          </fieldset>
          <div class="detail-field"><label for="an-description">Description</label><textarea id="an-description" rows="2"></textarea></div>
          <div class="form-actions"><button class="button-primary" id="add-annotation" type="button">Add Annotation</button></div>
          <p class="cc-meta">Annotations are investigator metadata. They never modify the original evidence file.</p>
        </div>

        ${annotations.length === 0
          ? '<div class="cc-empty">No annotations.</div>'
          : annotations
              .map(
                (a) => `
          <div class="case-row" data-annotation-row="${a.id}">
            <div>
              <div class="case-title">[${esc(a.annotationType)}] ${esc(a.description)}${a.amended ? " • superseded" : ""} <span class="status-badge">revision ${a.revision}</span></div>
              <div class="case-meta">${esc(a.author)} • ${fmtTime(a.createdAt)}${a.target.startSeconds !== undefined ? ` • ${a.target.startSeconds}s${a.target.endSeconds !== undefined ? `–${a.target.endSeconds}s` : ""}` : ""}${a.target.section ? ` • ${esc(a.target.section)}` : ""}${a.target.x !== undefined ? ` • region ${a.target.x},${a.target.y} ${a.target.width}×${a.target.height}` : ""}</div>
            </div>
            ${a.amended ? "" : `<button class="back-button" data-revise-annotation="${a.id}" type="button">Revise…</button>`}
          </div>`,
              )
              .join("")}

        <h3 class="cc-section-title">Review History (${reviews.length})</h3>
        ${reviews.length === 0
          ? '<div class="cc-empty">No review entries yet.</div>'
          : reviews
              .map(
                (r) => `
          <div class="case-row">
            <div>
              <div class="case-title">${esc(REVIEW_STATUS_LABELS[r.status])} — ${esc(r.reviewer)}</div>
              <div class="case-meta">${fmtTime(r.at)}${r.notes ? ` • ${esc(r.notes)}` : ""}${r.observations ? ` • observations: ${esc(r.observations)}` : ""}${r.naturalExplanations ? ` • natural explanations considered: ${esc(r.naturalExplanations)}` : ""}${r.followUp ? ` • follow-up: ${esc(r.followUp)}` : ""}${r.annotationIds.length ? ` • ${r.annotationIds.length} annotation(s)` : ""}</div>
            </div>
          </div>`,
              )
              .join("")}`
            : ""
        }

        <h3 class="cc-section-title">Outstanding Review Items</h3>
        ${blockers.length === 0
          ? '<div class="cc-empty">No outstanding review items.</div>'
          : blockers
              .map(
                (b) => `
          <div class="case-row" role="alert">
            <div><div class="case-title">${esc(b.reason)}</div><div class="case-meta">required action: ${esc(b.requiredAction)}${b.nonOverridable ? " • <strong>not overridable</strong>" : ""}</div></div>
            <span class="status-badge error">error</span>
          </div>`,
              )
              .join("")}

        <div class="form-actions"><button class="back-button" id="rv-back" type="button">← Back to Case Hub</button></div>
      </div>
    `,
  ));

  onDelegate(container, "click", "#rv-back", () => void renderCaseHub(container.closest<HTMLElement>(".cc-view")?.parentElement ?? container, caseId));
  onDelegate(container, "click", "[data-select-evidence]", async (el) => {
    stateOf(container).selectedEvidenceId = el.dataset.selectEvidence ?? "";
    await renderEvidenceReview(container, caseId);
  });
  onDelegate(container, "click", "#save-review", async () => {
    const id = container.querySelector<HTMLElement>("[data-review-form]")?.dataset.reviewForm ?? "";
    try {
      await reviewService.recordReview(id, {
        status: (container.querySelector<HTMLSelectElement>("#rv-status")?.value ?? "reviewed") as EvidenceReviewStatus,
        reviewer: container.querySelector<HTMLInputElement>("#rv-reviewer")?.value ?? "",
        notes: container.querySelector<HTMLTextAreaElement>("#rv-notes")?.value ?? "",
        observations: container.querySelector<HTMLTextAreaElement>("#rv-observations")?.value ?? "",
        naturalExplanations: container.querySelector<HTMLTextAreaElement>("#rv-natural")?.value ?? "",
        followUp: container.querySelector<HTMLTextAreaElement>("#rv-followup")?.value ?? "",
      });
      clearDrafts(container);
      setViewNote(container, "review", "Review saved.");
      await renderEvidenceReview(container, caseId);
    } catch (err) {
      const message = (err as Error).message;
      setViewNote(container, "review", message);
      const el = container.querySelector<HTMLElement>("#review-status");
      if (el) el.textContent = message;
    }
  });
  onDelegate(container, "click", "#add-annotation", async () => {
    const id = stateOf(container).selectedEvidenceId;
    const type = (container.querySelector<HTMLSelectElement>("#an-type")?.value ?? "note") as AnnotationType;
    const num = (sel: string) => {
      const raw = container.querySelector<HTMLInputElement>(sel)?.value ?? "";
      return raw === "" ? undefined : Number(raw);
    };
    const target =
      type === "audioRange" || type === "videoRange"
        ? { startSeconds: num("#an-start"), endSeconds: num("#an-end") }
        : type === "imageRegion"
          ? { x: num("#an-x"), y: num("#an-y"), width: num("#an-w"), height: num("#an-h") }
          : type === "documentSection"
            ? { section: container.querySelector<HTMLInputElement>("#an-section")?.value ?? "" }
            : {};
    try {
      clearDrafts(container);
      await annotationService.create(id, {
        author: container.querySelector<HTMLInputElement>("#an-author")?.value ?? "",
        annotationType: type,
        target,
        description: container.querySelector<HTMLTextAreaElement>("#an-description")?.value ?? "",
      });
      await renderEvidenceReview(container, caseId);
    } catch (err) {
      const message = (err as Error).message;
      setViewNote(container, "review", message);
      const el = container.querySelector<HTMLElement>("#review-status");
      if (el) el.textContent = message;
    }
  });
  onDelegate(container, "click", "[data-revise-annotation]", async (el) => {
    const id = el.dataset.reviseAnnotation ?? "";
    const description = window.prompt("Revised annotation description:", "");
    if (description === null) return;
    const reason = window.prompt("Document the reason for this revision:", "");
    if (!reason?.trim()) return;
    try {
      await annotationService.revise(id, { description, reason });
      await renderEvidenceReview(container, caseId);
    } catch (err) {
      alert((err as Error).message);
    }
  });
  wireBackButton(container);
}

function reviewsFileStatus(reviewStatus: string): string {
  switch (reviewStatus) {
    case "reviewed": return "reviewed";
    case "flagged": return "needs follow-up";
    default: return "unreviewed";
  }
}

/* ============================== comparison ============================== */

export async function renderEnvironmentalComparison(container: HTMLElement, caseId: string): Promise<void> {
  const record = await new CaseRepository(db()).getCase(caseId);
  if (!record) {
    invalidateView(container);
    mountView(container, viewShell("Environmental Comparison", `<div class="cc-empty">Case not found.</div>`));
    wireBackButton(container);
    return;
  }
  const evidence = (await db().evidence.where("caseId").equals(caseId).toArray()).filter((e) => e.kind === "original");
  const st = stateOf(container);
  if (!st.selectedEvidenceId && evidence.length > 0) st.selectedEvidenceId = evidence[0]!.id;

  const result = st.selectedEvidenceId
    ? await new EnvironmentalComparisonService(db()).compare(st.selectedEvidenceId, {
        windowMinutes: st.windowMinutes,
        includeSessionEvents: true,
        includeObservations: true,
      })
    : null;

  const availabilityLabels: Record<string, string> = {
    nearbyReadingsFound: "Nearby readings found in time",
    sameRoomRecordsFound: "Records found in the same room",
    insufficientData: "Insufficient data",
    noMatchingRecords: "No matching records found",
  };

  invalidateView(container);
  mountView(
    container,
    viewShell(
      `Environmental Comparison — ${record.caseNumber}`,
      `
      <div class="case-form" data-root="environmental-comparison" data-case-id="${esc(caseId)}" data-epoch="${Date.now()}-${Math.random()}">
        <p class="cc-meta">This view lists records that fall within an investigator-chosen time window around an evidence item. <strong>Temporal proximity does not establish causation</strong>, and no statistical correlation is calculated or implied.</p>

        <div class="case-form">
          <div class="detail-grid">
            <div class="detail-field"><label for="cmp-evidence">Evidence item</label>
              <select id="cmp-evidence">
                ${evidence.length === 0 ? '<option value="">— no evidence imported —</option>' : evidence.map((e) => `<option value="${e.id}"${e.id === st.selectedEvidenceId ? " selected" : ""}>${esc(e.title)} (${esc(e.mediaType)})</option>`).join("")}
              </select></div>
            <div class="detail-field"><label for="cmp-window">Time window (± minutes)</label>
              <input id="cmp-window" type="number" min="1" max="1440" value="${st.windowMinutes}"></div>
          </div>
          <div class="form-actions"><button class="button-secondary" id="cmp-apply" type="button">Compare</button></div>
        </div>

        ${
          !result
            ? '<div class="cc-empty">Import evidence to compare it with environmental records.</div>'
            : `
        <div class="case-row" data-comparison-availability="${esc(result.availability)}">
          <div>
            <div class="case-title">${esc(availabilityLabels[result.availability] ?? result.availability)}</div>
            <div class="case-meta">Window: ${fmtTime(result.windowStart)} → ${fmtTime(result.windowEnd)} (±${st.windowMinutes} minutes around the evidence timestamp) • ${result.records.length} matching record(s)</div>
          </div>
          <span class="status-badge">${result.records.length}</span>
        </div>

        ${result.missing.length > 0 ? `<div class="case-form"><h3 class="cc-section-title">Missing Data</h3>${result.missing.map((m) => `<div class="case-row"><div><div class="case-title">${esc(m)}</div></div></div>`).join("")}</div>` : ""}

        <h3 class="cc-section-title">Nearby Records (${result.records.length})</h3>
        ${result.records.length === 0
          ? '<div class="cc-empty">No matching records found in this window.</div>'
          : result.records
              .map(
                (r) => `
          <div class="case-row">
            <div>
              <div class="case-title">[${esc(r.kind)}] ${esc(r.label)}</div>
              <div class="case-meta">${fmtTime(r.at)} • ${esc(r.relation)} • ${esc(r.detail)}</div>
            </div>
          </div>`,
              )
              .join("")}

        <div class="case-form">
          <h3 class="cc-section-title">Reading Notes</h3>
          ${result.notes.map((n) => `<p class="cc-meta">${esc(n)}</p>`).join("")}
        </div>`
        }

        <div class="form-actions"><button class="back-button" id="cmp-back" type="button">← Back to Case Hub</button></div>
      </div>
    `,
  ));

  onDelegate(container, "click", "#cmp-back", () => void renderCaseHub(container.closest<HTMLElement>(".cc-view")?.parentElement ?? container, caseId));
  onDelegate(container, "click", "#cmp-apply", async () => {
    const s = stateOf(container);
    s.selectedEvidenceId = container.querySelector<HTMLSelectElement>("#cmp-evidence")?.value ?? "";
    const windowValue = Number(container.querySelector<HTMLInputElement>("#cmp-window")?.value ?? "15");
    s.windowMinutes = Number.isFinite(windowValue) && windowValue > 0 ? Math.min(1440, windowValue) : 15;
    await renderEnvironmentalComparison(container, caseId);
  });
  wireBackButton(container);
}
