/**
 * Equipment field capture (TPI-V2-WEB-012).
 *
 * The original iPad Equipment hub exposed Camera Capture and Video Recorder as
 * "coming soon" placeholders, while its working walkthrough camera used
 * UIImagePickerController for in-app room photos and videos. This view provides
 * the browser equivalent for the Equipment hub: a genuine getUserMedia +
 * canvas/MediaRecorder flow, case/room/session association, original-byte
 * preservation through the existing OPFS + SHA-256 evidence pipeline, and
 * explicit device/permission limitations.
 *
 * It never fabricates a frame, recording, sensor reading, object detection or
 * paranormal conclusion. Capture and analysis remain separate.
 */
import "../dashboard/dashboard.css";
import { getDb } from "../../core/db";
import { CaseRepository } from "../../core/repositories/caseRepository";
import { EvidenceRepository } from "../../core/repositories/evidenceRepository";
import { AuditService } from "../../core/audit";
import { ValidationError } from "../../core/validation";
import type { CaseRecord, EvidenceRecord, InvestigationSessionRecord } from "../../core/types";
import {
  captureFileName,
  classifyCaptureError,
  formatCaptureDuration,
  photoConstraints,
  pickVideoMimeType,
  silentVideoConstraints,
  stopMediaStream,
  streamHasAudio,
  videoConstraints,
} from "../../core/media/fieldCapture";
import { esc, viewShell } from "../dashboard/shell";
import { invalidateView, mountView, onDelegate } from "../../shared/uidom";

const db = () => getDb();

type CaptureMode = "photo" | "video";

interface LastCapture {
  id: string;
  fileName: string;
  contentHash: string;
  mimeType: string;
  sizeBytes: number;
  durationMs?: number;
  width?: number;
  height?: number;
  audio?: boolean;
  sessionId?: string;
  createdAt: number;
}

interface FieldCaptureState {
  mode: CaptureMode;
  caseId: string | null;
  roomId: string;
  sessionId: string;
  status: string;
  error: string;
  live: boolean;
  recording: boolean;
  recordingStartedAt: number | null;
  last: LastCapture | null;
  lastBlob: Blob | null;
}

const ui = new WeakMap<HTMLElement, FieldCaptureState>();

let activeStream: MediaStream | null = null;
let activeRecorder: MediaRecorder | null = null;
let activeChunks: BlobPart[] = [];
let activeTimer: number | null = null;
let activeContainer: HTMLElement | null = null;
const objectUrls = new Set<string>();

function state(container: HTMLElement, mode: CaptureMode): FieldCaptureState {
  const existing = ui.get(container);
  if (existing?.mode === mode) return existing;
  const created: FieldCaptureState = {
    mode,
    caseId: null,
    roomId: "",
    sessionId: "",
    status: "Ready. Nothing is captured until you explicitly start the camera.",
    error: "",
    live: false,
    recording: false,
    recordingStartedAt: null,
    last: null,
    lastBlob: null,
  };
  ui.set(container, created);
  return created;
}

function revokeObjectUrls(): void {
  for (const url of objectUrls) URL.revokeObjectURL(url);
  objectUrls.clear();
}

function previewUrl(blob: Blob): string {
  const url = URL.createObjectURL(blob);
  objectUrls.add(url);
  return url;
}

/** Release the active camera/recorder and revoke preview URLs. Safe repeatedly. */
export async function releaseFieldCapture(): Promise<void> {
  if (activeTimer !== null) {
    window.clearInterval(activeTimer);
    activeTimer = null;
  }
  if (activeRecorder && activeRecorder.state !== "inactive") {
    try {
      activeRecorder.stop();
    } catch {
      /* already stopping */
    }
  }
  activeRecorder = null;
  activeChunks = [];
  stopMediaStream(activeStream);
  activeStream = null;
  revokeObjectUrls();
  activeContainer = null;
}

function setStatus(container: HTMLElement, s: FieldCaptureState, text: string, error = ""): void {
  s.status = text;
  s.error = error;
  const status = container.querySelector<HTMLElement>("#fc-status");
  if (status) status.textContent = text;
  const errorNode = container.querySelector<HTMLElement>("#fc-error");
  if (errorNode) {
    errorNode.textContent = error;
    errorNode.hidden = error.length === 0;
  }
}

function setLiveControls(container: HTMLElement, s: FieldCaptureState): void {
  const start = container.querySelector<HTMLButtonElement>("#fc-start");
  const capture = container.querySelector<HTMLButtonElement>("#fc-capture");
  const record = container.querySelector<HTMLButtonElement>("#fc-record");
  const stop = container.querySelector<HTMLButtonElement>("#fc-stop");
  const again = container.querySelector<HTMLButtonElement>("#fc-again");
  const preview = container.querySelector<HTMLVideoElement>("#fc-preview");
  if (preview) preview.hidden = !s.live;
  if (start) start.hidden = s.live || s.recording;
  if (capture) capture.hidden = !s.live || s.recording || s.mode !== "photo";
  if (record) record.hidden = !s.live || s.recording || s.mode !== "video";
  if (stop) stop.hidden = !s.recording;
  if (again) again.hidden = s.live || s.recording;
}

function fmtBytes(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  return `${(bytes / 1024).toFixed(1)} KB`;
}

function shortHash(hash: string): string {
  return `${hash.slice(0, 12)}…${hash.slice(-8)}`;
}

interface CaptureContext {
  cases: CaseRecord[];
  record?: CaseRecord;
  rooms: Array<{ id: string; name: string }>;
  sessions: InvestigationSessionRecord[];
}

async function loadContext(s: FieldCaptureState): Promise<CaptureContext> {
  const cases = (await new CaseRepository(db()).listCases(200)).filter((record) => record.status !== "archived");
  if (!s.caseId || !cases.some((record) => record.id === s.caseId)) s.caseId = cases[0]?.id ?? null;
  const record = s.caseId ? cases.find((item) => item.id === s.caseId) : undefined;
  const structure = record ? await db().propertyStructures.where("caseId").equals(record.id).first() : undefined;
  const rooms = structure
    ? (await db().structureRooms.where("structureId").equals(structure.id).toArray()).filter((room) => !room.archived)
    : [];
  if (!s.roomId || !rooms.some((room) => room.id === s.roomId)) s.roomId = "";
  const sessions = record
    ? (await db().sessions.where("caseId").equals(record.id).toArray()).sort((a, b) => b.startedAt - a.startedAt)
    : [];
  if (!s.sessionId || !sessions.some((session) => session.id === s.sessionId)) {
    s.sessionId = sessions.find((session) => session.status === "active" || session.status === "paused")?.id ?? "";
  }
  return { cases, record, rooms, sessions };
}

function contextHtml(s: FieldCaptureState, ctx: CaptureContext): string {
  return `
    <section class="capture-context" aria-labelledby="fc-context-title">
      <h3 class="cc-section-title" id="fc-context-title">Case + Room Context</h3>
      <div class="detail-grid">
        <div class="detail-field"><label for="fc-case">Active case</label>
          <select id="fc-case" ${ctx.cases.length === 0 ? "disabled" : ""}>
            ${ctx.cases.length === 0 ? '<option value="">— no active cases —</option>' : ctx.cases.map((record) =>
              `<option value="${esc(record.id)}"${record.id === s.caseId ? " selected" : ""}>${esc(record.caseNumber)} — ${esc(record.title)}</option>`,
            ).join("")}
          </select>
        </div>
        <div class="detail-field"><label for="fc-room">Room / area</label>
          <select id="fc-room">
            <option value="">Unassigned</option>
            ${ctx.rooms.map((room) => `<option value="${esc(room.id)}"${room.id === s.roomId ? " selected" : ""}>${esc(room.name)}</option>`).join("")}
          </select>
        </div>
        <div class="detail-field"><label for="fc-session">Investigation session</label>
          <select id="fc-session">
            <option value="">— no session association —</option>
            ${ctx.sessions.map((session) => `<option value="${esc(session.id)}"${session.id === s.sessionId ? " selected" : ""}>${esc(session.status)} — ${new Date(session.startedAt).toLocaleString()}</option>`).join("")}
          </select>
        </div>
      </div>
      <p class="cc-meta">The selected case, room and session IDs are stored on the evidence record. A missing association is never inferred from the filename.</p>
      ${s.caseId ? "" : '<p class="cc-count" role="alert">Create or select an active case before using the camera.</p>'}
    </section>`;
}

function lastCaptureHtml(s: FieldCaptureState): string {
  if (!s.last || !s.lastBlob) {
    return '<div class="cc-empty" id="fc-last-empty">No capture in this view yet.</div>';
  }
  const url = previewUrl(s.lastBlob);
  const preview = s.last.mimeType.startsWith("image/")
    ? `<img class="capture-preview" src="${url}" alt="Last captured field photo">`
    : `<video class="capture-preview" controls playsinline src="${url}" aria-label="Last recorded field video"></video>`;
  const duration = s.last.durationMs !== undefined ? ` • duration ${formatCaptureDuration(s.last.durationMs)}` : "";
  const dimensions = s.last.width && s.last.height ? `${s.last.width}×${s.last.height}` : "dimensions not reported";
  return `
    <div class="capture-last" id="fc-last" data-evidence-id="${esc(s.last.id)}">
      ${preview}
      <div class="capture-last-meta">
        <div class="case-title">${esc(s.last.fileName)}</div>
        <div class="case-meta">Original evidence • ${esc(s.last.mimeType)} • ${fmtBytes(s.last.sizeBytes)}${duration}<br>
          ${esc(dimensions)} • SHA-256 ${esc(shortHash(s.last.contentHash))}</div>
        <div class="case-meta">Stored unchanged in this case. No analysis, classification or conclusion was generated.</div>
      </div>
    </div>`;
}

function recentCapturesHtml(records: EvidenceRecord[]): string {
  if (records.length === 0) return '<div class="cc-empty">No equipment camera or video captures for this case yet.</div>';
  return records
    .slice(0, 10)
    .map(
      (record) => `
      <div class="case-row" data-equipment-capture="${esc(record.id)}">
        <div>
          <div class="case-title">${esc(record.originalFileName ?? record.fileName)}</div>
          <div class="case-meta">${esc(record.mediaType)} • ${fmtBytes(record.fileSizeBytes)} • ${new Date(record.captureTimestamp ?? record.createdAt).toLocaleString()} • integrity: ${esc(record.verificationStatus ?? "unverified")}${record.sessionId ? ` • session ${esc(record.sessionId.slice(0, 8))}` : ""}</div>
        </div>
        <span class="status-badge implemented">ORIGINAL</span>
      </div>`,
    )
    .join("");
}

export async function renderEquipmentCamera(container: HTMLElement): Promise<void> {
  await releaseFieldCapture();
  const s = state(container, "photo");
  const ctx = await loadContext(s);
  const supported = typeof navigator !== "undefined" && !!navigator.mediaDevices?.getUserMedia;
  const captures = ctx.record
    ? (await db().evidence.where("caseId").equals(ctx.record.id).toArray())
        .filter((record) => record.provenance.origin === "equipment-camera")
        .sort((a, b) => b.createdAt - a.createdAt)
    : [];

  invalidateView(container);
  mountView(
    container,
    viewShell(
      "Camera Capture",
      `
      <div class="case-form field-capture" data-root="equipment-camera" data-mode="photo" data-epoch="${Date.now()}-${Math.random()}">
        <p class="primary-line">Capture • Tag • Case Link</p>
        <p class="cc-meta">Capture a still image with this device's camera. The image is stored as original evidence; no adjustment, anomaly detection or conclusion is applied.</p>
        ${supported ? "" : '<p class="cc-count" role="alert"><strong>Camera capture is unavailable in this browser.</strong> The card is shown to preserve the original equipment hierarchy; no image is fabricated.</p>'}
        ${contextHtml(s, ctx)}
        <section class="capture-stage" aria-labelledby="fc-camera-title">
          <h3 class="cc-section-title" id="fc-camera-title">Camera</h3>
          <video id="fc-preview" class="capture-preview" autoplay muted playsinline hidden aria-label="Live camera preview"></video>
          <div class="form-actions">
            <button class="button-primary" id="fc-start" type="button" ${supported ? "" : "disabled"}>Enable Camera</button>
            <button class="button-primary" id="fc-capture" type="button" hidden>Capture Photo</button>
            <button class="button-secondary" id="fc-again" type="button" hidden>Capture Another</button>
          </div>
          <p class="cc-meta">The browser controls camera permission. Granting camera permission is not the same as consent to photograph people or private property; confirm the case's Audio, Video, and Photography Investigation Consent first.</p>
        </section>
        <section class="capture-result" aria-live="polite">
          <p class="cc-meta" id="fc-status" role="status">${esc(s.status)}</p>
          <p class="cc-count" id="fc-error" role="alert" ${s.error ? "" : "hidden"}>${esc(s.error)}</p>
          ${lastCaptureHtml(s)}
        </section>
        <h3 class="cc-section-title">Equipment Camera Evidence (${captures.length})</h3>
        ${recentCapturesHtml(captures)}
        <div class="form-actions"><button class="back-button" id="fc-back" type="button">← Back to Equipment</button></div>
      </div>`,
    ),
  );

  wireContext(container, s, "photo");
  wireCamera(container, s);
  setLiveControls(container, s);
}

export async function renderEquipmentVideo(container: HTMLElement): Promise<void> {
  await releaseFieldCapture();
  const s = state(container, "video");
  const ctx = await loadContext(s);
  const supported = typeof navigator !== "undefined" && !!navigator.mediaDevices?.getUserMedia;
  const recordings = ctx.record
    ? (await db().evidence.where("caseId").equals(ctx.record.id).toArray())
        .filter((record) => record.provenance.origin === "equipment-video")
        .sort((a, b) => b.createdAt - a.createdAt)
    : [];
  const mimeType = pickVideoMimeType();

  invalidateView(container);
  mountView(
    container,
    viewShell(
      "Video Recorder",
      `
      <div class="case-form field-capture" data-root="equipment-video" data-mode="video" data-epoch="${Date.now()}-${Math.random()}">
        <p class="primary-line">Record • Timestamp • Case Link</p>
        <p class="cc-meta">Record a video with this device's camera. The clip is stored as original evidence; no playback enhancement, frame interpretation or anomaly detection is performed here.</p>
        ${supported ? "" : '<p class="cc-count" role="alert"><strong>Video capture is unavailable in this browser.</strong> The card is shown to preserve the original equipment hierarchy; no video is fabricated.</p>'}
        ${mimeType ? "" : '<p class="cc-count" role="alert"><strong>This browser cannot record video</strong> (MediaRecorder video support unavailable). The interface is preserved, but no recording can be saved.</p>'}
        ${contextHtml(s, ctx)}
        <section class="capture-stage" aria-labelledby="fc-video-title">
          <h3 class="cc-section-title" id="fc-video-title">Camera + Recording</h3>
          <video id="fc-preview" class="capture-preview" autoplay muted playsinline hidden aria-label="Live camera preview"></video>
          <p class="cc-count" id="fc-timer" hidden>Elapsed: 00:00</p>
          <div class="form-actions">
            <button class="button-primary" id="fc-start" type="button" ${supported && mimeType ? "" : "disabled"}>Enable Camera</button>
            <button class="button-primary" id="fc-record" type="button" hidden ${mimeType ? "" : "disabled"}>Start Recording</button>
            <button class="button-secondary" id="fc-stop" type="button" hidden>Stop &amp; Save</button>
            <button class="button-secondary" id="fc-again" type="button" hidden>Record Another</button>
          </div>
          <p class="cc-meta">Video includes microphone audio when the browser supplies it. If no microphone is available, the recorder reports that the clip is silent rather than inventing audio.</p>
          <p class="cc-meta">The browser may choose a WebM or MP4 container. The exact MIME type is recorded with the original; playback depends on the browser's codec support.</p>
        </section>
        <section class="capture-result" aria-live="polite">
          <p class="cc-meta" id="fc-status" role="status">${esc(s.status)}</p>
          <p class="cc-count" id="fc-error" role="alert" ${s.error ? "" : "hidden"}>${esc(s.error)}</p>
          ${lastCaptureHtml(s)}
        </section>
        <h3 class="cc-section-title">Equipment Video Evidence (${recordings.length})</h3>
        ${recentCapturesHtml(recordings)}
        <div class="form-actions"><button class="back-button" id="fc-back" type="button">← Back to Equipment</button></div>
      </div>`,
    ),
  );

  wireContext(container, s, "video");
  wireVideo(container, s);
  setLiveControls(container, s);
}

function wireContext(container: HTMLElement, s: FieldCaptureState, mode: CaptureMode): void {
  onDelegate(container, "change", "#fc-case", (element) => {
    s.caseId = (element as HTMLSelectElement).value || null;
    s.roomId = "";
    s.sessionId = "";
    void releaseFieldCapture();
    void (mode === "photo" ? renderEquipmentCamera(container) : renderEquipmentVideo(container));
  });
  onDelegate(container, "change", "#fc-room", (element) => {
    s.roomId = (element as HTMLSelectElement).value || "";
  });
  onDelegate(container, "change", "#fc-session", (element) => {
    s.sessionId = (element as HTMLSelectElement).value || "";
  });
  onDelegate(container, "click", "#fc-back", () => {
    void releaseFieldCapture().then(async () => {
      // Camera and video are subviews of #/equipment; navigating to the same
      // hash would not emit a route change. Re-render the hub explicitly.
      const { renderEquipment } = await import("../dashboard/views");
      await renderEquipment(container);
    });
  });
}

function attachPreview(container: HTMLElement, stream: MediaStream): Promise<void> {
  const video = container.querySelector<HTMLVideoElement>("#fc-preview");
  if (!video) return Promise.reject(new Error("Camera preview element is missing."));
  video.srcObject = stream;
  video.hidden = false;
  return video.play().catch(() => {
    /* Some browsers resolve play after metadata; the stream is still live. */
  });
}

async function requestPhotoStream(): Promise<MediaStream> {
  if (!navigator.mediaDevices?.getUserMedia) throw new DOMException("Captured API unavailable", "NotSupportedError");
  return navigator.mediaDevices.getUserMedia(photoConstraints());
}

interface VideoStreamResult {
  stream: MediaStream;
  hasAudio: boolean;
  warning: string;
}

async function requestVideoStream(): Promise<VideoStreamResult> {
  if (!navigator.mediaDevices?.getUserMedia) throw new DOMException("Captured API unavailable", "NotSupportedError");
  try {
    const stream = await navigator.mediaDevices.getUserMedia(videoConstraints());
    if (streamHasAudio(stream)) return { stream, hasAudio: true, warning: "" };
    return { stream, hasAudio: false, warning: "No microphone audio track was supplied; this clip will be silent." };
  } catch (err) {
    const name = (err as { name?: string }).name ?? "";
    // A camera-only fallback is honest only when the failure is about the
    // audio device, not when the investigator denied permission.
    if (name === "NotFoundError" || name === "OverconstrainedError" || name === "NotReadableError") {
      const stream = await navigator.mediaDevices.getUserMedia(silentVideoConstraints());
      return { stream, hasAudio: false, warning: "No microphone was available; this clip is silent." };
    }
    throw err;
  }
}

function wireCamera(container: HTMLElement, s: FieldCaptureState): void {
  onDelegate(container, "click", "#fc-start", async () => {
    if (!s.caseId) {
      setStatus(container, s, "Select a case before enabling the camera.", "No case is selected; nothing was captured.");
      return;
    }
    setStatus(container, s, "Requesting camera permission…");
    try {
      const stream = await requestPhotoStream();
      activeStream = stream;
      activeContainer = container;
      s.live = true;
      await attachPreview(container, stream);
      setStatus(container, s, "Camera live. Nothing is saved until you capture a photo.");
      setLiveControls(container, s);
    } catch (err) {
      const failure = classifyCaptureError(err, "camera");
      s.live = false;
      setStatus(container, s, failure.message, failure.message);
      setLiveControls(container, s);
    }
  });

  onDelegate(container, "click", "#fc-capture", async () => {
    if (!activeStream || !s.caseId) {
      setStatus(container, s, "The camera is not live. Enable it before capturing.", "No live camera stream is available.");
      return;
    }
    const video = container.querySelector<HTMLVideoElement>("#fc-preview");
    if (!video || video.videoWidth === 0 || video.videoHeight === 0) {
      setStatus(container, s, "The camera has not produced a decodable frame yet. Wait a moment and try again.", "No frame was captured; nothing was saved.");
      return;
    }
    setStatus(container, s, "Capturing photo…");
    try {
      const width = video.videoWidth;
      const height = video.videoHeight;
      const canvas = document.createElement("canvas");
      canvas.width = width;
      canvas.height = height;
      const context = canvas.getContext("2d");
      if (!context) throw new Error("Canvas 2D context is unavailable.");
      context.drawImage(video, 0, 0, width, height);
      const blob = await new Promise<Blob | null>((resolve) => canvas.toBlob((value) => resolve(value), "image/png"));
      if (!blob || blob.size === 0) throw new Error("The camera frame could not be encoded as PNG.");
      const capturedAt = Date.now();
      await releaseFieldCapture();
      s.live = false;
      const record = await persistCapture({
        caseId: s.caseId,
        sessionId: s.sessionId,
        roomId: s.roomId,
        mediaType: "photo",
        fileName: captureFileName("photo", capturedAt),
        file: new File([blob], captureFileName("photo", capturedAt), { type: "image/png" }),
        title: `Equipment photo — ${new Date(capturedAt).toLocaleString()}`,
        origin: "equipment-camera",
        capturedAt,
        width,
        height,
        notes: `Captured with the Equipment Camera at ${width}×${height}. Original bytes stored unchanged; no analysis or conclusion generated.`,
      });
      s.lastBlob = blob;
      s.last = {
        id: record.id,
        fileName: record.originalFileName ?? record.fileName,
        contentHash: record.contentHash,
        mimeType: record.mimeType ?? "image/png",
        sizeBytes: record.fileSizeBytes,
        width,
        height,
        sessionId: record.sessionId,
        createdAt: record.createdAt,
      };
      s.status = "Photo saved as original evidence.";
      s.error = "";
      await renderEquipmentCamera(container);
    } catch (err) {
      s.live = false;
      stopMediaStream(activeStream);
      activeStream = null;
      const failure = classifyCaptureError(err, "camera");
      setStatus(container, s, failure.message, failure.message);
      setLiveControls(container, s);
    }
  });

  onDelegate(container, "click", "#fc-again", async () => {
    s.last = null;
    s.lastBlob = null;
    s.status = "Ready for a new capture.";
    await renderEquipmentCamera(container);
  });
}

function wireVideo(container: HTMLElement, s: FieldCaptureState): void {
  onDelegate(container, "click", "#fc-start", async () => {
    if (!s.caseId) {
      setStatus(container, s, "Select a case before enabling the camera.", "No case is selected; nothing was recorded.");
      return;
    }
    const mimeType = pickVideoMimeType();
    if (!mimeType) {
      setStatus(container, s, "This browser cannot record video (MediaRecorder video support unavailable).", "No video was recorded.");
      return;
    }
    setStatus(container, s, "Requesting camera and microphone permission…");
    try {
      const result = await requestVideoStream();
      activeStream = result.stream;
      activeContainer = container;
      s.live = true;
      await attachPreview(container, result.stream);
      setStatus(
        container,
        s,
        result.warning
          ? `Camera live. ${result.warning}`
          : "Camera and microphone live. Nothing is saved until you start recording.",
      );
      setLiveControls(container, s);
    } catch (err) {
      const failure = classifyCaptureError(err, "camera");
      s.live = false;
      setStatus(container, s, failure.message, failure.message);
      setLiveControls(container, s);
    }
  });

  onDelegate(container, "click", "#fc-record", async () => {
    if (!activeStream || !s.caseId) {
      setStatus(container, s, "The camera is not live. Enable it before recording.", "No live camera stream is available.");
      return;
    }
    const mimeType = pickVideoMimeType();
    if (!mimeType) {
      setStatus(container, s, "This browser cannot record video.", "No video was recorded.");
      return;
    }
    try {
      activeChunks = [];
      const recorder = mimeType
        ? new MediaRecorder(activeStream, { mimeType })
        : new MediaRecorder(activeStream);
      activeRecorder = recorder;
      activeContainer = container;
      const startedAt = Date.now();
      s.recording = true;
      s.recordingStartedAt = startedAt;
      s.status = "Recording…";
      s.error = "";
      recorder.addEventListener("dataavailable", (event) => {
        if (event.data && event.data.size > 0) activeChunks.push(event.data);
      });
      recorder.start(1000);
      if (activeTimer !== null) window.clearInterval(activeTimer);
      activeTimer = window.setInterval(() => {
        const timer = container.querySelector<HTMLElement>("#fc-timer");
        if (timer) {
          timer.hidden = false;
          timer.textContent = `Elapsed: ${formatCaptureDuration(Date.now() - startedAt)}`;
        }
      }, 250);
      const timer = container.querySelector<HTMLElement>("#fc-timer");
      if (timer) {
        timer.hidden = false;
        timer.textContent = "Elapsed: 00:00";
      }
      setStatus(container, s, "Recording. Nothing is saved until you stop.");
      setLiveControls(container, s);
    } catch (err) {
      activeRecorder = null;
      s.recording = false;
      s.recordingStartedAt = null;
      const failure = classifyCaptureError(err, "camera");
      setStatus(container, s, failure.message, failure.message);
      setLiveControls(container, s);
    }
  });

  onDelegate(container, "click", "#fc-stop", async () => {
    const recorder = activeRecorder;
    const stream = activeStream;
    const startedAt = s.recordingStartedAt;
    if (!recorder || !stream || !startedAt || !s.caseId) {
      setStatus(container, s, "No active recording is available to save.", "No recording was saved.");
      return;
    }
    setStatus(container, s, "Stopping and saving the original video…");
    const chunks = activeChunks;
    const mimeType = recorder.mimeType || pickVideoMimeType() || "video/webm";
    const stopped = new Promise<void>((resolve) => {
      recorder.addEventListener("stop", () => resolve(), { once: true });
    });
    try {
      const hasAudio = streamHasAudio(stream);
      if (recorder.state !== "inactive") recorder.stop();
      await stopped;
      if (activeTimer !== null) {
        window.clearInterval(activeTimer);
        activeTimer = null;
      }
      activeRecorder = null;
      const durationMs = Math.max(0, Date.now() - startedAt);
      stopMediaStream(stream);
      activeStream = null;
      s.recording = false;
      s.recordingStartedAt = null;
      if (chunks.length === 0) throw new Error("The recorder produced no video data.");
      const blob = new Blob(chunks, { type: mimeType });
      if (blob.size === 0) throw new Error("The recorder produced an empty video file.");
      const fileName = captureFileName("video", startedAt, mimeType);
      const video = container.querySelector<HTMLVideoElement>("#fc-preview");
      const width = video?.videoWidth || undefined;
      const height = video?.videoHeight || undefined;
      const record = await persistCapture({
        caseId: s.caseId,
        sessionId: s.sessionId,
        roomId: s.roomId,
        mediaType: "video",
        fileName,
        file: new File([blob], fileName, { type: mimeType }),
        title: `Equipment video — ${new Date(startedAt).toLocaleString()}`,
        origin: "equipment-video",
        capturedAt: startedAt,
        durationMs,
        width,
        height,
        audio: hasAudio,
        notes: `Recorded with the Equipment Video Recorder for ${formatCaptureDuration(durationMs)}. Container: ${mimeType}. Audio track: ${hasAudio ? "present" : "absent"}. Original bytes stored unchanged; no analysis or conclusion generated.`,
      });
      s.lastBlob = blob;
      s.last = {
        id: record.id,
        fileName: record.originalFileName ?? record.fileName,
        contentHash: record.contentHash,
        mimeType: record.mimeType ?? mimeType,
        sizeBytes: record.fileSizeBytes,
        durationMs,
        width,
        height,
        audio: hasAudio,
        sessionId: record.sessionId,
        createdAt: record.createdAt,
      };
      s.status = "Video saved as original evidence.";
      s.error = "";
      await renderEquipmentVideo(container);
    } catch (err) {
      activeRecorder = null;
      activeChunks = [];
      s.recording = false;
      s.recordingStartedAt = null;
      stopMediaStream(stream);
      activeStream = null;
      if (activeTimer !== null) {
        window.clearInterval(activeTimer);
        activeTimer = null;
      }
      const failure = classifyCaptureError(err, "camera");
      setStatus(container, s, failure.message, failure.message);
      setLiveControls(container, s);
    }
  });

  onDelegate(container, "click", "#fc-again", async () => {
    s.last = null;
    s.lastBlob = null;
    s.status = "Ready for a new recording.";
    await renderEquipmentVideo(container);
  });
}

interface PersistCaptureInput {
  caseId: string;
  sessionId: string;
  roomId: string;
  mediaType: "photo" | "video";
  fileName: string;
  file: File;
  title: string;
  origin: "equipment-camera" | "equipment-video";
  capturedAt: number;
  durationMs?: number;
  width?: number;
  height?: number;
  audio?: boolean;
  notes: string;
}

async function persistCapture(input: PersistCaptureInput): Promise<EvidenceRecord> {
  if (input.roomId) {
    const room = await db().structureRooms.get(input.roomId);
    if (!room || room.caseId !== input.caseId) {
      throw new ValidationError("Room does not belong to the selected case", "roomId");
    }
  }
  const repo = new EvidenceRepository(db());
  const record = await repo.storeOriginal({
    caseId: input.caseId,
    sessionId: input.sessionId || undefined,
    mediaType: input.mediaType,
    title: input.title,
    fileName: input.fileName,
    data: input.file,
    origin: input.origin,
    recordedBy: "local-user",
  });
  const updated: EvidenceRecord = {
    ...record,
    originalFileName: input.fileName,
    sourceDescription:
      input.origin === "equipment-camera"
        ? "Captured in-app with the Equipment Camera. Original bytes stored unchanged and hashed on write."
        : "Captured in-app with the Equipment Video Recorder. Original bytes stored unchanged and hashed on write.",
    importedAt: Date.now(),
    verificationStatus: "verified",
    verifiedAt: Date.now(),
    verificationDetail: "Stored unchanged from the capture and hashed immediately after write.",
    roomId: input.roomId || null,
    captureTimestamp: input.capturedAt,
    captureTimestampSource: "capture",
    captureTimezoneOffsetMinutes: -new Date().getTimezoneOffset(),
    notes: input.notes,
  };
  await db().evidence.put(updated);
  await new AuditService(db()).record("evidenceImported", `Equipment ${input.mediaType} capture saved as original evidence.`, {
    caseId: input.caseId,
    affectedRecordId: record.id,
    metadata: {
      mediaType: input.mediaType,
      origin: input.origin,
      sessionId: input.sessionId || null,
      roomId: input.roomId || null,
      durationMs: input.durationMs ?? null,
      width: input.width ?? null,
      height: input.height ?? null,
      audio: input.audio ?? null,
    },
  });
  return updated;
}

/** Release the active stream when the page is hidden; it is never claimed to run in the background. */
export function bindFieldCaptureVisibility(): void {
  if (typeof document === "undefined") return;
  document.addEventListener("visibilitychange", () => {
    if (document.hidden && (activeStream || activeRecorder)) {
      const container = activeContainer;
      void releaseFieldCapture();
      if (container) {
        const status = container.querySelector<HTMLElement>("#fc-status");
        if (status) status.textContent = "Camera released because the page was hidden. Nothing partial was saved.";
      }
    }
  });
}

export type { LastCapture };
