/**
 * Checklist service (TPI-V2-WEB-005 §7) — persistent investigation checklists.
 * Kept in its own module so caseRepository can import it without a cycle.
 */
import type { TPIDatabase } from "../db";
import { SCHEMA_VERSION } from "../db";
import { v4 as uuidv4 } from "../../shared/uuid";
import type {
  ChecklistItemRecord,
  ChecklistItemStatus,
  WorkflowPhase,
} from "../types";
import { ValidationError } from "../validation";
import { AuditService } from "../audit";

/** Canonical checklist template (ported from iOS PPFrontHalfWorkflowChecklistItemID). */
export const CANONICAL_CHECKLIST: ReadonlyArray<{
  definitionId: string;
  phase: WorkflowPhase;
  title: string;
  guidance: string;
  required: boolean;
}> = [
  { definitionId: "caseCreated", phase: "caseCreation", title: "Case Created", guidance: "Active case exists and is attached.", required: true },
  { definitionId: "requiredDocumentsSigned", phase: "documents", title: "Required Documents Signed", guidance: "Required documents and signatures are complete.", required: true },
  { definitionId: "intakeComplete", phase: "intake", title: "Intake", guidance: "Intake cards are complete.", required: true },
  { definitionId: "walkthroughComplete", phase: "walkthrough", title: "Walkthrough", guidance: "Walkthrough is complete.", required: true },
  { definitionId: "baselineComplete", phase: "baseline", title: "Baseline Complete", guidance: "Baseline is complete.", required: true },
  { definitionId: "investigationReady", phase: "investigationReady", title: "Investigation Ready", guidance: "Front-half preparation is complete.", required: true },
  // TPI-V2-WEB-009: evidence review gate (readiness derives from review records)
  { definitionId: "evidenceReviewed", phase: "review", title: "Evidence Reviewed", guidance: "Imported evidence has been reviewed.", required: true },
];

export class ChecklistService {
  constructor(private readonly db: TPIDatabase) {}

  private get audit(): AuditService {
    return new AuditService(this.db);
  }

  async listForCase(caseId: string): Promise<ChecklistItemRecord[]> {
    return this.db.checklistItems.where("caseId").equals(caseId).sortBy("createdAt");
  }

  /** Seed the canonical checklist for a newly created case (idempotent). */
  async ensureCanonicalChecklist(caseId: string): Promise<void> {
    const existing = await this.listForCase(caseId);
    if (existing.length > 0) return;
    const rows: ChecklistItemRecord[] = CANONICAL_CHECKLIST.map((d, i) => ({
      id: uuidv4(),
      schemaVersion: SCHEMA_VERSION as ChecklistItemRecord["schemaVersion"],
      createdAt: Date.now() + i,
      updatedAt: Date.now() + i,
      caseId,
      phase: d.phase,
      definitionId: d.definitionId,
      title: d.title,
      guidance: d.guidance,
      required: d.required,
      status: d.definitionId === "caseCreated" ? "complete" : "pending",
      completedAt: d.definitionId === "caseCreated" ? Date.now() : null,
      completedBy: d.definitionId === "caseCreated" ? "system" : null,
      notes: "",
    }));
    await this.db.checklistItems.bulkAdd(rows);
  }

  /** Set an item's completion state with audit. Exceptions require justification. */
  async setItemStatus(
    caseId: string,
    itemId: string,
    status: ChecklistItemStatus,
    options: { justification?: string; actor?: string } = {},
  ): Promise<ChecklistItemRecord | undefined> {
    return this.db.transaction("rw", this.db.checklistItems, this.db.auditEvents, async () => {
      const item = await this.db.checklistItems.get(itemId);
      if (!item || item.caseId !== caseId) {
        throw new ValidationError(`Checklist item not found for case: ${itemId}`, "itemId");
      }
      if (status === "exception" && !options.justification?.trim()) {
        throw new ValidationError(
          "Proceeding without a requirement requires a documented justification",
          "justification",
        );
      }
      if (status === "exception" && item.definitionId === "requiredDocumentsSigned") {
        throw new ValidationError(
          "Required documents cannot be overridden: proceeding without signed documents is not permitted",
          "definitionId",
        );
      }
      const next: ChecklistItemRecord = {
        ...item,
        status,
        updatedAt: Date.now(),
        completedAt: status === "complete" ? Date.now() : item.completedAt,
        completedBy: status === "complete" ? (options.actor ?? "investigator") : item.completedBy,
        notes: options.justification ?? item.notes,
      };
      await this.db.checklistItems.put(next);
      await this.audit.record(
        status === "exception" ? "statusChanged" : "checklistChanged",
        `Checklist "${item.title}" → ${status}`,
        {
          caseId,
          affectedRecordId: itemId,
          metadata: { definitionId: item.definitionId, status },
        },
      );
      return next;
    });
  }
}

