const db = () => getDb();
const selectedRoomByCase = new Map<string, string>();
const caseHubBackHandlers = new WeakMap<HTMLElement, () => void>();

function fmtTime(ms: number): string {
  return new Date(ms).toLocaleString();
}

export async function renderCaseHub(container: HTMLElement, caseId: string, onBack?: () => void): Promise<void> {
  if (onBack) caseHubBackHandlers.set(container, onBack);
  const back = caseHubBackHandlers.get(container);

  if (!caseId) {
    renderMissingCase(container, back, "No case was specified.");
    return;
  }

  const record = await new CaseRepository(db()).getCase(caseId);
  if (!record) {
    // Never silently fall back to another case (TPI-V2-WEB-014B §2).
    renderMissingCase(container, back, "This case does not exist or is no longer available.");
    return;
  }
  const client = record.clientId ? await new ClientRepository(db()).get(record.clientId) : undefined;
  const location = record.locationId ? await new LocationRepository(db()).get(record.locationId) : undefined;
  const stage = new WorkflowService(db()).lifecycleStage(record);
  const evaluation = await new WorkflowReadinessService(db()).evaluate(record.id);
  const items = await new ChecklistService(db()).listForCase(record.id);
  const events = await new AuditService(db()).listForCase(record.id, 25);
  const structure = await db().propertyStructures.where("caseId").equals(record.id).first();
  const rooms = structure
    ? (await db().structureRooms.where("structureId").equals(structure.id).toArray())
        .filter((room) => !room.archived)
        .sort((a, b) => a.orderIndex - b.orderIndex)
    : [];
  const baselines = await db().baselineRecords.where("caseId").equals(record.id).toArray();
  const sessions = await new SessionService(db()).listSessions(record.id);
  const investigationCompletion = await new InvestigationCompletionService(db()).getCompletion(record.id);
  const walkthroughSessions = await db().walkthroughSessions.where("caseId").equals(record.id).toArray();
  render(container, record, { stage, client, location, evaluation, items, events, structure, rooms, baselines, sessions, investigationCompletion, walkthroughSessions }, back);
}

function renderMissingCase(container: HTMLElement, back: (() => void) | undefined, detail: string): void {
  container.innerHTML = viewShell(
    "Case Hub",
    `<div class="cc-empty" data-casehub-missing="true">
      <p><strong>Case not found.</strong> ${esc(detail)}</p>
      <p class="cc-meta">No other case was opened. Choose a case from Case Files to continue.</p>
      <button class="button-primary" id="casehub-missing-back" type="button">Back to Case Files</button>
    </div>`,
  );
  container.querySelector<HTMLButtonElement>("#casehub-missing-back")?.addEventListener("click", () => {
    if (back) back();
    else window.location.hash = "/command-center";
  });
}

function render(
  container: HTMLElement,
  record: CaseRecord,
  data: {
    stage: string;
    client?: { fullName: string };
    location?: { name: string };
    evaluation?: {
      state: string;
      blockers: WorkflowBlocker[];
      progress: WorkflowProgress;
      nextSteps: NextStep[];
    };
    items: ChecklistItemRecord[];
    events: Array<{ createdAt: number; type: string; detail: string }>;
    structure?: PropertyStructureRecord;
    rooms: RoomRecord[];
    baselines: BaselineRecord[];
    sessions: InvestigationSessionRecord[];
    walkthroughSessions: Array<{ status: string; completedAt: number | null }>;
    investigationCompletion?: InvestigationCompletion;
  },
  onBack?: () => void,
): void {
  const { evaluation } = data;
  const progress = evaluation?.progress;

  mountView(container, `
    <div class="view cc-view casehub-view" data-casehub-case="${esc(record.id)}">
      <header class="cc-page-header">
        <button class="back-button cc-hub-back" type="button" data-hub-back>‹ Case Files</button>
        <h2 id="cc-page-title">Case Hub</h2>
        <button class="back-button" id="hub-case-details" type="button" aria-label="Edit case details">Case Details</button>
      </header>
    ${caseWorkspaceHtml(record, data)}
    <div class="casehub-sections" aria-label="Case Hub modules">
      ${CASE_HUB_SECTIONS.map((section) => caseHubSectionHtml(section.id, section.title, record.id, Boolean(data.investigationCompletion))).join("")}
    </div>
    <details class="cc-readiness-details" open>
      <summary>Workflow readiness, checklist, and recent activity</summary>
      <h3 class="cc-section-title">Workflow readiness</h3>
    <div class="case-form hub-overview">
      <div class="detail-grid">
        <div class="detail-field"><label>Status / Lifecycle</label><div><span class="status-badge">${esc(record.status)}</span> ${esc(data.stage)}</div></div>
        <div class="detail-field"><label>Client</label><div>${data.client ? esc(data.client.fullName) : esc(record.clientName ?? "—")}</div></div>
        <div class="detail-field"><label>Location</label><div>${data.location ? esc(data.location.name) : "—"}</div></div>
        <div class="detail-field"><label>Created</label><div>${fmtTime(record.createdAt)}</div></div>
        <div class="detail-field"><label>Updated</label><div>${fmtTime(record.updatedAt)}</div></div>
      </div>
      <div class="phase-timeline" aria-label="Workflow phase timeline">
        ${WORKFLOW_PHASE_ORDER.map((p) => {
          const idx = WORKFLOW_PHASE_ORDER.indexOf(record.currentPhase);
          const myIdx = WORKFLOW_PHASE_ORDER.indexOf(p);
          return `<span class="phase-step ${myIdx === idx ? "current" : myIdx < idx ? "done" : ""}">${p}</span>`;
        }).join("")}
      </div>
      ${progress ? progressHtml(progress, evaluation?.blockers ?? [], record.id) : ""}
    </div>

    <h3 class="cc-section-title">Next steps</h3>
    ${nextStepsHtml(evaluation?.nextSteps ?? [])}

    <h3 class="cc-section-title">Blockers</h3>
    ${blockersHtml(evaluation?.blockers ?? [])}

    <h3 class="cc-section-title">Checklist</h3>
    <div class="checklist" id="hub-checklist">
      ${data.items.map((i) => checklistItemHtml(record.id, i)).join("")}
    </div>

    <h3 class="cc-section-title">Case activity</h3>
    ${data.events.length === 0
      ? `<div class="cc-empty">No activity recorded.</div>`
      : `<ul class="activity-list">${data.events
          .map(
            (e) =>
              `<li><span class="when">${fmtTime(e.createdAt)} • ${esc(e.type)}</span><div class="what">${esc(e.detail)}</div></li>`,
          )
          .join("")}</ul>`}
    </details>
    </div>
  `);

  // TPI-V2-WEB-007 §4: persistent delegated handlers — bound once per
  // container, state read from data-* attributes, immune to re-renders.
  onDelegate(container, "click", "[data-check]", async (btn) => {
    const { caseId: cid, itemId, status, justification } = btn.dataset;
    try {
      await new ChecklistService(db()).setItemStatus(cid ?? "", itemId ?? "", (status ?? "complete") as ChecklistItemRecord["status"], {
        justification: justification ?? undefined,
      });
      const root = container.closest<HTMLElement>(".cc-view")?.parentElement ?? container;
      await renderCaseHub(root, cid ?? "");
    } catch (err) {
      // Non-overridable blockers surface as clear feedback (no state change)
      toastError((err as Error).message);
    }
  });
  onDelegate(container, "click", "[data-na-reason]", async (btn) => {
    const { caseId: cid, itemId } = btn.dataset;
    const reason = window.prompt("Document why this item is not applicable:", "");
    if (!reason?.trim()) {
      toastError("A documented reason is required to mark an item not applicable.");
      return;
    }
    await new ChecklistService(db()).setItemStatus(cid ?? "", itemId ?? "", "notApplicable", {
      justification: reason,
    });
    const root = container.closest<HTMLElement>(".cc-view")?.parentElement ?? container;
    await renderCaseHub(root, cid ?? "");
  });
  onDelegate(container, "click", "[data-override-advance]", async (btn) => {
    const cid = btn.dataset.overrideAdvance ?? "";
    const justification = window.prompt("Document the authorized exception for advancing:", "");
    if (!justification?.trim()) {
      toastError("An override requires a documented justification.");
      return;
    }
    try {
      await new WorkflowReadinessService(db()).forceAdvanceWithOverride(cid, justification);
      toastError("Override advancement recorded");
      const root = container.closest<HTMLElement>(".cc-view")?.parentElement ?? container;
      await renderCaseHub(root, cid);
    } catch (err) {
      toastError((err as Error).message);
    }
  });
  onDelegate(container, "click", "#hub-advance", async (btn) => {
    try {
      const next = await new WorkflowReadinessService(db()).advanceIfReady(btn.dataset.caseId ?? "");
      if (next) toastError(`Workflow advanced to ${next.currentPhase}`);
      const root = container.closest<HTMLElement>(".cc-view")?.parentElement ?? container;
      await renderCaseHub(root, btn.dataset.caseId ?? "");
    } catch (err) {
      // Blocked progression explains the blocker without changing case state
      toastError((err as Error).message);
    }
  });
  onDelegate(container, "click", "[data-hub-room]", async (button) => {
    const cid = button.dataset.caseId ?? "";
    const roomId = button.dataset.hubRoom ?? "";
    if (!cid || !roomId) return;
    selectedRoomByCase.set(cid, roomId);
    localStorage.setItem(`tpi-casehub-room:${cid}`, roomId);
    const sessionService = new SessionService(db());
    const active = (await sessionService.listSessions(cid)).find((session) => session.status === "active" || session.status === "paused");
    if (active && active.currentRoomId !== roomId) {
      const room = await db().structureRooms.get(roomId);
      await db().sessions.put({ ...active, currentRoomId: roomId, updatedAt: Date.now() });
      await sessionService.recordEvent(active.id, "roomChanged", `Investigation room selected: ${room?.name ?? "room"}.`, {
        metadata: { roomId },
      });
      await new AuditService(db()).record("sessionRoomChanged", "Investigation room selection changed.", {
        caseId: cid,
        affectedRecordId: active.id,
        metadata: { roomId },
      });
    }
    const root = container.closest<HTMLElement>(".cc-view")?.parentElement ?? container;
    await renderCaseHub(root, cid);
  });
  onDelegate(container, "change", "[data-sensor-toggle]", (input) => {
    const cid = container.querySelector<HTMLElement>("[data-casehub-case]")?.dataset.casehubCase;
    if (!cid) return;
    const key = `tpi-casehub-sensors:${cid}`;
    let preferences: Record<string, boolean> = {};
    try { preferences = JSON.parse(localStorage.getItem(key) ?? "{}"); } catch { preferences = {}; }
    preferences[input.dataset.sensorToggle ?? ""] = (input as HTMLInputElement).checked;
    localStorage.setItem(key, JSON.stringify(preferences));
  });
  onDelegate(container, "click", "#hub-start-investigation", async (button) => {
    const cid = button.dataset.caseId ?? "";
    if (!cid) return;
    try {
      const investigator = container.querySelector<HTMLInputElement>("#hub-investigator")?.value.trim();
      const created = await new SessionService(db()).createSession(cid, {
        investigators: investigator ? [investigator] : [],
        roomId: button.dataset.roomId || null,
      });
      await new SessionService(db()).startSession(created.id);
      const root = container.closest<HTMLElement>(".cc-view")?.parentElement ?? container;
      await renderCaseHub(root, cid);
    } catch (err) { toastError((err as Error).message); }
  });
  onDelegate(container, "click", "#hub-end-investigation", async (button) => {
    try {
      await new SessionService(db()).endSession(button.dataset.sessionId ?? "", "completed");
      const root = container.closest<HTMLElement>(".cc-view")?.parentElement ?? container;
      await renderCaseHub(root, record.id);
    } catch (err) { toastError((err as Error).message); }
  });
  onDelegate(container, "click", "#hub-complete-investigation", async (button) => {
    const cid = button.dataset.caseId ?? record.id;
    if (!window.confirm("Record explicit investigation completion? This unlocks Evidence Review for this case. Existing evidence and review records are preserved.")) return;
    try {
      await new InvestigationCompletionService(db()).complete(cid);
      const root = container.closest<HTMLElement>(".cc-view")?.parentElement ?? container;
      await renderCaseHub(root, cid);
    } catch (err) { toastError((err as Error).message); }
  });

  // ---- Module cards (original three sections) + retained workspace entries ----
  const root = container.closest<HTMLElement>(".cc-view")?.parentElement ?? container;
  const openCard = (el: HTMLElement) => {
    const id = el.dataset.card ?? "";
    const cid = el.dataset.caseId ?? record.id;
    if (!id || !cid) return;

    const definition = cardFor(id);
    if (definition?.availability === "unavailable") {
      toastError(`${definition.title} is not implemented in this build. ${definition.limitation ?? ""}`.trim());
      return;
    }

    switch (id) {
      case "checklist": void renderChecklistView(root, cid); return;
      case "investigationStatus": void renderInvestigationStatusView(root, cid); return;
      case "investigationAssistant": expandMystic(); return;
      case "documents": void renderDocumentsCenter(root, cid); return;
      case "intake": void renderIntakeView(root, cid); return;
      case "structure":
      case "hauntedLocationStructure":
      case "zoneStructureBuilder": void renderPropertyStructure(root, cid); return;
      case "walkthrough": void renderWalkthroughView(root, cid); return;
      case "baseline":
      case "environmentWeather": void renderBaselineView(root, cid); return;
      case "session": void renderSessionView(root, cid); return;
      case "emfReadings": void renderEmfReadings(root, cid); return;
      case "motionReadings": void renderMotionReadings(root, cid); return;
      case "noiseReadings": void renderNoiseReadings(root, cid); return;
      case "evidence": void renderEvidenceLibrary(root, cid); return;
      case "evidenceTimeline": void renderEvidenceTimeline(root, cid); return;
      case "evidenceReview": void renderEvidenceReview(root, cid); return;
      case "environmentalComparison": void renderEnvironmentalComparison(root, cid); return;
      case "multimedia": void renderMultimedia(root, cid); return;
      case "investigationSummary": void renderInvestigationSummary(root, cid); return;
      case "investigationInbox": void renderInvestigationInbox(root, cid); return;
      case "investigationNotes": void renderInvestigationNotes(root, cid); return;
      case "audioReadings": void renderAudioReadings(root, cid); return;
      case "audioAnalysis": void import("../forensic/AudioAnalysis").then((m) => m.renderAudioAnalysis(root)); return;
      case "darkRoom": void import("../forensic/DarkRoom").then((m) => m.renderDarkRoom(root)); return;
      case "videoAnalysis": void import("../forensic/VideoAnalysis").then((m) => m.renderVideoAnalysis(root)); return;
      default: return;
    }
  };
  onDelegate(container, "click", "[data-card]", (el) => openCard(el));

  // Case details editor — preserves the legacy detail surface's unique
  // capabilities (field editing, client/location association, archive/close).
  onDelegate(container, "click", "#hub-case-details", async (button) => {
    const cid = button.dataset.caseId ?? record.id;
    const module = await import("../commandcenter/CommandCenter");
    await module.renderCaseDetails(root, cid, () => void renderCaseHub(root, cid));
  });

  onDelegate(container, "click", "[data-hub-back]", () => {
    if (onBack) onBack();
    else window.location.hash = "/command-center";
  });

  // The header back control is handled exactly once, by the delegated
  // `[data-hub-back]` dispatcher above. Adding a second direct listener here
  // produced two history navigations for one click (Stage C1 regression).
  if (!onBack) wireBackButton(container);
}

