function cardIcon(systemImage: string): string {
  const path = CARD_ICONS[systemImage] ?? CARD_ICONS["doc.text.fill"];
  return `<svg viewBox="0 0 24 24" aria-hidden="true">${path}</svg>`;
}

const AVAILABILITY_LABEL: Record<CaseHubCardDefinition["availability"], string> = {
  implemented: "AVAILABLE",
  partial: "PARTIAL",
  unavailable: "UNAVAILABLE",
};

function caseHubSectionHtml(sectionId: string, title: string, caseId: string, investigationCompleted: boolean): string {
  const cards = cardsInSection(sectionId as "workflow" | "tools" | "support");
  return `
    <section class="casehub-section" data-section="${esc(sectionId)}" aria-labelledby="casehub-section-${esc(sectionId)}">
      <h3 class="casehub-section-title" id="casehub-section-${esc(sectionId)}">${esc(title)}</h3>
      ${cards.length === 0
        ? `<div class="casehub-reserved" aria-disabled="true">
             <strong>Reserved for additional tools</strong>
             <span class="cc-meta">This section is ready for future investigation modules.</span>
           </div>`
        : `<div class="casehub-card-list">
            ${cards.map((card) => caseHubCardHtml(card, caseId, investigationCompleted)).join("")}
          </div>`}
    </section>`;
}

function caseHubCardHtml(card: CaseHubCardDefinition, caseId: string, investigationCompleted: boolean): string {
  const unavailable = card.availability === "unavailable";
  const locked = card.id === "evidenceReview" && !investigationCompleted;
  const badgeClass = locked || card.availability !== "implemented" ? "status-badge pending" : "status-badge";
  const badgeLabel = locked ? "LOCKED" : AVAILABILITY_LABEL[card.availability];
  return `
    <button class="hub-card casehub-card${unavailable ? " unavailable" : ""}${locked ? " review-locked" : ""}" type="button"
      data-card="${esc(card.id)}" data-case-id="${esc(caseId)}"
      data-availability="${card.availability}" data-destination="${esc(card.destination ?? "")}"
      data-review-locked="${locked ? "true" : "false"}"
      ${unavailable ? 'aria-disabled="true"' : ""}
      aria-label="${esc(card.title)} — ${locked ? "LOCKED" : AVAILABILITY_LABEL[card.availability]}">
      <span class="casehub-card-icon" aria-hidden="true">${cardIcon(card.systemImage)}</span>
      <span class="casehub-card-text">
        <span class="case-title">${esc(card.title)}</span>
        <span class="case-meta">${esc(card.subtitle)}</span>
        ${card.limitation ? `<span class="cc-meta casehub-card-limit">${esc(card.limitation)}</span>` : ""}
        ${locked ? `<span class="cc-meta casehub-card-limit" data-review-locked-note>Investigation completion is required before Evidence Review opens.</span>` : ""}
      </span>
      <span class="${badgeClass}">${badgeLabel}</span>
    </button>`;
}

function caseWorkspaceHtml(
  record: CaseRecord,
  data: {
    structure?: PropertyStructureRecord;
    rooms: RoomRecord[];
    baselines: BaselineRecord[];
    sessions: InvestigationSessionRecord[];
    walkthroughSessions: Array<{ status: string; completedAt: number | null }>;
    investigationCompletion?: InvestigationCompletion;
    location?: { name: string; street?: string; city?: string; state?: string; propertyDetails?: string };
  },
): string {
  const { structure, rooms, baselines, sessions, walkthroughSessions, investigationCompletion, location } = data;
  const activeSession = sessions.find((session) => session.status === "active" || session.status === "paused");
  const selectedRoomId = activeSession?.currentRoomId
    ?? selectedRoomByCase.get(record.id)
    ?? localStorage.getItem(`tpi-casehub-room:${record.id}`)
    ?? "";
  const selectedRoom = rooms.find((room) => room.id === selectedRoomId);
  const address = [record.street?.trim() || location?.street, record.city?.trim() || location?.city, record.state?.trim() || location?.state, record.zip]
    .filter((part) => part?.trim()).join(", ");
  const latestWalkthrough = walkthroughSessions.slice().sort((a, b) => (b.completedAt ?? 0) - (a.completedAt ?? 0))[0];
  const walkthroughStatus = latestWalkthrough?.status === "completed"
    ? "Complete"
    : latestWalkthrough ? "In Progress" : "Not Started";
  const baselineComplete = rooms.length > 0 && rooms.every((room) => {
    const baseline = baselines.find((item) => item.roomId === room.id);
    return Boolean(baseline?.baselineStart && baseline.baselineEnd && baseline.baselineSummary.trim()
      && baseline.baselineMarkedComplete && baseline.driftChecked && !baseline.driftDetected);
  });
  const baselineLabel = rooms.length === 0 ? "No rooms selected" : baselineComplete ? "Complete" : "Incomplete";
  const currentRoomLabel = selectedRoom?.name ?? (selectedRoomId ? "Room unavailable" : "Unassigned");
  let sensorPreferences: Record<string, boolean> = {};
  try { sensorPreferences = JSON.parse(localStorage.getItem(`tpi-casehub-sensors:${record.id}`) ?? "{}"); } catch { sensorPreferences = {}; }
  const canStart = rooms.length > 0 && Boolean(selectedRoomId) && baselineComplete && record.status !== "archived";
  const investigationPhaseIdx = WORKFLOW_PHASE_ORDER.indexOf("investigation");
  const completionAvailable = WORKFLOW_PHASE_ORDER.indexOf(record.currentPhase) >= investigationPhaseIdx;
  const completionHtml = investigationCompletion
    ? `<p class="cc-session-state" data-investigation-completion="complete" role="status">Investigation completed ${esc(fmtTime(investigationCompletion.completedAt))}. Evidence Review is unlocked for this case.</p>`
    : completionAvailable
      ? `<p class="cc-meta" data-investigation-completion="pending">Investigation completion has not been recorded. Ending a session does not complete the investigation, and Evidence Review remains locked.</p>
         <button class="button-secondary" id="hub-complete-investigation" data-case-id="${esc(record.id)}" type="button">Complete Investigation</button>`
      : `<p class="cc-meta" data-investigation-completion="unavailable">Investigation completion becomes available after the workflow reaches the Investigation phase. Evidence Review remains locked until then.</p>`;
  const sessionAction = activeSession
    ? `<p class="cc-session-state" role="status">${activeSession.status === "paused" ? "Investigation paused" : "Active Investigation"}${activeSession.startedAt ? ` • started ${esc(new Date(activeSession.startedAt).toLocaleTimeString())}` : ""}</p>
       <button class="button-secondary" id="hub-end-investigation" data-session-id="${esc(activeSession.id)}" type="button">End Session</button>`
    : `<label class="cc-inline-label" for="hub-investigator">Investigator</label>
       <input id="hub-investigator" type="text" placeholder="Investigator name (optional)" />
       <button class="button-primary" id="hub-start-investigation" data-case-id="${esc(record.id)}" data-room-id="${esc(selectedRoomId)}" type="button" ${canStart ? "" : "disabled"}>Start Investigation</button>
       ${canStart ? "" : `<p class="cc-meta">Investigation start requires a selected room and a complete baseline. Existing baseline records are never replaced here.</p>`}`;

  return `
    <div class="cc-case-workspace">
      <section class="cc-native-card cc-native-header" data-card="overview" aria-labelledby="case-workspace-title">
        <p class="cc-org-name">THE PARANORMAL INITIATIVE</p>
        <h1 id="case-workspace-title">${esc(record.title)}</h1>
        <div class="cc-native-meta">
          <span>Investigation date: Not recorded</span>
          <span>Case created: ${new Date(record.createdAt).toLocaleDateString()}</span>
          <span>Case: ${esc(record.caseNumber)}</span>
          <span>Investigation classification: ${esc(investigationTypeLabel(record.investigationType))}</span>
          <span>Property: ${esc(location?.name ?? "Not recorded")}</span>
        </div>
        <p class="cc-native-summary">${esc(record.notes?.trim() || "No case description recorded.")}</p>
        <div class="cc-native-meta" style="margin-top:8px">
          <span>Address: ${esc(address || "Not recorded")}</span>
          <span>Location classification: Not recorded</span>
          ${location?.propertyDetails ? `<span>Location information: ${esc(location.propertyDetails)}</span>` : ""}
        </div>
      </section>

      <section class="cc-native-card" data-panel="investigation-status" aria-labelledby="investigation-status-title">
        <h3 id="investigation-status-title">Investigation Status</h3>
        <div class="cc-native-facts">
          <div class="cc-native-fact"><strong>Phase</strong>${esc(record.currentPhase)}</div>
          <div class="cc-native-fact"><strong>Current room</strong>${esc(currentRoomLabel)}</div>
          <div class="cc-native-fact"><strong>Room count</strong>${rooms.length}</div>
          <div class="cc-native-fact"><strong>Walkthrough</strong>${walkthroughStatus}</div>
          <div class="cc-native-fact"><strong>Property access</strong>Not recorded</div>
          <div class="cc-native-fact"><strong>Structure type</strong>${esc(structure?.kind ?? "Not recorded")}</div>
          <div class="cc-native-fact"><strong>Baseline</strong>${baselineLabel}</div>
          <div class="cc-native-fact"><strong>Investigation status</strong>${activeSession ? esc(activeSession.status) : "Not started"}</div>
        </div>
      </section>

      <section class="cc-native-card" aria-labelledby="baseline-progress-title">
        <h3 id="baseline-progress-title">Baseline Progress (Per Room)</h3>
        ${rooms.length === 0 ? `<p class="cc-meta">No rooms selected. Define the property structure and walkthrough plan first.</p>` : rooms.map((room, index) => {
          const baseline = baselines.find((item) => item.roomId === room.id);
          const complete = Boolean(baseline?.baselineStart && baseline.baselineEnd && baseline.baselineSummary.trim()
            && baseline.baselineMarkedComplete && baseline.driftChecked && !baseline.driftDetected);
          const started = Boolean(baseline?.baselineStart || baseline?.baselineEnd || baseline?.baselineSummary.trim());
          const label = complete ? "Complete" : started ? "In Progress" : "Not Started";
          return `<div class="cc-baseline-row"><strong>${index + 1}. ${esc(room.name)}</strong><span> — ${label}</span>
            <div class="cc-native-meta"><span>Start: ${baseline?.baselineStart ? esc(new Date(baseline.baselineStart).toLocaleTimeString()) : "—"}</span><span>End: ${baseline?.baselineEnd ? esc(new Date(baseline.baselineEnd).toLocaleTimeString()) : "—"}</span><span>Summary: ${baseline?.baselineSummary.trim() ? "Saved" : "Missing"}</span></div>
          </div>`;
        }).join("")}
      </section>

      <section class="cc-native-card" aria-labelledby="session-controls-title">
        <h3 id="session-controls-title">Session Controls</h3>
        ${rooms.length ? `<div class="cc-room-order"><strong style="width:100%;font-size:12px;color:var(--text-secondary)">Investigation Room Order</strong>
          ${rooms.map((room, index) => `<button type="button" class="cc-room-chip" data-hub-room="${esc(room.id)}" data-case-id="${esc(record.id)}" data-room-name="${esc(room.name)}" aria-pressed="${room.id === selectedRoomId}">${index + 1}. ${esc(room.name)}</button>`).join("")}</div>` : `<p class="cc-meta">No rooms are currently defined.</p>`}
        <div class="cc-sensor-controls" aria-label="Investigation sensor controls">
          ${([["EMF", "emf"], ["Motion", "motion"], ["Noise", "noise"]] as const).map(([label, key]) => `<label class="cc-sensor-toggle">${label}<input type="checkbox" data-sensor-toggle="${key}" ${sensorPreferences[key] === false ? "" : "checked"} aria-label="Use ${label} during investigation"></label>`).join("")}
        </div>
        <p class="cc-meta">Sensor switches are session preferences only; this browser does not fabricate or imply live hardware readings.</p>
        ${sessionAction}
        ${completionHtml}
        <button class="button-secondary" id="hub-reset-investigation" type="button" disabled aria-describedby="hub-reset-note">Reset Investigation</button>
        <p class="cc-meta" id="hub-reset-note">Reset is unavailable here because this browser build cannot safely reset baseline or session history. Existing records are preserved.</p>
      </section>

      <section class="cc-native-card" aria-labelledby="case-workflow-title">
        <h3 id="case-workflow-title">Case Workflow</h3>
        <div class="cc-native-meta"><span>Phase: ${esc(record.currentPhase)}</span><span>Current room: ${esc(currentRoomLabel)}</span><span>Rooms: ${rooms.length}</span><span>Walkthrough: ${walkthroughStatus}</span></div>
      </section>

      <section class="cc-native-card casehub-workspace" aria-labelledby="case-workspace-tools-title">
        <h3 id="case-workspace-tools-title">Case Workspace</h3>
        <p class="cc-meta">Browser operational workspaces attached to this case. These are retained from earlier browser work packages and are not part of the original Xcode card registry.</p>
        <div class="casehub-workspace-actions">
          <button class="workspace-action" type="button" data-card="structure" data-case-id="${esc(record.id)}">Property Structure</button>
          <button class="workspace-action" type="button" data-card="baseline" data-case-id="${esc(record.id)}">Environmental Baseline</button>
          <button class="workspace-action" type="button" data-card="session" data-case-id="${esc(record.id)}">Investigation Session</button>
          <button class="workspace-action" type="button" data-card="investigationNotes" data-case-id="${esc(record.id)}">Investigator Notes</button>
          <button class="workspace-action" type="button" data-card="evidence" data-case-id="${esc(record.id)}">Evidence Library</button>
          <button class="workspace-action" type="button" data-card="multimedia" data-case-id="${esc(record.id)}">Multimedia Capture</button>
          <button class="workspace-action" type="button" data-card="audioAnalysis" data-case-id="${esc(record.id)}">Audio Analysis</button>
          <button class="workspace-action" type="button" data-card="environmentalComparison" data-case-id="${esc(record.id)}">Environmental Comparison</button>
        </div>
      </section>
    </div>`;
}

function progressHtml(progress: WorkflowProgress, blockers: WorkflowBlocker[], caseId: string): string {
  return `
    <div class="hub-progress">
      <div class="progress-row"><span>Phase progression</span>
        <div class="meter" role="meter" aria-valuenow="${progress.phasePercent}" aria-valuemin="0" aria-valuemax="100" aria-label="Phase progression"><div class="fill" style="width:${progress.phasePercent}%"></div></div>
        <span class="pct">${progress.phasePercent}%</span></div>
      <div class="progress-row"><span>Required checklist complete</span>
        <div class="meter" role="meter" aria-valuenow="${progress.checklistPercent}" aria-valuemin="0" aria-valuemax="100" aria-label="Checklist completion"><div class="fill" style="width:${progress.checklistPercent}%"></div></div>
        <span class="pct">${progress.checklistPercent}%</span></div>
      <p class="cc-count">Readiness: <strong>${esc(progress.readiness)}</strong> • Outstanding required: ${progress.outstandingRequiredCount} • Blockers: ${progress.blockerCount} • Documented exceptions: ${progress.overrideCount}</p>
      <div class="form-actions">
        <button class="button-primary" id="hub-advance" data-case-id="${caseId}" type="button">Advance Workflow</button>
        ${blockers.length > 0 && blockers.every((b) => b.overridePermitted)
          ? `<button class="button-secondary" data-override-advance="${esc(caseId)}" type="button">Override Advance…</button>`
          : ""}
      </div>
    </div>`;
}

function nextStepsHtml(steps: NextStep[]): string {
  if (steps.length === 0) return `<div class="cc-empty">No next steps.</div>`;
  return steps
    .map(
      (s) => `
    <div class="case-row">
      <div><div class="case-title">${esc(s.action)}</div>
      <div class="case-meta">${s.phase ? `phase: ${esc(s.phase)}` : ""}${s.available ? "" : " • module pending"}</div></div>
    </div>`,
    )
    .join("");
}

function blockersHtml(blockers: WorkflowBlocker[]): string {
  if (blockers.length === 0) return `<div class="cc-empty">No blockers.</div>`;
  return blockers
    .map(
      (b) => `
    <div class="case-row" role="alert">
      <div>
        <div class="case-title">${esc(b.reason)}</div>
        <div class="case-meta">phase ${esc(b.phase)} • required action: ${esc(b.requiredAction)}${b.overridePermitted ? " • override permitted" : " • <strong>not overridable</strong>"}</div>
      </div>
      <span class="status-badge ${b.severity === "error" ? "error" : ""}">${esc(b.severity)}</span>
    </div>`,
    )
    .join("");
}

function checklistItemHtml(caseId: string, item: ChecklistItemRecord): string {
  const done = item.status === "complete";
  const exception = item.status === "exception";
  const na = item.status === "notApplicable";
  return `
    <div class="case-row checklist-item" data-item="${item.id}">
      <div>
        <div class="case-title">${done ? "✓" : exception ? "⚠" : na ? "—" : "□"} ${esc(item.title)} ${item.required ? '<span class="status-badge">required</span>' : '<span class="status-badge pending">optional</span>'}</div>
        <div class="case-meta">${esc(item.guidance ?? "")}${exception ? ` • exception: ${esc(item.notes)}` : ""}${na ? ` • reason: ${esc(item.notes)}` : ""}${done && item.completedAt ? ` • completed ${fmtTime(item.completedAt)}` : ""}</div>
      </div>
      <div style="display:flex;gap:6px;">
        ${done
          ? `<button class="back-button" data-check data-case-id="${caseId}" data-item-id="${item.id}" data-status="pending" type="button">Reopen</button>`
          : `<button class="back-button" data-check data-case-id="${caseId}" data-item-id="${item.id}" data-status="complete" type="button">Complete</button>
             <button class="back-button" data-check data-case-id="${caseId}" data-item-id="${item.id}" data-status="exception" type="button" data-justification="">Exception</button>
             <button class="back-button" data-na-reason data-case-id="${caseId}" data-item-id="${item.id}" type="button">N/A</button>`}
      </div>
    </div>`;
}

function toastError(message: string): void {
  const el = document.createElement("div");
  el.className = "toast error";
  el.setAttribute("role", "status");
  el.textContent = message;
  document.body.appendChild(el);
  setTimeout(() => el.remove(), 5000);
}
