/**
 * TPI-V2-WEB-019 — case-scoped report repository.
 *
 * WRITE BOUNDARY
 *   Draft operations touch only `caseReports`. Revision insertion touches only
 *   `caseReportRevisions` and the report's current-revision pointer. No method
 *   here changes evidence, claims, notes, sessions, measurements, observations,
 *   review state, readiness or closure state.
 *
 * FINALIZATION / AMENDMENTS
 *   `appendRevision` inserts one immutable revision, advances the current
 *   pointer, clears the editable amendment state and records an audit event in
 *   the same transaction. `startAmendment` copies the current finalized
 *   revision back into a working draft without changing that revision.
 *   Saving a draft never creates a revision.
 */
import { now, SCHEMA_VERSION, type TPIDatabase } from "../db";
import { v4 as uuidv4 } from "../../shared/uuid";
import { ValidationError } from "../validation";
import type {
  CaseReportRecord,
  CaseReportRevisionRecord,
  ReportContentSnapshot,
  ReportEligibilitySnapshot,
  ReportPrivacyReview,
  ReportSignoff,
  ReportSourceRef,
  ReportType,
} from "../types";
import {
  REPORT_TYPES,
  REPORT_TYPE_LABELS,
  emptyReportContent,
  hashReportContent,
  normalizeReportContent,
} from "./reportDraft";

export interface CreateReportDraftInput {
  caseId: string;
  reportType: ReportType;
  title?: string;
  content?: ReportContentSnapshot;
  author?: string;
  sourceRefs?: ReportSourceRef[];
}

export interface UpdateReportDraftInput {
  title?: string;
  content?: ReportContentSnapshot;
  author?: string;
  sourceRefs?: ReportSourceRef[];
}

export interface AppendReportRevisionInput {
  caseId: string;
  reportId: string;
  content: ReportContentSnapshot;
  sourceRefs?: ReportSourceRef[];
  eligibility: ReportEligibilitySnapshot;
  signoff: ReportSignoff;
  privacyReview?: ReportPrivacyReview | null;
  /** Optimistic concurrency guard used by the finalization service. */
  expectedCurrentRevisionId?: string | null;
  finalizedAt?: number;
}

function assertReportType(value: string): asserts value is ReportType {
  if (!REPORT_TYPES.includes(value as ReportType)) {
    throw new ValidationError(`Unknown report type: ${value}`, "reportType");
  }
}

function assertCaseId(caseId: string): void {
  if (!caseId?.trim()) throw new ValidationError("Case id is required.", "caseId");
}

function copyRefs(refs: readonly ReportSourceRef[] = []): ReportSourceRef[] {
  return refs.map((ref) => ({ ...ref }));
}

function copyPrivacyReview(review: ReportPrivacyReview | null | undefined): ReportPrivacyReview | null {
  if (!review) return null;
  return {
    ...review,
    flagsAcknowledged: [...review.flagsAcknowledged],
  };
}

function assertSignoff(signoff: ReportSignoff): void {
  if (!signoff.finalizedBy?.trim()) {
    throw new ValidationError("A finalizing investigator is required.", "signoff.finalizedBy");
  }
  if (!signoff.attestation?.trim()) {
    throw new ValidationError("A finalization attestation is required.", "signoff.attestation");
  }
  if (!Number.isFinite(signoff.signedAt)) {
    throw new ValidationError("A sign-off timestamp is required.", "signoff.signedAt");
  }
}

function assertEligibility(eligibility: ReportEligibilitySnapshot): void {
  if (!Number.isFinite(eligibility.capturedAt)) {
    throw new ValidationError("An eligibility capture timestamp is required.", "eligibility.capturedAt");
  }
  if (!Array.isArray(eligibility.blockers) || !Array.isArray(eligibility.warnings)) {
    throw new ValidationError("Eligibility blockers and warnings must be arrays.", "eligibility");
  }
}

export class CaseReportRepository {
  constructor(private readonly db: TPIDatabase) {}

  /** The unique case/type index is the authoritative one-report guarantee. */
  async get(caseId: string, reportType: ReportType): Promise<CaseReportRecord | undefined> {
    assertReportType(reportType);
    return this.db.caseReports
      .where("[caseId+reportType]")
      .equals([caseId, reportType])
      .first();
  }

  async getById(caseId: string, reportId: string): Promise<CaseReportRecord | undefined> {
    const report = await this.db.caseReports.get(reportId);
    return report && report.caseId === caseId ? report : undefined;
  }

  async listForCase(caseId: string): Promise<CaseReportRecord[]> {
    const rows = await this.db.caseReports.where("caseId").equals(caseId).toArray();
    return rows.sort(
      (a, b) =>
        REPORT_TYPES.indexOf(a.reportType) - REPORT_TYPES.indexOf(b.reportType) ||
        a.createdAt - b.createdAt,
    );
  }

  async createDraft(input: CreateReportDraftInput): Promise<CaseReportRecord> {
    assertCaseId(input.caseId);
    assertReportType(input.reportType);

    return this.db.transaction("rw", this.db.cases, this.db.caseReports, async () => {
      const caseRecord = await this.db.cases.get(input.caseId);
      if (!caseRecord) {
        throw new ValidationError(`Case not found: ${input.caseId}`, "caseId");
      }

      const duplicate = await this.db.caseReports
        .where("[caseId+reportType]")
        .equals([input.caseId, input.reportType])
        .first();
      if (duplicate) {
        throw new ValidationError(
          `A ${REPORT_TYPE_LABELS[input.reportType]} already exists for this case.`,
          "reportType",
        );
      }

      const title = (input.title?.trim() || REPORT_TYPE_LABELS[input.reportType]).trim();
      const draft = input.content
        ? normalizeReportContent(input.content, title)
        : emptyReportContent(title);
      const ts = now();
      const record: CaseReportRecord = {
        id: uuidv4(),
        schemaVersion: SCHEMA_VERSION as CaseReportRecord["schemaVersion"],
        caseId: input.caseId,
        reportType: input.reportType,
        title,
        draft: { ...draft, title },
        status: "draft",
        createdAt: ts,
        updatedAt: ts,
        currentRevisionId: null,
        draftBaseRevisionId: null,
        author: input.author?.trim() ?? "",
        sourceRefs: copyRefs(input.sourceRefs),
        privacyReview: null,
      };

      try {
        await this.db.caseReports.add(record);
      } catch (error) {
        if ((error as { name?: string }).name === "ConstraintError") {
          throw new ValidationError(
            `A ${REPORT_TYPE_LABELS[input.reportType]} already exists for this case.`,
            "reportType",
          );
        }
        throw error;
      }
      return record;
    });
  }

  /** Edits a draft only. Finalized revisions are never edited in place. */
  async updateDraft(
    caseId: string,
    reportId: string,
    input: UpdateReportDraftInput,
  ): Promise<CaseReportRecord> {
    assertCaseId(caseId);

    return this.db.transaction("rw", this.db.caseReports, async () => {
      const existing = await this.db.caseReports.get(reportId);
      // Foreign and missing reports are indistinguishable to the caller.
      if (!existing || existing.caseId !== caseId) {
        throw new ValidationError("Report not found for this case.", "reportId");
      }
      if (existing.status !== "draft" && existing.status !== "amendmentDraft") {
        throw new ValidationError(
          "Finalized reports are immutable. Create an amendment draft to propose changes.",
          "status",
        );
      }

      const title = (input.title ?? existing.title).trim();
      if (!title) throw new ValidationError("Report title is required.", "title");
      const draft = input.content
        ? normalizeReportContent(input.content, title)
        : { ...existing.draft, title };
      const next: CaseReportRecord = {
        ...existing,
        title,
        draft: { ...draft, title },
        author: input.author === undefined ? existing.author : input.author.trim(),
        sourceRefs: input.sourceRefs ? copyRefs(input.sourceRefs) : copyRefs(existing.sourceRefs),
        updatedAt: Math.max(now(), existing.updatedAt + 1),
      };
      await this.db.caseReports.put(next);
      return next;
    });
  }

  /**
   * Insert an immutable finalized revision. Repository-level infrastructure
   * for WEB-020 only; no WEB-019 UI path calls this method.
   */
  async appendRevision(input: AppendReportRevisionInput): Promise<CaseReportRevisionRecord> {
    assertCaseId(input.caseId);
    assertEligibility(input.eligibility);
    assertSignoff(input.signoff);

    // Hash outside the Dexie transaction: WebCrypto is not an IndexedDB
    // request, and awaiting it inside the transaction commits the transaction
    // early. The snapshot is immutable and its hash is computed before write.
    const existing = await this.db.caseReports.get(input.reportId);
    if (!existing || existing.caseId !== input.caseId) {
      throw new ValidationError("Report not found for this case.", "reportId");
    }
    const content = normalizeReportContent(input.content, existing.title);
    const contentHash = await hashReportContent(content);

    return this.db.transaction(
      "rw",
      this.db.caseReports,
      this.db.caseReportRevisions,
      this.db.auditEvents,
      async () => {
        const report = await this.db.caseReports.get(input.reportId);
        if (!report || report.caseId !== input.caseId) {
          throw new ValidationError("Report not found for this case.", "reportId");
        }
        if (
          input.expectedCurrentRevisionId !== undefined &&
          report.currentRevisionId !== input.expectedCurrentRevisionId
        ) {
          throw new ValidationError(
            "This report changed before finalization completed. Reload it and review the latest draft.",
            "currentRevisionId",
          );
        }

        const revisions = await this.db.caseReportRevisions
          .where("reportId")
          .equals(report.id)
          .toArray();
        const revisionNumber =
          revisions.reduce((max, revision) => Math.max(max, revision.revisionNumber), 0) + 1;
        const ts = input.finalizedAt ?? now();
        const privacyReview = copyPrivacyReview(input.privacyReview ?? report.privacyReview);
        const revision: CaseReportRevisionRecord = {
          id: uuidv4(),
          schemaVersion: SCHEMA_VERSION as CaseReportRevisionRecord["schemaVersion"],
          reportId: report.id,
          caseId: report.caseId,
          reportType: report.reportType,
          revisionNumber,
          finalizedAt: ts,
          content,
          contentHash,
          sourceRefs: copyRefs(input.sourceRefs ?? report.sourceRefs),
          eligibility: {
            ...input.eligibility,
            blockers: [...input.eligibility.blockers],
            warnings: [...input.eligibility.warnings],
          },
          signoff: { ...input.signoff, finalizedBy: input.signoff.finalizedBy.trim(), attestation: input.signoff.attestation.trim() },
          privacyReview,
          supersedesRevisionId: report.currentRevisionId,
          createdAt: ts,
        };

        try {
          await this.db.caseReportRevisions.add(revision);
        } catch (error) {
          if ((error as { name?: string }).name === "ConstraintError") {
            throw new ValidationError(
              "A revision with that number already exists for this report.",
              "revisionNumber",
            );
          }
          throw error;
        }
        await this.db.caseReports.put({
          ...report,
          status: "final",
          currentRevisionId: revision.id,
          draftBaseRevisionId: null,
          draft: content,
          title: content.title,
          privacyReview,
          sourceRefs: copyRefs(input.sourceRefs ?? report.sourceRefs),
          updatedAt: Math.max(now(), report.updatedAt + 1),
        });
        await this.db.auditEvents.add({
          id: uuidv4(),
          schemaVersion: SCHEMA_VERSION,
          createdAt: Math.max(now(), revision.finalizedAt),
          type: "reportFinalized",
          detail: `${REPORT_TYPE_LABELS[report.reportType]} revision ${revision.revisionNumber} finalized`,
          caseId: report.caseId,
          affectedRecordId: revision.id,
          metadata: {
            reportId: report.id,
            revisionNumber: revision.revisionNumber,
            contentHash: revision.contentHash,
            reportType: report.reportType,
          },
        });
        return revision;
      },
    );
  }

  /**
   * Start an amendment from the current finalized revision. The revision row
   * is not touched; only the report's editable working state changes.
   */
  async startAmendment(caseId: string, reportId: string): Promise<CaseReportRecord> {
    assertCaseId(caseId);
    return this.db.transaction(
      "rw",
      this.db.caseReports,
      this.db.caseReportRevisions,
      this.db.auditEvents,
      async () => {
        const report = await this.db.caseReports.get(reportId);
        if (!report || report.caseId !== caseId) {
          throw new ValidationError("Report not found for this case.", "reportId");
        }
        if (report.status !== "final" || !report.currentRevisionId) {
          throw new ValidationError("Only a finalized report can be amended.", "status");
        }
        const base = await this.db.caseReportRevisions.get(report.currentRevisionId);
        if (!base || base.reportId !== report.id || base.caseId !== caseId) {
          throw new ValidationError("The current finalized revision is unavailable.", "currentRevisionId");
        }
        const ts = Math.max(now(), report.updatedAt + 1);
        const next: CaseReportRecord = {
          ...report,
          status: "amendmentDraft",
          draftBaseRevisionId: base.id,
          draft: {
            ...base.content,
            title: base.content.title,
            sections: base.content.sections.map((section) => ({ ...section })),
          },
          title: base.content.title,
          privacyReview: null,
          sourceRefs: copyRefs(base.sourceRefs),
          updatedAt: ts,
        };
        await this.db.caseReports.put(next);
        await this.db.auditEvents.add({
          id: uuidv4(),
          schemaVersion: SCHEMA_VERSION,
          createdAt: ts,
          type: "reportAmendmentStarted",
          detail: `${REPORT_TYPE_LABELS[report.reportType]} amendment started from revision ${base.revisionNumber}`,
          caseId,
          affectedRecordId: report.id,
          metadata: { reportId: report.id, baseRevisionId: base.id, baseRevisionNumber: base.revisionNumber },
        });
        return next;
      },
    );
  }

  /** Abandon an amendment without deleting or rewriting the finalized revision. */
  async discardAmendment(caseId: string, reportId: string): Promise<CaseReportRecord> {
    assertCaseId(caseId);
    return this.db.transaction(
      "rw",
      this.db.caseReports,
      this.db.caseReportRevisions,
      this.db.auditEvents,
      async () => {
        const report = await this.db.caseReports.get(reportId);
        if (!report || report.caseId !== caseId) {
          throw new ValidationError("Report not found for this case.", "reportId");
        }
        if (report.status !== "amendmentDraft" || !report.draftBaseRevisionId) {
          throw new ValidationError("There is no amendment draft to discard.", "status");
        }
        const base = await this.db.caseReportRevisions.get(report.draftBaseRevisionId);
        if (!base || base.reportId !== report.id || base.caseId !== caseId) {
          throw new ValidationError("The amendment base revision is unavailable.", "draftBaseRevisionId");
        }
        const ts = Math.max(now(), report.updatedAt + 1);
        const next: CaseReportRecord = {
          ...report,
          status: "final",
          currentRevisionId: base.id,
          draftBaseRevisionId: null,
          draft: {
            ...base.content,
            sections: base.content.sections.map((section) => ({ ...section })),
          },
          title: base.content.title,
          sourceRefs: copyRefs(base.sourceRefs),
          privacyReview: base.privacyReview ?? null,
          updatedAt: ts,
        };
        await this.db.caseReports.put(next);
        await this.db.auditEvents.add({
          id: uuidv4(),
          schemaVersion: SCHEMA_VERSION,
          createdAt: ts,
          type: "reportAmendmentDiscarded",
          detail: `${REPORT_TYPE_LABELS[report.reportType]} amendment discarded; revision ${base.revisionNumber} remains current`,
          caseId,
          affectedRecordId: report.id,
          metadata: { reportId: report.id, baseRevisionId: base.id, baseRevisionNumber: base.revisionNumber },
        });
        return next;
      },
    );
  }

  async getRevision(caseId: string, revisionId: string): Promise<CaseReportRevisionRecord | undefined> {
    const revision = await this.db.caseReportRevisions.get(revisionId);
    return revision && revision.caseId === caseId ? revision : undefined;
  }

  /** Read-only, newest first. There is no updateRevision or deleteRevision. */
  async listRevisions(caseId: string, reportId: string): Promise<CaseReportRevisionRecord[]> {
    const report = await this.db.caseReports.get(reportId);
    if (!report || report.caseId !== caseId) return [];
    const rows = await this.db.caseReportRevisions.where("reportId").equals(reportId).toArray();
    return rows.sort((a, b) => b.revisionNumber - a.revisionNumber);
  }

  async listForCaseWithRevisions(
    caseId: string,
  ): Promise<Array<{ report: CaseReportRecord; revisions: CaseReportRevisionRecord[] }>> {
    const reports = await this.listForCase(caseId);
    return Promise.all(
      reports.map(async (report) => ({
        report,
        revisions: await this.listRevisions(caseId, report.id),
      })),
    );
  }
}
