/**
 * TPI-V2-WEB-020 — client-report privacy review.
 *
 * This is deliberately an ADVISORY screen, not an automated redactor and not a
 * confidentiality guarantee. It looks for recorded client/location values and
 * common personal-information patterns in the report text, then requires the
 * investigator to acknowledge the result and explicitly approve the content
 * for client distribution. The investigator remains responsible for the final
 * text; WEB-019's client starter allowlist remains the default source boundary.
 */
import type { ReportContentSnapshot, ReportPrivacyReview } from "../types";
import type { CaseReportModel } from "./caseReport";

export const CLIENT_PRIVACY_ATTESTATION =
  "I reviewed this client report for private, internal or sensitive information and confirm it is appropriate for client distribution.";

export const FINALIZATION_ATTESTATION =
  "I intentionally finalize this report and accept responsibility for the content recorded under my name.";

export const CLOSURE_ACKNOWLEDGEMENT =
  "I intentionally close this investigation and confirm that the referenced finalized report revision is the basis for closure.";

export interface PrivacyFlag {
  id: string;
  label: string;
  detail: string;
}

function normalized(value: string): string {
  return value.toLowerCase().replace(/\s+/g, " ").trim();
}

function contentText(content: ReportContentSnapshot): string {
  return normalized(
    [content.title, ...content.sections.map((section) => `${section.heading}\n${section.body}`)].join("\n"),
  );
}

function containsValue(text: string, value: string | null | undefined, minLength = 3): boolean {
  if (!value) return false;
  const candidate = normalized(value);
  return candidate.length >= minLength && text.includes(candidate);
}

/**
 * Find phone-shaped candidates without turning every number in a report into a
 * warning. Application references and dates are commonly year-first
 * (`TPI-2026-0001`, `2026-11-13`, `RPT-2026-0001`) or letter-prefixed
 * identifiers; those shapes are deliberately excluded before the remaining
 * candidates are classified by digit count/format. This is advisory only.
 */
const PHONE_CANDIDATE = /(?:\+?\d|\(\d)[\d\s().-]{5,}\d/g;

function isAttachedToIdentifier(text: string, index: number): boolean {
  const prefix = text.slice(Math.max(0, index - 48), index);
  // A candidate glued to a letter/number is part of a larger identifier.
  if (/[a-z0-9]$/i.test(prefix)) return true;
  // Structured references normally use a separator: TPI-2026-0001, RPT-..., etc.
  return /[a-z][a-z0-9._]*[-_/]$/i.test(prefix);
}

function isStructuredNumber(candidate: string): boolean {
  const compact = candidate.trim().replace(/\s+/g, "");
  const digits = compact.replace(/\D/g, "");
  // Application identifiers and ISO dates begin with a four-digit year.
  if (/^(?:19|20)\d{2}[-_./]\d{4}(?:[-_./]\d{1,4})?$/.test(compact)) return true;
  if (/^(?:19|20)\d{2}[-_./]\d{1,2}[-_./]\d{1,2}$/.test(compact)) return true;
  // Four+four groups and short numeric dates are not telephone formats.
  if (/^\d{4}[-_./]\d{4}$/.test(compact)) return true;
  if (/^\d{1,2}[-_./]\d{1,2}[-_./]\d{2,4}$/.test(compact) && digits.length === 8) return true;
  return false;
}

function isPlausiblePhone(candidate: string): boolean {
  const compact = candidate.trim().replace(/\s+/g, " ");
  const digits = compact.replace(/\D/g, "");
  if (candidate.trimStart().startsWith("+")) return digits.length >= 8 && digits.length <= 15;
  if (digits.length === 10) return true;
  if (digits.length === 11 && digits.startsWith("1")) return true;
  // Seven-digit local numbers are accepted only in the common 3-4 form.
  return digits.length === 7 && /^\d{3}[-. ]\d{4}$/.test(compact);
}

/**
 * Public for focused tests and diagnostics. Returns only plausible telephone
 * candidates; it does not decide whether showing one is appropriate.
 */
export function findPhoneLikeText(text: string): string[] {
  const normalizedText = normalized(text);
  const found: string[] = [];
  for (const match of normalizedText.matchAll(PHONE_CANDIDATE)) {
    const candidate = match[0];
    const index = match.index ?? 0;
    if (isAttachedToIdentifier(normalizedText, index)) continue;
    if (isStructuredNumber(candidate)) continue;
    if (!isPlausiblePhone(candidate)) continue;
    found.push(candidate);
  }
  return found;
}

function containsPhone(text: string, phone: string | null | undefined): boolean {
  if (!phone) return false;
  const digits = phone.replace(/\D/g, "");
  if (digits.length < 7) return false;
  return findPhoneLikeText(text).some((candidate) => candidate.replace(/\D/g, "") === digits);
}

/**
 * Return potential issues only. An empty array means "nothing obvious was
 * detected", never "safe for distribution".
 */
export function scanClientReportPrivacy(
  content: ReportContentSnapshot,
  model: CaseReportModel,
): PrivacyFlag[] {
  const text = contentText(content);
  const flags: PrivacyFlag[] = [];
  const add = (id: string, label: string, detail: string): void => {
    if (!flags.some((flag) => flag.id === id)) flags.push({ id, label, detail });
  };

  if (containsValue(text, model.client.name)) {
    add("client-name", "Client name may appear", "The report text contains the client name recorded on this case.");
  }
  if (containsValue(text, model.client.email)) {
    add("client-email", "Client email may appear", "The report text contains the client email recorded on this case.");
  }
  if (containsPhone(text, model.client.phone)) {
    add("client-phone", "Client phone may appear", "The report text contains the client phone number recorded on this case.");
  }
  if (containsValue(text, model.location.address, 6)) {
    add("location-address", "Street address may appear", "The report text contains the address recorded on this case.");
  }
  if (containsValue(text, model.client.notes, 8)) {
    add("client-notes", "Private client-note text may appear", "The report text contains text also recorded in the client's private notes.");
  }
  if (containsValue(text, model.location.propertyDetails, 8)) {
    add("property-details", "Private property details may appear", "The report text contains property details recorded in the internal case file.");
  }

  if (/\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/i.test(text)) {
    add("email-pattern", "Email-like text detected", "An email-shaped string appears in the report. Confirm it is intended for the client.");
  }
  if (findPhoneLikeText(text).length > 0) {
    add("phone-pattern", "Phone-like text detected", "A phone-number-shaped string appears in the report. Confirm it is intended for the client.");
  }

  for (const evidence of model.evidence) {
    if (evidence.fileName && containsValue(text, evidence.fileName, 4)) {
      add("evidence-filename", "Internal evidence file name may appear", "An internal evidence file name appears in the client report.");
      break;
    }
  }

  for (const [id, label, detail] of [
    ["internal-commentary", "Internal commentary language detected", "The text contains wording such as \"internal\" or \"do not share\". Confirm it is appropriate for the client."],
    ["confidential-witness", "Witness confidentiality language detected", "The text contains wording about confidential witnesses. Confirm client disclosure is authorized."],
  ] as const) {
    if (text.includes(id === "internal-commentary" ? "internal" : "confidential witness")) {
      add(id, label, detail);
    }
  }

  return flags;
}

export function privacyReviewIsComplete(
  review: ReportPrivacyReview | null | undefined,
  flags: readonly PrivacyFlag[],
): boolean {
  if (!review?.confirmed || !review.reviewedBy.trim()) return false;
  if (review.attestation.trim() !== CLIENT_PRIVACY_ATTESTATION) return false;
  return flags.every((flag) => review.flagsAcknowledged.includes(flag.id));
}
