/**
 * Authoritative case workflow service (TPI-V2-WEB-004 §11).
 *
 * THE single workflow authority for case lifecycle state. UI components and
 * future Mystic integration must consume this service — they must never
 * compute or mutate case status themselves. Mystic may *request* transitions
 * through this service but cannot bypass validation.
 *
 * Phase model mirrors iOS `PPCaseWorkflowPhase` (caseCreation → intake →
 * walkthrough → baseline → investigation → review → summary). The status
 * lifecycle distinguishes New/Intake/… presentation from the archived state.
 */
import type { TPIDatabase } from "../db";
import { CaseRepository } from "../repositories/caseRepository";
import { AuditService } from "../audit";
export { ChecklistService, CANONICAL_CHECKLIST } from "./checklistService";
import type { CaseRecord, CaseStatus, WorkflowPhase } from "../types";
import { ValidationError } from "../validation";
import { DocumentService, type DocumentsBlocker } from "../documents/documentService";
import { IntakeService, type IntakeEvaluation } from "../intake/intakeService";
import { PropertyService } from "../property/propertyService";
import { WalkthroughService, type WalkthroughBlocker } from "../property/walkthroughService";
import { BaselineService, type BaselineBlocker } from "../environment/baselineService";
import { SessionService } from "../session/sessionService";
import { EvidenceReviewService, type EvidenceReviewBlocker } from "../evidence/evidenceReviewService";
import { InvestigationCompletionService } from "./investigationCompletionService";

/**
 * Canonical workflow phase order — reconciled from the iOS source audit
 * (TPI-V2-WEB-005 §6): `PPFrontHalfWorkflowPhase` contributes the documents
 * and investigationReady gates; `PPCaseWorkflowPhase` contributes review and
 * summary. Legacy 7-phase browser records map through migration v5.
 */
export const WORKFLOW_PHASE_ORDER: readonly WorkflowPhase[] = [
  "caseCreation",
  "documents",
  "intake",
  "walkthrough",
  "baseline",
  "investigationReady",
  "investigation",
  "review",
  "summary",
];

/** User-facing lifecycle states derived from case records. */
export type LifecycleStage =
  | "new"
  | "intake"
  | "assessment"
  | "planning"
  | "investigation"
  | "evidenceReview"
  | "reporting"
  | "closed"
  | "archived";

/**
 * Presentation mapping from workflow phases (reconciled with the iOS model —
 * the original uses the seven phases above; the richer stage vocabulary maps
 * onto them without creating a second authority).
 */
const PHASE_TO_STAGE: Record<WorkflowPhase, LifecycleStage> = {
  caseCreation: "new",
  documents: "intake",
  intake: "intake",
  walkthrough: "assessment",
  baseline: "planning",
  investigationReady: "planning",
  investigation: "investigation",
  review: "evidenceReview",
  summary: "reporting",
};

export class WorkflowService {
  private readonly cases: CaseRepository;
  private readonly audit: AuditService;

  constructor(private readonly db: TPIDatabase) {
    this.cases = new CaseRepository(db);
    this.audit = new AuditService(db);
  }

  /** Workflow stage as presented in the interface. */
  lifecycleStage(caseRecord: CaseRecord): LifecycleStage {
    if (caseRecord.status === "archived") return "archived";
    if (caseRecord.isClosed) return "closed";
    return PHASE_TO_STAGE[caseRecord.currentPhase];
  }

  /** Ordered phases with the current one marked (for navigation UIs). */
  phaseTimeline(caseRecord: CaseRecord): Array<{ phase: WorkflowPhase; current: boolean; index: number }> {
    const current = WORKFLOW_PHASE_ORDER.indexOf(caseRecord.currentPhase);
    return WORKFLOW_PHASE_ORDER.map((phase, index) => ({
      phase,
      current: index === current,
      index,
    }));
  }

  /** Phases the case has not yet reached (forward moves only). */
  canAdvanceTo(phase: WorkflowPhase, caseRecord: CaseRecord): boolean {
    const currentIdx = WORKFLOW_PHASE_ORDER.indexOf(caseRecord.currentPhase);
    const targetIdx = WORKFLOW_PHASE_ORDER.indexOf(phase);
    return targetIdx === currentIdx + 1;
  }

  /**
   * Move a case to a workflow phase. Forward-only, one step at a time.
   * Backward/recovery moves are manual-only via explicit business decision
   * (recorded as an audit event) and use `movePhaseManually`.
   */
  async advancePhase(caseId: string): Promise<CaseRecord | undefined> {
    return this.db.transaction("rw", this.db.cases, this.db.auditEvents, async () => {
      const record = await this.db.cases.get(caseId);
      if (!record) throw new ValidationError(`Case not found: ${caseId}`, "caseId");
      if (record.status === "archived") {
        throw new ValidationError("Archived cases cannot advance workflow", "status");
      }
      const currentIdx = WORKFLOW_PHASE_ORDER.indexOf(record.currentPhase);
      if (currentIdx === WORKFLOW_PHASE_ORDER.length - 1) {
        throw new ValidationError("Case is already at the final workflow phase", "currentPhase");
      }
      const nextPhase = WORKFLOW_PHASE_ORDER[currentIdx + 1] as WorkflowPhase;
      const next: CaseRecord = { ...record, currentPhase: nextPhase, updatedAt: Date.now() };
      await this.db.cases.put(next);
      await this.audit.record("statusChanged", `Workflow advanced to ${nextPhase}`, {
        caseId,
        affectedRecordId: caseId,
        metadata: { phase: nextPhase },
      });
      return next;
    });
  }

  /** Manual phase correction (audit-recorded; used sparingly, never auto-driven). */
  async movePhaseManually(caseId: string, target: WorkflowPhase, reason: string): Promise<CaseRecord | undefined> {
    if (!reason.trim()) {
      throw new ValidationError("A reason is required for manual phase changes", "reason");
    }
    return this.db.transaction("rw", this.db.cases, this.db.auditEvents, async () => {
      const record = await this.db.cases.get(caseId);
      if (!record) throw new ValidationError(`Case not found: ${caseId}`, "caseId");
      const next: CaseRecord = { ...record, currentPhase: target, updatedAt: Date.now() };
      await this.db.cases.put(next);
      await this.audit.record("statusChanged", `Manual phase change: ${target} — ${reason.slice(0, 200)}`, {
        caseId,
        affectedRecordId: caseId,
        metadata: { phase: target, manual: true },
      });
      return next;
    });
  }

  /** Controlled lifecycle status change (delegates to the case repository). */
  async setStatus(caseId: string, status: CaseStatus, archiveNote?: string): Promise<CaseRecord | undefined> {
    return this.cases.setCaseStatus(caseId, status, archiveNote);
  }
}

/* ============================================================
 * TPI-V2-WEB-005 — Checklist, blockers, readiness, overrides,
 * progress, and next-step recommendations.
 * ============================================================ */


export type ReadinessState = "incomplete" | "blocked" | "ready" | "overridden";

export interface WorkflowBlocker {
  id: string;
  phase: WorkflowPhase;
  reason: string;
  severity: "error" | "warning";
  requiredAction: string;
  /** Whether an investigator exception may satisfy this blocker. */
  overridePermitted: boolean;
  sourceRecordId?: string;
}

export interface WorkflowProgress {
  /** Completed phases ÷ phases before the current one (0–100). */
  phasePercent: number;
  /** Completed required checklist items ÷ total required items (0–100). */
  checklistPercent: number;
  readiness: ReadinessState;
  outstandingRequiredCount: number;
  blockerCount: number;
  overrideCount: number;
}

export interface NextStep {
  action: string;
  phase: WorkflowPhase | null;
  /** Where to navigate in the UI, or null when unavailable in this build. */
  destination: string | null;
  available: boolean;
}

export class WorkflowReadinessService {
  constructor(private readonly db: TPIDatabase) {}

  private get audit(): AuditService {
    return new AuditService(this.db);
  }

  /** Evaluate the case workflow: readiness state, blockers, and progress. */
  async evaluate(caseId: string): Promise<{
    state: ReadinessState;
    blockers: WorkflowBlocker[];
    progress: WorkflowProgress;
    nextSteps: NextStep[];
  } | undefined> {
    const record = await this.db.cases.get(caseId);
    if (!record) return undefined;
    const items = await this.db.checklistItems.where("caseId").equals(caseId).sortBy("createdAt");
    const phaseIdx = WORKFLOW_PHASE_ORDER.indexOf(record.currentPhase);

    const blockers: WorkflowBlocker[] = [];

    // TPI-V2-WEB-006 §10: documents + intake phase readiness is derived from
    // REAL persisted records — never from checklist checkboxes alone.
    const documentsIdx = WORKFLOW_PHASE_ORDER.indexOf("documents");
    const intakeIdx = WORKFLOW_PHASE_ORDER.indexOf("intake");
    let documentsBlockers: DocumentsBlocker[] = [];
    let intakeEvaluation: IntakeEvaluation | undefined;
    let walkthroughBlockers: WalkthroughBlocker[] = [];
    const walkthroughIdx = WORKFLOW_PHASE_ORDER.indexOf("walkthrough");
    const baselineIdx = WORKFLOW_PHASE_ORDER.indexOf("baseline");
    const reviewIdx = WORKFLOW_PHASE_ORDER.indexOf("review");
    const investigationIdx = WORKFLOW_PHASE_ORDER.indexOf("investigation");
    if (phaseIdx >= documentsIdx) {
      documentsBlockers = await new DocumentService(this.db).evaluateCaseDocuments(caseId);
      for (const b of documentsBlockers) {
        blockers.push({
          id: `blocker-doc-${b.templateId}`,
          phase: "documents",
          reason: b.reason,
          severity: "error",
          requiredAction: b.requiredAction,
          overridePermitted: !b.nonOverridable,
          sourceRecordId: b.documentId ?? undefined,
        });
      }
    }
    if (phaseIdx >= intakeIdx) {
      intakeEvaluation = await new IntakeService(this.db).evaluate(caseId);
      if (!intakeEvaluation.complete) {
        const first = intakeEvaluation.missing[0];
        blockers.push({
          id: "blocker-intake-responses",
          phase: "intake",
          reason: `Guided intake is incomplete — ${intakeEvaluation.missing.length} required question(s) outstanding.`,
          severity: "error",
          requiredAction: first
            ? `Answer "${first.prompt.slice(0, 120)}" in Guided Intake.`
            : "Complete the outstanding intake questions.",
          // Missing safety/health screening responses must not be overridable.
          overridePermitted: false,
        });
      }
    }
    // Checklist reconciliation runs alongside evaluation so a stale placeholder
    // "complete" never survives contact with real records (TPI-V2-WEB-006 §10).
    if (phaseIdx >= walkthroughIdx) {
      walkthroughBlockers = await new WalkthroughService(this.db, new PropertyService(this.db)).evaluateCaseWalkthrough(caseId);
      for (const b of walkthroughBlockers) {
        blockers.push({
          id: `blocker-walkthrough-${b.roomId ?? "general"}`,
          phase: "walkthrough",
          reason: b.reason,
          severity: "error",
          requiredAction: b.requiredAction,
          overridePermitted: !b.nonOverridable,
          sourceRecordId: b.roomId ?? b.sessionId ?? undefined,
        });
      }
      await new WalkthroughService(this.db, new PropertyService(this.db)).reconcileChecklist(caseId);
    }
    // TPI-V2-WEB-008: the baseline phase derives readiness from recorded
    // baseline data (start/end/summary/completion + global lock + drift).
    const baselineService = new BaselineService(
      this.db,
      new PropertyService(this.db),
      new WalkthroughService(this.db, new PropertyService(this.db)),
      new SessionService(this.db),
    );
    if (phaseIdx >= baselineIdx) {
      const baselineBlockers: BaselineBlocker[] = await baselineService.evaluateCaseBaseline(caseId);
      for (const b of baselineBlockers) {
        blockers.push({
          id: `blocker-baseline-${b.roomId ?? "global"}`,
          phase: "baseline",
          reason: b.reason,
          severity: "error",
          requiredAction: b.requiredAction,
          overridePermitted: !b.nonOverridable,
          sourceRecordId: b.roomId ?? undefined,
        });
      }
      await baselineService.reconcileChecklist(caseId);
    }
    // TPI-V2-WEB-C4C: explicit investigation completion is a case-level event,
    // not an automatic consequence of ending a session. It is non-overridable.
    if (phaseIdx >= investigationIdx) {
      const completion = await new InvestigationCompletionService(this.db).getCompletion(caseId);
      if (!completion) {
        blockers.push({
          id: "blocker-investigation-completion",
          phase: "investigation",
          reason: "Investigation has not been explicitly completed for this case.",
          severity: "error",
          requiredAction: "End all active sessions and record Complete Investigation before entering Evidence Review.",
          overridePermitted: false,
        });
      }
    }

    // TPI-V2-WEB-009: evidence review readiness derives from real review records.
    if (phaseIdx >= reviewIdx) {
      const reviewService = new EvidenceReviewService(this.db);
      const reviewBlockers: EvidenceReviewBlocker[] = await reviewService.evaluateCaseEvidence(caseId);
      for (const b of reviewBlockers) {
        blockers.push({
          id: `blocker-evidence-${b.evidenceId ?? "general"}`,
          phase: "review",
          reason: b.reason,
          severity: "error",
          requiredAction: b.requiredAction,
          overridePermitted: !b.nonOverridable,
          sourceRecordId: b.evidenceId ?? undefined,
        });
      }
      await reviewService.reconcileChecklist(caseId);
    }
    if (phaseIdx >= documentsIdx) {
      await new DocumentService(this.db).reconcileChecklistFromBlockers(caseId, documentsBlockers);
      if (intakeEvaluation) {
        await new IntakeService(this.db).reconcileChecklistFromEvaluation(caseId, intakeEvaluation);
      }
    }

    // Blocker: phase-gate incomplete — required items for phases at or before
    // the current phase must be satisfied (complete or documented exception).
    for (const item of items) {
      const itemIdx = WORKFLOW_PHASE_ORDER.indexOf(item.phase);
      if (!item.required) continue;
      if (itemIdx > phaseIdx) continue; // future-phase requirement, not yet due
      if (item.status === "complete" || item.status === "exception") continue;
      if (item.status === "notApplicable" && item.notes.length > 0) continue;
      blockers.push({
        id: `blocker-${item.definitionId}`,
        phase: item.phase,
        reason: item.status === "notApplicable"
          ? `${item.title} marked not applicable without a documented reason.`
          : `${item.title} is required and not complete.`,
        severity: "error",
        requiredAction:
          item.status === "notApplicable"
            ? "Provide a documented reason, or mark the item complete."
            : `Complete "${item.title}" or document an exception with justification.`,
        overridePermitted: item.definitionId !== "requiredDocumentsSigned",
        sourceRecordId: item.id,
      });
    }

    // Blocker: invalid case relationship — investigation-phase work requires a location.
    if (phaseIdx >= WORKFLOW_PHASE_ORDER.indexOf("walkthrough") && !record.locationId) {
      blockers.push({
        id: "blocker-missing-location",
        phase: "walkthrough",
        reason: "No investigation location is associated with this case.",
        severity: "warning",
        requiredAction: "Associate a location with the case.",
        overridePermitted: true,
      });
    }

    const overriddenCount = items.filter((i) => i.required && i.status === "exception").length;
    const outstandingRequired = items.filter(
      (i) =>
        i.required &&
        i.status !== "complete" &&
        i.status !== "exception" &&
        !(i.status === "notApplicable" && i.notes.trim().length > 0),
    ).length;

    const state: ReadinessState =
      blockers.some((b) => !b.overridePermitted) ? "blocked"
      : blockers.length > 0 ? "incomplete"
      : overriddenCount > 0 ? "overridden"
      : "ready";

    // Progress — documented in docs/WORKFLOW_ENGINE.md
    const phasePercent = Math.round((phaseIdx / (WORKFLOW_PHASE_ORDER.length - 1)) * 100);
    const requiredItems = items.filter((i) => i.required);
    const requiredDone = requiredItems.filter(
      (i) => i.status === "complete" || i.status === "exception",
    ).length;
    const checklistPercent = requiredItems.length
      ? Math.round((requiredDone / requiredItems.length) * 100)
      : 100;

    const progress: WorkflowProgress = {
      phasePercent,
      checklistPercent,
      readiness: state,
      outstandingRequiredCount: outstandingRequired,
      blockerCount: blockers.length,
      overrideCount: overriddenCount,
    };

    // Deterministic next steps (offline; no AI)
    const nextSteps: NextStep[] = [];
    if (blockers.length > 0) {
      const b = blockers[0] as WorkflowBlocker;
      nextSteps.push({
        action: b.requiredAction,
        phase: b.phase,
        destination:
          b.phase === "documents" ? "documents-center"
          : b.phase === "intake" ? "guided-intake"
          : b.phase === "walkthrough" ? "walkthrough"
          : b.phase === "baseline" ? "baseline"
          : b.phase === "review" ? "evidence-library"
          : b.phase === "investigation" ? "session-view"
          : "command-center",
        available:
          b.phase === "documents" || b.phase === "intake" || b.phase === "walkthrough" ||
          b.phase === "baseline" || b.phase === "investigation" || b.phase === "review",
      });
    }
    const atFinal = phaseIdx === WORKFLOW_PHASE_ORDER.length - 1;
    if (!atFinal && blockers.length === 0) {
      nextSteps.push({
        action: `Advance workflow to ${WORKFLOW_PHASE_ORDER[phaseIdx + 1]}`,
        phase: record.currentPhase,
        destination: "command-center",
        available: true,
      });
    }
    if (atFinal && blockers.length === 0) {
      nextSteps.push({
        action: "Case is at the final workflow phase — proceed to reporting and closure when work is complete.",
        phase: "summary",
        destination: null,
        available: false,
      });
    }

    return { state, blockers, progress, nextSteps };
  }

  /**
   * Attempt a phase transition honoring blockers. Normal advancement requires
   * readiness (or documented exceptions); use `forceAdvanceWithOverride`
   * for permitted exceptions (never for non-overridable blockers).
   */
  async advanceIfReady(caseId: string): Promise<CaseRecord | undefined> {
    const evaluation = await this.evaluate(caseId);
    if (!evaluation) throw new ValidationError(`Case not found: ${caseId}`, "caseId");
    if (evaluation.state === "blocked") {
      const b = evaluation.blockers.find((x) => !x.overridePermitted);
      throw new ValidationError(
        `Workflow blocked: ${b?.reason ?? "unresolved requirements"} — ${b?.requiredAction ?? ""}`,
        "workflow",
      );
    }
    const service = new WorkflowService(this.db);
    return service.advancePhase(caseId);
  }

  /** Documented-override advancement: allowed only when no non-overridable blockers. */
  async forceAdvanceWithOverride(caseId: string, justification: string): Promise<CaseRecord | undefined> {
    if (!justification.trim()) {
      throw new ValidationError("An override requires a documented justification", "justification");
    }
    const evaluation = await this.evaluate(caseId);
    if (!evaluation) throw new ValidationError(`Case not found: ${caseId}`, "caseId");
    if (evaluation.state === "blocked") {
      const b = evaluation.blockers.find((x) => !x.overridePermitted);
      throw new ValidationError(
        `This blocker cannot be overridden: ${b?.reason ?? ""}`,
        "workflow",
      );
    }
    // Document the override as an exception note on the blocking items
    for (const blocker of evaluation.blockers) {
      if (blocker.sourceRecordId) {
        const item = await this.db.checklistItems.get(blocker.sourceRecordId);
        if (item) {
          await this.db.checklistItems.put({
            ...item,
            status: "exception",
            notes: justification,
            updatedAt: Date.now(),
          });
        }
      }
    }
    await this.audit.record("statusChanged", `Override advancement documented: ${justification.slice(0, 200)}`, {
      caseId,
      affectedRecordId: caseId,
      metadata: { override: true },
    });
    const service = new WorkflowService(this.db);
    return service.advancePhase(caseId);
  }
}
