/** Cards of one section in original order. */
export function cardsInSection(section: CaseHubSectionId): CaseHubCardDefinition[] {
  return CASE_HUB_CARDS.filter((card) => card.section === section).sort((a, b) => a.order - b.order);
}

export function cardFor(id: string): CaseHubCardDefinition | undefined {
  return CASE_HUB_CARDS.find((card) => card.id === id);
}

export const CARD_COUNTS: Record<CaseHubSectionId, number> = {
  workflow: cardsInSection("workflow").length,
  tools: cardsInSection("tools").length,
  support: cardsInSection("support").length,
};
