/**
 * Investigation Inbox read model — TPI-V2-WEB-015.
 *
 * ORIGINAL SOURCE
 *   `Cases/CaseDetailView.swift` → `CaseInvestigationInboxView` (lines 3180–3728)
 *   `Core/Evidence/PPEvidenceTimelineOrganizer.swift` (entry composition)
 *
 * The original inbox is a case-scoped staging view for investigation-phase
 * field media, shown as a Global Feed or grouped By Room, filtered by room and
 * review state, newest first. This module reproduces that read model over the
 * records the browser already stores.
 *
 * It is a READ MODEL ONLY:
 *   - every query is scoped to one case;
 *   - nothing is written, promoted, classified, or re-timestamped;
 *   - a missing room/session reference is labelled missing, never guessed and
 *     never silently dropped;
 *   - no conclusion, classification or readiness state is derived.
 */
import type { TPIDatabase } from "../db";
import { CaseRepository } from "../repositories/caseRepository";
import { EvidenceRepository } from "../repositories/evidenceRepository";
import type {
  EvidenceRecord,
  EvidenceReviewRecord,
  EvidenceReviewStatus,
  InvestigationSessionRecord,
  RoomRecord,
} from "../types";

/** `__unassigned` matches records with no room association. */
export const UNASSIGNED = "__unassigned";

export const REVIEW_LABELS: Record<EvidenceRecord["reviewStatus"], string> = {
  raw: "Raw",
  reviewed: "Reviewed",
  flagged: "Flagged",
  excluded: "Excluded",
};

export const MEDIA_LABELS: Record<EvidenceRecord["mediaType"], string> = {
  audio: "Audio",
  photo: "Photo",
  video: "Video",
  "sensor-log": "Sensor log",
  document: "Document",
};

const TIMESTAMP_SOURCE_LABELS: Record<string, string> = {
  capture: "capture time",
  import: "import time",
  investigator: "investigator-entered time",
  fileMetadata: "file metadata time",
  unknown: "time of unknown origin",
};

export interface InboxRow {
  evidenceId: string;
  title: string;
  kind: EvidenceRecord["kind"];
  mediaType: EvidenceRecord["mediaType"];
  /** Display timestamp: capture time when known, otherwise acquisition time. */
  at: number;
  /** Honest description of where `at` came from. */
  atSource: string;
  roomId: string | null;
  roomLabel: string;
  roomMissing: boolean;
  sessionId: string | null;
  sessionLabel: string;
  sessionMissing: boolean;
  origin: string;
  recordedBy: string;
  reviewStatus: EvidenceRecord["reviewStatus"];
  notes: string;
  verificationStatus: string;
  importedAt: number | null;
  fileSizeBytes: number;
  contentHash: string;
  latestReview: { status: EvidenceReviewStatus; reviewer: string; at: number } | null;
}

export interface InboxCounts {
  total: number;
  awaitingReview: number;
  flagged: number;
  excluded: number;
  derived: number;
  integrityProblems: number;
}

export interface InboxData {
  caseNumber: string;
  rows: InboxRow[];
  filterRooms: Array<{ id: string; name: string }>;
  counts: InboxCounts;
  /** Rows whose stored reference no longer resolves in this case. */
  unresolved: { rooms: number; sessions: number };
}

/** Latest structured review per evidence id — context, never a verdict. */
function latestReviews(reviews: EvidenceReviewRecord[]): Map<string, InboxRow["latestReview"]> {
  const map = new Map<string, InboxRow["latestReview"]>();
  for (const review of reviews) {
    const current = map.get(review.evidenceId);
    if (!current || review.at >= current.at) {
      map.set(review.evidenceId, { status: review.status, reviewer: review.reviewer, at: review.at });
    }
  }
  return map;
}

/**
 * Build inbox rows from records that already exist.
 *
 * Pure: no reads, no writes, no inference. A record whose room or session
 * reference is missing is kept and labelled, because hiding it would hide real
 * captured data; the stored association itself is never rewritten.
 */
export function buildInboxRows(input: {
  evidence: EvidenceRecord[];
  sessions: InvestigationSessionRecord[];
  rooms: RoomRecord[];
  reviews: EvidenceReviewRecord[];
}): InboxRow[] {
  const sessionsById = new Map(input.sessions.map((s) => [s.id, s]));
  const roomsById = new Map(input.rooms.map((r) => [r.id, r]));
  const reviewsByEvidence = latestReviews(input.reviews);

  return input.evidence
    .map((record): InboxRow => {
      const room = record.roomId ? roomsById.get(record.roomId) : undefined;
      const session = record.sessionId ? sessionsById.get(record.sessionId) : undefined;
      const captureAt = record.captureTimestamp ?? null;
      const at = captureAt ?? record.acquiredAt ?? record.createdAt;
      const atSource =
        captureAt !== null
          ? (TIMESTAMP_SOURCE_LABELS[record.captureTimestampSource ?? "capture"] ?? "capture time")
          : "acquisition time";
      return {
        evidenceId: record.id,
        title: record.title.trim() || "Untitled record",
        kind: record.kind,
        mediaType: record.mediaType,
        at,
        atSource,
        roomId: record.roomId ?? null,
        roomLabel: record.roomId
          ? room
            ? room.archived
              ? `${room.name} (archived)`
              : room.name
            : "(room record missing)"
          : "Unassigned",
        roomMissing: Boolean(record.roomId) && !room,
        sessionId: record.sessionId ?? null,
        sessionLabel: record.sessionId
          ? session
            ? `${session.status} — ${new Date(session.startedAt).toLocaleString()}`
            : "session record missing from this case"
          : "No session association",
        sessionMissing: Boolean(record.sessionId) && !session,
        origin: record.provenance.origin || "not recorded",
        recordedBy: record.provenance.recordedBy || "not recorded",
        reviewStatus: record.reviewStatus,
        notes: record.notes?.trim() ?? "",
        verificationStatus: record.verificationStatus ?? "unverified",
        importedAt: record.importedAt ?? null,
        fileSizeBytes: record.fileSizeBytes,
        contentHash: record.contentHash,
        latestReview: reviewsByEvidence.get(record.id) ?? null,
      };
    })
    .sort((a, b) => b.at - a.at);
}

/** Filter rows by room and review state. Empty string means "no filter". */
export function filterInboxRows(
  rows: InboxRow[],
  filters: { room?: string; review?: string },
): InboxRow[] {
  return rows.filter((row) => {
    if (filters.room) {
      if (filters.room === UNASSIGNED) {
        if (row.roomId) return false;
      } else if (row.roomId !== filters.room) {
        return false;
      }
    }
    if (filters.review && row.reviewStatus !== filters.review) return false;
    return true;
  });
}

/** Original "By Room" grouping: room sections, newest record first in each. */
export function groupInboxRowsByRoom(rows: InboxRow[]): Array<{ roomLabel: string; rows: InboxRow[] }> {
  const groups = new Map<string, InboxRow[]>();
  for (const row of rows) {
    const bucket = groups.get(row.roomLabel);
    if (bucket) bucket.push(row);
    else groups.set(row.roomLabel, [row]);
  }
  return [...groups.entries()]
    .sort((a, b) => a[0].localeCompare(b[0]))
    .map(([roomLabel, group]) => ({
      roomLabel,
      rows: [...group].sort((a, b) => b.at - a.at),
    }));
}

/**
 * Read one case's inbox records.
 *
 * Case isolation is structural: the case must exist and every query is scoped
 * to it. Returns null rather than an empty fabricated case. Reviews are read in
 * full and filtered by case here so no review row can leak across cases.
 */
export async function loadInboxData(db: TPIDatabase, caseId: string): Promise<InboxData | null> {
  const record = await new CaseRepository(db).getCase(caseId);
  if (!record) return null;

  const evidence = await new EvidenceRepository(db).listForCase(caseId, 500);
  const sessions = await db.sessions.where("caseId").equals(caseId).toArray();
  const structure = await db.propertyStructures.where("caseId").equals(caseId).first();
  // All rooms, including archived: an association must still resolve to the
  // historical room name rather than be reported as missing.
  const rooms = structure
    ? await db.structureRooms.where("structureId").equals(structure.id).toArray()
    : [];
  const reviews = (await db.evidenceReviews.toArray()).filter((r) => r.caseId === caseId);

  const rows = buildInboxRows({ evidence, sessions, rooms, reviews });
  const filterRooms = rooms
    .filter((room) => !room.archived)
    .map((room) => ({ id: room.id, name: room.name }))
    .sort((a, b) => a.name.localeCompare(b.name));

  const counts: InboxCounts = {
    total: rows.length,
    awaitingReview: rows.filter((r) => r.reviewStatus === "raw").length,
    flagged: rows.filter((r) => r.reviewStatus === "flagged").length,
    excluded: rows.filter((r) => r.reviewStatus === "excluded").length,
    derived: rows.filter((r) => r.kind === "derived").length,
    integrityProblems: rows.filter(
      (r) =>
        r.verificationStatus === "missing" ||
        r.verificationStatus === "corrupted" ||
        r.verificationStatus === "verificationFailed",
    ).length,
  };

  return {
    caseNumber: record.caseNumber,
    rows,
    filterRooms,
    counts,
    unresolved: {
      rooms: rows.filter((r) => r.roomMissing).length,
      sessions: rows.filter((r) => r.sessionMissing).length,
    },
  };
}
