/**
 * Document rendering — port of iOS PPDocumentRenderer (TPI-V2-WEB-006).
 * Standard header + template body with marker substitution, matching the
 * original semantics (see docs/DOCUMENTS_PARITY_AUDIT.md §3).
 */
import type { DocumentFormType, DocumentInstanceRecord, CaseRecord } from "../types";
import { templateFor, type DocumentTemplate } from "./templates";

export interface DocumentRenderContext {
  teamName: string;
  teamEmail: string;
  teamPhone: string;
  leadInvestigator: string;
  leadInvestigatorTitle: string;
  caseId: string;
  caseNumber: string;
  caseDate: string;
  documentDate: string;
  clientName: string;
  clientPhone: string;
  clientEmail: string;
  propertyAddress: string;
}

const DEFAULT_TEAM_NAME =
  "The Paranormal Initiative: Complete Case Management System for Professional Paranormal Investigations Team";

export const STANDARD_HEADER_LINES = [
  "[TEAM_NAME]",
  "OFFICIAL INVESTIGATION DOCUMENT",
  "",
  "Case Number: [CASE_ID]",
  "Case Date: [CASE_DATE]",
  "Document Date: [DOCUMENT_DATE]",
  "",
  "Client Name: [CLIENT_NAME]",
  "Property Address: [PROPERTY_ADDRESS]",
  "",
  "Lead Investigator: [LEAD_INVESTIGATOR]",
  "Title: [LEAD_INVESTIGATOR_TITLE]",
  "",
  "Contact:",
  "[TEAM_EMAIL]",
  "[TEAM_PHONE]",
];

/** Build a render context from a case record (+ team profile overrides). */
export function renderContextForCase(
  caseRecord: CaseRecord,
  team?: Partial<Pick<DocumentRenderContext, "teamName" | "teamEmail" | "teamPhone" | "leadInvestigator" | "leadInvestigatorTitle">>,
): DocumentRenderContext {
  const propertyAddress = [caseRecord.street, caseRecord.city, caseRecord.state, caseRecord.zip]
    .filter((p) => p && p.trim().length > 0)
    .join(", ");
  return {
    teamName: team?.teamName?.trim() || DEFAULT_TEAM_NAME,
    teamEmail: team?.teamEmail?.trim() ?? "",
    teamPhone: team?.teamPhone?.trim() ?? "",
    leadInvestigator: team?.leadInvestigator?.trim() || "Lead Investigator",
    leadInvestigatorTitle: team?.leadInvestigatorTitle?.trim() || "Lead Investigator",
    caseId: caseRecord.caseNumber || caseRecord.id,
    caseNumber: caseRecord.caseNumber || caseRecord.id,
    caseDate: new Date(caseRecord.createdAt).toLocaleDateString(),
    documentDate: new Date().toLocaleDateString(),
    clientName: caseRecord.clientName?.trim() || "Client Name Pending",
    clientPhone: caseRecord.phone?.trim() ?? "",
    clientEmail: caseRecord.email?.trim() ?? "",
    propertyAddress: propertyAddress || "Address Pending",
  };
}

function substitute(body: string, replacements: Record<string, string>): string {
  let out = body;
  for (const [key, value] of Object.entries(replacements)) {
    out = out.split(key).join(value);
  }
  return out;
}

/** Render a template body for a document instance (draft or version snapshot). */
export function renderDocument(
  templateId: DocumentFormType,
  instance: Pick<DocumentInstanceRecord, "fieldValues">,
  context: DocumentRenderContext,
  templateOverride?: DocumentTemplate,
): string {
  const template = templateOverride ?? templateFor(templateId);
  let body = template.body;
  // Remove duplicated title prefix (iOS behavior).
  const duplicatedTitlePrefix = `[DOCUMENT_TITLE]\n${template.title}`;
  if (body.startsWith(duplicatedTitlePrefix)) {
    body = body.slice(duplicatedTitlePrefix.length).trim();
  }
  const restrictedAreas = instance.fieldValues["restrictedAreas"]?.trim();
  const permissionLevel = instance.fieldValues["permissionLevel"]?.trim();
  const replacements: Record<string, string> = {
    "[TEAM_NAME]": context.teamName,
    "[CASE_ID]": context.caseId,
    "[CASE_DATE]": context.caseDate,
    "[DOCUMENT_DATE]": context.documentDate,
    "[CLIENT_NAME]": context.clientName,
    "[CLIENT_PHONE]": context.clientPhone,
    "[CLIENT_EMAIL]": context.clientEmail,
    "[PROPERTY_ADDRESS]": context.propertyAddress,
    "[LEAD_INVESTIGATOR]": context.leadInvestigator,
    "[LEAD_INVESTIGATOR_TITLE]": context.leadInvestigatorTitle,
    "[TEAM_EMAIL]": context.teamEmail,
    "[TEAM_PHONE]": context.teamPhone,
    "[RESTRICTED_AREAS]": restrictedAreas && restrictedAreas.length > 0 ? restrictedAreas : "____________________________________________________________",
    // Mark the selected permission option in the checkbox list.
    "[ ] PRIVATE CASE USE ONLY": permissionLevel === EVIDENCE_USE_OPTIONS_0 ? "[X] PRIVATE CASE USE ONLY" : "[ ] PRIVATE CASE USE ONLY",
  };
  body = substitute(body, replacements);
  body = substitute(body, {
    "[ ] ANONYMOUS EDUCATIONAL USE": permissionLevel === EVIDENCE_USE_OPTIONS_1 ? "[X] ANONYMOUS EDUCATIONAL USE" : "[ ] ANONYMOUS EDUCATIONAL USE",
    "[ ] PUBLIC RELEASE REQUIRES SEPARATE WRITTEN APPROVAL":
      permissionLevel === EVIDENCE_USE_OPTIONS_2 ? "[X] PUBLIC RELEASE REQUIRES SEPARATE WRITTEN APPROVAL" : "[ ] PUBLIC RELEASE REQUIRES SEPARATE WRITTEN APPROVAL",
  });
  body = body.replace(/\[STANDARD_SIGNATURE_BLOCK\]/g, "").trim();
  body = body.replace(/\n{3,}/g, "\n\n");
  return `${STANDARD_HEADER_LINES.map((l) =>
    substitute(l, replacements),
  ).join("\n")}\n${"-".repeat(70)}\nDOCUMENT TITLE: ${template.title}\n${"-".repeat(70)}\n\n${body}`;
}

const EVIDENCE_USE_OPTIONS_0 = "PRIVATE CASE USE ONLY";
const EVIDENCE_USE_OPTIONS_1 = "ANONYMOUS EDUCATIONAL USE";
const EVIDENCE_USE_OPTIONS_2 = "PUBLIC RELEASE REQUIRES SEPARATE WRITTEN APPROVAL";
