/**
 * Ambient audio level monitor (TPI-V2-WEB-008 §10).
 *
 * Ports the iOS NoiseMonitor calculation: RMS → dBFS, i.e.
 *   level = max(-80, min(0, 20 * log10(rms)))
 * (iOS `NoiseMonitor.handle(buffer:)` computes exactly this and clamps to
 * [-80, 0] — a digital full-scale ratio, NOT a calibrated sound-pressure level.)
 *
 * Scientific honesty:
 *  - The displayed value is a DIGITAL SIGNAL LEVEL in dBFS. It is never
 *    labelled dB SPL and never claimed to be calibrated.
 *  - Raw audio is NOT retained. Only numeric levels are produced, and only
 *    an explicit investigator action persists a measurement.
 *
 * Persistence policy (§21): continuous sampling does NOT write to IndexedDB.
 * Levels accumulate in a bounded in-memory ring buffer; the investigator
 * records an explicit measurement (which aggregates the window) when they
 * choose. This avoids excessive database writes.
 */
import { getSensorCapabilities } from "./sensorCapabilities";

export type AudioMonitorState = "stopped" | "starting" | "active" | "interrupted" | "denied" | "unavailable";

export interface AudioLevelSample {
  at: number;
  /** dBFS, clamped to [-80, 0] exactly as the iOS NoiseMonitor does. */
  dbfs: number;
}

export interface AudioWindowSummary {
  /** Number of samples aggregated. */
  count: number;
  /** Arithmetic mean of the sampled dBFS values. */
  meanDbfs: number;
  /** Peak (maximum) dBFS observed. */
  peakDbfs: number;
  /** Floor (minimum) dBFS observed. */
  floorDbfs: number;
  startedAt: number;
  endedAt: number;
  /** Sampling interval actually used, in ms. */
  intervalMs: number;
}

const MAX_SAMPLES = 300; // bounded ring buffer (~2.5 min at 500 ms)

export class AudioLevelMonitor {
  private state: AudioMonitorState = "stopped";
  private stream: MediaStream | null = null;
  private context: AudioContext | null = null;
  private analyser: AnalyserNode | null = null;
  private buffer: Float32Array | null = null;
  private timer: number | null = null;
  private samples: AudioLevelSample[] = [];
  private intervalMs = 500;
  private windowStartedAt = 0;
  private listeners = new Set<(s: { state: AudioMonitorState; level: number | null; samples: AudioLevelSample[] }) => void>();
  private lastError = "";

  getState(): AudioMonitorState {
    return this.state;
  }
  getLastError(): string {
    return this.lastError;
  }
  getSamples(): AudioLevelSample[] {
    return [...this.samples];
  }
  getCurrentLevel(): number | null {
    const last = this.samples[this.samples.length - 1];
    return last ? last.dbfs : null;
  }

  subscribe(fn: (s: { state: AudioMonitorState; level: number | null; samples: AudioLevelSample[] }) => void): () => void {
    this.listeners.add(fn);
    this.emit();
    return () => this.listeners.delete(fn);
  }

  private emit(): void {
    const payload = { state: this.state, level: this.getCurrentLevel(), samples: this.getSamples() };
    for (const fn of this.listeners) fn(payload);
  }

  /**
   * Begin level monitoring. Requires an explicit user gesture and a secure
   * context. Returns the resulting state (never throws for expected
   * permission/device conditions).
   */
  async start(intervalMs = 500): Promise<AudioMonitorState> {
    this.lastError = "";
    if (this.state === "active") return this.state;
    const caps = getSensorCapabilities();
    if (typeof navigator === "undefined" || !navigator.mediaDevices?.getUserMedia) {
      this.state = "unavailable";
      caps.setState("microphone", "unsupported");
      this.emit();
      return this.state;
    }
    this.state = "starting";
    this.emit();
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      this.stream = stream;
      const Ctor: typeof AudioContext | undefined =
        typeof AudioContext !== "undefined" ? AudioContext : (globalThis as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
      if (!Ctor) {
        await this.stopTracks();
        this.state = "unavailable";
        caps.setState("microphone", "unsupported");
        this.emit();
        return this.state;
      }
      const context = new Ctor();
      this.context = context;
      const source = context.createMediaStreamSource(stream);
      const analyser = context.createAnalyser();
      analyser.fftSize = 2048;
      source.connect(analyser);
      this.analyser = analyser;
      this.buffer = new Float32Array(analyser.fftSize);
      this.samples = [];
      this.windowStartedAt = Date.now();
      this.intervalMs = intervalMs;
      this.timer = window.setInterval(() => this.sample(), intervalMs);
      this.sample();
      this.state = "active";
      caps.setState("microphone", "active", "Monitoring signal level (dBFS). Raw audio is not retained.");
      this.emit();
      return this.state;
    } catch (err) {
      this.lastError = (err as Error).message;
      const name = (err as { name?: string }).name ?? "";
      if (name === "NotAllowedError" || name === "SecurityError") {
        this.state = "denied";
        getSensorCapabilities().setState("microphone", "permissionDenied", "Microphone permission was denied. Level monitoring is unavailable until permission is granted.");
      } else if (name === "NotFoundError" || name === "OverconstrainedError") {
        this.state = "unavailable";
        getSensorCapabilities().setState("microphone", "deviceUnavailable", "No microphone device was found.");
      } else {
        this.state = "unavailable";
        getSensorCapabilities().setState("microphone", "deviceUnavailable", `Microphone unavailable: ${this.lastError}`);
      }
      this.emit();
      return this.state;
    }
  }

  /** Stop monitoring and release the microphone (no capture continues). */
  async stop(): Promise<void> {
    if (this.timer !== null) {
      window.clearInterval(this.timer);
      this.timer = null;
    }
    await this.stopTracks();
    if (this.context && this.context.state !== "closed") {
      try {
        await this.context.close();
      } catch {
        /* already closing */
      }
    }
    this.context = null;
    this.analyser = null;
    this.buffer = null;
    this.state = "stopped";
    const cap = getSensorCapabilities().get("microphone");
    if (cap && cap.state !== "unsupported") {
      getSensorCapabilities().setState("microphone", "stopped", "Monitoring stopped. The microphone has been released.");
    }
    this.emit();
  }

  /** Called when the page is hidden/suspended — monitoring may not continue. */
  markInterrupted(): void {
    if (this.state !== "active") return;
    this.state = "interrupted";
    getSensorCapabilities().setState("microphone", "interrupted", "The page was suspended; monitoring was interrupted and did not continue in the background.");
    this.emit();
  }

  private async stopTracks(): Promise<void> {
    if (this.stream) {
      for (const track of this.stream.getTracks()) track.stop();
      this.stream = null;
    }
  }

  /**
   * One sample: RMS across the time-domain buffer → dBFS, clamped to [-80, 0]
   * (identical mathematics to the iOS NoiseMonitor).
   */
  private sample(): void {
    if (!this.analyser || !this.buffer) return;
    this.analyser.getFloatTimeDomainData(this.buffer as Float32Array<ArrayBuffer>);
    let sumSquares = 0;
    for (let i = 0; i < this.buffer.length; i += 1) sumSquares += this.buffer[i]! * this.buffer[i]!;
    const rms = Math.sqrt(sumSquares / this.buffer.length);
    const dbfs = Math.max(-80, Math.min(0, 20 * Math.log10(Math.max(rms, 0.000_001))));
    this.samples.push({ at: Date.now(), dbfs });
    if (this.samples.length > MAX_SAMPLES) this.samples.splice(0, this.samples.length - MAX_SAMPLES);
    this.emit();
  }

  /**
   * Aggregate the current sampling window into a single measurement summary
   * for explicit persistence. Returns null when nothing has been sampled.
   */
  summarizeWindow(): AudioWindowSummary | null {
    if (this.samples.length === 0) return null;
    const values = this.samples.map((s) => s.dbfs);
    const mean = values.reduce((a, b) => a + b, 0) / values.length;
    return {
      count: values.length,
      meanDbfs: round2(mean),
      peakDbfs: round2(Math.max(...values)),
      floorDbfs: round2(Math.min(...values)),
      startedAt: this.windowStartedAt,
      endedAt: Date.now(),
      intervalMs: this.intervalMs,
    };
  }

  clearWindow(): void {
    this.samples = [];
    this.windowStartedAt = Date.now();
    this.emit();
  }
}

function round2(v: number): number {
  return Math.round(v * 100) / 100;
}

let monitor: AudioLevelMonitor | undefined;
export function getAudioLevelMonitor(): AudioLevelMonitor {
  monitor ??= new AudioLevelMonitor();
  return monitor;
}
export function setAudioLevelMonitorForTesting(m: AudioLevelMonitor | undefined): void {
  monitor = m;
}
