/**
 * Reference-directory claim selection and explicit destination review
 * (TPI-V2-WEB-C6D).
 *
 * The catalogue is read-only. Selecting an activity never creates a claim and
 * never chooses a room. Import is enabled only after every selected statement
 * has an explicit destination decision: a case room or "Leave unassigned".
 * The actual write remains the C6A ClaimImportService path.
 */
import { getDb } from "../../core/db";
import {
  ClaimImportService,
  type ClaimImportInspection,
  type ClaimImportRequest,
} from "../../core/claims/claimImportService";
import {
  buildReferenceClaimImportRequest,
  type ReferenceDestinationReview,
} from "../../core/claims/referenceClaimImport";
import {
  REFERENCE_STATE_SECTIONS,
  referenceActivityKey,
  referenceLocationById,
  referenceStateSection,
} from "../../core/reference/referenceCatalog";
import type { ReferenceLocationRecord } from "../../core/reference/referenceLocationCatalog";
import type { RoomRecord } from "../../core/types";
import { esc } from "../dashboard/shell";
import { clearDrafts, onDelegate } from "../../shared/uidom";

export interface ReferenceImportData {
  caseId: string;
  rooms: RoomRecord[];
  floors: ReadonlyArray<{ id: string; displayName: string }>;
  zones: ReadonlyArray<{ id: string; displayName: string }>;
  eligible: boolean;
}

interface ReferenceImportState {
  open: boolean;
  stateCode: string;
  locationId: string | null;
  selected: Set<string>;
  destinations: Record<string, string>;
  notice: string;
  error: string;
  plan: ClaimImportInspection | null;
}

const importState = new WeakMap<HTMLElement, ReferenceImportState>();

function initialLocation(): { stateCode: string; locationId: string | null } {
  const section = REFERENCE_STATE_SECTIONS[0];
  return {
    stateCode: section?.code ?? "",
    locationId: section?.locations[0]?.id ?? null,
  };
}

function stateFor(container: HTMLElement): ReferenceImportState {
  let state = importState.get(container);
  if (!state) {
    const initial = initialLocation();
    state = {
      open: false,
      stateCode: initial.stateCode,
      locationId: initial.locationId,
      selected: new Set<string>(),
      destinations: {},
      notice: "",
      error: "",
      plan: null,
    };
    importState.set(container, state);
  }
  return state;
}

function selectedLocation(state: ReferenceImportState): ReferenceLocationRecord | null {
  return state.locationId ? referenceLocationById(state.locationId) ?? null : null;
}

function activityIndices(location: ReferenceLocationRecord, state: ReferenceImportState): number[] {
  return location.claims
    .map((_text, index) => index)
    .filter((index) => state.selected.has(referenceActivityKey(location.id, index)));
}

function roomContext(room: RoomRecord, data: ReferenceImportData): string {
  const floor = data.floors.find((candidate) => candidate.id === room.floorId);
  const zone = data.zones.find((candidate) => candidate.id === room.zoneId);
  const parent = floor
    ? `Floor: ${floor.displayName}`
    : zone
      ? `Zone: ${zone.displayName}`
      : "Unassigned area";
  return `${parent} — ${room.name}${room.archived ? " (archived)" : ""}`;
}

function destinationOptions(current: string, data: ReferenceImportData): string {
  return `<option value=""${current === "" ? " selected" : ""} disabled>Choose destination room…</option>
    <option value="unassigned"${current === "unassigned" ? " selected" : ""}>Leave unassigned (explicit)</option>
    ${data.rooms
      .map(
        (room) =>
          `<option value="${esc(room.id)}"${current === room.id ? " selected" : ""}>${esc(roomContext(room, data))}</option>`,
      )
      .join("")}`;
}

function statusLabel(status: string): string {
  if (status === "new") return "New";
  if (status === "duplicate") return "Already imported";
  if (status === "conflict") return "Conflict — blocked";
  return "Rejected";
}

function canSubmit(
  state: ReferenceImportState,
  location: ReferenceLocationRecord | null,
  _data: ReferenceImportData,
): boolean {
  if (!location || state.selected.size === 0) return false;
  return [...state.selected].every(
    (key) => (state.destinations[key] ?? "").trim().length > 0,
  );
}

function reviewRowsHtml(
  location: ReferenceLocationRecord,
  state: ReferenceImportState,
  data: ReferenceImportData,
): string {
  const indices = activityIndices(location, state);
  if (indices.length === 0) {
    return `<p class="cc-empty" data-reference-review-empty>Select at least one activity statement to review destination rooms.</p>`;
  }
  const planByIndex = new Map(
    (state.plan?.entries ?? []).map((entry) => [entry.index, entry]),
  );
  return `<div class="reference-import-review" data-reference-review>
    <div class="reference-import-review-heading">
      <h5>Destination-room review</h5>
      <p class="cc-meta">Every selected statement needs an explicit room or an explicit unassigned decision. No source room label is mapped automatically.</p>
    </div>
    <div class="reference-import-review-list">
      ${indices
        .map((index) => {
          const key = referenceActivityKey(location.id, index);
          const text = location.claims[index]!;
          const destination = state.destinations[key] ?? "";
          const plan = planByIndex.get(index);
          return `<div class="reference-import-review-row" data-reference-review-row="${esc(key)}">
            <div class="reference-import-review-text">
              <span class="claims-eyebrow">Activity ${index + 1}</span>
              <p>${esc(text)}</p>
              ${plan ? `<span class="reference-import-status reference-import-status-${esc(plan.status)}">${esc(statusLabel(plan.status))}</span>` : ""}
            </div>
            <div class="detail-field">
              <label for="reference-destination-${esc(key)}">Destination for activity ${index + 1}</label>
              <select id="reference-destination-${esc(key)}" data-reference-destination data-reference-key="${esc(key)}" required>
                ${destinationOptions(destination, data)}
              </select>
            </div>
          </div>`;
        })
        .join("")}
    </div>
    <div class="form-actions reference-import-actions">
      <button class="button-secondary" type="button" data-reference-mark-unassigned>Mark all selected unassigned</button>
      <button class="button-primary" type="button" data-reference-import-submit ${canSubmit(state, location, data) ? "" : "disabled"}>Import selected activities</button>
    </div>
    <p class="cc-meta" data-reference-submit-help>${canSubmit(state, location, data) ? "Ready to import. Duplicate source identities are skipped; conflicting content is blocked and never overwritten." : "Choose a destination room or leave every selected activity explicitly unassigned to enable import."}</p>
  </div>`;
}

function locationCard(location: ReferenceLocationRecord): string {
  return `<div class="reference-import-location" data-reference-location-card data-reference-location-id="${esc(location.id)}">
    <div class="reference-import-location-heading">
      <div>
        <span class="claims-eyebrow">Reference location — read-only source</span>
        <h4>${esc(location.name)}</h4>
        <p class="cc-count">${esc(location.city)}, ${esc(location.stateName)} • ${esc(location.locationType)} • ${location.claims.length} activity statement(s)</p>
      </div>
      <span class="claims-badge">${esc(location.stateCode)}</span>
    </div>
    <div class="reference-import-location-grid">
      <div>
        <h5>Source history</h5>
        <p>${esc(location.history)}</p>
      </div>
      <div>
        <h5>Source classification</h5>
        <p>${esc(location.classification)}</p>
      </div>
    </div>
    <dl class="claims-facts">
      <div class="claims-fact"><dt>Address</dt><dd>${esc(location.address || "Not recorded in source")}</dd></div>
      <div class="claims-fact"><dt>Website</dt><dd>${location.website ? esc(location.website) : "Not recorded in source"}</dd></div>
      <div class="claims-fact"><dt>Tags</dt><dd>${location.tags.length > 0 ? esc(location.tags.join(" · ")) : "Not recorded in source"}</dd></div>
    </dl>
    <div class="reference-import-source-rooms" data-reference-source-rooms>
      <h5>Source structure labels — not destination rooms</h5>
      <p class="cc-meta">These labels describe the reference resource only. C6D never maps them to case rooms; choose a destination explicitly below.</p>
      <ul>${location.rooms.map((room) => `<li>${esc(room)}</li>`).join("")}</ul>
    </div>
  </div>`;
}

function activitiesHtml(
  location: ReferenceLocationRecord,
  state: ReferenceImportState,
): string {
  return `<div class="reference-import-activities" data-reference-activities>
    <div class="reference-import-activities-heading">
      <h5>Activity statements (${location.claims.length})</h5>
      <div class="reference-import-quick-actions">
        <button class="back-button" type="button" data-reference-select-all>Select all in location</button>
        <button class="back-button" type="button" data-reference-clear>Clear selection</button>
      </div>
    </div>
    <p class="cc-meta">Statements are copied verbatim into the imported source statement. Titles and identifiers are deterministic; no witness, occurrence date or cause is inferred.</p>
    <div class="reference-import-activity-list">
      ${location.claims
        .map((text, index) => {
          const key = referenceActivityKey(location.id, index);
          return `<label class="reference-import-activity" data-reference-activity>
            <input type="checkbox" data-reference-claim="${esc(key)}" data-reference-claim-index="${index}"${state.selected.has(key) ? " checked" : ""}>
            <span>${esc(text)}</span>
          </label>`;
        })
        .join("")}
    </div>
  </div>`;
}

export function referenceClaimImportHtml(
  container: HTMLElement,
  data: ReferenceImportData,
): string {
  if (!data.eligible) return "";
  const state = stateFor(container);
  if (!state.open) return "";
  const section = referenceStateSection(state.stateCode);
  const location = selectedLocation(state);
  const selectedCount = location ? activityIndices(location, state).length : 0;

  return `<section class="reference-import" data-root="reference-import" data-case-id="${esc(data.caseId)}" aria-labelledby="reference-import-title">
    <div class="reference-import-heading">
      <div>
        <span class="claims-eyebrow">Reference Directory</span>
        <h3 id="reference-import-title">Import Reference Claims</h3>
        <p class="cc-count">${REFERENCE_STATE_SECTIONS.length} state sections • ${REFERENCE_STATE_SECTIONS.reduce((total, entry) => total + entry.locations.length, 0)} locations • ${REFERENCE_STATE_SECTIONS.reduce((total, entry) => total + entry.locations.reduce((n, item) => n + item.claims.length, 0), 0)} activity statements</p>
      </div>
      <button class="back-button" type="button" data-reference-close>Close reference import</button>
    </div>
    <p class="claims-safeguard"><strong>Read-only source, explicit destination.</strong> Selecting an activity does not write anything. Imported activities remain reported claims, not evidence or observations. Import never changes readiness, phases, reviews or investigation completion.</p>
    ${state.notice ? `<p class="reference-import-notice" data-reference-import-notice role="status">${esc(state.notice)}</p>` : ""}
    ${state.error ? `<p class="reference-import-error" data-reference-import-error role="alert">${esc(state.error)}</p>` : ""}

    <div class="reference-import-picker">
      <div class="detail-field">
        <label for="reference-state-section">State section</label>
        <select id="reference-state-section" data-reference-state>
          ${REFERENCE_STATE_SECTIONS.map(
            (entry) =>
              `<option value="${esc(entry.code)}"${entry.code === state.stateCode ? " selected" : ""}>${esc(entry.name)} (${entry.locations.length})</option>`,
          ).join("")}
        </select>
      </div>
      <div class="detail-field">
        <label for="reference-location">Reference location</label>
        <select id="reference-location" data-reference-location>
          <option value="">Choose a location…</option>
          ${(section?.locations ?? [])
            .map(
              (entry) =>
                `<option value="${esc(entry.id)}"${entry.id === state.locationId ? " selected" : ""}>${esc(entry.name)} — ${esc(entry.city)} (${entry.claims.length})</option>`,
            )
            .join("")}
        </select>
      </div>
    </div>

    ${!section || section.locations.length === 0
      ? `<p class="cc-empty" data-reference-section-empty>No reference locations are recorded for this state section.</p>`
      : !location
        ? `<p class="cc-empty" data-reference-location-empty>Choose a reference location to inspect its read-only activity statements.</p>`
        : `${locationCard(location)}
          ${activitiesHtml(location, state)}
          <p class="cc-count" data-reference-selected-count>${selectedCount} activity statement(s) selected.</p>
          ${reviewRowsHtml(location, state, data)}`}
  </section>`;
}

function showError(container: HTMLElement, message: string): void {
  stateFor(container).error = message;
}

async function runImport(
  container: HTMLElement,
  data: ReferenceImportData,
  rerender: () => Promise<void>,
): Promise<void> {
  const state = stateFor(container);
  state.error = "";
  const location = selectedLocation(state);
  if (!location) {
    showError(container, "Choose a reference location first.");
    await rerender();
    return;
  }
  const indices = activityIndices(location, state);
  if (indices.length === 0) {
    showError(container, "Select at least one activity statement.");
    await rerender();
    return;
  }
  const reviews: ReferenceDestinationReview[] = [];
  for (const index of indices) {
    const key = referenceActivityKey(location.id, index);
    const destination = state.destinations[key] ?? "";
    if (!destination) {
      showError(
        container,
        `Choose a destination room or explicitly leave activity ${index + 1} unassigned.`,
      );
      await rerender();
      return;
    }
    if (destination === "unassigned") {
      reviews.push({ activityIndex: index, roomId: null, roomName: "" });
      continue;
    }
    const room = data.rooms.find((candidate) => candidate.id === destination);
    if (!room) {
      showError(container, `The destination room for activity ${index + 1} is no longer available. No claim was written.`);
      await rerender();
      return;
    }
    reviews.push({ activityIndex: index, roomId: room.id, roomName: room.name });
  }

  let request: ClaimImportRequest;
  try {
    request = buildReferenceClaimImportRequest(data.caseId, location, reviews);
  } catch (error) {
    showError(container, (error as Error).message || "The import request is invalid.");
    await rerender();
    return;
  }

  const importer = new ClaimImportService(getDb());
  try {
    const plan = await importer.inspectClaims(request);
    state.plan = plan;
    if (plan.conflictCount > 0) {
      showError(
        container,
        `${plan.conflictCount} selected source claim(s) conflict with existing imported records. No claim was written; existing provenance is preserved.`,
      );
      await rerender();
      return;
    }
    if (plan.rejectedCount > 0) {
      showError(
        container,
        `${plan.rejectedCount} selected source claim(s) failed validation. No claim was written.`,
      );
      await rerender();
      return;
    }
    if (plan.newCount === 0) {
      state.notice = `${plan.duplicateCount} selected source claim(s) are already imported. No duplicate was created.`;
      state.error = "";
      await rerender();
      return;
    }

    const result = await importer.importClaims(request);
    state.notice = `${result.imported} claim(s) imported; ${result.skipped} already present; ${result.conflicts.length} conflict(s); ${result.rejected.length} rejected.`;
    state.error = result.conflicts.length > 0
      ? "A concurrent import changed one or more records. Existing claims were preserved and no conflict was overwritten."
      : "";
    state.selected.clear();
    state.destinations = {};
    state.plan = null;
    clearDrafts(container);
    await rerender();
  } catch (error) {
    showError(container, (error as Error).message || "The reference import could not be completed.");
    await rerender();
  }
}

export function wireReferenceClaimImport(
  container: HTMLElement,
  data: ReferenceImportData,
  rerender: () => Promise<void>,
): void {
  onDelegate(container, "click", "[data-reference-import-open]", () => {
    const state = stateFor(container);
    state.open = true;
    state.notice = "";
    state.error = "";
    state.plan = null;
    clearDrafts(container);
    void rerender();
  });

  onDelegate(container, "click", "[data-reference-close]", () => {
    const state = stateFor(container);
    state.open = false;
    state.error = "";
    clearDrafts(container);
    void rerender();
  });

  onDelegate(container, "change", "[data-reference-state]", (element) => {
    const state = stateFor(container);
    state.stateCode = (element as HTMLSelectElement).value;
    state.locationId = referenceStateSection(state.stateCode)?.locations[0]?.id ?? null;
    state.selected.clear();
    state.destinations = {};
    state.plan = null;
    state.notice = "";
    state.error = "";
    clearDrafts(container);
    void rerender();
  });

  onDelegate(container, "change", "[data-reference-location]", (element) => {
    const state = stateFor(container);
    state.locationId = (element as HTMLSelectElement).value || null;
    state.selected.clear();
    state.destinations = {};
    state.plan = null;
    state.notice = "";
    state.error = "";
    clearDrafts(container);
    void rerender();
  });

  onDelegate(container, "change", "[data-reference-claim]", (element) => {
    const state = stateFor(container);
    const input = element as HTMLInputElement;
    const key = input.dataset.referenceClaim ?? "";
    if (!key) return;
    if (input.checked) state.selected.add(key);
    else {
      state.selected.delete(key);
      delete state.destinations[key];
    }
    state.plan = null;
    state.notice = "";
    state.error = "";
    void rerender();
  });

  onDelegate(container, "change", "[data-reference-destination]", (element) => {
    const state = stateFor(container);
    const select = element as HTMLSelectElement;
    const key = select.dataset.referenceKey ?? "";
    if (!key) return;
    state.destinations[key] = select.value;
    state.plan = null;
    state.notice = "";
    state.error = "";
    void rerender();
  });

  onDelegate(container, "click", "[data-reference-select-all]", () => {
    const state = stateFor(container);
    const location = selectedLocation(state);
    if (!location) return;
    for (let index = 0; index < location.claims.length; index += 1) {
      state.selected.add(referenceActivityKey(location.id, index));
    }
    state.plan = null;
    state.error = "";
    void rerender();
  });

  onDelegate(container, "click", "[data-reference-clear]", () => {
    const state = stateFor(container);
    state.selected.clear();
    state.destinations = {};
    state.plan = null;
    state.notice = "";
    state.error = "";
    void rerender();
  });

  onDelegate(container, "click", "[data-reference-mark-unassigned]", () => {
    const state = stateFor(container);
    for (const key of state.selected) state.destinations[key] = "unassigned";
    state.plan = null;
    state.notice = "";
    state.error = "";
    void rerender();
  });

  onDelegate(container, "click", "[data-reference-import-submit]", () => {
    void runImport(container, data, rerender).catch((error) => {
      showError(container, (error as Error).message || "The reference import could not be completed.");
      void rerender();
    });
  });
}
