/**
 * Evidence timeline and environmental comparison (TPI-V2-WEB-009 §15/§19).
 *
 * Timeline merges evidence, session events, environmental measurements,
 * observations, reviews and annotations into one chronological view with
 * explicit timestamp provenance.
 *
 * Environmental comparison uses strictly neutral language: temporal proximity
 * is never presented as causation, and no statistics are fabricated.
 */
import type { TPIDatabase } from "../db";
import type {
  AcquisitionMethod,
  EvidenceMediaType,
  MeasurementType,
  ObservationKind,
  SessionEventType,
  TimestampSource,
} from "../types";

export type TimelineEntryKind =
  | "evidenceImport"
  | "evidenceCapture"
  | "sessionEvent"
  | "measurement"
  | "observation"
  | "review"
  | "annotation";

export interface TimelineEntry {
  id: string;
  kind: TimelineEntryKind;
  at: number;
  /** Which timestamp produced `at` — never invented. */
  timestampSource: TimestampSource;
  title: string;
  detail: string;
  roomId: string | null;
  sessionId: string | null;
  evidenceId: string | null;
  /** For measurements: how the value was acquired. */
  acquisition?: AcquisitionMethod;
  measurementType?: MeasurementType;
  observationKind?: ObservationKind;
  eventType?: SessionEventType;
  mediaType?: EvidenceMediaType;
  timezoneOffsetMinutes: number | null;
}

export interface TimelineFilter {
  sessionId?: string;
  roomId?: string;
  kinds?: TimelineEntryKind[];
  mediaType?: EvidenceMediaType;
  measurementType?: MeasurementType;
  /** Inclusive date range (ms). */
  from?: number;
  to?: number;
  /** Source classification filter: acquisition method or observation kind. */
  acquisition?: AcquisitionMethod;
  observationKind?: ObservationKind;
}

export class EvidenceTimelineService {
  constructor(private readonly db: TPIDatabase) {}

  /**
   * Build the chronological timeline. Entries are ordered by timestamp with a
   * stable tiebreak so repeated builds are deterministic.
   */
  async build(caseId: string, filter: TimelineFilter = {}): Promise<TimelineEntry[]> {
    const entries: TimelineEntry[] = [];

    // --- Evidence: both the capture timestamp and the import event ---
    const evidence = await this.db.evidence.where("caseId").equals(caseId).toArray();
    for (const e of evidence) {
      if (e.kind !== "original") continue;
      const captureAt = e.captureTimestamp ?? e.acquiredAt;
      entries.push({
        id: `ev-capture-${e.id}`,
        kind: "evidenceCapture",
        at: captureAt,
        timestampSource: e.captureTimestampSource ?? "unknown",
        title: `Evidence captured: ${e.title}`,
        detail: `${e.mediaType}${e.originalFileName ? ` • ${e.originalFileName}` : ""}${e.sourceDescription ? ` • ${e.sourceDescription}` : ""}`,
        roomId: e.roomId ?? null,
        sessionId: e.sessionId ?? null,
        evidenceId: e.id,
        mediaType: e.mediaType,
        timezoneOffsetMinutes: e.captureTimezoneOffsetMinutes ?? null,
      });
      if (e.importedAt) {
        entries.push({
          id: `ev-import-${e.id}`,
          kind: "evidenceImport",
          at: e.importedAt,
          timestampSource: "import",
          title: `Evidence imported: ${e.title}`,
          detail: `${Math.round(e.fileSizeBytes / 1024)} KB • integrity: ${e.verificationStatus ?? "unverified"}`,
          roomId: e.roomId ?? null,
          sessionId: e.sessionId ?? null,
          evidenceId: e.id,
          mediaType: e.mediaType,
          timezoneOffsetMinutes: null,
        });
      }
    }

    // --- Session events ---
    const events = await this.db.sessionEvents.where("caseId").equals(caseId).toArray();
    for (const e of events) {
      entries.push({
        id: `se-${e.id}`,
        kind: "sessionEvent",
        at: e.at,
        timestampSource: "investigator",
        title: e.type,
        detail: e.detail,
        roomId: null,
        sessionId: e.sessionId,
        evidenceId: null,
        eventType: e.type,
        timezoneOffsetMinutes: null,
      });
    }

    // --- Environmental measurements ---
    const measurements = await this.db.environmentMeasurements.where("caseId").equals(caseId).toArray();
    for (const m of measurements) {
      if (m.amended) continue;
      entries.push({
        id: `ms-${m.id}`,
        kind: "measurement",
        at: m.at,
        timestampSource: "investigator",
        title: `${m.measurementType}${m.value !== null ? `: ${m.value} ${m.unit}` : `: ${m.text}`}`,
        detail: `${m.acquisition}${m.instrument ? ` • ${m.instrument}` : ""}${m.calibration !== "unknown" ? ` • calibration: ${m.calibration}` : ""}`,
        roomId: m.roomId,
        sessionId: m.sessionId,
        evidenceId: null,
        acquisition: m.acquisition,
        measurementType: m.measurementType,
        timezoneOffsetMinutes: null,
      });
    }

    // --- Walkthrough observations ---
    const observations = await this.db.walkthroughObservations.where("caseId").equals(caseId).toArray();
    for (const o of observations) {
      if (o.amended) continue;
      entries.push({
        id: `ob-${o.id}`,
        kind: "observation",
        at: o.createdAt,
        timestampSource: "investigator",
        title: `Observation (${o.kind})`,
        detail: o.description,
        roomId: o.roomId,
        sessionId: o.sessionId,
        evidenceId: null,
        observationKind: o.kind,
        timezoneOffsetMinutes: null,
      });
    }

    // --- Reviews ---
    const reviews = await this.db.evidenceReviews.where("caseId").equals(caseId).toArray();
    for (const r of reviews) {
      entries.push({
        id: `rv-${r.id}`,
        kind: "review",
        at: r.at,
        timestampSource: "investigator",
        title: `Evidence review: ${r.status}`,
        detail: `${r.reviewer}${r.notes ? ` • ${r.notes}` : ""}${r.naturalExplanations ? ` • natural explanations considered: ${r.naturalExplanations}` : ""}`,
        roomId: null,
        sessionId: null,
        evidenceId: r.evidenceId,
        timezoneOffsetMinutes: null,
      });
    }

    // --- Annotations ---
    const annotations = await this.db.evidenceAnnotations.where("caseId").equals(caseId).toArray();
    for (const a of annotations) {
      if (a.amended) continue;
      entries.push({
        id: `an-${a.id}`,
        kind: "annotation",
        at: a.createdAt,
        timestampSource: "investigator",
        title: `Annotation (${a.annotationType})`,
        detail: a.description,
        roomId: null,
        sessionId: null,
        evidenceId: a.evidenceId,
        timezoneOffsetMinutes: null,
      });
    }

    const filtered = entries.filter((e) => {
      if (filter.sessionId && e.sessionId !== filter.sessionId) return false;
      if (filter.roomId && e.roomId !== filter.roomId) return false;
      if (filter.kinds && filter.kinds.length > 0 && !filter.kinds.includes(e.kind)) return false;
      if (filter.mediaType && e.mediaType !== filter.mediaType) return false;
      if (filter.measurementType && e.measurementType !== filter.measurementType) return false;
      if (filter.acquisition && e.acquisition !== filter.acquisition) return false;
      if (filter.observationKind && e.observationKind !== filter.observationKind) return false;
      if (filter.from !== undefined && e.at < filter.from) return false;
      if (filter.to !== undefined && e.at > filter.to) return false;
      return true;
    });

    return filtered.sort((a, b) => a.at - b.at || a.id.localeCompare(b.id));
  }
}

/* ======================= environmental comparison ======================= */

export interface ComparisonRecord {
  id: string;
  kind: "measurement" | "sessionEvent" | "observation";
  at: number;
  label: string;
  detail: string;
  /** Neutral relationship label — never causation. */
  relation: string;
}

export interface ComparisonResult {
  evidenceId: string;
  evidenceTitle: string;
  windowStart: number;
  windowEnd: number;
  /** Neutral statement about data availability. */
  availability:
    | "nearbyReadingsFound"
    | "sameRoomRecordsFound"
    | "insufficientData"
    | "noMatchingRecords";
  records: ComparisonRecord[];
  missing: string[];
  notes: string[];
}

export class EnvironmentalComparisonService {
  constructor(private readonly db: TPIDatabase) {}

  /**
   * Compare one evidence item with records near it in time. The window is
   * explicit and investigator-controlled; defaults to ±15 minutes.
   */
  async compare(evidenceId: string, options: { windowMinutes?: number; includeSessionEvents?: boolean; includeObservations?: boolean } = {}): Promise<ComparisonResult> {
    const evidence = await this.db.evidence.get(evidenceId);
    if (!evidence) throw new Error(`Evidence not found: ${evidenceId}`);
    const windowMs = (options.windowMinutes ?? 15) * 60_000;
    const centre = evidence.captureTimestamp ?? evidence.acquiredAt;
    const windowStart = centre - windowMs;
    const windowEnd = centre + windowMs;

    const records: ComparisonRecord[] = [];
    const missing: string[] = [];

    const measurements = (await this.db.environmentMeasurements.where("caseId").equals(evidence.caseId).toArray())
      .filter((m) => !m.amended && m.at >= windowStart && m.at <= windowEnd);
    for (const m of measurements) {
      const relation =
        evidence.roomId && m.roomId === evidence.roomId
          ? "Recorded during the same session and in the same room"
          : m.sessionId && m.sessionId === evidence.sessionId
            ? "Recorded during the same session"
            : "Nearby in time";
      records.push({
        id: m.id,
        kind: "measurement",
        at: m.at,
        label: `${m.measurementType}${m.value !== null ? `: ${m.value} ${m.unit}` : `: ${m.text}`}`,
        detail: `${m.acquisition}${m.instrument ? ` • ${m.instrument}` : ""}${m.calibration === "unknown" ? " • calibration unknown" : ` • calibration: ${m.calibration}`}`,
        relation,
      });
    }

    if (options.includeSessionEvents) {
      const events = (await this.db.sessionEvents.where("caseId").equals(evidence.caseId).toArray()).filter(
        (e) => e.at >= windowStart && e.at <= windowEnd,
      );
      for (const e of events) {
        records.push({
          id: e.id,
          kind: "sessionEvent",
          at: e.at,
          label: e.type,
          detail: e.detail,
          relation: evidence.sessionId && e.sessionId === evidence.sessionId ? "Recorded during the same session" : "Nearby in time",
        });
      }
    }

    if (options.includeObservations) {
      const observations = (await this.db.walkthroughObservations.where("caseId").equals(evidence.caseId).toArray()).filter(
        (o) => !o.amended && o.createdAt >= windowStart && o.createdAt <= windowEnd,
      );
      for (const o of observations) {
        records.push({
          id: o.id,
          kind: "observation",
          at: o.createdAt,
          label: `Observation (${o.kind})`,
          detail: o.description,
          relation:
            evidence.roomId && o.roomId === evidence.roomId
              ? "Recorded in the same room"
              : "Nearby in time",
        });
      }
    }

    const notes: string[] = [];
    const hasEnvironmental = measurements.length > 0;
    if (!hasEnvironmental) {
      missing.push("No environmental measurements were recorded within this window.");
    }
    if (evidence.roomId && !measurements.some((m) => m.roomId === evidence.roomId)) {
      missing.push("No environmental measurements were recorded in the same room.");
    }
    if (!evidence.captureTimestamp) {
      notes.push("The capture timestamp is unknown; the evidence acquisition time was used as the centre of the window.");
    }
    if (evidence.captureTimestampSource === "fileMetadata") {
      notes.push("The capture time came from file metadata, which can be absent or inaccurate.");
    }

    const availability: ComparisonResult["availability"] =
      records.length === 0
        ? hasEnvironmental
          ? "noMatchingRecords"
          : "insufficientData"
        : measurements.some((m) => evidence.roomId && m.roomId === evidence.roomId)
          ? "sameRoomRecordsFound"
          : "nearbyReadingsFound";

    notes.push("Temporal proximity does not establish causation. These records are listed for context only; no statistical correlation is calculated.");

    return {
      evidenceId,
      evidenceTitle: evidence.title,
      windowStart,
      windowEnd,
      availability,
      records: records.sort((a, b) => a.at - b.at),
      missing,
      notes,
    };
  }
}
