/**
 * TPI-V2-WEB-017 — read-only case report preview.
 *
 * Renders the assembler's persisted-record model. No finding, conclusion,
 * confidence score or paranormal classification is generated here. The only
 * actions are browser print/save-as-PDF and a case-scoped evidence manifest
 * download; neither mutates the source records.
 */
import "./report.css";
import { esc } from "../dashboard/shell";
import {
  evidenceManifestJson,
  reportFileToken,
  type CaseReportModel,
  type ReportEvidence,
} from "../../core/reporting/caseReport";

function fmt(ms: number | null | undefined): string {
  return ms ? new Date(ms).toLocaleString() : "Not recorded";
}

function fmtDuration(minutes: number | null): string {
  if (minutes === null) return "Not recorded";
  if (minutes < 60) return `${minutes} min`;
  return `${Math.floor(minutes / 60)} h ${minutes % 60} min`;
}

function missing(text = "Not recorded"): string {
  return `<span class="report-missing" data-report-missing>${esc(text)}</span>`;
}

function cell(value: string | null | undefined, fallback = "Not recorded"): string {
  return value?.trim() ? esc(value.trim()) : missing(fallback);
}

function badge(text: string, extra = ""): string {
  return `<span class="report-badge${extra ? ` ${extra}` : ""}">${esc(text)}</span>`;
}

function section(id: string, title: string, body: string, source: string): string {
  return `<section class="report-section" data-report-section="${esc(id)}" data-report-source="${esc(source)}">
    <h3 class="report-section-title">${esc(title)}</h3>
    ${body}
  </section>`;
}

function empty(text: string): string {
  return `<p class="report-empty" data-report-empty>${esc(text)}</p>`;
}

function table(headers: string[], rows: string[][]): string {
  if (!rows.length) return empty("No records are available for this section.");
  return `<div class="report-table-wrap"><table class="report-table">
    <thead><tr>${headers.map((header) => `<th scope="col">${esc(header)}</th>`).join("")}</tr></thead>
    <tbody>${rows.map((row) => `<tr>${row.map((value) => `<td>${value}</td>`).join("")}</tr>`).join("")}</tbody>
  </table></div>`;
}

function list(items: string[]): string {
  return `<ul class="report-list">${items.map((item) => `<li>${item}</li>`).join("")}</ul>`;
}

function sourceLine(source: string, id: string): string {
  return `<p class="report-source">Source: ${esc(source)} · ${esc(id)}</p>`;
}

function evidenceBadge(status: string): string {
  const extra = status === "verified" ? " report-badge-ok" : status === "unverified" ? " report-badge-warn" : " report-badge-error";
  return badge(status, extra);
}

function evidenceProvenance(item: ReportEvidence): string {
  const parts = [
    item.provenanceOrigin ? `origin: ${item.provenanceOrigin}` : "",
    item.recordedBy ? `recorded by: ${item.recordedBy}` : "",
    item.recordedAt ? `recorded: ${fmt(item.recordedAt)}` : "",
    item.verifiedAt ? `verified: ${fmt(item.verifiedAt)}` : "",
  ].filter(Boolean);
  return parts.length ? `<br><span class="report-source">${esc(parts.join(" · "))}</span>` : "";
}

export function caseReportHtml(report: CaseReportModel): string {
  const caseLabel = report.caseNumber || report.caseId;
  const title = report.title || "Untitled case";
  const identity = table(
    ["Field", "Recorded value", "Source"],
    [
      ["Case number", cell(report.caseNumber, "Not recorded"), esc("cases")],
      ["Case ID", esc(report.caseId), esc("cases")],
      ["Title", cell(report.title), esc("cases")],
      ["Investigation type", cell(report.investigationType), esc("cases")],
      ["Status", cell(report.status), esc("cases")],
      ["Current phase", cell(report.currentPhase), esc("cases")],
      ["Opened", esc(fmt(report.createdAt)), esc("cases · createdAt")],
      ["Last updated", esc(fmt(report.updatedAt)), esc("cases · updatedAt")],
      ["Closed", esc(fmt(report.closedAt)), esc("cases · closedAt")],
      ["Archived", esc(fmt(report.archivedAt)), esc("cases · archivedAt")],
    ],
  );

  const client = table(
    ["Field", "Recorded value", "Source"],
    [
      ["Name", cell(report.client.name), esc(report.client.source)],
      ["Phone", cell(report.client.phone), esc(report.client.source)],
      ["Email", cell(report.client.email), esc(report.client.source)],
      ["Client notes", cell(report.client.notes), esc(report.client.source)],
      ["Record id", report.client.recordId ? esc(report.client.recordId) : missing("No linked client record"), esc(report.client.source)],
    ],
  );

  const location = table(
    ["Field", "Recorded value", "Source"],
    [
      ["Name", cell(report.location.name), esc(report.location.source)],
      ["Address", cell(report.location.address), esc(report.location.source)],
      ["Property details", cell(report.location.propertyDetails), esc(report.location.source)],
      ["Structure", report.structure ? esc(`${report.structure.name} (${report.structure.kind}), revision ${report.structure.revision}`) : missing("No structure recorded"), esc("propertyStructures")],
      ["Rooms", report.rooms.length ? esc(report.rooms.map((room) => `${room.name}${room.archived ? " (archived)" : ""}`).join(", ")) : missing("No rooms recorded"), esc("structureRooms")],
    ],
  );

  const sessionBody = report.sessions.length
    ? `<div class="report-list">${report.sessions
        .map(
          (session) => `<article class="report-entry" data-report-session="${esc(session.id)}">
            <div class="report-entry-head"><strong>${esc(fmt(session.startedAt))}</strong>${badge(session.status)}</div>
            <p class="report-meta">Ended: ${esc(fmt(session.endedAt))} · Duration: ${esc(fmtDuration(session.durationMinutes))} · Investigators: ${esc(session.investigators.length ? session.investigators.join(", ") : "Not recorded")} · Room: ${cell(session.roomName)}</p>
            ${session.notes ? `<p class="report-copy">${esc(session.notes)}</p>` : `<p class="report-missing">No session notes recorded.</p>`}
            ${sourceLine("sessions", session.id)}
          </article>`,
        )
        .join("")}</div>`
    : empty("No investigation sessions recorded.");

  const summaryBody = report.summaries.length
    ? `<div class="report-list">${report.summaries
        .map(
          (summary) => `<article class="report-entry" data-report-summary="${esc(summary.id)}">
            <div class="report-entry-head"><strong>${cell(summary.roomName)}</strong>${badge("Room summary")}</div>
            <p class="report-meta">Session: ${esc(summary.sessionLabel)} · Created: ${esc(fmt(summary.createdAt))} · Updated: ${esc(fmt(summary.updatedAt))} · Recorded by: ${cell(summary.author, "not recorded")}</p>
            <p class="report-copy">${esc(summary.body)}</p>
            ${sourceLine("roomSummaries", summary.id)}
          </article>`,
        )
        .join("")}</div>`
    : empty("No per-room summary text recorded.");

  const notesBody = report.notes.length
    ? `<div class="report-list">${report.notes
        .map(
          (note) => `<article class="report-entry" data-report-note="${esc(note.id)}">
            <div class="report-entry-head">${badge(note.kindLabel)}<strong>${cell(note.title, "Untitled note")}</strong></div>
            <p class="report-meta">Room: ${esc(note.roomName)} · Session: ${esc(note.sessionLabel)} · Recorded by: ${cell(note.author, "not recorded")} · Created: ${esc(fmt(note.createdAt))} · Updated: ${esc(fmt(note.updatedAt))}</p>
            <p class="report-copy">${esc(note.body)}</p>
            ${sourceLine("investigationNotes", note.id)}
          </article>`,
        )
        .join("")}</div>`
    : empty("No investigator notes recorded.");

  const claimBody = report.claims.length
    ? table(
        ["Claim", "Classification", "Room", "Occurrence", "Witnesses", "Notes"],
        report.claims.map((claim) => [
          `<strong>${esc(claim.title)}</strong><br><span class="report-source">${esc(claim.id)}</span>`,
          badge(claim.classification),
          cell(claim.roomName),
          [claim.firstOccurrence ? `First: ${esc(claim.firstOccurrence)}` : "", claim.mostRecentOccurrence ? `Most recent: ${esc(claim.mostRecentOccurrence)}` : "", claim.frequency ? `Frequency: ${esc(claim.frequency)}` : "", claim.timePattern ? `Pattern: ${esc(claim.timePattern)}` : ""].filter(Boolean).join("<br>") || missing(),
          cell(claim.witnesses),
          cell(claim.notes),
        ]),
      )
    : empty("No client or witness claims recorded.");

  const evidenceBody = report.evidence.length
    ? `${table(
        ["Evidence", "Type", "Acquired", "Integrity", "Review", "SHA-256", "File", "Context"],
        report.evidence.map((item) => [
          `<strong>${esc(item.title)}</strong><br><span class="report-source">${esc(item.id)}</span>`,
          `${esc(item.mediaType)}<br><span class="report-source">${esc(item.kind)}</span>`,
          `${esc(fmt(item.acquiredAt))}<br><span class="report-source">source: ${esc(item.timestampSource)}</span>`,
          evidenceBadge(item.integrity),
          badge(item.reviewStatus),
          `<code class="report-hash">${esc(item.contentHash)}</code>`,
          `${esc(item.fileName)}<br><span class="report-source">${item.fileSizeBytes.toLocaleString()} bytes</span>`,
          `${cell(item.roomName, "Room not recorded")}<br><span class="report-source">${cell(item.sessionLabel, "Session not recorded")}</span>${evidenceProvenance(item)}`,
        ]),
      )}<p class="report-note">Hashes are the stored SHA-256 values. They demonstrate byte integrity of the referenced file, not authenticity, causation or paranormal activity. Media bytes are not embedded in this preview or manifest.</p>`
    : empty("No evidence records recorded.");

  const measurementBody = report.measurements.length
    ? table(
        ["Type", "Value", "Time", "Acquisition", "Instrument", "Calibration", "Context"],
        report.measurements.map((item) => [
          esc(item.measurementType),
          item.value !== null ? esc(`${item.value}${item.unit ? ` ${item.unit}` : ""}`) : cell(item.text, "No numeric value"),
          esc(fmt(item.at)),
          esc(item.acquisition),
          cell(item.instrument),
          esc(item.calibration),
          `${cell(item.roomName, "Room not recorded")}<br><span class="report-source">${cell(item.sessionLabel, "Session not recorded")}${item.notes ? ` · ${esc(item.notes)}` : ""}</span>`,
        ]),
      )
    : empty("No equipment measurements recorded.");

  const findingBody = report.findings.length
    ? `<div class="report-list">${report.findings
        .map(
          (finding) => `<article class="report-entry" data-report-finding="${esc(finding.id)}">
            <div class="report-entry-head">${badge(finding.classification)}<strong>${esc(finding.title)}</strong></div>
            <p class="report-meta">${cell(finding.roomName, "Area not recorded")} · ${cell(finding.sessionLabel, "Session not recorded")} · ${esc(fmt(finding.at))}${finding.amended ? " · amended" : ""}${finding.evidenceId ? ` · evidence ${esc(finding.evidenceId)}` : ""}</p>
            <p class="report-copy">${esc(finding.body)}</p>
            ${sourceLine(finding.source, finding.id)}
          </article>`,
        )
        .join("")}</div>`
    : empty("No investigator-authored findings or observations recorded. None were generated.");

  const sourceBody = table(
    ["Record family", "Table", "Records", "Included in this report"],
    report.sources.map((source) => [esc(source.label), esc(source.table), String(source.records), esc(source.included)]),
  );

  const limitations = list([
    ...report.warnings.map((warning) => esc(warning)),
    ...report.limitations.map((limitation) => esc(limitation)),
  ]);

  return `<section class="case-report" data-report-preview data-report-case-id="${esc(report.caseId)}">
    <header class="report-header">
      <div>
        <p class="report-kicker">Investigation report · read-only foundation</p>
        <h2>${esc(caseLabel)} — ${esc(title)}</h2>
        <p class="report-meta">Generated ${esc(fmt(report.generatedAt))} · Model v${report.reportVersion} · Database schema v${report.databaseSchemaVersion}</p>
      </div>
      <div class="report-actions" data-report-actions>
        <button class="button-secondary" id="report-print" type="button">Print report</button>
        <button class="button-secondary" id="report-manifest" type="button">Download Evidence Manifest (JSON)</button>
      </div>
    </header>
    <p class="report-integrity" data-report-integrity>This preview reproduces persisted records only. It does not generate findings, conclusions, confidence scores, classifications or paranormal claims. Missing information is labelled, not inferred.</p>
    ${section("identification", "Case Identification", identity, "cases")}
    ${section("client", "Client", client, report.client.source)}
    ${section("location", "Location & Property", location, report.location.source)}
    ${section("sessions", "Investigation Sessions", sessionBody, "sessions")}
    ${section("summaries", "Per-Room Summaries", summaryBody, "roomSummaries")}
    ${section("notes", "Investigator Notes", notesBody, "investigationNotes")}
    ${section("claims", "Reported Claims", `${claimBody}<p class="report-note">Client and witness statements remain statements; they are not verified facts, evidence or findings.</p>`, "claims")}
    ${section("evidence", "Evidence References", evidenceBody, "evidence")}
    ${section("measurements", "Recorded Equipment Measurements", `${measurementBody}<p class="report-note">Measurements are recorded readings with their acquisition and calibration. They are not interpreted as findings.</p>`, "environmentMeasurements")}
    ${section("findings", "Investigator Findings & Observations", `${findingBody}<p class="report-note">Only entries already authored by an investigator are reproduced. No finding or conclusion was generated from evidence, measurements or claims.</p>`, "walkthroughObservations / observations")}
    ${section("sources", "Report Sources & Inclusion", sourceBody, "report model")}
    ${section("limitations", "Missing Data & Limitations", limitations, "report model")}
  </section>`;
}

export function wireCaseReport(container: HTMLElement, report: CaseReportModel): void {
  container.querySelector<HTMLButtonElement>("#report-print")?.addEventListener("click", () => {
    window.print();
  });

  container.querySelector<HTMLButtonElement>("#report-manifest")?.addEventListener("click", () => {
    const token = reportFileToken(report);
    const blob = new Blob([evidenceManifestJson(report)], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement("a");
    anchor.href = url;
    anchor.download = `Case_${token}_EvidenceManifest.json`;
    document.body.appendChild(anchor);
    anchor.click();
    anchor.remove();
    window.setTimeout(() => URL.revokeObjectURL(url), 1_000);
  });
}
