/**
 * Guided intake service (TPI-V2-WEB-006).
 *
 * iOS origins: PPGuidedIntakeStepResolver / PPGuidedIntakeAnswerApplier /
 * PPIntakeDossier. Supports partial save + resume, conditional questions,
 * claim repeat loops, and completion derived from real responses (never a
 * bare completion flag). Client statements are never promoted to verified
 * facts — the statement-source classification is preserved per response.
 */
import type { TPIDatabase } from "../db";
import { v4 as uuidv4 } from "../../shared/uuid";
import type { IntakeDossierRecord, IntakeResponseRecord, IntakeSource } from "../types";
import { ValidationError } from "../validation";
import { AuditService } from "../audit";
import {
  INTAKE_QUESTIONS,
  INTAKE_QUESTION_VERSION,
  expandQuestions,
  questionById,
  validateResponse,
  type IntakeQuestion,
} from "./questions";

export interface IntakeMissingItem {
  questionId: string;
  section: string;
  prompt: string;
  reason: string;
}

export interface IntakeEvaluation {
  complete: boolean;
  percent: number;
  applicableCount: number;
  answeredCount: number;
  missing: IntakeMissingItem[];
}

export class IntakeService {
  private readonly audit: AuditService;

  constructor(private readonly db: TPIDatabase) {
    this.audit = new AuditService(db);
  }

  async ensureDossier(caseId: string): Promise<IntakeDossierRecord> {
    const existing = await this.db.intakeDossiers.where("caseId").equals(caseId).first();
    if (existing) return existing as IntakeDossierRecord;
    const ts = Date.now();
    const dossier: IntakeDossierRecord = {
      id: uuidv4(),
      schemaVersion: 6,
      createdAt: ts,
      updatedAt: ts,
      caseId,
      status: "inProgress",
      finalizedAt: null,
      investigatorNotes: "",
      walkthrough: {
        roomsVisited: false,
        subLocationsPinned: false,
        witnessStatementsCaptured: false,
        environmentalNotesEntered: false,
        additionalClaimsChecked: false,
      },
    };
    await this.db.intakeDossiers.put(dossier);
    await this.audit.record("intakeStarted", "Guided intake started.", {
      caseId,
      affectedRecordId: dossier.id,
    });
    return dossier;
  }

  async getDossier(caseId: string): Promise<IntakeDossierRecord | undefined> {
    return this.db.intakeDossiers.where("caseId").equals(caseId).first();
  }

  async listResponses(caseId: string): Promise<IntakeResponseRecord[]> {
    return this.db.intakeResponses.where("caseId").equals(caseId).toArray();
  }

  /** Saved answers keyed by effective question id (loop ids included). */
  async answerMap(caseId: string): Promise<Map<string, IntakeResponseRecord>> {
    const responses = await this.listResponses(caseId);
    const map = new Map<string, IntakeResponseRecord>();
    for (const r of responses) {
      const key = r.repeatIndex > 0 ? `${r.questionId}#${r.repeatIndex}` : r.questionId;
      map.set(key, r);
    }
    return map;
  }

  /** Number of claim sets currently active (1 + answered "Yes" decisions). */
  claimCount(answers: Map<string, IntakeResponseRecord>): number {
    let count = 1;
    for (let i = 0; i < 32; i++) {
      const decision = answers.get(i === 0 ? "additionalClaimDecision" : `additionalClaimDecision#${i}`);
      if (!decision || decision.status !== "answered") break;
      const value = JSON.parse(decision.value) as string;
      if (value === "Yes") count = i + 2;
      else break;
    }
    return count;
  }

  /** Questions applicable to the current answer state, with index-aware conditions. */
  applicableQuestions(claimCount: number, answers: Map<string, IntakeResponseRecord>): IntakeQuestion[] {
    const rawValue = (id: string): string | undefined => {
      const r = answers.get(id);
      if (!r || r.status !== "answered") return undefined;
      try {
        const parsed = JSON.parse(r.value) as unknown;
        return Array.isArray(parsed) ? parsed.join(", ") : String(parsed);
      } catch {
        return r.value;
      }
    };
    const questions = expandQuestions(claimCount);
    return questions.filter((q) => {
      if (!q.appliesTo) return true;
      // Rewrite bare loop-question ids to the same repeat index.
      const index = q.id.includes("#") ? Number(q.id.split("#")[1]) : 0;
      const get = (id: string): string | undefined => {
        const base = id.split("#")[0];
        const looped = INTAKE_QUESTIONS.some((x) => x.id === base && x.loop);
        return rawValue(looped && index > 0 ? `${base}#${index}` : id);
      };
      return q.appliesTo(get);
    });
  }

  /** Save (or update) a single response. Partial save — the user can leave any time. */
  async saveResponse(
    caseId: string,
    questionId: string,
    input: { value: string; status: "answered" | "skipped"; source?: IntakeSource; repeatIndex?: number },
  ): Promise<IntakeResponseRecord> {
    const question = questionById(questionId);
    if (!question) throw new ValidationError(`Unknown intake question: ${questionId}`, "questionId");
    const repeatIndex = input.repeatIndex ?? 0;
    if (input.status === "answered") {
      const error = validateResponse(question, input.value, "answered");
      if (error) throw new ValidationError(error, "value");
    }
    await this.ensureDossier(caseId);
    const responses = await this.listResponses(caseId);
    const existing = responses.find((r) => r.questionId === questionId && r.repeatIndex === repeatIndex);
    const record: IntakeResponseRecord = existing
      ? {
          ...existing,
          value: JSON.stringify(input.status === "answered" ? parseValue(question, input.value) : ""),
          status: input.status,
          source: input.source ?? existing.source,
          updatedAt: Date.now(),
        }
      : {
          id: uuidv4(),
          schemaVersion: 6,
          createdAt: Date.now(),
          updatedAt: Date.now(),
          caseId,
          questionId,
          questionVersion: INTAKE_QUESTION_VERSION,
          value: JSON.stringify(input.status === "answered" ? parseValue(question, input.value) : ""),
          status: input.status,
          source: input.source ?? question.source,
          repeatIndex,
        };
    await this.db.intakeResponses.put(record);
    await this.audit.record("intakeUpdated", `Intake response recorded for "${question.id}" (${record.status}).`, {
      caseId,
      affectedRecordId: record.id,
      metadata: { questionId, status: record.status },
      // NOTE: response content is intentionally NOT logged (contains PII).
    });
    return record;
  }

  /** Evaluate intake completion from real responses (directive §15). */
  async evaluate(caseId: string): Promise<IntakeEvaluation> {
    const answers = await this.answerMap(caseId);
    const claimCount = this.claimCount(answers);
    const questions = this.applicableQuestions(claimCount, answers);
    const missing: IntakeMissingItem[] = [];
    let answeredCount = 0;
    for (const q of questions) {
      const response = answers.get(q.id);
      if (response?.status === "answered") {
        answeredCount++;
        continue;
      }
      if (response?.status === "skipped" && !q.required) {
        answeredCount++;
        continue;
      }
      if (!q.required && !response) {
        // Unanswered optional question — recorded as outstanding progress but
        // does not block completion (directive §15 keys on required responses).
        continue;
      }
      missing.push({
        questionId: q.id,
        section: q.section,
        prompt: q.prompt,
        reason:
          response?.status === "skipped"
            ? "A required question was skipped and must be answered before intake can finalize."
            : "Required question not yet answered.",
      });
    }
    const applicableCount = questions.length;
    const percent = applicableCount === 0 ? 100 : Math.round((answeredCount / applicableCount) * 100);
    return { complete: missing.length === 0 && applicableCount > 0, percent, applicableCount, answeredCount, missing };
  }

  /** Finalize intake — requires all applicable required questions answered. */
  async finalize(caseId: string, actor = "local-user"): Promise<IntakeDossierRecord> {
    const evaluation = await this.evaluate(caseId);
    if (!evaluation.complete) {
      const first = evaluation.missing[0];
      throw new ValidationError(
        `Intake cannot be finalized: ${evaluation.missing.length} required question(s) outstanding. Next: "${first?.prompt ?? ""}" (${first?.reason ?? ""})`,
        "intake",
      );
    }
    const dossier = await this.ensureDossier(caseId);
    if (dossier.status === "finalized") return dossier;
    const next: IntakeDossierRecord = { ...dossier, status: "finalized", finalizedAt: Date.now(), updatedAt: Date.now() };
    await this.db.intakeDossiers.put(next);
    await this.audit.record("intakeFinalized", `Intake dossier finalized (${evaluation.answeredCount} responses).`, {
      caseId,
      affectedRecordId: dossier.id,
    });
    await this.reconcileChecklist(caseId);
    void actor;
    return next;
  }

  /** Reopen a finalized dossier for documented corrections (history preserved). */
  async reopen(caseId: string, reason: string): Promise<IntakeDossierRecord> {
    if (!reason.trim()) throw new ValidationError("Reopening intake requires a documented reason.", "reason");
    const dossier = await this.ensureDossier(caseId);
    const next: IntakeDossierRecord = { ...dossier, status: "inProgress", finalizedAt: null, updatedAt: Date.now() };
    await this.db.intakeDossiers.put(next);
    await this.audit.record("intakeUpdated", `Intake reopened for correction: ${reason.slice(0, 200)}`, {
      caseId,
      affectedRecordId: dossier.id,
    });
    return next;
  }

  /**
   * Checklist reconciliation for `intakeComplete` — mirrors the documents
   * strategy: completion may only come from real evaluated responses.
   */
  async reconcileChecklist(caseId: string): Promise<void> {
    const evaluation = await this.evaluate(caseId);
    await this.reconcileChecklistFromEvaluation(caseId, evaluation);
  }

  /** Checklist sync from a pre-computed evaluation (used by the workflow engine). */
  async reconcileChecklistFromEvaluation(caseId: string, evaluation: IntakeEvaluation): Promise<void> {
    const items = await this.db.checklistItems.where("caseId").equals(caseId).toArray();
    const item = items.find((i) => i.definitionId === "intakeComplete");
    if (!item) return;
    const dossier = await this.getDossier(caseId);
    const satisfied = evaluation.complete && dossier?.status === "finalized";
    if (satisfied && item.status !== "complete") {
      await this.db.checklistItems.put({
        ...item,
        status: "complete",
        completedAt: Date.now(),
        completedBy: "intake-service",
        updatedAt: Date.now(),
      });
      await this.audit.record("checklistChanged", "Intake checklist satisfied by evaluated intake responses.", {
        caseId,
        affectedRecordId: item.id,
      });
    } else if (!satisfied && (item.status === "complete" || item.status === "exception")) {
      await this.db.checklistItems.put({
        ...item,
        status: "pending",
        completedAt: null,
        completedBy: null,
        notes:
          "Reconciled under TPI-V2-WEB-006: the previous checklist completion was not backed by evaluated intake responses.",
        updatedAt: Date.now(),
      });
      await this.audit.record("checklistChanged", "Intake checklist item reset — evaluated responses did not support completion.", {
        caseId,
        affectedRecordId: item.id,
      });
    }
  }
}

function parseValue(question: IntakeQuestion, raw: string): unknown {
  if (question.type === "multi") {
    try {
      const parsed = JSON.parse(raw) as unknown;
      if (Array.isArray(parsed)) return parsed;
    } catch {
      /* fall through */
    }
    return raw.split(",").map((s) => s.trim());
  }
  return raw;
}

/** Exported for tests/UI: full canonical question list. */
export { INTAKE_QUESTIONS };
