/**
 * Intake attachment service (TPI-V2-WEB-010G §9–§11, Phase 010G-B).
 *
 * Field-for-field port of `PPIntakeAttachment` and the original "Add Attachment"
 * sheet in `Cases/IntakeFormView.swift`. Attachments belong to the **Research
 * Archive** intake section.
 *
 * Storage: the existing evidence pipeline holds any binary file (OPFS + SHA-256);
 * this service stores the original metadata record and links to the file by
 * `evidenceId`. There is no second attachment storage system and no copy of bytes.
 *
 * Source classification keeps the distinction the directive requires: a client's
 * document is a *client-supplied* record and is never presented as an
 * investigator observation.
 */
import type { TPIDatabase } from "../db";
import { SCHEMA_VERSION } from "../db";
import { v4 as uuidv4 } from "../../shared/uuid";
import type { IntakeAttachmentRecord } from "../types";
import { ValidationError } from "../validation";
import { AuditService } from "../audit";

/** Original verification statuses (IntakeFormView `attachmentStatuses`). */
export const ATTACHMENT_STATUSES = ["Submitted by Client", "Pending Verification", "Verified"] as const;
/** Original default (PPIntakeAttachment init). */
export const DEFAULT_ATTACHMENT_STATUS = "Pending Verification";
/** Original document types (IntakeFormView `documentTypes`). */
export const DOCUMENT_TYPES = [
  "Deed",
  "Property Record",
  "Historical Article",
  "Census Record",
  "Map",
  "Historical Photograph",
  "Permit Record",
  "Newspaper Clipping",
  "Death Certificate",
  "Other",
] as const;
export const DEFAULT_DOCUMENT_TYPE = "Other";

export type AttachmentClassification = "clientSupplied" | "investigatorCaptured" | "importedExternal" | "notRecorded";
export const ATTACHMENT_CLASSIFICATIONS: readonly AttachmentClassification[] = [
  "clientSupplied", "investigatorCaptured", "importedExternal", "notRecorded",
];

export interface IntakeAttachment extends IntakeAttachmentRecord {
  evidenceId: string | null;
  questionId: string | null;
  classification: AttachmentClassification;
  dossierId: string | null;
}

function normalise(row: IntakeAttachmentRecord): IntakeAttachment {
  return {
    ...row,
    evidenceId: row.evidenceId ?? null,
    questionId: row.questionId ?? null,
    classification: ATTACHMENT_CLASSIFICATIONS.includes(row.classification as AttachmentClassification)
      ? row.classification as AttachmentClassification
      : "notRecorded",
    dossierId: row.dossierId ?? null,
    documentType: DOCUMENT_TYPES.includes(row.documentType as never) ? row.documentType : DEFAULT_DOCUMENT_TYPE,
    verificationStatus: ATTACHMENT_STATUSES.includes(row.verificationStatus as never)
      ? row.verificationStatus
      : DEFAULT_ATTACHMENT_STATUS,
  };
}

export interface AttachmentInput {
  documentTitle: string;
  documentType: string;
  source: string;
  dateText: string;
  uploadedBy: string;
  verificationStatus: string;
  notes: string;
  evidenceId?: string | null;
  questionId?: string | null;
  classification?: AttachmentClassification;
  dossierId?: string | null;
}

export class IntakeAttachmentService {
  private readonly audit: AuditService;

  constructor(private readonly db: TPIDatabase) {
    this.audit = new AuditService(db);
  }

  /** Idempotently ensure the intake dossier exists for the case. */
  private async ensureDossier(caseId: string): Promise<string> {
    const existing = await this.db.intakeDossiers.where("caseId").equals(caseId).first();
    if (existing) return existing.id;
    const ts = Date.now();
    const id = uuidv4();
    await this.db.intakeDossiers.put({
      id,
      schemaVersion: SCHEMA_VERSION,
      createdAt: ts,
      updatedAt: ts,
      caseId,
      status: "inProgress",
      finalizedAt: null,
      investigatorNotes: "",
      walkthrough: {
        roomsVisited: false,
        subLocationsPinned: false,
        witnessStatementsCaptured: false,
        environmentalNotesEntered: false,
        additionalClaimsChecked: false,
      },
    });
    return id;
  }

  async listForCase(caseId: string): Promise<IntakeAttachment[]> {
    const rows = await this.db.intakeAttachments.where("caseId").equals(caseId).toArray();
    return rows.map(normalise).sort((a, b) => a.createdAt - b.createdAt);
  }

  async get(id: string): Promise<IntakeAttachment | undefined> {
    const row = await this.db.intakeAttachments.get(id);
    return row ? normalise(row) : undefined;
  }

  /** Create an attachment record (original fields + optional evidence link). */
  async create(caseId: string, input: AttachmentInput): Promise<IntakeAttachment> {
    const caseRecord = await this.db.cases.get(caseId);
    if (!caseRecord) throw new ValidationError(`Case not found: ${caseId}`, "caseId");
    if (!input.documentTitle.trim()) {
      throw new ValidationError("What is the title of this document? A title is required.", "documentTitle");
    }
    if (input.documentType && !DOCUMENT_TYPES.includes(input.documentType as never)) {
      throw new ValidationError(`Unknown document type: ${input.documentType}`, "documentType");
    }
    if (input.verificationStatus && !ATTACHMENT_STATUSES.includes(input.verificationStatus as never)) {
      throw new ValidationError(
        `Unknown verification status: ${input.verificationStatus}. Expected one of: ${ATTACHMENT_STATUSES.join(", ")}.`,
        "verificationStatus",
      );
    }
    if (input.classification && !ATTACHMENT_CLASSIFICATIONS.includes(input.classification)) {
      throw new ValidationError(`Unknown source classification: ${input.classification}.`, "classification");
    }
    if (input.evidenceId) {
      const evidence = await this.db.evidence.get(input.evidenceId);
      if (!evidence) throw new ValidationError("The linked evidence record does not exist.", "evidenceId");
      if (evidence.caseId !== caseId) {
        throw new ValidationError("The linked evidence belongs to a different case.", "evidenceId");
      }
    }
    const dossierId = input.dossierId ?? (await this.ensureDossier(caseId));
    const ts = Date.now();
    const record: IntakeAttachmentRecord = {
      id: uuidv4(),
      schemaVersion: SCHEMA_VERSION,
      createdAt: ts,
      updatedAt: ts,
      caseId,
      documentTitle: input.documentTitle.trim(),
      documentType: input.documentType || DEFAULT_DOCUMENT_TYPE,
      source: input.source.trim(),
      dateText: input.dateText.trim(),
      uploadedBy: input.uploadedBy.trim(),
      verificationStatus: input.verificationStatus || DEFAULT_ATTACHMENT_STATUS,
      notes: input.notes.trim(),
      evidenceId: input.evidenceId ?? null,
      questionId: input.questionId ?? "researchArchiveNotes",
      classification: input.classification ?? "notRecorded",
      dossierId,
    };
    await this.db.intakeAttachments.put(record);
    await this.audit.record("intakeUpdated", "Intake research attachment added.", {
      caseId,
      affectedRecordId: record.id,
      metadata: {
        documentType: record.documentType,
        verificationStatus: record.verificationStatus,
        classification: record.classification ?? "notRecorded",
        hasFile: Boolean(record.evidenceId),
      },
    });
    return normalise(record);
  }

  /** Edit an attachment (original form fields) — history is preserved by audit. */
  async update(id: string, patch: Partial<AttachmentInput>): Promise<IntakeAttachment> {
    const existing = await this.get(id);
    if (!existing) throw new ValidationError(`Attachment not found: ${id}`, "id");
    if (patch.documentTitle !== undefined && !patch.documentTitle.trim()) {
      throw new ValidationError("A title is required.", "documentTitle");
    }
    if (patch.documentType && !DOCUMENT_TYPES.includes(patch.documentType as never)) {
      throw new ValidationError(`Unknown document type: ${patch.documentType}`, "documentType");
    }
    if (patch.verificationStatus && !ATTACHMENT_STATUSES.includes(patch.verificationStatus as never)) {
      throw new ValidationError(`Unknown verification status: ${patch.verificationStatus}`, "verificationStatus");
    }
    if (patch.classification && !ATTACHMENT_CLASSIFICATIONS.includes(patch.classification)) {
      throw new ValidationError(`Unknown source classification: ${patch.classification}.`, "classification");
    }
    const next: IntakeAttachmentRecord = {
      ...existing,
      documentTitle: patch.documentTitle?.trim() ?? existing.documentTitle,
      documentType: patch.documentType ?? existing.documentType,
      source: patch.source?.trim() ?? existing.source,
      dateText: patch.dateText?.trim() ?? existing.dateText,
      uploadedBy: patch.uploadedBy?.trim() ?? existing.uploadedBy,
      verificationStatus: patch.verificationStatus ?? existing.verificationStatus,
      notes: patch.notes?.trim() ?? existing.notes,
      evidenceId: patch.evidenceId !== undefined ? patch.evidenceId : existing.evidenceId,
      questionId: patch.questionId !== undefined ? patch.questionId : existing.questionId,
      classification: patch.classification ?? existing.classification,
      updatedAt: Date.now(),
    };
    await this.db.intakeAttachments.put(next);
    await this.audit.record("intakeUpdated", "Intake research attachment updated.", {
      caseId: existing.caseId,
      affectedRecordId: id,
      metadata: {
        verificationStatus: next.verificationStatus,
        classification: next.classification ?? "notRecorded",
        hasFile: Boolean(next.evidenceId),
      },
    });
    return normalise(next);
  }

  /**
   * Remove the attachment record. The linked evidence file is NEVER deleted —
   * only the association is removed (§10.8), and the removal is audited.
   */
  async removeAssociation(id: string): Promise<{ removed: IntakeAttachment; evidencePreserved: boolean }> {
    const existing = await this.get(id);
    if (!existing) throw new ValidationError(`Attachment not found: ${id}`, "id");
    await this.db.intakeAttachments.delete(id);
    const evidencePreserved = existing.evidenceId
      ? (await this.db.evidence.get(existing.evidenceId)) !== undefined
      : true;
    await this.audit.record("intakeUpdated", "Intake research attachment association removed (evidence preserved).", {
      caseId: existing.caseId,
      affectedRecordId: id,
      metadata: {
        documentType: existing.documentType,
        evidencePreserved,
        evidenceId: existing.evidenceId ?? null,
      },
    });
    return { removed: existing, evidencePreserved };
  }

  /** Count used by the intake completion summary and tests. */
  async countForCase(caseId: string): Promise<number> {
    return this.db.intakeAttachments.where("caseId").equals(caseId).count();
  }
}
