/**
 * Investigation Session view (TPI-V2-WEB-008 §5/§6/§10/§11/§15/§19).
 *
 * Session controls, session event log, ambient audio level monitoring, manual
 * instrument entry (EMF and other quantities), and sensor/connectivity status.
 * All state comes from the authoritative services.
 */
import "./casehub.css";
import { getDb } from "../../core/db";
import { CaseRepository } from "../../core/repositories/caseRepository";
import { SessionService } from "../../core/session/sessionService";
import { InvestigationCompletionService, type InvestigationCompletion } from "../../core/workflow/investigationCompletionService";
import {
  CANONICAL_UNITS,
  EMF_METER_TYPES,
  K2_LED_LEVELS,
  MEASUREMENT_TYPE_LABELS,
  MeasurementService,
  UNIT_CONVERSIONS,
} from "../../core/environment/measurementService";
import { getAudioLevelMonitor, type AudioMonitorState, type AudioLevelSample } from "../../core/sensors/audioMonitor";
import { getSensorCapabilities, type SensorCapability } from "../../core/sensors/sensorCapabilities";
import { getConnectivity, type ConnectivityStatus } from "../../core/connectivity";
import { RoomSummaryRepository } from "../../core/repositories/notesRepository";
import type { InvestigationSessionRecord, MeasurementType, RoomSummaryRecord, WorkflowPhase } from "../../core/types";
import { esc, viewShell, wireBackButton } from "../dashboard/shell";
import { mountView, onDelegate, invalidateView, clearDrafts } from "../../shared/uidom";
import { renderCaseHub } from "./CaseHub";

const db = () => getDb();
const sessions = () => new SessionService(db());
const measurements = () => new MeasurementService(db(), sessions());

interface SessionUiState {
  caseId: string;
  sessionId: string | null;
  /** Selected room for the per-room summary panel (never inferred silently). */
  summaryRoomId: string | null;
  audioUnsub: (() => void) | null;
  connUnsub: (() => void) | null;
}

const ui = new WeakMap<HTMLElement, SessionUiState>();

function st(container: HTMLElement): SessionUiState {
  let s = ui.get(container);
  if (!s) {
    s = { caseId: "", sessionId: null, summaryRoomId: null, audioUnsub: null, connUnsub: null };
    ui.set(container, s);
  }
  return s;
}

function fmtDuration(ms: number): string {
  const total = Math.max(0, Math.floor(ms / 1000));
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  const s = total % 60;
  return `${h}h ${String(m).padStart(2, "0")}m ${String(s).padStart(2, "0")}s`;
}

function fmtTime(ms: number | null | undefined): string {
  return ms ? new Date(ms).toLocaleString() : "—";
}

function toast(message: string, error = false): void {
  const el = document.createElement("div");
  el.className = error ? "toast error" : "toast";
  el.setAttribute("role", error ? "alert" : "status");
  el.textContent = message;
  document.body.appendChild(el);
  window.setTimeout(() => el.remove(), 5000);
}

export interface SessionViewOptions {
  focusMeasurement?: MeasurementType;
  focusRoomId?: string | null;
  backToEquipment?: boolean;
}

export async function renderSessionView(
  container: HTMLElement,
  caseId: string,
  options: SessionViewOptions = {},
): Promise<void> {
  const record = await new CaseRepository(db()).getCase(caseId);
  if (!record) {
    invalidateView(container);
    mountView(container, viewShell("Investigation Session", `<div class="cc-empty">Case not found.</div>`));
    wireBackButton(container);
    return;
  }
  const s = st(container);
  if (s.caseId !== caseId) {
    s.caseId = caseId;
    s.sessionId = null;
  }
  const svc = sessions();
  // Recovery: sessions left running by a closed browser are flagged, not hidden.
  await svc.recoverInterruptedSessions(caseId);
  const allSessions = await svc.listSessions(caseId);
  if (!s.sessionId || !allSessions.some((x) => x.id === s.sessionId)) {
    s.sessionId = (await svc.activeSession(caseId))?.id ?? null;
  }
  const current = s.sessionId ? await svc.getSession(s.sessionId) : undefined;
  const investigationCompletion = await new InvestigationCompletionService(db()).getCompletion(caseId);
  const events = s.sessionId ? await svc.listEvents(s.sessionId) : [];
  const caseMeasurements = s.sessionId
    ? await measurements().query(caseId, { sessionId: s.sessionId })
    : await measurements().query(caseId);
  const structure = await db().propertyStructures.where("caseId").equals(caseId).first();
  const rooms = structure
    ? (await db().structureRooms.where("structureId").equals(structure.id).toArray()).filter((r) => !r.archived)
    : [];
  const summaries = s.sessionId
    ? await new RoomSummaryRepository(db()).listForSession(s.sessionId)
    : [];
  const preferredSummaryRoom = s.summaryRoomId ?? current?.currentRoomId ?? rooms[0]?.id ?? null;
  const summaryRoomId =
    preferredSummaryRoom && rooms.some((room) => room.id === preferredSummaryRoom)
      ? preferredSummaryRoom
      : rooms[0]?.id ?? null;
  s.summaryRoomId = summaryRoomId;
  const monitor = getAudioLevelMonitor();
  const capabilities = getSensorCapabilities().list();
  const connectivity = getConnectivity().getStatus();

  invalidateView(container);
  mountView(
    container,
    viewShell(
      `Investigation Session — ${record.caseNumber}`,
      `
      <div class="case-form" data-root="session-view" data-case-id="${esc(caseId)}" data-session-id="${esc(s.sessionId ?? "")}" data-epoch="${Date.now()}-${Math.random()}">
        <p class="cc-count">Elapsed time counts recorded session time only — paused time and browser-suspended time are excluded.</p>

        ${
          current
            ? sessionPanelHtml(current, svc)
            : `<div class="form-actions">
                 <input id="session-investigator" type="text" placeholder="Investigator name" aria-label="Investigator name">
                 <input id="session-device" type="text" placeholder="Device label (optional)" aria-label="Device label">
                 <button class="button-primary" id="create-session" type="button">Create Session</button>
               </div>
               <p class="cc-meta">A new session starts in <strong>planned</strong> state. Nothing is recorded until it is started.</p>`
        }

        ${current ? roomSummaryHtml(current, rooms, summaries, summaryRoomId) : ""}

        ${investigationCompletionHtml(record.currentPhase, investigationCompletion, allSessions)}

        ${
          current
            ? `
        <h3 class="cc-section-title">Measurements this session (${caseMeasurements.length})</h3>
        ${measurementListHtml(caseMeasurements.map((m) => ({
          id: m.id,
          type: MEASUREMENT_TYPE_LABELS[m.measurementType],
          value: m.value === null ? "" : `${m.value} ${m.unit}`,
          text: m.text,
          acquisition: m.acquisition,
          instrument: m.instrument,
          at: m.at,
          amended: m.amended,
        })))}

        <h3 class="cc-section-title">Session event log (${events.length})</h3>
        ${events.length === 0
          ? `<div class="cc-empty">No events recorded.</div>`
          : `<ul class="activity-list">${events
              .map(
                (e) =>
                  `<li><span class="when">${fmtTime(e.at)} • ${esc(e.type)} • ${esc(e.source)}</span><div class="what">${esc(e.detail)}</div></li>`,
              )
              .join("")}</ul>`}`
            : ""
        }

         ${measurementFormHtml(rooms, options.focusMeasurement, options.focusRoomId)}

        <h3 class="cc-section-title">Ambient Audio Level Monitor</h3>
        <div class="case-form" id="audio-monitor" data-audio-state="${esc(monitor.getState())}">
          <p class="cc-count"><strong id="audio-level">${monitor.getCurrentLevel() === null ? "—" : `${monitor.getCurrentLevel()!.toFixed(1)} dBFS`}</strong>
          • state: <span id="audio-state">${esc(monitor.getState())}</span></p>
          <div class="meter" role="meter" aria-valuenow="${monitor.getCurrentLevel() ?? -80}" aria-valuemin="-80" aria-valuemax="0" aria-label="Relative audio level in dBFS">
            <div class="fill" id="audio-meter-fill" style="width:${audioMeterWidth(monitor.getCurrentLevel())}%"></div>
          </div>
          <div id="audio-history" aria-label="Recent audio levels" style="display:flex;gap:2px;align-items:flex-end;height:40px;margin-top:8px;">
            ${audioHistoryHtml(monitor.getSamples())}
          </div>
          <div class="form-actions">
            <button class="button-primary" id="audio-start" type="button">Start Level Monitoring</button>
            <button class="secondary back-button" id="audio-stop" type="button">Stop Monitoring</button>
            <button class="button-secondary" id="audio-record" type="button" ${current ? "" : "disabled"}>Record Measurement from Window…</button>
            <button class="back-button" id="audio-clear" type="button">Clear Window</button>
          </div>
          <p class="cc-meta"><strong>Digital signal level (dBFS)</strong>, computed as 20·log10(RMS) clamped to −80…0 — the same calculation the original iOS NoiseMonitor uses.
          This is <strong>not</strong> a calibrated sound-pressure level (dB SPL) and no microphone calibration is claimed. Raw audio is never retained: only numeric levels are produced,
          and nothing is saved to the case unless you record a measurement. Monitoring stops when you stop it or leave this view.</p>
        </div>

        <h3 class="cc-section-title">Sensor & Device Status</h3>
        <div id="sensor-status">${capabilities.map(sensorRowHtml).join("")}</div>

        <h3 class="cc-section-title">Connectivity</h3>
        <div id="connectivity-status">${connectivityHtml(connectivity)}</div>
        <div class="form-actions"><button class="back-button" id="verify-connectivity" type="button">Verify Reachability</button></div>
        <p class="cc-meta">Browser-reported network state is a hint, not proof of reachability. Verification is manual and on-demand — no background network requests are made.</p>

        <h3 class="cc-section-title">Session History (${allSessions.length})</h3>
        ${allSessions.length === 0
          ? `<div class="cc-empty">No sessions yet.</div>`
          : allSessions
              .map(
                (x) => `
          <div class="case-row" data-session-row="${x.id}">
            <div>
              <div class="case-title">${esc(x.status)} — ${fmtTime(x.startedAt)}${x.interrupted && x.status === "active" ? ' <span class="status-badge error">INTERRUPTED</span>' : ""}</div>
              <div class="case-meta">Elapsed ${esc(fmtDuration(svc.elapsedMs(x)))} • ${esc(x.investigators.join(", ") || "no investigator recorded")}${x.pauseReason ? ` • pause reason: ${esc(x.pauseReason)}` : ""}</div>
            </div>
            <div style="display:flex;gap:6px;">
              ${x.id !== s.sessionId ? `<button class="back-button" data-open-session="${x.id}" type="button">Open</button>` : ""}
              ${x.status === "completed" || x.status === "aborted" ? `<button class="back-button" data-reopen-session="${x.id}" type="button">Reopen…</button>` : ""}
            </div>
          </div>`,
              )
              .join("")}

        <div class="form-actions">
           <button class="back-button" id="session-back" type="button">${options.backToEquipment ? "← Back to Equipment" : "← Back to Case Hub"}</button>
        </div>
      </div>
    `,
  ));

  wireHandlers(container, caseId, options);

  // Live audio + connectivity updates (subscriptions are re-established each
  // render and the previous ones are released to avoid duplicate listeners).
  s.audioUnsub?.();
  s.connUnsub?.();
  s.audioUnsub = monitor.subscribe((payload) => updateAudioUi(container, payload.state, payload.level, payload.samples));
  s.connUnsub = getConnectivity().subscribe((status) => {
    const el = container.querySelector<HTMLElement>("#connectivity-status");
    if (el) el.innerHTML = connectivityHtml(status);
  });

  wireBackButton(container);
}

function sessionPanelHtml(session: InvestigationSessionRecord, svc: SessionService): string {
  return `
    <div class="case-row" data-active-session="${session.id}">
      <div>
        <div class="case-title">Session ${esc(session.status)}${session.interrupted ? " (interrupted)" : ""}</div>
        <div class="case-meta">Started ${fmtTime(session.startedAt)} • elapsed ${esc(fmtDuration(svc.elapsedMs(session)))}${session.pausedAt ? ` • paused ${fmtTime(session.pausedAt)}` : ""}${session.pauseReason ? ` • ${esc(session.pauseReason)}` : ""}</div>
      </div>
      <span class="status-badge">${esc(session.status)}</span>
    </div>
    ${session.interrupted && session.status === "active"
      ? `<p class="cc-count" role="alert">This session was still recorded as active when the browser closed. It is flagged as interrupted — the browser was not monitoring, so no time or data is claimed for that gap. Resume it to continue, or end it.</p>`
      : ""}
    ${
      session.status === "planned"
        ? `<div class="form-actions"><button class="button-primary" id="start-session" type="button">Start Session</button></div>`
        : session.status === "active"
          ? `<div class="form-actions">
               <button class="button-secondary" id="pause-session" type="button">Pause Session</button>
               <button class="button-secondary" id="end-session" type="button">End Session (Completed)</button>
               <button class="back-button" id="abort-session" type="button">Abort Session…</button>
             </div>`
          : session.status === "paused"
            ? `<div class="form-actions">
                 <button class="button-primary" id="resume-session" type="button">Resume Session</button>
                 <button class="button-secondary" id="end-session" type="button">End Session (Completed)</button>
               </div>`
            : `<div class="form-actions">
                 <button class="button-secondary" id="review-session" type="button" ${session.reviewedAt ? "disabled" : ""}>Mark Reviewed</button>
               </div>`
    }`;
}

function roomSummaryHtml(
  session: InvestigationSessionRecord,
  rooms: Array<{ id: string; name: string; archived?: boolean }>,
  summaries: RoomSummaryRecord[],
  selectedRoomId: string | null,
): string {
  const selected = summaries.find((summary) => summary.roomId === selectedRoomId);
  const missingRoom = Boolean(selectedRoomId) && !rooms.some((room) => room.id === selectedRoomId);
  const savedList = summaries.length
    ? `<div class="room-summary-list" data-room-summary-list>
        ${summaries
          .map((summary) => {
            const room = rooms.find((item) => item.id === summary.roomId);
            return `<button class="case-row room-summary-row" type="button" data-open-room-summary="${esc(summary.roomId)}">
              <span><strong>${esc(room?.name ?? "Room unavailable")}</strong>
              <span class="cc-meta">Updated ${esc(fmtTime(summary.updatedAt))} · Recorded by ${esc(summary.author || "not recorded")}</span></span>
            </button>`;
          })
          .join("")}
      </div>`
    : `<div class="cc-empty" data-room-summary-none>No room summaries are saved for this session.</div>`;

  return `
    <section class="cc-native-card" data-room-summary-panel data-session-id="${esc(session.id)}" aria-labelledby="room-summary-title">
      <h3 class="cc-section-title" id="room-summary-title">Per-Room Investigation Summary</h3>
      <p class="cc-meta">Investigator-authored summary for one room in this session. It is saved once per case, session and room; editing replaces the stored text in place. It does not create findings, infer conclusions from measurements, or advance the investigation.</p>
      ${
        rooms.length === 0
          ? `<div class="cc-empty" data-room-summary-empty>No rooms are defined for this case. Add a room in Property Structure before recording a room summary.</div>`
          : `<div class="detail-field"><label for="room-summary-room">Room</label>
              <select id="room-summary-room" data-room-summary-room data-focus-id="room-summary-room:${session.id}">
                ${rooms.map((room) => `<option value="${esc(room.id)}"${room.id === selectedRoomId ? " selected" : ""}>${esc(room.name)}${room.archived ? " (archived)" : ""}</option>`).join("")}
                ${missingRoom ? `<option value="${esc(selectedRoomId ?? "")}" selected>Room unavailable</option>` : ""}
              </select></div>
            <div class="case-meta" data-room-summary-meta>
              ${selected ? `Created ${esc(fmtTime(selected.createdAt))} · Updated ${esc(fmtTime(selected.updatedAt))} · Recorded by ${esc(selected.author || "not recorded")}` : "No summary saved for this room and session."}
            </div>
            <div class="detail-field"><label for="room-summary-body">Summary text</label>
              <textarea id="room-summary-body" data-room-summary-body data-focus-id="room-summary-body:${session.id}:${selectedRoomId ?? "none"}" rows="4" placeholder="What happened in this room during this session — investigator text, not a conclusion.">${esc(selected?.body ?? "")}</textarea></div>
            <div class="detail-field"><label for="room-summary-author">Recorded by (optional)</label>
              <input id="room-summary-author" data-room-summary-author data-focus-id="room-summary-author:${session.id}:${selectedRoomId ?? "none"}" type="text" value="${esc(selected?.author ?? "")}" placeholder="Leave blank if no attribution is recorded"></div>
            <div class="form-actions"><button class="button-primary" id="room-summary-save" type="button">${selected ? "Save Room Summary" : "Create Room Summary"}</button></div>
            <p class="cc-meta">The stored text is preserved exactly; the summary is not regenerated from evidence, claims or measurements.</p>
            ${savedList}`
      }
    </section>`;
}

function investigationCompletionHtml(
  phase: WorkflowPhase,
  completion: InvestigationCompletion | undefined,
  sessions: InvestigationSessionRecord[],
): string {
  if (completion) {
    return `<section class="cc-native-card" data-investigation-completion="complete" aria-labelledby="investigation-completion-title">
      <h3 class="cc-section-title" id="investigation-completion-title">Investigation Completion</h3>
      <p class="cc-count">Explicitly completed ${esc(fmtTime(completion.completedAt))}.</p>
      <p class="cc-meta">Evidence Review is unlocked for this case. The completion event is retained in the case audit trail; ending or reopening a session does not erase it.</p>
    </section>`;
  }
  const eligible = phase === "investigation" || phase === "review" || phase === "summary";
  if (!eligible) {
    return `<section class="cc-native-card" data-investigation-completion="unavailable" aria-labelledby="investigation-completion-title">
      <h3 class="cc-section-title" id="investigation-completion-title">Investigation Completion</h3>
      <p class="cc-meta">Explicit completion becomes available after the workflow reaches the Investigation phase. Evidence Review is locked until then.</p>
    </section>`;
  }
  const active = sessions.some((session) => session.status === "active" || session.status === "paused");
  const hasCompleted = sessions.some((session) => session.status === "completed");
  const disabled = active || !hasCompleted;
  const reason = active
    ? "End the active investigation session before recording completion. Ending the session does not complete the investigation by itself."
    : !hasCompleted
      ? "At least one completed investigation session is required before completion can be recorded."
      : "Ending a session does not complete the investigation. Record explicit completion when the investigation work is finished; Evidence Review remains locked until then.";
  return `<section class="cc-native-card" data-investigation-completion="pending" aria-labelledby="investigation-completion-title">
    <h3 class="cc-section-title" id="investigation-completion-title">Investigation Completion</h3>
    <p class="cc-meta">${esc(reason)}</p>
    <div class="form-actions"><button class="button-primary" id="complete-investigation" type="button" ${disabled ? "disabled" : ""}>Complete Investigation</button></div>
  </section>`;
}

function measurementListHtml(rows: Array<{ id: string; type: string; value: string; text: string; acquisition: string; instrument: string; at: number; amended: boolean }>): string {
  if (rows.length === 0) return '<div class="cc-empty">No measurements recorded.</div>';
  return rows
    .map(
      (m) => `
    <div class="case-row" data-measurement-row="${m.id}">
      <div>
        <div class="case-title">${esc(m.type)}: ${esc(m.value || m.text)}${m.amended ? " • superseded" : ""}</div>
        <div class="case-meta">${fmtTime(m.at)} • acquisition: <strong>${esc(m.acquisition)}</strong>${m.instrument ? ` • instrument: ${esc(m.instrument)}` : ""}</div>
      </div>
      ${m.amended ? "" : `<button class="back-button" data-amend-measurement="${m.id}" type="button">Amend…</button>`}
    </div>`,
    )
    .join("");
}

function measurementFormHtml(rooms: Array<{ id: string; name: string }>, focusMeasurement?: MeasurementType, focusRoomId?: string | null): string {
  const types = Object.keys(MEASUREMENT_TYPE_LABELS) as MeasurementType[];
  return `
    <h3 class="cc-section-title">Record a Measurement</h3>
    <div class="case-form" id="measurement-form">
      <div class="detail-grid">
        <div class="detail-field"><label for="m-type">Measurement type</label>
          <select id="m-type">
            ${types.map((t) => `<option value="${t}"${t === focusMeasurement ? " selected" : ""}>${esc(MEASUREMENT_TYPE_LABELS[t])}</option>`).join("")}
          </select></div>
        <div class="detail-field"><label for="m-acquisition">Acquisition method</label>
          <select id="m-acquisition">
            <option value="manualInstrument">Manual instrument entry (read from an external meter)</option>
            <option value="observation">Observation (qualitative, no number)</option>
            <option value="imported">Imported (from a separately identified source)</option>
          </select></div>
        <div class="detail-field"><label for="m-room">Room / area</label>
          <select id="m-room">
            <option value="">— no room (property level) —</option>
            ${rooms.map((r) => `<option value="${r.id}"${r.id === focusRoomId ? " selected" : ""}>${esc(r.name)}</option>`).join("")}
          </select></div>
        <div class="detail-field"><label for="m-instrument">Instrument / source</label>
          <input id="m-instrument" type="text" placeholder="e.g. K-II meter, handheld thermometer, imported weather file">
          <div class="case-meta" id="m-instrument-hint">Required for manual instrument and imported readings.</div></div>
        <div class="detail-field"><label for="m-calibration">Calibration</label>
          <select id="m-calibration">
            <option value="unknown">Unknown</option>
            <option value="factory">Factory calibrated</option>
            <option value="userCalibrated">User calibrated</option>
            <option value="notApplicable">Not applicable</option>
          </select>
          <div class="case-meta">Never claim calibration you cannot evidence — "Unknown" is recorded honestly.</div></div>
        <div class="detail-field"><label for="m-value">Value</label>
          <input id="m-value" type="number" step="any" inputmode="decimal"></div>
        <div class="detail-field"><label for="m-unit">Unit</label>
          <select id="m-unit"><option value="">— canonical —</option></select></div>
      </div>
      <div class="detail-field"><label for="m-text">Observation / notes text</label>
        <textarea id="m-text" rows="2" placeholder="Required for observations; optional context otherwise"></textarea></div>
      <div class="detail-field" id="m-emf-extras" hidden>
        <label for="m-led">K-II LED level (LED state — not a numeric reading)</label>
        <select id="m-led"><option value="">— not using LED level —</option>${K2_LED_LEVELS.map((l) => `<option value="${esc(l)}">${esc(l)}</option>`).join("")}</select>
        <div class="case-meta">Meter types available for identification: ${EMF_METER_TYPES.join(", ")}.</div>
      </div>
      <div class="form-actions"><button class="button-primary" id="save-measurement" type="button">Save Measurement</button></div>
      <p class="cc-meta">The browser has no magnetometer or temperature sensor. EMF and temperature are recorded only from an external instrument you identify — never simulated.</p>
    </div>`;
}

function sensorRowHtml(cap: SensorCapability): string {
  const badge = cap.state === "active" ? "implemented" : cap.state === "unsupported" || cap.state === "permissionDenied" || cap.state === "deviceUnavailable" ? "error" : "";
  return `
    <div class="case-row" data-sensor="${cap.id}">
      <div>
        <div class="case-title">${esc(cap.label)}</div>
        <div class="case-meta">${esc(cap.detail)}</div>
      </div>
      <span class="status-badge ${badge}">${esc(cap.state)}</span>
    </div>`;
}

function connectivityHtml(status: ConnectivityStatus): string {
  const badge = status.browserReported === "online" ? "" : "error";
  return `
    <div class="case-row">
      <div>
        <div class="case-title">Browser-reported: <strong>${esc(status.browserReported)}</strong></div>
        <div class="case-meta">Verified reachability: <strong>${esc(status.reachability)}</strong>${status.verifiedAt ? ` • verified ${fmtTime(status.verifiedAt)}` : ""}${status.detail ? ` • ${esc(status.detail)}` : ""}</div>
      </div>
      <span class="status-badge ${badge}">${esc(status.browserReported)}</span>
    </div>`;
}

function audioMeterWidth(level: number | null): number {
  if (level === null) return 0;
  // dBFS −80…0 mapped to 0…100%
  return Math.max(0, Math.min(100, ((level + 80) / 80) * 100));
}

function audioHistoryHtml(samples: AudioLevelSample[]): string {
  return samples
    .slice(-40)
    .map((s) => `<div style="flex:1;background:linear-gradient(180deg,var(--cyan),var(--cyan-dim));height:${Math.max(2, audioMeterWidth(s.dbfs) * 0.4)}%" title="${s.dbfs.toFixed(1)} dBFS"></div>`)
    .join("");
}

function updateAudioUi(container: HTMLElement, state: AudioMonitorState, level: number | null, samples: AudioLevelSample[]): void {
  const levelEl = container.querySelector<HTMLElement>("#audio-level");
  if (levelEl) levelEl.textContent = level === null ? "—" : `${level.toFixed(1)} dBFS`;
  const stateEl = container.querySelector<HTMLElement>("#audio-state");
  if (stateEl) stateEl.textContent = state;
  const fill = container.querySelector<HTMLElement>("#audio-meter-fill");
  if (fill) fill.style.width = `${audioMeterWidth(level)}%`;
  const hist = container.querySelector<HTMLElement>("#audio-history");
  if (hist) hist.innerHTML = audioHistoryHtml(samples);
  const panel = container.querySelector<HTMLElement>("#audio-monitor");
  if (panel) panel.dataset.audioState = state;
}

function wireHandlers(container: HTMLElement, caseId: string, options: SessionViewOptions): void {
  const reload = () => renderSessionView(container, caseId, options);
  const sessionId = () => container.querySelector<HTMLElement>("[data-root='session-view']")?.dataset.sessionId ?? "";

  onDelegate(container, "click", "#session-back", () => {
    if (options.backToEquipment) location.hash = `/equipment?from=session-${Date.now()}`;
    else void renderCaseHub(container, caseId);
  });

  onDelegate(container, "click", "#create-session", async () => {
    clearDrafts(container);
    const investigator = container.querySelector<HTMLInputElement>("#session-investigator")?.value ?? "";
    const device = container.querySelector<HTMLInputElement>("#session-device")?.value ?? "";
    const created = await sessions().createSession(caseId, {
      investigators: investigator.trim() ? [investigator.trim()] : [],
      deviceLabel: device,
    });
    st(container).sessionId = created.id;
    await reload();
  });
  onDelegate(container, "click", "#start-session", async () => {
    await sessions().startSession(sessionId());
    await reload();
  });
  onDelegate(container, "click", "#pause-session", async () => {
    const reason = window.prompt("Pause reason (optional — e.g. restroom, equipment swap):", "") ?? "";
    await sessions().pauseSession(sessionId(), reason);
    await reload();
  });
  onDelegate(container, "click", "#resume-session", async () => {
    await sessions().resumeSession(sessionId());
    await reload();
  });
  onDelegate(container, "click", "#end-session", async () => {
    await sessions().endSession(sessionId(), "completed");
    await reload();
  });
  onDelegate(container, "click", "#complete-investigation", async () => {
    if (!window.confirm("Record explicit investigation completion? This unlocks Evidence Review for this case. Existing evidence and review records are preserved.")) return;
    try {
      await new InvestigationCompletionService(db()).complete(caseId);
      await reload();
    } catch (err) {
      toast((err as Error).message, true);
    }
  });
  onDelegate(container, "click", "#abort-session", async () => {
    const reason = window.prompt("Document why this session is being aborted:", "");
    if (!reason?.trim()) return;
    const sid = sessionId();
    await sessions().recordEvent(sid, "sessionEnded", `Session aborted: ${reason.slice(0, 160)}`);
    await sessions().endSession(sid, "aborted");
    await reload();
  });
  onDelegate(container, "click", "#review-session", async () => {
    await sessions().reviewSession(sessionId());
    await reload();
  });
  onDelegate(container, "click", "[data-open-session]", (el) => {
    st(container).sessionId = el.dataset.openSession ?? null;
    void reload();
  });
  onDelegate(container, "click", "[data-reopen-session]", async (el) => {
    const reason = window.prompt("Document why this completed session is being reopened:", "");
    if (!reason?.trim()) return;
    const reopened = await sessions().reopenSession(el.dataset.reopenSession ?? "", reason);
    st(container).sessionId = reopened.id;
    await reload();
  });

  // Per-room investigation summary -----------------------------------------
  onDelegate(container, "change", "#room-summary-room", (el) => {
    st(container).summaryRoomId = (el as HTMLSelectElement).value || null;
    void reload();
  });
  onDelegate(container, "click", "[data-open-room-summary]", (el) => {
    st(container).summaryRoomId = el.dataset.openRoomSummary ?? null;
    void reload();
  });
  onDelegate(container, "click", "#room-summary-save", async (button) => {
    const sid = sessionId();
    const roomId = container.querySelector<HTMLSelectElement>("#room-summary-room")?.value ?? "";
    const body = container.querySelector<HTMLTextAreaElement>("#room-summary-body")?.value ?? "";
    const author = container.querySelector<HTMLInputElement>("#room-summary-author")?.value ?? "";
    if (!sid || !roomId) return;
    const btn = button as HTMLButtonElement;
    btn.disabled = true;
    try {
      await new RoomSummaryRepository(db()).save({ caseId, sessionId: sid, roomId, body, author });
      // The stored text is authoritative after a save; selected-room drafts are
      // scoped per room, but clear them so the panel re-renders from the record.
      clearDrafts(container);
      await reload();
      toast("Room summary saved.");
    } catch (err) {
      btn.disabled = false;
      toast((err as Error).message, true);
    }
  });

  // Measurement entry ------------------------------------------------------
  const updateUnitOptions = () => {
    const type = (container.querySelector<HTMLSelectElement>("#m-type")?.value ?? "temperature") as MeasurementType;
    const unitSelect = container.querySelector<HTMLSelectElement>("#m-unit");
    const emfExtras = container.querySelector<HTMLElement>("#m-emf-extras");
    if (unitSelect) {
      const options = Object.keys(UNIT_CONVERSIONS[type] ?? {});
      const canonical = CANONICAL_UNITS[type];
      unitSelect.innerHTML =
        `<option value="">— canonical: ${esc(canonical || "n/a")} —</option>` +
        options.map((u) => `<option value="${esc(u)}">${esc(u)}</option>`).join("");
    }
    if (emfExtras) emfExtras.hidden = type !== "emf";
    const hint = container.querySelector<HTMLElement>("#m-instrument-hint");
    if (hint) {
      hint.textContent =
        type === "ambientSound"
          ? "Use the audio level monitor above for dBFS, or identify a sound-level meter you read manually."
          : "Required for manual instrument and imported readings.";
    }
  };
  updateUnitOptions();
  onDelegate(container, "change", "#m-type", updateUnitOptions);
  onDelegate(container, "change", "#m-acquisition", () => {
    const acq = container.querySelector<HTMLSelectElement>("#m-acquisition")?.value;
    const valueField = container.querySelector<HTMLInputElement>("#m-value");
    const ledgerExtra = container.querySelector<HTMLSelectElement>("#m-led");
    if (valueField) valueField.disabled = acq === "observation";
    if (ledgerExtra) ledgerExtra.disabled = acq === "observation";
  });

  onDelegate(container, "click", "#save-measurement", async () => {
    const readVal = (sel: string) => container.querySelector<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>(sel)?.value.trim() ?? "";
    const type = readVal("#m-type") as MeasurementType;
    const acquisition = readVal("#m-acquisition") as "manualInstrument" | "observation" | "imported";
    const ledLevel = readVal("#m-led");
    const rawValue = readVal("#m-value");
    const textParts = [readVal("#m-text")];
    if (ledLevel) textParts.push(`K-II LED level: ${ledLevel}`);
    try {
      clearDrafts(container); // measurement form resets after a successful save
      await measurements().record(caseId, {
        measurementType: type,
        acquisition,
        value: rawValue ? Number(rawValue) : null,
        unit: readVal("#m-unit") || undefined,
        text: textParts.filter(Boolean).join(" • "),
        instrument: readVal("#m-instrument"),
        calibration: (readVal("#m-calibration") || "unknown") as never,
        roomId: readVal("#m-room") || null,
        sessionId: st(container).sessionId,
      });
      await reload();
    } catch (err) {
      alert((err as Error).message);
    }
  });

  onDelegate(container, "click", "[data-amend-measurement]", async (el) => {
    const id = el.dataset.amendMeasurement ?? "";
    const value = window.prompt("Corrected value (leave blank to keep the existing value):", "");
    if (value === null) return;
    const reason = window.prompt("Document the reason for this amendment:", "");
    if (!reason?.trim()) return;
    try {
      await measurements().amend(id, {
        value: value.trim() ? Number(value) : undefined,
        reason,
      });
      await reload();
    } catch (err) {
      alert((err as Error).message);
    }
  });

  // Audio monitoring -------------------------------------------------------
  onDelegate(container, "click", "#audio-start", async () => {
    const monitor = getAudioLevelMonitor();
    const state = await monitor.start();
    if (state !== "active") {
      const detail = state === "denied"
        ? "Microphone permission was denied. Level monitoring is unavailable — no measurement can be recorded."
        : `Monitoring could not start (${state}). ${monitor.getLastError()}`;
      alert(detail);
    }
    updateAudioUi(container, monitor.getState(), monitor.getCurrentLevel(), monitor.getSamples());
  });
  onDelegate(container, "click", "#audio-stop", async () => {
    const monitor = getAudioLevelMonitor();
    await monitor.stop();
    updateAudioUi(container, monitor.getState(), monitor.getCurrentLevel(), monitor.getSamples());
  });
  onDelegate(container, "click", "#audio-clear", () => {
    const monitor = getAudioLevelMonitor();
    monitor.clearWindow();
    updateAudioUi(container, monitor.getState(), monitor.getCurrentLevel(), monitor.getSamples());
  });
  onDelegate(container, "click", "#audio-record", async () => {
    const monitor = getAudioLevelMonitor();
    const summary = monitor.summarizeWindow();
    if (!summary) {
      alert("No audio samples have been collected yet — start monitoring first.");
      return;
    }
    try {
      clearDrafts(container);
      await measurements().record(caseId, {
        measurementType: "ambientSound",
        acquisition: "automatic",
        value: summary.meanDbfs,
        text: `Sampled window: ${summary.count} samples at ${summary.intervalMs} ms intervals (peak ${summary.peakDbfs} dBFS, floor ${summary.floorDbfs} dBFS). Mean level recorded.`,
        instrument: "Browser microphone — digital signal level (dBFS, uncalibrated)",
        calibration: "unknown",
        roomId: container.querySelector<HTMLSelectElement>("#m-room")?.value || null,
        sessionId: st(container).sessionId,
        sampleWindowId: `audio-${summary.startedAt}`,
      });
      await reload();
    } catch (err) {
      alert((err as Error).message);
    }
  });

  // Connectivity -----------------------------------------------------------
  onDelegate(container, "click", "#verify-connectivity", async () => {
    await getConnectivity().verify();
  });
}
