/**
 * Minimal UUIDv4 generator using the Web Crypto API.
 * Avoids an external dependency for the WP-0 foundation.
 */

export function v4(): string {
  if (typeof crypto !== "undefined" && typeof crypto.randomUUID === "function") {
    return crypto.randomUUID();
  }
  // Fallback for environments without randomUUID (still CSPRNG-backed).
  const bytes = new Uint8Array(16);
  crypto.getRandomValues(bytes);
  const b6 = bytes[6];
  const b8 = bytes[8];
  if (b6 !== undefined) bytes[6] = (b6 & 0x0f) | 0x40; // version 4
  if (b8 !== undefined) bytes[8] = (b8 & 0x3f) | 0x80; // variant 10
  const hex: string[] = [];
  for (const b of bytes) hex.push(b.toString(16).padStart(2, "0"));
  const s = hex.join("");
  return `${s.slice(0, 8)}-${s.slice(8, 12)}-${s.slice(12, 16)}-${s.slice(16, 20)}-${s.slice(20)}`;
}
