/**
 * Document packet generation (TPI-V2-WEB-006 §11) — local, offline PDF
 * generation with pdf-lib (MIT, bundled — no network services).
 *
 * Draft vs finalized is clearly labeled. Generated bytes are NOT certified
 * digital signatures; the integrity hash of the packet is recorded for
 * change detection only (see docs/SIGNATURE_AND_CONSENT.md).
 */
import { PDFDocument, StandardFonts, rgb } from "pdf-lib";
import type { CaseRecord, DocumentInstanceRecord, DocumentVersionRecord, SignatureRecord } from "../types";
import { templateFor } from "./templates";
import { renderContextForCase } from "./renderer";

const FIXED_EPOCH = new Date(Date.UTC(2000, 0, 1, 0, 0, 0));

function wrap(text: string, size: number, maxWidth: number): string[] {
  const lines: string[] = [];
  for (const raw of text.split("\n")) {
    if (raw.trim() === "") {
      lines.push("");
      continue;
    }
    let current = "";
    for (const word of raw.split(/\s+/)) {
      const candidate = current.length === 0 ? word : `${current} ${word}`;
      if (fontWidth(candidate, size) > maxWidth && current.length > 0) {
        lines.push(current);
        current = word;
      } else {
        current = candidate;
      }
    }
    lines.push(current);
  }
  return lines;
}

// pdf-lib widthOfTextAtSize needs a font; approximate with a fixed estimate to
// keep this helper pure, then rely on generous margins.
function fontWidth(text: string, size: number): number {
  return text.length * size * 0.5;
}

export interface PacketInput {
  caseRecord: CaseRecord;
  instance: DocumentInstanceRecord;
  version: DocumentVersionRecord | null;
  signatures: SignatureRecord[];
}

/** Generate one document's PDF (single page or more as needed). */
export async function generateDocumentPdf(input: PacketInput): Promise<Uint8Array> {
  const { caseRecord, instance, version, signatures } = input;
  const template = templateFor(instance.templateId);
  const pdf = await PDFDocument.create();
  pdf.setTitle(`${template.title} — ${caseRecord.caseNumber}`);
  pdf.setProducer("TPI Research & Investigation Studio");
  pdf.setCreator("TPI Research & Investigation Studio (local, offline)");
  // Deterministic metadata: fixed epoch rather than wall-clock generation time.
  pdf.setCreationDate(FIXED_EPOCH);
  pdf.setModificationDate(FIXED_EPOCH);

  const font = await pdf.embedFont(StandardFonts.Courier);
  const bold = await pdf.embedFont(StandardFonts.CourierBold);
  const margin = 48;
  const pageWidth = 612;
  const pageHeight = 792;
  const maxWidth = pageWidth - margin * 2;

  const content = version?.content ?? renderBodyPlaceholder(instance);
  const isFinal = instance.status === "finalized" && version !== null;

  let page = pdf.addPage([pageWidth, pageHeight]);
  let y = pageHeight - margin;
  const newPage = () => {
    page = pdf.addPage([pageWidth, margin]);
    y = pageHeight - margin;
  };
  const draw = (text: string, opts: { size?: number; bold?: boolean } = {}) => {
    const size = opts.size ?? 10;
    for (const line of wrap(text, size, maxWidth)) {
      if (y < margin + size * 2) newPage();
      page.drawText(line, {
        x: margin,
        y,
        size,
        font: opts.bold ? bold : font,
        color: rgb(0.1, 0.1, 0.1),
      });
      y -= size * 1.4;
    }
  };

  draw(`THE PARANORMAL INITIATIVE — RESEARCH & INVESTIGATION STUDIO`, { size: 11, bold: true });
  draw(`DOCUMENT PACKET — ${isFinal ? "FINALIZED" : "DRAFT"} (not a certified digital signature)`, { size: 10, bold: true });
  draw(
    `Case: ${caseRecord.caseNumber}  •  Template: ${template.title}  •  Template version: ${instance.templateVersion}`,
  );
  draw(
    `Document ID: ${instance.id}  •  Version: ${version ? `v${version.versionNumber} (${version.id})` : "working draft"}`,
  );
  draw(
    `Content hash (SHA-256): ${instance.contentHash ?? "(unsaved draft)"}`,
    { size: 8 },
  );
  draw("");
  for (const [key, value] of Object.entries(instance.fieldValues)) {
    if (value.trim().length > 0) draw(`Field ${key}: ${value}`);
  }
  draw("");
  draw("=".repeat(72), { bold: true });
  draw("");

  for (const line of content.split("\n")) {
    draw(line);
  }

  draw("");
  draw("=".repeat(72), { bold: true });
  draw("SIGNATURES", { bold: true });
  const active = signatures.filter((s) => s.active);
  if (active.length === 0) {
    draw("No signatures captured.", { size: 9 });
  }
  for (const sig of active) {
    draw(
      `${sig.signerRole === "client" ? "Client" : "Investigator"}: ${sig.signerName}  (${sig.method} signature)`,
      { bold: true },
    );
    draw(`Signed at: ${new Date(sig.signedAt).toISOString()}`, { size: 9 });
    draw(`Intent acknowledgment recorded: ${sig.intentAcknowledged ? "yes" : "no"}`, { size: 9 });
    draw(`Bound content hash: ${sig.contentHash}`, { size: 8 });
    if (sig.imageDataUrl) {
      try {
        const png = await pdf.embedPng(sig.imageDataUrl);
        if (y < margin + 90) newPage();
        page.drawImage(png, { x: margin, y: y - 70, width: 180, height: 60 });
        y -= 80;
      } catch {
        draw("(Signature image could not be embedded.)", { size: 9 });
      }
    }
    draw("");
  }
  if (active.length < 2) {
    draw("Required signatures outstanding: client and lead investigator.", { size: 9 });
  }
  draw("");
  draw(
    "This document was generated locally by the TPI Research & Investigation Studio. " +
      "Locally captured signatures are not independently verified and this PDF is not " +
      "digitally certified.",
    { size: 8 },
  );

  return pdf.save();
}

function renderBodyPlaceholder(instance: DocumentInstanceRecord): string {
  const template = templateFor(instance.templateId);
  return `(Working draft — complete the fields in the Documents Center.)\n${template.body.replace(/\[STANDARD_SIGNATURE_BLOCK\]/g, "").trim()}`;
}

/** Generate a full case packet PDF (all provided documents, one per section). */
export async function generateCasePacket(
  caseRecord: CaseRecord,
  items: Array<{ instance: DocumentInstanceRecord; version: DocumentVersionRecord | null; signatures: SignatureRecord[] }>,
): Promise<Uint8Array> {
  if (items.length === 0) throw new Error("No documents to include in the packet.");
  const merged = await PDFDocument.create();
  merged.setProducer("TPI Research & Investigation Studio");
  merged.setCreationDate(FIXED_EPOCH);
  merged.setModificationDate(FIXED_EPOCH);
  merged.setTitle(`Document packet — ${caseRecord.caseNumber}`);
  for (const item of items) {
    const bytes = await generateDocumentPdf({ caseRecord, ...item });
    const doc = await PDFDocument.load(bytes);
    const pages = await merged.copyPages(doc, doc.getPageIndices());
    pages.forEach((p) => merged.addPage(p));
  }
  return merged.save();
}

export function renderContextFromCase(caseRecord: CaseRecord) {
  return renderContextForCase(caseRecord);
}
