/**
 * Claim creation, editing and room assignment (TPI-V2-WEB-C6C).
 *
 * ORIGINAL SOURCES:
 *   Cases/HauntedClaimAssignmentView.swift — title, notes and multi-room
 *   selection; Add Claim / Save; Cancel.
 *   Cases/HauntedClaimsListView.swift — case list, REF badge, room labels,
 *   empty state, createdAt-ascending order.
 *   Cases/HauntedLocationStructureBuilderView.swift — Claim Assignment entry
 *   point inside the location structure workspace.
 *
 * A claim is reported information, never evidence or an observation. This
 * manager writes only through ClaimRepository. It does not create evidence,
 * observations, reviews, checklist/readiness state, phase changes or
 * investigation-completion events. Delete is intentionally absent; reference
 * import lives in the separate C6D selector and always uses this same safe path.
 */
import { getDb } from "../../core/db";
import {
  ClaimRepository,
  CLAIM_CLASSIFICATIONS,
  CLAIM_WALKTHROUGH_STATUSES,
  type ClaimCreateInput,
  type ClaimUpdateInput,
} from "../../core/repositories/claimsRepository";
import type {
  ClaimClassification,
  ClaimRecord,
  ClaimWalkthroughStatus,
  RoomRecord,
} from "../../core/types";
import { esc } from "../dashboard/shell";
import { referenceClaimImportHtml } from "./ReferenceClaimImport";
import { clearDrafts, onDelegate } from "../../shared/uidom";

export interface ClaimsManagerData {
  caseId: string;
  claims: ClaimRecord[];
  /** All case rooms, including archived rooms whose historical links must survive. */
  rooms: RoomRecord[];
  floors: ReadonlyArray<{ id: string; displayName: string }>;
  zones: ReadonlyArray<{ id: string; displayName: string }>;
  /** Reference import preserves the original Haunted Location-only rule. */
  referenceImportEligible: boolean;
}

interface ClaimsManagerState {
  creating: boolean;
  editingId: string | null;
  notice: string;
}

const managerState = new WeakMap<HTMLElement, ClaimsManagerState>();

function stateFor(container: HTMLElement): ClaimsManagerState {
  let state = managerState.get(container);
  if (!state) {
    state = { creating: false, editingId: null, notice: "" };
    managerState.set(container, state);
  }
  return state;
}

const CLAIM_TYPES = [
  "Apparition / Visual",
  "Auditory / Voice / Sound",
  "Physical Touch / Contact",
  "Object Movement",
  "Shadow/Peripheral Movement",
  "Light Anomaly",
  "Electrical Interference",
  "Door/Window Movement",
  "Dream Experience",
  "Sleep Disturbance",
  "Environmental Sensation",
  "Other",
] as const;

const OCCURRENCE_LEVELS = [
  "Floor Level",
  "Lower Wall",
  "Mid-Level",
  "Upper Wall",
  "Ceiling Level",
  "Unknown",
] as const;

const IMPORT_SOURCE_LABELS: Record<string, string> = {
  referenceLocation: "Reference location",
  manual: "Manual source",
  external: "External source",
};

function isImported(claim: ClaimRecord): boolean {
  return (
    claim.importedFromReference ||
    claim.importSourceType !== null ||
    claim.importIdentity !== null ||
    claim.importedAt !== null
  );
}

function timeOrMissing(value: number | null | undefined): string {
  return value !== null && value !== undefined && Number.isFinite(value)
    ? esc(new Date(value).toLocaleString())
    : "Not recorded";
}

function textOrMissing(value: string | null | undefined, fallback = "Not recorded"): string {
  return value && value.trim().length > 0 ? esc(value) : `<span class="claims-missing">${esc(fallback)}</span>`;
}

function checked(value: boolean): string {
  return value ? " checked" : "";
}

function selected(value: string, current: string): string {
  return value === current ? " selected" : "";
}

function optionList(
  options: readonly string[],
  current: string,
  emptyLabel?: string,
): string {
  const values = [...options];
  if (current && !values.includes(current)) values.push(current);
  return (
    (emptyLabel !== undefined
      ? `<option value=""${selected("", current)}>${esc(emptyLabel)}</option>`
      : "") +
    values
      .map((value) => `<option value="${esc(value)}"${selected(value, current)}>${esc(value)}</option>`)
      .join("")
  );
}

function inputField(
  label: string,
  field: string,
  value: string,
  options: {
    type?: string;
    placeholder?: string;
    required?: boolean;
    min?: number;
    step?: number;
    help?: string;
  } = {},
): string {
  const id = `claim-field-${field}`;
  return `<div class="detail-field">
    <label for="${id}">${esc(label)}${options.required ? " *" : ""}</label>
    <input id="${id}" data-claim-field="${field}" type="${esc(options.type ?? "text")}"
      value="${esc(value)}" placeholder="${esc(options.placeholder ?? "")}"
      ${options.required ? "required" : ""}
      ${options.min !== undefined ? `min="${options.min}"` : ""}
      ${options.step !== undefined ? `step="${options.step}"` : ""}>
    ${options.help ? `<p class="cc-meta">${esc(options.help)}</p>` : ""}
  </div>`;
}

function textareaField(
  label: string,
  field: string,
  value: string,
  options: { rows?: number; placeholder?: string; help?: string } = {},
): string {
  const id = `claim-field-${field}`;
  return `<div class="detail-field">
    <label for="${id}">${esc(label)}</label>
    <textarea id="${id}" data-claim-field="${field}" rows="${options.rows ?? 3}"
      placeholder="${esc(options.placeholder ?? "")}">${esc(value)}</textarea>
    ${options.help ? `<p class="cc-meta">${esc(options.help)}</p>` : ""}
  </div>`;
}

function selectField(
  label: string,
  field: string,
  options: readonly string[],
  current: string,
  emptyLabel?: string,
  help?: string,
): string {
  const id = `claim-field-${field}`;
  return `<div class="detail-field">
    <label for="${id}">${esc(label)}</label>
    <select id="${id}" data-claim-field="${field}">${optionList(options, current, emptyLabel)}</select>
    ${help ? `<p class="cc-meta">${esc(help)}</p>` : ""}
  </div>`;
}

function checkboxField(
  label: string,
  field: string,
  isChecked: boolean,
  help?: string,
): string {
  const id = `claim-field-${field}`;
  return `<div class="detail-field claim-checkbox-field">
    <label class="claim-checkbox-label" for="${id}">
      <input id="${id}" data-claim-field="${field}" type="checkbox"${checked(isChecked)}>
      <span>${esc(label)}</span>
    </label>
    ${help ? `<p class="cc-meta">${esc(help)}</p>` : ""}
  </div>`;
}

function roomLabel(room: RoomRecord): string {
  return room.archived ? `${room.name} (archived)` : room.name;
}

function roomContext(
  room: RoomRecord,
  data: ClaimsManagerData,
): string {
  const floor = data.floors.find((candidate) => candidate.id === room.floorId);
  const zone = data.zones.find((candidate) => candidate.id === room.zoneId);
  const parent = floor ? `Floor: ${floor.displayName}` : zone ? `Zone: ${zone.displayName}` : "Unassigned area";
  return `${parent} — ${roomLabel(room)}`;
}

function claimRoomIds(claim: ClaimRecord): string[] {
  return [...new Set([claim.roomID, ...claim.linkedRoomIds].filter((id): id is string => Boolean(id)))];
}

function roomText(claim: ClaimRecord, roomById: ReadonlyMap<string, RoomRecord>): string {
  const ids = claimRoomIds(claim);
  if (ids.length === 0) {
    return claim.roomTBD ? "Room assignment TBD" : "No rooms assigned";
  }
  return ids
    .map((id) => roomById.get(id)?.name ?? `Unresolved room (${id})`)
    .join(", ");
}

function provenanceHtml(claim: ClaimRecord | null): string {
  if (!claim || !isImported(claim)) {
    return `<div class="claim-local-note">
      <h5>Locally recorded</h5>
      <p class="cc-meta">No immutable imported source statement is attached. This claim is still reported information, not evidence or an observation.</p>
    </div>`;
  }
  const sourceType = claim.importSourceType
    ? IMPORT_SOURCE_LABELS[claim.importSourceType] ?? claim.importSourceType
    : "Not recorded";
  return `<div class="claim-import-lock" data-claim-import-lock>
    <h5>Imported source — read-only</h5>
    <dl class="claims-facts">
      <div class="claims-fact"><dt>Source type</dt><dd>${esc(sourceType)}</dd></div>
      <div class="claims-fact"><dt>Source reference</dt><dd>${textOrMissing(claim.importSourceRef)}</dd></div>
      <div class="claims-fact"><dt>Source claim id</dt><dd>${textOrMissing(claim.importSourceClaimId)}</dd></div>
      <div class="claims-fact"><dt>Imported</dt><dd>${timeOrMissing(claim.importedAt)}</dd></div>
    </dl>
    <div class="claims-text-block">
      <h5>Original imported statement</h5>
      ${claim.sourceText && claim.sourceText.trim().length > 0
        ? `<p class="claims-original-text">${esc(claim.sourceText)}</p>`
        : `<p class="cc-meta">No separate source statement recorded.</p>`}
    </div>
    <div class="claims-text-block">
      <h5>Source occurrence text</h5>
      ${claim.sourceOccurrenceText && claim.sourceOccurrenceText.trim().length > 0
        ? `<p class="claims-original-text">${esc(claim.sourceOccurrenceText)}</p>`
        : `<p class="cc-meta">No source occurrence text recorded.</p>`}
    </div>
    <p class="cc-meta"><strong>Immutable:</strong> saving this form cannot rewrite the original statement, source identifiers, import identity or import timestamps. Only the editable claim fields below are written.</p>
  </div>`;
}

function roomFields(
  claim: ClaimRecord | null,
  data: ClaimsManagerData,
): string {
  const roomById = new Map(data.rooms.map((room) => [room.id, room]));
  const selectedIds = new Set(claim ? claimRoomIds(claim) : []);
  const active = data.rooms.filter((room) => !room.archived);
  const archived = data.rooms.filter((room) => room.archived);
  const unresolved = [...selectedIds].filter((id) => !roomById.has(id));
  const primary = claim?.roomID ?? "";
  const primaryOptions = data.rooms
    .map((room) => `<option value="${esc(room.id)}"${selected(room.id, primary)}>${esc(roomContext(room, data))}</option>`)
    .join("");
  const unresolvedPrimary = primary && !roomById.has(primary)
    ? `<option value="${esc(primary)}" selected>Unresolved primary room (${esc(primary)})</option>`
    : "";

  const group = (label: string, rooms: RoomRecord[]): string => {
    if (rooms.length === 0) return "";
    return `<fieldset class="claim-room-group"><legend>${esc(label)}</legend>
      ${rooms
        .map(
          (room) => `<label class="claim-room-option">
            <input type="checkbox" data-claim-room value="${esc(room.id)}"${selectedIds.has(room.id) ? " checked" : ""}>
            <span>${esc(roomLabel(room))}</span>
          </label>`,
        )
        .join("")}
    </fieldset>`;
  };

  return `<div class="claim-form-group">
    <h5>Room assignment</h5>
    <p class="cc-meta">Select any rooms where the reported experience occurred. A primary room is optional. Room ids are validated against this case by ClaimRepository; no room is created here.</p>
    <div class="detail-field">
      <label for="claim-primary-room">Primary room (optional)</label>
      <select id="claim-primary-room" data-claim-primary>
        <option value=""${selected("", primary)}>No primary room recorded</option>
        ${primaryOptions}${unresolvedPrimary}
      </select>
    </div>
    ${active.length === 0 && archived.length === 0
      ? `<p class="cc-meta">No rooms exist in this structure. The claim can still be saved unassigned.</p>`
      : `<div class="claim-room-groups">
          ${data.floors.map((floor) => group(`Floor: ${floor.displayName}`, active.filter((room) => room.floorId === floor.id))).join("")}
          ${data.zones.map((zone) => group(`Zone: ${zone.displayName}`, active.filter((room) => room.zoneId === zone.id))).join("")}
          ${group("Unassigned areas", active.filter((room) => !room.floorId && !room.zoneId))}
          ${group("Archived rooms", archived)}
        </div>`}
    ${unresolved.length > 0
      ? `<div class="claim-unresolved-rooms">
          <p class="cc-meta"><strong>Unresolved historical room references are preserved:</strong> ${unresolved.map((id) => esc(id)).join(", ")}. They remain attached when other fields are edited, and a new primary room can be chosen without deleting them; a missing room is never silently substituted.</p>
          ${unresolved.map((id) => `<input type="hidden" data-preserved-room value="${esc(id)}">`).join("")}
        </div>`
      : ""}
  </div>`;
}

function formHtml(claim: ClaimRecord | null, data: ClaimsManagerData): string {
  const title = claim?.title ?? "";
  const claimType = claim?.claimType ?? "Other";
  const claimTypeOther = claim?.claimTypeOtherText ?? "";
  const classification = claim?.classification ?? "Client Reported";
  const walkthroughStatus = claim?.walkthroughStatus ?? "Not Located";
  const occurrenceLevel = claim?.occurrenceLevel ?? "";
  const mostRecentKnown =
    claim?.mostRecentOccurrenceKnown === true
      ? "yes"
      : claim?.mostRecentOccurrenceKnown === false
        ? "no"
        : "";

  return `<form id="claim-form" class="claim-form" data-claim-form="${claim?.id ?? ""}" data-claim-id="${claim?.id ?? ""}" novalidate>
    <div class="claim-form-heading">
      <div>
        <span class="claims-eyebrow">${claim ? "Edit claim" : "New claim"}</span>
        <h4>${claim ? "Edit Claim" : "Assign New Claim"}</h4>
      </div>
      <span class="claims-badge">${claim ? "Reported record" : "Reported information only"}</span>
    </div>
    <p class="claims-safeguard">Save records a claim as reported information. It never creates evidence or an observation, confirms paranormal activity, changes evidence classification, satisfies readiness, advances a phase or completes an investigation.</p>
    <p class="claim-form-error" data-claim-form-error role="alert" hidden></p>

    ${provenanceHtml(claim)}

    <div class="claim-form-group">
      <h5>Claim details</h5>
      <div class="detail-grid">
        ${inputField("Claim title", "title", title, { required: true, placeholder: "What is being experienced?" })}
        ${selectField("Claim type", "claimType", CLAIM_TYPES, claimType, undefined, "Original PPClaim type list; Other uses the free-text value below.")}
        ${inputField("Other claim type", "claimTypeOtherText", claimTypeOther, { placeholder: "Describe the type when Other is selected" })}
        ${inputField("Sub-location / area detail", "subLocation", claim?.subLocation ?? "", { placeholder: "Optional area within the location" })}
        ${selectField("Classification", "classification", CLAIM_CLASSIFICATIONS, classification, undefined, "Stored claim mark only — not an observation, evidence or conclusion.")}
        ${selectField("Walkthrough status", "walkthroughStatus", CLAIM_WALKTHROUGH_STATUSES, walkthroughStatus)}
      </div>
      ${checkboxField("Classification marked resolved", "classificationResolved", claim?.classificationResolved ?? false)}
      ${textareaField("Investigator notes", "notes", claim?.notes ?? "", { rows: 3, help: "Notes are stored investigator text, not a conclusion or observation record." })}
    </div>

    <div class="claim-form-group">
      <h5>Reported occurrence</h5>
      <div class="detail-grid">
        ${selectField("Occurrence level", "occurrenceLevel", OCCURRENCE_LEVELS, occurrenceLevel, "Not recorded")}
        ${inputField("Frequency", "frequency", claim?.frequency ?? "", { placeholder: "e.g. Nightly, weekly, once" })}
        ${inputField("Time pattern", "timePattern", claim?.timePattern ?? "", { placeholder: "e.g. Around 02:00" })}
      </div>
      ${textareaField("First occurrence text", "firstOccurrenceText", claim?.firstOccurrenceText ?? "", { rows: 2 })}
      ${textareaField("Most recent occurrence text", "mostRecentOccurrenceText", claim?.mostRecentOccurrenceText ?? "", { rows: 2 })}
      <div class="detail-grid">
        ${selectField("Most recent occurrence known", "mostRecentOccurrenceKnown", ["yes", "no"], mostRecentKnown, "Not recorded")}
        ${inputField("Weather pattern", "weatherPattern", claim?.weatherPattern ?? "", { placeholder: "Weather context reported by the witness" })}
      </div>
      ${checkboxField("Weather correlation marked", "weatherCorrelation", claim?.weatherCorrelation ?? false)}
    </div>

    <div class="claim-form-group">
      <h5>Witness information</h5>
      <div class="detail-grid">
        ${inputField("Witness count", "witnessCount", String(claim?.witnessCount ?? 0), { type: "number", min: 0, step: 1 })}
        ${inputField("Emotional impact", "emotionalImpact", String(claim?.emotionalImpact ?? 0), { type: "number", min: 0, step: 1, help: "Integer scale value as stored; no scale is inferred." })}
      </div>
      ${checkboxField("Witness count marked resolved", "witnessCountResolved", claim?.witnessCountResolved ?? false)}
      ${checkboxField("Emotional impact marked resolved", "emotionalImpactResolved", claim?.emotionalImpactResolved ?? false)}
      ${textareaField("Witness name or source text", "witnessesText", claim?.witnessesText ?? "", { rows: 2, placeholder: "Exactly as reported; no member directory lookup is performed" })}
      ${inputField("Feeling text", "feelingText", claim?.feelingText ?? "", { placeholder: "e.g. Uneasy" })}
      ${textareaField("Feeling notes", "feelingNotes", claim?.feelingNotes ?? "", { rows: 2 })}
    </div>

    ${roomFields(claim, data)}

    <div class="form-actions">
      <button class="button-primary" type="submit" data-claim-save>${claim ? "Save Changes" : "Record Claim"}</button>
      <button class="button-secondary" type="button" data-claim-cancel>Cancel</button>
    </div>
    <p class="cc-meta">Delete is not part of this manager. Reference import is a separate explicit-destination flow. Existing imported provenance is protected by the repository, not just hidden in this form.</p>
  </form>`;
}

export function claimsManagerHtml(
  container: HTMLElement,
  data: ClaimsManagerData,
): string {
  const state = stateFor(container);
  if (state.editingId && !data.claims.some((claim) => claim.id === state.editingId)) {
    state.editingId = null;
  }
  const editing = state.editingId
    ? data.claims.find((claim) => claim.id === state.editingId) ?? null
    : null;
  const formOpen = state.creating || editing !== null;
  const roomById = new Map(data.rooms.map((room) => [room.id, room]));
  const sorted = [...data.claims].sort((a, b) => a.createdAt - b.createdAt || a.claimID.localeCompare(b.claimID));

  return `<section class="claims-manager" data-root="claims-manager" data-case-id="${esc(data.caseId)}" aria-labelledby="claims-manager-title">
    <div class="claims-manager-heading">
      <div>
        <h3 id="claims-manager-title">Claim Assignment</h3>
        <p class="cc-count">${sorted.length} claim(s) • reported, observed-marked and imported records remain distinct</p>
      </div>
      ${formOpen ? "" : `<div class="claim-manager-actions">
        <button class="button-secondary" type="button" data-claim-new>Assign Claim to Rooms</button>
        ${data.referenceImportEligible ? `<button class="button-secondary" type="button" data-reference-import-open>Import Reference Claims</button>` : ""}
      </div>`}
    </div>
    <p class="claims-safeguard" data-claim-manager-safeguard><strong>Reported information only.</strong> A claim is not evidence, not an observation record and not a paranormal conclusion. Classification is the stored claim mark; it does not verify the statement.</p>
    ${state.notice ? `<p class="claim-manager-notice" data-claim-manager-notice role="status">${esc(state.notice)}</p>` : ""}
    ${formOpen ? formHtml(editing, data) : ""}

    <div class="claim-manager-list" data-claim-manager-list>
      <h4>Claims (${sorted.length})</h4>
      ${sorted.length === 0
        ? `<p class="cc-empty" data-claim-manager-empty>No claims have been added yet.</p>`
        : sorted
            .map(
              (claim) => `<div class="claim-manager-row" data-claim-row="${esc(claim.id)}">
                <div class="claim-manager-row-text">
                  <div class="claim-manager-title-line">
                    <strong>${textOrMissing(claim.title, "Untitled claim")}</strong>
                    ${isImported(claim) ? `<span class="claims-badge claims-badge-import">${claim.importedFromReference ? "REF" : "IMPORTED"}</span>` : ""}
                  </div>
                  <div class="case-meta">${esc(claim.classification)} • ${esc(roomText(claim, roomById))} • created ${esc(new Date(claim.createdAt).toLocaleString())}</div>
                  ${claim.notes.trim() ? `<p class="claim-manager-note">${esc(claim.notes)}</p>` : ""}
                </div>
                <button class="back-button" type="button" data-claim-edit="${esc(claim.id)}">Edit Claim</button>
              </div>`,
            )
            .join("")}
    </div>

    ${referenceClaimImportHtml(container, {
      caseId: data.caseId,
      rooms: data.rooms,
      floors: data.floors,
      zones: data.zones,
      eligible: data.referenceImportEligible,
    })}
  </section>`;
}

function fieldValue(form: HTMLFormElement, field: string): string {
  const element = form.querySelector<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>(
    `[data-claim-field="${field}"]`,
  );
  return element?.value ?? "";
}

function fieldChecked(form: HTMLFormElement, field: string): boolean {
  return form.querySelector<HTMLInputElement>(`[data-claim-field="${field}"]`)?.checked ?? false;
}

function parseCount(raw: string, label: string): number {
  const value = raw.trim();
  if (!/^\d+$/.test(value)) {
    throw new Error(`${label} must be a whole number of 0 or more.`);
  }
  const parsed = Number(value);
  if (!Number.isSafeInteger(parsed)) {
    throw new Error(`${label} is too large.`);
  }
  return parsed;
}

function showFormError(container: HTMLElement, message: string): void {
  const target = container.querySelector<HTMLElement>("[data-claim-form-error]");
  if (target) {
    target.hidden = false;
    target.textContent = message;
  }
}

function clearFormError(container: HTMLElement): void {
  const target = container.querySelector<HTMLElement>("[data-claim-form-error]");
  if (target) {
    target.hidden = true;
    target.textContent = "";
  }
}

async function saveClaim(
  container: HTMLElement,
  caseId: string,
  rerender: () => Promise<void>,
): Promise<void> {
  const form = container.querySelector<HTMLFormElement>("#claim-form");
  if (!form) return;
  clearFormError(container);
  const repo = new ClaimRepository(getDb());
  const claimId = form.dataset.claimId ?? "";
  let existing: ClaimRecord | undefined;
  if (claimId) {
    existing = await repo.get(claimId);
    if (!existing || existing.caseId !== caseId) {
      showFormError(container, "This claim is not part of the selected case. No change was saved.");
      return;
    }
  }

  try {
    const title = fieldValue(form, "title").trim();
    if (!title) throw new Error("Claim title is required.");
    const classification = fieldValue(form, "classification");
    if (!CLAIM_CLASSIFICATIONS.includes(classification as ClaimClassification)) {
      throw new Error("Choose a valid claim classification.");
    }
    const walkthroughStatus = fieldValue(form, "walkthroughStatus");
    if (!CLAIM_WALKTHROUGH_STATUSES.includes(walkthroughStatus as ClaimWalkthroughStatus)) {
      throw new Error("Choose a valid walkthrough status.");
    }
    const witnessCount = parseCount(fieldValue(form, "witnessCount"), "Witness count");
    const emotionalImpact = parseCount(fieldValue(form, "emotionalImpact"), "Emotional impact");

    const selectedRoomIds = Array.from(
      form.querySelectorAll<HTMLInputElement>("input[data-claim-room]:checked"),
    ).map((element) => element.value);
    const preservedRoomIds = Array.from(
      form.querySelectorAll<HTMLInputElement>("input[data-preserved-room]"),
    ).map((element) => element.value);
    const primaryRoomId = form.querySelector<HTMLSelectElement>("[data-claim-primary]")?.value ?? "";
    const roomById = new Map(
      (await getDb().structureRooms.where("caseId").equals(caseId).toArray()).map((room) => [room.id, room]),
    );
    const primaryRoom = primaryRoomId ? roomById.get(primaryRoomId) : undefined;
    // Preserve historical unresolved references exactly: an unresolved primary
    // room that was not part of linkedRoomIds stays primary-only. Adding it to
    // the linked list would ask the repository to accept a new unresolved link.
    const linkedRoomSet = new Set([...selectedRoomIds, ...preservedRoomIds]);
    if (primaryRoom) linkedRoomSet.add(primaryRoomId);
    if (!primaryRoom && existing && !existing.linkedRoomIds.includes(primaryRoomId)) {
      linkedRoomSet.delete(primaryRoomId);
    }
    const linkedRoomIds = [...linkedRoomSet];
    const roomName = primaryRoom
      ? primaryRoom.name
      : existing?.roomName || "Structure Assigned";
    const roomTBD = linkedRoomIds.length === 0 ? existing?.roomTBD ?? false : false;
    const mostRecentKnownRaw = fieldValue(form, "mostRecentOccurrenceKnown");
    const mostRecentOccurrenceKnown =
      mostRecentKnownRaw === "yes" ? true : mostRecentKnownRaw === "no" ? false : null;

    const base: ClaimUpdateInput = {
      title,
      roomID: primaryRoomId || null,
      roomTBD,
      roomName,
      subLocation: fieldValue(form, "subLocation"),
      linkedRoomIds,
      occurrenceLevel: fieldValue(form, "occurrenceLevel"),
      claimType: fieldValue(form, "claimType"),
      claimTypeOtherText: fieldValue(form, "claimTypeOtherText"),
      firstOccurrenceText: fieldValue(form, "firstOccurrenceText"),
      mostRecentOccurrenceText: fieldValue(form, "mostRecentOccurrenceText"),
      frequency: fieldValue(form, "frequency"),
      timePattern: fieldValue(form, "timePattern"),
      weatherCorrelation: fieldChecked(form, "weatherCorrelation"),
      weatherPattern: fieldValue(form, "weatherPattern"),
      witnessCount,
      witnessesText: fieldValue(form, "witnessesText"),
      witnessCountResolved: fieldChecked(form, "witnessCountResolved"),
      emotionalImpact,
      emotionalImpactResolved: fieldChecked(form, "emotionalImpactResolved"),
      feelingText: fieldValue(form, "feelingText"),
      feelingNotes: fieldValue(form, "feelingNotes"),
      classification: classification as ClaimClassification,
      classificationResolved: fieldChecked(form, "classificationResolved"),
      notes: fieldValue(form, "notes"),
      walkthroughStatus: walkthroughStatus as ClaimWalkthroughStatus,
      mostRecentOccurrenceKnown,
    };

    if (existing) {
      await repo.update(existing.id, base);
    } else {
      const createInput: ClaimCreateInput = {
        caseId,
        locationId: null,
        ...base,
        title,
      };
      await repo.create(createInput);
    }

    const state = stateFor(container);
    state.creating = false;
    state.editingId = null;
    state.notice = existing
      ? "Claim updated. Imported source material and provenance were preserved."
      : "Claim recorded as reported information. No evidence, observation or readiness record was created.";
    clearDrafts(container);
    await rerender();
  } catch (error) {
    showFormError(container, (error as Error).message || "The claim could not be saved.");
  }
}

export function wireClaimsManager(
  container: HTMLElement,
  caseId: string,
  rerender: () => Promise<void>,
): void {
  onDelegate(container, "click", "[data-claim-new]", () => {
    const state = stateFor(container);
    state.creating = true;
    state.editingId = null;
    state.notice = "";
    clearDrafts(container);
    void rerender();
  });
  onDelegate(container, "click", "[data-claim-edit]", (element) => {
    const state = stateFor(container);
    state.creating = false;
    state.editingId = element.dataset.claimEdit ?? null;
    state.notice = "";
    clearDrafts(container);
    void rerender();
  });
  onDelegate(container, "click", "[data-claim-cancel]", () => {
    const state = stateFor(container);
    state.creating = false;
    state.editingId = null;
    clearDrafts(container);
    void rerender();
  });
  onDelegate(container, "submit", "#claim-form", (element, event) => {
    event.preventDefault();
    void saveClaim(container, caseId, rerender).catch((error) => {
      showFormError(container, (error as Error).message || "The claim could not be saved.");
    });
    void element;
  });
}
