/**
 * Checklist and Investigation Status screens — TPI-V2-WEB-C4.
 *
 * ORIGINAL SOURCES:
 *   Cases/CaseChecklistView.swift (367 lines)
 *   Cases/CaseProgressView.swift (352 lines)
 *   Cases/PPCaseProgressEvaluator.swift
 *   Core/FrontHalf/PPCaseWizardChecklistEngine.swift
 *   Core/FrontHalf/PPFrontHalfWorkflowChecklist.swift
 *
 * The original Checklist is a single ordered list of six canonical front-half
 * requirements. The original Investigation Status is a phase/progress screen
 * that lists those milestones and routes into the workflow sections.
 *
 * WHAT THIS BUILD DOES
 *   - Uses the existing canonical checklist (six original items plus the
 *     C1/TPI-V2-WEB-009 evidence-review requirement).
 *   - Uses WorkflowReadinessService for readiness, blockers and next steps.
 *   - Uses ChecklistService for every checklist mutation, including its
 *     justification and non-overridable-document validation.
 *   - Uses persisted sessions for current/latest session status.
 *
 * It does NOT add a schema, store, phase authority, readiness calculation,
 * automatic completion, automatic phase change or fabricated workflow state.
 * Missing records are shown as missing; future requirements are marked as such.
 */
import "./casehub.css";
import { getDb } from "../../core/db";
import { CaseRepository } from "../../core/repositories/caseRepository";
import {
  WorkflowService,
  WorkflowReadinessService,
  ChecklistService,
  WORKFLOW_PHASE_ORDER,
  type NextStep,
  type ReadinessState,
  type WorkflowBlocker,
  type WorkflowProgress,
} from "../../core/workflow/workflowService";
import { SessionService } from "../../core/session/sessionService";
import { InvestigationCompletionService } from "../../core/workflow/investigationCompletionService";
import type {
  CaseRecord,
  ChecklistItemRecord,
  InvestigationSessionRecord,
  RoomRecord,
  WorkflowPhase,
} from "../../core/types";
import { esc } from "../dashboard/shell";
import { invalidateView, mountView, onDelegate } from "../../shared/uidom";
import { renderCaseHub } from "./CaseHub";

const db = () => getDb();

type WorkflowEvaluation = {
  state: ReadinessState;
  blockers: WorkflowBlocker[];
  progress: WorkflowProgress;
  nextSteps: NextStep[];
};

const PHASE_LABEL: Record<WorkflowPhase, string> = {
  caseCreation: "Case Creation",
  documents: "Documents",
  intake: "Intake",
  walkthrough: "Walkthrough",
  baseline: "Baseline",
  investigationReady: "Investigation Ready",
  investigation: "Investigation",
  review: "Evidence Review",
  summary: "Summary",
};

const CHECKLIST_STATE_LABEL: Record<string, string> = {
  complete: "Completed",
  pending: "Pending",
  exception: "Documented Exception",
  notApplicable: "Not Applicable",
  blocked: "Blocked",
  inProgress: "In Progress",
  future: "Pending",
};

function fmtTime(ms: number | null | undefined): string {
  return ms ? new Date(ms).toLocaleString() : "—";
}

function fmtDuration(start: number, end: number | null | undefined): string {
  if (!end || end < start) return "—";
  const minutes = Math.round((end - start) / 60_000);
  if (minutes < 60) return `${minutes} min`;
  return `${Math.floor(minutes / 60)} h ${minutes % 60} min`;
}

function acceptedNotApplicable(item: ChecklistItemRecord): boolean {
  return item.status === "notApplicable" && item.notes.trim().length > 0;
}

function toast(message: string, error = false): void {
  const el = document.createElement("div");
  el.className = error ? "toast error" : "toast";
  el.setAttribute("role", error ? "alert" : "status");
  el.textContent = message;
  document.body.appendChild(el);
  window.setTimeout(() => el.remove(), 5000);
}

function facts(rows: Array<[string, string]>): string {
  return `<div class="cc-native-facts">${rows
    .map(([label, value]) => `<div class="cc-native-fact"><strong>${esc(label)}</strong>${value}</div>`)
    .join("")}</div>`;
}

function meter(label: string, value: number): string {
  return `<div class="progress-row"><span>${esc(label)}</span>
    <div class="meter" role="meter" aria-label="${esc(label)}" aria-valuenow="${value}" aria-valuemin="0" aria-valuemax="100"><div class="fill" style="width:${value}%"></div></div>
    <span class="pct">${value}%</span></div>`;
}

function itemWorkflowState(item: ChecklistItemRecord, due: boolean, blockers: WorkflowBlocker[]): string {
  if (item.status === "complete" || item.status === "exception") return item.status;
  if (item.status === "notApplicable") return item.notes.trim().length > 0 ? "notApplicable" : due ? "blocked" : "future";
  if (!due) return "future";
  if (blockers.length > 0) return "blocked";
  return "inProgress";
}

function badgeClass(state: string): string {
  if (state === "complete") return "status-badge";
  if (state === "exception") return "status-badge exception";
  return "status-badge pending";
}

async function loadWorkflow(caseId: string): Promise<{
  record: CaseRecord;
  evaluation: WorkflowEvaluation;
  items: ChecklistItemRecord[];
} | null> {
  if (!caseId) return null;
  const record = await new CaseRepository(db()).getCase(caseId);
  if (!record) return null;
  const evaluation = await new WorkflowReadinessService(db()).evaluate(record.id);
  if (!evaluation) return null;
  // Checklist reconciliation happens inside evaluate(); read afterwards so the
  // screen renders the authoritative post-reconciliation state.
  const items = await new ChecklistService(db()).listForCase(record.id);
  return { record, evaluation, items };
}

function renderWorkflowMissing(container: HTMLElement, kind: "checklist" | "status"): void {
  const label = kind === "checklist" ? "Checklist" : "Investigation Status";
  const marker = kind === "checklist" ? "data-checklist-missing" : "data-status-missing";
  invalidateView(container);
  mountView(
    container,
    `<div class="view workflow-screen" ${marker}="true">
      <div class="view-header">
        <button class="back-button" id="${kind}-missing-back" type="button">‹ Case Files</button>
        <h2>${label}</h2>
      </div>
      <div class="cc-empty">
        <p><strong>Case not found.</strong> This case does not exist or is no longer available.</p>
        <p class="cc-meta">No other case was opened. Choose a case from Case Files to continue.</p>
      </div>
    </div>`,
  );
  onDelegate(container, "click", `#${kind}-missing-back`, () => {
    window.location.hash = "/command-center";
  });
}

/* ============================================================
 * Dedicated Checklist screen
 * ============================================================ */

export async function renderChecklistView(container: HTMLElement, caseId: string): Promise<void> {
  const loaded = await loadWorkflow(caseId);
  if (!loaded) {
    renderWorkflowMissing(container, "checklist");
    return;
  }
  const { record, evaluation, items } = loaded;
  const currentIdx = WORKFLOW_PHASE_ORDER.indexOf(record.currentPhase);
  const required = items.filter((item) => item.required);
  const optional = items.filter((item) => !item.required);
  const completed = items.filter((item) => item.status === "complete");
  const exceptions = items.filter((item) => item.status === "exception");
  const acceptedNa = required.filter(acceptedNotApplicable);
  const outstanding = required.filter(
    (item) =>
      item.status !== "complete" &&
      item.status !== "exception" &&
      !acceptedNotApplicable(item),
  );
  const categories = WORKFLOW_PHASE_ORDER
    .map((phase) => ({ phase, items: items.filter((item) => item.phase === phase) }))
    .filter((category) => category.items.length > 0);

  const categoryHtml = categories
    .map(({ phase, items: categoryItems }) => {
      const closed = categoryItems.filter((item) => item.status === "complete" || item.status === "exception").length;
      const requiredCount = categoryItems.filter((item) => item.required).length;
      return `<section class="workflow-category" data-checklist-category="${esc(phase)}">
        <div class="workflow-category-head">
          <div>
            <h3>${esc(PHASE_LABEL[phase])}</h3>
            <p class="cc-meta">${requiredCount} required requirement(s) · ${closed} satisfied</p>
          </div>
          <span class="status-badge pending">${esc(phase)}</span>
        </div>
        ${categoryItems.map((item) => checklistItemHtml(record, item, currentIdx, evaluation.blockers)).join("")}
      </section>`;
    })
    .join("");

  const outstandingHtml = outstanding.length
    ? `<ul class="summary-list" data-checklist-outstanding>${outstanding
        .map(
          (item) => `<li data-checklist-outstanding-item="${esc(item.definitionId)}">
            <span class="summary-head"><span class="${badgeClass(item.status)}">${esc(item.status === "notApplicable" ? "Not applicable — reason required" : "Outstanding")}</span><strong>${esc(item.title)}</strong></span>
            <p class="cc-meta">${esc(PHASE_LABEL[item.phase])} · ${item.required ? "required" : "optional"}${item.status === "notApplicable" ? " · N/A reason missing; this remains outstanding" : ""}</p>
          </li>`,
        )
        .join("")}</ul>`
    : `<p class="cc-meta" data-checklist-outstanding-empty>No outstanding requirements.</p>`;

  const acceptedNaHtml = acceptedNa.length
    ? `<ul class="summary-list" data-checklist-na>${acceptedNa
        .map(
          (item) => `<li data-checklist-na-item="${esc(item.definitionId)}">
            <span class="summary-head"><span class="status-badge pending">accepted N/A</span><strong>${esc(item.title)}</strong></span>
            <p class="cc-meta">${esc(PHASE_LABEL[item.phase])} · not counted as completed work${item.notes.trim() ? ` · reason: ${esc(item.notes)}` : ""}</p>
          </li>`,
        )
        .join("")}</ul>`
    : `<p class="cc-meta" data-checklist-na-empty>No accepted N/A requirements.</p>`;

  const exceptionHtml = exceptions.length
    ? `<ul class="summary-list" data-checklist-exceptions>${exceptions
        .map(
          (item) => `<li data-checklist-exception="${esc(item.definitionId)}">
            <span class="summary-head"><span class="status-badge exception">documented exception</span><strong>${esc(item.title)}</strong></span>
            <p class="cc-meta">${esc(item.notes || "Exception recorded without notes.")}</p>
          </li>`,
        )
        .join("")}</ul>`
    : `<p class="cc-meta" data-checklist-exceptions-empty>No documented exceptions.</p>`;

  const blockerHtml = evaluation.blockers.length
    ? `<ul class="summary-list" data-checklist-blockers>${evaluation.blockers
        .map(
          (blocker) => `<li data-checklist-blocker="${esc(blocker.id)}" data-severity="${esc(blocker.severity)}" data-override="${blocker.overridePermitted ? "permitted" : "refused"}">
            <span class="summary-head"><span class="status-badge ${blocker.severity === "error" ? "error" : "pending"}">${esc(blocker.severity)}</span><strong>${esc(blocker.reason)}</strong></span>
            <p class="cc-meta">Phase: ${esc(PHASE_LABEL[blocker.phase])} · Required action: ${esc(blocker.requiredAction)}</p>
            <p class="cc-meta">${blocker.overridePermitted ? "A documented exception may satisfy this blocker." : "This blocker is not overridable."}</p>
          </li>`,
        )
        .join("")}</ul>`
    : `<p class="cc-meta" data-checklist-blockers-empty>No workflow blockers.</p>`;

  const body = `<div class="view workflow-screen" data-root="checklist" data-case-id="${esc(record.id)}" data-epoch="${Date.now()}-${Math.random()}">
    <div class="view-header">
      <button class="back-button" id="checklist-back" type="button">‹ Case Hub</button>
      <h2>Checklist</h2>
    </div>

    <section class="workflow-screen-head">
      <p class="cc-org-name">THE PARANORMAL INITIATIVE</p>
      <h3 data-checklist-case-title>${esc(record.title)}</h3>
      <p class="cc-meta">Case ${esc(record.caseNumber)} · ${esc(record.status)} · Current phase: ${esc(PHASE_LABEL[record.currentPhase])}</p>
      <p class="cc-meta">This checklist reflects the canonical workflow from case creation through evidence review. Every mutation is validated by the existing checklist service; no requirement is completed automatically here.</p>
    </section>

    <section class="workflow-summary-card" aria-labelledby="checklist-summary-title" data-checklist-summary>
      <div class="workflow-category-head">
        <div>
          <h3 id="checklist-summary-title">Case Workflow Checklist</h3>
          <p class="cc-meta">${completed.length} completed · ${acceptedNa.length} accepted N/A · ${outstanding.length} outstanding · ${exceptions.length} documented exception(s)</p>
        </div>
        <span class="${badgeClass(evaluation.state)}" data-checklist-readiness="${esc(evaluation.state)}">${esc(evaluation.state)}</span>
      </div>
      ${meter("Checklist completion", evaluation.progress.checklistPercent)}
      <div class="progress-row"><span>Phase progression</span>
        <div class="meter" role="meter" aria-label="Phase progression" aria-valuenow="${evaluation.progress.phasePercent}" aria-valuemin="0" aria-valuemax="100"><div class="fill" style="width:${evaluation.progress.phasePercent}%"></div></div>
        <span class="pct">${evaluation.progress.phasePercent}%</span></div>
      ${facts([
        ["Required requirements", `${required.length} total`],
        ["Completed requirements", `${required.filter((item) => item.status === "complete").length} completed`],
        ["Accepted N/A requirements", `${acceptedNa.length} accepted N/A`],
        ["Outstanding requirements", `${outstanding.length} outstanding`],
        ["Optional requirements", optional.length ? `${optional.length} defined` : "None defined by the canonical checklist"],
        ["Workflow blockers", String(evaluation.blockers.length)],
        ["Documented exceptions", String(evaluation.progress.overrideCount)],
      ])}
      <p class="cc-meta" data-checklist-source-note>Readiness, blockers and percentages come from WorkflowReadinessService. The original full-access/minimal-requirement mode is not present in this browser build, so every canonical item remains required.</p>
    </section>

    <section class="workflow-section" aria-labelledby="checklist-requirements-title">
      <div class="workflow-section-head">
        <h3 id="checklist-requirements-title">Requirements by Category</h3>
        <p class="cc-meta">Categories follow the canonical workflow phases, in the same order used by the workflow engine. The original presents one numbered list.</p>
      </div>
      ${categoryHtml || `<p class="cc-empty">No checklist requirements are recorded for this case.</p>`}
    </section>

    <section class="cc-native-card" data-checklist-section="outstanding">
      <h3>Outstanding Requirements</h3>
      ${outstandingHtml}
    </section>

    <section class="cc-native-card" data-checklist-section="accepted-na">
      <h3>Accepted N/A Requirements</h3>
      ${acceptedNaHtml}
    </section>

    <section class="cc-native-card" data-checklist-section="exceptions">
      <h3>Documented Exceptions</h3>
      ${exceptionHtml}
    </section>

    <section class="cc-native-card" data-checklist-section="blockers">
      <h3>Workflow Blockers</h3>
      ${blockerHtml}
    </section>

    <section class="cc-native-card" data-checklist-section="limitations">
      <h3>Source and Scope Notes</h3>
      <ul class="workflow-notes">
        <li>The original checklist order places Intake before Required Documents. This browser's canonical phase chain keeps Documents before Intake, as established by TPI-V2-WEB-005.</li>
        <li>Required Documents is not closed by a manual status alone. Its completion is reconciled from signed, finalized records in Documents + Signatures; exception and not-applicable controls are not offered here.</li>
        <li>Room-level subtotals shown by the original Walkthrough and Baseline rows are not duplicated here; those live in their dedicated modules.</li>
      </ul>
    </section>
  </div>`;

  invalidateView(container);
  mountView(container, body);
  onDelegate(container, "click", "#checklist-back", () => {
    void renderCaseHub(container, caseId);
  });
  onDelegate(container, "click", "[data-checklist-action]", (button) => {
    void handleChecklistAction(container, caseId, button);
  });
}

function checklistItemHtml(
  record: CaseRecord,
  item: ChecklistItemRecord,
  currentIdx: number,
  blockers: WorkflowBlocker[],
): string {
  const itemIdx = WORKFLOW_PHASE_ORDER.indexOf(item.phase);
  const due = itemIdx <= currentIdx;
  const itemBlockers = blockers.filter((blocker) => blocker.phase === item.phase || blocker.sourceRecordId === item.id);
  const workflowState = itemWorkflowState(item, due, itemBlockers);
  const isDocumentGate = item.definitionId === "requiredDocumentsSigned";
  const actionHtml = item.status === "pending"
    ? `<button class="workflow-action" type="button" data-checklist-action="complete" data-case-id="${esc(record.id)}" data-item-id="${esc(item.id)}">Complete</button>
       ${isDocumentGate
         ? ""
         : `<button class="workflow-action" type="button" data-checklist-action="exception" data-case-id="${esc(record.id)}" data-item-id="${esc(item.id)}">Document Exception</button>
            <button class="workflow-action" type="button" data-checklist-action="notApplicable" data-case-id="${esc(record.id)}" data-item-id="${esc(item.id)}">Not Applicable</button>`}`
    : `<button class="workflow-action" type="button" data-checklist-action="pending" data-case-id="${esc(record.id)}" data-item-id="${esc(item.id)}">Reopen</button>`;

  return `<article class="workflow-item" data-checklist-item data-definition-id="${esc(item.definitionId)}" data-checklist-status="${esc(item.status)}" data-workflow-state="${esc(workflowState)}" data-due="${due ? "true" : "false"}" data-required="${item.required ? "true" : "false"}">
    <div class="workflow-item-main">
      <div class="workflow-item-heading">
        <span class="workflow-index">${WORKFLOW_PHASE_ORDER.indexOf(item.phase) + 1}.</span>
        <strong>${esc(item.title)}</strong>
        <span class="status-badge ${item.required ? "" : "pending"}">${item.required ? "required" : "optional"}</span>
        <span class="${badgeClass(workflowState)}" data-checklist-state-label>${esc(CHECKLIST_STATE_LABEL[workflowState] ?? workflowState)}</span>
      </div>
      <p class="cc-meta">${esc(item.guidance ?? "No guidance text was recorded for this requirement.")}</p>
      <p class="cc-meta">${due ? "Due in the current or an earlier phase." : `Future phase: ${esc(PHASE_LABEL[item.phase])}.`}${item.completedAt ? ` · Completed ${esc(fmtTime(item.completedAt))}${item.completedBy ? ` by ${esc(item.completedBy)}` : ""}` : ""}</p>
      ${item.notes.trim() ? `<p class="cc-meta workflow-item-note">${item.status === "exception" ? "Exception" : item.status === "notApplicable" ? "Not-applicable reason" : "Notes"}: ${esc(item.notes)}</p>` : ""}
      ${isDocumentGate ? `<p class="cc-meta" data-checklist-derived-note>This requirement is reconciled from signed, finalized document records. A manual completion does not bypass the documents gate and is reset when readiness is evaluated.</p>` : ""}
      ${itemBlockers.length
        ? `<ul class="workflow-item-blockers" data-checklist-item-blockers>${itemBlockers
            .map(
              (blocker) => `<li><span class="status-badge ${blocker.overridePermitted ? "pending" : "error"}">${blocker.overridePermitted ? "overridable" : "not overridable"}</span> ${esc(blocker.reason)} <span class="cc-meta">${esc(blocker.requiredAction)}</span></li>`,
            )
            .join("")}</ul>`
        : ""}
    </div>
    <div class="workflow-item-actions">${actionHtml}</div>
  </article>`;
}

async function handleChecklistAction(container: HTMLElement, caseId: string, button: HTMLElement): Promise<void> {
  const itemId = button.dataset.itemId ?? "";
  const action = button.dataset.checklistAction ?? "";
  if (!itemId || !action) return;
  const service = new ChecklistService(db());
  try {
    if (action === "exception" || action === "notApplicable") {
      const promptText = action === "exception"
        ? "Document the exception and its justification:"
        : "Document why this requirement is not applicable:";
      const reason = window.prompt(promptText, "");
      if (reason === null) return;
      if (!reason.trim()) {
        toast("A documented reason is required.", true);
        return;
      }
      await service.setItemStatus(caseId, itemId, action, { justification: reason.trim() });
    } else if (action === "complete" || action === "pending") {
      await service.setItemStatus(caseId, itemId, action);
    } else {
      return;
    }
    await renderChecklistView(container, caseId);
  } catch (err) {
    toast((err as Error).message, true);
  }
}

/* ============================================================
 * Dedicated Investigation Status screen
 * ============================================================ */

export async function renderInvestigationStatusView(container: HTMLElement, caseId: string): Promise<void> {
  const loaded = await loadWorkflow(caseId);
  if (!loaded) {
    renderWorkflowMissing(container, "status");
    return;
  }
  const { record, evaluation, items } = loaded;
  const [stage, sessions, rooms, investigationCompletion] = await Promise.all([
    Promise.resolve(new WorkflowService(db()).lifecycleStage(record)),
    new SessionService(db()).listSessions(record.id),
    db().structureRooms.where("caseId").equals(record.id).toArray(),
    new InvestigationCompletionService(db()).getCompletion(record.id),
  ]);
  const activeRooms = (rooms as RoomRecord[]).filter((room) => !room.archived).sort((a, b) => a.orderIndex - b.orderIndex);
  const activeSession = sessions.find((session) => session.status === "active" || session.status === "paused");
  const latestSession = [...sessions].sort((a, b) => b.startedAt - a.startedAt)[0];
  const completed = items.filter((item) => item.status === "complete");
  const exceptions = items.filter((item) => item.status === "exception");
  const acceptedNa = items.filter((item) => item.required && acceptedNotApplicable(item));
  const outstanding = items.filter(
    (item) =>
      item.required &&
      item.status !== "complete" &&
      item.status !== "exception" &&
      !acceptedNotApplicable(item),
  );
  const atFinal = record.currentPhase === WORKFLOW_PHASE_ORDER[WORKFLOW_PHASE_ORDER.length - 1];
  const nextPhase = atFinal ? null : WORKFLOW_PHASE_ORDER[WORKFLOW_PHASE_ORDER.indexOf(record.currentPhase) + 1] ?? null;
  const canAdvance = Boolean(
    nextPhase &&
    record.status !== "archived" &&
    evaluation.blockers.length === 0 &&
    (evaluation.state === "ready" || evaluation.state === "overridden"),
  );
  const roomName = (roomId: string | null | undefined): string =>
    activeRooms.find((room) => room.id === roomId)?.name ?? "Not recorded";

  const timeline = new WorkflowService(db()).phaseTimeline(record);
  const phaseHtml = timeline
    .map(({ phase, current, index }) => {
      const currentIdx = WORKFLOW_PHASE_ORDER.indexOf(record.currentPhase);
      const state = index < currentIdx ? "done" : current ? "current" : "future";
      return `<li class="workflow-phase ${state}" data-status-phase="${esc(phase)}" data-phase-state="${state}"${current ? ' aria-current="step"' : ""}>
        <span class="workflow-phase-number">${index + 1}</span>
        <span>${esc(PHASE_LABEL[phase])}</span>
      </li>`;
    })
    .join("");

  const milestoneHtml = completed.length
    ? `<ul class="summary-list" data-status-milestones>${completed
        .map(
          (item) => `<li data-status-milestone="${esc(item.definitionId)}">
            <span class="summary-head"><span class="status-badge">completed</span><strong>${esc(item.title)}</strong></span>
            <p class="cc-meta">${esc(PHASE_LABEL[item.phase])}${item.completedAt ? ` · ${esc(fmtTime(item.completedAt))}` : ""}${item.completedBy ? ` · ${esc(item.completedBy)}` : ""}</p>
          </li>`,
        )
        .join("")}</ul>`
    : `<p class="cc-meta" data-status-milestones-empty>No checklist milestones are complete.</p>`;

  const outstandingHtml = outstanding.length
    ? `<ul class="summary-list" data-status-outstanding>${outstanding
        .map(
          (item) => `<li data-status-outstanding-item="${esc(item.definitionId)}">
            <span class="summary-head"><span class="status-badge pending">${item.status === "notApplicable" ? "N/A reason required" : "outstanding"}</span><strong>${esc(item.title)}</strong></span>
            <p class="cc-meta">${esc(PHASE_LABEL[item.phase])} · ${item.status === "notApplicable" ? "a reasoned N/A is accepted; this reason is missing" : "required"}</p>
          </li>`,
        )
        .join("")}</ul>`
    : `<p class="cc-meta" data-status-outstanding-empty>No outstanding requirements.</p>`;

  const acceptedNaHtml = acceptedNa.length
    ? `<ul class="summary-list" data-status-na>${acceptedNa
        .map(
          (item) => `<li data-status-na-item="${esc(item.definitionId)}">
            <span class="summary-head"><span class="status-badge pending">accepted N/A</span><strong>${esc(item.title)}</strong></span>
            <p class="cc-meta">${esc(PHASE_LABEL[item.phase])} · not counted as completed work · reason: ${esc(item.notes)}</p>
          </li>`,
        )
        .join("")}</ul>`
    : `<p class="cc-meta" data-status-na-empty>No accepted N/A requirements.</p>`;

  const blockerHtml = evaluation.blockers.length
    ? `<ul class="summary-list" data-status-blockers>${evaluation.blockers
        .map(
          (blocker) => `<li data-status-blocker="${esc(blocker.id)}" data-severity="${esc(blocker.severity)}" data-override="${blocker.overridePermitted ? "permitted" : "refused"}">
            <span class="summary-head"><span class="status-badge ${blocker.severity === "error" ? "error" : "pending"}">${esc(blocker.severity)}</span><strong>${esc(blocker.reason)}</strong></span>
            <p class="cc-meta">${esc(PHASE_LABEL[blocker.phase])} · Required action: ${esc(blocker.requiredAction)}</p>
            <p class="cc-meta">${blocker.overridePermitted ? "A documented exception may satisfy this blocker." : "This blocker is not overridable."}</p>
          </li>`,
        )
        .join("")}</ul>`
    : `<p class="cc-meta" data-status-blockers-empty>No blocking conditions.</p>`;

  const exceptionHtml = exceptions.length
    ? `<ul class="summary-list" data-status-exceptions>${exceptions
        .map(
          (item) => `<li data-status-exception="${esc(item.definitionId)}">
            <span class="summary-head"><span class="status-badge exception">exception</span><strong>${esc(item.title)}</strong></span>
            <p class="cc-meta">${esc(item.notes || "Exception recorded without notes.")}</p>
          </li>`,
        )
        .join("")}</ul>`
    : `<p class="cc-meta" data-status-exceptions-empty>No documented exceptions.</p>`;

  const nextHtml = evaluation.nextSteps.length
    ? `<ul class="summary-list" data-status-next-steps>${evaluation.nextSteps
        .map(
          (step, index) => `<li data-status-next="${index}">
            <span class="summary-head"><span class="status-badge ${step.available ? "" : "pending"}">${step.available ? "available" : "not available"}</span><strong>${esc(step.action)}</strong></span>
            <p class="cc-meta">${step.phase ? `Phase: ${esc(PHASE_LABEL[step.phase])}` : "No phase"}${step.available ? "" : " · module pending"}</p>
          </li>`,
        )
        .join("")}</ul>`
    : `<p class="cc-meta" data-status-next-steps-empty>No next step is recorded.</p>`;

  const sessionHtml = latestSession
    ? `<ul class="summary-list" data-status-sessions>${[...sessions]
        .sort((a, b) => b.startedAt - a.startedAt)
        .slice(0, 5)
        .map(
          (session: InvestigationSessionRecord) => `<li data-status-session="${esc(session.id)}" data-session-status="${esc(session.status)}">
            <span class="summary-head"><span class="status-badge ${session.status === "active" || session.status === "paused" ? "" : "pending"}">${esc(session.status)}</span><strong>${esc(fmtTime(session.startedAt))}</strong></span>
            <p class="cc-meta">Ended: ${esc(fmtTime(session.endedAt))} · Duration: ${esc(fmtDuration(session.startedAt, session.endedAt))}${session.interrupted ? " · interrupted (recovered)" : ""}</p>
            <p class="cc-meta">Investigators: ${esc(session.investigators.length ? session.investigators.join(", ") : "Not recorded")} · Room: ${esc(roomName(session.currentRoomId))}</p>
            ${session.notes?.trim() ? `<p class="cc-meta summary-copy">${esc(session.notes.trim())}</p>` : ""}
          </li>`,
        )
        .join("")}</ul>`
    : `<p class="cc-meta" data-status-sessions-empty>No investigation sessions have been recorded.</p>`;

  const advanceNote = atFinal
    ? "This case is at the final workflow phase."
    : canAdvance
      ? `The workflow service permits advancement to ${PHASE_LABEL[nextPhase!]}.`
      : record.status === "archived"
        ? "Archived cases cannot advance."
        : "Advancement is unavailable while blockers remain. Resolve the listed conditions first.";

  const body = `<div class="view workflow-screen" data-root="investigation-status" data-case-id="${esc(record.id)}" data-epoch="${Date.now()}-${Math.random()}">
    <div class="view-header">
      <button class="back-button" id="status-back" type="button">‹ Case Hub</button>
      <h2>Investigation Status</h2>
    </div>

    <section class="workflow-screen-head">
      <p class="cc-org-name">THE PARANORMAL INITIATIVE</p>
      <h3 data-status-case-title>${esc(record.title)}</h3>
      <p class="cc-meta">Case ${esc(record.caseNumber)} · ${esc(record.status)} · ${esc(record.investigationType)} investigation</p>
      <p class="cc-meta">Phase, readiness and next actions are read from the authoritative workflow services. This screen keeps no workflow state of its own.</p>
    </section>

    <section class="cc-native-card" data-status-section="phase">
      <h3>Current Phase</h3>
      ${facts([
        ["Workflow phase", esc(PHASE_LABEL[record.currentPhase])],
        ["Lifecycle stage", esc(stage)],
        ["Case status", esc(record.status)],
        ["Investigation type", esc(record.investigationType)],
        ["Rooms defined", String(activeRooms.length)],
      ])}
      <ol class="workflow-path" aria-label="Workflow phase timeline">${phaseHtml}</ol>
    </section>

    <section class="cc-native-card" data-status-section="readiness">
      <h3>Investigation Readiness</h3>
      <div class="workflow-readiness-head">
        <span class="status-badge ${evaluation.state === "blocked" ? "error" : evaluation.state === "ready" ? "" : "pending"}" data-status-readiness="${esc(evaluation.state)}">${esc(evaluation.state)}</span>
        <span class="cc-meta">${evaluation.blockers.length} blocker(s) · ${evaluation.progress.outstandingRequiredCount} outstanding required item(s) · ${acceptedNa.length} accepted N/A · ${evaluation.progress.overrideCount} documented exception(s)</span>
      </div>
      ${meter("Phase progression", evaluation.progress.phasePercent)}
      ${meter("Checklist completion", evaluation.progress.checklistPercent)}
      <p class="cc-meta">Readiness comes from documents, intake, walkthrough, baseline and evidence-review records, not from this screen. Progress is never combined into one score.</p>
    </section>

    <section class="cc-native-card" data-status-section="completion">
      <h3>Investigation Completion</h3>
      ${investigationCompletion
        ? `<p class="cc-count" data-status-completion="complete">Explicitly completed ${esc(fmtTime(investigationCompletion.completedAt))}.</p>
           <p class="cc-meta">Evidence Review is unlocked for this case. The completion event is retained in the case audit trail.</p>`
        : `<p class="cc-count" data-status-completion="missing">Not recorded.</p>
           <p class="cc-meta">Evidence Review is locked until an explicit Complete Investigation action is recorded. Ending a session alone does not complete the investigation.</p>`}
    </section>

    <section class="cc-native-card" data-status-section="milestones">
      <h3>Completed Milestones</h3>
      ${milestoneHtml}
    </section>

    <section class="cc-native-card" data-status-section="outstanding">
      <h3>Outstanding Requirements</h3>
      ${outstandingHtml}
    </section>

    <section class="cc-native-card" data-status-section="accepted-na">
      <h3>Accepted N/A Requirements</h3>
      ${acceptedNaHtml}
    </section>

    <section class="cc-native-card" data-status-section="blockers">
      <h3>Blocking Conditions</h3>
      ${blockerHtml}
    </section>

    <section class="cc-native-card" data-status-section="sessions">
      <h3>Investigation Sessions</h3>
      ${facts([
        ["Current session", activeSession ? esc(`${activeSession.status} since ${fmtTime(activeSession.startedAt)}`) : "No active session"],
        ["Latest session", latestSession ? esc(`${latestSession.status} — ${fmtTime(latestSession.startedAt)}`) : "Not recorded"],
        ["Sessions recorded", String(sessions.length)],
        ["Current room", activeSession ? esc(roomName(activeSession.currentRoomId)) : "Not recorded"],
      ])}
      ${sessionHtml}
    </section>

    <section class="cc-native-card" data-status-section="exceptions">
      <h3>Documented Exceptions</h3>
      ${exceptionHtml}
    </section>

    <section class="cc-native-card" data-status-section="next">
      <h3>Next Permitted Workflow Actions</h3>
      ${nextHtml}
      <div class="workflow-advance">
        <button class="button-primary" id="status-advance" type="button" data-case-id="${esc(record.id)}" data-status-advance="${canAdvance ? "allowed" : atFinal ? "final" : "blocked"}" ${canAdvance ? "" : "disabled"}>${atFinal ? "Final Phase" : nextPhase ? `Advance to ${esc(PHASE_LABEL[nextPhase])}` : "Advance Workflow"}</button>
        <p class="cc-meta" data-status-advance-note>${esc(advanceNote)}</p>
      </div>
    </section>

    <section class="cc-native-card" data-status-section="limitations">
      <h3>Source and Scope Notes</h3>
      <ul class="workflow-notes">
        <li>The original status screen also lists Timeline, Review, Summary and Archive sections, and locks Review until an “Investigation Completed” system event exists. This browser records explicit completion as a case-level <code>investigationCompleted</code> audit event; the Review entry and readiness gate require it. Ending a session alone does not create it.</li>
        <li>The original full-access/minimal-requirement behaviour for location cases is not represented in the browser data model. This screen never marks a requirement not required.</li>
        <li>Advancement is only offered when the workflow service reports no blockers and readiness is ready or overridden. The button calls <code>advanceIfReady</code>; it cannot silently advance a blocked case.</li>
      </ul>
    </section>
  </div>`;

  invalidateView(container);
  mountView(container, body);
  onDelegate(container, "click", "#status-back", () => {
    void renderCaseHub(container, caseId);
  });
  onDelegate(container, "click", "#status-advance", (button) => {
    void handleAdvance(container, caseId, button);
  });
}

async function handleAdvance(container: HTMLElement, caseId: string, button: HTMLElement): Promise<void> {
  if (button.dataset.statusAdvance !== "allowed") return;
  try {
    const next = await new WorkflowReadinessService(db()).advanceIfReady(caseId);
    if (next) toast(`Workflow advanced to ${PHASE_LABEL[next.currentPhase]}.`);
    await renderInvestigationStatusView(container, caseId);
  } catch (err) {
    toast((err as Error).message, true);
  }
}
