/**
 * Append-only audit trail (Directive §9).
 * Audit events record meaningful changes with PII-free payloads.
 * There is deliberately no delete/clear API — ordinary workflows cannot
 * erase history.
 *
 * LIMITATION (documented in docs/EVIDENCE_INTEGRITY.md): a local-only audit
 * trail is not tamper-proof. Anyone with control of the device or browser
 * profile can modify or delete the underlying IndexedDB data. Integrity is
 * provided for export manifests; community-side verification is future work.
 */
import type { TPIDatabase } from "./db";

import { SCHEMA_VERSION } from "./db";
import { v4 as uuidv4 } from "../shared/uuid";
import type { AuditEventRecord, AuditEventType } from "./types";

export class AuditService {
  /** Ensures audit event timestamps are strictly increasing so ordering
   *  reflects event order even when events occur in the same millisecond. */
  private lastTimestamp = 0;

  constructor(private readonly db: TPIDatabase) {}

  private monotonicTimestamp(): number {
    const nowMs = Date.now();
    this.lastTimestamp = nowMs > this.lastTimestamp ? nowMs : this.lastTimestamp + 1;
    return this.lastTimestamp;
  }

  async record(
    type: AuditEventType,
    detail: string,
    options: {
      caseId?: string;
      affectedRecordId?: string;
      metadata?: Record<string, string | number | boolean | null>;
    } = {},
  ): Promise<AuditEventRecord> {
    if (detail.length > 500) {
      detail = detail.slice(0, 500);
    }
    const event: AuditEventRecord = {
      id: uuidv4(),
      schemaVersion: SCHEMA_VERSION,
      createdAt: this.monotonicTimestamp(),
      type,
      detail,
      caseId: options.caseId,
      affectedRecordId: options.affectedRecordId,
      metadata: options.metadata,
    };
    await this.db.auditEvents.add(event);
    return event;
  }

  async listForCase(caseId: string, limit = 100, offset = 0): Promise<AuditEventRecord[]> {
    return this.db.auditEvents
      .where("caseId")
      .equals(caseId)
      .reverse()
      .sortBy("createdAt")
      .then((all) => all.slice(offset, offset + limit));
  }
}
