/**
 * Investigation Notes view (TPI-V2-WEB-016).
 *
 * ORIGINAL REFERENCE
 *   `Cases/PPInvestigationNotesView.swift` and `Core/PPInvestigationNote.swift`.
 *   The original is a case-scoped, room/kind-filtered notes editor grouped by
 *   recency (Today, Yesterday, Previous 7 Days, …) with autosave. This browser
 *   port preserves the room/kind filters, grouping, title/body semantics and
 *   three note kinds, but saves explicitly so an accidental keystroke cannot
 *   persist a half-written observation.
 *
 * WHAT THIS IS NOT
 *   Notes are investigator-authored text. They do not create evidence or
 *   observations, change review status, complete checklist items, advance the
 *   workflow, or mark an investigation complete.
 */
import "./casehub.css";
import { getDb } from "../../core/db";
import { CaseRepository } from "../../core/repositories/caseRepository";
import {
  InvestigationNoteRepository,
  NOTE_KIND_LABELS,
  NOTE_KINDS,
} from "../../core/repositories/notesRepository";
import type {
  InvestigationNoteKind,
  InvestigationSessionRecord,
  RoomRecord,
} from "../../core/types";
import { esc, viewShell, wireBackButton } from "../dashboard/shell";
import { clearDrafts, invalidateView, mountView, onDelegate } from "../../shared/uidom";
import { renderCaseHub } from "./CaseHub";

const db = () => getDb();

interface NotesUiState {
  caseId: string;
  /** "general" (roomId === null) or a room id. Matches the original default. */
  roomFilter: string;
  kind: InvestigationNoteKind;
  selectedId: string | null;
  creating: boolean;
}

const ui = new WeakMap<HTMLElement, NotesUiState>();

function st(container: HTMLElement): NotesUiState {
  let state = ui.get(container);
  if (!state) {
    state = { caseId: "", roomFilter: "general", kind: "note", selectedId: null, creating: false };
    ui.set(container, state);
  }
  return state;
}

function fmtTime(ms: number): string {
  return new Date(ms).toLocaleString();
}

function roomLabel(rooms: RoomRecord[], roomId: string | null): string {
  if (!roomId) return "General investigator notes";
  return rooms.find((room) => room.id === roomId)?.name ?? "Room unavailable";
}

/** Original Apple-Notes-style recency buckets. */
function recencyLabel(ms: number): string {
  const startOfToday = new Date();
  startOfToday.setHours(0, 0, 0, 0);
  const today = startOfToday.getTime();
  const day = 86_400_000;
  if (ms >= today) return "Today";
  if (ms >= today - day) return "Yesterday";
  if (ms >= Date.now() - 7 * day) return "Previous 7 Days";
  if (ms >= Date.now() - 30 * day) return "Previous 30 Days";
  return "Earlier";
}

const GROUP_ORDER = ["Today", "Yesterday", "Previous 7 Days", "Previous 30 Days", "Earlier"];

function toast(message: string, error = false): void {
  const el = document.createElement("div");
  el.className = error ? "toast error" : "toast";
  el.setAttribute("role", error ? "alert" : "status");
  el.textContent = message;
  document.body.appendChild(el);
  window.setTimeout(() => el.remove(), 5000);
}

export async function renderInvestigationNotes(
  container: HTMLElement,
  caseId: string,
): Promise<void> {
  const record = await new CaseRepository(db()).getCase(caseId);
  if (!record) {
    invalidateView(container);
    mountView(container, viewShell("Investigator Notes", `<div class="cc-empty">Case not found.</div>`));
    wireBackButton(container);
    return;
  }

  const structure = await db().propertyStructures.where("caseId").equals(caseId).first();
  const rooms = structure
    ? await db().structureRooms.where("structureId").equals(structure.id).toArray()
    : [];
  const sessions = (await db().sessions.where("caseId").equals(caseId).toArray()).sort(
    (a, b) => b.startedAt - a.startedAt,
  );
  const repo = new InvestigationNoteRepository(db());
  const notes = await repo.listForCase(caseId);

  const state = st(container);
  if (state.caseId !== caseId) {
    state.caseId = caseId;
    state.roomFilter = "general";
    state.kind = "note";
    state.selectedId = null;
    state.creating = false;
  }
  if (state.roomFilter !== "general" && !rooms.some((room) => room.id === state.roomFilter)) {
    state.roomFilter = "general";
  }

  const roomNotes = notes.filter((note) =>
    state.roomFilter === "general" ? note.roomId === null : note.roomId === state.roomFilter,
  );
  const filtered = roomNotes.filter((note) => note.kind === state.kind);
  const selected = state.creating
    ? undefined
    : filtered.find((note) => note.id === state.selectedId) ?? filtered[0];
  state.selectedId = state.creating ? null : selected?.id ?? null;

  const kindCount = (kind: InvestigationNoteKind) =>
    roomNotes.filter((note) => note.kind === kind).length;

  const grouped = GROUP_ORDER.map((label) => ({
    label,
    notes: filtered.filter((note) => recencyLabel(note.updatedAt) === label),
  })).filter((group) => group.notes.length > 0);

  // Draft restoration is keyed by data-focus-id. Scoping every editor field to
  // the selected note prevents an empty "new note" draft (or another note's
  // draft) from overwriting the values loaded from the selected record.
  const editorKey = selected?.id ?? "new";
  const selectedRoomValue = selected?.roomId ?? (state.roomFilter === "general" ? "" : state.roomFilter);
  const roomOptions = [
    `<option value=""${selectedRoomValue === "" ? " selected" : ""}>General investigator notes</option>`,
    ...rooms.map(
      (room) =>
        `<option value="${esc(room.id)}"${selectedRoomValue === room.id ? " selected" : ""}>${esc(room.name)}${room.archived ? " (archived)" : ""}</option>`,
    ),
  ];
  if (selectedRoomValue && !rooms.some((room) => room.id === selectedRoomValue)) {
    roomOptions.push(
      `<option value="${esc(selectedRoomValue)}" selected>Room unavailable (${esc(selectedRoomValue)})</option>`,
    );
  }

  const sessionOptions = [
    `<option value="">No session association</option>`,
    ...sessions.map(
      (session: InvestigationSessionRecord) =>
        `<option value="${esc(session.id)}"${selected?.sessionId === session.id ? " selected" : ""}>${esc(session.status)} — ${esc(fmtTime(session.startedAt))}</option>`,
    ),
  ];
  if (selected?.sessionId && !sessions.some((session) => session.id === selected.sessionId)) {
    sessionOptions.push(
      `<option value="${esc(selected.sessionId)}" selected>Session unavailable (${esc(selected.sessionId)})</option>`,
    );
  }

  const listHtml = grouped.length
    ? grouped
        .map(
          (group) => `
        <div class="notes-group">
          <h4 class="notes-group-title">${esc(group.label)}</h4>
          ${group.notes
            .map(
              (note) => `
            <button class="notes-row${note.id === selected?.id ? " active" : ""}" type="button"
              data-note-select="${esc(note.id)}" aria-pressed="${note.id === selected?.id}">
              <span class="notes-row-title">${esc(note.title || NOTE_KIND_LABELS[note.kind])}</span>
              <span class="notes-row-meta">${esc(NOTE_KIND_LABELS[note.kind])} · ${esc(roomLabel(rooms, note.roomId))} · ${esc(fmtTime(note.updatedAt))}</span>
              <span class="notes-row-preview">${esc(note.body.trim().slice(0, 120) || "No text yet")}</span>
            </button>`,
            )
            .join("")}
        </div>`,
        )
        .join("")
    : notes.length === 0
      ? `<div class="cc-empty" data-notes-empty="none">No investigation notes have been recorded for this case. Create the first note for this room and type.</div>`
      : `<div class="cc-empty" data-notes-empty="filtered">No notes match this room and note type. Choose a different room or type, or create a note here.</div>`;

  invalidateView(container);
  mountView(
    container,
    viewShell(
      `Investigator Notes — ${record.caseNumber}`,
      `
      <div class="case-form notes-workspace" data-root="investigation-notes" data-case-id="${esc(caseId)}" data-epoch="${Date.now()}-${Math.random()}">
        <p class="cc-meta">
          Investigator-authored notes for this case. A note of kind <strong>Observation</strong> is still text written by an investigator —
          it is not an <code>ObservationRecord</code>, evidence, a claim, or a verified finding. Notes never change evidence review,
          readiness, checklist state or investigation completion.
        </p>

        <div class="notes-toolbar">
          <label class="cc-inline-label" for="notes-room-filter">Room</label>
          <select id="notes-room-filter" data-notes-room-filter aria-label="Filter notes by room">
            <option value="general"${state.roomFilter === "general" ? " selected" : ""}>General investigator notes</option>
            ${rooms
              .map(
                (room) =>
                  `<option value="${esc(room.id)}"${state.roomFilter === room.id ? " selected" : ""}>${esc(room.name)}${room.archived ? " (archived)" : ""}</option>`,
              )
              .join("")}
          </select>
          <div class="notes-kind-tabs" role="tablist" aria-label="Note type">
            ${NOTE_KINDS.map(
              (kind) => `
              <button class="back-button notes-kind-tab${state.kind === kind ? " active" : ""}" type="button"
                role="tab" aria-selected="${state.kind === kind}"
                data-note-kind-filter="${kind}">
                ${esc(NOTE_KIND_LABELS[kind])} <span class="notes-kind-count" data-note-kind-count="${kind}">${kindCount(kind)}</span>
              </button>`,
            ).join("")}
          </div>
          <button class="button-primary" id="notes-new" type="button">New Note</button>
        </div>

        <div class="notes-layout">
          <div class="notes-list" data-notes-list>${listHtml}</div>

          <div class="notes-editor" data-notes-editor data-editing-id="${esc(selected?.id ?? "")}">
            <h3 class="cc-section-title">${selected ? "Edit note" : "New note"}</h3>
            <p class="cc-meta" id="notes-editor-meta" data-notes-editor-meta>
              ${
                selected
                  ? `Created ${esc(fmtTime(selected.createdAt))} · Updated ${esc(fmtTime(selected.updatedAt))} · Recorded by ${esc(selected.author || "not recorded")}`
                  : "Not saved yet. Creation and modification times are recorded by the database."
              }
            </p>

            <div class="detail-grid">
              <div class="detail-field">
                <label for="note-kind">Note kind</label>
                <select id="note-kind" data-note-kind data-focus-id="note-kind:${editorKey}">
                  ${NOTE_KINDS.map(
                    (kind) =>
                      `<option value="${kind}"${(selected?.kind ?? state.kind) === kind ? " selected" : ""}>${esc(NOTE_KIND_LABELS[kind])}</option>`,
                  ).join("")}
                </select>
                <div class="case-meta">Original kinds: Note, Observation, Photo Flag.</div>
              </div>
              <div class="detail-field">
                <label for="note-room">Room</label>
                <select id="note-room" data-note-room data-focus-id="note-room:${editorKey}">${roomOptions.join("")}</select>
              </div>
              <div class="detail-field">
                <label for="note-session">Investigation session (optional)</label>
                <select id="note-session" data-note-session data-focus-id="note-session:${editorKey}">${sessionOptions.join("")}</select>
              </div>
              <div class="detail-field">
                <label for="note-author">Recorded by (optional)</label>
                <input id="note-author" data-note-author data-focus-id="note-author:${editorKey}" type="text" value="${esc(selected?.author ?? "")}" placeholder="Leave blank if no attribution is recorded">
                <div class="case-meta">Leave blank rather than guessing. “Not recorded” is shown until an attribution is entered.</div>
              </div>
            </div>

            <div class="detail-field">
              <label for="note-title">Title</label>
              <input id="note-title" data-note-title data-focus-id="note-title:${editorKey}" type="text" value="${esc(selected?.title ?? "")}" placeholder="e.g. Landing — unexplained knock sequence">
            </div>
            <div class="detail-field">
              <label for="note-body">Note body</label>
              <textarea id="note-body" data-note-body data-focus-id="note-body:${editorKey}" rows="10" placeholder="Record what was written, heard, observed or discussed — without turning it into a conclusion.">${esc(selected?.body ?? "")}</textarea>
            </div>

            <div class="form-actions">
              <button class="button-primary" id="notes-save" type="button">${selected ? "Save Note" : "Create Note"}</button>
              <span class="cc-meta" id="notes-status" data-notes-status role="status"></span>
            </div>
            <p class="cc-meta">Editing preserves the original creation time. Notes are stored locally in this browser profile and survive reload/offline use.</p>
          </div>
        </div>

        <div class="form-actions">
          <button class="back-button" id="notes-back" type="button">← Back to Case Hub</button>
        </div>
      </div>
    `,
    ),
  );

  wireBackButton(container);

  onDelegate(container, "click", "#notes-back", () => {
    void renderCaseHub(container, caseId);
  });

  onDelegate(container, "change", "[data-notes-room-filter]", (el) => {
    state.roomFilter = (el as HTMLSelectElement).value || "general";
    state.selectedId = null;
    state.creating = false;
    void renderInvestigationNotes(container, caseId);
  });

  onDelegate(container, "click", "[data-note-kind-filter]", (el) => {
    const kind = el.dataset.noteKindFilter ?? "note";
    if (!NOTE_KINDS.includes(kind as InvestigationNoteKind)) return;
    state.kind = kind as InvestigationNoteKind;
    state.selectedId = null;
    state.creating = false;
    void renderInvestigationNotes(container, caseId);
  });

  onDelegate(container, "click", "[data-note-select]", (el) => {
    state.selectedId = el.dataset.noteSelect ?? null;
    state.creating = false;
    void renderInvestigationNotes(container, caseId);
  });

  onDelegate(container, "click", "#notes-new", () => {
    state.creating = true;
    state.selectedId = null;
    void renderInvestigationNotes(container, caseId);
  });

  onDelegate(container, "click", "#notes-save", async (button) => {
    const read = (selector: string) =>
      container.querySelector<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>(selector)?.value ?? "";
    const kind = read("#note-kind") as InvestigationNoteKind;
    const roomId = read("#note-room") || null;
    const sessionId = read("#note-session") || null;
    const title = read("#note-title");
    const body = read("#note-body");
    const author = read("#note-author");
    const status = container.querySelector<HTMLElement>("#notes-status");
    const btn = button as HTMLButtonElement;

    if (status) {
      status.textContent = "";
      status.dataset.state = "";
    }
    if (!title.trim() && !body.trim()) {
      if (status) {
        status.textContent = "A note needs a title or body text.";
        status.dataset.state = "error";
      }
      return;
    }

    btn.disabled = true;
    try {
      if (selected && !state.creating) {
        const saved = await repo.update(caseId, selected.id, {
          kind,
          roomId,
          sessionId,
          title,
          body,
          author,
        });
        state.selectedId = saved.id;
      } else {
        const created = await repo.create({
          caseId,
          kind,
          roomId,
          sessionId,
          title,
          body,
          author,
        });
        state.selectedId = created.id;
      }
      state.creating = false;
      // Keep the saved note visible: the original room/kind pickers move the
      // sidebar to the note's own section after a save.
      state.kind = kind;
      state.roomFilter = roomId ?? "general";
      // The committed record is now authoritative; drop uncommitted drafts so
      // the re-render shows exactly what was stored.
      clearDrafts(container);
      await renderInvestigationNotes(container, caseId);
      toast("Note saved.");
    } catch (err) {
      btn.disabled = false;
      if (status) {
        status.textContent = (err as Error).message;
        status.dataset.state = "error";
      }
    }
  });
}
