/**
 * Application entry point.
 * Boots the PWA shell, mounts the dashboard (design reference:
 * iOS HomeDashboardView), and wires connectivity + service worker.
 *
 * Route mounting contract: see `app/viewHost.ts`. Each navigation renders into
 * a fresh host; the host is attached only when its render succeeded and its
 * navigation is still current. Late async work can only reach detached DOM.
 */
import "./styles/theme.css";
import { caseIdFromRoute, navigate, onRouteChange, routeQuery, type RouteName } from "./app/router";
import { attachRouteHost, createRouteHost } from "./app/viewHost";
import { renderDashboard, renderEquipment, renderForensic, renderWeather, renderMystic } from "./features/dashboard/views";
import { renderCommandCenterV2 } from "./features/commandcenter/CommandCenter";
import { renderCaseHub } from "./features/casehub/CaseHub";
import { mountMystic } from "./features/mystic/mystic";
import { bindFieldCaptureVisibility } from "./features/equipment/FieldCapture";

/** Release per-tool resources (microphone, object URLs) on route change. */
async function releaseToolResources(container: HTMLElement): Promise<void> {
  try {
    const { releaseEvpRecorder } = await import("./features/equipment/EvpRecorder");
    await releaseEvpRecorder();
  } catch {
    /* recorder module not loaded — nothing to release */
  }
  try {
    const { releaseFieldCapture } = await import("./features/equipment/FieldCapture");
    await releaseFieldCapture();
  } catch {
    /* field-capture module not loaded — nothing to release */
  }
  try {
    const { releaseAudioAnalysisUrls } = await import("./features/forensic/AudioAnalysis");
    releaseAudioAnalysisUrls(container);
  } catch {
    /* analysis module not loaded */
  }
}
import { logBuildIdentity } from "./core/devInfo";

const app = document.querySelector<HTMLElement>("#app")!;
if (!app) throw new Error("#app mount point missing");

function offlineBanner(): string {
  return `<div class="offline-banner" role="status">Offline mode — all data stays on this device.</div>`;
}

function setActiveRoute(route: RouteName): void {
  app.dataset.route = route;
}

/** `redirected` renders are superseded by the navigation they triggered. */
type RenderOutcome = "rendered" | "redirected";

async function render(route: RouteName, host: HTMLElement): Promise<RenderOutcome> {
  setActiveRoute(route);
  // Release audio/object resources from the previous tool before switching, so
  // a recording session or preview URL can never leak across routes.
  await releaseToolResources(app);
  switch (route) {
    case "dashboard":
      await renderDashboard(host);
      return "rendered";
    case "command-center": {
      // Legacy deep link (`...detail=case`) is redirected to the canonical
      // case-scoped Case Hub route instead of a second case-detail surface.
      const legacy = hashDetail();
      if (legacy) {
        const legacyCase = routeQuery().get("case");
        if (legacyCase) {
          navigate("casehub", { case: legacyCase });
          return "redirected";
        }
      }
      renderCommandCenterV2(host);
      return "rendered";
    }
    case "casehub": {
      const caseId = caseIdFromRoute();
      if (!caseId) {
        navigate("command-center");
        return "redirected";
      }
      await renderCaseHub(host, caseId, () => navigate("command-center"));
      return "rendered";
    }
    case "equipment":
      renderEquipment(host);
      return "rendered";
    case "forensic":
      renderForensic(host);
      return "rendered";
    case "weather":
      renderWeather(host);
      return "rendered";
    case "mystic":
      renderMystic(host);
      return "rendered";
  }
}

// Identify the running build in every browser console (TPI-V2-WEB-009C §20) so
// a stale build can never be mistaken for a code defect.
logBuildIdentity();

// Mystic floats above the routed views and is mounted exactly once so view
// re-renders can never destroy it or a typed draft (TPI-V2-WEB-009B §14).
mountMystic();
bindFieldCaptureVisibility();

function updateConnectivity(): void {
  document.body.classList.toggle("is-offline", !navigator.onLine);
}

window.addEventListener("online", updateConnectivity);
window.addEventListener("offline", updateConnectivity);
updateConnectivity();

if ("serviceWorker" in navigator) {
  window.addEventListener("load", () => {
    navigator.serviceWorker.register("/sw.js").catch((err: unknown) => {
      console.warn("Service worker registration failed", err);
    });
  });
}

function hashDetail(): boolean {
  return location.hash.includes("detail=case");
}

/**
 * Route renders are serialized and stale ones are dropped (TPI-V2-WEB-014B §2;
 * hardened in TPI-V2-WEB-C1H). Each navigation owns a fresh host: a render that
 * completes after a newer navigation never attaches, and a render that changes
 * the route (legacy redirect) leaves the current screen in place until the
 * destination render arrives.
 */
let routeRenderTicket = 0;
let routeRenderQueue: Promise<void> = Promise.resolve();

function scheduleRouteRender(route: RouteName): void {
  const ticket = ++routeRenderTicket;
  const host = createRouteHost(route);
  routeRenderQueue = routeRenderQueue
    .then(async () => {
      // Superseded before it started — never render a stale route.
      if (ticket !== routeRenderTicket) return;
      const outcome = await render(route, host);
      // Attach only the newest successful render. A superseded host is dropped
      // with its DOM and any late async continuations aiming at it.
      if (outcome === "rendered" && ticket === routeRenderTicket) attachRouteHost(app, host);
    })
    .catch((error: unknown) => {
      console.error("TPI route render failed", error);
    });
}

onRouteChange((route) => scheduleRouteRender(route));

export { offlineBanner };
