/**
 * Dedicated browser adaptation of EquipmentEMFView.swift.
 *
 * The layout remains instrument-specific, but browser capability is explicit:
 * no calibrated magnetometer value is shown or simulated. Manual external
 * meter logging reuses the existing SessionView/MeasurementService path.
 */
import "../dashboard/dashboard.css";
import { getDb } from "../../core/db";
import { CaseRepository } from "../../core/repositories/caseRepository";
import { SessionService } from "../../core/session/sessionService";
import { esc, viewShell } from "../dashboard/shell";
import { mountView, onDelegate } from "../../shared/uidom";
import { navigate } from "../../app/router";
import { renderSessionView } from "../casehub/SessionView";

interface EmfUiState {
  caseId: string | null;
  roomId: string | null;
}

const db = () => getDb();
const ui = new WeakMap<HTMLElement, EmfUiState>();

function state(container: HTMLElement): EmfUiState {
  const existing = ui.get(container);
  if (existing) return existing;
  const created = { caseId: null, roomId: null };
  ui.set(container, created);
  return created;
}

export async function renderMagneticFieldReference(container: HTMLElement): Promise<void> {
  const s = state(container);
  const cases = await new CaseRepository(db()).listCases(200);
  const activeCases = cases.filter((record) => record.status !== "archived");
  if (!s.caseId || !activeCases.some((record) => record.id === s.caseId)) s.caseId = activeCases[0]?.id ?? null;

  const selectedCase = s.caseId ? activeCases.find((record) => record.id === s.caseId) : undefined;
  const structure = selectedCase
    ? await db().propertyStructures.where("caseId").equals(selectedCase.id).first()
    : undefined;
  const rooms = structure
    ? (await db().structureRooms.where("structureId").equals(structure.id).toArray()).filter((room) => !room.archived)
    : [];
  if (!s.roomId || !rooms.some((room) => room.id === s.roomId)) s.roomId = rooms[0]?.id ?? null;
  const selectedRoom = rooms.find((room) => room.id === s.roomId);
  const activeSession = selectedCase ? await new SessionService(db()).activeSession(selectedCase.id) : undefined;

  mountView(container, viewShell("Magnetic Field Reference", `
    <div class="case-form emf-reference" data-root="magnetic-field-reference">
      <section class="instrument-header-card">
        <div class="instrument-kicker">MAGNETIC FIELD REFERENCE</div>
        <div class="instrument-subtitle">Device Magnetometer - Reference Only</div>
      </section>

      <section class="instrument-lock-card">
        <span class="instrument-lock-icon" aria-hidden="true">▣</span>
        <strong>Active Case Locked: ${esc(selectedCase?.caseNumber ?? "No case selected")}</strong>
      </section>

      <section class="instrument-note-card">
        <strong>Accuracy Note</strong>
        <span>Calibrated for local change detection and trend logging. Confirm absolute values with a dedicated EMF meter.</span>
      </section>

      <section class="instrument-panel instrument-meter-panel">
        <div class="instrument-gauge instrument-gauge-unsupported" role="img" aria-label="Magnetometer unavailable in browser">
          <div class="instrument-gauge-inner"><span>—</span><small>UNAVAILABLE</small></div>
        </div>
        <div class="instrument-reading">— µT</div>
        <div class="instrument-baseline">Baseline: — µT</div>
        <div class="instrument-delta">Δ — µT</div>
        <span class="status-badge error">POWER OFF · BROWSER UNSUPPORTED</span>
        <p class="instrument-status">No calibrated browser magnetometer is available. Live readings are not generated.</p>
      </section>

      <section class="instrument-panel">
        <h3>Controls</h3>
        <div class="form-actions">
          <button class="button-primary" id="emf-power" type="button" disabled title="No calibrated browser magnetometer is available">Power On</button>
          <button class="button-secondary" id="emf-baseline" type="button" disabled title="A live reading is required">Set Baseline</button>
        </div>
        <label class="cc-count instrument-toggle"><input id="emf-auto-baseline" type="checkbox" disabled> Auto-set baseline on power on</label>
        <p class="cc-meta">Power controls remain visible to preserve the original instrument hierarchy. They are disabled rather than simulated.</p>
      </section>

      <section class="instrument-panel">
        <h3>Baseline Context</h3>
        <div class="detail-grid">
          <div class="detail-field"><label for="emf-case">Active case</label>
            <select id="emf-case">${activeCases.length === 0 ? '<option value="">— no active cases —</option>' : activeCases.map((record) => `<option value="${esc(record.id)}"${record.id === s.caseId ? " selected" : ""}>${esc(record.caseNumber)} — ${esc(record.title)}</option>`).join("")}</select></div>
          <div class="detail-field"><label for="emf-room">Room</label>
            <select id="emf-room"><option value="">Unassigned</option>${rooms.map((room) => `<option value="${esc(room.id)}"${room.id === s.roomId ? " selected" : ""}>${esc(room.name)}</option>`).join("")}</select></div>
        </div>
        <div class="instrument-context-grid">
          <span>Investigation phase<strong>${esc(selectedCase?.currentPhase ?? "No active case")}</strong></span>
          <span>Session state<strong>${esc(activeSession?.status ?? "No active session")}</strong></span>
          <span>Selected room<strong>${esc(selectedRoom?.name ?? "Unassigned")}</strong></span>
        </div>
        <p class="cc-meta">Manual readings retain the selected case, room, session, instrument identity and provenance through the existing measurement ledger.</p>
        <div class="form-actions"><button class="button-secondary" id="emf-manual-log" type="button" ${selectedCase ? "" : "disabled"}>Open Manual EMF Logging</button></div>
      </section>

      <div class="form-actions"><button class="back-button" id="emf-back" type="button">← Back to Equipment</button></div>
    </div>`,));

  onDelegate(container, "change", "#emf-case", (element) => {
    s.caseId = (element as HTMLSelectElement).value || null;
    s.roomId = null;
    void renderMagneticFieldReference(container);
  });
  onDelegate(container, "change", "#emf-room", (element) => {
    s.roomId = (element as HTMLSelectElement).value || null;
    void renderMagneticFieldReference(container);
  });
  onDelegate(container, "click", "#emf-manual-log", () => {
    if (s.caseId) void renderSessionView(container, s.caseId, { focusMeasurement: "emf", focusRoomId: s.roomId, backToEquipment: true });
  });
  onDelegate(container, "click", "#emf-back", () => navigate("equipment"));
}
