export function esc(text: string): string {
  return text.replace(/[&<>"']/g, (c) => {
    switch (c) {
      case "&": return "&amp;";
      case "<": return "&lt;";
      case ">": return "&gt;";
      case '"': return "&quot;";
      default: return "&#39;";
    }
  });
}

export function panelHtml(panel: (typeof PANELS)[number]): string {
  const iconKey: Record<string, string> = {
    folder: "folder",
    signal: "radio",
    waveform: "ecg",
    weather: "weather",
  };
  const icon = iconKey[panel.icon] ?? "folder";
  return `
    <button class="panel" data-route="${panel.route}" type="button">
      <span class="panel-head">
        <span class="panel-icon"><svg viewBox="0 0 24 24" aria-hidden="true">${DASH_ICONS[icon]}</svg></span>
        <span class="panel-title">${panel.title}</span>
        <svg class="panel-chevron" viewBox="0 0 24 24" aria-hidden="true"><path d="M9 5l7 7-7 7"/></svg>
      </span>
      <p class="primary-line">${panel.primary}</p>
      <p class="secondary-line">${panel.secondary}</p>
      <p class="footer-line">${panel.footer}</p>
    </button>`;
}

