export function viewShell(title: string, body: string): string {
  return `
    <div class="view">
      <div class="view-header">
        <button class="back-button" data-action="back" type="button">‹ Dashboard</button>
        <h2>${esc(title)}</h2>
      </div>
      ${body}
    </div>`;
}

export function wirePanels(scope: Element): void {
  scope.querySelectorAll<HTMLElement>("[data-route]").forEach((el) => {
    el.addEventListener("click", () => navigate(el.dataset.route as RouteName));
  });
}

export function wireBackButton(scope: Element): void {
  scope.querySelector<HTMLButtonElement>("[data-action='back']")?.addEventListener("click", () => {
    navigate("dashboard");
  });
}

export function offlineBanner(): string {
  return `<div class="offline-banner" role="status">Offline mode — all data stays on this device.</div>`;
}
