/**
 * TPI-V2-WEB-020 — case closure surface inside Investigation Summary.
 *
 * Closure is presented separately from report finalization. It is available
 * only when the case is open and one current finalized report revision exists.
 * Reopening and subsequent closure preserve every earlier closure row.
 */
import "./report.css";
import { esc } from "../dashboard/shell";
import { onDelegate } from "../../shared/uidom";
import type {
  CaseClosureRecord,
  CaseReportRecord,
  CaseReportRevisionRecord,
} from "../../core/types";
import type { CaseClosureState, CaseClosureService } from "../../core/reporting/caseClosureService";
import { CLOSURE_ACKNOWLEDGEMENT } from "../../core/reporting/reportPrivacy";
import { REPORT_TYPE_SHORT_LABELS } from "../../core/reporting/reportDraft";

function fmt(ms: number | null): string {
  return ms ? new Date(ms).toLocaleString() : "—";
}

interface ClosableRevision {
  report: CaseReportRecord;
  revision: CaseReportRevisionRecord;
}

function closableRevisions(
  reports: readonly CaseReportRecord[],
  revisionsByReport: Readonly<Record<string, readonly CaseReportRevisionRecord[]>>,
): ClosableRevision[] {
  return reports.flatMap((report) => {
    if (report.status !== "final" || !report.currentRevisionId) return [];
    const revision = (revisionsByReport[report.id] ?? []).find(
      (candidate) => candidate.id === report.currentRevisionId,
    );
    return revision ? [{ report, revision }] : [];
  });
}

function closureHistory(history: readonly CaseClosureRecord[]): string {
  return `<details class="report-history" data-closure-history ${history.length ? "" : "open"}>
    <summary>Closure history (${history.length})</summary>
    ${history.length
      ? `<div class="report-table-wrap"><table class="report-table">
          <thead><tr><th>Closure</th><th>Responsible investigator</th><th>Referenced revision</th><th>Reopened</th></tr></thead>
          <tbody>${history
            .map(
              (closure) => `<tr data-closure-record="${esc(closure.id)}" data-closure-reopened="${closure.reopenedAt !== null}">
                <td>${esc(fmt(closure.closedAt))}${closure.legacy ? `<br><span class="report-source">Legacy closure</span>` : ""}${closure.notes ? `<br><span class="report-source">${esc(closure.notes)}</span>` : ""}</td>
                <td>${esc(closure.closedBy)}</td>
                <td>${closure.reportRevisionId ? `Revision ${closure.reportRevisionNumber ?? "?"}` : `<span class="report-missing">Not recorded</span>`}</td>
                <td>${closure.reopenedAt ? `${esc(fmt(closure.reopenedAt))}<br><span class="report-source">${esc(closure.reopenedBy ?? "Not recorded")}</span>` : `<span class="report-badge report-badge-ok">Current closure</span>`}</td>
              </tr>`,
            )
            .join("")}</tbody>
        </table></div>`
      : `<p class="report-missing">No closure history is recorded for this case.</p>`}
  </details>`;
}

export function caseClosureHtml(
  state: CaseClosureState | undefined,
  reports: readonly CaseReportRecord[],
  revisionsByReport: Readonly<Record<string, readonly CaseReportRevisionRecord[]>>,
): string {
  if (!state) return "";
  const { record, closure, history } = state;
  const closed = record.isClosed;
  const options = closableRevisions(reports, revisionsByReport);
  const statusLabel = closed
    ? closure
      ? "Closed Investigation"
      : "Closed Investigation (legacy closure record)"
    : history.some((item) => item.reopenedAt !== null)
      ? "Reopened Investigation"
      : "Open Investigation";

  const closeArea = closed
    ? `<div class="report-closure-state" data-closure-current>
        <p class="report-meta"><strong>${esc(statusLabel)}.</strong> ${closure ? `Closed ${esc(fmt(closure.closedAt))} by ${esc(closure.closedBy)}.` : `The case is closed from a pre-WEB-020 closure; no historical report revision was recorded.`}</p>
        ${closure?.reportRevisionId ? `<p class="report-source" data-closure-revision>Referenced revision ${closure.reportRevisionNumber ?? "?"} · ${esc(closure.reportId ?? "")}</p>` : ""}
        ${closure?.notes ? `<p class="report-copy">${esc(closure.notes)}</p>` : ""}
        <div class="report-draft-actions">
          <button class="button-secondary" type="button" data-closure-reopen-toggle>Reopen Investigation</button>
        </div>
        <div class="report-closure-form" data-closure-reopen-form hidden>
          <h4>Reopen investigation</h4>
          <p class="report-note">Reopening preserves this closure record and its report revision. It does not edit the finalized report.</p>
          <label class="report-field">
            <span>Responsible investigator</span>
            <input data-closure-reopen-by data-focus-id="closure-reopen-by" placeholder="Investigator reopening the case" />
          </label>
          <label class="report-field">
            <span>Reason for reopening</span>
            <textarea data-closure-reopen-reason data-focus-id="closure-reopen-reason" rows="3" placeholder="New witness information, new evidence, required correction, or additional investigation."></textarea>
          </label>
          <label class="report-check">
            <input type="checkbox" data-closure-reopen-confirm />
            <span>I intentionally reopen this investigation. The original closure remains in history.</span>
          </label>
          <div class="report-draft-actions">
            <button class="button-primary" type="button" data-closure-reopen>Reopen investigation</button>
            <button class="button-secondary" type="button" data-closure-reopen-cancel>Cancel</button>
          </div>
        </div>
      </div>`
    : options.length
      ? `<div class="report-closure-state" data-closure-open-state>
          <p class="report-meta"><strong>${esc(statusLabel)}.</strong> Formal closure is separate from report finalization and archiving.</p>
          <div class="report-draft-actions">
            <button class="button-secondary" type="button" data-closure-open-toggle>Close Investigation</button>
          </div>
          <div class="report-closure-form" data-closure-form hidden>
            <h4>Close investigation</h4>
            <p class="report-note">The closure record will reference one current finalized report revision. Closing will not archive the case, delete evidence or change any report revision.</p>
            <label class="report-field">
              <span>Finalized report revision</span>
              <select data-closure-report data-focus-id="closure-report">
                ${options
                  .map(
                    ({ report, revision }) =>
                      `<option value="${esc(report.id)}|${esc(revision.id)}">${esc(REPORT_TYPE_SHORT_LABELS[report.reportType])} — revision ${revision.revisionNumber} — ${esc(report.title)}</option>`,
                  )
                  .join("")}
              </select>
            </label>
            <label class="report-field">
              <span>Responsible investigator</span>
              <input data-closure-by data-focus-id="closure-by" placeholder="Investigator responsible for closure" />
            </label>
            <label class="report-field">
              <span>Closure notes <small>(optional)</small></span>
              <textarea data-closure-notes data-focus-id="closure-notes" rows="3" placeholder="Optional closure context. Do not add evidence or conclusions that are not in the records."></textarea>
            </label>
            <label class="report-check">
              <input type="checkbox" data-closure-confirm />
              <span>${esc(CLOSURE_ACKNOWLEDGEMENT)}</span>
            </label>
            <div class="report-draft-actions">
              <button class="button-primary" type="button" data-closure-close>Close investigation</button>
              <button class="button-secondary" type="button" data-closure-cancel>Cancel</button>
            </div>
          </div>
        </div>`
      : `<div class="report-closure-state" data-closure-blocked>
          <p class="report-meta"><strong>${esc(statusLabel)}.</strong> Formal closure requires an existing finalized report revision. No finalized report currently exists for this case.</p>
          <p class="report-note">You may continue investigating, create a report, or finalize a report first. No closure or archive was performed.</p>
        </div>`;

  return `<section class="case-report case-closure-workspace" data-closure-workspace data-closure-state="${closed ? "closed" : "open"}">
    <header class="report-header">
      <div>
        <p class="report-kicker">Case lifecycle · explicit investigator action</p>
        <h2>Case Closure</h2>
        <p class="report-meta">${esc(statusLabel)}. Report finalization does not close the case. Closure does not auto-archive, export a package, delete evidence or alter revisions.</p>
      </div>
    </header>
    <p class="report-draft-status" data-closure-status role="status"></p>
    ${closeArea}
    ${closureHistory(history)}
  </section>`;
}

function selectedPair(panel: HTMLElement): { reportId: string; revisionId: string } | null {
  const value = panel.querySelector<HTMLSelectElement>("[data-closure-report]")?.value ?? "";
  const [reportId, revisionId] = value.split("|");
  return reportId && revisionId ? { reportId, revisionId } : null;
}

function setClosureStatus(container: HTMLElement, message: string): void {
  const status = container.querySelector<HTMLElement>("[data-closure-status]");
  if (status) status.textContent = message;
}

export function wireCaseClosure(
  container: HTMLElement,
  options: {
    caseId: string;
    service: CaseClosureService;
    rerender: () => Promise<void>;
  },
): void {
  const { caseId, service, rerender } = options;

  onDelegate(container, "click", "[data-closure-open-toggle]", (button) => {
    const form = button.closest<HTMLElement>("[data-closure-open-state]")?.querySelector<HTMLElement>("[data-closure-form]");
    if (!form) return;
    form.hidden = !form.hidden;
    if (!form.hidden) form.querySelector<HTMLElement>("[data-closure-by]")?.focus();
  });

  onDelegate(container, "click", "[data-closure-cancel]", (button) => {
    const form = button.closest<HTMLElement>("[data-closure-form]");
    if (form) form.hidden = true;
  });

  onDelegate(container, "click", "[data-closure-reopen-toggle]", (button) => {
    const form = button.closest<HTMLElement>("[data-closure-current]")?.querySelector<HTMLElement>("[data-closure-reopen-form]");
    if (!form) return;
    form.hidden = !form.hidden;
    if (!form.hidden) form.querySelector<HTMLElement>("[data-closure-reopen-by]")?.focus();
  });

  onDelegate(container, "click", "[data-closure-reopen-cancel]", (button) => {
    const form = button.closest<HTMLElement>("[data-closure-reopen-form]");
    if (form) form.hidden = true;
  });

  onDelegate(container, "click", "[data-closure-close]", (button) => {
    const scope = button.closest<HTMLElement>("[data-closure-open-state]");
    if (!scope) return;
    const selected = selectedPair(scope);
    const closedBy = scope.querySelector<HTMLInputElement>("[data-closure-by]")?.value.trim() ?? "";
    const notes = scope.querySelector<HTMLTextAreaElement>("[data-closure-notes]")?.value ?? "";
    const confirmed = scope.querySelector<HTMLInputElement>("[data-closure-confirm]")?.checked ?? false;
    if (!selected) {
      setClosureStatus(container, "Select a finalized report revision.");
      return;
    }
    if (!closedBy) {
      setClosureStatus(container, "A responsible investigator name is required.");
      return;
    }
    if (!confirmed) {
      setClosureStatus(container, "Confirm the closure acknowledgement.");
      return;
    }
    button.setAttribute("disabled", "true");
    void (async () => {
      try {
        await service.closeCase({
          caseId,
          reportId: selected.reportId,
          reportRevisionId: selected.revisionId,
          closedBy,
          confirmed,
          acknowledgement: CLOSURE_ACKNOWLEDGEMENT,
          notes,
        });
        await rerender();
        setClosureStatus(
          container,
          "Investigation closed. The case was not archived; evidence and report revisions are unchanged.",
        );
      } catch (error) {
        setClosureStatus(
          container,
          `Could not close investigation: ${error instanceof Error ? error.message : "unknown error"}`,
        );
        button.removeAttribute("disabled");
      }
    })();
  });

  onDelegate(container, "click", "[data-closure-reopen]", (button) => {
    const scope = button.closest<HTMLElement>("[data-closure-reopen-form]");
    if (!scope) return;
    const reopenedBy = scope.querySelector<HTMLInputElement>("[data-closure-reopen-by]")?.value.trim() ?? "";
    const reason = scope.querySelector<HTMLTextAreaElement>("[data-closure-reopen-reason]")?.value.trim() ?? "";
    const confirmed = scope.querySelector<HTMLInputElement>("[data-closure-reopen-confirm]")?.checked ?? false;
    if (!reopenedBy) {
      setClosureStatus(container, "A responsible investigator name is required.");
      return;
    }
    if (!reason) {
      setClosureStatus(container, "A reopening reason is required.");
      return;
    }
    if (!confirmed) {
      setClosureStatus(container, "Confirm the reopening action.");
      return;
    }
    button.setAttribute("disabled", "true");
    void (async () => {
      try {
        await service.reopenCase({ caseId, reopenedBy, reason, confirmed });
        await rerender();
        setClosureStatus(
          container,
          "Investigation reopened. The previous closure record and its report revision remain in history.",
        );
      } catch (error) {
        setClosureStatus(
          container,
          `Could not reopen investigation: ${error instanceof Error ? error.message : "unknown error"}`,
        );
        button.removeAttribute("disabled");
      }
    })();
  });
}
