/**
 * Environmental measurement service (TPI-V2-WEB-008 §8/§9/§11).
 *
 * Every quantitative measurement carries explicit provenance. A manually
 * entered instrument reading is NEVER labelled automatic, and an uncalibrated
 * browser value (e.g. microphone dBFS) is never presented as a calibrated
 * instrument reading.
 *
 * iOS origins: EnvironmentSnapshot (environmental context/fields),
 * ExternalEMFLogView (manual K-II / MEL / Tri-Field meter logging with LED or
 * numeric input), NoiseMonitor (dBFS level), EMFManager (hardware
 * magnetometer — NOT portable; browser uses manual entry only).
 */
import type { TPIDatabase } from "../db";
import { SCHEMA_VERSION } from "../db";
import { v4 as uuidv4 } from "../../shared/uuid";
import type {
  AcquisitionMethod,
  CalibrationStatus,
  EnvironmentMeasurementRecord,
  MeasurementType,
} from "../types";
import { assertRoomBelongsToCase, ValidationError } from "../validation";
import { AuditService } from "../audit";
import type { SessionService } from "../session/sessionService";

/** Canonical unit per measurement type (SI/metric storage, as iOS does). */
export const CANONICAL_UNITS: Record<MeasurementType, string> = {
  temperature: "°C",
  humidity: "% RH",
  pressure: "hPa",
  ambientLight: "lx",
  ambientSound: "dBFS",
  airMovement: "m/s",
  emf: "µT",
  electricalInterference: "index",
  vibration: "index",
  other: "",
};

/** Alternative units accepted on entry, with conversion to the canonical unit. */
export const UNIT_CONVERSIONS: Partial<Record<MeasurementType, Record<string, { toCanonical: (v: number) => number; label: string }>>> = {
  temperature: {
    "°C": { toCanonical: (v) => v, label: "Celsius" },
    "°F": { toCanonical: (v) => (v - 32) / 1.8, label: "Fahrenheit" },
  },
  emf: {
    µT: { toCanonical: (v) => v, label: "Microtesla" },
    mG: { toCanonical: (v) => v / 10, label: "Milligauss (1 mG = 0.1 µT)" },
  },
  airMovement: {
    "m/s": { toCanonical: (v) => v, label: "Metres per second" },
    mph: { toCanonical: (v) => v * 0.44704, label: "Miles per hour" },
  },
};

/** iOS ExternalEMFLogView meter types. */
export const EMF_METER_TYPES = ["K-II", "MEL", "Tri-Field", "Other"] as const;

/** iOS ExternalEMFLogView K-II LED levels: LED state, not a numeric reading. */
export const K2_LED_LEVELS = [
  "1 — first LED",
  "2 — second LED",
  "3 — third LED",
  "4 — fourth LED",
  "5 — fifth LED (highest)",
] as const;

export const MEASUREMENT_TYPE_LABELS: Record<MeasurementType, string> = {
  temperature: "Temperature",
  humidity: "Relative humidity",
  pressure: "Atmospheric pressure",
  ambientLight: "Ambient light",
  ambientSound: "Ambient sound (signal level)",
  airMovement: "Air movement",
  emf: "Electromagnetic field (external meter)",
  electricalInterference: "Electrical interference (qualitative)",
  vibration: "Structural vibration / motion",
  other: "Other",
};

export interface MeasurementInput {
  measurementType: MeasurementType;
  /** Readable value from an external instrument / entered number. */
  value?: number | null;
  /** Entry unit; converted to the canonical unit before storage. */
  unit?: string;
  /** Qualitative observation text (required for `observation` acquisition). */
  text?: string;
  acquisition: AcquisitionMethod;
  instrument?: string;
  calibration?: CalibrationStatus;
  roomId?: string | null;
  sessionId?: string | null;
  baselineRecordId?: string | null;
  sampleWindowId?: string | null;
  notes?: string;
  at?: number;
}

export class MeasurementService {
  private readonly audit: AuditService;

  constructor(
    private readonly db: TPIDatabase,
    private readonly sessions?: SessionService,
  ) {
    this.audit = new AuditService(db);
  }

  /**
   * Record one measurement with full provenance. Numeric values are converted
   * to the canonical unit; the stored unit is always the canonical one, and
   * the entered unit is preserved in the notes metadata for traceability.
   */
  async record(caseId: string, input: MeasurementInput): Promise<EnvironmentMeasurementRecord> {
    const caseRecord = await this.db.cases.get(caseId);
    if (!caseRecord) throw new ValidationError(`Case not found: ${caseId}`, "caseId");
    if (input.sessionId) {
      const session = await this.db.sessions.get(input.sessionId);
      if (!session) throw new ValidationError("Session does not exist.", "sessionId");
      if (session.caseId !== caseId) throw new ValidationError("Session belongs to a different case.", "sessionId");
    }
    if (input.roomId) {
      const room = await this.db.structureRooms.get(input.roomId);
      if (!room) throw new ValidationError("Room does not exist.", "roomId");
      assertRoomBelongsToCase(room, caseId);
    }

    const isObservation = input.acquisition === "observation";
    if (isObservation) {
      if (!input.text?.trim()) throw new ValidationError("An observation requires description text.", "text");
    } else {
      if (input.value === undefined || input.value === null || Number.isNaN(input.value)) {
        throw new ValidationError("A numeric value is required for this acquisition method.", "value");
      }
    }
    // Honesty guard: an automatic acquisition must identify its source, and
    // manual entries must identify the instrument they were read from.
    if (input.acquisition === "manualInstrument" && !input.instrument?.trim()) {
      throw new ValidationError("A manual instrument reading requires the instrument to be identified.", "instrument");
    }
    if (input.acquisition === "automatic" && !input.instrument?.trim()) {
      throw new ValidationError("An automatic measurement must identify its source.", "instrument");
    }

    const canonicalUnit = CANONICAL_UNITS[input.measurementType];
    let storedValue: number | null = null;
    let enteredAs = "";
    if (!isObservation) {
      const enteredUnit = input.unit?.trim() || canonicalUnit;
      const conversion = UNIT_CONVERSIONS[input.measurementType]?.[enteredUnit];
      // The canonical unit is always valid, including measurement types with
      // no conversion table (dBFS, index, percentage humidity, etc.).
      if (!conversion && enteredUnit !== canonicalUnit) {
        const supported = [...new Set([
          canonicalUnit,
          ...Object.keys(UNIT_CONVERSIONS[input.measurementType] ?? {}),
        ])].filter(Boolean);
        throw new ValidationError(
          `Unsupported unit "${enteredUnit}" for ${MEASUREMENT_TYPE_LABELS[input.measurementType]}. Supported: ${supported.join(", ")}`,
          "unit",
        );
      }
      storedValue = round(conversion ? conversion.toCanonical(input.value as number) : (input.value as number), 3);
      if (conversion && enteredUnit !== canonicalUnit) enteredAs = `entered as ${input.value} ${enteredUnit} (converted to ${canonicalUnit})`;
    }

    const ts = Date.now();
    const record: EnvironmentMeasurementRecord = {
      id: uuidv4(),
      schemaVersion: SCHEMA_VERSION,
      caseId,
      sessionId: input.sessionId ?? null,
      roomId: input.roomId ?? null,
      baselineRecordId: input.baselineRecordId ?? null,
      at: input.at ?? ts,
      measurementType: input.measurementType,
      value: storedValue,
      unit: isObservation ? "" : canonicalUnit,
      text: input.text?.trim() ?? "",
      acquisition: input.acquisition,
      instrument: input.instrument?.trim() ?? "",
      calibration: input.calibration ?? "unknown",
      sampleWindowId: input.sampleWindowId ?? null,
      notes: [input.notes?.trim(), enteredAs].filter(Boolean).join(" • "),
      createdAt: ts,
      amendedFromId: null,
      amended: false,
    };
    await this.db.environmentMeasurements.put(record);
    if (input.sessionId && this.sessions) {
      await this.sessions.recordEvent(input.sessionId, "measurementRecorded", `Measurement recorded (${input.measurementType}, ${input.acquisition}).`, {
        source: input.acquisition === "automatic" ? "audioMonitor" : input.acquisition === "manualInstrument" ? "manualInstrument" : "investigator",
        metadata: { measurementType: input.measurementType, acquisition: input.acquisition },
      });
    }
    await this.audit.record("measurementRecorded", `Environmental measurement recorded (${input.measurementType}).`, {
      caseId,
      affectedRecordId: record.id,
      // Values are not audit payloads; type/acquisition are safe.
      metadata: { measurementType: input.measurementType, acquisition: input.acquisition, unit: record.unit },
    });
    return record;
  }

  /** Amendment: the prior record is preserved, never overwritten. */
  async amend(
    measurementId: string,
    update: { value?: number; text?: string; notes?: string; instrument?: string; reason: string },
  ): Promise<EnvironmentMeasurementRecord> {
    if (!update.reason.trim()) throw new ValidationError("An amendment requires a documented reason.", "reason");
    const prior = await this.db.environmentMeasurements.get(measurementId);
    if (!prior) throw new ValidationError(`Measurement not found: ${measurementId}`, "measurementId");
    const ts = Date.now();
    const revised: EnvironmentMeasurementRecord = {
      ...prior,
      id: uuidv4(),
      createdAt: ts,
      value: update.value !== undefined ? round(update.value, 3) : prior.value,
      text: update.text?.trim() ?? prior.text,
      notes: [update.notes?.trim() ?? prior.notes, `amended: ${update.reason}`].filter(Boolean).join(" • "),
      instrument: update.instrument?.trim() ?? prior.instrument,
      amendedFromId: prior.id,
      amended: false,
    };
    await this.db.environmentMeasurements.put(revised);
    await this.db.environmentMeasurements.put({ ...prior, amended: true });
    await this.audit.record("measurementRecorded", `Environmental measurement amended: ${update.reason.slice(0, 160)}`, {
      caseId: prior.caseId,
      affectedRecordId: revised.id,
      metadata: { priorId: prior.id },
    });
    return revised;
  }

  async listForCase(caseId: string): Promise<EnvironmentMeasurementRecord[]> {
    const rows = await this.db.environmentMeasurements.where("caseId").equals(caseId).toArray();
    return rows.sort((a, b) => a.at - b.at);
  }

  async listForRoom(roomId: string): Promise<EnvironmentMeasurementRecord[]> {
    const rows = await this.db.environmentMeasurements.where("roomId").equals(roomId).toArray();
    return rows.sort((a, b) => a.at - b.at);
  }

  /** History query used by the environmental history interface (§13). */
  async query(
    caseId: string,
    filter: { roomId?: string; sessionId?: string; measurementType?: MeasurementType; acquisition?: AcquisitionMethod; includeSuperseded?: boolean } = {},
  ): Promise<EnvironmentMeasurementRecord[]> {
    let rows = await this.listForCase(caseId);
    if (filter.roomId) rows = rows.filter((r) => r.roomId === filter.roomId);
    if (filter.sessionId) rows = rows.filter((r) => r.sessionId === filter.sessionId);
    if (filter.measurementType) rows = rows.filter((r) => r.measurementType === filter.measurementType);
    if (filter.acquisition) rows = rows.filter((r) => r.acquisition === filter.acquisition);
    if (!filter.includeSuperseded) rows = rows.filter((r) => !r.amended);
    return rows;
  }
}

function round(v: number, digits: number): number {
  const f = 10 ** digits;
  return Math.round(v * f) / f;
}
