/**
 * Equipment-to-session bridge.
 * Hardware-limited tools reuse the existing SessionView measurement/audio
 * services; this module does not create sensor readings or a second store.
 */
import { getDb } from "../../core/db";
import { CaseRepository } from "../../core/repositories/caseRepository";
import type { MeasurementType } from "../../core/types";
import { esc, viewShell } from "../dashboard/shell";
import { mountView, onDelegate } from "../../shared/uidom";
import { navigate } from "../../app/router";
import { renderSessionView } from "../casehub/SessionView";

export type EquipmentSessionInstrument = "emf" | "external-emf" | "motion" | "noise";

const PROFILES: Record<EquipmentSessionInstrument, {
  title: string;
  description: string;
  measurementType: MeasurementType;
  limitation: string;
}> = {
  emf: {
    title: "Magnetic Field Reference",
    description: "Record a reading from an identified external EMF meter.",
    measurementType: "emf",
    limitation: "The browser has no calibrated magnetometer. No live EMF value is generated.",
  },
  "external-emf": {
    title: "External EMF Devices",
    description: "Log a K-II, MEL, Tri-Field, or other external meter reading.",
    measurementType: "emf",
    limitation: "External device readings are entered by the investigator; no Bluetooth or USB meter integration is claimed.",
  },
  motion: {
    title: "Motion Sensor",
    description: "Record an investigator observation or an identified external motion instrument reading.",
    measurementType: "vibration",
    limitation: "Calibrated browser motion capture is unavailable. Manual observation remains supported.",
  },
  noise: {
    title: "Noise Detector",
    description: "Open the existing session audio monitor and measurement ledger.",
    measurementType: "ambientSound",
    limitation: "Browser audio is digital dBFS signal level, not calibrated dB SPL.",
  },
};

const db = () => getDb();

export async function renderEquipmentSessionEntry(
  container: HTMLElement,
  instrument: EquipmentSessionInstrument,
): Promise<void> {
  const profile = PROFILES[instrument];
  const records = await new CaseRepository(db()).listCases(200);
  const active = records.filter((record) => record.status !== "archived");

  mountView(container, viewShell(profile.title, `
    <div class="case-form" data-root="equipment-session-entry" data-instrument="${instrument}">
      <p class="primary-line">${esc(profile.description)}</p>
      <p class="cc-meta"><strong>Honest browser status:</strong> ${esc(profile.limitation)}</p>
      <h3 class="cc-section-title">Active Case Context</h3>
      ${active.length === 0
        ? `<div class="cc-empty">No active cases exist. Create a case before logging equipment data.</div>`
        : `<div class="case-list">${active.map((record) => `
          <button class="case-row" data-equipment-case="${esc(record.id)}" type="button">
            <span><strong class="case-title">${esc(record.caseNumber)} — ${esc(record.title)}</strong>
            <span class="case-meta">Open the existing Investigation Session and preserve case/room context.</span></span>
            <span class="status-badge">Open</span>
          </button>`).join("")}</div>`}
      <div class="form-actions"><button class="back-button" id="equipment-entry-back" type="button">← Back to Equipment</button></div>
    </div>`,));

  onDelegate(container, "click", "#equipment-entry-back", () => navigate("equipment"));
  onDelegate(container, "click", "[data-equipment-case]", (element) => {
    const caseId = element.dataset.equipmentCase;
    if (caseId) void renderSessionView(container, caseId, { focusMeasurement: profile.measurementType, backToEquipment: true });
  });
}
