/**
 * Claim repository — the single write path for reported claims (C6A).
 *
 * A claim is a reported statement or investigator mark. It is NOT an evidence
 * record, NOT an observation and NOT a workflow conclusion. This repository
 * never writes evidence, observations, checklist/readiness state, case phases
 * or investigation-completion events.
 */
import type { TPIDatabase } from "../db";
import { now, SCHEMA_VERSION } from "../db";
import { v4 as uuidv4 } from "../../shared/uuid";
import type {
  CaseRecord,
  ClaimClassification,
  ClaimImportSourceType,
  ClaimRecord,
  ClaimWalkthroughStatus,
} from "../types";
import {
  ValidationError,
  assertNonEmpty,
  assertReferenceExists,
  assertTimestampsMonotonic,
} from "../validation";
import { AuditService } from "../audit";

export const CLAIM_CLASSIFICATIONS: readonly ClaimClassification[] = [
  "Client Reported",
  "Witness Reported",
  "Investigator Observed",
];

export const CLAIM_WALKTHROUGH_STATUSES: readonly ClaimWalkthroughStatus[] = [
  "Not Located",
  "Located",
  "Confirmed with Client",
];

const CLAIM_IMPORT_SOURCE_TYPES: readonly ClaimImportSourceType[] = [
  "referenceLocation",
  "manual",
  "external",
];

export interface ClaimCreateInput {
  caseId: string;
  title: string;
  claimID?: string;
  locationId?: string | null;
  roomID?: string | null;
  roomTBD?: boolean;
  roomName?: string;
  subLocation?: string;
  linkedRoomIds?: string[];
  occurrenceLevel?: string;
  claimType?: string;
  claimTypeOtherText?: string;
  firstOccurrenceText?: string;
  mostRecentOccurrenceText?: string;
  frequency?: string;
  timePattern?: string;
  weatherCorrelation?: boolean;
  weatherPattern?: string;
  witnessCount?: number;
  witnessesText?: string;
  witnessCountResolved?: boolean;
  witnessMemberIds?: string[];
  emotionalImpact?: number;
  emotionalImpactResolved?: boolean;
  feelingText?: string;
  feelingNotes?: string;
  classification?: ClaimClassification;
  classificationResolved?: boolean;
  notes?: string;
  linkedPinID?: string | null;
  walkthroughStatus?: ClaimWalkthroughStatus;
  mostRecentOccurrenceKnown?: boolean | null;
  isGuidedDraft?: boolean;
  importedFromReference?: boolean;
  importSourceType?: ClaimImportSourceType | null;
  importSourceRef?: string | null;
  importSourceClaimId?: string | null;
  importIdentity?: string | null;
  importedAt?: number | null;
  sourceText?: string | null;
  sourceTextHash?: string | null;
  sourceOccurrenceText?: string | null;
  sourceOccurrenceAt?: number | null;
}

/**
 * Fields a caller may change after creation. Case ownership, claim identity,
 * creation time and every import/source provenance field are deliberately
 * excluded; they are preserved byte-for-byte by `update`.
 */
export type ClaimUpdateInput = Partial<
  Pick<
    ClaimRecord,
    | "locationId"
    | "roomID"
    | "roomTBD"
    | "roomName"
    | "subLocation"
    | "linkedRoomIds"
    | "title"
    | "occurrenceLevel"
    | "claimType"
    | "claimTypeOtherText"
    | "firstOccurrenceText"
    | "mostRecentOccurrenceText"
    | "frequency"
    | "timePattern"
    | "weatherCorrelation"
    | "weatherPattern"
    | "witnessCount"
    | "witnessesText"
    | "witnessCountResolved"
    | "witnessMemberIds"
    | "emotionalImpact"
    | "emotionalImpactResolved"
    | "feelingText"
    | "feelingNotes"
    | "classification"
    | "classificationResolved"
    | "notes"
    | "linkedPinID"
    | "walkthroughStatus"
    | "mostRecentOccurrenceKnown"
    | "isGuidedDraft"
  >
>;

function assertClassification(value: string): asserts value is ClaimClassification {
  if (!CLAIM_CLASSIFICATIONS.includes(value as ClaimClassification)) {
    throw new ValidationError(
      `Unknown claim classification: ${value}`,
      "classification",
    );
  }
}

function assertWalkthroughStatus(
  value: string,
): asserts value is ClaimWalkthroughStatus {
  if (!CLAIM_WALKTHROUGH_STATUSES.includes(value as ClaimWalkthroughStatus)) {
    throw new ValidationError(
      `Unknown claim walkthrough status: ${value}`,
      "walkthroughStatus",
    );
  }
}

function assertImportSourceType(
  value: string,
): asserts value is ClaimImportSourceType {
  if (!CLAIM_IMPORT_SOURCE_TYPES.includes(value as ClaimImportSourceType)) {
    throw new ValidationError(
      `Unknown claim import source type: ${value}`,
      "importSourceType",
    );
  }
}

function assertCount(value: number, field: string): void {
  if (!Number.isInteger(value) || value < 0) {
    throw new ValidationError(`${field} must be a non-negative integer`, field);
  }
}

function normalizeStringArray(value: string[] | undefined, field: string): string[] {
  if (value === undefined) return [];
  const seen = new Set<string>();
  const result: string[] = [];
  for (const item of value) {
    if (typeof item !== "string" || item.trim().length === 0) {
      throw new ValidationError(`${field} must contain non-empty identifiers`, field);
    }
    const trimmed = item.trim();
    if (!seen.has(trimmed)) {
      seen.add(trimmed);
      result.push(trimmed);
    }
  }
  return result;
}

export class ClaimRepository {
  private readonly audit: AuditService;

  constructor(private readonly db: TPIDatabase) {
    this.audit = new AuditService(db);
  }

  private async validateAssociations(
    caseRecord: CaseRecord,
    locationId: string | null,
    roomID: string | null,
    linkedRoomIds: string[],
    existing?: ClaimRecord,
  ): Promise<void> {
    // A historical claim may refer to a location/room that has since been
    // removed. Editing unrelated fields must not destroy that historical link,
    // but a NEW unresolved reference is never accepted. Cross-case references
    // are always rejected, even if the same id is already on the record.
    if (locationId !== null) {
      const location = await this.db.locations.get(locationId);
      if (!location) {
        if (!existing || existing.locationId !== locationId) {
          throw new ValidationError("Referenced location not found", "locationId");
        }
      } else if (caseRecord.locationId && caseRecord.locationId !== locationId) {
        throw new ValidationError(
          "The claim location must match the case's linked location",
          "locationId",
        );
      }
    }
    for (const [field, id] of [
      ["roomID", roomID],
      ...linkedRoomIds.map((roomId) => ["linkedRoomIds", roomId] as const),
    ] as const) {
      if (id === null) continue;
      const room = await this.db.structureRooms.get(id);
      if (!room) {
        const alreadyOnClaim = existing
          ? field === "roomID"
            ? existing.roomID === id
            : existing.linkedRoomIds.includes(id)
          : false;
        if (!alreadyOnClaim) {
          throw new ValidationError("Referenced room not found", field);
        }
        continue;
      }
      if (room.caseId !== caseRecord.id) {
        throw new ValidationError(
          "Referenced room belongs to a different case",
          field,
        );
      }
    }
  }

  private buildRecord(input: ClaimCreateInput, ts: number): ClaimRecord {
    assertNonEmpty(input.caseId, "caseId");
    assertNonEmpty(input.title, "title");
    const classification = input.classification ?? "Client Reported";
    assertClassification(classification);
    const walkthroughStatus = input.walkthroughStatus ?? "Not Located";
    assertWalkthroughStatus(walkthroughStatus);
    const importSourceType = input.importSourceType ?? null;
    if (importSourceType !== null) assertImportSourceType(importSourceType);
    const witnessCount = input.witnessCount ?? 0;
    const emotionalImpact = input.emotionalImpact ?? 0;
    assertCount(witnessCount, "witnessCount");
    assertCount(emotionalImpact, "emotionalImpact");
    if (
      input.sourceOccurrenceAt !== undefined &&
      input.sourceOccurrenceAt !== null &&
      !Number.isFinite(input.sourceOccurrenceAt)
    ) {
      throw new ValidationError(
        "sourceOccurrenceAt must be a finite timestamp",
        "sourceOccurrenceAt",
      );
    }
    if (input.importedAt !== undefined && input.importedAt !== null && !Number.isFinite(input.importedAt)) {
      throw new ValidationError("importedAt must be a finite timestamp", "importedAt");
    }
    const claimID = input.claimID?.trim() || uuidv4();
    return {
      id: uuidv4(),
      schemaVersion: SCHEMA_VERSION as ClaimRecord["schemaVersion"],
      createdAt: ts,
      updatedAt: ts,
      claimID,
      caseId: input.caseId,
      locationId: input.locationId ?? null,
      roomID: input.roomID ?? null,
      roomTBD: input.roomTBD ?? false,
      roomName: input.roomName ?? "",
      subLocation: input.subLocation ?? "",
      linkedRoomIds: normalizeStringArray(input.linkedRoomIds, "linkedRoomIds"),
      title: input.title.trim(),
      occurrenceLevel: input.occurrenceLevel ?? "",
      claimType: input.claimType ?? "Other",
      claimTypeOtherText: input.claimTypeOtherText ?? "",
      firstOccurrenceText: input.firstOccurrenceText ?? "",
      mostRecentOccurrenceText: input.mostRecentOccurrenceText ?? "",
      frequency: input.frequency ?? "",
      timePattern: input.timePattern ?? "",
      weatherCorrelation: input.weatherCorrelation ?? false,
      weatherPattern: input.weatherPattern ?? "",
      witnessCount,
      witnessesText: input.witnessesText ?? "",
      witnessCountResolved: input.witnessCountResolved ?? false,
      witnessMemberIds: normalizeStringArray(input.witnessMemberIds, "witnessMemberIds"),
      emotionalImpact,
      emotionalImpactResolved: input.emotionalImpactResolved ?? false,
      feelingText: input.feelingText ?? "",
      feelingNotes: input.feelingNotes ?? "",
      classification,
      classificationResolved: input.classificationResolved ?? false,
      notes: input.notes ?? "",
      linkedPinID: input.linkedPinID ?? null,
      walkthroughStatus,
      mostRecentOccurrenceKnown: input.mostRecentOccurrenceKnown ?? null,
      isGuidedDraft: input.isGuidedDraft ?? false,
      importedFromReference: input.importedFromReference ?? false,
      importSourceType,
      importSourceRef: input.importSourceRef ?? null,
      importSourceClaimId: input.importSourceClaimId ?? null,
      importIdentity: input.importIdentity ?? null,
      importedAt: input.importedAt ?? null,
      sourceText: input.sourceText ?? null,
      sourceTextHash: input.sourceTextHash ?? null,
      sourceOccurrenceText: input.sourceOccurrenceText ?? null,
      sourceOccurrenceAt: input.sourceOccurrenceAt ?? null,
    };
  }

  async create(input: ClaimCreateInput): Promise<ClaimRecord> {
    const ts = now();
    const record = this.buildRecord(input, ts);
    return this.db.transaction(
      "rw",
      this.db.claims,
      this.db.cases,
      this.db.locations,
      this.db.structureRooms,
      this.db.auditEvents,
      async () => {
        const caseRecord = await this.db.cases.get(record.caseId);
        assertReferenceExists(record.caseId, caseRecord !== undefined, "caseId");
        if (!caseRecord) throw new ValidationError("Referenced case not found", "caseId");
        await this.validateAssociations(
          caseRecord,
          record.locationId,
          record.roomID,
          record.linkedRoomIds,
        );
        const duplicate = await this.db.claims
          .where("claimID")
          .equals(record.claimID)
          .first();
        if (duplicate) {
          throw new ValidationError(
            "A claim with this claimID already exists",
            "claimID",
          );
        }
        await this.db.claims.add(record);
        await this.audit.record("claimRecorded", "Claim recorded for case", {
          caseId: record.caseId,
          affectedRecordId: record.id,
          metadata: { imported: record.importedFromReference },
        });
        return record;
      },
    );
  }

  async get(id: string): Promise<ClaimRecord | undefined> {
    return this.db.claims.get(id);
  }

  async listForCase(caseId: string): Promise<ClaimRecord[]> {
    const rows = await this.db.claims.where("caseId").equals(caseId).toArray();
    return rows.sort((a, b) => a.createdAt - b.createdAt);
  }

  async listByClassification(
    caseId: string,
    classification: ClaimClassification,
  ): Promise<ClaimRecord[]> {
    assertClassification(classification);
    return (await this.listForCase(caseId)).filter(
      (claim) => claim.classification === classification,
    );
  }

  async listByLocation(
    locationId: string,
    caseId?: string,
  ): Promise<ClaimRecord[]> {
    const rows = await this.db.claims
      .where("locationId")
      .equals(locationId)
      .toArray();
    return rows
      .filter((claim) => caseId === undefined || claim.caseId === caseId)
      .sort((a, b) => a.createdAt - b.createdAt);
  }

  /** Claims whose primary or linked room is `roomId`, scoped to the case. */
  async listByRoom(caseId: string, roomId: string): Promise<ClaimRecord[]> {
    return (await this.listForCase(caseId)).filter(
      (claim) =>
        claim.roomID === roomId || claim.linkedRoomIds.includes(roomId),
    );
  }

  async findByImportIdentity(
    caseId: string,
    importIdentity: string,
  ): Promise<ClaimRecord | undefined> {
    const row = await this.db.claims
      .where("importIdentity")
      .equals(importIdentity)
      .first();
    return row && row.caseId === caseId ? row : undefined;
  }

  /**
   * Update permitted content fields only. Case ownership, claimID, createdAt
   * and all import/source provenance are restored from the existing record
   * after the patch is applied, so an update cannot rewrite provenance.
   */
  async update(id: string, patch: ClaimUpdateInput): Promise<ClaimRecord> {
    return this.db.transaction(
      "rw",
      this.db.claims,
      this.db.cases,
      this.db.locations,
      this.db.structureRooms,
      this.db.auditEvents,
      async () => {
        const existing = await this.db.claims.get(id);
        if (!existing) throw new ValidationError("Claim not found", "id");
        const caseRecord = await this.db.cases.get(existing.caseId);
        assertReferenceExists(existing.caseId, caseRecord !== undefined, "caseId");
        if (!caseRecord) throw new ValidationError("Owning case not found", "caseId");

        const next: ClaimRecord = { ...existing, ...patch, updatedAt: now() };
        // Provenance and identity are immutable.
        next.id = existing.id;
        next.schemaVersion = existing.schemaVersion;
        next.caseId = existing.caseId;
        next.claimID = existing.claimID;
        next.createdAt = existing.createdAt;
        next.importedFromReference = existing.importedFromReference;
        next.importSourceType = existing.importSourceType;
        next.importSourceRef = existing.importSourceRef;
        next.importSourceClaimId = existing.importSourceClaimId;
        next.importIdentity = existing.importIdentity;
        next.importedAt = existing.importedAt;
        next.sourceText = existing.sourceText;
        next.sourceTextHash = existing.sourceTextHash;
        next.sourceOccurrenceText = existing.sourceOccurrenceText;
        next.sourceOccurrenceAt = existing.sourceOccurrenceAt;

        assertNonEmpty(next.title, "title");
        assertClassification(next.classification);
        assertWalkthroughStatus(next.walkthroughStatus);
        assertCount(next.witnessCount, "witnessCount");
        assertCount(next.emotionalImpact, "emotionalImpact");
        next.linkedRoomIds = normalizeStringArray(
          next.linkedRoomIds,
          "linkedRoomIds",
        );
        next.witnessMemberIds = normalizeStringArray(
          next.witnessMemberIds,
          "witnessMemberIds",
        );
        assertTimestampsMonotonic(next.createdAt, next.updatedAt);
        await this.validateAssociations(
          caseRecord,
          next.locationId,
          next.roomID,
          next.linkedRoomIds,
          existing,
        );

        await this.db.claims.put(next);
        await this.audit.record("claimRecorded", "Claim record updated", {
          caseId: next.caseId,
          affectedRecordId: next.id,
          metadata: { updated: true },
        });
        return next;
      },
    );
  }
}
