/**
 * TPI-V2-WEB-019 — persisted report draft helpers.
 *
 * The original `PPInvestigationReport` was a free-text model inside the case.
 * This module restores its section structure for a stable, case-scoped browser
 * draft while retaining the original prohibition on generated findings:
 *
 *   - a starter contains only facts already stored in the case;
 *   - claims remain reported statements, never evidence;
 *   - measurements remain readings, never findings;
 *   - no conclusion, confidence score or investigator identity is invented;
 *   - a client report starts from an explicit allowlist and never receives
 *     client contact fields or private investigator notes automatically.
 */
import { type TPIDatabase } from "../db";
import { ValidationError } from "../validation";
import type {
  CaseReportModel,
  ReportClaim,
  ReportEvidence,
  ReportFinding,
  ReportMeasurement,
  ReportNote,
  ReportSession,
} from "./caseReport";
import type {
  ReportContentSnapshot,
  ReportSourceRef,
  ReportSourceTable,
  ReportType,
} from "../types";

export const REPORT_CONTENT_VERSION = 1;
export const REPORT_TYPES: readonly ReportType[] = ["internal", "client"];

export const REPORT_TYPE_LABELS: Record<ReportType, string> = {
  internal: "Internal Investigation Report",
  client: "Client-Facing Investigation Report",
};

export const REPORT_TYPE_SHORT_LABELS: Record<ReportType, string> = {
  internal: "Internal report",
  client: "Client report",
};

interface ReportSectionDefinition {
  id: string;
  heading: string;
  hint: string;
}

/** Original PPInvestigationReport section structure, where portable. */
export const REPORT_SECTION_DEFINITIONS: readonly ReportSectionDefinition[] = [
  {
    id: "summary",
    heading: "Executive Summary",
    hint: "Author the narrative summary. Do not state a conclusion that the records do not support.",
  },
  {
    id: "case-information",
    heading: "Case Information",
    hint: "Case identity and workflow information already recorded.",
  },
  {
    id: "client-location",
    heading: "Client / Location Summary",
    hint: "Internal reports may include recorded client and location details. Client reports use a restricted allowlist.",
  },
  {
    id: "sessions",
    heading: "Investigation Session Summary",
    hint: "Session dates, status and recorded duration. Investigator names are excluded from client-facing text.",
  },
  {
    id: "timeline",
    heading: "Timeline of Events",
    hint: "Recorded events and observations in chronological order. Do not infer missing events.",
  },
  {
    id: "evidence",
    heading: "Evidence Logged",
    hint: "Evidence references and stored SHA-256 values. Media bytes remain in the evidence store.",
  },
  {
    id: "environment",
    heading: "Environmental / Sensor Findings",
    hint: "Recorded measurements with acquisition and calibration. A reading is not a finding.",
  },
  {
    id: "ai-insights",
    heading: "AI Correlation Insights",
    hint: "Retained for structural parity. No AI correlation engine exists in this browser build; do not fabricate output.",
  },
  {
    id: "notes",
    heading: "Investigator Notes",
    hint: "Investigator-authored notes. Private notes must not be copied into a client report.",
  },
  {
    id: "conclusions",
    heading: "Preliminary Conclusions",
    hint: "Investigator interpretation, clearly separated from observations and measurements.",
  },
  {
    id: "follow-up",
    heading: "Recommended Follow-Up",
    hint: "Recommended next steps or additional investigation.",
  },
] as const;

/**
 * Explicit client-facing allowlist. Client records, locations, private notes,
 * room summaries and internal evidence-review records are intentionally absent.
 * Source references identify records only; this list also governs which source
 * families may contribute to the client starter text.
 */
export const CLIENT_ALLOWED_SOURCE_TABLES: readonly ReportSourceTable[] = [
  "cases",
  "sessions",
  "claims",
  "evidence",
  "environmentMeasurements",
  "observations",
  "walkthroughObservations",
];

export const INTERNAL_SOURCE_TABLES: readonly ReportSourceTable[] = [
  ...CLIENT_ALLOWED_SOURCE_TABLES,
  "clients",
  "locations",
  "investigationNotes",
  "roomSummaries",
  "evidenceReviews",
];

export function emptyReportContent(title: string): ReportContentSnapshot {
  return {
    schemaVersion: REPORT_CONTENT_VERSION,
    title: title.trim(),
    sections: REPORT_SECTION_DEFINITIONS.map((definition) => ({
      id: definition.id,
      heading: definition.heading,
      body: "",
    })),
  };
}

export function normalizeReportContent(
  content: ReportContentSnapshot,
  fallbackTitle: string,
): ReportContentSnapshot {
  const title = content.title.trim() || fallbackTitle.trim();
  if (!title) throw new ValidationError("Report title is required.", "title");
  return {
    schemaVersion: REPORT_CONTENT_VERSION,
    title,
    sections: content.sections.map((section) => ({
      id: section.id.trim(),
      heading: section.heading.trim(),
      body: section.body,
    })),
  };
}

function dateLabel(ms: number | null | undefined): string {
  return ms ? new Date(ms).toLocaleString() : "Not recorded";
}

function durationLabel(minutes: number | null): string {
  if (minutes === null) return "Not recorded";
  if (minutes < 60) return `${minutes} min`;
  return `${Math.floor(minutes / 60)} h ${minutes % 60} min`;
}

function countLine(model: CaseReportModel): string {
  const c = model.counts;
  return `${c.sessions} session(s), ${c.claims} reported claim(s), ${c.evidence} evidence reference(s), ${c.measurements} measurement(s), ${c.findings} investigator-authored finding/observation record(s), ${c.notes} note(s), ${c.summaries} room summary record(s).`;
}

function sectionBodies(model: CaseReportModel, reportType: ReportType): Record<string, string> {
  const internal = reportType === "internal";
  const sessionLines = model.sessions
    .map(
      (session: ReportSession) =>
        `${dateLabel(session.startedAt)} — ${session.status}; duration ${durationLabel(session.durationMinutes)}${internal && session.investigators.length ? `; investigators: ${session.investigators.join(", ")}` : ""}`,
    )
    .join("\n");
  const evidenceLines = model.evidence
    .map((item: ReportEvidence) =>
      internal
        ? `${item.title} (${item.mediaType}) — ${item.integrity}; SHA-256 ${item.contentHash}; file ${item.fileName}`
        : `Evidence ${item.id} (${item.mediaType}) — ${item.integrity}; SHA-256 ${item.contentHash}`,
    )
    .join("\n");
  const measurementLines = model.measurements
    .map((item: ReportMeasurement) =>
      internal
        ? `${dateLabel(item.at)} — ${item.measurementType}: ${item.value ?? item.text ?? "recorded value"} ${item.unit ?? ""}; acquisition ${item.acquisition}; instrument ${item.instrument ?? "not recorded"}; calibration ${item.calibration}`
        : `${dateLabel(item.at)} — ${item.measurementType}: ${item.value ?? item.text ?? "recorded value"} ${item.unit ?? ""}; acquisition ${item.acquisition}`,
    )
    .join("\n");
  const findingLines = model.findings
    .map((item: ReportFinding) => `${dateLabel(item.at)} — ${item.classification}: ${item.title}\n${item.body}`)
    .join("\n\n");
  const noteLines = model.notes
    .map((note: ReportNote) => `${note.kindLabel} — ${note.roomName} — ${note.author ?? "author not recorded"}\n${note.body}`)
    .join("\n\n");
  const claimLines = model.claims
    .map((claim: ReportClaim) =>
      internal
        ? `${claim.title} — classification: ${claim.classification}; room: ${claim.roomName ?? "not recorded"}; witnesses: ${claim.witnesses ?? "not recorded"}; notes: ${claim.notes ?? "none"}`
        : `${claim.title} — classification: ${claim.classification}; room: ${claim.roomName ?? "not recorded"}`,
    )
    .join("\n");
  const timelineBody = [
    sessionLines || "No investigation sessions recorded.",
    findingLines ? `Investigator-authored records (not automatic conclusions):\n${findingLines}` : "",
    claimLines ? `Reported claims (not verified; not evidence):\n${claimLines}` : "",
  ]
    .filter(Boolean)
    .join("\n\n");

  if (!internal) {
    return {
      summary:
        "This client-facing draft began from a restricted allowlist. It contains no automatic finding or paranormal conclusion; the investigator must author and approve the narrative.",
      "case-information": [
        `Case number: ${model.caseNumber ?? "Not recorded"}`,
        `Case title: ${model.title ?? "Not recorded"}`,
        `Investigation type: ${model.investigationType}`,
        `Status: ${model.status}`,
        "Client contact fields, street address and private investigator notes are excluded from this starter.",
      ].join("\n"),
      "client-location":
        `Location: ${model.location.name ?? "Not recorded"}\nCity/state: ${model.location.address ? "Recorded in the internal case file; street address excluded from this client starter." : "Not recorded"}`,
      sessions: sessionLines || "No investigation sessions recorded.",
      timeline: timelineBody,
      evidence: evidenceLines || "No evidence references recorded.",
      environment: measurementLines || "No equipment measurements recorded.",
      notes: "Private investigator notes are not included in a client-facing draft. Add only approved client-facing text.",
      conclusions: "",
      "follow-up": "",
      "ai-insights": "No AI correlation engine exists in this browser build. This section is retained for structural parity and must not be fabricated.",
    };
  }

  return {
    summary: `Draft created from persisted records. ${countLine(model)}\n\nAuthor the narrative here. The starter does not add a finding or paranormal conclusion.`,
    "case-information": [
      `Case number: ${model.caseNumber ?? "Not recorded"}`,
      `Title: ${model.title ?? "Not recorded"}`,
      `Status: ${model.status}`,
      `Investigation type: ${model.investigationType}`,
      `Current phase: ${model.currentPhase}`,
      `Opened: ${dateLabel(model.createdAt)}`,
      `Last updated: ${dateLabel(model.updatedAt)}`,
    ].join("\n"),
    "client-location": [
      `Client: ${model.client.name ?? "Not recorded"}`,
      `Phone: ${model.client.phone ?? "Not recorded"}`,
      `Email: ${model.client.email ?? "Not recorded"}`,
      `Client notes: ${model.client.notes ?? "None recorded"}`,
      `Location: ${model.location.name ?? "Not recorded"}`,
      `Address: ${model.location.address ?? "Not recorded"}`,
      `Property details: ${model.location.propertyDetails ?? "Not recorded"}`,
    ].join("\n"),
    sessions: sessionLines || "No investigation sessions recorded.",
    timeline: timelineBody,
    evidence: evidenceLines || "No evidence references recorded.",
    environment: measurementLines || "No equipment measurements recorded.",
    notes: noteLines || "No investigator notes recorded.",
    conclusions: "",
    "follow-up": "",
    "ai-insights": "No AI correlation engine exists in this browser build. This section is retained for structural parity and must not be fabricated.",
  };
}

/**
 * Build a new draft from persisted records. This is a draft starter, not a
 * finalized report: it creates no revision, finding, conclusion or closure.
 * The client branch never receives the client's name, contact fields, street
 * address, private notes or room summaries.
 */
export function buildReportStarter(
  model: CaseReportModel,
  reportType: ReportType,
): ReportContentSnapshot {
  const title = `${model.caseNumber ?? "Case"} — ${REPORT_TYPE_LABELS[reportType]}`;
  const content = emptyReportContent(title);
  const bodies = sectionBodies(model, reportType);
  return {
    ...content,
    sections: content.sections.map((section) => ({
      ...section,
      body: bodies[section.id] ?? "",
    })),
  };
}

function sourceUpdatedAt(row: Record<string, unknown>): number {
  for (const key of ["updatedAt", "createdAt", "at", "capturedAt", "acquiredAt"]) {
    const value = row[key];
    if (typeof value === "number" && Number.isFinite(value)) return value;
  }
  return 0;
}

function sourceRef(table: ReportSourceTable, row: Record<string, unknown>, caseId: string): ReportSourceRef | null {
  const recordId = row.id;
  if (typeof recordId !== "string" || !recordId) return null;
  const ref: ReportSourceRef = {
    table,
    recordId,
    caseId,
    updatedAt: sourceUpdatedAt(row),
  };
  if (table === "evidence" && typeof row.contentHash === "string" && /^[0-9a-f]{64}$/i.test(row.contentHash)) {
    ref.contentHash = row.contentHash.toLowerCase();
  }
  return ref;
}

/**
 * Capture stable identities for records that exist now. Evidence bytes are
 * never read or copied; only the stored evidence SHA-256 is carried in a ref.
 */
export async function collectReportSourceRefs(
  db: TPIDatabase,
  caseId: string,
  reportType: ReportType,
): Promise<ReportSourceRef[]> {
  const caseRow = await db.cases.get(caseId);
  if (!caseRow) throw new ValidationError(`Case not found: ${caseId}`, "caseId");

  const refs: ReportSourceRef[] = [];
  const add = (table: ReportSourceTable, row: Record<string, unknown> | undefined): void => {
    if (!row) return;
    const ref = sourceRef(table, row, caseId);
    if (ref) refs.push(ref);
  };

  add("cases", caseRow as unknown as Record<string, unknown>);

  if (reportType === "internal") {
    if (caseRow.clientId) {
      const client = await db.clients.get(caseRow.clientId);
      if (client?.caseId === caseId) add("clients", client as unknown as Record<string, unknown>);
    }
    if (caseRow.locationId) {
      const location = await db.locations.get(caseRow.locationId);
      if (location?.caseId === caseId) add("locations", location as unknown as Record<string, unknown>);
    }
  }

  const tables = reportType === "client" ? CLIENT_ALLOWED_SOURCE_TABLES : INTERNAL_SOURCE_TABLES;
  for (const table of tables) {
    if (table === "cases" || table === "clients" || table === "locations") continue;
    const rows = await db.table<Record<string, unknown>, string>(table).where("caseId").equals(caseId).toArray();
    for (const row of rows) add(table, row);
  }

  const seen = new Set<string>();
  return refs
    .filter((ref) => {
      const key = `${ref.table}\u0000${ref.recordId}`;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    })
    .sort((a, b) => a.table.localeCompare(b.table) || a.recordId.localeCompare(b.recordId));
}

/** Deterministic JSON used for revision content hashing. */
function canonicalValue(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(canonicalValue);
  if (value && typeof value === "object") {
    const object = value as Record<string, unknown>;
    return Object.fromEntries(
      Object.keys(object)
        .sort()
        .map((key) => [key, canonicalValue(object[key])]),
    );
  }
  return value;
}

export function canonicalReportJson(value: unknown): string {
  return JSON.stringify(canonicalValue(value));
}

/** SHA-256 of the canonical content snapshot (not a signature). */
export async function hashReportContent(content: ReportContentSnapshot): Promise<string> {
  const digest = await crypto.subtle.digest(
    "SHA-256",
    new TextEncoder().encode(canonicalReportJson(content)),
  );
  return Array.from(new Uint8Array(digest), (byte) => byte.toString(16).padStart(2, "0")).join("");
}

