/**
 * TPI-V2-WEB-020 — explicit investigation closure and reopening.
 *
 * Closure is separate from report finalization and from archiving. It requires
 * one existing finalized revision, but does not require evidence, claims,
 * measurements, a completed checklist or a positive finding. Closing never
 * archives, deletes or rewrites evidence, notes, reports or revisions.
 */
import type { TPIDatabase } from "../db";
import { now, SCHEMA_VERSION } from "../db";
import { v4 as uuidv4 } from "../../shared/uuid";
import { ValidationError } from "../validation";
import { AuditService } from "../audit";
import type {
  CaseClosureRecord,
  CaseRecord,
  CaseReportRecord,
  CaseReportRevisionRecord,
} from "../types";
import { CLOSURE_ACKNOWLEDGEMENT } from "./reportPrivacy";

export interface CloseCaseInput {
  caseId: string;
  reportId: string;
  reportRevisionId: string;
  closedBy: string;
  confirmed: boolean;
  acknowledgement: string;
  notes?: string;
}

export interface ReopenCaseInput {
  caseId: string;
  reopenedBy: string;
  reason: string;
  confirmed: boolean;
}

export interface CaseClosureState {
  record: CaseRecord;
  closure: CaseClosureRecord | undefined;
  history: CaseClosureRecord[];
}

function assertClosureIdentity(closure: CaseClosureRecord | undefined, caseId: string): void {
  if (closure && closure.caseId !== caseId) {
    throw new ValidationError("Closure record does not belong to this case.", "caseId");
  }
}

export class CaseClosureService {
  private readonly audit: AuditService;

  constructor(private readonly db: TPIDatabase) {
    this.audit = new AuditService(db);
  }

  async listForCase(caseId: string): Promise<CaseClosureRecord[]> {
    if (!caseId) return [];
    const rows = await this.db.caseClosures.where("caseId").equals(caseId).toArray();
    return rows.sort((a, b) => b.closedAt - a.closedAt || b.createdAt - a.createdAt);
  }

  async currentClosure(caseId: string): Promise<CaseClosureRecord | undefined> {
    const history = await this.listForCase(caseId);
    return history.find((closure) => closure.reopenedAt === null);
  }

  async state(caseId: string): Promise<CaseClosureState | undefined> {
    const record = await this.db.cases.get(caseId);
    if (!record) return undefined;
    const history = await this.listForCase(caseId);
    return { record, closure: history.find((closure) => closure.reopenedAt === null), history };
  }

  async closeCase(input: CloseCaseInput): Promise<{ record: CaseRecord; closure: CaseClosureRecord }> {
    if (!input.confirmed) {
      throw new ValidationError("Closing an investigation requires explicit confirmation.", "confirmed");
    }
    if (!input.closedBy?.trim()) {
      throw new ValidationError("A responsible investigator is required.", "closedBy");
    }
    if (input.acknowledgement.trim() !== CLOSURE_ACKNOWLEDGEMENT) {
      throw new ValidationError("The closure acknowledgement must be confirmed.", "acknowledgement");
    }

    const ts = now();
    return this.db.transaction(
      "rw",
      this.db.cases,
      this.db.caseReports,
      this.db.caseReportRevisions,
      this.db.caseClosures,
      this.db.auditEvents,
      async () => {
        const record = await this.db.cases.get(input.caseId);
        if (!record) throw new ValidationError(`Case not found: ${input.caseId}`, "caseId");
        if (record.status === "archived") {
          throw new ValidationError("An archived case cannot be formally closed.", "status");
        }
        if (record.isClosed) {
          throw new ValidationError("This investigation is already closed.", "isClosed");
        }

        const report: CaseReportRecord | undefined = await this.db.caseReports.get(input.reportId);
        if (!report || report.caseId !== input.caseId) {
          throw new ValidationError("Finalized report not found for this case.", "reportId");
        }
        if (report.status !== "final" || report.currentRevisionId !== input.reportRevisionId) {
          throw new ValidationError(
            "Closure requires the report's current finalized revision.",
            "reportRevisionId",
          );
        }
        const revision: CaseReportRevisionRecord | undefined = await this.db.caseReportRevisions.get(
          input.reportRevisionId,
        );
        if (
          !revision ||
          revision.caseId !== input.caseId ||
          revision.reportId !== report.id ||
          !/^[0-9a-f]{64}$/i.test(revision.contentHash)
        ) {
          throw new ValidationError("The referenced finalized revision is invalid.", "reportRevisionId");
        }

        const closure: CaseClosureRecord = {
          id: uuidv4(),
          schemaVersion: SCHEMA_VERSION,
          caseId: input.caseId,
          closedAt: ts,
          closedBy: input.closedBy.trim(),
          reportId: report.id,
          reportRevisionId: revision.id,
          reportRevisionNumber: revision.revisionNumber,
          acknowledgement: input.acknowledgement.trim(),
          notes: (input.notes ?? "").trim(),
          reopenedAt: null,
          reopenedBy: null,
          createdAt: ts,
          updatedAt: ts,
        };
        await this.db.caseClosures.add(closure);
        const next: CaseRecord = {
          ...record,
          isClosed: true,
          closedAt: ts,
          updatedAt: ts,
        };
        await this.db.cases.put(next);
        await this.audit.record(
          "caseClosed",
          `Case ${record.caseNumber} closed against ${report.reportType} report revision ${revision.revisionNumber}`,
          {
            caseId: input.caseId,
            affectedRecordId: closure.id,
            metadata: {
              reportId: report.id,
              reportType: report.reportType,
              revisionId: revision.id,
              revisionNumber: revision.revisionNumber,
              contentHash: revision.contentHash,
            },
          },
        );
        return { record: next, closure };
      },
    );
  }

  async reopenCase(input: ReopenCaseInput): Promise<{ record: CaseRecord; closure: CaseClosureRecord }> {
    if (!input.confirmed) {
      throw new ValidationError("Reopening an investigation requires explicit confirmation.", "confirmed");
    }
    if (!input.reopenedBy?.trim()) {
      throw new ValidationError("A responsible investigator is required.", "reopenedBy");
    }
    if (!input.reason?.trim()) {
      throw new ValidationError("A reopening reason is required.", "reason");
    }

    const ts = now();
    return this.db.transaction(
      "rw",
      this.db.cases,
      this.db.caseClosures,
      this.db.auditEvents,
      async () => {
        const record = await this.db.cases.get(input.caseId);
        if (!record) throw new ValidationError(`Case not found: ${input.caseId}`, "caseId");
        if (record.status === "archived") {
          throw new ValidationError("Restore the archived case before reopening the investigation.", "status");
        }
        if (!record.isClosed) {
          throw new ValidationError("This investigation is not closed.", "isClosed");
        }

        const rows = await this.db.caseClosures.where("caseId").equals(input.caseId).toArray();
        const closure = rows
          .filter((candidate) => candidate.reopenedAt === null)
          .sort((a, b) => b.closedAt - a.closedAt)[0];
        let preserved: CaseClosureRecord;
        if (closure) {
          preserved = {
            ...closure,
            reopenedAt: ts,
            reopenedBy: input.reopenedBy.trim(),
            updatedAt: ts,
          };
          await this.db.caseClosures.put(preserved);
        } else {
          // A pre-WEB-020 case may have isClosed/closedAt but no closure row.
          // Preserve that known closure transparently instead of deleting it.
          preserved = {
            id: uuidv4(),
            schemaVersion: SCHEMA_VERSION,
            caseId: input.caseId,
            closedAt: record.closedAt ?? ts,
            closedBy: "Not recorded",
            reportId: null,
            reportRevisionId: null,
            reportRevisionNumber: null,
            acknowledgement: "Closure predates WEB-020; no report revision was recorded.",
            notes: "",
            reopenedAt: ts,
            reopenedBy: input.reopenedBy.trim(),
            legacy: true,
            createdAt: ts,
            updatedAt: ts,
          };
          await this.db.caseClosures.add(preserved);
        }

        const next: CaseRecord = {
          ...record,
          isClosed: false,
          closedAt: null,
          updatedAt: ts,
        };
        await this.db.cases.put(next);
        await this.audit.record(
          "caseClosureReopened",
          `Case ${record.caseNumber} reopened: ${input.reason.trim().slice(0, 200)}`,
          {
            caseId: input.caseId,
            affectedRecordId: preserved.id,
            metadata: {
              reopenedBy: input.reopenedBy.trim(),
              previousClosureId: preserved.id,
              previousRevisionId: preserved.reportRevisionId,
              previousRevisionNumber: preserved.reportRevisionNumber,
            },
          },
        );
        return { record: next, closure: preserved };
      },
    );
  }
}

export function closureReportLabel(closure: CaseClosureRecord): string {
  if (closure.legacy || !closure.reportRevisionId) return "Legacy closure (no report revision recorded)";
  return `Report revision ${closure.reportRevisionNumber ?? "?"}`;
}

export function assertClosureRecordBelongsToCase(
  closure: CaseClosureRecord | undefined,
  caseId: string,
): void {
  assertClosureIdentity(closure, caseId);
}
