/**
 * Evidence review, annotation, and integrity services (TPI-V2-WEB-009 §13/§16/§17).
 *
 * Review is investigator assessment, not a verdict: no status forces a
 * paranormal or non-paranormal conclusion, and an unexplained recording is
 * explicitly not presented as proof of paranormal activity.
 */
import type { TPIDatabase } from "../db";
import { SCHEMA_VERSION } from "../db";
import { v4 as uuidv4 } from "../../shared/uuid";
import type {
  AnnotationTarget,
  AnnotationType,
  EvidenceAnnotationRecord,
  EvidenceRecord,
  EvidenceReviewRecord,
  EvidenceReviewStatus,
  EvidenceVerificationStatus,
} from "../types";
import { ValidationError } from "../validation";
import { AuditService } from "../audit";
import { hashBlob } from "../files/opfs.hash";
import { getManagedFileStore } from "../files/storeRegistry";

export const REVIEW_STATUS_LABELS: Record<EvidenceReviewStatus, string> = {
  unreviewed: "Unreviewed",
  inReview: "In Review",
  reviewed: "Reviewed",
  needsFollowUp: "Needs Follow-Up",
  inconclusive: "Inconclusive",
};

export const ANNOTATION_TYPE_LABELS: Record<AnnotationType, string> = {
  audioRange: "Audio time range",
  videoRange: "Video time range",
  imageRegion: "Image region",
  documentSection: "Document section",
  note: "General note",
};

export interface EvidenceReviewBlocker {
  evidenceId: string | null;
  reason: string;
  requiredAction: string;
  nonOverridable: boolean;
}

/* ============================== annotations ============================== */

export class EvidenceAnnotationService {
  private readonly audit: AuditService;

  constructor(private readonly db: TPIDatabase) {
    this.audit = new AuditService(db);
  }

  /** Validate a target against the annotation type (never a silent no-op). */
  private validateTarget(type: AnnotationType, target: AnnotationTarget): void {
    switch (type) {
      case "audioRange":
      case "videoRange": {
        if (target.startSeconds === undefined || Number.isNaN(target.startSeconds)) {
          throw new ValidationError("A time-range annotation requires a start time in seconds.", "startSeconds");
        }
        if (target.endSeconds !== undefined && target.endSeconds < target.startSeconds) {
          throw new ValidationError("The end time must not precede the start time.", "endSeconds");
        }
        return;
      }
      case "imageRegion": {
        for (const key of ["x", "y", "width", "height"] as const) {
          const v = target[key];
          if (v === undefined || Number.isNaN(v)) {
            throw new ValidationError(`An image region requires ${key} (normalized 0–1).`, key);
          }
          if (v < 0 || v > 1) throw new ValidationError(`${key} must be between 0 and 1.`, key);
        }
        return;
      }
      case "documentSection": {
        if (!target.section?.trim()) {
          throw new ValidationError("A document-section annotation requires a section reference.", "section");
        }
        return;
      }
      default:
        return;
    }
  }

  async create(
    evidenceId: string,
    input: { author: string; annotationType: AnnotationType; target?: AnnotationTarget; description: string; notes?: string },
  ): Promise<EvidenceAnnotationRecord> {
    const evidence = await this.db.evidence.get(evidenceId);
    if (!evidence) throw new ValidationError(`Evidence not found: ${evidenceId}`, "evidenceId");
    if (!input.description.trim()) throw new ValidationError("An annotation requires a description.", "description");
    if (!input.author.trim()) throw new ValidationError("An annotation requires investigator attribution.", "author");
    const target = input.target ?? {};
    this.validateTarget(input.annotationType, target);
    const ts = Date.now();
    const record: EvidenceAnnotationRecord = {
      id: uuidv4(),
      schemaVersion: SCHEMA_VERSION,
      caseId: evidence.caseId,
      evidenceId,
      author: input.author.trim(),
      createdAt: ts,
      updatedAt: ts,
      annotationType: input.annotationType,
      target,
      description: input.description.trim(),
      notes: input.notes?.trim() ?? "",
      archived: false,
      amendedFromId: null,
      amended: false,
      revision: 1,
    };
    await this.db.evidenceAnnotations.put(record);
    await this.audit.record("annotationCreated", `Annotation added (${input.annotationType}).`, {
      caseId: evidence.caseId,
      affectedRecordId: record.id,
      metadata: { evidenceId, annotationType: input.annotationType },
    });
    return record;
  }

  /** Revise an annotation; the prior revision is preserved in the chain. */
  async revise(
    annotationId: string,
    input: { description?: string; notes?: string; archived?: boolean; target?: AnnotationTarget; reason: string; author?: string },
  ): Promise<EvidenceAnnotationRecord> {
    if (!input.reason.trim()) throw new ValidationError("A revision requires a documented reason.", "reason");
    const prior = await this.db.evidenceAnnotations.get(annotationId);
    if (!prior) throw new ValidationError(`Annotation not found: ${annotationId}`, "annotationId");
    if (prior.amended) throw new ValidationError("This annotation revision has already been superseded.", "amended");
    const target = input.target ?? prior.target;
    this.validateTarget(prior.annotationType, target);
    const ts = Date.now();
    const revised: EvidenceAnnotationRecord = {
      ...prior,
      id: uuidv4(),
      createdAt: ts,
      updatedAt: ts,
      author: input.author?.trim() || prior.author,
      target,
      description: input.description?.trim() ?? prior.description,
      notes: input.notes?.trim() ?? prior.notes ?? "",
      archived: input.archived ?? false,
      amendedFromId: prior.id,
      amended: false,
      revision: prior.revision + 1,
    };
    await this.db.evidenceAnnotations.put(revised);
    await this.db.evidenceAnnotations.put({ ...prior, amended: true, updatedAt: ts });
    await this.audit.record("annotationRevised", `Annotation revised: ${input.reason.slice(0, 160)}`, {
      caseId: prior.caseId,
      affectedRecordId: revised.id,
      metadata: { priorId: prior.id, revision: revised.revision },
    });
    return revised;
  }

  async listForEvidence(evidenceId: string, includeSuperseded = false): Promise<EvidenceAnnotationRecord[]> {
    const rows = await this.db.evidenceAnnotations.where("evidenceId").equals(evidenceId).toArray();
    return rows
      .filter((a) => includeSuperseded || (!a.amended && !a.archived))
      .sort((a, b) => a.createdAt - b.createdAt);
  }

  async listForCase(caseId: string): Promise<EvidenceAnnotationRecord[]> {
    const rows = await this.db.evidenceAnnotations.where("caseId").equals(caseId).toArray();
    return rows.sort((a, b) => a.createdAt - b.createdAt);
  }
}

/* ================================ reviews ================================ */

export class EvidenceReviewService {
  private readonly audit: AuditService;

  constructor(private readonly db: TPIDatabase) {
    this.audit = new AuditService(db);
  }

  /** Record (or supersede) a review entry for an evidence item. */
  async recordReview(
    evidenceId: string,
    input: {
      status: EvidenceReviewStatus;
      reviewer: string;
      notes?: string;
      observations?: string;
      naturalExplanations?: string;
      followUp?: string;
    },
  ): Promise<EvidenceReviewRecord> {
    const evidence = await this.db.evidence.get(evidenceId);
    if (!evidence) throw new ValidationError(`Evidence not found: ${evidenceId}`, "evidenceId");
    if (!input.reviewer.trim()) throw new ValidationError("A review requires the reviewer's name.", "reviewer");
    if (input.status === "reviewed" && !input.notes?.trim() && !input.observations?.trim()) {
      throw new ValidationError(
        "Marking evidence reviewed requires recorded notes or observations describing the assessment.",
        "notes",
      );
    }
    if (input.status === "needsFollowUp" && !input.followUp?.trim()) {
      throw new ValidationError("Needs Follow-Up requires a follow-up recommendation.", "followUp");
    }
    const ts = Date.now();
    const annotations = await new EvidenceAnnotationService(this.db).listForEvidence(evidenceId);
    const record: EvidenceReviewRecord = {
      id: uuidv4(),
      schemaVersion: SCHEMA_VERSION,
      caseId: evidence.caseId,
      evidenceId,
      status: input.status,
      reviewer: input.reviewer.trim(),
      at: ts,
      notes: input.notes?.trim() ?? "",
      observations: input.observations?.trim() ?? "",
      naturalExplanations: input.naturalExplanations?.trim() ?? "",
      followUp: input.followUp?.trim() ?? "",
      annotationIds: annotations.map((a) => a.id),
    };
    await this.db.evidenceReviews.put(record);
    // Review status is mirrored onto the evidence record for fast list rendering.
    await this.db.evidence.put({
      ...evidence,
      reviewStatus:
        input.status === "reviewed" ? "reviewed"
        : input.status === "needsFollowUp" ? "flagged"
        : input.status === "inconclusive" ? "reviewed"
        : "raw",
      updatedAt: ts,
    });
    await this.audit.record("evidenceReviewUpdated", `Evidence review status: ${input.status}.`, {
      caseId: evidence.caseId,
      affectedRecordId: evidenceId,
      metadata: { status: input.status, annotations: record.annotationIds.length },
    });
    return record;
  }

  async latestReview(evidenceId: string): Promise<EvidenceReviewRecord | undefined> {
    const rows = await this.db.evidenceReviews.where("evidenceId").equals(evidenceId).toArray();
    return rows.sort((a, b) => b.at - a.at)[0];
  }

  async listForEvidence(evidenceId: string): Promise<EvidenceReviewRecord[]> {
    const rows = await this.db.evidenceReviews.where("evidenceId").equals(evidenceId).toArray();
    return rows.sort((a, b) => a.at - b.at);
  }

  async listForCase(caseId: string): Promise<EvidenceReviewRecord[]> {
    const rows = await this.db.evidenceReviews.where("caseId").equals(caseId).toArray();
    return rows.sort((a, b) => a.at - b.at);
  }

  /**
   * Review readiness derived from REAL records (WP-9 §20). Every imported
   * original must have a review entry; import alone never satisfies review.
   */
  async evaluateCaseEvidence(caseId: string): Promise<EvidenceReviewBlocker[]> {
    const evidence = (await this.db.evidence.where("caseId").equals(caseId).toArray()).filter(
      (e) => e.kind === "original",
    );
    const blockers: EvidenceReviewBlocker[] = [];
    if (evidence.length === 0) {
      blockers.push({
        evidenceId: null,
        reason: "No evidence has been imported for this case.",
        requiredAction: "Import evidence in the Evidence Library, or record a documented exception if none exists.",
        nonOverridable: false,
      });
      return blockers;
    }
    const reviews = await this.listForCase(caseId);
    const reviewed = new Map<string, EvidenceReviewRecord>();
    for (const r of reviews) reviewed.set(r.evidenceId, r);
    for (const item of evidence) {
      const review = reviewed.get(item.id);
      if (!review) {
        blockers.push({
          evidenceId: item.id,
          reason: `"${item.title}" has not been reviewed.`,
          requiredAction: "Open the evidence review and record an assessment.",
          nonOverridable: false,
        });
        continue;
      }
      if (review.status === "unreviewed" || review.status === "inReview") {
        blockers.push({
          evidenceId: item.id,
          reason: `"${item.title}" review is still ${REVIEW_STATUS_LABELS[review.status].toLowerCase()}.`,
          requiredAction: "Complete the review (Reviewed, Needs Follow-Up, or Inconclusive).",
          nonOverridable: false,
        });
        continue;
      }
      if (review.status === "needsFollowUp") {
        blockers.push({
          evidenceId: item.id,
          reason: `"${item.title}" is flagged as Needs Follow-Up.`,
          requiredAction: review.followUp || "Complete the outstanding follow-up and re-review.",
          nonOverridable: false,
        });
        continue;
      }
      if (item.verificationStatus === "missing" || item.verificationStatus === "corrupted") {
        blockers.push({
          evidenceId: item.id,
          reason: `"${item.title}" integrity check reports: ${item.verificationStatus}.`,
          requiredAction: "Re-import the evidence or document why the managed copy cannot be restored.",
          nonOverridable: true,
        });
      }
    }
    return blockers;
  }

  /** Checklist reconciliation for `evidenceReviewed` (real records only). */
  async reconcileChecklist(caseId: string): Promise<void> {
    const items = await this.db.checklistItems.where("caseId").equals(caseId).toArray();
    const item = items.find((i) => i.definitionId === "evidenceReviewed");
    if (!item) return;
    const blockers = await this.evaluateCaseEvidence(caseId);
    const satisfied = blockers.length === 0;
    if (satisfied && item.status !== "complete") {
      await this.db.checklistItems.put({
        ...item,
        status: "complete",
        completedAt: Date.now(),
        completedBy: "evidence-review-service",
        updatedAt: Date.now(),
      });
      await this.audit.record("checklistChanged", "Evidence review checklist satisfied by recorded reviews.", {
        caseId,
        affectedRecordId: item.id,
      });
    } else if (!satisfied && (item.status === "complete" || item.status === "exception")) {
      await this.db.checklistItems.put({
        ...item,
        status: "pending",
        completedAt: null,
        completedBy: null,
        notes: "Reconciled under TPI-V2-WEB-009: the previous completion was not backed by evidence review records.",
        updatedAt: Date.now(),
      });
      await this.audit.record("checklistChanged", "Evidence review checklist item reset — no supporting review records existed.", {
        caseId,
        affectedRecordId: item.id,
      });
    }
  }
}

/* ============================== integrity ============================== */

export class EvidenceIntegrityService {
  private readonly audit: AuditService;

  constructor(private readonly db: TPIDatabase) {
    this.audit = new AuditService(db);
  }

  /**
   * Verify one managed file. Distinguishes missing from corrupted and never
   * labels an unreadable file corrupted unless the bytes actually mismatch.
   */
  async verify(evidenceId: string): Promise<EvidenceVerificationStatus> {
    const evidence = await this.db.evidence.get(evidenceId);
    if (!evidence) throw new ValidationError(`Evidence not found: ${evidenceId}`, "evidenceId");
    let status: EvidenceVerificationStatus;
    let detail: string;

    let bytes: ArrayBuffer | undefined;
    try {
      bytes = await getManagedFileStore().read(evidence.opfsPath);
    } catch (err) {
      status = "verificationFailed";
      detail = `Could not read the managed copy: ${(err as Error).message}`;
      await this.persist(evidence, status, detail);
      return status;
    }
    if (!bytes) {
      status = "missing";
      detail = "The managed copy is not present in browser storage.";
    } else {
      try {
        const hash = await hashBlob(bytes);
        if (hash === evidence.contentHash) {
          status = "verified";
          detail = "Stored copy matches the recorded integrity hash.";
        } else {
          status = "corrupted";
          detail = "Stored copy does not match the recorded integrity hash.";
        }
      } catch (err) {
        status = "verificationFailed";
        detail = `Hashing failed: ${(err as Error).message}`;
      }
    }
    await this.persist(evidence, status, detail);
    return status;
  }

  private async persist(evidence: EvidenceRecord, status: EvidenceVerificationStatus, detail: string): Promise<void> {
    await this.db.evidence.put({
      ...evidence,
      verificationStatus: status,
      verifiedAt: Date.now(),
      verificationDetail: detail,
    });
    await this.audit.record("evidenceVerified", `Evidence integrity check: ${status}.`, {
      caseId: evidence.caseId,
      affectedRecordId: evidence.id,
      metadata: { status },
    });
  }

  /** Verify every original in a case; returns a per-item summary. */
  async verifyCase(caseId: string): Promise<{
    total: number;
    verified: number;
    missing: number;
    corrupted: number;
    verificationFailed: number;
    results: Array<{ evidence: EvidenceRecord; status: EvidenceVerificationStatus }>;
  }> {
    const items = (await this.db.evidence.where("caseId").equals(caseId).toArray()).filter((e) => e.kind === "original");
    const results: Array<{ evidence: EvidenceRecord; status: EvidenceVerificationStatus }> = [];
    for (const item of items) {
      const status = await this.verify(item.id);
      const fresh = (await this.db.evidence.get(item.id)) ?? item;
      results.push({ evidence: { ...fresh, verificationStatus: status }, status });
    }
    const count = (s: EvidenceVerificationStatus) => results.filter((r) => r.status === s).length;
    return {
      total: results.length,
      verified: count("verified"),
      missing: count("missing"),
      corrupted: count("corrupted"),
      verificationFailed: count("verificationFailed"),
      results,
    };
  }
}
