/**
 * Explicit investigation completion (TPI-V2-WEB-C4C).
 *
 * Original Xcode behaviour:
 *   InvestigationSessionManager.endInvestigation() records a case-level
 *   "Investigation Completed" system event in the case event history.
 *   PPCaseProgressEvaluator.isInvestigationComplete() accepts any such event
 *   for the case, and CaseProgressView / CaseDetailView use that result to lock
 *   or unlock Evidence Review.
 *
 * Browser representation:
 *   The existing append-only auditEvents store already supports case-scoped,
 *   typed events. This service uses the `investigationCompleted` audit type.
 *   It does not reuse `sessionEnded`, does not add a schema version, and does
 *   not touch evidence or review records.
 */
import type { TPIDatabase } from "../db";
import { AuditService } from "../audit";
import type { AuditEventRecord, WorkflowPhase } from "../types";
import { ValidationError } from "../validation";

const COMPLETION_ELIGIBLE_PHASES: readonly WorkflowPhase[] = ["investigation", "review", "summary"];

export interface InvestigationCompletion {
  eventId: string;
  caseId: string;
  completedAt: number;
  sessionId: string | null;
}

export interface CompleteInvestigationOptions {
  /** Optional completed session to link. The latest completed session is used otherwise. */
  sessionId?: string;
}

export class InvestigationCompletionService {
  private readonly audit: AuditService;

  constructor(private readonly db: TPIDatabase) {
    this.audit = new AuditService(db);
  }

  /** The first persisted explicit-completion event for this case, if any. */
  async getCompletion(caseId: string): Promise<InvestigationCompletion | undefined> {
    if (!caseId) return undefined;
    const events = await this.db.auditEvents.where("caseId").equals(caseId).toArray();
    const event = events
      .filter((candidate) => candidate.type === "investigationCompleted")
      .sort((a, b) => a.createdAt - b.createdAt)[0];
    return event ? this.toCompletion(event) : undefined;
  }

  async isComplete(caseId: string): Promise<boolean> {
    return Boolean(await this.getCompletion(caseId));
  }

  /**
   * Record explicit completion once per case. This is idempotent: a repeated
   * call returns the existing event and never creates a second completion.
   *
   * Validation mirrors the original outcome without inventing a completion:
   * the case must have reached the investigation phase; there must be at least
   * one completed session; and no session may still be active or paused.
   */
  async complete(caseId: string, options: CompleteInvestigationOptions = {}): Promise<InvestigationCompletion> {
    const existing = await this.getCompletion(caseId);
    if (existing) return existing;

    return this.db.transaction("rw", this.db.cases, this.db.sessions, this.db.auditEvents, async () => {
      // Re-read inside the transaction so two tabs cannot create two events.
      const repeat = await this.getCompletion(caseId);
      if (repeat) return repeat;

      const record = await this.db.cases.get(caseId);
      if (!record) throw new ValidationError(`Case not found: ${caseId}`, "caseId");
      if (record.status === "archived") {
        throw new ValidationError("Archived cases cannot record investigation completion.", "status");
      }
      if (!COMPLETION_ELIGIBLE_PHASES.includes(record.currentPhase)) {
        throw new ValidationError(
          "Investigation completion requires the case to be in the investigation phase or later.",
          "currentPhase",
        );
      }

      const sessions = await this.db.sessions.where("caseId").equals(caseId).toArray();
      const active = sessions.find((session) => session.status === "active" || session.status === "paused");
      if (active) {
        throw new ValidationError(
          "End the active investigation session before completing the investigation.",
          "session",
        );
      }

      const completedSessions = sessions
        .filter((session) => session.status === "completed")
        .sort((a, b) => (b.endedAt ?? b.startedAt) - (a.endedAt ?? a.startedAt));
      if (completedSessions.length === 0) {
        throw new ValidationError(
          "At least one completed investigation session is required before completion can be recorded.",
          "session",
        );
      }

      const session = options.sessionId
        ? completedSessions.find((candidate) => candidate.id === options.sessionId)
        : completedSessions[0];
      if (!session) {
        throw new ValidationError(
          "The linked session must be a completed session belonging to this case.",
          "sessionId",
        );
      }

      const event = await this.audit.record("investigationCompleted", "Investigation explicitly completed for this case.", {
        caseId,
        affectedRecordId: session.id,
        metadata: {
          sessionId: session.id,
          previousPhase: record.currentPhase,
          explicit: true,
        },
      });
      return this.toCompletion(event);
    });
  }

  private toCompletion(event: AuditEventRecord): InvestigationCompletion {
    const linkedSession = event.metadata?.sessionId;
    return {
      eventId: event.id,
      caseId: event.caseId ?? "",
      completedAt: event.createdAt,
      sessionId: typeof linkedSession === "string" ? linkedSession : event.affectedRecordId ?? null,
    };
  }
}
