/**
 * Walkthrough view (TPI-V2-WEB-007 §10/§11/§12/§15).
 *
 * Persistent walkthrough sessions (multiple per case, never overwritten),
 * room-by-room assessment navigation, structured observations with source
 * classification, and manual environmental observations. Delegated handlers +
 * idempotent mounting (KI-WEB-006-1 fix).
 */
import "./casehub.css";
import { getDb } from "../../core/db";
import { CaseRepository } from "../../core/repositories/caseRepository";
import { PropertyService, ELECTRONICS_OPTIONS, HVAC_OPTIONS, LIGHTING_OPTIONS, WINDOW_OPTIONS } from "../../core/property/propertyService";
import { WalkthroughService } from "../../core/property/walkthroughService";
import type { ObservationKind, RoomRecord, WalkthroughSessionRecord } from "../../core/types";
import { esc, viewShell, wireBackButton } from "../dashboard/shell";
import { mountView, onDelegate, invalidateView } from "../../shared/uidom";
import { renderCaseHub } from "./CaseHub";

const db = () => getDb();
const property = () => new PropertyService(db());
const walkthrough = () => new WalkthroughService(db(), property());

const uiState = new WeakMap<HTMLElement, WalkthroughState>();
interface WalkthroughState {
  caseId: string;
  sessionId: string | null;
  selectedRoomId: string | null;
}

function st(container: HTMLElement): WalkthroughState {
  let s = uiState.get(container);
  if (!s) {
    s = { caseId: "", sessionId: null, selectedRoomId: null };
    uiState.set(container, s);
  }
  return s;
}

const OBSERVATION_KINDS: ReadonlyArray<{ id: ObservationKind; label: string; hint: string }> = [
  { id: "reported", label: "Reported", hint: "Information supplied by the client or a witness." },
  { id: "observed", label: "Observed", hint: "Directly documented by an investigator." },
  { id: "measured", label: "Measured", hint: "Produced by an identified instrument (record the instrument)." },
  { id: "interpreted", label: "Interpreted", hint: "A proposed explanation — tentative, never a conclusion." },
];

export async function renderWalkthroughView(container: HTMLElement, caseId: string): Promise<void> {
  const record = await new CaseRepository(db()).getCase(caseId);
  if (!record) {
    invalidateView(container);
    mountView(container, viewShell("Walkthrough", `<div class="cc-empty">Case not found.</div>`));
    wireBackButton(container);
    return;
  }
  const s = st(container);
  s.caseId = caseId;
  if (!s.sessionId || !(await walkthrough().getSession(s.sessionId))) {
    s.sessionId = (await walkthrough().activeSession(caseId))?.id ?? null;
  }
  const sessions = await walkthrough().listSessions(caseId);
  const active = s.sessionId ? await walkthrough().getSession(s.sessionId) : undefined;
  const structure = await property().ensureStructureForCase(caseId);
  const hierarchy = await property().loadHierarchy(structure.id);
  const areas: RoomRecord[] = [
    ...hierarchy.floors.flatMap((f) => f.rooms.map((r) => ({ ...r, parent: f.displayName }))),
    ...hierarchy.zones.flatMap((z) => z.rooms.map((r) => ({ ...r, parent: z.displayName }))),
    ...hierarchy.unassignedRooms.map((r) => ({ ...r, parent: "Unassigned" })),
  ] as RoomRecord[];
  const rooms = areas.map((a) => a as RoomRecord & { parent?: string });
  if (!s.selectedRoomId || !rooms.some((r) => r.id === s.selectedRoomId)) s.selectedRoomId = rooms[0]?.id ?? null;
  const selectedRoom = rooms.find((r) => r.id === s.selectedRoomId) ?? null;
  const observations = s.sessionId ? await walkthrough().listObservations(caseId, s.sessionId) : [];
  const reviewedCount = rooms.filter((r) => r.assessmentStatus === "reviewed" || (r.assessmentStatus === "notApplicable" && r.notApplicableReason.trim())).length;

  invalidateView(container);
  mountView(
    container,
    viewShell(
      `Walkthrough — ${record.caseNumber}`,
      `
      <div class="case-form" data-root="walkthrough" data-case-id="${esc(caseId)}">
        <p class="cc-count">Room assessment progress: <strong>${reviewedCount} of ${rooms.length}</strong> areas assessed.
        Walkthrough records are retained per session — new sessions never overwrite previous ones.</p>

        ${
          active
            ? `
        <div class="case-row" data-active-session="${active.id}">
          <div>
            <div class="case-title">Active session (started ${new Date(active.startedAt).toLocaleString()})</div>
            <div class="case-meta">Investigator: ${esc(active.investigator)} • structure revision ${active.structureRevision}${active.locationId ? " • location-linked" : ""}</div>
          </div>
          <span class="status-badge">active</span>
        </div>`
            : `
        <div class="form-actions">
          <input id="wt-investigator" type="text" placeholder="Investigator name" aria-label="Investigator name">
          <button class="button-primary" id="start-walkthrough" type="button">Start Walkthrough Session</button>
        </div>`
        }

        ${
          active && selectedRoom
            ? `
        <h3 class="cc-section-title">Room-by-Room Assessment</h3>
        <div>${rooms
          .map(
            (r) => `
          <div class="case-row" data-wt-room-row="${r.id}">
            <div>
              <div class="case-title">${r.id === s.selectedRoomId ? "▸ " : ""}${esc(r.name)}${r.assessmentStatus === "reviewed" ? " ✓" : r.assessmentStatus === "notApplicable" ? " (N/A)" : ""}</div>
              <div class="case-meta">${esc(r.parent ?? "")} • ${esc(r.assessmentStatus)}${r.assessmentStatus === "notApplicable" && r.notApplicableReason ? ` • ${esc(r.notApplicableReason.slice(0, 80))}` : ""}</div>
            </div>
            <button class="back-button" data-wt-select-room="${r.id}" type="button">Open</button>
          </div>`,
          )
          .join("")}</div>

        <div class="case-form" id="room-assessment" data-room-id="${selectedRoom.id}">
          <h3 class="cc-section-title">Assessment — ${esc(selectedRoom.name)}</h3>
          <div class="detail-grid">
            <div class="detail-field"><label for="wa-lighting">Lighting conditions</label>
              <select id="wa-lighting" data-wa="lightingConditions">
                <option value="">— select —</option>
                ${LIGHTING_OPTIONS.map((o) => `<option ${selectedRoom.lightingConditions === o ? "selected" : ""}>${esc(o)}</option>`).join("")}
              </select></div>
            <div class="detail-field"><label for="wa-windows">Windows</label>
              <select id="wa-windows" data-wa="windowsState">
                <option value="">— select —</option>
                ${WINDOW_OPTIONS.map((o) => `<option ${selectedRoom.windowsState === o ? "selected" : ""}>${esc(o)}</option>`).join("")}
              </select></div>
            <div class="detail-field"><label for="wa-hvac">HVAC</label>
              <select id="wa-hvac" data-wa="hvacState">
                <option value="">— select —</option>
                ${HVAC_OPTIONS.map((o) => `<option ${selectedRoom.hvacState === o ? "selected" : ""}>${esc(o)}</option>`).join("")}
              </select></div>
            <div class="detail-field"><label for="wa-electronics">Electronics</label>
              <select id="wa-electronics" data-wa="electronicsState">
                <option value="">— select —</option>
                ${ELECTRONICS_OPTIONS.map((o) => `<option ${selectedRoom.electronicsState === o ? "selected" : ""}>${esc(o)}</option>`).join("")}
              </select></div>
          </div>
          <div class="detail-field"><label for="wa-modifications">Recent modifications</label>
            <textarea id="wa-modifications" data-wa="recentModifications" rows="2">${esc(selectedRoom.recentModifications)}</textarea></div>
          <div class="detail-field"><label for="wa-repairs">Repairs / structural notes</label>
            <textarea id="wa-repairs" data-wa="repairsNotes" rows="2">${esc(selectedRoom.repairsNotes)}</textarea></div>
          <div class="detail-field"><label for="wa-environmental">Environmental observations (manual observation — not automatic measurement)</label>
            <textarea id="wa-environmental" data-wa="environmentalObservations" rows="2">${esc(selectedRoom.environmentalObservations)}</textarea></div>
          <div class="detail-field"><label for="wa-notes">Investigator notes</label>
            <textarea id="wa-notes" data-wa="notes" rows="2">${esc(selectedRoom.notes)}</textarea></div>
          <div class="form-actions">
            <button class="button-primary" id="save-room-assessment" type="button">Save Assessment</button>
            <button class="button-primary" id="mark-room-reviewed" type="button">Mark Reviewed</button>
            <button class="back-button" id="mark-room-na" type="button">Not Applicable…</button>
          </div>
        </div>

        <h3 class="cc-section-title">Observations</h3>
        <div class="case-form" id="observation-form">
          <div class="detail-grid">
            <div class="detail-field"><label for="obs-kind">Classification</label>
              <select id="obs-kind">
                ${OBSERVATION_KINDS.map((k) => `<option value="${k.id}">${k.label}</option>`).join("")}
              </select></div>
            <div class="detail-field"><label for="obs-room">Room / area</label>
              <select id="obs-room">
                ${rooms.map((r) => `<option value="${r.id}" ${r.id === s.selectedRoomId ? "selected" : ""}>${esc(r.name)}</option>`).join("")}
                <option value="">Other (use area label)</option>
              </select></div>
          </div>
          <div class="detail-field"><label for="obs-area">Area label (when no room applies)</label>
            <input id="obs-area" type="text" placeholder="e.g. North Grounds"></div>
          <div class="detail-field"><label for="obs-description">Description</label>
            <textarea id="obs-description" rows="2" placeholder="What was reported, observed, measured, or interpreted"></textarea></div>
          <div class="detail-field"><label for="obs-instrument">Instrument (required for Measured)</label>
            <input id="obs-instrument" type="text" placeholder="e.g. handheld thermometer (user-entered reading)"></div>
          <div class="form-actions"><button class="button-primary" id="add-observation" type="button">Record Observation</button></div>
          <p class="cc-meta">${OBSERVATION_KINDS.map((k) => `<strong>${k.label}:</strong> ${k.hint}`).join(" ")}</p>
        </div>

        <div id="observation-list">
          ${observations.length === 0 ? '<div class="cc-empty">No observations recorded in this session.</div>' : observations
            .map(
              (o) => `
            <div class="case-row" data-obs="${o.id}">
              <div>
                <div class="case-title">[${esc(o.kind)}] ${esc(o.description)}${o.amended ? " • superseded" : ""}</div>
                <div class="case-meta">${new Date(o.createdAt).toLocaleString()} • ${o.roomId ? "room-linked" : esc(o.areaLabel || "general")}${o.instrument ? ` • instrument: ${esc(o.instrument)}` : ""}${o.amendedFromId ? " • amendment (prior value preserved)" : ""}</div>
              </div>
              ${o.amended ? "" : `<button class="back-button" data-amend-obs="${o.id}" type="button">Amend…</button>`}
            </div>`,
            )
            .join("")}
        </div>

        <div class="form-actions">
          <button class="button-primary" id="complete-walkthrough" type="button">Complete Walkthrough</button>
        </div>`
            : ""
        }

        <div class="form-actions">
          <button class="back-button" id="wt-back" type="button">← Back to Case Hub</button>
        </div>

        <h3 class="cc-section-title">Session History</h3>
        ${sessions.length === 0 ? '<div class="cc-empty">No walkthrough sessions yet.</div>' : sessions
          .map(
            (sess: WalkthroughSessionRecord) => `
          <div class="case-row" data-session-row="${sess.id}">
            <div>
              <div class="case-title">${esc(sess.status)} — started ${new Date(sess.startedAt).toLocaleString()}${sess.completedAt ? ` • completed ${new Date(sess.completedAt).toLocaleString()}` : ""}</div>
              <div class="case-meta">Investigator: ${esc(sess.investigator)} • structure revision ${sess.structureRevision}</div>
            </div>
            ${sess.status === "active" && sess.id !== s.sessionId ? `<button class="back-button" data-resume-session="${sess.id}" type="button">Resume</button>` : ""}
          </div>`,
          )
          .join("")}
      </div>
    `,
  ));

  wireHandlers(container, caseId);
  wireBackButton(container);
}

function readAssessment(container: HTMLElement): Record<string, string> {
  const out: Record<string, string> = {};
  container.querySelectorAll<HTMLSelectElement | HTMLTextAreaElement>("[data-wa]").forEach((el) => {
    out[el.dataset.wa ?? ""] = el.value;
  });
  return out;
}

function wireHandlers(container: HTMLElement, caseId: string): void {
  const reload = () => renderWalkthroughView(container, caseId);

  onDelegate(container, "click", "[data-root='walkthrough'] #wt-back", () => {
    void renderCaseHub(container, caseId);
  });
  onDelegate(container, "click", "#start-walkthrough", async () => {
    const investigator = container.querySelector<HTMLInputElement>("#wt-investigator")?.value ?? "";
    const session = await walkthrough().startSession(caseId, investigator);
    st(container).sessionId = session.id;
    await reload();
  });
  onDelegate(container, "click", "[data-resume-session]", (el) => {
    st(container).sessionId = el.dataset.resumeSession ?? null;
    void reload();
  });
  onDelegate(container, "click", "[data-wt-select-room]", (el) => {
    st(container).selectedRoomId = el.dataset.wtSelectRoom ?? null;
    void reload();
  });
  onDelegate(container, "click", "#save-room-assessment", async () => {
    const roomId = container.querySelector<HTMLElement>("#room-assessment")?.dataset.roomId ?? "";
    await property().saveRoomAssessment(roomId, readAssessment(container));
    await reload();
  });
  onDelegate(container, "click", "#mark-room-reviewed", async () => {
    const roomId = container.querySelector<HTMLElement>("#room-assessment")?.dataset.roomId ?? "";
    try {
      await property().saveRoomAssessment(roomId, readAssessment(container), { markReviewed: true });
      await reload();
    } catch (err) {
      alert((err as Error).message);
    }
  });
  onDelegate(container, "click", "#mark-room-na", async () => {
    const roomId = container.querySelector<HTMLElement>("#room-assessment")?.dataset.roomId ?? "";
    const reason = window.prompt("Document why this room/area does not apply:", "");
    if (!reason?.trim()) return;
    await property().markRoomNotApplicable(roomId, reason);
    await reload();
  });
  onDelegate(container, "click", "#add-observation", async () => {
    const sessionId = st(container).sessionId;
    if (!sessionId) return;
    const kind = (container.querySelector<HTMLSelectElement>("#obs-kind")?.value ?? "observed") as ObservationKind;
    const roomId = container.querySelector<HTMLSelectElement>("#obs-room")?.value || null;
    const areaLabel = container.querySelector<HTMLInputElement>("#obs-area")?.value ?? "";
    const description = container.querySelector<HTMLTextAreaElement>("#obs-description")?.value ?? "";
    const instrument = container.querySelector<HTMLInputElement>("#obs-instrument")?.value ?? "";
    try {
      await walkthrough().addObservation(sessionId, { roomId, areaLabel, kind, description, instrument });
      await reload();
    } catch (err) {
      alert((err as Error).message);
    }
  });
  onDelegate(container, "click", "[data-amend-obs]", async (el) => {
    const obsId = el.dataset.amendObs ?? "";
    const updated = window.prompt("Corrected description (the prior value is preserved):", "");
    if (updated === null) return;
    const reason = window.prompt("Document the reason for this amendment:", "");
    if (!reason?.trim()) return;
    try {
      await walkthrough().amendObservation(obsId, { description: updated, reason });
      await reload();
    } catch (err) {
      alert((err as Error).message);
    }
  });
  onDelegate(container, "click", "#complete-walkthrough", async () => {
    const sessionId = st(container).sessionId;
    if (!sessionId) return;
    try {
      await walkthrough().completeSession(sessionId);
      st(container).sessionId = null;
      await reload();
    } catch (err) {
      alert((err as Error).message);
    }
  });
}
