/**
 * Managed-file store registry (TPI-V2-WEB-009).
 *
 * Evidence bytes live in OPFS in the browser. Automated tests run under Node
 * where OPFS does not exist, so all managed-file IO is routed through this
 * single seam. Production code uses the OPFS implementation; tests may inject
 * an in-memory implementation. There is exactly one store — no competing
 * storage engine.
 */
import { storeCaseFile, readCasePath } from "./opfs";

export interface ManagedFileStore {
  store(
    caseId: string,
    fileName: string,
    data: ArrayBuffer | Blob,
  ): Promise<{ path: string; contentHash: string }>;
  read(path: string): Promise<ArrayBuffer | undefined>;
}

const opfsStore: ManagedFileStore = {
  store: (caseId, fileName, data) => storeCaseFile(caseId, `evidence/${fileName}`, data),
  read: (path) => readCasePath(path),
};

let current: ManagedFileStore = opfsStore;

export function getManagedFileStore(): ManagedFileStore {
  return current;
}

/** Test seam: inject or reset the managed-file store. */
export function setCaseFileStoreForTesting(store: ManagedFileStore | undefined): void {
  current = store ?? opfsStore;
}
