/**
 * Investigation classification (TPI-V2-WEB-C5 Phase 5C).
 *
 * AUTHORITATIVE SOURCE: `Core/CaseFile.swift` — `enum InvestigationType`
 * has exactly five members: residential, business, hauntedLocation,
 * discovery, urbanExploration.
 *
 * Classification is a description of the investigation being conducted. It is
 * NOT a conclusion about the location and it must never be presented as
 * evidence that a site is haunted. The original `CaseTypeBehavior` also changes
 * document/baseline requirements for some types; this browser build deliberately
 * does NOT import those workflow exemptions (C5 directive: no workflow changes
 * without separate approval).
 *
 * `historical` is a browser-only value from TPI-V2-WEB-004. It remains valid on
 * existing records but is not one of the original classifications and is not
 * offered for new or edited cases.
 */
import type { InvestigationType } from "./types";

export interface InvestigationTypeOption {
  value: InvestigationType;
  label: string;
  description: string;
}

/** The five classifications that exist in the original Xcode application. */
export const INVESTIGATION_TYPE_OPTIONS: readonly InvestigationTypeOption[] = [
  {
    value: "residential",
    label: "Residential",
    description: "Investigation of a private residence.",
  },
  {
    value: "business",
    label: "Business",
    description: "Investigation of a commercial or business premises.",
  },
  {
    value: "hauntedLocation",
    label: "Haunted Location Investigation",
    description:
      "Location-focused investigation of a site with reported activity. The label describes the investigation, not a finding about the site.",
  },
  {
    value: "discovery",
    label: "Discovery",
    description: "Discovery-led investigation.",
  },
  {
    value: "urbanExploration",
    label: "Urban Exploration",
    description: "Urban-exploration investigation.",
  },
];

/** Browser-only values retained for existing records; never offered as choices. */
export const LEGACY_INVESTIGATION_TYPE_LABELS: Readonly<Record<string, string>> = {
  historical: "Historical (legacy browser value)",
};

export const INVESTIGATION_CLASSIFICATION_NOTE =
  "Classification describes the kind of investigation being conducted. It is not a conclusion about the location, it does not declare a location haunted, and in this build it does not change workflow requirements, documents, baselines, or readiness gates.";

const ORIGINAL_VALUES = new Set<string>(INVESTIGATION_TYPE_OPTIONS.map((option) => option.value));

export function isOriginalInvestigationType(type: InvestigationType): boolean {
  return ORIGINAL_VALUES.has(type);
}

export function investigationTypeLabel(type: InvestigationType): string {
  return (
    INVESTIGATION_TYPE_OPTIONS.find((option) => option.value === type)?.label ??
    LEGACY_INVESTIGATION_TYPE_LABELS[type] ??
    type
  );
}

/** Options for a select, adding the record's legacy value when it is not original. */
export function investigationTypeSelectOptions(current: InvestigationType): InvestigationTypeOption[] {
  if (isOriginalInvestigationType(current)) return [...INVESTIGATION_TYPE_OPTIONS];
  return [
    ...INVESTIGATION_TYPE_OPTIONS,
    {
      value: current,
      label: LEGACY_INVESTIGATION_TYPE_LABELS[current] ?? `${current} (legacy)`,
      description: "Legacy browser classification retained on this record; choose an original classification to migrate it deliberately.",
    },
  ];
}
