/**
 * Evidence Library view (TPI-V2-WEB-009 §11/§13/§14/§22).
 *
 * Import (journalled + verified), integrity verification, associations,
 * media preview, and the import journal including interrupted imports.
 */
import "./casehub.css";
import { getDb } from "../../core/db";
import { CaseRepository } from "../../core/repositories/caseRepository";
import { EvidenceRepository } from "../../core/repositories/evidenceRepository";
import { EvidenceImportService, inferMediaType } from "../../core/evidence/evidenceImportService";
import { EvidenceIntegrityService } from "../../core/evidence/evidenceReviewService";
import { getSensorCapabilities } from "../../core/sensors/sensorCapabilities";
import type { EvidenceRecord, EvidenceVerificationStatus, InvestigationSessionRecord } from "../../core/types";
import { esc, viewShell, wireBackButton } from "../dashboard/shell";
import { mountView, onDelegate, invalidateView, clearDrafts, setViewNote, viewNote } from "../../shared/uidom";
import { renderCaseHub } from "./CaseHub";

const db = () => getDb();
const integrity = () => new EvidenceIntegrityService(db());

function fmtBytes(n: number): string {
  if (n < 1024) return `${n} B`;
  if (n < 1024 * 1024) return `${(n / 1024).toFixed(1)} KB`;
  return `${(n / (1024 * 1024)).toFixed(1)} MB`;
}

function fmtTime(ms: number | null | undefined): string {
  if (!ms) return "—";
  const d = new Date(ms);
  return `${d.toLocaleString()} (UTC${d.getTimezoneOffset() <= 0 ? "+" : "-"}${Math.abs(d.getTimezoneOffset() / 60)})`;
}

const VERIFICATION_BADGE: Record<EvidenceVerificationStatus, string> = {
  verified: "implemented",
  unverified: "",
  missing: "error",
  corrupted: "error",
  verificationFailed: "error",
};

const ORIGIN_LABELS: Record<string, string> = {
  "equipment-camera": "Equipment camera",
  "equipment-video": "Equipment video",
  "evp-recorder": "EVP recorder",
  "local-capture": "Local capture",
  derived: "Derived asset",
};

function originLabel(origin: string): string {
  return ORIGIN_LABELS[origin] ?? (origin || "Not recorded");
}

function sessionLabel(
  sessionId: string,
  sessions: InvestigationSessionRecord[],
): string {
  const session = sessions.find((row) => row.id === sessionId);
  return session
    ? `${session.status} — ${fmtTime(session.startedAt)}`
    : "session record missing from this case";
}

export async function renderEvidenceLibrary(container: HTMLElement, caseId: string): Promise<void> {
  const record = await new CaseRepository(db()).getCase(caseId);
  if (!record) {
    invalidateView(container);
    mountView(container, viewShell("Evidence Library", `<div class="cc-empty">Case not found.</div>`));
    wireBackButton(container);
    return;
  }
  const repo = new EvidenceRepository(db());
  const items = await repo.listForCase(caseId, 200);
  const originals = items.filter((i) => i.kind === "original");
  const imports = await new EvidenceImportService(db()).listImports(caseId);
  const structure = await db().propertyStructures.where("caseId").equals(caseId).first();
  // All rooms (including archived) are loaded so an evidence association can
  // always resolve its historical room name; only active rooms are offered in
  // the association dropdown.
  const allRooms = structure
    ? await db().structureRooms.where("structureId").equals(structure.id).toArray()
    : [];
  const rooms = allRooms.filter((r) => !r.archived);
  const roomLabel = (roomId: string): string => {
    const room = allRooms.find((r) => r.id === roomId);
    if (!room) return "(room record missing)";
    return room.archived ? `${room.name} (archived)` : room.name;
  };
  const sessions = await db().sessions.where("caseId").equals(caseId).toArray();
  const locations = await db().locations.toArray();
  const capabilities = getSensorCapabilities().list();

  const counts = {
    total: originals.length,
    verified: originals.filter((o) => o.verificationStatus === "verified").length,
    unverified: originals.filter((o) => !o.verificationStatus || o.verificationStatus === "unverified").length,
    problem: originals.filter((o) => o.verificationStatus === "missing" || o.verificationStatus === "corrupted" || o.verificationStatus === "verificationFailed").length,
  };
  const fieldCaptures = originals.filter(
    (o) => o.provenance.origin === "equipment-camera" || o.provenance.origin === "equipment-video",
  );
  detailRooms = allRooms.filter((room) => !room.archived).map((room) => ({ id: room.id, name: room.name }));
  detailSessions = sessions;

  invalidateView(container);
  mountView(
    container,
    viewShell(
      `Evidence Library — ${record.caseNumber}`,
      `
      <div class="case-form" data-root="evidence-library" data-case-id="${esc(caseId)}" data-epoch="${Date.now()}-${Math.random()}">
        <p class="cc-count">Evidence: <strong>${counts.total}</strong> original item(s) • verified ${counts.verified} • not yet verified ${counts.unverified} • integrity problems ${counts.problem}
        • storage used for this case ${esc(fmtBytes(originals.reduce((s, o) => s + o.fileSizeBytes, 0)))}</p>
        <p class="cc-meta">Original files are stored unchanged. Imports are hashed (SHA-256), the stored copy is read back and re-hashed, and only then is the evidence record committed. Nothing is compressed, enhanced, or transcoded.</p>
        <p class="cc-count" data-field-captures>Equipment field captures: <strong>${fieldCaptures.length}</strong> (${fieldCaptures.filter((o) => o.mediaType === "photo").length} photo, ${fieldCaptures.filter((o) => o.mediaType === "video").length} video)</p>

        <h3 class="cc-section-title">Import Evidence</h3>
        <div class="case-form" id="import-form">
          <div class="detail-field"><label for="ev-files">Files (audio, video, images, documents, sensor logs)</label>
            <input id="ev-files" type="file" multiple></div>
          <div class="detail-grid">
            <div class="detail-field"><label for="ev-room">Room / area (optional)</label>
              <select id="ev-room"><option value="">— no room association —</option>${rooms.map((r) => `<option value="${r.id}">${esc(r.name)}</option>`).join("")}</select></div>
            <div class="detail-field"><label for="ev-session">Session (optional)</label>
              <select id="ev-session"><option value="">— no session association —</option>${sessions.map((s) => `<option value="${s.id}">${esc(s.status)} — ${fmtTime(s.startedAt)}</option>`).join("")}</select></div>
            <div class="detail-field"><label for="ev-location">Location (optional)</label>
              <select id="ev-location"><option value="">— no location association —</option>${locations.map((l) => `<option value="${l.id}">${esc(l.name)}</option>`).join("")}</select></div>
            <div class="detail-field"><label for="ev-capture">Capture time (investigator-entered, optional)</label>
              <input id="ev-capture" type="datetime-local"></div>
          </div>
          <div class="detail-field"><label for="ev-source">Source description</label>
            <input id="ev-source" type="text" placeholder="e.g. Handheld recorder placed on the upstairs landing"></div>
          <div class="detail-field"><label for="ev-notes">Investigator notes</label>
            <textarea id="ev-notes" rows="2"></textarea></div>
          <div class="form-actions"><button class="button-primary" id="import-evidence" type="button">Import Selected Files</button></div>
          <p class="cc-meta" id="import-status" role="status">${esc(viewNote(container, "import"))}</p>
        </div>

        <h3 class="cc-section-title">Integrity</h3>
        <div class="form-actions">
          <button class="button-secondary" id="verify-case" type="button">Verify All Evidence in This Case</button>
        </div>
        <p class="cc-meta" id="verify-status" role="status">${esc(viewNote(container, "verify"))}</p>
        <p class="cc-meta">A matching hash demonstrates consistency with the recorded reference hash. It does not independently prove when, where, or by whom the original was created.</p>

        <h3 class="cc-section-title">Evidence (${items.length})</h3>
        ${items.length === 0
          ? '<div class="cc-empty">No evidence imported yet. A case may legitimately have no evidence.</div>'
          : items
              .map((item) => {
                const status = (item.verificationStatus ?? "unverified") as EvidenceVerificationStatus;
                return `
          <div class="case-row" data-evidence-row="${item.id}" data-evidence-origin="${esc(item.provenance.origin)}">
            <div>
              <div class="case-title">${esc(item.title)}${item.kind === "derived" ? ' <span class="status-badge pending">derived</span>' : ""}${item.provenance.origin === "equipment-camera" || item.provenance.origin === "equipment-video" ? ' <span class="status-badge implemented">field capture</span>' : ""}</div>
              <div class="case-meta">
                ${esc(item.mediaType)} • ${esc(fmtBytes(item.fileSizeBytes))} • captured ${fmtTime(item.captureTimestamp ?? item.acquiredAt)} (${esc(item.captureTimestampSource ?? "unknown")})<br>
                imported ${fmtTime(item.importedAt)} • review: ${esc(item.reviewStatus)} • source: ${esc(originLabel(item.provenance.origin))}
                ${item.roomId ? ` • room: ${esc(roomLabel(item.roomId))}` : ""}
                ${item.sessionId ? ` • session: ${esc(sessionLabel(item.sessionId, sessions))}` : ""}
                ${item.originalFileName ? `<br>file: ${esc(item.originalFileName)}` : ""}
              </div>
            </div>
            <div style="display:flex;flex-direction:column;gap:6px;align-items:flex-end;">
              <span class="status-badge ${VERIFICATION_BADGE[status]}">${esc(status)}</span>
              <div style="display:flex;gap:6px;">
                <button class="back-button" data-preview="${item.id}" type="button">Preview</button>
                <button class="back-button" data-verify="${item.id}" type="button">Verify</button>
                <button class="back-button" data-evidence-detail="${item.id}" type="button">Details</button>
              </div>
            </div>
          </div>`;
              })
              .join("")}

        <h3 class="cc-section-title">Import Journal (${imports.length})</h3>
        ${imports.length === 0
          ? '<div class="cc-empty">No imports recorded.</div>'
          : imports
              .slice(0, 40)
              .map(
                (row) => `
          <div class="case-row">
            <div>
              <div class="case-title">${esc(row.fileName)} — <strong>${esc(row.stage)}</strong></div>
              <div class="case-meta">${fmtTime(row.createdAt)} • ${esc(fmtBytes(row.fileSizeBytes))}${row.error ? ` • ${esc(row.error)}` : ""}${row.completedAt ? ` • completed ${fmtTime(row.completedAt)}` : ""}</div>
            </div>
            ${row.stage === "failed" ? `<button class="back-button" data-retry-import="${row.id}" type="button">Retry…</button>` : ""}
          </div>`,
              )
              .join("")}
        <div class="form-actions"><button class="back-button" id="recover-imports" type="button">Recover Interrupted Imports</button></div>

        <h3 class="cc-section-title">Evidence Preview</h3>
        <div id="evidence-preview"><div class="cc-empty">Select Preview on an evidence item.</div></div>

        <h3 class="cc-section-title">Capture Capabilities</h3>
        <div>${capabilities
          .filter((c) => c.id === "microphone" || c.id === "geolocation")
          .map(
            (c) => `<div class="case-row"><div><div class="case-title">${esc(c.label)}</div><div class="case-meta">${esc(c.detail)}</div></div><span class="status-badge">${esc(c.state)}</span></div>`,
          )
          .join("")}
          <p class="cc-meta">Browser-based EMF/temperature capture is unavailable — import external-instrument exports instead of expecting the browser to measure them.</p>
        </div>

        <div class="form-actions"><button class="back-button" id="evidence-back" type="button">← Back to Case Hub</button></div>
      </div>
    `,
  ));

  wireHandlers(container, caseId, items);
  wireBackButton(container);
}

function detailHtml(item: EvidenceRecord): string {
  return `
    <div class="case-form" data-evidence-detail-panel="${item.id}">
      <div class="detail-grid">
        <div class="detail-field"><label>Evidence id</label><div>${esc(item.id)}</div></div>
        <div class="detail-field"><label>Kind</label><div>${esc(item.kind)}</div></div>
        <div class="detail-field"><label>Media type</label><div>${esc(item.mediaType)}</div></div>
        <div class="detail-field"><label>Size</label><div>${esc(fmtBytes(item.fileSizeBytes))}</div></div>
        <div class="detail-field"><label>MIME type</label><div>${esc(item.mimeType ?? "unknown")}</div></div>
        <div class="detail-field"><label>Managed path</label><div>${esc(item.opfsPath)}</div></div>
        <div class="detail-field"><label>Original filename</label><div>${esc(item.originalFileName ?? item.fileName)}</div></div>
        <div class="detail-field"><label>SHA-256</label><div style="word-break:break-all;">${esc(item.contentHash)}</div></div>
        <div class="detail-field"><label>Capture timestamp</label><div>${fmtTime(item.captureTimestamp ?? item.acquiredAt)} — source: ${esc(item.captureTimestampSource ?? "unknown")}</div></div>
        <div class="detail-field"><label>Import timestamp</label><div>${fmtTime(item.importedAt)}</div></div>
        <div class="detail-field"><label>Integrity</label><div>${esc(item.verificationStatus ?? "unverified")}${item.verifiedAt ? ` (checked ${fmtTime(item.verifiedAt)})` : ""}</div></div>
        <div class="detail-field"><label>Verification detail</label><div>${esc(item.verificationDetail ?? "—")}</div></div>
      </div>
      <div class="detail-field"><label>Source description</label><div>${esc(item.sourceDescription || "—")}</div></div>
      <div class="detail-field"><label>Notes</label><div>${esc(item.notes || "—")}</div></div>
      <div class="detail-field"><label>Provenance</label><div>origin: ${esc(originLabel(item.provenance.origin))} (${esc(item.provenance.origin)}) • recorded ${fmtTime(item.provenance.recordedAt)} by ${esc(item.provenance.recordedBy)}</div></div>
      <div class="detail-field"><label>Session</label><div>${item.sessionId ? esc(sessionLabel(item.sessionId, detailSessions)) : "No session association"}</div></div>

      <h3 class="cc-section-title">Associations</h3>
      <div class="case-form">
        <div class="detail-field"><label for="assoc-room-${item.id}">Room / area</label>
          <div class="form-actions">
            <select data-assoc-select="room" data-evidence-id="${item.id}">
              <option value="">— none —</option>
              ${(detailRooms ?? []).map((r) => `<option value="${r.id}"${item.roomId === r.id ? " selected" : ""}>${esc(r.name)}</option>`).join("")}
            </select>
          </div>
        </div>
        <p class="cc-meta">Room renames and archival never break this reference: the association stores the stable room identifier.</p>
      </div>
    </div>`;
}

/** Current-case associations for the detail panel's module-scope bridge. */
let detailRooms: Array<{ id: string; name: string }> = [];
let detailSessions: InvestigationSessionRecord[] = [];

function wireHandlers(container: HTMLElement, caseId: string, items: EvidenceRecord[]): void {
  const reload = () => renderEvidenceLibrary(container, caseId);

  onDelegate(container, "click", "#evidence-back", () => {
    const root = container.closest<HTMLElement>(".cc-view")?.parentElement ?? container;
    void renderCaseHub(root, caseId);
  });

  onDelegate(container, "click", "#import-evidence", async () => {
    const input = container.querySelector<HTMLInputElement>("#ev-files");
    const statusEl = container.querySelector<HTMLElement>("#import-status");
    const files = Array.from(input?.files ?? []);
    if (files.length === 0) {
      if (statusEl) statusEl.textContent = "Select at least one file to import.";
      return;
    }
    const captureValue = container.querySelector<HTMLInputElement>("#ev-capture")?.value ?? "";
    const captureTs = captureValue ? new Date(captureValue).getTime() : null;
    setViewNote(container, "import", `Importing ${files.length} file(s): hashing, storing, verifying…`);
    if (statusEl) statusEl.textContent = viewNote(container, "import");
    clearDrafts(container);
    const service = new EvidenceImportService(db());
    const report = await service.importFiles(files, {
      caseId,
      sessionId: container.querySelector<HTMLSelectElement>("#ev-session")?.value || null,
      roomId: container.querySelector<HTMLSelectElement>("#ev-room")?.value || null,
      locationId: container.querySelector<HTMLSelectElement>("#ev-location")?.value || null,
      sourceDescription: container.querySelector<HTMLInputElement>("#ev-source")?.value ?? "",
      notes: container.querySelector<HTMLTextAreaElement>("#ev-notes")?.value ?? "",
      captureTimestamp: captureTs,
      captureTimestampSource: captureTs ? "investigator" : undefined,
    });
    const parts = [
      `${report.imported.length} imported`,
      report.duplicates.length ? `${report.duplicates.length} duplicate(s) recognised` : "",
      report.failed.length ? `${report.failed.length} failed` : "",
    ].filter(Boolean);
    setViewNote(
      container,
      "import",
      parts.join(" • ") +
        (report.failed.length
          ? ` — ${report.failed.map((f) => `${f.fileName} (${f.stage}: ${f.error})`).join("; ")}`
          : ""),
    );
    await reload();
  });

  onDelegate(container, "click", "#verify-case", async () => {
    const statusEl = container.querySelector<HTMLElement>("#verify-status");
    setViewNote(container, "verify", "Verifying…");
    if (statusEl) statusEl.textContent = "Verifying…";
    const summary = await integrity().verifyCase(caseId);
    setViewNote(
      container,
      "verify",
      `Checked ${summary.total}: verified ${summary.verified} • missing ${summary.missing} • corrupted ${summary.corrupted} • could not verify ${summary.verificationFailed}`,
    );
    await reload();
  });

  onDelegate(container, "click", "[data-verify]", async (el) => {
    const id = el.dataset.verify ?? "";
    await integrity().verify(id);
    await reload();
  });

  onDelegate(container, "click", "[data-evidence-detail]", (el) => {
    const id = el.dataset.evidenceDetail ?? "";
    const item = items.find((i) => i.id === id);
    const panel = container.querySelector<HTMLElement>("#evidence-preview");
    if (item && panel) panel.innerHTML = detailHtml(item);
  });

  onDelegate(container, "click", "[data-preview]", async (el) => {
    const id = el.dataset.preview ?? "";
    const item = items.find((i) => i.id === id);
    const panel = container.querySelector<HTMLElement>("#evidence-preview");
    if (!item || !panel) return;
    panel.innerHTML = `<div class="cc-empty">Loading preview…</div>`;
    const { getManagedFileStore } = await import("../../core/files/storeRegistry");
    const bytes = await getManagedFileStore().read(item.opfsPath);
    if (!bytes) {
      panel.innerHTML = `
        <div class="case-form" role="alert">
          <p class="cc-count"><strong>Preview unavailable.</strong> The managed copy is not present in browser storage (integrity: ${esc(item.verificationStatus ?? "unverified")}).</p>
          <p class="cc-meta">The metadata record is intact. Re-import the original if you still have it; this preview never fabricates content.</p>
        </div>`;
      return;
    }
    const blob = new Blob([bytes], { type: item.mimeType ?? "" });
    const url = URL.createObjectURL(blob);
    const type = item.mediaType;
    const supported =
      type === "photo" ? `<img src="${url}" alt="Evidence preview: ${esc(item.title)}" style="max-width:100%;border:1px solid #2A3441;border-radius:6px;">`
      : type === "audio" ? `<audio controls src="${url}" style="width:100%;" aria-label="Audio evidence preview"></audio>`
      : type === "video" ? `<video controls src="${url}" style="max-width:100%;border:1px solid #2A3441;border-radius:6px;" aria-label="Video evidence preview"></video>`
      : type === "document" && (item.mimeType ?? "").includes("pdf") ? `<object data="${url}" type="application/pdf" width="100%" height="480" aria-label="PDF evidence preview"><p>Inline PDF preview is unavailable in this browser. <a href="${url}" download="${esc(item.originalFileName ?? item.fileName)}">Download the file</a>.</p></object>`
      : `<p>No inline preview is available for ${esc(type)} files in this browser. <a href="${url}" download="${esc(item.originalFileName ?? item.fileName)}">Download the original file</a>.</p>`;
    panel.innerHTML = `
      <div class="case-form">
        <div class="case-title">${esc(item.title)}</div>
        <div class="case-meta">${esc(item.mediaType)} • ${esc(fmtBytes(item.fileSizeBytes))} • ${esc(item.mimeType ?? "unknown MIME type")}</div>
        <div style="margin-top:10px;">${supported}</div>
        <p class="cc-meta">Preview uses browser-native playback. Codec support varies by browser; an unsupported format is reported rather than hidden. The temporary object URL is released when you navigate away.</p>
        <div class="form-actions"><button class="back-button" id="release-preview" type="button">Close Preview</button></div>
      </div>`;
    // Release the object URL when the preview is replaced or closed.
    const release = () => URL.revokeObjectURL(url);
    onDelegate(container, "click", "#release-preview", () => {
      release();
      const p = container.querySelector<HTMLElement>("#evidence-preview");
      if (p) p.innerHTML = '<div class="cc-empty">Select Preview on an evidence item.</div>';
    });
    window.addEventListener("beforeunload", release, { once: true });
  });

  onDelegate(container, "click", "#recover-imports", async () => {
    const result = await new EvidenceImportService(db()).recoverIncompleteImports();
    alert(
      `Recovery complete. Promoted ${result.promoted.length} verified staged import(s). ${result.unresolved.length} could not be resolved and remain listed in the import journal.`,
    );
    await reload();
  });

  onDelegate(container, "click", "[data-retry-import]", () => {
    alert("A failed import cannot be retried automatically — the original file must be selected again in the import form so it can be re-verified.");
  });

  onDelegate(container, "change", "[data-assoc-select='room']", async (el) => {
    const evidenceId = el.dataset.evidenceId ?? "";
    const roomId = (el as HTMLSelectElement).value || null;
    const item = items.find((i) => i.id === evidenceId);
    if (!item) return;
    await db().evidence.put({ ...item, roomId, updatedAt: Date.now() });
    await reload();
  });

  // Populate the module-scope room list used by detail panels.
  void db()
    .propertyStructures.where("caseId")
    .equals(caseId)
    .first()
    .then((structure) =>
      structure
        ? db().structureRooms.where("structureId").equals(structure.id).toArray()
        : Promise.resolve([]),
    )
    .then((rooms) => {
      detailRooms = rooms.filter((r) => !r.archived).map((r) => ({ id: r.id, name: r.name }));
    });
}

export { inferMediaType };
