/**
 * Browser field-capture helpers (TPI-V2-WEB-012).
 *
 * These helpers deliberately contain no device state and no fabricated
 * readings. They classify real browser errors, probe real MediaRecorder
 * codec support and build deterministic original filenames for evidence
 * captured by the Equipment camera/video views.
 */

export type FieldCaptureKind = "photo" | "video";

export type CaptureFailureKind =
  | "permissionDenied"
  | "deviceUnavailable"
  | "deviceBusy"
  | "unsupported"
  | "unknown";

export interface CaptureFailure {
  kind: CaptureFailureKind;
  message: string;
}

export type CaptureDevice = "camera" | "microphone";

/**
 * Map a getUserMedia/MediaRecorder error to an honest investigator-facing
 * message. The original error name is never hidden; unsupported browsers and
 * permission denials are distinct states.
 */
export function classifyCaptureError(
  error: unknown,
  device: CaptureDevice = "camera",
): CaptureFailure {
  const name = typeof error === "object" && error !== null && "name" in error
    ? String((error as { name?: unknown }).name ?? "")
    : "";
  const detail = error instanceof Error && error.message ? ` ${error.message}` : "";

  if (name === "NotAllowedError" || name === "SecurityError") {
    return {
      kind: "permissionDenied",
      message: `${device === "microphone" ? "Microphone" : "Camera"} permission was denied. Nothing was captured or saved.`,
    };
  }
  if (name === "NotFoundError" || name === "OverconstrainedError") {
    return {
      kind: "deviceUnavailable",
      message: `No ${device} device was found. Nothing was captured or saved.`,
    };
  }
  if (name === "NotReadableError" || name === "AbortError" || name === "InvalidStateError") {
    return {
      kind: "deviceBusy",
      message: `The ${device} is unavailable or busy. Close other applications using it and try again.`,
    };
  }
  if (name === "TypeError" || name === "NotSupportedError") {
    return {
      kind: "unsupported",
      message: `This browser does not support the requested ${device} capture path.`,
    };
  }
  return {
    kind: "unknown",
    message: `${device === "microphone" ? "Microphone" : "Camera"} capture could not start.${detail}`.trim(),
  };
}

/** Real codecs offered in preference order. Availability is always probed. */
export const VIDEO_MIME_CANDIDATES = [
  "video/webm;codecs=vp9,opus",
  "video/webm;codecs=vp8,opus",
  "video/webm",
  "video/mp4;codecs=avc1.42E01E,mp4a.40.2",
  "video/mp4",
] as const;

/**
 * Return the first browser-supported video container, or an empty string.
 * `isSupported` is injectable so the negotiation can be unit-tested without a
 * browser. No candidate is assumed to work merely because MediaRecorder exists.
 */
export function pickVideoMimeType(
  isSupported: (mimeType: string) => boolean = (mimeType) => {
    if (typeof MediaRecorder === "undefined" || typeof MediaRecorder.isTypeSupported !== "function") return false;
    try {
      return MediaRecorder.isTypeSupported(mimeType);
    } catch {
      return false;
    }
  },
): string {
  for (const mimeType of VIDEO_MIME_CANDIDATES) {
    try {
      if (isSupported(mimeType)) return mimeType;
    } catch {
      /* probe failure is treated as unsupported, never as success */
    }
  }
  return "";
}

export function videoExtension(mimeType: string): "webm" | "mp4" {
  return mimeType.toLowerCase().includes("mp4") ? "mp4" : "webm";
}

function localStamp(at: number): string {
  const date = new Date(at);
  const pad = (n: number) => String(n).padStart(2, "0");
  return (
    `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}` +
    `_${pad(date.getHours())}${pad(date.getMinutes())}${pad(date.getSeconds())}`
  );
}

/** Deterministic, filesystem-safe original name; never claims a different codec. */
export function captureFileName(kind: FieldCaptureKind, at: number, mimeType = ""): string {
  if (kind === "photo") return `CAM_${localStamp(at)}.png`;
  return `VID_${localStamp(at)}.${videoExtension(mimeType)}`;
}

export function formatCaptureDuration(ms: number): string {
  const totalSeconds = Math.max(0, Math.floor(ms / 1000));
  return `${String(Math.floor(totalSeconds / 60)).padStart(2, "0")}:${String(totalSeconds % 60).padStart(2, "0")}`;
}

export function photoConstraints(): MediaStreamConstraints {
  return {
    audio: false,
    video: {
      facingMode: { ideal: "environment" },
      width: { ideal: 1920 },
      height: { ideal: 1080 },
    },
  };
}

export function videoConstraints(): MediaStreamConstraints {
  return {
    audio: true,
    video: {
      facingMode: { ideal: "environment" },
      width: { ideal: 1920 },
      height: { ideal: 1080 },
    },
  };
}

/** A genuine no-microphone fallback for video capture; the UI must label it. */
export function silentVideoConstraints(): MediaStreamConstraints {
  return { audio: false, video: videoConstraints().video };
}

export function streamHasAudio(stream: MediaStream): boolean {
  return stream.getAudioTracks().some((track) => track.readyState === "live");
}

export function stopMediaStream(stream: MediaStream | null | undefined): void {
  if (!stream) return;
  for (const track of stream.getTracks()) {
    try {
      track.stop();
    } catch {
      /* already ended */
    }
  }
}
