/**
 * TPI-V2-WEB-020 — persisted report workspace with finalization, amendments,
 * revision history and client privacy review.
 *
 * The editable surface remains the existing Investigation Summary. It is still
 * one internal report and one client report per case, with independent drafts,
 * revisions and sign-offs. Saving never creates a revision; finalizing is a
 * separate explicit action, and amendments copy a finalized revision into a
 * new editable draft without changing that revision.
 */
import "./report.css";
import { esc } from "../dashboard/shell";
import { onDelegate } from "../../shared/uidom";
import { getDb } from "../../core/db";
import type {
  CaseReportRecord,
  CaseReportRevisionRecord,
  ReportContentSnapshot,
  ReportPrivacyReview,
  ReportSectionContent,
  ReportSignoffRole,
  ReportSourceRef,
  ReportType,
} from "../../core/types";
import type { CaseReportModel } from "../../core/reporting/caseReport";
import {
  REPORT_SECTION_DEFINITIONS,
  REPORT_TYPES,
  REPORT_TYPE_SHORT_LABELS,
  buildReportStarter,
  collectReportSourceRefs,
} from "../../core/reporting/reportDraft";
import { CaseReportRepository } from "../../core/reporting/reportRepository";
import { ReportFinalizationService } from "../../core/reporting/reportFinalizationService";
import {
  CLIENT_PRIVACY_ATTESTATION,
  FINALIZATION_ATTESTATION,
  scanClientReportPrivacy,
} from "../../core/reporting/reportPrivacy";

export interface ReportWorkspaceContext {
  readinessState: string;
  readinessBlockers: number;
}

function fmt(ms: number): string {
  return new Date(ms).toLocaleString();
}

export function selectedTypeFor(container: HTMLElement, caseId: string): ReportType {
  if (container.dataset.reportCaseId !== caseId) {
    container.dataset.reportCaseId = caseId;
    container.dataset.reportSelectedType = "internal";
  }
  const value = container.dataset.reportSelectedType;
  return value === "client" ? "client" : "internal";
}

function sourceSummary(refs: readonly ReportSourceRef[]): string {
  const tables = [...new Set(refs.map((ref) => ref.table))].sort();
  return tables.length ? tables.join(", ") : "no source records referenced";
}

function reportStateLabel(report: CaseReportRecord): string {
  if (report.status === "final") return "Finalized";
  if (report.status === "amendmentDraft") return "Amendment draft";
  return "Draft";
}

function reportBadgeClass(report: CaseReportRecord): string {
  if (report.status === "final") return "report-badge report-badge-ok";
  if (report.status === "amendmentDraft") return "report-badge report-badge-warn";
  return "report-badge";
}

function sourceRefList(refs: readonly ReportSourceRef[], testId: string): string {
  if (!refs.length) {
    return `<p class="report-missing" data-${testId}-empty>No source references were captured.</p>`;
  }
  return `<ul class="report-source-list" data-${testId}>
    ${refs
      .map(
        (ref) => `<li data-${testId}-item="${esc(ref.recordId)}">
          <code>${esc(ref.table)}</code> · ${esc(ref.recordId)}${ref.contentHash ? `<br><span class="report-source">SHA-256 ${esc(ref.contentHash)}</span>` : ""}
        </li>`,
      )
      .join("")}
  </ul>`;
}

function readableContent(content: ReportContentSnapshot, testId: string): string {
  return `<div class="report-readonly-content" data-${testId}>
    <h3>${esc(content.title)}</h3>
    ${content.sections
      .map(
        (section) => `<section class="report-readonly-section" data-report-section="${esc(section.id)}">
          <h4>${esc(section.heading)}</h4>
          ${section.body.trim() ? `<p class="report-copy">${esc(section.body)}</p>` : `<p class="report-missing">No text recorded.</p>`}
        </section>`,
      )
      .join("")}
  </div>`;
}

function revisionHtml(
  revision: CaseReportRevisionRecord,
  currentRevisionId: string | null,
  numbersById: Map<string, number>,
): string {
  const current = revision.id === currentRevisionId;
  const supersedes = revision.supersedesRevisionId
    ? `Supersedes revision ${numbersById.get(revision.supersedesRevisionId) ?? "?"}`
    : "First finalized revision";
  return `<article class="report-revision" data-revision-id="${esc(revision.id)}" data-revision-number="${revision.revisionNumber}" data-revision-current="${current}">
    <div class="report-revision-head">
      <strong>Revision ${revision.revisionNumber}</strong>
      ${current ? `<span class="report-badge report-badge-ok" data-current-revision>Current</span>` : `<span class="report-badge">Historical</span>`}
    </div>
    <p class="report-meta">Finalized ${esc(fmt(revision.finalizedAt))} · ${esc(revision.signoff.finalizedBy)} (${esc(revision.signoff.role)}) · ${esc(supersedes)}</p>
    <p class="report-source">SHA-256 <code class="report-hash">${esc(revision.contentHash)}</code></p>
    <p class="report-source">Source reference snapshot: ${revision.sourceRefs.length} record(s) · ${esc(sourceSummary(revision.sourceRefs))}</p>
    <details class="report-revision-sources">
      <summary>Source identities captured with this revision</summary>
      ${sourceRefList(revision.sourceRefs, "revision-source-ref")}
    </details>
    ${revision.privacyReview ? `<p class="report-source">Client privacy reviewed by ${esc(revision.privacyReview.reviewedBy)} at ${esc(fmt(revision.privacyReview.reviewedAt))}.</p>` : ""}
    <details class="report-revision-content">
      <summary>Open revision content read-only</summary>
      ${readableContent(revision.content, "revision-content")}
    </details>
  </article>`;
}

function revisionHistory(
  report: CaseReportRecord,
  revisions: readonly CaseReportRevisionRecord[],
): string {
  const numbers = new Map(revisions.map((revision) => [revision.id, revision.revisionNumber]));
  return `<details class="report-history" data-revision-history ${revisions.length ? "" : "open"}>
    <summary>View revision history (${revisions.length})</summary>
    <p class="report-meta">Finalized revisions are immutable. The current revision is the authoritative version for this report.</p>
    ${revisions.length
      ? revisions.map((revision) => revisionHtml(revision, report.currentRevisionId, numbers)).join("")
      : `<p class="report-missing" data-no-revisions>No finalized revisions. This report is still editable and saving it does not create a revision.</p>`}
  </details>`;
}

function advisoryList(report: CaseReportRecord, model: CaseReportModel, context: ReportWorkspaceContext): string[] {
  const warnings: string[] = [];
  if (model.counts.evidence === 0) warnings.push("No evidence records are referenced. Finalization is still permitted.");
  if (model.counts.claims === 0) warnings.push("No claims are recorded. A report with no claims is valid.");
  if (model.counts.measurements === 0) warnings.push("No measurements are recorded. No finding is required.");
  if (model.counts.sessions === 0) warnings.push("No investigation sessions are recorded.");
  if (context.readinessState !== "ready" && context.readinessState !== "overridden") {
    warnings.push(
      `Workflow readiness is "${context.readinessState}" with ${context.readinessBlockers} advisory condition(s). Readiness is not a finalization gate.`,
    );
  }
  if (report.sourceRefs.length === 0) warnings.push("No source references are currently attached to this report.");
  return warnings;
}

function finalizationReview(
  report: CaseReportRecord,
  model: CaseReportModel,
  context: ReportWorkspaceContext,
): string {
  const client = report.reportType === "client";
  const flags = client ? scanClientReportPrivacy(report.draft, model) : [];
  const warnings = advisoryList(report, model, context);
  return `<div class="report-finalization-form" data-report-finalize-form hidden>
    <h4>Review for finalization</h4>
    <div class="report-review-facts">
      <div><strong>Report</strong><span>${esc(report.title)}</span></div>
      <div><strong>Type</strong><span>${esc(REPORT_TYPE_SHORT_LABELS[report.reportType])}</span></div>
      <div><strong>Case</strong><span>${esc(model.caseNumber ?? model.caseId)}</span></div>
      <div><strong>Attribution</strong><span>${esc(report.author || "Not recorded")}</span></div>
      <div><strong>Source references</strong><span>${report.sourceRefs.length} record(s)</span></div>
      <div><strong>Readiness</strong><span>${esc(context.readinessState)} (advisory)</span></div>
    </div>
    <div class="report-review-sources">
      <strong>Referenced source identities</strong>
      ${sourceRefList(report.sourceRefs, "finalization-source-ref")}
    </div>
    <div class="report-review-warnings">
      <strong>Advisory conditions</strong>
      <ul>${warnings.map((warning) => `<li>${esc(warning)}</li>`).join("")}</ul>
      <p class="report-meta">Advisory conditions do not prevent finalization. Only identity, sign-off, client privacy approval and source-reference integrity can block it.</p>
    </div>
    <details class="report-review-content">
      <summary>Review full current content</summary>
      ${readableContent(report.draft, "finalization-content")}
    </details>
    ${client
      ? `<div class="report-privacy-review" data-client-privacy-review>
          <h4>Client privacy review</h4>
          <p class="report-note"><strong>This is a deliberate manual review, not automated redaction.</strong> The allowlist started this report, but text can still be added manually. Automated checks cannot guarantee confidentiality.</p>
          ${flags.length
            ? `<ul class="report-privacy-flags" data-privacy-flags>${flags.map((flag) => `<li data-privacy-flag="${esc(flag.id)}"><strong>${esc(flag.label)}</strong><br><span>${esc(flag.detail)}</span></li>`).join("")}</ul>`
            : `<p class="report-meta" data-privacy-flags-empty>No obvious sensitive values or patterns were detected. This is not a guarantee that the report is safe for distribution.</p>`}
          <label class="report-field">
            <span>Privacy reviewer name</span>
            <input data-privacy-reviewer data-focus-id="privacy-reviewer-${report.reportType}-${report.updatedAt}" value="${esc(report.author)}" placeholder="Investigator who reviewed client-facing content" />
          </label>
          <label class="report-check">
            <input type="checkbox" data-client-privacy-confirm />
            <span>I reviewed every section and confirm this content is appropriate for client distribution, including any flagged items.</span>
          </label>
        </div>`
      : ""}
    <div class="report-signoff">
      <h4>Investigator sign-off</h4>
      <p class="report-meta">A typed sign-off is an investigator acknowledgment. It is not a legally verified signature, identity certificate or notarized document. The revision SHA-256 verifies content integrity only.</p>
      <label class="report-field">
        <span>Investigator’s typed name</span>
        <input data-report-signoff-name data-focus-id="report-signoff-${report.reportType}-${report.updatedAt}" value="${esc(report.author)}" placeholder="Name recorded on the finalized revision" />
      </label>
      <label class="report-field">
        <span>Sign-off role</span>
        <select data-report-signoff-role data-focus-id="report-role-${report.reportType}-${report.updatedAt}">
          <option value="leadInvestigator">Lead investigator</option>
          <option value="investigator">Investigator</option>
          <option value="reviewer">Reviewer</option>
        </select>
      </label>
      <label class="report-check">
        <input type="checkbox" data-report-finalize-confirm />
        <span>${esc(FINALIZATION_ATTESTATION)}</span>
      </label>
      <div class="report-draft-actions">
        <button class="button-primary" type="button" data-report-finalize>Finalize report</button>
        <button class="button-secondary" type="button" data-report-cancel-review>Cancel review</button>
      </div>
      <p class="report-draft-status" data-report-finalize-status role="status"></p>
    </div>
  </div>`;
}

function editablePanel(
  report: CaseReportRecord,
  revisions: readonly CaseReportRevisionRecord[],
  model: CaseReportModel,
  context: ReportWorkspaceContext,
): string {
  const sectionById = new Map(report.draft.sections.map((section) => [section.id, section]));
  const amendment = report.status === "amendmentDraft";
  return `<div class="report-draft-editor" data-report-panel="${report.reportType}" data-report-id="${esc(report.id)}" data-report-dirty="false">
    <div class="report-draft-meta">
      <span class="${reportBadgeClass(report)}">${esc(reportStateLabel(report))}</span>
      <span>Created ${esc(fmt(report.createdAt))}</span>
      <span>Last saved <span data-report-saved-at>${esc(fmt(report.updatedAt))}</span></span>
      <span>Schema v${report.schemaVersion}</span>
    </div>
    <p class="report-draft-status" data-report-status="saved" role="status">${amendment ? "Amendment draft loaded. Saving changes only the working copy; the current finalized revision remains authoritative." : "Draft loaded. Saving updates this draft only."}</p>
    ${amendment && report.draftBaseRevisionId ? `<p class="report-draft-sources"><strong>Amendment base:</strong> the current finalized revision remains unchanged until a new revision is finalized.</p>` : ""}
    <label class="report-field">
      <span>Report title</span>
      <input data-report-title data-report-dirty-field data-focus-id="report-title-${report.reportType}" value="${esc(report.title)}" />
    </label>
    <label class="report-field">
      <span>Prepared by <small>(optional until sign-off)</small></span>
      <input data-report-author data-report-dirty-field data-focus-id="report-author-${report.reportType}" value="${esc(report.author)}" placeholder="Investigator attribution, if recorded" />
    </label>
    <p class="report-draft-sources"><strong>Source references:</strong> ${report.sourceRefs.length} record(s) · ${esc(sourceSummary(report.sourceRefs))}</p>
    <div class="report-draft-sections">
      ${REPORT_SECTION_DEFINITIONS.map((definition) => {
        const section = sectionById.get(definition.id);
        return `<label class="report-field report-section-field">
          <span>${esc(definition.heading)}</span>
          <small>${esc(definition.hint)}</small>
          <textarea data-report-section-input data-report-dirty-field data-section-id="${esc(definition.id)}" data-section-heading="${esc(definition.heading)}" data-focus-id="report-section-${report.reportType}-${esc(definition.id)}" rows="4">${esc(section?.body ?? "")}</textarea>
        </label>`;
      }).join("")}
    </div>
    <div class="report-draft-actions">
      <button class="button-primary" type="button" data-report-save>Save draft</button>
      <button class="button-secondary" type="button" data-report-review>Review for finalization</button>
      ${amendment ? `<button class="button-secondary" type="button" data-report-discard-amendment>Discard amendment draft</button>` : ""}
      <span class="report-draft-unsaved" data-report-unsaved role="status" hidden>Unsaved changes</span>
    </div>
    <p class="report-draft-note">Saving ${amendment ? "an amendment " : "a draft "}does not finalize it and creates no revision. Finalization is a separate explicit action.</p>
    ${finalizationReview(report, model, context)}
    ${revisionHistory(report, revisions)}
  </div>`;
}

function finalizedPanel(
  report: CaseReportRecord,
  revisions: readonly CaseReportRevisionRecord[],
): string {
  const current = revisions.find((revision) => revision.id === report.currentRevisionId);
  return `<div class="report-draft-editor report-finalized" data-report-panel="${report.reportType}" data-report-id="${esc(report.id)}" data-report-state="final">
    <div class="report-draft-meta">
      <span class="${reportBadgeClass(report)}">${esc(reportStateLabel(report))}</span>
      <span>Current revision ${current?.revisionNumber ?? "unavailable"}</span>
      <span>${current ? `Finalized ${esc(fmt(current.finalizedAt))}` : "Revision unavailable"}</span>
      <span>Schema v${report.schemaVersion}</span>
    </div>
    <p class="report-draft-status" data-report-status="saved">Finalized content is immutable. Create an amendment draft to propose changes; the current revision remains authoritative until another revision is finalized.</p>
    ${current
      ? `<div class="report-final-meta">
          <p class="report-source">Signed by ${esc(current.signoff.finalizedBy)} (${esc(current.signoff.role)}) at ${esc(fmt(current.signoff.signedAt))}</p>
          <p class="report-source">SHA-256 <code class="report-hash" data-current-hash data-report-current-hash>${esc(current.contentHash)}</code></p>
          ${current.privacyReview ? `<p class="report-source">Client privacy reviewed by ${esc(current.privacyReview.reviewedBy)} at ${esc(fmt(current.privacyReview.reviewedAt))}.</p>` : ""}
          ${readableContent(current.content, "final-content")}
        </div>`
      : `<p class="report-missing">The current finalized revision could not be loaded. No replacement content was inferred.</p>`}
    <div class="report-draft-actions">
      <button class="button-secondary" type="button" data-report-amend>Create amendment</button>
    </div>
    <p class="report-draft-note">Finalizing this report did not close or archive the case. Amendment drafts and later revisions remain separate investigator actions.</p>
    ${revisionHistory(report, revisions)}
  </div>`;
}

function emptyPanel(reportType: ReportType, caseId: string): string {
  const clientNote =
    reportType === "client"
      ? " The client draft starts from a restricted allowlist; client contact details, street address, private notes and internal review comments are not copied."
      : "";
  return `<div class="report-draft-editor report-draft-empty" data-report-panel="${reportType}" data-report-empty-state="${reportType}">
    <p><strong>No ${esc(REPORT_TYPE_SHORT_LABELS[reportType].toLowerCase())} has been created for this case.</strong></p>
    <p class="cc-meta">A report is case-scoped and saved locally. Creating or saving a draft does not alter evidence, claims, notes, review state or case closure.${clientNote}</p>
    <button class="button-secondary" type="button" data-report-create="${reportType}" data-case-id="${esc(caseId)}">Create ${esc(REPORT_TYPE_SHORT_LABELS[reportType].toLowerCase())}</button>
  </div>`;
}

export function reportDraftWorkspaceHtml(
  reports: readonly CaseReportRecord[],
  model: CaseReportModel,
  selected: ReportType,
  revisionsByReport: Readonly<Record<string, readonly CaseReportRevisionRecord[]>> = {},
  context: ReportWorkspaceContext = { readinessState: "not assessed", readinessBlockers: 0 },
): string {
  const byType = new Map(reports.map((report) => [report.reportType, report]));
  return `<section class="case-report report-draft-workspace" data-report-workspace data-report-case-id="${esc(model.caseId)}" data-selected-report-type="${selected}">
    <header class="report-header">
      <div>
        <p class="report-kicker">Persisted investigation reports · schema v14</p>
        <h2>Report Drafts, Finalization &amp; Revisions</h2>
        <p class="report-meta">Internal and client-facing reports are separate records with separate drafts, revisions and sign-offs. Finalizing one never finalizes the other. Saving never creates a revision.</p>
      </div>
    </header>
    <div class="report-tabs" role="tablist" aria-label="Report type">
      ${REPORT_TYPES.map((type) => {
        const report = byType.get(type);
        return `<button class="report-tab${selected === type ? " is-active" : ""}" type="button" role="tab" data-report-tab="${type}" aria-selected="${selected === type}" aria-controls="report-panel-${type}">
          ${esc(REPORT_TYPE_SHORT_LABELS[type])}<span class="report-tab-state">${report ? esc(reportStateLabel(report)) : "Not created"}</span>
        </button>`;
      }).join("")}
    </div>
    <p class="report-draft-allowlist">Client allowlist: ${sourceSummary(
      byType.get("client")?.sourceRefs ?? [],
    )}. Internal notes and client contact records are not part of the client source set. A deliberate privacy review is still required before any client report is finalized.</p>
    <div class="report-draft-panels">
      ${REPORT_TYPES.map((type) => {
        const report = byType.get(type);
        const revisions = report ? revisionsByReport[report.id] ?? [] : [];
        const body = report
          ? report.status === "final"
            ? finalizedPanel(report, revisions)
            : editablePanel(report, revisions, model, context)
          : emptyPanel(type, model.caseId);
        return `<div id="report-panel-${type}" class="report-draft-panel" role="tabpanel" data-report-panel-wrap="${type}"${selected === type ? "" : " hidden"}>
          ${body}
        </div>`;
      }).join("")}
    </div>
    <p class="report-draft-note">Finalization, amendments and case closure are independent investigator actions. Finalizing a report does not close the case; closing a case does not finalize or archive anything.</p>
  </section>`;
}

function readContent(panel: HTMLElement): ReportContentSnapshot {
  const title = panel.querySelector<HTMLInputElement>("[data-report-title]")?.value.trim() ?? "";
  const sections: ReportSectionContent[] = REPORT_SECTION_DEFINITIONS.map((definition) => {
    const textarea = panel.querySelector<HTMLTextAreaElement>(
      `[data-report-section-input][data-section-id="${definition.id}"]`,
    );
    return {
      id: definition.id,
      heading: definition.heading,
      body: textarea?.value ?? "",
    };
  });
  return { schemaVersion: 1, title, sections };
}

const reportResizeInstalled = new WeakSet<HTMLElement>();

/** Fit persisted report text on screen instead of hiding it in a fixed scroll box. */
function resizeReportTextareas(container: HTMLElement): void {
  container
    .querySelectorAll<HTMLTextAreaElement>("[data-report-section-input]")
    .forEach((textarea) => {
      if (textarea.offsetParent === null) return;
      textarea.style.height = "auto";
      const styles = getComputedStyle(textarea);
      const border = parseFloat(styles.borderTopWidth) + parseFloat(styles.borderBottomWidth);
      textarea.style.height = `${Math.max(92, textarea.scrollHeight + border)}px`;
    });
}

function installReportResize(container: HTMLElement): void {
  if (reportResizeInstalled.has(container)) return;
  reportResizeInstalled.add(container);
  window.addEventListener("resize", () => resizeReportTextareas(container));
}

function markDirty(panel: HTMLElement): void {
  panel.dataset.reportDirty = "true";
  // A review opened against the prior persisted content is no longer valid.
  const review = panel.querySelector<HTMLElement>("[data-report-finalize-form]");
  if (review) review.hidden = true;
  const status = panel.querySelector<HTMLElement>("[data-report-status]");
  if (status) status.textContent = "Unsaved changes. Save explicitly to persist this draft.";
  const unsaved = panel.querySelector<HTMLElement>("[data-report-unsaved]");
  if (unsaved) unsaved.hidden = false;
}

function panelFor(button: HTMLElement): HTMLElement | null {
  return button.closest<HTMLElement>("[data-report-panel]");
}

function reportTypeOf(panel: HTMLElement): ReportType | null {
  const value = panel.dataset.reportPanel;
  return value === "internal" || value === "client" ? value : null;
}

async function setStatusAfterRerender(
  container: HTMLElement,
  reportType: ReportType,
  reportId: string,
  message: string,
): Promise<void> {
  const status = container.querySelector<HTMLElement>(
    `[data-report-panel="${reportType}"][data-report-id="${reportId}"] [data-report-status]`,
  );
  if (status) status.textContent = message;
}

export function wireReportDraftWorkspace(
  container: HTMLElement,
  options: {
    caseId: string;
    model: CaseReportModel;
    repository: CaseReportRepository;
    finalization: ReportFinalizationService;
    rerender: () => Promise<void>;
  },
): void {
  const { caseId, model, repository, finalization, rerender } = options;
  installReportResize(container);
  resizeReportTextareas(container);

  onDelegate(container, "click", "[data-report-tab]", (button) => {
    const type = button.dataset.reportTab;
    if (type !== "internal" && type !== "client") return;
    container.dataset.reportSelectedType = type;
    container.querySelectorAll<HTMLElement>("[data-report-tab]").forEach((tab) => {
      const active = tab.dataset.reportTab === type;
      tab.classList.toggle("is-active", active);
      tab.setAttribute("aria-selected", String(active));
    });
    container.querySelectorAll<HTMLElement>("[data-report-panel-wrap]").forEach((panel) => {
      panel.hidden = panel.dataset.reportPanelWrap !== type;
    });
    resizeReportTextareas(container);
  });

  onDelegate(container, "input", "[data-report-dirty-field]", (field) => {
    const panel = field.closest<HTMLElement>("[data-report-panel]");
    if (field instanceof HTMLTextAreaElement && field.matches("[data-report-section-input]")) {
      field.style.height = "auto";
      const styles = getComputedStyle(field);
      const border = parseFloat(styles.borderTopWidth) + parseFloat(styles.borderBottomWidth);
      field.style.height = `${Math.max(92, field.scrollHeight + border)}px`;
    }
    if (panel) markDirty(panel);
  });

  onDelegate(container, "click", "[data-report-create]", (button) => {
    const type = button.dataset.reportCreate;
    if (type !== "internal" && type !== "client") return;
    button.setAttribute("disabled", "true");
    void (async () => {
      const panel = panelFor(button);
      const status = panel?.querySelector<HTMLElement>("[data-report-status]");
      if (status) status.textContent = "Creating report...";
      try {
        const starter = buildReportStarter(model, type);
        const sourceRefs = await collectReportSourceRefs(getDb(), caseId, type);
        await repository.createDraft({
          caseId,
          reportType: type,
          title: starter.title,
          content: starter,
          sourceRefs,
        });
        container.dataset.reportSelectedType = type;
        await rerender();
      } catch (error) {
        if (status) {
          status.textContent = `Could not create report: ${error instanceof Error ? error.message : "unknown error"}`;
        }
        button.removeAttribute("disabled");
      }
    })();
  });

  onDelegate(container, "click", "[data-report-save]", (button) => {
    const panel = panelFor(button);
    if (!panel) return;
    const reportId = panel.dataset.reportId;
    const reportType = reportTypeOf(panel);
    if (!reportId || !reportType) return;
    button.setAttribute("disabled", "true");
    void (async () => {
      const status = panel.querySelector<HTMLElement>("[data-report-status]");
      try {
        const content = readContent(panel);
        if (!content.title) throw new Error("A report title is required.");
        const author = panel.querySelector<HTMLInputElement>("[data-report-author]")?.value ?? "";
        const sourceRefs = await collectReportSourceRefs(getDb(), caseId, reportType);
        const saved = await repository.updateDraft(caseId, reportId, {
          title: content.title,
          content,
          author,
          sourceRefs,
        });
        // Re-render after saving so the finalization review always displays the
        // exact persisted content and privacy flags, never a stale page load.
        await rerender();
        await setStatusAfterRerender(
          container,
          reportType,
          reportId,
          `${saved.status === "amendmentDraft" ? "Amendment draft" : "Draft"} saved ${fmt(saved.updatedAt)}. No revision was created.`,
        );
      } catch (error) {
        if (status) {
          status.textContent = `Could not save draft: ${error instanceof Error ? error.message : "unknown error"}`;
        }
      } finally {
        button.removeAttribute("disabled");
      }
    })();
  });

  onDelegate(container, "click", "[data-report-review]", (button) => {
    const panel = panelFor(button);
    const form = panel?.querySelector<HTMLElement>("[data-report-finalize-form]");
    if (!form || !panel) return;
    if (panel.dataset.reportDirty === "true") {
      const status = panel.querySelector<HTMLElement>("[data-report-status]");
      if (status) status.textContent = "Save this draft before reviewing finalization. Only persisted content can be reviewed and finalized.";
      return;
    }
    form.hidden = !form.hidden;
    if (!form.hidden) {
      form.scrollIntoView({ block: "nearest", behavior: "smooth" });
      form.querySelector<HTMLElement>("[data-report-signoff-name]")?.focus();
    }
  });

  onDelegate(container, "click", "[data-report-cancel-review]", (button) => {
    const panel = panelFor(button);
    const form = panel?.querySelector<HTMLElement>("[data-report-finalize-form]");
    if (form) form.hidden = true;
  });

  onDelegate(container, "click", "[data-report-amend]", (button) => {
    const panel = panelFor(button);
    if (!panel?.dataset.reportId) return;
    button.setAttribute("disabled", "true");
    void (async () => {
      try {
        await repository.startAmendment(caseId, panel.dataset.reportId!);
        await rerender();
      } catch (error) {
        await setStatusAfterRerender(
          container,
          reportTypeOf(panel) ?? "internal",
          panel.dataset.reportId!,
          `Could not create amendment: ${error instanceof Error ? error.message : "unknown error"}`,
        );
        button.removeAttribute("disabled");
      }
    })();
  });

  onDelegate(container, "click", "[data-report-discard-amendment]", (button) => {
    const panel = panelFor(button);
    if (!panel?.dataset.reportId) return;
    if (!window.confirm("Discard this amendment draft? The current finalized revision remains authoritative.")) return;
    button.setAttribute("disabled", "true");
    void (async () => {
      try {
        await repository.discardAmendment(caseId, panel.dataset.reportId!);
        await rerender();
      } catch (error) {
        await setStatusAfterRerender(
          container,
          reportTypeOf(panel) ?? "internal",
          panel.dataset.reportId!,
          `Could not discard amendment: ${error instanceof Error ? error.message : "unknown error"}`,
        );
        button.removeAttribute("disabled");
      }
    })();
  });

  onDelegate(container, "click", "[data-report-finalize]", (button) => {
    const panel = panelFor(button);
    if (!panel?.dataset.reportId) return;
    const reportId = panel.dataset.reportId;
    const reportType = reportTypeOf(panel);
    if (!reportType) return;
    const status = panel.querySelector<HTMLElement>("[data-report-finalize-status]");
    if (panel.dataset.reportDirty === "true") {
      if (status) status.textContent = "Save draft before finalizing. Only persisted content can become a revision.";
      return;
    }
    const typedName = panel.querySelector<HTMLInputElement>("[data-report-signoff-name]")?.value.trim() ?? "";
    const role = (panel.querySelector<HTMLSelectElement>("[data-report-signoff-role]")?.value ??
      "leadInvestigator") as ReportSignoffRole;
    const confirmed = panel.querySelector<HTMLInputElement>("[data-report-finalize-confirm]")?.checked ?? false;
    const privacyConfirmed =
      panel.querySelector<HTMLInputElement>("[data-client-privacy-confirm]")?.checked ?? false;
    const privacyReviewer =
      panel.querySelector<HTMLInputElement>("[data-privacy-reviewer]")?.value.trim() ?? "";
    button.setAttribute("disabled", "true");
    void (async () => {
      try {
        if (!typedName) throw new Error("A typed investigator name is required for sign-off.");
        if (!confirmed) throw new Error("Confirm the intentional finalization statement.");
        const report = await repository.getById(caseId, reportId);
        if (!report) throw new Error("Report not found for this case.");
        const flags = report.reportType === "client" ? scanClientReportPrivacy(report.draft, model) : [];
        const privacyReview: ReportPrivacyReview | null =
          report.reportType === "client" && privacyConfirmed && privacyReviewer
            ? {
                reviewedBy: privacyReviewer,
                reviewedAt: Date.now(),
                confirmed: true,
                attestation: CLIENT_PRIVACY_ATTESTATION,
                flagsAcknowledged: flags.map((flag) => flag.id),
              }
            : null;
        const result = await finalization.finalize(
          {
            caseId,
            reportId,
            signoff: {
              finalizedBy: typedName,
              role,
              signedAt: Date.now(),
              attestation: FINALIZATION_ATTESTATION,
            },
            privacyReview,
            confirmed,
          },
          model,
        );
        await rerender();
        await setStatusAfterRerender(
          container,
          reportType,
          reportId,
          `Report finalized as revision ${result.revision.revisionNumber}. The revision is immutable; the case was not closed or archived.`,
        );
      } catch (error) {
        if (status) status.textContent = `Could not finalize: ${error instanceof Error ? error.message : "unknown error"}`;
        button.removeAttribute("disabled");
      }
    })();
  });
}
