/**
 * Centralized validation rules for investigation records (Directive §12).
 * Repositories call these before any write; validators never invent
 * scientific conclusions — unexplained does not mean paranormal.
 */
import type {
  CaseStatus,
  EvidenceRecord,
  InvestigationSessionRecord,
} from "./types";

export class ValidationError extends Error {
  constructor(
    message: string,
    public readonly field?: string,
  ) {
    super(message);
    this.name = "ValidationError";
  }
}

const UUID_RE =
  /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

export function assertValidId(id: string, field = "id"): void {
  if (!UUID_RE.test(id)) {
    throw new ValidationError(`Invalid identifier for ${field}`, field);
  }
}

export function assertNonEmpty(value: string | undefined, field: string): void {
  if (value === undefined || value.trim().length === 0) {
    throw new ValidationError(`${field} must not be empty`, field);
  }
}

/** Status transitions for cases. Archiving/reopening are controlled moves. */
const CASE_STATUS_TRANSITIONS: Record<CaseStatus, CaseStatus[]> = {
  active: ["inactive", "archived"],
  inactive: ["active", "archived"],
  archived: ["active"], // reopen
};

export function assertCaseStatusTransition(
  from: CaseStatus,
  to: CaseStatus,
): void {
  const allowed = CASE_STATUS_TRANSITIONS[from];
  if (!allowed.includes(to)) {
    throw new ValidationError(
      `Illegal case status transition ${from} → ${to}`,
      "status",
    );
  }
}

export function assertTimestampsMonotonic(createdAt: number, updatedAt: number): void {
  if (updatedAt < createdAt) {
    throw new ValidationError("updatedAt must not precede createdAt", "updatedAt");
  }
}

/**
 * Referential integrity: throws when a record references a missing parent.
 * IndexedDB cannot enforce relationships, so the data layer does.
 */
export function assertReferenceExists(
  referencedId: string | undefined,
  exists: boolean | undefined,
  field: string,
): void {
  if (referencedId !== undefined && !exists) {
    throw new ValidationError(
      `Referenced record not found for ${field}: ${referencedId}`,
      field,
    );
  }
}

export function assertSessionBelongsToCase(
  session: InvestigationSessionRecord | undefined,
  caseId: string,
): void {
  if (session && session.caseId !== caseId) {
    throw new ValidationError("Session does not belong to the given case", "sessionId");
  }
}

export function assertRoomBelongsToCase(
  room: { caseId: string } | undefined,
  caseId: string,
): void {
  if (room && room.caseId !== caseId) {
    throw new ValidationError("Room does not belong to the given case", "roomId");
  }
}

export function assertEvidenceRecordShape(record: EvidenceRecord): void {
  assertValidId(record.id, "evidence.id");
  assertValidId(record.caseId, "evidence.caseId");
  assertNonEmpty(record.fileName, "fileName");
  assertNonEmpty(record.opfsPath, "opfsPath");
  assertNonEmpty(record.contentHash, "contentHash");
  if (!/^[0-9a-f]{64}$/.test(record.contentHash)) {
    throw new ValidationError("contentHash must be a sha-256 hex digest", "contentHash");
  }
  if (record.kind === "derived" && !record.parentId) {
    throw new ValidationError("Derived evidence requires a parentId", "parentId");
  }
  if (record.kind === "original" && record.parentId) {
    throw new ValidationError("Original evidence must not have a parentId", "parentId");
  }
}
