/**
 * Environmental baseline service (TPI-V2-WEB-008 §7/§12/§16).
 *
 * Ports the iOS baseline semantics exactly:
 *  - `BaselineRoomRecord` / `PPPersistedBaselineRecord`: a room baseline is
 *    complete only when start + end + non-empty summary + explicitly marked
 *    complete (`isBaselineComplete`).
 *  - `PPCaseProgressEvaluator.isBaselineComplete`: EVERY walkthrough-flagged
 *    room must have a complete baseline; at least one room must record the
 *    global lock (phones logged, HVAC logged, stable placement); every flagged
 *    room must have a drift check; and unresolved unstable drift blocks.
 *  - `baselineStartGate`: baseline readings may only begin after the
 *    walkthrough is complete.
 *
 * A baseline is a documented reference condition — never proof about the
 * paranormal, and measurements are never fabricated to satisfy it.
 */
import type { TPIDatabase } from "../db";
import { SCHEMA_VERSION } from "../db";
import { v4 as uuidv4 } from "../../shared/uuid";
import type { BaselineRecord } from "../types";
import { ValidationError } from "../validation";
import { AuditService } from "../audit";
import type { PropertyService } from "../property/propertyService";
import type { WalkthroughService } from "../property/walkthroughService";
import type { SessionService } from "../session/sessionService";

export interface BaselineBlocker {
  roomId: string | null;
  roomName: string;
  reason: string;
  requiredAction: string;
  nonOverridable: boolean;
}

export interface BaselineProgress {
  flaggedRooms: number;
  completeRooms: number;
  driftCheckedRooms: number;
  globalLockRecorded: boolean;
  unresolvedDrift: boolean;
}

export class BaselineService {
  private readonly audit: AuditService;

  constructor(
    private readonly db: TPIDatabase,
    private readonly property: PropertyService,
    private readonly walkthrough: WalkthroughService,
    private readonly sessions: SessionService,
  ) {
    this.audit = new AuditService(db);
  }

  /** iOS `baselineStartGate`: walkthrough must be complete first. */
  async canStartBaseline(caseId: string): Promise<{ allowed: boolean; reason: string }> {
    const caseRecord = await this.db.cases.get(caseId);
    if (!caseRecord) return { allowed: false, reason: "Case not found." };
    if (caseRecord.status === "archived") return { allowed: false, reason: "Archived cases cannot collect baseline readings." };
    const walkthroughBlockers = await this.walkthrough.evaluateCaseWalkthrough(caseId);
    if (walkthroughBlockers.length > 0) {
      return { allowed: false, reason: "Walkthrough must be completed before baseline readings can begin." };
    }
    return { allowed: true, reason: "" };
  }

  /** Idempotently ensure a baseline record exists for a room. */
  async ensureBaseline(caseId: string, roomId: string, sessionId?: string | null): Promise<BaselineRecord> {
    const room = await this.db.structureRooms.get(roomId);
    if (!room) throw new ValidationError(`Room not found: ${roomId}`, "roomId");
    if (room.caseId !== caseId) throw new ValidationError("Room belongs to a different case.", "roomId");
    const existing = (await this.db.baselineRecords.where("roomId").equals(roomId).toArray()).find(
      (b) => b.caseId === caseId,
    );
    if (existing) return existing as BaselineRecord;
    // The iOS global lock is a property-wide condition; a new room baseline
    // inherits it from any sibling record that already recorded it.
    const siblings = await this.db.baselineRecords.where("caseId").equals(caseId).toArray();
    const inherited = siblings.find((b) => b.globalPhonesLogged && b.globalHvacLogged && b.globalStablePlacement);
    const ts = Date.now();
    const record: BaselineRecord = {
      id: uuidv4(),
      schemaVersion: SCHEMA_VERSION,
      caseId,
      roomId,
      sessionId: sessionId ?? null,
      structureId: room.structureId,
      roomNameAtRecord: room.name,
      baselineStart: null,
      baselineEnd: null,
      baselineSummary: "",
      baselineMarkedComplete: false,
      globalPhonesLogged: inherited?.globalPhonesLogged ?? false,
      globalHvacLogged: inherited?.globalHvacLogged ?? false,
      globalStablePlacement: inherited?.globalStablePlacement ?? false,
      driftChecked: false,
      driftDetected: false,
      notes: "",
      createdAt: ts,
      updatedAt: ts,
    };
    await this.db.baselineRecords.put(record);
    await this.audit.record("baselineRecorded", "Baseline record created for a room.", {
      caseId,
      affectedRecordId: record.id,
      metadata: { roomId },
    });
    return record;
  }

  /** Begin a room's baseline window (iOS `startBaseline(for:)`). */
  async startBaseline(caseId: string, roomId: string, sessionId?: string | null): Promise<BaselineRecord> {
    const gate = await this.canStartBaseline(caseId);
    if (!gate.allowed) throw new ValidationError(gate.reason, "baseline");
    const record = await this.ensureBaseline(caseId, roomId, sessionId);
    const next: BaselineRecord = {
      ...record,
      baselineStart: Date.now(),
      baselineEnd: null,
      baselineMarkedComplete: false,
      sessionId: sessionId ?? record.sessionId,
      updatedAt: Date.now(),
    };
    await this.db.baselineRecords.put(next);
    if (sessionId) {
      await this.sessions.recordEvent(sessionId, "baselineUpdated", `Baseline window started (${record.roomNameAtRecord}).`, {
        metadata: { roomId, phase: "start" },
      });
    }
    return next;
  }

  /** End a room's baseline window and store the investigator summary. */
  async endBaseline(
    baselineId: string,
    input: { summary: string; notes?: string; markComplete?: boolean },
  ): Promise<BaselineRecord> {
    const record = await this.db.baselineRecords.get(baselineId);
    if (!record) throw new ValidationError(`Baseline not found: ${baselineId}`, "baselineId");
    if (record.baselineStart === null) {
      throw new ValidationError("Start the baseline window before ending it.", "baselineStart");
    }
    if (!input.summary.trim()) {
      // iOS requires a non-empty summary before a baseline can be complete.
      throw new ValidationError(
        "A baseline summary is required (the iOS baseline rule requires recorded notes before completion).",
        "summary",
      );
    }
    const next: BaselineRecord = {
      ...record,
      baselineEnd: Date.now(),
      baselineSummary: input.summary.trim(),
      notes: input.notes ?? record.notes,
      updatedAt: Date.now(),
    };
    if (input.markComplete) {
      if (!next.baselineEnd) throw new ValidationError("Baseline requires both a start and an end timestamp.", "baselineEnd");
      next.baselineMarkedComplete = true;
    }
    await this.db.baselineRecords.put(next);
    await this.audit.record("baselineRecorded", `Baseline window ended for a room${next.baselineMarkedComplete ? " and marked complete" : ""}.`, {
      caseId: record.caseId,
      affectedRecordId: baselineId,
      metadata: { roomId: record.roomId, complete: next.baselineMarkedComplete },
    });
    if (record.sessionId) {
      await this.sessions.recordEvent(record.sessionId, "baselineUpdated", "Baseline window ended.", {
        metadata: { roomId: record.roomId, complete: next.baselineMarkedComplete },
      });
    }
    return next;
  }

  /**
   * Global property lock (iOS GLOBAL_PHONES / GLOBAL_HVAC_LOGGED /
   * GLOBAL_STABLE_PLACEMENT). Recorded once per property, on any room baseline.
   */
  async recordGlobalLock(
    baselineId: string,
    flags: { phonesLogged: boolean; hvacLogged: boolean; stablePlacement: boolean },
  ): Promise<BaselineRecord> {
    const record = await this.db.baselineRecords.get(baselineId);
    if (!record) throw new ValidationError(`Baseline not found: ${baselineId}`, "baselineId");
    const next: BaselineRecord = {
      ...record,
      globalPhonesLogged: flags.phonesLogged || record.globalPhonesLogged,
      globalHvacLogged: flags.hvacLogged || record.globalHvacLogged,
      globalStablePlacement: flags.stablePlacement || record.globalStablePlacement,
      updatedAt: Date.now(),
    };
    await this.db.baselineRecords.put(next);
    // Propagate the lock to the other rooms of the same case (property-wide).
    if (flags.phonesLogged || flags.hvacLogged || flags.stablePlacement) {
      const others = (await this.db.baselineRecords.where("caseId").equals(record.caseId).toArray()).filter(
        (b) => b.id !== baselineId,
      );
      for (const other of others) {
        await this.db.baselineRecords.put({
          ...other,
          globalPhonesLogged: other.globalPhonesLogged || flags.phonesLogged,
          globalHvacLogged: other.globalHvacLogged || flags.hvacLogged,
          globalStablePlacement: other.globalStablePlacement || flags.stablePlacement,
          updatedAt: Date.now(),
        });
      }
    }
    await this.audit.record("baselineRecorded", "Baseline global lock recorded for the property.", {
      caseId: record.caseId,
      affectedRecordId: baselineId,
      metadata: { phones: flags.phonesLogged, hvac: flags.hvacLogged, stablePlacement: flags.stablePlacement },
    });
    if (record.sessionId) {
      await this.sessions.recordEvent(record.sessionId, "baselineUpdated", "Global baseline lock recorded.", { metadata: { roomId: record.roomId } });
    }
    return next;
  }

  /** Drift verification (iOS DRIFT_CHECKED / DRIFT_DETECTED). */
  async recordDriftCheck(
    baselineId: string,
    input: { checked: boolean; detected: boolean; notes?: string; sessionId?: string | null },
  ): Promise<BaselineRecord> {
    const record = await this.db.baselineRecords.get(baselineId);
    if (!record) throw new ValidationError(`Baseline not found: ${baselineId}`, "baselineId");
    if (input.detected && !input.notes?.trim()) {
      throw new ValidationError("Recording unstable drift requires notes explaining what was observed.", "notes");
    }
    const next: BaselineRecord = {
      ...record,
      driftChecked: input.checked,
      driftDetected: input.checked ? input.detected : false,
      notes: input.notes?.trim() ? [record.notes, input.notes.trim()].filter(Boolean).join(" • ") : record.notes,
      updatedAt: Date.now(),
    };
    await this.db.baselineRecords.put(next);
    await this.audit.record("driftChecked", `Drift verification recorded (${input.detected ? "unstable" : "stable"}).`, {
      caseId: record.caseId,
      affectedRecordId: baselineId,
      metadata: { roomId: record.roomId, driftDetected: input.detected },
    });
    const sid = input.sessionId ?? record.sessionId;
    if (sid) {
      await this.sessions.recordEvent(sid, "driftChecked", `Drift check recorded (${input.detected ? "unstable" : "stable"}).`, {
        metadata: { roomId: record.roomId, driftDetected: input.detected },
      });
    }
    return next;
  }

  async listForCase(caseId: string): Promise<BaselineRecord[]> {
    const rows = await this.db.baselineRecords.where("caseId").equals(caseId).toArray();
    return rows.sort((a, b) => a.createdAt - b.createdAt);
  }

  async get(baselineId: string): Promise<BaselineRecord | undefined> {
    return this.db.baselineRecords.get(baselineId);
  }

  /** Baseline records for the rooms flagged for walkthrough (iOS flagged set). */
  private async flaggedRooms(caseId: string) {
    const structure = await this.property.getStructureForCase(caseId);
    if (!structure) return [];
    const hierarchy = await this.property.loadHierarchy(structure.id);
    return [
      ...hierarchy.floors.flatMap((f) => f.rooms),
      ...hierarchy.zones.flatMap((z) => z.rooms),
      ...hierarchy.unassignedRooms,
    ];
  }

  async progress(caseId: string): Promise<BaselineProgress> {
    const rooms = await this.flaggedRooms(caseId);
    const records = await this.listForCase(caseId);
    const byRoom = new Map(records.map((r) => [r.roomId, r]));
    const completeRooms = rooms.filter((room) => {
      const rec = byRoom.get(room.id);
      return rec ? isBaselineComplete(rec) : false;
    }).length;
    const driftCheckedRooms = rooms.filter((room) => byRoom.get(room.id)?.driftChecked === true).length;
    const globalLockRecorded = records.some(
      (r) => r.globalPhonesLogged && r.globalHvacLogged && r.globalStablePlacement,
    );
    const unresolvedDrift = records.some((r) => r.driftDetected);
    return { flaggedRooms: rooms.length, completeRooms, driftCheckedRooms, globalLockRecorded, unresolvedDrift };
  }

  /**
   * Evaluate baseline readiness from REAL records (WP-6 §16). Mirrors the iOS
   * rule set. Blockers are non-overridable where the iOS source treats the
   * condition as mandatory (missing global lock / unstable drift), and
   * overridable where an investigator exception is legitimate (a room whose
   * baseline could not be captured for a documented reason).
   */
  async evaluateCaseBaseline(caseId: string): Promise<BaselineBlocker[]> {
    const rooms = await this.flaggedRooms(caseId);
    const blockers: BaselineBlocker[] = [];
    if (rooms.length === 0) {
      blockers.push({
        roomId: null,
        roomName: "Property structure",
        reason: "No rooms/areas are defined, so no baseline can be collected.",
        requiredAction: "Define rooms in the Property Structure module.",
        nonOverridable: true,
      });
      return blockers;
    }
    const records = await this.listForCase(caseId);
    const byRoom = new Map(records.map((r) => [r.roomId, r]));

    for (const room of rooms) {
      const rec = byRoom.get(room.id);
      if (!rec) {
        blockers.push({
          roomId: room.id,
          roomName: room.name,
          reason: `No baseline recorded for "${room.name}".`,
          requiredAction: "Record a baseline window and summary for this room.",
          nonOverridable: false,
        });
        continue;
      }
      if (!isBaselineComplete(rec)) {
        const missing: string[] = [];
        if (rec.baselineStart === null) missing.push("start");
        if (rec.baselineEnd === null) missing.push("end");
        if (!rec.baselineSummary.trim()) missing.push("summary");
        if (!rec.baselineMarkedComplete) missing.push("completion confirmation");
        blockers.push({
          roomId: room.id,
          roomName: room.name,
          reason: `Baseline for "${room.name}" is incomplete (missing: ${missing.join(", ")}).`,
          requiredAction: "Complete the baseline window, record a summary, and confirm completion.",
          nonOverridable: false,
        });
        continue;
      }
      if (!rec.driftChecked) {
        blockers.push({
          roomId: room.id,
          roomName: room.name,
          reason: `Drift verification has not been recorded for "${room.name}".`,
          requiredAction: "Record a drift check (stable or unstable) for this room.",
          nonOverridable: false,
        });
      } else if (rec.driftDetected) {
        blockers.push({
          roomId: room.id,
          roomName: room.name,
          reason: `Unresolved unstable drift is recorded for "${room.name}".`,
          requiredAction: "Re-check conditions and record a resolved drift verification, or document why it cannot be resolved.",
          nonOverridable: true,
        });
      }
    }

    if (!records.some((r) => r.globalPhonesLogged && r.globalHvacLogged && r.globalStablePlacement)) {
      blockers.push({
        roomId: null,
        roomName: "Global baseline lock",
        reason: "The global baseline lock has not been recorded (phones off/away, HVAC state logged, stable equipment placement).",
        requiredAction: "Record the global baseline lock on any room baseline.",
        // The iOS source treats the global lock as mandatory for baseline completion.
        nonOverridable: true,
      });
    }
    return blockers;
  }

  /**
   * Checklist reconciliation for `baselineComplete` (real records only).
   */
  async reconcileChecklist(caseId: string): Promise<void> {
    const items = await this.db.checklistItems.where("caseId").equals(caseId).toArray();
    const item = items.find((i) => i.definitionId === "baselineComplete");
    if (!item) return;
    const blockers = await this.evaluateCaseBaseline(caseId);
    const satisfied = blockers.length === 0;
    if (satisfied && item.status !== "complete") {
      await this.db.checklistItems.put({
        ...item,
        status: "complete",
        completedAt: Date.now(),
        completedBy: "baseline-service",
        updatedAt: Date.now(),
      });
      await this.audit.record("checklistChanged", "Baseline checklist satisfied by recorded baseline data.", {
        caseId,
        affectedRecordId: item.id,
      });
    } else if (!satisfied && (item.status === "complete" || item.status === "exception")) {
      await this.db.checklistItems.put({
        ...item,
        status: "pending",
        completedAt: null,
        completedBy: null,
        notes: "Reconciled under TPI-V2-WEB-008: the previous completion was not backed by baseline records.",
        updatedAt: Date.now(),
      });
      await this.audit.record("checklistChanged", "Baseline checklist item reset — no supporting baseline records existed.", {
        caseId,
        affectedRecordId: item.id,
      });
    }
  }
}

/** iOS `BaselineRoomRecord.isBaselineComplete`. */
export function isBaselineComplete(rec: BaselineRecord): boolean {
  return rec.baselineStart !== null && rec.baselineEnd !== null && rec.baselineSummary.trim().length > 0 && rec.baselineMarkedComplete;
}
