/**
 * Documents Center (TPI-V2-WEB-006 §5). Dark TPI theme, offline-first.
 * All state comes from DocumentService — no UI-computed truth.
 */
import "./casehub.css";
import { getDb } from "../../core/db";
import { CaseRepository } from "../../core/repositories/caseRepository";
import { DocumentService } from "../../core/documents/documentService";
import { templateFor, DOCUMENT_TEMPLATES } from "../../core/documents/templates";
import { generateDocumentPdf, generateCasePacket } from "../../core/documents/pdfPacket";
import { hashBlob } from "../../core/files/opfs.hash";
import type { DocumentInstanceRecord, SignatureRole } from "../../core/types";
import { esc, viewShell, wireBackButton } from "../dashboard/shell";
import { mountView, onDelegate, invalidateView } from "../../shared/uidom";
import { renderCaseHub } from "./CaseHub";

const db = () => getDb();

const STATUS_LABEL: Record<string, string> = {
  notStarted: "Not Started",
  draft: "Draft",
  awaitingSignature: "Awaiting Signature",
  signed: "Signed",
  finalized: "Finalized",
  superseded: "Superseded",
  voided: "Voided",
};

export async function renderDocumentsCenter(container: HTMLElement, caseId: string): Promise<void> {
  const record = await new CaseRepository(db()).getCase(caseId);
  if (!record) {
    container.innerHTML = viewShell("Documents Center", `<div class="cc-empty">Case not found.</div>`);
    wireBackButton(container);
    return;
  }
  const service = new DocumentService(db());
  await service.ensureDocumentsForCase(caseId);
  const docs = await service.listForCase(caseId);
  const finalized = docs.filter((d) => d.status === "finalized").length;
  const required = docs.filter((d) => d.isRequired);

  const cards = docs
    .map(
      (d) => `
      <div class="case-row hub-card" data-doc="${d.id}">
        <div>
          <div class="case-title">${esc(templateFor(d.templateId).title)}${d.isRequired ? ' <span class="status-badge">required</span>' : ' <span class="status-badge pending">optional</span>'}</div>
          <div class="case-meta">Status: <strong>${STATUS_LABEL[d.status]}</strong> • template v${esc(d.templateVersion)}${d.finalizedAt ? ` • finalized ${new Date(d.finalizedAt).toLocaleString()}` : ""}${!d.applicability.applicable && d.applicability.determinedBy ? " • determined inapplicable (documented)" : ""}</div>
        </div>
        <span class="status-badge">${esc(d.status)}</span>
      </div>`,
    )
    .join("");

  invalidateView(container); // different view — reset idempotence cache
  mountView(container, viewShell(
    `Documents Center — ${record.caseNumber}`,
    `
    <div class="case-form">
      <p class="cc-count">Required documents finalized: <strong>${finalized} of ${required.length}</strong>.
      Signatures are bound to the exact document content; changing content invalidates prior signatures.
      Locally captured signatures are not independently verified and PDFs are not digitally certified.</p>
      <div class="form-actions">
        <button class="button-primary" id="docs-export-packet" type="button">Export Case Packet (PDF)</button>
        <button class="back-button" id="docs-back" type="button">← Back to Case Hub</button>
      </div>
      <h3 class="cc-section-title">Documents</h3>
      <div id="docs-list">${cards}</div>
      <h3 class="cc-section-title">Add optional document</h3>
      <div class="form-actions">
        <select id="doc-add-template" aria-label="Optional document template">
          ${DOCUMENT_TEMPLATES.filter((t) => !t.isRequired)
            .map((t) => `<option value="${t.id}">${esc(t.title)}</option>`)
            .join("")}
        </select>
        <button class="button-secondary" id="doc-add" type="button">Add Document</button>
      </div>
    </div>
    <div id="doc-editor"></div>
    `,
  ));

  // TPI-V2-WEB-007 §4: delegated handlers — state via data-* attributes.
  onDelegate(container, "click", "#docs-back", () => {
    void renderCaseHub(container, caseId);
  });
  onDelegate(container, "click", "#doc-add", async () => {
    const select = container.querySelector<HTMLSelectElement>("#doc-add-template");
    if (select) {
      await service.createOptionalDocument(caseId, select.value as DocumentInstanceRecord["templateId"]);
      await renderDocumentsCenter(container, caseId);
    }
  });
  onDelegate(container, "click", "#docs-export-packet", async () => {
    const items: Parameters<typeof generateCasePacket>[1] = [];
    for (const d of docs) {
      const version = d.finalizedVersionId ? ((await db().documentVersions.get(d.finalizedVersionId)) ?? null) : null;
      items.push({ instance: d, version, signatures: await service.signaturesFor(d.id) });
    }
    try {
      const bytes = await generateCasePacket(record, items);
      await downloadPdf(bytes, `TPI-packet-${record.caseNumber}.pdf`);
      await new (await import("../../core/audit")).AuditService(db()).record(
        "packetExported",
        `Case document packet exported (${items.length} documents, ${bytes.length} bytes).`,
        { caseId, metadata: { documents: items.length } },
      );
      void hashBlob(bytes.buffer as ArrayBuffer);
    } catch (err) {
      alert((err as Error).message);
    }
  });
  onDelegate(container, "click", "[data-doc]", (el) => {
    const docId = el.dataset.doc ?? "";
    if (docId) void openDocumentEditor(container, caseId, docId);
  });

  wireBackButton(container);
}

async function openDocumentEditor(container: HTMLElement, caseId: string, documentId: string): Promise<void> {
  const service = new DocumentService(db());
  const doc = await service.get(documentId);
  const record = await new CaseRepository(db()).getCase(caseId);
  if (!doc || !record) return;
  const template = templateFor(doc.templateId);
  const signatures = await service.signaturesFor(documentId);
  const versions = await service.versionsFor(documentId);
  const editable = doc.status === "notStarted" || doc.status === "draft" || doc.status === "awaitingSignature" || doc.status === "signed";

  const fieldHtml = template.fields
    .map(
      (f) => `
      <div class="detail-field doc-field" data-field-row="${f.id}">
        <label for="field-${f.id}">${esc(f.label)}${f.required ? " *" : ""}</label>
        ${f.type === "textarea"
          ? `<textarea id="field-${f.id}" data-field="${f.id}" rows="3">${esc(doc.fieldValues[f.id] ?? "")}</textarea>`
          : f.type === "select"
            ? `<select id="field-${f.id}" data-field="${f.id}">
                <option value="">— select —</option>
                ${(f.options ?? []).map((o) => `<option ${doc.fieldValues[f.id] === o ? "selected" : ""}>${esc(o)}</option>`).join("")}
              </select>`
            : `<input id="field-${f.id}" data-field="${f.id}" type="text" value="${esc(doc.fieldValues[f.id] ?? "")}">`}
        ${f.help ? `<div class="case-meta">${esc(f.help)}</div>` : ""}
      </div>`,
    )
    .join("");

  const sigHtml = (["client", "investigator"] as SignatureRole[])
    .map(() => "")
    .join("");
  const sigList = signatures
    .map(
      (s) => `
      <div class="case-row">
        <div>
          <div class="case-title">${s.signerRole === "client" ? "Client" : "Investigator"}: ${esc(s.signerName)} ${s.active ? "" : " (invalidated)"}</div>
          <div class="case-meta">${esc(s.method)} • signed ${new Date(s.signedAt).toLocaleString()} • bound hash ${esc(s.contentHash.slice(0, 16))}…${s.intentAcknowledged ? " • intent acknowledged" : ""}</div>
        </div>
        ${s.active && editable ? `<button class="back-button" data-clear-sig="${s.signerRole}" type="button">Clear</button>` : ""}
      </div>`,
    )
    .join("");

  const editor = container.querySelector<HTMLDivElement>("#doc-editor");
  if (!editor) return;
  editor.dataset.caseId = caseId;
  editor.dataset.docId = documentId;
  editor.dataset.status = doc.status;
  invalidateView(editor);
  mountView(editor, viewShell(
    template.title,
    `
    <div class="case-form">
      <p class="cc-count" id="doc-status-line">Status: <strong>${STATUS_LABEL[doc.status]}</strong> • template v${esc(doc.templateVersion)} • document id ${esc(doc.id.slice(0, 8))}…</p>
      ${doc.status === "finalized" ? `<p class="cc-count">This document is finalized and immutable. Create an amendment to correct it.</p>` : ""}
      ${doc.applicability.determinedBy && !doc.applicability.applicable ? `<p class="cc-count">Determined inapplicable: ${esc(doc.applicability.justification)}</p>` : ""}
      ${editable && template.fields.length > 0 ? `
      <div class="detail-grid">${fieldHtml}</div>
      <div class="form-actions">
        <button class="button-primary" id="doc-save" type="button">Save Draft</button>
        <span id="doc-save-status" role="status"></span>
      </div>` : template.fields.length === 0 && editable ? `<p class="cc-count">This document has no fillable fields — save it to prepare for signatures.</p>
      <div class="form-actions"><button class="button-primary" id="doc-save" type="button">Save Draft</button><span id="doc-save-status" role="status"></span></div>` : ""}
      <h3 class="cc-section-title">Signatures</h3>
      <div id="doc-signature-list">${sigList || '<div class="cc-empty">No signatures captured.</div>'}</div>
      ${editable ? signatureCaptureHtml() : ""}
      <div class="form-actions">
        <button class="button-primary" id="doc-finalize" type="button" ${doc.status === "signed" ? "" : "hidden"}>Review & Finalize</button>
        <button class="button-secondary" id="doc-amend" type="button" ${doc.status === "finalized" ? "" : "hidden"}>Create Amendment…</button>
        <button class="back-button" id="doc-inapplicable" type="button" ${doc.status === "finalized" || doc.status === "voided" ? "hidden" : ""}>Determine Inapplicable…</button>
        <button class="back-button" id="doc-void" type="button" ${doc.status === "finalized" || doc.status === "voided" ? "hidden" : ""}>Void Document…</button>
        <button class="button-secondary" id="doc-export" type="button">Export PDF</button>
        <button class="back-button" id="doc-back" type="button">← Documents Center</button>
      </div>
      <h3 class="cc-section-title">Version history</h3>
      ${versions.length === 0 ? '<div class="cc-empty">No finalized versions yet.</div>' : versions.map((v) => `<div class="case-row"><div><div class="case-title">v${v.versionNumber} (${v.label})</div><div class="case-meta">${new Date(v.createdAt).toLocaleString()} • hash ${esc(v.contentHash.slice(0, 16))}… • ${v.signatureIds.length} signature(s)</div></div></div>`).join("")}
    </div>
    `,
  ));

  const readFields = (scope: HTMLElement): Record<string, string> => {
    const values: Record<string, string> = { ...doc.fieldValues };
    scope.querySelectorAll<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>("[data-field]").forEach((el) => {
      values[el.dataset.field ?? ""] = el.value;
    });
    return values;
  };

  // TPI-V2-WEB-007 §4: delegated editor handlers — documentId/caseId come from
  // the editor's data-* attributes so handlers stay valid across re-renders.
  const scopeOf = (el: HTMLElement): HTMLElement => el.closest<HTMLElement>("#doc-editor") ?? editor;
  const docIdOf = (scope: HTMLElement): string => scope.dataset.docId ?? "";
  const caseIdOf = (scope: HTMLElement): string => scope.dataset.caseId ?? "";

  onDelegate(container, "click", "#doc-editor #doc-back", () => {
    void renderDocumentsCenter(container, caseId);
  });
  onDelegate(container, "click", "#doc-editor #doc-save", async (el) => {
    const scope = scopeOf(el);
    const did = docIdOf(scope);
    try {
      const saved = await service.saveDraft(did, readFields(scope));
      const statusEl = scope.querySelector<HTMLSpanElement>("#doc-save-status");
      if (statusEl) statusEl.textContent = "Saved ✓";
      // In-place status update (KI-WEB-006-1): no re-render during active
      // editing — repeated/racing clicks cannot detach the button mid-click.
      applyStatusInPlace(scope, saved.status);
      // A content change may have invalidated signatures — refresh the list.
      const sigList = scope.querySelector<HTMLDivElement>("#doc-signature-list");
      if (sigList) {
        const sigs = await service.signaturesFor(did);
        sigList.innerHTML = sigListHtml(sigs, saved.status !== "finalized");
      }
    } catch (err) {
      alert((err as Error).message);
    }
  });
  onDelegate(container, "click", "#doc-editor #doc-finalize", async (el) => {
    const scope = scopeOf(el);
    const did = docIdOf(scope);
    try {
      await service.finalize(did);
      applyStatusInPlace(scope, "finalized");
    } catch (err) {
      alert((err as Error).message);
    }
  });
  onDelegate(container, "click", "#doc-editor #doc-amend", async (el) => {
    const scope = scopeOf(el);
    const reason = window.prompt("Document the reason for this amendment:", "");
    if (!reason?.trim()) return;
    const amendment = await service.createAmendment(docIdOf(scope), reason);
    await openDocumentEditor(container, caseIdOf(scope), amendment.id);
  });
  onDelegate(container, "click", "#doc-editor #doc-void", async (el) => {
    const scope = scopeOf(el);
    const reason = window.prompt("Document why this document is being voided:", "");
    if (!reason?.trim()) return;
    await service.voidDocument(docIdOf(scope), reason);
    await renderDocumentsCenter(container, caseIdOf(scope));
  });
  onDelegate(container, "click", "#doc-editor #doc-inapplicable", async (el) => {
    const scope = scopeOf(el);
    const reason = window.prompt("Document why this document does not apply to this case:", "");
    if (!reason?.trim()) return;
    await service.determineApplicability(docIdOf(scope), false, reason);
    await renderDocumentsCenter(container, caseIdOf(scope));
  });
  onDelegate(container, "click", "#doc-editor #doc-export", async (el) => {
    const scope = scopeOf(el);
    const did = docIdOf(scope);
    try {
      const fresh = await service.get(did);
      if (!fresh) return;
      const freshCase = await new CaseRepository(db()).getCase(fresh.caseId);
      if (!freshCase) return;
      const version = fresh.finalizedVersionId ? ((await db().documentVersions.get(fresh.finalizedVersionId)) ?? null) : null;
      const bytes = await generateDocumentPdf({
        caseRecord: freshCase,
        instance: fresh,
        version,
        signatures: await service.signaturesFor(did),
      });
      await downloadPdf(bytes, `${template.fileNameStem}-${record.caseNumber}.pdf`);
    } catch (err) {
      alert((err as Error).message);
    }
  });
  onDelegate(container, "click", "#doc-editor [data-clear-sig]", async (el) => {
    const scope = scopeOf(el);
    const did = docIdOf(scope);
    await service.clearSignature(did, el.dataset.clearSig as SignatureRole);
    const list = scope.querySelector<HTMLDivElement>("#doc-signature-list");
    if (list) {
      const instance = await service.get(did);
      const sigs = await service.signaturesFor(did);
      list.innerHTML = sigListHtml(sigs, instance ? instance.status !== "finalized" : true);
    }
  });
  wireSignatureCapture(container, editor, async (input) => {
    const currentEditor = container.querySelector<HTMLElement>("#doc-editor") ?? editor;
    const did = currentEditor.dataset.docId ?? docIdOf(editor);
    const scope = currentEditor;
    try {
      await service.captureSignature(did, input);
      const instance = await service.get(did);
      if (instance) applyStatusInPlace(scope, instance.status);
      // Refresh the signature list region in place.
      const list = scope.querySelector<HTMLDivElement>("#doc-signature-list");
      if (list) {
        const sigs = await service.signaturesFor(did);
        list.innerHTML = sigListHtml(sigs, instance ? instance.status !== "finalized" : true);
      }
    } catch (err) {
      alert((err as Error).message);
    }
  });
  void sigHtml;
}

/** Render the signature list region (used for in-place updates). */
function sigListHtml(sigs: Awaited<ReturnType<DocumentService["signaturesFor"]>>, editable: boolean): string {
  if (sigs.length === 0) return '<div class="cc-empty">No signatures captured.</div>';
  return sigs
    .map(
      (s) => `
      <div class="case-row">
        <div>
          <div class="case-title">${s.signerRole === "client" ? "Client" : "Investigator"}: ${esc(s.signerName)} ${s.active ? "" : " (invalidated)"}</div>
          <div class="case-meta">${esc(s.method)} • signed ${new Date(s.signedAt).toLocaleString()} • bound hash ${esc(s.contentHash.slice(0, 16))}…${s.intentAcknowledged ? " • intent acknowledged" : ""}</div>
        </div>
        ${s.active && editable ? `<button class="back-button" data-clear-sig="${s.signerRole}" type="button">Clear</button>` : ""}
      </div>`,
    )
    .join("");
}

const STATUS_LABELS: Record<string, string> = {
  notStarted: "Not Started",
  draft: "Draft",
  awaitingSignature: "Awaiting Signature",
  signed: "Signed",
  finalized: "Finalized",
  superseded: "Superseded",
  voided: "Voided",
};

/** In-place status update: no innerHTML replacement during active editing. */
function applyStatusInPlace(scope: HTMLElement, status: string): void {
  scope.dataset.status = status;
  const line = scope.querySelector<HTMLElement>("#doc-status-line strong");
  if (line) line.textContent = STATUS_LABELS[status] ?? status;
  const finalize = scope.querySelector<HTMLButtonElement>("#doc-finalize");
  if (finalize) finalize.hidden = status !== "signed";
  const amend = scope.querySelector<HTMLButtonElement>("#doc-amend");
  if (amend) amend.hidden = status !== "finalized";
  for (const id of ["#doc-inapplicable", "#doc-void"]) {
    const btn = scope.querySelector<HTMLButtonElement>(id);
    if (btn) btn.hidden = status === "finalized" || status === "voided";
  }
}

function signatureCaptureHtml(): string {
  return `
  <div class="case-form signature-capture" id="signature-capture">
    <div class="detail-grid">
      <div class="detail-field"><label for="sig-role">Signing as</label>
        <select id="sig-role"><option value="client">Client</option><option value="investigator">Investigator (lead)</option></select></div>
      <div class="detail-field"><label for="sig-name">Signer full name</label>
        <input id="sig-name" type="text" autocomplete="off"></div>
      <div class="detail-field"><label for="sig-method">Method</label>
        <select id="sig-method"><option value="drawn">Drawn signature</option><option value="typed">Typed signature</option></select></div>
    </div>
    <div class="detail-field" id="sig-draw-wrap"><label>Draw your signature below</label>
      <canvas id="sig-canvas" width="360" height="120" style="border:1px solid #2A3441;background:#0B0E12;touch-action:none;" aria-label="Signature drawing area"></canvas>
      <div class="form-actions">
        <button class="back-button" id="sig-clear" type="button">Clear & Retry</button>
      </div>
      <div class="case-meta">Drawing is one option; a typed signature with acknowledgment is equally valid here.</div>
    </div>
    <div class="detail-field" id="sig-typed-wrap" hidden><label for="sig-typed">Type your full legal name</label>
      <input id="sig-typed" type="text" autocomplete="off">
      <div class="case-meta">Typing your name records a typed signature; it is not legally superior or inferior to a drawn one.</div>
    </div>
    <div class="detail-field">
      <label><input type="checkbox" id="sig-intent"> I confirm this is my signature and I intend to sign this document as shown on screen.</label>
    </div>
    <div class="form-actions"><button class="button-primary" id="sig-sign" type="button">Review & Sign…</button></div>
  </div>`;
}

function wireSignatureCapture(
  container: HTMLElement,
  editor: HTMLElement,
  onSign: (input: Parameters<DocumentService["captureSignature"]>[1]) => void,
): void {
  // TPI-V2-WEB-007 §4: everything is delegated and re-queried at event time —
  // the editor DOM is replaced when the document status changes, so closure-
  // captured canvas/select references would go stale (KI-WEB-006-1 class).
  const scopeOf = (el: HTMLElement): HTMLElement => el.closest<HTMLElement>("#doc-editor") ?? editor;
  const current = (scope: HTMLElement) => scope.querySelector<HTMLCanvasElement>("#sig-canvas");
  const ctxOf = (canvas: HTMLCanvasElement) => {
    const ctx = canvas.getContext("2d");
    if (ctx) {
      ctx.lineWidth = 2;
      ctx.lineCap = "round";
      ctx.strokeStyle = "#00C2FF";
    }
    return ctx;
  };
  const pos = (canvas: HTMLCanvasElement, e: PointerEvent) => {
    const rect = canvas.getBoundingClientRect();
    return { x: ((e.clientX - rect.left) / rect.width) * canvas.width, y: ((e.clientY - rect.top) / rect.height) * canvas.height };
  };
  let drawing = false;

  onDelegate(container, "pointerdown", "#doc-editor #sig-canvas", (canvasEl, e) => {
    const canvas = current(scopeOf(canvasEl));
    if (!canvas) return;
    drawing = true;
    const ctx = ctxOf(canvas);
    const p = pos(canvas, e);
    ctx?.beginPath();
    ctx?.moveTo(p.x, p.y);
  });
  onDelegate(container, "pointermove", "#doc-editor #sig-canvas", (canvasEl, e) => {
    if (!drawing) return;
    const canvas = current(scopeOf(canvasEl));
    if (!canvas) return;
    const ctx = ctxOf(canvas);
    const p = pos(canvas, e);
    ctx?.lineTo(p.x, p.y);
    ctx?.stroke();
    canvas.dataset.dirty = "1";
  });
  onDelegate(container, "pointerup", "#doc-editor #sig-canvas", () => {
    drawing = false;
  });
  onDelegate(container, "click", "#doc-editor #sig-clear", (el) => {
    const canvas = current(scopeOf(el));
    if (!canvas) return;
    ctxOf(canvas)?.clearRect(0, 0, canvas.width, canvas.height);
    canvas.dataset.dirty = "";
  });
  onDelegate(container, "change", "#doc-editor #sig-method", (el) => {
    const scope = scopeOf(el);
    const isDrawn = (el as HTMLSelectElement).value === "drawn";
    const drawWrap = scope.querySelector<HTMLElement>("#sig-draw-wrap");
    const typedWrap = scope.querySelector<HTMLElement>("#sig-typed-wrap");
    if (drawWrap) drawWrap.hidden = !isDrawn;
    if (typedWrap) typedWrap.hidden = isDrawn;
  });
  onDelegate(container, "click", "#doc-editor #sig-sign", (el) => {
    const scope = scopeOf(el);
    const name = scope.querySelector<HTMLInputElement>("#sig-name")?.value ?? "";
    const intent = scope.querySelector<HTMLInputElement>("#sig-intent")?.checked ?? false;
    if (!window.confirm(`Sign this document as ${name}? The signature will be bound to the exact content shown.`)) return;
    const method = scope.querySelector<HTMLSelectElement>("#sig-method")?.value ?? "drawn";
    const isDrawn = method === "drawn";
    const canvas = current(scope);
    if (isDrawn && (!canvas || canvas.dataset.dirty !== "1")) {
      alert("Draw a signature first, or switch the method to a typed signature.");
      return;
    }
    onSign({
      signerName: name,
      signerRole: (scope.querySelector<HTMLSelectElement>("#sig-role")?.value ?? "client") as SignatureRole,
      method: isDrawn ? "drawn" : "typed",
      imageDataUrl: isDrawn && canvas ? canvas.toDataURL("image/png") : null,
      intentAcknowledged: intent,
    });
  });
}

async function downloadPdf(bytes: Uint8Array, fileName: string): Promise<void> {
  const blob = new Blob([bytes as BlobPart], { type: "application/pdf" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = fileName;
  a.click();
  setTimeout(() => URL.revokeObjectURL(url), 10_000);
}
