/**
 * Guided intake question bank — verbatim port of iOS PPGuidedIntakeStep +
 * PPGuidedIntakeQuestionBank (TPI-V2-WEB-006; docs/INTAKE_PARITY_AUDIT.md).
 *
 * Question text is preserved from the original application. Question version
 * `ios-migrate-1` is stored with every response for historical accuracy.
 * No paranormal conclusions and no leading questions are introduced.
 */

export const INTAKE_QUESTION_VERSION = "ios-migrate-1";

export type IntakeSectionId =
  | "clientHousehold"
  | "claims"
  | "healthWellness"
  | "propertyStructure"
  | "environmentalFactors"
  | "landHistorical"
  | "researchArchive";

export const INTAKE_SECTIONS: ReadonlyArray<{ id: IntakeSectionId; label: string }> = [
  { id: "clientHousehold", label: "Client & Household" },
  { id: "claims", label: "Claims" },
  { id: "healthWellness", label: "Health & Wellness" },
  { id: "propertyStructure", label: "Property & Structure" },
  { id: "environmentalFactors", label: "Environmental Factors" },
  { id: "landHistorical", label: "Land & Historical Context" },
  { id: "researchArchive", label: "Research Archive" },
];

export type IntakeQuestionType = "shortText" | "longText" | "select" | "multi" | "yesNo" | "date" | "number";

/** `source` distinguishes client statements from investigator observations. */
export type IntakeQuestionSource = "client-statement" | "investigator-observation" | "interpretation";

export interface IntakeQuestion {
  id: string;
  section: IntakeSectionId;
  prompt: string;
  type: IntakeQuestionType;
  /** Required steps may be skipped during a session but must be answered
   *  (not skipped) before intake can finalize. */
  required: boolean;
  options?: string[];
  source: IntakeQuestionSource;
  /** Claim/member loop membership (suffix #N per repeat index). */
  loop?: "claims" | "household";
  /** Conditional applicability based on saved answers. */
  appliesTo?: (get: (questionId: string) => string | undefined) => boolean;
  help?: string;
}

const YES_NO = ["Yes", "No", "Unknown"];
const YES_NO_SKIP = ["Yes", "No"];

/** Readiness helper mirrors iOS StepResolver "Yes, <inline note>" parsing. */
export function isAffirmativeAnswer(value: string | undefined): boolean {
  if (!value) return false;
  const v = value.trim().toLowerCase();
  return v === "yes" || v === "yeah" || v === "yep" || v.startsWith("yes,");
}

