function hasPets(petsType: string | undefined): boolean {
  if (!petsType) return true; // unanswered — show by default until answered "None"
  const v = petsType.trim().toLowerCase();
  return v.length > 0 && v !== "none";
}

/** Base (non-looped) questions in canonical order. */
export function baseQuestions(): IntakeQuestion[] {
  return INTAKE_QUESTIONS.filter((q) => !q.loop);
}

/** Expanded question list including looped claims (claimCount ≥ 1). */
export function expandQuestions(claimCount: number): IntakeQuestion[] {
  const out: IntakeQuestion[] = [];
  for (const q of INTAKE_QUESTIONS) {
    if (q.loop === "claims") {
      for (let i = 0; i < Math.max(1, claimCount); i++) out.push(questionForIndex(q, i));
    } else if (q.loop === "household") {
      // WP-4 limitation: single household member (see docs/INTAKE_PARITY_AUDIT.md §6).
      out.push(questionForIndex(q, 0));
    } else {
      out.push(q);
    }
  }
  return out;
}

export function questionForIndex(q: IntakeQuestion, index: number): IntakeQuestion {
  if (index === 0) return q;
  return {
    ...q,
    id: `${q.id}#${index}`,
    required: q.required,
    // The "another?" decision belongs to the previous claim set.
    appliesTo: q.id === "additionalClaimDecision"
      ? undefined
      : q.appliesTo,
  };
}

export function questionById(id: string): IntakeQuestion | undefined {
  const [baseId] = id.split("#");
  return INTAKE_QUESTIONS.find((q) => q.id === baseId);
}

/** Validate a response value against a question's type/options. */
export function validateResponse(
  question: IntakeQuestion,
  value: string,
  status: "answered" | "skipped",
): string | null {
  if (status === "skipped") return null;
  const v = value.trim();
  if (v.length === 0) return "A response is required (or choose Skip for optional questions).";
  switch (question.type) {
    case "select":
      if (question.options && !question.options.includes(v)) {
        return `Choose one of: ${question.options.join(", ")}.`;
      }
      return null;
    case "multi": {
      let parsed: string[];
      try {
        parsed = JSON.parse(v) as string[];
      } catch {
        return "Invalid multi-select value.";
      }
      if (!Array.isArray(parsed) || parsed.length === 0) return "Select at least one option.";
      if (question.options && parsed.some((p) => !question.options!.includes(p))) {
        return `Options must be from: ${question.options.join(", ")}.`;
      }
      return null;
    }
    case "number": {
      const n = Number(v);
      if (!Number.isFinite(n)) return "Enter a numeric value.";
      if (question.id.startsWith("claimEmotionalImpact") && (!Number.isInteger(n) || n < 0 || n > 5)) {
        return "Emotional impact must be an integer from 0 to 5.";
      }
      return null;
    }
    case "date":
      if (Number.isNaN(Date.parse(v))) return "Enter a valid date.";
      return null;
    default:
      return null;
  }
}
